  95 | static void
  96 | nl_set_rcvbuf(int fd, uint val)
  97 | {
  98 |   if (setsockopt(fd, SOL_SOCKET, SO_RCVBUFFORCE, &val, sizeof(val)) < 0)
  99 |     log(L_WARN "KRT: Cannot set netlink rx buffer size to %u: %m", val);
