 260 | static struct tbf rl_netlink_err = TBF_DEFAULT_LOG_LIMITS;
 261 | 
 262 | static int
 263 | nl_error(struct nlmsghdr *h, int ignore_esrch)
 264 | {
 265 |   struct nlmsgerr *e;
 266 |   int ec;
 267 | 
 268 |   if (h->nlmsg_len < NLMSG_LENGTH(sizeof(struct nlmsgerr)))
 269 |     {
 270 |       log(L_WARN "Netlink: Truncated error message received");
 271 |       return ENOBUFS;
 272 |     }
 273 |   e = (struct nlmsgerr *) NLMSG_DATA(h);
 274 |   ec = netlink_error_to_os(e->error);
 275 |   if (ec && !(ignore_esrch && (ec == ESRCH)))
 276 |     log_rl(&rl_netlink_err, L_WARN "Netlink: %s", strerror(ec));
 277 |   return ec;
 278 | }
