 280 | static struct nlmsghdr *
 281 | nl_get_scan(void)
 282 | {
 283 |   struct nlmsghdr *h = nl_get_reply(&nl_scan);
 284 | 
 285 |   if (h->nlmsg_type == NLMSG_DONE)
 286 |     return NULL;
 287 |   if (h->nlmsg_type == NLMSG_ERROR)
 288 |     {
 289 |       nl_error(h, 0);
 290 |       return NULL;
 291 |     }
 292 |   return h;
 293 | }
