 499 | static inline ip_addr rta_get_via(struct rtattr *a)
 500 | {
 501 |   struct rtvia *v = RTA_DATA(a);
 502 |   switch(v->rtvia_family) {
 503 |     case AF_INET:  return ipa_from_ip4(ip4_ntoh(*(ip4_addr *) v->rtvia_addr));
 504 |     case AF_INET6: return ipa_from_ip6(ip6_ntoh(*(ip6_addr *) v->rtvia_addr));
 505 |   }
 506 |   return IPA_NONE;
 507 | }
