 531 | struct rtattr *
 532 | nl_add_attr(struct nlmsghdr *h, uint bufsize, uint code, const void *data, uint dlen)
 533 | {
 534 |   uint pos = NLMSG_ALIGN(h->nlmsg_len);
 535 |   uint len = RTA_LENGTH(dlen);
 536 | 
 537 |   if (pos + len > bufsize)
 538 |     bug("nl_add_attr: packet buffer overflow");
 539 | 
 540 |   struct rtattr *a = (struct rtattr *)((char *)h + pos);
 541 |   a->rta_type = code;
 542 |   a->rta_len = len;
 543 |   h->nlmsg_len = pos + len;
 544 | 
 545 |   if (dlen > 0)
 546 |     memcpy(RTA_DATA(a), data, dlen);
 547 | 
 548 |   return a;
 549 | }
