 997 | static void
 998 | nl_parse_addr4(struct ifaddrmsg *i, int scan, int new)
 999 | {
1000 |   struct rtattr *a[BIRD_IFA_MAX];
1001 |   struct iface *ifi;
1002 |   u32 ifa_flags;
1003 |   int scope;
1004 | 
1005 |   if (!nl_parse_attrs(IFA_RTA(i), ifa_attr_want4, a, sizeof(a)))
1006 |     return;
1007 | 
1008 |   if (!a[IFA_LOCAL])
1009 |     {
1010 |       log(L_ERR "KIF: Malformed message received (missing IFA_LOCAL)");
1011 |       return;
1012 |     }
1013 |   if (!a[IFA_ADDRESS])
1014 |     {
1015 |       log(L_ERR "KIF: Malformed message received (missing IFA_ADDRESS)");
1016 |       return;
1017 |     }
1018 | 
1019 |   ifi = if_find_by_index(i->ifa_index);
1020 |   if (!ifi)
1021 |     {
1022 |       log(L_ERR "KIF: Received address message for unknown interface %d", i->ifa_index);
1023 |       return;
1024 |     }
1025 | 
1026 |   if (a[IFA_FLAGS])
1027 |     ifa_flags = rta_get_u32(a[IFA_FLAGS]);
1028 |   else
1029 |     ifa_flags = i->ifa_flags;
1030 | 
1031 |   struct ifa ifa;
1032 |   bzero(&ifa, sizeof(ifa));
1033 |   ifa.iface = ifi;
1034 |   if (ifa_flags & IFA_F_SECONDARY)
1035 |     ifa.flags |= IA_SECONDARY;
1036 | 
1037 |   ifa.ip = rta_get_ipa(a[IFA_LOCAL]);
1038 | 
1039 |   if (i->ifa_prefixlen > IP4_MAX_PREFIX_LENGTH)
1040 |     {
1041 |       log(L_ERR "KIF: Invalid prefix length for interface %s: %d", ifi->name, i->ifa_prefixlen);
1042 |       new = 0;
1043 |     }
1044 |   if (i->ifa_prefixlen == IP4_MAX_PREFIX_LENGTH)
1045 |     {
1046 |       ifa.brd = rta_get_ipa(a[IFA_ADDRESS]);
1047 |       net_fill_ip4(&ifa.prefix, rta_get_ip4(a[IFA_ADDRESS]), i->ifa_prefixlen);
1048 | 
1049 |       /* It is either a host address or a peer address */
1050 |       if (ipa_equal(ifa.ip, ifa.brd))
1051 | 	ifa.flags |= IA_HOST;
1052 |       else
1053 | 	{
1054 | 	  ifa.flags |= IA_PEER;
1055 | 	  ifa.opposite = ifa.brd;
1056 | 	}
1057 |     }
1058 |   else
1059 |     {
1060 |       net_fill_ip4(&ifa.prefix, ipa_to_ip4(ifa.ip), i->ifa_prefixlen);
1061 |       net_normalize(&ifa.prefix);
1062 | 
1063 |       if (i->ifa_prefixlen == IP4_MAX_PREFIX_LENGTH - 1)
1064 | 	ifa.opposite = ipa_opposite_m1(ifa.ip);
1065 | 
1066 |       if (i->ifa_prefixlen == IP4_MAX_PREFIX_LENGTH - 2)
1067 | 	ifa.opposite = ipa_opposite_m2(ifa.ip);
1068 | 
1069 |       if (ifi->flags & IF_BROADCAST)
1070 |         {
1071 | 	  /* If kernel offers us a broadcast address, we trust it */
1072 | 	  if (a[IFA_BROADCAST])
1073 | 	    ifa.brd = ipa_from_ip4(rta_get_ip4(a[IFA_BROADCAST]));
1074 | 	  /* Otherwise we create one (except for /31) */
1075 | 	  else if (i->ifa_prefixlen < (IP4_MAX_PREFIX_LENGTH - 1))
1076 | 	    ifa.brd = ipa_from_ip4(ip4_or(ipa_to_ip4(ifa.ip),
1077 | 					  ip4_not(ip4_mkmask(i->ifa_prefixlen))));
1078 | 	}
1079 |     }
1080 | 
1081 |   scope = ipa_classify(ifa.ip);
1082 |   if (scope < 0)
1083 |     {
1084 |       log(L_ERR "KIF: Invalid interface address %I for %s", ifa.ip, ifi->name);
1085 |       return;
1086 |     }
1087 |   ifa.scope = scope & IADDR_SCOPE_MASK;
1088 | 
1089 |   DBG("KIF: IF%d(%s): %s IPA %I, flg %x, net %N, brd %I, opp %I\n",
1090 |       ifi->index, ifi->name,
1091 |       new ? "added" : "removed",
1092 |       ifa.ip, ifa.flags, &ifa.prefix, ifa.brd, ifa.opposite);
1093 | 
1094 |   if (new)
1095 |     ifa_update(&ifa);
1096 |   else
1097 |     ifa_delete(&ifa);
1098 | 
1099 |   if (!scan)
1100 |     if_end_partial_update(ifi);
1101 | }
