1128 |     ifa_flags = rta_get_u32(a[IFA_FLAGS]);
1129 |   else
1130 |     ifa_flags = i->ifa_flags;
1131 | 
1132 |   struct ifa ifa;
1133 |   bzero(&ifa, sizeof(ifa));
1134 |   ifa.iface = ifi;
1135 |   if (ifa_flags & IFA_F_SECONDARY)
1136 |     ifa.flags |= IA_SECONDARY;
1137 | 
1138 |   /* Ignore tentative addresses silently */
1139 |   if (ifa_flags & IFA_F_TENTATIVE)
1140 |     return;
1141 | 
1142 |   /* IFA_LOCAL can be unset for IPv6 interfaces */
1143 |   ifa.ip = rta_get_ipa(a[IFA_LOCAL] ? : a[IFA_ADDRESS]);
1144 | 
1145 |   if (i->ifa_prefixlen > IP6_MAX_PREFIX_LENGTH)
1146 |     {
1147 |       log(L_ERR "KIF: Invalid prefix length for interface %s: %d", ifi->name, i->ifa_prefixlen);
1148 |       new = 0;
1149 |     }
1150 |   if (i->ifa_prefixlen == IP6_MAX_PREFIX_LENGTH)
1151 |     {
1152 |       ifa.brd = rta_get_ipa(a[IFA_ADDRESS]);
1153 |       net_fill_ip6(&ifa.prefix, rta_get_ip6(a[IFA_ADDRESS]), i->ifa_prefixlen);
1154 | 
1155 |       /* It is either a host address or a peer address */
1156 |       if (ipa_equal(ifa.ip, ifa.brd))
1157 | 	ifa.flags |= IA_HOST;
1158 |       else
1159 | 	{
1160 | 	  ifa.flags |= IA_PEER;
1161 | 	  ifa.opposite = ifa.brd;
1162 | 	}
1163 |     }
1164 |   else
1165 |     {
1166 |       net_fill_ip6(&ifa.prefix, ipa_to_ip6(ifa.ip), i->ifa_prefixlen);
1167 |       net_normalize(&ifa.prefix);
1168 | 
1169 |       if (i->ifa_prefixlen == IP6_MAX_PREFIX_LENGTH - 1)
1170 | 	ifa.opposite = ipa_opposite_m1(ifa.ip);
1171 |     }
1172 | 
1173 |   scope = ipa_classify(ifa.ip);
1174 |   if (scope < 0)
1175 |     {
1176 |       log(L_ERR "KIF: Invalid interface address %I for %s", ifa.ip, ifi->name);
1177 |       return;
1178 |     }
1179 |   ifa.scope = scope & IADDR_SCOPE_MASK;
1180 | 
1181 |   DBG("KIF: IF%d(%s): %s IPA %I, flg %x, net %N, brd %I, opp %I\n",
1182 |       ifi->index, ifi->name,
1183 |       new ? "added" : "removed",
1184 |       ifa.ip, ifa.flags, &ifa.prefix, ifa.brd, ifa.opposite);
1185 | 
1186 |   if (new)
1187 |     ifa_update(&ifa);
1188 |   else
1189 |     ifa_delete(&ifa);
1190 | 
1191 |   if (!scan)
1192 |     if_end_partial_update(ifi);
1193 | }
