 447 | static int
 448 | nl_parse_attrs(struct rtattr *a, struct nl_want_attrs *want, struct rtattr **k, int ksize)
 449 | {
 450 |   int max = ksize / sizeof(struct rtattr *);
 451 |   bzero(k, ksize);
 452 | 
 453 |   for ( ; RTA_OK(a, nl_attr_len); a = RTA_NEXT(a, nl_attr_len))
 454 |     {
 455 |       if ((a->rta_type >= max) || !want[a->rta_type].defined)
 456 | 	continue;
 457 | 
 458 |       if (want[a->rta_type].checksize && (RTA_PAYLOAD(a) != want[a->rta_type].size))
 459 | 	{
 460 | 	  log(L_ERR "nl_parse_attrs: Malformed attribute received");
 461 | 	  return 0;
 462 | 	}
 463 | 
 464 |       k[a->rta_type] = a;
 465 |     }
 466 | 
 467 |   if (nl_attr_len)
 468 |     {
 469 |       log(L_ERR "nl_parse_attrs: remnant of size %d", nl_attr_len);
 470 |       return 0;
 471 |     }
 472 | 
 473 |   return 1;
 474 | }
