 663 | static inline void
 664 | nl_add_nexthop(struct nlmsghdr *h, uint bufsize, struct nexthop *nh, int af UNUSED)
 665 | {
 666 | #ifdef HAVE_MPLS_KERNEL
 667 |   if (nh->labels > 0)
 668 |     if (af == AF_MPLS)
 669 |       nl_add_attr_mpls(h, bufsize, RTA_NEWDST, nh->labels, nh->label);
 670 |     else
 671 |       nl_add_attr_mpls_encap(h, bufsize, nh->labels, nh->label);
 672 | 
 673 |   if (ipa_nonzero(nh->gw))
 674 |   {
 675 |     if (af == (ipa_is_ip4(nh->gw) ? AF_INET : AF_INET6))
 676 |       nl_add_attr_ipa(h, bufsize, RTA_GATEWAY, nh->gw);
 677 |     else
 678 |       nl_add_attr_via(h, bufsize, nh->gw);
 679 |   }
 680 | #else
 681 | 
 682 |   if (ipa_nonzero(nh->gw))
 683 |     nl_add_attr_ipa(h, bufsize, RTA_GATEWAY, nh->gw);
 684 | #endif
 685 | }
