 717 | static struct nexthop *
 718 | nl_parse_multipath(struct nl_parse_state *s, struct krt_proto *p, const net_addr *n, struct rtattr *ra, int af, int krt_src)
 719 | {
 720 |   struct rtattr *a[BIRD_RTA_MAX];
 721 |   struct rtnexthop *nh = RTA_DATA(ra);
 722 |   struct nexthop *rv, *first, **last;
 723 |   unsigned len = RTA_PAYLOAD(ra);
 724 | 
 725 |   first = NULL;
 726 |   last = &first;
 727 | 
 728 |   while (len)
 729 |     {
 730 |       /* Use RTNH_OK(nh,len) ?? */
 731 |       if ((len < sizeof(*nh)) || (len < nh->rtnh_len))
 732 | 	goto err;
 733 | 
 734 |       if ((nh->rtnh_flags & RTNH_F_DEAD) && (krt_src != KRT_SRC_BIRD))
 735 | 	goto next;
 736 | 
 737 |       *last = rv = lp_allocz(s->pool, NEXTHOP_MAX_SIZE);
 738 |       last = &(rv->next);
 739 | 
 740 |       rv->weight = nh->rtnh_hops;
 741 |       rv->iface = if_find_by_index(nh->rtnh_ifindex);
 742 |       if (!rv->iface)
 743 | 	{
 744 | 	  log(L_ERR "KRT: Received route %N with unknown ifindex %u", n, nh->rtnh_ifindex);
 745 | 	  return NULL;
 746 | 	}
 747 | 
 748 |       /* Nonexistent RTNH_PAYLOAD ?? */
 749 |       nl_attr_len = nh->rtnh_len - RTNH_LENGTH(0);
 750 |       switch (af)
 751 |         {
 752 | 	case AF_INET:
 753 | 	  if (!nl_parse_attrs(RTNH_DATA(nh), nexthop_attr_want4, a, sizeof(a)))
 754 | 	    goto err;
 755 | 	  break;
 756 | 
 757 | 	case AF_INET6:
 758 | 	  if (!nl_parse_attrs(RTNH_DATA(nh), nexthop_attr_want6, a, sizeof(a)))
 759 | 	    goto err;
 760 | 	  break;
 761 | 
 762 | #ifdef HAVE_MPLS_KERNEL
 763 | 	case AF_MPLS:
 764 | 	  if (!nl_parse_attrs(RTNH_DATA(nh), nexthop_attr_want_mpls, a, sizeof(a)))
 765 | 	    goto err;
 766 | 
 767 | 	  if (a[RTA_NEWDST])
 768 | 	    rv->labels = rta_get_mpls(a[RTA_NEWDST], rv->label);
 769 | 
 770 | 	  break;
 771 | #endif
 772 | 
 773 | 	default:
 774 | 	  goto err;
 775 | 	}
 776 | 
 777 |       if (a[RTA_GATEWAY])
 778 | 	rv->gw = rta_get_ipa(a[RTA_GATEWAY]);
 779 | 
 780 |       if (a[RTA_FLOW])
 781 | 	s->rta_flow = rta_get_u32(a[RTA_FLOW]);
 782 | 
 783 |       if (a[RTA_VIA])
 784 | 	rv->gw = rta_get_via(a[RTA_VIA]);
 785 | 
 786 |       if (nh->rtnh_flags & RTNH_F_ONLINK)
 787 | 	rv->flags |= RNF_ONLINK;
 788 | 
 789 |       if (ipa_nonzero(rv->gw))
 790 | 	{
 791 | #ifdef CONFIG_ASSUME_ONLINK
 792 | 	  if (krt_assume_onlink(rv->iface, ipa_is_ip6(rv->gw)))
 793 | 	    rv->flags |= RNF_ONLINK;
 794 | #endif
 795 | 
 796 | 	  neighbor *nbr;
 797 | 	  nbr = neigh_find(&p->p, rv->gw, rv->iface,
 798 | 			   (rv->flags & RNF_ONLINK) ? NEF_ONLINK : 0);
 799 | 	  if (!nbr || (nbr->scope == SCOPE_HOST))
 800 | 	    {
 801 | 	        log(L_ERR "KRT: Received route %N with strange next-hop %I", n, rv->gw);
 802 | 	        return NULL;
 803 | 	    }
 804 | 	}
 805 | 
 806 | #ifdef HAVE_MPLS_KERNEL
 807 |       if (a[RTA_ENCAP] && a[RTA_ENCAP_TYPE])
 808 |       {
 809 | 	if (rta_get_u16(a[RTA_ENCAP_TYPE]) != LWTUNNEL_ENCAP_MPLS)
 810 | 	{
 811 | 	  log(L_WARN "KRT: Received route %N with unknown encapsulation method %d",
 812 | 	      n, rta_get_u16(a[RTA_ENCAP_TYPE]));
 813 | 	  return NULL;
 814 | 	}
 815 | 
 816 | 	struct rtattr *enca[BIRD_RTA_MAX];
 817 | 	nl_attr_len = RTA_PAYLOAD(a[RTA_ENCAP]);
 818 | 	nl_parse_attrs(RTA_DATA(a[RTA_ENCAP]), encap_mpls_want, enca, sizeof(enca));
 819 | 	rv->labels = rta_get_mpls(enca[RTA_DST], rv->label);
 820 |       }
 821 | #endif
 822 | 
 823 |     next:
 824 |       len -= NLMSG_ALIGN(nh->rtnh_len);
 825 |       nh = RTNH_NEXT(nh);
 826 |     }
 827 | 
 828 |   /* Ensure nexthops are sorted to satisfy nest invariant */
 829 |   if (!nexthop_is_sorted(first))
 830 |     first = nexthop_sort(first);
 831 | 
 832 |   return first;
 833 | 
 834 | err:
 835 |   log(L_ERR "KRT: Received strange multipath route %N", n);
 836 |   return NULL;
 837 | }
