 841 | static void
 842 | nl_add_metrics(struct nlmsghdr *h, uint bufsize, u32 *metrics, const char *cc_algo, int max)
 843 | {
 844 |   struct rtattr *a = nl_open_attr(h, bufsize, RTA_METRICS);
 845 |   int t;
 846 | 
 847 |   for (t = 1; t < max; t++)
 848 |     if (metrics[0] & (1 << t))
 849 |       if (t == RTAX_CC_ALGO)
 850 |         nl_add_attr_str(h, bufsize, t, cc_algo);
 851 |       else
 852 |         nl_add_attr_u32(h, bufsize, t, metrics[t]);
 853 | 
 854 |   nl_close_attr(h, a);
 855 | }
 856 | 
 857 | static int
 858 | nl_parse_metrics(struct rtattr *hdr, u32 *metrics, const char **cc_algo, int max)
 859 | {
 860 |   struct rtattr *a = RTA_DATA(hdr);
 861 |   int len = RTA_PAYLOAD(hdr);
 862 | 
 863 |   metrics[0] = 0;
 864 |   for (; RTA_OK(a, len); a = RTA_NEXT(a, len))
 865 |   {
 866 |     if (a->rta_type == RTAX_UNSPEC)
 867 |       continue;
 868 | 
 869 |     if (a->rta_type >= max)
 870 |       continue;
 871 | 
 872 |     if (a->rta_type == RTAX_CC_ALGO)
 873 |     {
 874 |       *cc_algo = rta_get_str(a);
 875 |       int slen = RTA_PAYLOAD(a);
 876 | 
 877 |       if (!slen || ((*cc_algo)[slen - 1] != 0))
 878 | 	return -1;
 879 | 
 880 |       metrics[0] |= 1 << a->rta_type;
 881 |       metrics[a->rta_type] = 0;
 882 |     }
 883 |     else
 884 |     {
 885 |       if (RTA_PAYLOAD(a) != 4)
 886 | 	return -1;
 887 | 
 888 |       metrics[0] |= 1 << a->rta_type;
 889 |       metrics[a->rta_type] = rta_get_u32(a);
 890 |     }
 891 |   }
 892 | 
 893 |   if (len > 0)
 894 |     return -1;
 895 | 
 896 |   return 0;
 897 | }
