1541 | 
1542 | #define SKIP0(ARG, ...) do { DBG("KRT: Ignoring route - " ARG, ##__VA_ARGS__); return; } while(0)
1543 | #define SKIP(ARG, ...)  do { DBG("KRT: Ignoring route %N - " ARG, &dst, ##__VA_ARGS__); return; } while(0)
1544 | 
1545 | static void
1546 | nl_parse_route(struct nl_parse_state *s, struct nlmsghdr *h)
1547 | {
1548 |   struct krt_proto *p;
1549 |   struct rtmsg *i;
1550 |   struct rtattr *a[BIRD_RTA_MAX];
1551 |   int new = h->nlmsg_type == RTM_NEWROUTE;
1552 | 
1553 |   net_addr dst, src = {};
1554 |   u32 oif = ~0;
1555 |   u32 table_id;
1556 |   u32 priority = 0;
1557 |   u32 def_scope = RT_SCOPE_UNIVERSE;
1558 |   int krt_src;
1559 | 
1560 |   if (!(i = nl_checkin(h, sizeof(*i))))
1561 |     return;
1562 | 
1563 |   switch (i->rtm_family)
1564 |     {
1565 |     case AF_INET:
1566 |       if (!nl_parse_attrs(RTM_RTA(i), rtm_attr_want4, a, sizeof(a)))
1567 | 	return;
1568 | 
1569 |       if (a[RTA_DST])
1570 | 	net_fill_ip4(&dst, rta_get_ip4(a[RTA_DST]), i->rtm_dst_len);
1571 |       else
1572 | 	net_fill_ip4(&dst, IP4_NONE, 0);
1573 |       break;
1574 | 
1575 |     case AF_INET6:
1576 |       if (!nl_parse_attrs(RTM_RTA(i), rtm_attr_want6, a, sizeof(a)))
1577 | 	return;
1578 | 
1579 |       if (a[RTA_DST])
1580 | 	net_fill_ip6(&dst, rta_get_ip6(a[RTA_DST]), i->rtm_dst_len);
1581 |       else
1582 | 	net_fill_ip6(&dst, IP6_NONE, 0);
1583 | 
1584 |       if (a[RTA_SRC])
1585 | 	net_fill_ip6(&src, rta_get_ip6(a[RTA_SRC]), i->rtm_src_len);
1586 |       else
1587 | 	net_fill_ip6(&src, IP6_NONE, 0);
1588 |       break;
1589 | 
1590 | #ifdef HAVE_MPLS_KERNEL
1591 |     case AF_MPLS:
1592 |       if (!nl_parse_attrs(RTM_RTA(i), rtm_attr_want_mpls, a, sizeof(a)))
1593 | 	return;
1594 | 
1595 |       if (!a[RTA_DST])
1596 | 	SKIP0("MPLS route without RTA_DST\n");
1597 | 
1598 |       if (rta_get_mpls(a[RTA_DST], rta_mpls_stack) != 1)
1599 | 	SKIP0("MPLS route with multi-label RTA_DST\n");
1600 | 
1601 |       net_fill_mpls(&dst, rta_mpls_stack[0]);
1602 |       break;
1603 | #endif
1604 | 
1605 |     default:
1606 |       return;
1607 |     }
1608 | 
1609 |   if (a[RTA_OIF])
1610 |     oif = rta_get_u32(a[RTA_OIF]);
1611 | 
1612 |   if (a[RTA_TABLE])
1613 |     table_id = rta_get_u32(a[RTA_TABLE]);
1614 |   else
1615 |     table_id = i->rtm_table;
1616 | 
1617 |   if (i->rtm_flags & RTM_F_CLONED)
1618 |     SKIP("cloned\n");
1619 | 
1620 |   /* Do we know this table? */
1621 |   p = HASH_FIND(nl_table_map, RTH, i->rtm_family, table_id);
1622 |   if (!p)
1623 |     SKIP("unknown table %u\n", table_id);
1624 | 
1625 |   if (a[RTA_SRC] && (p->p.net_type != NET_IP6_SADR))
1626 |     SKIP("src prefix for non-SADR channel\n");
1627 | 
1628 |   if (a[RTA_IIF])
1629 |     SKIP("IIF set\n");
1630 | 
1631 |   if (i->rtm_tos != 0)			/* We don't support TOS */
1632 |     SKIP("TOS %02x\n", i->rtm_tos);
1633 | 
1634 |   if (s->scan && !new)
1635 |     SKIP("RTM_DELROUTE in scan\n");
1636 | 
1637 |   if (a[RTA_PRIORITY])
1638 |     priority = rta_get_u32(a[RTA_PRIORITY]);
1639 | 
1640 |   int c = net_classify(&dst);
1641 |   if ((c < 0) || !(c & IADDR_HOST) || ((c & IADDR_SCOPE_MASK) <= SCOPE_LINK))
1642 |     SKIP("strange class/scope\n");
1643 | 
1644 |   switch (i->rtm_protocol)
1645 |     {
1646 |     case RTPROT_UNSPEC:
1647 |       SKIP("proto unspec\n");
1648 | 
1649 |     case RTPROT_REDIRECT:
1650 |       krt_src = KRT_SRC_REDIRECT;
1651 |       break;
1652 | 
1653 |     case RTPROT_KERNEL:
1654 |       krt_src = KRT_SRC_KERNEL;
1655 |       break;
1656 | 
1657 |     case RTPROT_BIRD:
1658 |       if (!s->scan)
1659 | 	SKIP("echo\n");
1660 |       krt_src = KRT_SRC_BIRD;
1661 |       break;
1662 | 
1663 |     case RTPROT_BOOT:
1664 |     default:
1665 |       krt_src = KRT_SRC_ALIEN;
1666 |     }
1667 | 
1668 |   net_addr *n = &dst;
1669 |   if (p->p.net_type == NET_IP6_SADR)
1670 |   {
1671 |     n = alloca(sizeof(net_addr_ip6_sadr));
1672 |     net_fill_ip6_sadr(n, net6_prefix(&dst), net6_pxlen(&dst),
1673 | 		      net6_prefix(&src), net6_pxlen(&src));
1674 |   }
1675 | 
1676 |   net *net = net_get(p->p.main_channel->table, n);
1677 | 
1678 |   rta *ra = lp_allocz(s->pool, RTA_MAX_SIZE);
1679 |   ra->source = RTS_INHERIT;
1680 |   ra->scope = SCOPE_UNIVERSE;
1681 | 
1682 |   {
1683 |     ea_list *ea = lp_alloc(s->pool, sizeof(ea_list) + 2 * sizeof(eattr));
1684 |     *ea = (ea_list) { .flags = EALF_SORTED, .count = 2 };
1685 |     ea->next = ra->eattrs;
1686 |     ra->eattrs = ea;
1687 | 
1688 |     ea->attrs[0] = (eattr) {
1689 |       .id = EA_KRT_SOURCE,
1690 |       .type = EAF_TYPE_INT,
1691 |       .u.data = i->rtm_protocol
1692 |     };
1693 | 
1694 |     ea->attrs[1] = (eattr) {
1695 |       .id = EA_KRT_METRIC,
1696 |       .type = EAF_TYPE_INT,
1697 |       .u.data = priority,
1698 |     };
1699 |   }
1700 | 
1701 |   if (a[RTA_FLOW])
1702 |     s->rta_flow = rta_get_u32(a[RTA_FLOW]);
1703 |   else
1704 |     s->rta_flow = 0;
1705 | 
1706 |   switch (i->rtm_type)
1707 |     {
1708 |     case RTN_UNICAST:
1709 |       ra->dest = RTD_UNICAST;
1710 | 
1711 |       if (a[RTA_MULTIPATH])
1712 |         {
1713 | 	  struct nexthop *nh = nl_parse_multipath(s, p, n, a[RTA_MULTIPATH], i->rtm_family, krt_src);
1714 | 	  if (!nh)
1715 | 	    SKIP("strange RTA_MULTIPATH\n");
1716 | 
1717 | 	  nexthop_link(ra, nh);
1718 | 	  break;
1719 | 	}
1720 | 
1721 |       if ((i->rtm_flags & RTNH_F_DEAD) && (krt_src != KRT_SRC_BIRD))
1722 | 	SKIP("ignore RTNH_F_DEAD\n");
1723 | 
1724 |       ra->nh.iface = if_find_by_index(oif);
1725 |       if (!ra->nh.iface)
1726 | 	{
1727 | 	  log(L_ERR "KRT: Received route %N with unknown ifindex %u", net->n.addr, oif);
1728 | 	  return;
1729 | 	}
1730 | 
1731 |       if (a[RTA_GATEWAY])
1732 | 	ra->nh.gw = rta_get_ipa(a[RTA_GATEWAY]);
1733 | 
1734 |       if (a[RTA_VIA])
1735 | 	ra->nh.gw = rta_get_via(a[RTA_VIA]);
1736 | 
1737 |       if (i->rtm_flags & RTNH_F_ONLINK)
1738 | 	ra->nh.flags |= RNF_ONLINK;
1739 | 
1740 |       if (ipa_nonzero(ra->nh.gw))
1741 | 	{
1742 | 	  /* Silently skip strange 6to4 routes */
1743 | 	  const net_addr_ip6 sit = NET_ADDR_IP6(IP6_NONE, 96);
1744 | 	  if ((i->rtm_family == AF_INET6) && ipa_in_netX(ra->nh.gw, (net_addr *) &sit))
1745 | 	    return;
1746 | 
1747 | #ifdef CONFIG_ASSUME_ONLINK
1748 | 	  if (krt_assume_onlink(ra->nh.iface, ipa_is_ip6(ra->nh.gw)))
1749 | 	    ra->nh.flags |= RNF_ONLINK;
1750 | #endif
1751 | 
1752 | 	  neighbor *nbr;
1753 | 	  nbr = neigh_find(&p->p, ra->nh.gw, ra->nh.iface,
1754 | 			   (ra->nh.flags & RNF_ONLINK) ? NEF_ONLINK : 0);
1755 | 	  if (!nbr || (nbr->scope == SCOPE_HOST))
1756 | 	    {
1757 | 	      log(L_ERR "KRT: Received route %N with strange next-hop %I", net->n.addr,
1758 |                   ra->nh.gw);
1759 | 	      return;
1760 | 	    }
1761 | 	}
1762 | 
1763 |       break;
1764 |     case RTN_BLACKHOLE:
1765 |       ra->dest = RTD_BLACKHOLE;
1766 |       break;
1767 |     case RTN_UNREACHABLE:
1768 |       ra->dest = RTD_UNREACHABLE;
1769 |       break;
1770 |     case RTN_PROHIBIT:
1771 |       ra->dest = RTD_PROHIBIT;
1772 |       break;
1773 |     /* FIXME: What about RTN_THROW? */
1774 |     default:
1775 |       SKIP("type %d\n", i->rtm_type);
1776 |       return;
1777 |     }
1778 | 
1779 | #ifdef HAVE_MPLS_KERNEL
1780 |   if ((i->rtm_family == AF_MPLS) && a[RTA_NEWDST] && !ra->nh.next)
1781 |     ra->nh.labels = rta_get_mpls(a[RTA_NEWDST], ra->nh.label);
1782 | 
1783 |   if (a[RTA_ENCAP] && a[RTA_ENCAP_TYPE] && !ra->nh.next)
1784 |     {
1785 |       switch (rta_get_u16(a[RTA_ENCAP_TYPE]))
1786 | 	{
1787 | 	  case LWTUNNEL_ENCAP_MPLS:
1788 | 	    {
1789 | 	      struct rtattr *enca[BIRD_RTA_MAX];
1790 | 	      nl_attr_len = RTA_PAYLOAD(a[RTA_ENCAP]);
1791 | 	      nl_parse_attrs(RTA_DATA(a[RTA_ENCAP]), encap_mpls_want, enca, sizeof(enca));
1792 | 	      ra->nh.labels = rta_get_mpls(enca[RTA_DST], ra->nh.label);
1793 | 	      break;
1794 | 	    }
1795 | 	  default:
1796 | 	    SKIP("unknown encapsulation method %d\n", rta_get_u16(a[RTA_ENCAP_TYPE]));
1797 | 	    break;
1798 | 	}
1799 |     }
1800 | #endif
1801 | 
1802 |   if (i->rtm_scope != def_scope)
1803 |     {
1804 |       ea_list *ea = lp_alloc(s->pool, sizeof(ea_list) + sizeof(eattr));
1805 |       ea->next = ra->eattrs;
1806 |       ra->eattrs = ea;
1807 |       ea->flags = EALF_SORTED;
1808 |       ea->count = 1;
1809 |       ea->attrs[0] = (eattr) {
1810 |         .id = EA_KRT_SCOPE,
1811 |         .flags = 0,
1812 |         .type = EAF_TYPE_INT,
1813 |         .u.data = i->rtm_scope,
1814 |       };
1815 |     }
1816 | 
1817 |   if (a[RTA_PREFSRC])
1818 |     {
1819 |       ip_addr ps = rta_get_ipa(a[RTA_PREFSRC]);
1820 | 
1821 |       struct adata *ad = lp_alloc(s->pool, sizeof(struct adata) + sizeof(ps));
1822 |       ad->length = sizeof(ps);
1823 |       memcpy(ad->data, &ps, sizeof(ps));
1824 | 
1825 |       ea_list *ea = lp_alloc(s->pool, sizeof(ea_list) + sizeof(eattr));
1826 |       ea->next = ra->eattrs;
1827 |       ra->eattrs = ea;
1828 |       ea->flags = EALF_SORTED;
1829 |       ea->count = 1;
1830 |       ea->attrs[0] = (eattr) {
1831 | 	.id = EA_KRT_PREFSRC,
1832 |         .flags = 0,
1833 |         .type = EAF_TYPE_IP_ADDRESS,
1834 |         .u.ptr = ad,
1835 |       };
1836 |     }
1837 | 
1838 |   /* Can be set per-route or per-nexthop */
1839 |   if (s->rta_flow)
1840 |     {
1841 |       ea_list *ea = lp_alloc(s->pool, sizeof(ea_list) + sizeof(eattr));
1842 |       ea->next = ra->eattrs;
1843 |       ra->eattrs = ea;
1844 |       ea->flags = EALF_SORTED;
1845 |       ea->count = 1;
1846 |       ea->attrs[0] = (eattr) {
1847 | 	.id = EA_KRT_REALM,
1848 | 	.flags = 0,
1849 | 	.type = EAF_TYPE_INT,
1850 | 	.u.data = s->rta_flow,
1851 |       };
1852 |     }
1853 | 
1854 |   if (a[RTA_METRICS])
1855 |     {
1856 |       u32 metrics[KRT_METRICS_MAX];
1857 |       const char *cc_algo = NULL;
1858 |       ea_list *ea = lp_alloc(s->pool, sizeof(ea_list) + KRT_METRICS_MAX * sizeof(eattr));
1859 |       int t, n = 0;
1860 | 
1861 |       if (nl_parse_metrics(a[RTA_METRICS], metrics, &cc_algo, ARRAY_SIZE(metrics)) < 0)
1862 |         {
1863 | 	  log(L_ERR "KRT: Received route %N with strange RTA_METRICS attribute", net->n.addr);
1864 | 	  return;
1865 | 	}
1866 | 
1867 |       for (t = 1; t < KRT_METRICS_MAX; t++)
1868 | 	if (metrics[0] & (1 << t))
1869 | 	  if ((t == RTAX_LOCK) || (t == RTAX_FEATURES))
1870 | 	    {
1871 | 	      ea->attrs[n++] = (eattr) {
1872 | 		.id = EA_KRT_METRICS + t,
1873 | 		.type = EAF_TYPE_BITFIELD,
1874 | 		.u.data = metrics[t],
1875 | 	      };
1876 | 	    }
1877 |           else if (t == RTAX_CC_ALGO)
1878 | 	    {
1879 | 	      struct adata *ad = lp_alloc_adata(s->pool, strlen(cc_algo));
1880 | 	      memcpy(ad->data, cc_algo, ad->length);
1881 | 
1882 | 	      ea->attrs[n++] = (eattr) {
1883 | 		.id = EA_KRT_CONGCTL,
1884 | 		.type = EAF_TYPE_STRING,
1885 | 		.u.ptr = ad,
1886 | 	      };
1887 | 	    }
1888 | 	  else
1889 | 	    {
1890 | 	      ea->attrs[n++] = (eattr) {
1891 | 		.id = EA_KRT_METRICS + t,
1892 | 		.type = EAF_TYPE_INT,
1893 | 		.u.data = metrics[t],
1894 | 	      };
1895 | 	    }
1896 | 
1897 |       if (n > 0)
1898 |         {
1899 | 	  ea->next = ra->eattrs;
1900 | 	  ea->flags = EALF_SORTED;
1901 | 	  ea->count = n;
1902 | 	  ra->eattrs = ea;
1903 | 	}
1904 |     }
1905 | 
1906 |   rte *e = rte_get_temp(ra, p->p.main_source);
1907 |   e->net = net;
1908 | 
1909 |   if (s->scan)
1910 |     krt_got_route(p, e, krt_src);
1911 |   else
1912 |     krt_got_route_async(p, e, new, krt_src);
1913 | 
1914 |   lp_flush(s->pool);
1915 | }
1916 | 
1917 | void
1918 | krt_do_scan(struct krt_proto *p)
1919 | {
1920 |   struct nl_parse_state s = {
1921 |     .proto = p,
1922 |     .pool = nl_linpool,
1923 |     .scan = 1,
1924 |   };
1925 | 
1926 |   /* Table-specific scan or shared scan */
1927 |   if (p)
1928 |     nl_request_dump_route(p->af, krt_table_id(p));
1929 |   else
1930 |     nl_request_dump_route(AF_UNSPEC, 0);
1931 | 
1932 |   struct nlmsghdr *h;
1933 |   while (h = nl_get_scan())
1934 |   {
1935 |     if (h->nlmsg_type == RTM_NEWROUTE || h->nlmsg_type == RTM_DELROUTE)
1936 |       nl_parse_route(&s, h);
1937 |     else
1938 |       log(L_DEBUG "nl_scan_fire: Unknown packet received (type=%d)", h->nlmsg_type);
1939 |   }
1940 | }
