 476 | static inline u16 rta_get_u16(struct rtattr *a)
 477 | { return *(u16 *) RTA_DATA(a); }
 478 | 
 479 | static inline u32 rta_get_u32(struct rtattr *a)
 480 | { return *(u32 *) RTA_DATA(a); }
 481 | 
 482 | static inline const char *rta_get_str(struct rtattr *a)
 483 | { return RTA_DATA(a); }
 484 | 
 485 | static inline ip4_addr rta_get_ip4(struct rtattr *a)
 486 | { return ip4_ntoh(*(ip4_addr *) RTA_DATA(a)); }
 487 | 
 488 | static inline ip6_addr rta_get_ip6(struct rtattr *a)
 489 | { return ip6_ntoh(*(ip6_addr *) RTA_DATA(a)); }
 490 | 
 491 | static inline ip_addr rta_get_ipa(struct rtattr *a)
 492 | {
 493 |   if (RTA_PAYLOAD(a) == sizeof(ip4_addr))
 494 |     return ipa_from_ip4(rta_get_ip4(a));
 495 |   else
 496 |     return ipa_from_ip6(rta_get_ip6(a));
 497 | }
