 511 | static inline int rta_get_mpls(struct rtattr *a, u32 *stack)
 512 | {
 513 |   if (!a)
 514 |     return 0;
 515 | 
 516 |   if (RTA_PAYLOAD(a) % 4)
 517 |     log(L_WARN "KRT: Strange length of received MPLS stack: %u", RTA_PAYLOAD(a));
 518 | 
 519 |   int labels = mpls_get(RTA_DATA(a), RTA_PAYLOAD(a) & ~0x3, stack);
 520 | 
 521 |   if (labels < 0)
 522 |   {
 523 |     log(L_WARN "KRT: Too long MPLS stack received, ignoring");
 524 |     labels = 0;
 525 |   }
 526 | 
 527 |   return labels;
 528 | }
