 687 | static void
 688 | nl_add_multipath(struct nlmsghdr *h, uint bufsize, struct nexthop *nh, int af, ea_list *eattrs)
 689 | {
 690 |   struct rtattr *a = nl_open_attr(h, bufsize, RTA_MULTIPATH);
 691 |   eattr *flow = ea_find(eattrs, EA_KRT_REALM);
 692 | 
 693 |   for (; nh; nh = nh->next)
 694 |   {
 695 |     struct rtnexthop *rtnh = nl_open_nexthop(h, bufsize);
 696 | 
 697 |     rtnh->rtnh_flags = 0;
 698 |     rtnh->rtnh_hops = nh->weight;
 699 |     rtnh->rtnh_ifindex = nh->iface->index;
 700 | 
 701 |     nl_add_nexthop(h, bufsize, nh, af);
 702 | 
 703 |     if (nh->flags & RNF_ONLINK)
 704 |       rtnh->rtnh_flags |= RTNH_F_ONLINK;
 705 | 
 706 |     /* Our KRT_REALM is per-route, but kernel RTA_FLOW is per-nexthop.
 707 |        Therefore, we need to attach the same attribute to each nexthop. */
 708 |     if (flow)
 709 |       nl_add_attr_u32(h, bufsize, RTA_FLOW, flow->u.data);
 710 | 
 711 |     nl_close_nexthop(h, rtnh);
 712 |   }
 713 | 
 714 |   nl_close_attr(h, a);
 715 | }
