 904 | static void
 905 | nl_parse_link(struct nlmsghdr *h, int scan)
 906 | {
 907 |   struct ifinfomsg *i;
 908 |   struct rtattr *a[BIRD_IFLA_MAX];
 909 |   int new = h->nlmsg_type == RTM_NEWLINK;
 910 |   struct iface f = {};
 911 |   struct iface *ifi;
 912 |   const char *name, *kind = NULL;
 913 |   u32 mtu, master = 0;
 914 |   uint fl;
 915 | 
 916 |   if (!(i = nl_checkin(h, sizeof(*i))) || !nl_parse_attrs(IFLA_RTA(i), ifla_attr_want, a, sizeof(a)))
 917 |     return;
 918 |   if (!a[IFLA_IFNAME] || (RTA_PAYLOAD(a[IFLA_IFNAME]) < 2) || !a[IFLA_MTU])
 919 |     {
 920 |       /*
 921 |        * IFLA_IFNAME and IFLA_MTU are required, in fact, but there may also come
 922 |        * a message with IFLA_WIRELESS set, where (e.g.) no IFLA_IFNAME exists.
 923 |        * We simply ignore all such messages with IFLA_WIRELESS without notice.
 924 |        */
 925 | 
 926 |       if (a[IFLA_WIRELESS])
 927 | 	return;
 928 | 
 929 |       log(L_ERR "KIF: Malformed message received");
 930 |       return;
 931 |     }
 932 | 
 933 |   name = RTA_DATA(a[IFLA_IFNAME]);
 934 |   mtu = rta_get_u32(a[IFLA_MTU]);
 935 | 
 936 |   if (a[IFLA_MASTER])
 937 |     master = rta_get_u32(a[IFLA_MASTER]);
 938 | 
 939 |   if (a[IFLA_LINKINFO])
 940 |   {
 941 |     struct rtattr *li[BIRD_INFO_MAX];
 942 |     nl_attr_len = RTA_PAYLOAD(a[IFLA_LINKINFO]);
 943 |     nl_parse_attrs(RTA_DATA(a[IFLA_LINKINFO]), ifinfo_attr_want, li, sizeof(li));
 944 |     if (li[IFLA_INFO_KIND])
 945 |       kind = RTA_DATA(li[IFLA_INFO_KIND]);
 946 |   }
 947 | 
 948 |   ifi = if_find_by_index(i->ifi_index);
 949 |   if (!new)
 950 |     {
 951 |       DBG("KIF: IF%d(%s) goes down\n", i->ifi_index, name);
 952 |       if (!ifi)
 953 | 	return;
 954 | 
 955 |       if_delete(ifi);
 956 |     }
 957 |   else
 958 |     {
 959 |       DBG("KIF: IF%d(%s) goes up (mtu=%d,flg=%x)\n", i->ifi_index, name, mtu, i->ifi_flags);
 960 |       if (ifi && strncmp(ifi->name, name, sizeof(ifi->name)-1))
 961 | 	if_delete(ifi);
 962 | 
 963 |       strncpy(f.name, name, sizeof(f.name)-1);
 964 |       f.index = i->ifi_index;
 965 |       f.mtu = mtu;
 966 | 
 967 |       f.master_index = master;
 968 |       f.master = if_find_by_index(master);
 969 | 
 970 |       fl = i->ifi_flags;
 971 |       if (fl & IFF_UP)
 972 | 	f.flags |= IF_ADMIN_UP;
 973 |       if (fl & IFF_LOWER_UP)
 974 | 	f.flags |= IF_LINK_UP;
 975 |       if (fl & IFF_LOOPBACK)		/* Loopback */
 976 | 	f.flags |= IF_MULTIACCESS | IF_LOOPBACK | IF_IGNORE;
 977 |       else if (fl & IFF_POINTOPOINT)	/* PtP */
 978 | 	f.flags |= IF_MULTICAST;
 979 |       else if (fl & IFF_BROADCAST)	/* Broadcast */
 980 | 	f.flags |= IF_MULTIACCESS | IF_BROADCAST | IF_MULTICAST;
 981 |       else
 982 | 	f.flags |= IF_MULTIACCESS;	/* NBMA */
 983 | 
 984 |       if (fl & IFF_MULTICAST)
 985 | 	f.flags |= IF_MULTICAST;
 986 | 
 987 |       if (kind && !strcmp(kind, "vrf"))
 988 | 	f.flags |= IF_VRF;
 989 | 
 990 |       ifi = if_update(&f);
 991 | 
 992 |       if (!scan)
 993 | 	if_end_partial_update(ifi);
 994 |     }
 995 | }
