1215 | void
1216 | kif_do_scan(struct kif_proto *p UNUSED)
1217 | {
1218 |   struct nlmsghdr *h;
1219 | 
1220 |   if_start_update();
1221 | 
1222 |   nl_request_dump_link();
1223 |   while (h = nl_get_scan())
1224 |     if (h->nlmsg_type == RTM_NEWLINK || h->nlmsg_type == RTM_DELLINK)
1225 |       nl_parse_link(h, 1);
1226 |     else
1227 |       log(L_DEBUG "nl_scan_ifaces: Unknown packet received (type=%d)", h->nlmsg_type);
1228 | 
1229 |   /* Re-resolve master interface for slaves */
1230 |   struct iface *i;
1231 |   WALK_LIST(i, iface_list)
1232 |     if (i->master_index)
1233 |     {
1234 |       struct iface f = {
1235 | 	.flags = i->flags,
1236 | 	.mtu = i->mtu,
1237 | 	.index = i->index,
1238 | 	.master_index = i->master_index,
1239 | 	.master = if_find_by_index(i->master_index)
1240 |       };
1241 | 
1242 |       if (f.master != i->master)
1243 |       {
1244 | 	memcpy(f.name, i->name, sizeof(f.name));
1245 | 	if_update(&f);
1246 |       }
1247 |     }
1248 | 
1249 |   nl_request_dump_addr(AF_INET);
1250 |   while (h = nl_get_scan())
1251 |     if (h->nlmsg_type == RTM_NEWADDR || h->nlmsg_type == RTM_DELADDR)
1252 |       nl_parse_addr(h, 1);
1253 |     else
1254 |       log(L_DEBUG "nl_scan_ifaces: Unknown packet received (type=%d)", h->nlmsg_type);
1255 | 
1256 |   nl_request_dump_addr(AF_INET6);
1257 |   while (h = nl_get_scan())
1258 |     if (h->nlmsg_type == RTM_NEWADDR || h->nlmsg_type == RTM_DELADDR)
1259 |       nl_parse_addr(h, 1);
1260 |     else
1261 |       log(L_DEBUG "nl_scan_ifaces: Unknown packet received (type=%d)", h->nlmsg_type);
1262 | 
1263 |   if_end_update();
1264 | }
