1797 | 	    break;
1798 | 	}
1799 |     }
1800 | #endif
1801 | 
1802 |   if (i->rtm_scope != def_scope)
1803 |     {
1804 |       ea_list *ea = lp_alloc(s->pool, sizeof(ea_list) + sizeof(eattr));
1805 |       ea->next = ra->eattrs;
1806 |       ra->eattrs = ea;
1807 |       ea->flags = EALF_SORTED;
1808 |       ea->count = 1;
1809 |       ea->attrs[0] = (eattr) {
1810 |         .id = EA_KRT_SCOPE,
1811 |         .flags = 0,
1812 |         .type = EAF_TYPE_INT,
1813 |         .u.data = i->rtm_scope,
1814 |       };
