1195 | static void
1196 | nl_parse_addr(struct nlmsghdr *h, int scan)
1197 | {
1198 |   struct ifaddrmsg *i;
1199 | 
1200 |   if (!(i = nl_checkin(h, sizeof(*i))))
1201 |     return;
1202 | 
1203 |   int new = (h->nlmsg_type == RTM_NEWADDR);
1204 | 
1205 |   switch (i->ifa_family)
1206 |     {
1207 |       case AF_INET:
1208 | 	return nl_parse_addr4(i, scan, new);
1209 | 
1210 |       case AF_INET6:
1211 | 	return nl_parse_addr6(i, scan, new);
1212 |     }
