1315 | static int
1316 | nl_send_route(struct krt_proto *p, rte *e, int op)
1317 | {
1318 |   eattr *ea;
1319 |   net *net = e->net;
1320 |   rta *a = e->attrs;
1321 |   ea_list *eattrs = a->eattrs;
1322 |   int bufsize = 128 + KRT_METRICS_MAX*8 + nh_bufsize(&(a->nh));
1323 |   u32 priority = 0;
1324 | 
1325 |   struct {
1326 |     struct nlmsghdr h;
1327 |     struct rtmsg r;
1328 |     char buf[0];
1329 |   } *r;
1330 | 
1331 |   int rsize = sizeof(*r) + bufsize;
1332 |   r = alloca(rsize);
1333 | 
1334 |   DBG("nl_send_route(%N,op=%x)\n", net->n.addr, op);
1335 | 
1336 |   bzero(&r->h, sizeof(r->h));
1337 |   bzero(&r->r, sizeof(r->r));
1338 |   r->h.nlmsg_type = op ? RTM_NEWROUTE : RTM_DELROUTE;
1339 |   r->h.nlmsg_len = NLMSG_LENGTH(sizeof(struct rtmsg));
1340 |   r->h.nlmsg_flags = op | NLM_F_REQUEST | NLM_F_ACK;
1341 | 
1342 |   r->r.rtm_family = p->af;
1343 |   r->r.rtm_dst_len = net_pxlen(net->n.addr);
1344 |   r->r.rtm_protocol = RTPROT_BIRD;
1345 |   r->r.rtm_scope = RT_SCOPE_NOWHERE;
1346 | #ifdef HAVE_MPLS_KERNEL
1347 |   if (p->af == AF_MPLS)
1348 |   {
1349 |     /*
1350 |      * Kernel MPLS code is a bit picky. We must:
1351 |      * 1) Always set RT_SCOPE_UNIVERSE and RTN_UNICAST (even for RTM_DELROUTE)
1352 |      * 2) Never use RTA_PRIORITY
1353 |      */
1354 | 
1355 |     u32 label = net_mpls(net->n.addr);
1356 |     nl_add_attr_mpls(&r->h, rsize, RTA_DST, 1, &label);
1357 |     r->r.rtm_scope = RT_SCOPE_UNIVERSE;
1358 |     r->r.rtm_type = RTN_UNICAST;
1359 |   }
1360 |   else
1361 | #endif
1362 |   {
1363 |     nl_add_attr_ipa(&r->h, rsize, RTA_DST, net_prefix(net->n.addr));
1364 | 
1365 |     /* Add source address for IPv6 SADR routes */
1366 |     if (net->n.addr->type == NET_IP6_SADR)
1367 |     {
1368 |       net_addr_ip6_sadr *a = (void *) &net->n.addr;
1369 |       nl_add_attr_ip6(&r->h, rsize, RTA_SRC, a->src_prefix);
1370 |       r->r.rtm_src_len = a->src_pxlen;
1371 |     }
1372 |   }
1373 | 
1374 |   /*
1375 |    * Strange behavior for RTM_DELROUTE:
1376 |    * 1) rtm_family is ignored in IPv6, works for IPv4
1377 |    * 2) not setting RTA_PRIORITY is different from setting default value (on IPv6)
1378 |    * 3) not setting RTA_PRIORITY is equivalent to setting 0, which is wildcard
1379 |    */
1380 | 
1381 |   if (krt_table_id(p) < 256)
1382 |     r->r.rtm_table = krt_table_id(p);
1383 |   else
1384 |     nl_add_attr_u32(&r->h, rsize, RTA_TABLE, krt_table_id(p));
1385 | 
1386 |   if (p->af == AF_MPLS)
1387 |     priority = 0;
1388 |   else if (KRT_CF->sys.metric)
1389 |     priority = KRT_CF->sys.metric;
1390 |   else if ((op != NL_OP_DELETE) && (ea = ea_find(eattrs, EA_KRT_METRIC)))
1391 |     priority = ea->u.data;
1392 | 
1393 |   if (priority)
1394 |     nl_add_attr_u32(&r->h, rsize, RTA_PRIORITY, priority);
1395 | 
1396 |   /* For route delete, we do not specify remaining route attributes */
1397 |   if (op == NL_OP_DELETE)
1398 |     goto done;
1399 | 
1400 |   /* Default scope is LINK for device routes, UNIVERSE otherwise */
1401 |   if (p->af == AF_MPLS)
1402 |     r->r.rtm_scope = RT_SCOPE_UNIVERSE;
1403 |   else if (ea = ea_find(eattrs, EA_KRT_SCOPE))
1404 |     r->r.rtm_scope = ea->u.data;
1405 |   else if (a->dest == RTD_UNICAST && ipa_zero(a->nh.gw))
1406 |     r->r.rtm_scope = RT_SCOPE_LINK;
1407 |   else
1408 |     r->r.rtm_scope = RT_SCOPE_UNIVERSE;
1409 | 
1410 |   if (ea = ea_find(eattrs, EA_KRT_PREFSRC))
1411 |     nl_add_attr_ipa(&r->h, rsize, RTA_PREFSRC, *(ip_addr *)ea->u.ptr->data);
1412 | 
1413 |   if (ea = ea_find(eattrs, EA_KRT_REALM))
1414 |     nl_add_attr_u32(&r->h, rsize, RTA_FLOW, ea->u.data);
1415 | 
1416 | 
1417 |   u32 metrics[KRT_METRICS_MAX];
1418 |   const char *cc_algo = NULL;
1419 |   metrics[0] = 0;
1420 | 
1421 |   struct ea_walk_state ews = { .eattrs = eattrs };
1422 |   while (ea = ea_walk(&ews, EA_KRT_METRICS, KRT_METRICS_MAX))
1423 |   {
1424 |     int id = ea->id - EA_KRT_METRICS;
1425 |     metrics[0] |= 1 << id;
1426 | 
1427 |     if (id == RTAX_CC_ALGO)
1428 |       cc_algo = ea->u.ptr->data;
1429 |     else
1430 |       metrics[id] = ea->u.data;
1431 |   }
1432 | 
1433 |   if (metrics[0])
1434 |     nl_add_metrics(&r->h, rsize, metrics, cc_algo, KRT_METRICS_MAX);
1435 | 
1436 |   switch (a->dest)
1437 |     {
1438 |     case RTD_UNICAST:
1439 |       r->r.rtm_type = RTN_UNICAST;
1440 |       struct nexthop *nh = &(a->nh);
1441 |       if (nh->next)
1442 | 	nl_add_multipath(&r->h, rsize, nh, p->af, eattrs);
1443 |       else
1444 |       {
1445 | 	nl_add_attr_u32(&r->h, rsize, RTA_OIF, nh->iface->index);
1446 | 	nl_add_nexthop(&r->h, rsize, nh, p->af);
1447 | 
1448 | 	if (nh->flags & RNF_ONLINK)
1449 | 	  r->r.rtm_flags |= RTNH_F_ONLINK;
1450 |       }
1451 |       break;
1452 |     case RTD_BLACKHOLE:
1453 |       r->r.rtm_type = RTN_BLACKHOLE;
1454 |       break;
1455 |     case RTD_UNREACHABLE:
1456 |       r->r.rtm_type = RTN_UNREACHABLE;
1457 |       break;
1458 |     case RTD_PROHIBIT:
1459 |       r->r.rtm_type = RTN_PROHIBIT;
1460 |       break;
1461 |     case RTD_NONE:
1462 |       break;
1463 |     default:
1464 |       bug("krt_capable inconsistent with nl_send_route");
1465 |     }
1466 | 
1467 | done:
1468 |   /* Ignore missing for DELETE */
1469 |   return nl_exchange(&r->h, (op == NL_OP_DELETE));
1470 | }
