1472 | static inline int
1473 | nl_allow_replace(struct krt_proto *p, rte *new, rte *old)
1474 | {
1475 |   /*
1476 |    * In kernel routing tables, (net, metric) is the primary key. Therefore, we
1477 |    * can use NL_OP_REPLACE only if the new and and the old route have the same
1478 |    * kernel metric, otherwise the replace would just add the new route while
1479 |    * keep the old one.
1480 |    */
1481 | 
1482 |   if ((p->af != AF_MPLS) && (KRT_CF->sys.metric == 0))
1483 |   {
1484 |     uint new_metric = ea_get_int(new->attrs->eattrs, EA_KRT_METRIC, 0);
1485 |     uint old_metric = ea_get_int(old->attrs->eattrs, EA_KRT_METRIC, 0);
1486 | 
1487 |     if (new_metric != old_metric)
1488 |       return 0;
1489 |   }
1490 | 
1491 |   /*
1492 |    * We use NL_OP_REPLACE for IPv4, it has an issue with not checking for
1493 |    * matching rtm_protocol, but that is OK when dedicated priority is used.
1494 |    *
1495 |    * For IPv6, the NL_OP_REPLACE is still broken even in Linux 4.19 LTS
1496 |    * (although it seems to be fixed in Linux 5.10 LTS) for sequence:
1497 |    *
1498 |    * ip route add 2001:db8::/32 via fe80::1 dev eth0
1499 |    * ip route replace 2001:db8::/32 dev eth0
1500 |    *
1501 |    * (it ends with two routes instead of replacing the first by the second one)
1502 |    *
1503 |    * Replacing with direct and special type (e.g. unreachable) routes does not
1504 |    * work, but replacing with regular routes work reliably
1505 |    */
1506 | 
1507 |   if (krt_ipv4(p))
1508 |     return 1;
1509 | 
1510 |   rta *a = new->attrs;
1511 |   return (a->dest == RTD_UNICAST) && ipa_nonzero(a->nh.gw);
1512 | }
1513 | 
1514 | void
1515 | krt_replace_rte(struct krt_proto *p, net *n UNUSED, rte *new, rte *old)
1516 | {
1517 |   int err = 0;
1518 | 
1519 |   if (old && new && nl_allow_replace(p, new, old))
1520 |   {
1521 |     err = nl_send_route(p, new, NL_OP_REPLACE);
1522 |   }
1523 |   else
1524 |   {
1525 |     if (old)
1526 |       nl_send_route(p, old, NL_OP_DELETE);
1527 | 
1528 |     if (new)
1529 |       err = nl_send_route(p, new, NL_OP_ADD);
1530 |   }
1531 | 
1532 |   if (new)
1533 |   {
1534 |     if (err < 0)
1535 |       bmap_clear(&p->sync_map, new->id);
1536 |     else
1537 |       bmap_set(&p->sync_map, new->id);
1538 |   }
1539 | }
