1942 | /*
1943 |  *	Asynchronous Netlink interface
1944 |  */
1945 | 
1946 | static sock *nl_async_sk;		/* BIRD socket for asynchronous notifications */
1947 | static byte *nl_async_rx_buffer;	/* Receive buffer */
1948 | static uint nl_async_bufsize;		/* Kernel rx buffer size for the netlink socket */
1949 | static struct config *nl_last_config;	/* For tracking changes to nl_async_bufsize */
1950 | 
1951 | static void
1952 | nl_async_msg(struct nlmsghdr *h)
1953 | {
1954 |   struct nl_parse_state s = {
1955 |     .proto = NULL,
1956 |     .pool = nl_linpool,
1957 |     .scan = 0,
1958 |   };
1959 | 
1960 |   switch (h->nlmsg_type)
1961 |     {
1962 |     case RTM_NEWROUTE:
1963 |     case RTM_DELROUTE:
1964 |       DBG("KRT: Received async route notification (%d)\n", h->nlmsg_type);
1965 |       nl_parse_route(&s, h);
1966 |       break;
1967 |     case RTM_NEWLINK:
1968 |     case RTM_DELLINK:
1969 |       DBG("KRT: Received async link notification (%d)\n", h->nlmsg_type);
1970 |       if (kif_proto)
1971 | 	nl_parse_link(h, 0);
1972 |       break;
1973 |     case RTM_NEWADDR:
1974 |     case RTM_DELADDR:
1975 |       DBG("KRT: Received async address notification (%d)\n", h->nlmsg_type);
1976 |       if (kif_proto)
1977 | 	nl_parse_addr(h, 0);
1978 |       break;
1979 |     default:
1980 |       DBG("KRT: Received unknown async notification (%d)\n", h->nlmsg_type);
1981 |     }
1982 | }
1983 | 
1984 | static int
1985 | nl_async_hook(sock *sk, uint size UNUSED)
1986 | {
1987 |   struct iovec iov = { nl_async_rx_buffer, NL_RX_SIZE };
1988 |   struct sockaddr_nl sa;
1989 |   struct msghdr m = {
1990 |     .msg_name = &sa,
1991 |     .msg_namelen = sizeof(sa),
1992 |     .msg_iov = &iov,
1993 |     .msg_iovlen = 1,
1994 |   };
1995 |   struct nlmsghdr *h;
1996 |   int x;
1997 |   uint len;
1998 | 
1999 |   x = recvmsg(sk->fd, &m, 0);
2000 |   if (x < 0)
2001 |     {
2002 |       if (errno == ENOBUFS)
2003 | 	{
2004 | 	  /*
2005 | 	   *  Netlink reports some packets have been thrown away.
2006 | 	   *  One day we might react to it by asking for route table
2007 | 	   *  scan in near future.
2008 | 	   */
2009 | 	  log(L_WARN "Kernel dropped some netlink messages, will resync on next scan.");
2010 | 	  return 1;	/* More data are likely to be ready */
2011 | 	}
2012 |       else if (errno != EWOULDBLOCK)
2013 | 	log(L_ERR "Netlink recvmsg: %m");
2014 |       return 0;
2015 |     }
2016 |   if (sa.nl_pid)		/* It isn't from the kernel */
2017 |     {
2018 |       DBG("Non-kernel packet\n");
2019 |       return 1;
2020 |     }
2021 |   h = (void *) nl_async_rx_buffer;
2022 |   len = x;
2023 |   if (m.msg_flags & MSG_TRUNC)
2024 |     {
2025 |       log(L_WARN "Netlink got truncated asynchronous message");
2026 |       return 1;
2027 |     }
2028 |   while (NLMSG_OK(h, len))
2029 |     {
2030 |       nl_async_msg(h);
2031 |       h = NLMSG_NEXT(h, len);
2032 |     }
2033 |   if (len)
2034 |     log(L_WARN "nl_async_hook: Found packet remnant of size %d", len);
2035 |   return 1;
2036 | }
2037 | 
2038 | static void
2039 | nl_async_err_hook(sock *sk, int e UNUSED)
2040 | {
2041 |   nl_async_hook(sk, 0);
2042 | }
2043 | 
2044 | static void
2045 | nl_open_async(void)
2046 | {
2047 |   sock *sk;
2048 |   struct sockaddr_nl sa;
2049 |   int fd;
2050 | 
2051 |   if (nl_async_sk)
2052 |     return;
2053 | 
2054 |   DBG("KRT: Opening async netlink socket\n");
2055 | 
2056 |   fd = socket(PF_NETLINK, SOCK_RAW, NETLINK_ROUTE);
2057 |   if (fd < 0)
2058 |     {
2059 |       log(L_ERR "Unable to open asynchronous rtnetlink socket: %m");
2060 |       return;
2061 |     }
2062 | 
2063 |   bzero(&sa, sizeof(sa));
2064 |   sa.nl_family = AF_NETLINK;
2065 |   sa.nl_groups = RTMGRP_LINK |
2066 |     RTMGRP_IPV4_IFADDR | RTMGRP_IPV4_ROUTE |
2067 |     RTMGRP_IPV6_IFADDR | RTMGRP_IPV6_ROUTE;
2068 | 
2069 |   if (bind(fd, (struct sockaddr *) &sa, sizeof(sa)) < 0)
2070 |     {
2071 |       log(L_ERR "Unable to bind asynchronous rtnetlink socket: %m");
2072 |       close(fd);
2073 |       return;
2074 |     }
2075 | 
2076 |   nl_async_rx_buffer = xmalloc(NL_RX_SIZE);
2077 | 
2078 |   sk = nl_async_sk = sk_new(krt_pool);
2079 |   sk->type = SK_MAGIC;
2080 |   sk->rx_hook = nl_async_hook;
2081 |   sk->err_hook = nl_async_err_hook;
2082 |   sk->fd = fd;
2083 |   if (sk_open(sk) < 0)
2084 |     bug("Netlink: sk_open failed");
2085 | }
2086 | 
2087 | static void
2088 | nl_update_async_bufsize(void)
2089 | {
2090 |   /* No async socket */
2091 |   if (!nl_async_sk)
2092 |     return;
2093 | 
2094 |   /* Already reconfigured */
2095 |   if (nl_last_config == config)
2096 |     return;
2097 | 
2098 |   /* Update netlink buffer size */
2099 |   uint bufsize = nl_cfg_rx_buffer_size(config);
2100 |   if (bufsize && (bufsize != nl_async_bufsize))
2101 |   {
2102 |     /* Log message for reconfigurations only */
2103 |     if (nl_last_config)
2104 |       log(L_INFO "KRT: Changing netlink rx buffer size to %u", bufsize);
2105 | 
2106 |     nl_set_rcvbuf(nl_async_sk->fd, bufsize);
2107 |     nl_async_bufsize = bufsize;
2108 |   }
2109 | 
2110 |   nl_last_config = config;
2111 | }
