399 | /*
400 |  * IFS stack - it contains structures needed for recursive processing
401 |  * of include in config files. On the top of the stack is a structure
402 |  * for currently processed file. Other structures are either for
403 |  * active files interrupted because of include directive (these have
404 |  * fd and flex buffer) or for inactive files scheduled to be processed
405 |  * later (when parent requested including of several files by wildcard
406 |  * match - these do not have fd and flex buffer yet).
407 |  *
408 |  * FIXME: Most of these ifs and include functions are really sysdep/unix.
409 |  */
410 | 
411 | static struct include_file_stack *
412 | push_ifs(struct include_file_stack *old)
413 | {
414 |   struct include_file_stack *ret;
415 |   ret = cfg_allocz(sizeof(struct include_file_stack));
416 |   ret->lino = 1;
417 |   ret->prev = old;
418 |   return ret;
419 | }
420 | 
421 | static struct include_file_stack *
422 | pop_ifs(struct include_file_stack *old)
423 | {
424 |  yy_delete_buffer(old->buffer);
425 |  close(old->fd);
426 |  return old->prev;
427 | }
428 | 
429 | static void
430 | enter_ifs(struct include_file_stack *new)
431 | {
432 |   if (!new->buffer)
433 |     {
434 |       new->fd = open(new->file_name, O_RDONLY);
435 |       if (new->fd < 0)
436 |         {
437 |           ifs = ifs->up;
438 | 	  cf_error("Unable to open included file %s: %m", new->file_name);
439 |         }
440 | 
441 |       new->buffer = yy_create_buffer(NULL, YY_BUF_SIZE);
442 |     }
443 | 
444 |   yy_switch_to_buffer(new->buffer);
445 | }
446 | 
447 | /**
448 |  * cf_lex_unwind - unwind lexer state during error
449 |  *
450 |  * cf_lex_unwind() frees the internal state on IFS stack when the lexical
451 |  * analyzer is terminated by cf_error().
452 |  */
453 | void
454 | cf_lex_unwind(void)
455 | {
456 |   struct include_file_stack *n;
457 | 
458 |   for (n = ifs; n != ifs_head; n = n->prev)
459 |     {
460 |       /* Memory is freed automatically */
461 |       if (n->buffer)
462 | 	yy_delete_buffer(n->buffer);
463 |       if (n->fd)
464 |         close(n->fd);
465 |     }
466 | 
467 |   ifs = ifs_head;
468 | }
469 | 
470 | static void
471 | cf_include(char *arg, int alen)
472 | {
473 |   struct include_file_stack *base_ifs = ifs;
474 |   int new_depth, rv, i;
475 |   char *patt;
476 |   glob_t g = {};
477 | 
478 |   new_depth = ifs->depth + 1;
479 |   if (new_depth > MAX_INCLUDE_DEPTH)
480 |     cf_error("Max include depth reached");
481 | 
482 |   /* expand arg to properly handle relative filenames */
483 |   if (*arg != '/')
484 |     {
485 |       int dlen = strlen(ifs->file_name);
486 |       char *dir = alloca(dlen + 1);
487 |       patt = alloca(dlen + alen + 2);
488 |       memcpy(dir, ifs->file_name, dlen + 1);
489 |       sprintf(patt, "%s/%s", dirname(dir), arg);
490 |     }
491 |   else
492 |     patt = arg;
493 | 
494 |   /* Skip globbing if there are no wildcards, mainly to get proper
495 |      response when the included config file is missing */
496 |   if (!strpbrk(arg, "?*["))
497 |     {
498 |       ifs = push_ifs(ifs);
499 |       ifs->file_name = cfg_strdup(patt);
500 |       ifs->depth = new_depth;
501 |       ifs->up = base_ifs;
502 |       enter_ifs(ifs);
503 |       return;
504 |     }
505 | 
506 |   /* Expand the pattern */
507 |   rv = glob(patt, GLOB_ERR | GLOB_NOESCAPE, NULL, &g);
508 |   if (rv == GLOB_ABORTED)
509 |     cf_error("Unable to match pattern %s: %m", patt);
510 |   if ((rv != 0) || (g.gl_pathc <= 0))
511 |     return;
512 | 
513 |   /*
514 |    * Now we put all found files to ifs stack in reverse order, they
515 |    * will be activated and processed in order as ifs stack is popped
516 |    * by pop_ifs() and enter_ifs() in check_eof().
517 |    */
518 |   for(i = g.gl_pathc - 1; i >= 0; i--)
519 |     {
520 |       char *fname = g.gl_pathv[i];
521 |       struct stat fs;
522 | 
523 |       if (stat(fname, &fs) < 0)
524 | 	{
525 | 	  globfree(&g);
526 | 	  cf_error("Unable to stat included file %s: %m", fname);
527 | 	}
528 | 
529 |       if (fs.st_mode & S_IFDIR)
530 |         continue;
531 | 
532 |       /* Prepare new stack item */
533 |       ifs = push_ifs(ifs);
534 |       ifs->file_name = cfg_strdup(fname);
535 |       ifs->depth = new_depth;
536 |       ifs->up = base_ifs;
537 |     }
538 | 
539 |   globfree(&g);
540 |   enter_ifs(ifs);
541 | }
542 | 
543 | static int
544 | check_eof(void)
545 | {
546 |   if (ifs == ifs_head)
547 |     {
548 |       /* EOF in main config file */
549 |       ifs->lino = 1; /* Why this? */
550 |       return 1;
551 |     }
552 | 
553 |   ifs = pop_ifs(ifs);
554 |   enter_ifs(ifs);
555 |   return 0;
556 | }
