560 | struct symbol *
561 | cf_new_symbol(struct sym_scope *scope, pool *p, struct linpool *lp, const byte *c)
562 | {
563 |   if (scope->readonly)
564 |     cf_error("Unknown symbol %s", c);
565 | 
566 |   struct symbol *s;
567 | 
568 |   uint l = strlen(c);
569 |   if (l > SYM_MAX_LEN)
570 |     cf_error("Symbol too long");
571 | 
572 |   s = lp_alloc(lp, sizeof(struct symbol) + l + 1);
573 |   *s = (struct symbol) { .scope = scope, .class = SYM_VOID, };
574 |   strcpy(s->name, c);
575 | 
576 |   if (!scope->hash.data)
577 |     HASH_INIT(scope->hash, p, SYM_ORDER);
578 | 
579 |   HASH_INSERT2(scope->hash, SYM, p, s);
580 | 
581 |   if (new_config && (scope == new_config->root_scope))
582 |     add_tail(&(new_config->symbols), &(s->n));
