587 | /**
588 |  * cf_find_symbol_scope - find a symbol by name
589 |  * @scope: config scope
590 |  * @c: symbol name
591 |  *
592 |  * This functions searches the symbol table in the scope @scope for a symbol of
593 |  * given name. First it examines the current scope, then the underlying one
594 |  * and so on until it either finds the symbol and returns a pointer to its
595 |  * &symbol structure or reaches the end of the scope chain and returns %NULL to
596 |  * signify no match.
597 |  */
598 | struct symbol *
599 | cf_find_symbol_scope(const struct sym_scope *scope, const byte *c)
600 | {
601 |   struct symbol *s;
602 | 
603 |   /* Find the symbol here or anywhere below */
604 |   while (scope)
605 |     if (scope->hash.data && (s = HASH_FIND(scope->hash, SYM, c)))
606 |       return s;
607 |     else
608 |       scope = scope->next;
609 | 
610 |   return NULL;
611 | }
