613 | /**
614 |  * cf_get_symbol - get a symbol by name
615 |  * @c: symbol name
616 |  *
617 |  * This functions searches the symbol table of the currently parsed config
618 |  * (@new_config) for a symbol of given name. It returns either the already
619 |  * existing symbol or a newly allocated undefined (%SYM_VOID) symbol if no
620 |  * existing symbol is found.
621 |  */
622 | struct symbol *
623 | cf_get_symbol(struct config *conf, const byte *c)
624 | {
625 |   return cf_find_symbol_scope(conf->current_scope, c) ?: (
626 |       cf_swap_soft_scope(conf),
627 |       cf_new_symbol(conf->current_scope, conf->pool, conf->mem, c)
628 |       );
629 | }
630 | 
631 | /**
632 |  * cf_localize_symbol - get the local instance of given symbol
633 |  * @sym: the symbol to localize
634 |  *
635 |  * This functions finds the symbol that is local to current scope
636 |  * for purposes of cf_define_symbol().
637 |  */
638 | struct symbol *
639 | cf_localize_symbol(struct config *conf, struct symbol *sym)
640 | {
641 |   /* If the symbol type is void, it has been recently allocated just in this scope. */
642 |   if (!sym->class)
643 |     return sym;
644 | 
645 |   /* If the scope is the current, it is already defined in this scope. */
646 |   if (cf_symbol_is_local(conf, sym))
647 |     cf_error("Symbol '%s' already defined", sym->name);
648 | 
649 |   /* Not allocated here yet, doing it now. */
650 |   cf_swap_soft_scope(conf);
651 |   return cf_new_symbol(conf->current_scope, conf->pool, conf->mem, sym->name);
652 | }
