654 | struct symbol *
655 | cf_default_name(struct config *conf, char *template, int *counter)
656 | {
657 |   char buf[SYM_MAX_LEN];
658 |   struct symbol *s;
659 |   char *perc = strchr(template, '%');
660 | 
661 |   for(;;)
662 |     {
663 |       bsprintf(buf, template, ++(*counter));
