673 | static enum yytokentype
674 | cf_lex_symbol(const char *data)
675 | {
676 |   /* Have we defined such a symbol? */
677 |   struct symbol *sym = cf_get_symbol(new_config, data);
678 |   cf_lval.s = sym;
679 | 
680 |   switch (sym->class)
681 |   {
682 |     case SYM_KEYWORD:
683 |     {
684 |       int val = sym->keyword->value;
685 |       if (val > 0) return val;
686 |       cf_lval.i = -val;
687 |       return ENUM_TOKEN;
688 |     }
689 |     case SYM_METHOD:
690 |       return (sym->method->arg_num > 1) ? CF_SYM_METHOD_ARGS : CF_SYM_METHOD_BARE;
691 |     case SYM_VOID:
692 |       return CF_SYM_UNDEFINED;
693 |     default:
694 |       return CF_SYM_KNOWN;
695 |   }
