587 | /**
588 |  * cf_find_symbol_scope - find a symbol by name
589 |  * @scope: config scope
590 |  * @c: symbol name
591 |  *
592 |  * This functions searches the symbol table in the scope @scope for a symbol of
593 |  * given name. First it examines the current scope, then the underlying one
594 |  * and so on until it either finds the symbol and returns a pointer to its
595 |  * &symbol structure or reaches the end of the scope chain and returns %NULL to
596 |  * signify no match.
597 |  */
598 | struct symbol *
599 | cf_find_symbol_scope(const struct sym_scope *scope, const byte *c)
600 | {
601 |   struct symbol *s;
602 | 
603 |   /* Find the symbol here or anywhere below */
604 |   while (scope)
605 |     if (scope->hash.data && (s = HASH_FIND(scope->hash, SYM, c)))
606 |       return s;
607 |     else
608 |       scope = scope->next;
609 | 
610 |   return NULL;
611 | }
612 | 
613 | /**
614 |  * cf_get_symbol - get a symbol by name
615 |  * @c: symbol name
616 |  *
617 |  * This functions searches the symbol table of the currently parsed config
618 |  * (@new_config) for a symbol of given name. It returns either the already
619 |  * existing symbol or a newly allocated undefined (%SYM_VOID) symbol if no
620 |  * existing symbol is found.
621 |  */
622 | struct symbol *
623 | cf_get_symbol(struct config *conf, const byte *c)
624 | {
625 |   return cf_find_symbol_scope(conf->current_scope, c) ?: (
626 |       cf_swap_soft_scope(conf),
627 |       cf_new_symbol(conf->current_scope, conf->pool, conf->mem, c)
628 |       );
629 | }
630 | 
631 | /**
632 |  * cf_localize_symbol - get the local instance of given symbol
633 |  * @sym: the symbol to localize
634 |  *
635 |  * This functions finds the symbol that is local to current scope
636 |  * for purposes of cf_define_symbol().
637 |  */
638 | struct symbol *
639 | cf_localize_symbol(struct config *conf, struct symbol *sym)
640 | {
641 |   /* If the symbol type is void, it has been recently allocated just in this scope. */
642 |   if (!sym->class)
643 |     return sym;
644 | 
645 |   /* If the scope is the current, it is already defined in this scope. */
646 |   if (cf_symbol_is_local(conf, sym))
647 |     cf_error("Symbol '%s' already defined", sym->name);
648 | 
649 |   /* Not allocated here yet, doing it now. */
650 |   cf_swap_soft_scope(conf);
651 |   return cf_new_symbol(conf->current_scope, conf->pool, conf->mem, sym->name);
652 | }
653 | 
654 | struct symbol *
655 | cf_default_name(struct config *conf, char *template, int *counter)
656 | {
657 |   char buf[SYM_MAX_LEN];
658 |   struct symbol *s;
659 |   char *perc = strchr(template, '%');
660 | 
661 |   for(;;)
662 |     {
663 |       bsprintf(buf, template, ++(*counter));
664 |       s = cf_get_symbol(conf, buf);
665 |       if (s->class == SYM_VOID)
666 | 	return s;
667 |       if (!perc)
668 | 	break;
669 |     }
670 |   cf_error("Unable to generate default name");
671 | }
