673 | static enum yytokentype
674 | cf_lex_symbol(const char *data)
675 | {
676 |   /* Have we defined such a symbol? */
677 |   struct symbol *sym = cf_get_symbol(new_config, data);
678 |   cf_lval.s = sym;
679 | 
680 |   switch (sym->class)
681 |   {
682 |     case SYM_KEYWORD:
683 |     {
