271 | server_got_reply(char *x)
272 | {
273 |   int code;
274 |   int len = 0;
275 | 
276 |   if (*x == '+')                        /* Async reply */
277 |     PRINTF(len, ">>> %s\n", x+1);
278 |   else if (x[0] == ' ')                 /* Continuation */
279 |     PRINTF(len, "%s%s\n", verbose ? "     " : "", x+1);
280 |   else if (strlen(x) > 4 &&
281 |            sscanf(x, "%d", &code) == 1 && code >= 0 && code < 10000 &&
282 |            (x[4] == ' ' || x[4] == '-'))
