349 | select_loop(void)
350 | {
351 |   int rv;
352 |   while (1)
353 |     {
354 |       if (init && !busy)
355 | 	init_commands();
356 | 
357 |       if (!init)
358 | 	input_notify(!busy);
359 | 
360 |       fd_set select_fds;
361 |       FD_ZERO(&select_fds);
362 | 
363 |       FD_SET(server_fd, &select_fds);
364 |       if (!busy)
365 | 	FD_SET(0, &select_fds);
366 | 
367 |       rv = select(server_fd+1, &select_fds, NULL, NULL, NULL);
368 |       if (rv < 0)
369 | 	{
370 | 	  if (errno == EINTR)
371 | 	    continue;
372 | 	  else
373 | 	    DIE("select");
374 | 	}
375 | 
376 |       if (FD_ISSET(0, &select_fds))
377 | 	{
378 | 	  input_read();
379 | 	  continue;
380 | 	}
381 | 
382 |       if (FD_ISSET(server_fd, &select_fds))
383 | 	{
384 | 	  server_read();
385 | 	  continue;
386 | 	}
387 |     }
