390 | static void
391 | wait_for_write(int fd)
392 | {
393 |   while (1)
394 |     {
395 |       int rv;
396 |       fd_set set;
397 |       FD_ZERO(&set);
398 |       FD_SET(fd, &set);
399 | 
400 |       rv = select(fd+1, NULL, &set, NULL, NULL);
401 |       if (rv < 0)
402 | 	{
403 | 	  if (errno == EINTR)
404 | 	    continue;
405 | 	  else
406 | 	    DIE("select");
407 | 	}
408 | 
409 |       if (FD_ISSET(server_fd, &set))
410 | 	return;
411 |     }
412 | }
