414 | static void
415 | server_send(char *cmd)
416 | {
417 |   int l = strlen(cmd);
418 |   byte *z = alloca(l + 1);
419 | 
420 |   memcpy(z, cmd, l);
421 |   z[l++] = '\n';
422 |   while (l)
423 |     {
424 |       int cnt = write(server_fd, z, l);
425 | 
426 |       if (cnt < 0)
427 | 	{
428 | 	  if (errno == EAGAIN)
429 | 	    wait_for_write(server_fd);
430 | 	  else if (errno == EINTR)
431 | 	    continue;
432 | 	  else
433 | 	    DIE("Server write error");
434 | 	}
435 |       else
436 | 	{
437 | 	  l -= cnt;
438 | 	  z += cnt;
439 | 	}
440 |     }
441 | }
