 68 | static void
 69 | parse_args(int argc, char **argv)
 70 | {
 71 |   int server_changed = 0;
 72 |   int c;
 73 | 
 74 |   while ((c = getopt(argc, argv, opt_list)) >= 0)
 75 |     switch (c)
 76 |       {
