 96 |   if (optind < argc)
 97 |     {
 98 |       char *tmp;
 99 |       int i;
100 |       int len = 0;
101 | 
102 |       for (i = optind; i < argc; i++)
103 | 	len += strlen(argv[i]) + 1;
104 | 
105 |       tmp = init_cmd = malloc(len);
106 |       for (i = optind; i < argc; i++)
107 | 	{
108 | 	  strcpy(tmp, argv[i]);
109 | 	  tmp += strlen(tmp);
110 | 	  *tmp++ = ' ';
111 | 	}
