 65 | 	  for(new=old->son; new; new=new->sibling)
 66 | 	    if (new->len == c-d && !memcmp(new->token, d, c-d))
 67 | 	      break;
 68 | 	  if (!new)
 69 | 	    {
 70 | 	      /* If new keyword is not stored yet */
 71 | 	      int size = sizeof(struct cmd_node) + c-d;
 72 | 	      new = malloc(size);
 73 | 	      bzero(new, size);
 74 | 	      /* Making this keyword child of the previons
 75 | 	       * keyword in the command */
 76 | 	      *old->plastson = new;
 77 | 	      old->plastson = &new->sibling;
 78 | 	      new->plastson = &new->son;
 79 | 	      new->len = c-d;
 80 | 	      memcpy(new->token, d, c-d);
 81 | 	      new->prio = (new->len == 3 && (!memcmp(new->token, "roa", 3) || !memcmp(new->token, "rip", 3))) ? 0 : 1; /* Hack */
 82 | 	    }
 83 | 	  while (isspace_(*c))
 84 | 	    c++;
 85 | 	}
