155 | static void
156 | cmd_list_ambiguous(struct cmd_node *root, char *cmd, int len)
157 | {
158 |   struct cmd_node *m;
159 | 
160 |   for(m=root->son; m; m=m->sibling)
161 |     if (m->len > len && !memcmp(m->token, cmd, len))
162 |       cmd_display_help(m);
163 | }
