128 | static struct cmd_node *
129 | cmd_find_abbrev(struct cmd_node *root, char *cmd, int len, int *pambiguous)
130 | {
131 |   struct cmd_node *m, *best = NULL, *best2 = NULL;
132 | 
133 |   *pambiguous = 0;
134 |   for(m=root->son; m; m=m->sibling)
135 |     {
136 |       if (m->len == len && !memcmp(m->token, cmd, len))
137 | 	return m;
138 |       if (m->len > len && !memcmp(m->token, cmd, len))
139 | 	{
140 | 	  if (best && best->prio > m->prio)
141 | 	    continue;
142 | 	  if (best && best->prio == m->prio)
143 | 	    best2 = best;
144 | 	  best = m;
145 | 	}
146 |     }
147 |   if (best2)
148 |     {
149 |       *pambiguous = 1;
150 |       return NULL;
151 |     }
152 |   return best;
153 | }
