206 | cmd_find_common_match(struct cmd_node *root, char *cmd, int len, int *pcount, char *buf)
207 | {
208 |   struct cmd_node *m;
209 |   int best, best_prio, i;
210 | 
211 |   *pcount = 0;
212 |   best = -1;
213 |   best_prio = -1;
214 |   for(m=root->son; m; m=m->sibling)
215 |     {
216 |       if (m->len < len || memcmp(m->token, cmd, len))
217 | 	continue;
218 | 
219 |       if (best_prio > m->prio)
220 | 	continue;
221 | 
222 |       if (best_prio < m->prio)
223 | 	{
224 | 	  *pcount = 0;
225 | 	  best = -1;
226 | 	}
227 | 
228 |       (*pcount)++;
229 |       if (best < 0)
230 | 	{
231 | 	  strcpy(buf, m->token + len);
232 | 	  best = m->len - len;
233 | 	  best_prio = m->prio;
234 | 	}
235 |       else
236 | 	{
237 | 	  i = 0;
238 | 	  while (i < best && i < m->len - len && buf[i] == m->token[len+i])
239 | 	    i++;
240 | 	  best = i;
241 | 	}
242 |     }
243 |   return best;
244 | }
