319 |   int ambig;
320 | 
321 |   args = c = cmd;
322 |   n = &cmd_root;
323 |   while (*c && !n->final)
324 |     {
325 |       if (isspace_(*c))
326 | 	{
327 | 	  c++;
328 | 	  continue;
329 | 	}
330 |       b = c;
331 |       while (*c && !isspace_(*c))
332 | 	c++;
