 44 | cmd_build_tree(void)
 45 | {
 46 |   uint i;
 47 | 
 48 |   cmd_root.plastson = &cmd_root.son;
 49 | 
 50 |   for(i=0; i<ARRAY_SIZE(command_table); i++)
 51 |     {
 52 |       struct cmd_info *cmd = &command_table[i];
 53 |       struct cmd_node *old, *new;
 54 |       char *c = cmd->command;
 55 | 
 56 |       new = &cmd_root;
 57 |       while (*c)
 58 | 	{
 59 | 	  /* Walk through the keywords in the command from start of the command
 60 | 	   * to its end */
 61 | 	  char *d = c;
 62 | 	  while (*c && !isspace_(*c))
 63 | 	    c++;
 64 | 	  old = new;
 65 | 	  for(new=old->son; new; new=new->sibling)
 66 | 	    if (new->len == c-d && !memcmp(new->token, d, c-d))
 67 | 	      break;
 68 | 	  if (!new)
 69 | 	    {
 70 | 	      /* If new keyword is not stored yet */
 71 | 	      int size = sizeof(struct cmd_node) + c-d;
 72 | 	      new = malloc(size);
 73 | 	      bzero(new, size);
 74 | 	      /* Making this keyword child of the previons
 75 | 	       * keyword in the command */
 76 | 	      *old->plastson = new;
 77 | 	      old->plastson = &new->sibling;
 78 | 	      new->plastson = &new->son;
 79 | 	      new->len = c-d;
 80 | 	      memcpy(new->token, d, c-d);
 81 | 	      new->prio = (new->len == 3 && (!memcmp(new->token, "roa", 3) || !memcmp(new->token, "rip", 3))) ? 0 : 1; /* Hack */
 82 | 	    }
 83 | 	  while (isspace_(*c))
 84 | 	    c++;
 85 | 	}
 86 | 
 87 |       /* In new there is now stored the last keyword in command.
 88 |        * Only this command is going to contain cmd and help */
 89 |       if (cmd->is_real_cmd)
 90 | 	new->cmd = cmd;
 91 |       else
 92 | 	new->help = cmd;
 93 | 
 94 |       if (cmd->is_option)
 95 | 	old->final = 1;
 96 |     }
