source_code:
  1 | /*
  2 |  *	BIRD Client -- Command Handling
  3 |  *
  4 |  *	(c) 1999--2000 Martin Mares <mj@ucw.cz>
  5 |  *
  6 |  *	Can be freely distributed and used under the terms of the GNU GPL.
  7 |  */
  8 | 
  9 | #include <stdio.h>
 10 | #include <stdlib.h>
 11 | #include <ctype.h>
 12 | 
 13 | #include "nest/bird.h"
 14 | #include "lib/resource.h"
 15 | #include "lib/string.h"
 16 | #include "client/client.h"
 17 | 
 18 | struct cmd_info {
 19 |   char *command;
 20 |   char *args;
 21 |   char *help;
 22 |   int is_real_cmd;
 23 |   int is_option;
 24 | };
 25 | 
 26 | static struct cmd_info command_table[] = {
 27 | #include "conf/commands.h"
 28 | };
 29 | 
 30 | struct cmd_node {
 31 |   struct cmd_node *sibling, *son, **plastson;
 32 |   struct cmd_info *cmd, *help;
 33 |   int len;
 34 |   u8 final;
 35 |   s8 prio;
 36 |   char token[1];
 37 | };
 38 | 
 39 | static struct cmd_node cmd_root;
 40 | 
 41 | #define isspace_(X) isspace((unsigned char) (X))
 42 | 
 43 | void
 44 | cmd_build_tree(void)
 45 | {
 46 |   uint i;
 47 | 
 48 |   cmd_root.plastson = &cmd_root.son;
 49 | 
 50 |   for(i=0; i<ARRAY_SIZE(command_table); i++)
 51 |     {
 52 |       struct cmd_info *cmd = &command_table[i];
 53 |       struct cmd_node *old, *new;
 54 |       char *c = cmd->command;
 55 | 
 56 |       new = &cmd_root;
 57 |       while (*c)
 58 | 	{
 59 | 	  /* Walk through the keywords in the command from start of the command
 60 | 	   * to its end */
 61 | 	  char *d = c;
 62 | 	  while (*c && !isspace_(*c))
 63 | 	    c++;
 64 | 	  old = new;
 65 | 	  for(new=old->son; new; new=new->sibling)
 66 | 	    if (new->len == c-d && !memcmp(new->token, d, c-d))
 67 | 	      break;
 68 | 	  if (!new)
 69 | 	    {
 70 | 	      /* If new keyword is not stored yet */
 71 | 	      int size = sizeof(struct cmd_node) + c-d;
 72 | 	      new = malloc(size);
 73 | 	      bzero(new, size);
 74 | 	      /* Making this keyword child of the previons
 75 | 	       * keyword in the command */
 76 | 	      *old->plastson = new;
 77 | 	      old->plastson = &new->sibling;
 78 | 	      new->plastson = &new->son;
 79 | 	      new->len = c-d;
 80 | 	      memcpy(new->token, d, c-d);
 81 | 	      new->prio = (new->len == 3 && (!memcmp(new->token, "roa", 3) || !memcmp(new->token, "rip", 3))) ? 0 : 1; /* Hack */
 82 | 	    }
 83 | 	  while (isspace_(*c))
 84 | 	    c++;
 85 | 	}
 86 | 
 87 |       /* In new there is now stored the last keyword in command.
 88 |        * Only this command is going to contain cmd and help */
 89 |       if (cmd->is_real_cmd)
 90 | 	new->cmd = cmd;
 91 |       else
 92 | 	new->help = cmd;
 93 | 
 94 |       if (cmd->is_option)
 95 | 	old->final = 1;
 96 |     }
 97 | }
 98 | 
 99 | static void
100 | cmd_do_display_help(struct cmd_info *c)
101 | {
102 |   char buf[strlen(c->command) + strlen(c->args) + 4];
103 | 
104 |   sprintf(buf, "%s %s", c->command, c->args);
105 |   printf("%-45s  %s\n", buf, c->help);
106 | }
107 | 
108 | static void
109 | cmd_display_help(struct cmd_node *m)
110 | {
111 |   /* Go through children of the base keyword. Each keyword has its own node. */
112 |   for (struct cmd_node *mm = m->son; mm; mm = mm->sibling)
113 |   {
114 |     /* Print hints for all of the children of given keyword. */
115 |     if (mm->help)
116 |       cmd_do_display_help(mm->help);
117 |     else if (mm->cmd)
118 |       cmd_do_display_help(mm->cmd);
119 |     else
120 |     {
121 |       /* This child does not contain hint, let's try its children instead
122 |        * (this child might be first part of multi keyword command) */
123 |       cmd_display_help(mm);
124 |     }
125 |   }
126 | }
127 | 
128 | static struct cmd_node *
129 | cmd_find_abbrev(struct cmd_node *root, char *cmd, int len, int *pambiguous)
130 | {
131 |   struct cmd_node *m, *best = NULL, *best2 = NULL;
132 | 
133 |   *pambiguous = 0;
134 |   for(m=root->son; m; m=m->sibling)
135 |     {
136 |       if (m->len == len && !memcmp(m->token, cmd, len))
137 | 	return m;
138 |       if (m->len > len && !memcmp(m->token, cmd, len))
139 | 	{
140 | 	  if (best && best->prio > m->prio)
141 | 	    continue;
142 | 	  if (best && best->prio == m->prio)
143 | 	    best2 = best;
144 | 	  best = m;
145 | 	}
146 |     }
147 |   if (best2)
148 |     {
149 |       *pambiguous = 1;
150 |       return NULL;
151 |     }
152 |   return best;
153 | }
154 | 
155 | static void
156 | cmd_list_ambiguous(struct cmd_node *root, char *cmd, int len)
157 | {
158 |   struct cmd_node *m;
159 | 
160 |   for(m=root->son; m; m=m->sibling)
161 |     if (m->len > len && !memcmp(m->token, cmd, len))
162 |       cmd_display_help(m);
163 | }
164 | 
165 | void
166 | cmd_help(char *cmd, int len)
167 | {
168 |   char *end = cmd + len;
169 |   struct cmd_node *n, *m;
170 |   char *z;
171 |   int ambig;
172 | 
173 |   n = &cmd_root;
174 |   while (cmd < end && !n->final)
175 |     {
176 |       if (isspace_(*cmd))
177 | 	{
178 | 	  cmd++;
179 | 	  continue;
180 | 	}
181 |       z = cmd;
182 |       while (cmd < end && !isspace_(*cmd))
183 | 	cmd++;
184 |       m = cmd_find_abbrev(n, z, cmd-z, &ambig);
185 |       if (ambig)
186 | 	{
187 | 	  cmd_list_ambiguous(n, z, cmd-z);
188 | 	  return;
189 | 	}
190 |       if (!m)
191 | 	break;
192 |       n = m;
193 |     }
194 | 
195 |   if (n && n->cmd)
196 |     cmd_do_display_help(n->cmd);
197 | 
198 |   /* Currently no help for options */
199 |   if (n->final)
200 |     return;
201 | 
202 |   cmd_display_help(n);
203 | }
204 | 
205 | static int
206 | cmd_find_common_match(struct cmd_node *root, char *cmd, int len, int *pcount, char *buf)
207 | {
208 |   struct cmd_node *m;
209 |   int best, best_prio, i;
210 | 
211 |   *pcount = 0;
212 |   best = -1;
213 |   best_prio = -1;
214 |   for(m=root->son; m; m=m->sibling)
215 |     {
216 |       if (m->len < len || memcmp(m->token, cmd, len))
217 | 	continue;
218 | 
219 |       if (best_prio > m->prio)
220 | 	continue;
221 | 
222 |       if (best_prio < m->prio)
223 | 	{
224 | 	  *pcount = 0;
225 | 	  best = -1;
226 | 	}
227 | 
228 |       (*pcount)++;
229 |       if (best < 0)
230 | 	{
231 | 	  strcpy(buf, m->token + len);
232 | 	  best = m->len - len;
233 | 	  best_prio = m->prio;
234 | 	}
235 |       else
236 | 	{
237 | 	  i = 0;
238 | 	  while (i < best && i < m->len - len && buf[i] == m->token[len+i])
239 | 	    i++;
240 | 	  best = i;
241 | 	}
242 |     }
243 |   return best;
244 | }
245 | 
246 | int
247 | cmd_complete(char *cmd, int len, char *buf, int again)
248 | {
249 |   char *start = cmd;
250 |   char *end = cmd + len;
251 |   char *fin;
252 |   struct cmd_node *n, *m;
253 |   char *z;
254 |   int ambig, cnt = 0, common;
255 | 
256 |   /* Find the last word we want to complete */
257 |   for(fin=end; fin > start && !isspace_(fin[-1]); fin--)
258 |     ;
259 | 
260 |   /* Find the context */
261 |   n = &cmd_root;
262 |   while (cmd < fin && n->son && !n->final)
263 |     {
264 |       if (isspace_(*cmd))
265 | 	{
266 | 	  cmd++;
267 | 	  continue;
268 | 	}
269 |       z = cmd;
270 |       while (cmd < fin && !isspace_(*cmd))
271 | 	cmd++;
272 |       m = cmd_find_abbrev(n, z, cmd-z, &ambig);
273 |       if (ambig)
274 | 	{
275 | 	  if (!again)
276 | 	    return -1;
277 | 	  input_start_list();
278 | 	  cmd_list_ambiguous(n, z, cmd-z);
279 | 	  input_stop_list();
280 | 	  return 0;
281 | 	}
282 |       if (!m)
283 | 	return -1;
284 |       n = m;
285 |     }
286 | 
287 |   /* Completion of parameters is not yet supported */
288 |   if (!n->son)
289 |     return -1;
290 | 
291 |   /* We know the context, let's try to complete */
292 |   common = cmd_find_common_match(n, fin, end-fin, &cnt, buf);
293 |   if (!cnt)
294 |     return -1;
295 |   if (cnt == 1)
296 |     {
297 |       buf[common++] = ' ';
298 |       buf[common] = 0;
299 |       return 1;
300 |     }
301 |   if (common > 0)
302 |     {
303 |       buf[common] = 0;
304 |       return 1;
305 |     }
306 |   if (!again)
307 |     return -1;
308 |   input_start_list();
309 |   cmd_list_ambiguous(n, fin, end-fin);
310 |   input_stop_list();
311 |   return 0;
312 | }
313 | 
314 | char *
315 | cmd_expand(char *cmd)
316 | {
317 |   struct cmd_node *n, *m;
318 |   char *c, *b, *args;
319 |   int ambig;
320 | 
321 |   args = c = cmd;
322 |   n = &cmd_root;
323 |   while (*c && !n->final)
324 |     {
325 |       if (isspace_(*c))
326 | 	{
327 | 	  c++;
328 | 	  continue;
329 | 	}
330 |       b = c;
331 |       while (*c && !isspace_(*c))
332 | 	c++;
333 |       m = cmd_find_abbrev(n, b, c-b, &ambig);
334 |       if (!m)
335 | 	{
336 | 	  if (!ambig)
337 | 	    break;
338 | 	  puts("Ambiguous command, possible expansions are:");
339 | 	  cmd_list_ambiguous(n, b, c-b);
340 | 	  return NULL;
341 | 	}
342 |       args = c;
343 |       n = m;
344 |     }
345 |   if (!n->cmd)
346 |     {
347 |       puts("No such command. Press `?' for help.");
348 |       return NULL;
349 |     }
350 |   b = malloc(strlen(n->cmd->command) + strlen(args) + 1);
351 |   sprintf(b, "%s%s", n->cmd->command, args);
352 |   return b;
353 | }

