 62 | static jmp_buf conf_jmpbuf;
 63 | 
 64 | struct config *config, *new_config;
 65 | pool *config_pool;
 66 | 
 67 | static struct config *old_config;	/* Old configuration */
 68 | static struct config *future_config;	/* New config held here if recon requested during recon */
 69 | static int old_cftype;			/* Type of transition old_config -> config (RECONFIG_SOFT/HARD) */
 70 | static int future_cftype;		/* Type of scheduled transition, may also be RECONFIG_UNDO */
 71 | /* Note that when future_cftype is RECONFIG_UNDO, then future_config is NULL,
 72 |    therefore proper check for future scheduled config checks future_cftype */
 73 | 
 74 | static event *config_event;		/* Event for finalizing reconfiguration */
 75 | static timer *config_timer;		/* Timer for scheduled configuration rollback */
 76 | 
 77 | /* These are public just for cmd_show_status(), should not be accessed elsewhere */
 78 | int shutting_down;			/* Shutdown requested, do not accept new config changes */
 79 | int configuring;			/* Reconfiguration is running */
 80 | int undo_available;			/* Undo was not requested from last reconfiguration */
 81 | /* Note that both shutting_down and undo_available are related to requests, not processing */
 82 | 
 83 | /**
 84 |  * config_alloc - allocate a new configuration
 85 |  * @name: name of the config
 86 |  *
 87 |  * This function creates new &config structure, attaches a resource
 88 |  * pool and a linear memory pool to it and makes it available for
 89 |  * further use. Returns a pointer to the structure.
 90 |  */
 91 | struct config *
 92 | config_alloc(const char *name)
 93 | {
 94 |   pool *p = rp_new(config_pool, "Config");
 95 |   linpool *l = lp_new_default(p);
 96 |   struct config *c = lp_allocz(l, sizeof(struct config));
 97 | 
 98 |   /* Duplication of name string in local linear pool */
 99 |   uint nlen = strlen(name) + 1;
100 |   char *ndup = lp_allocu(l, nlen);
101 |   memcpy(ndup, name, nlen);
102 | 
103 |   init_list(&c->tests);
104 |   init_list(&c->symbols);
105 |   c->mrtdump_file = -1; /* Hack, this should be sysdep-specific */
106 |   c->pool = p;
107 |   c->mem = l;
108 |   c->file_name = ndup;
109 |   c->load_time = current_time();
110 |   c->tf_route = c->tf_proto = TM_ISO_SHORT_MS;
111 |   c->tf_base = c->tf_log = TM_ISO_LONG_MS;
112 |   c->gr_wait = DEFAULT_GR_WAIT;
113 | 
114 |   return c;
115 | }
116 | 
117 | /**
118 |  * config_parse - parse a configuration
119 |  * @c: configuration
120 |  *
121 |  * config_parse() reads input by calling a hook function pointed to
122 |  * by @cf_read_hook and parses it according to the configuration
123 |  * grammar. It also calls all the preconfig and postconfig hooks
124 |  * before, resp. after parsing.
125 |  *
126 |  * Result: 1 if the config has been parsed successfully, 0 if any
127 |  * error has occurred (such as anybody calling cf_error()) and
128 |  * the @err_msg field has been set to the error message.
129 |  */
130 | int
131 | config_parse(struct config *c)
132 | {
133 |   int done = 0;
134 |   DBG("Parsing configuration file `%s'\n", c->file_name);
135 |   new_config = c;
136 |   cfg_mem = c->mem;
137 |   if (setjmp(conf_jmpbuf))
138 |     goto cleanup;
139 | 
140 |   cf_lex_init(0, c);
141 |   sysdep_preconfig(c);
142 |   protos_preconfig(c);
143 |   mpls_preconfig(c);
144 |   rt_preconfig(c);
145 |   cf_parse();
146 |   rt_postconfig(c);
147 | 
148 |   if (EMPTY_LIST(c->protos))
149 |     cf_error("No protocol is specified in the config file");
150 | 
151 |   /*
152 |   if (!c->router_id)
153 |     cf_error("Router ID must be configured manually");
154 |   */
155 | 
156 |   done = 1;
157 | 
158 | cleanup:
159 |   new_config = NULL;
160 |   cfg_mem = NULL;
161 |   return done;
162 | }
163 | 
164 | /**
165 |  * cli_parse - parse a CLI command
166 |  * @c: temporary config structure
167 |  *
168 |  * cli_parse() is similar to config_parse(), but instead of a configuration,
169 |  * it parses a CLI command. See the CLI module for more information.
170 |  */
171 | int
172 | cli_parse(struct config *c)
173 | {
174 |   int done = 0;
175 |   new_config = c;
176 |   cfg_mem = c->mem;
177 |   if (setjmp(conf_jmpbuf))
178 |     goto cleanup;
179 | 
180 |   cf_lex_init(1, c);
181 |   cf_parse();
182 |   done = 1;
183 | 
184 | cleanup:
185 |   new_config = NULL;
186 |   cfg_mem = NULL;
187 |   return done;
188 | }
