530 | /**
531 |  * order_shutdown - order BIRD shutdown
532 |  *
533 |  * This function initiates shutdown of BIRD. It's accomplished by asking
534 |  * for switching to an empty configuration.
535 |  */
536 | void
537 | order_shutdown(int gr)
538 | {
539 |   struct config *c;
540 | 
541 |   if (shutting_down)
542 |     return;
543 | 
544 |   if (!gr)
545 |     log(L_INFO "Shutting down");
546 |   else
547 |     log(L_INFO "Shutting down for graceful restart");
548 | 
549 |   c = lp_alloc(config->mem, sizeof(struct config));
550 |   memcpy(c, config, sizeof(struct config));
551 |   init_list(&c->protos);
552 |   init_list(&c->tables);
553 |   init_list(&c->mpls_domains);
554 |   init_list(&c->symbols);
555 |   c->cli = (struct cli_config_list) {};
556 |   memset(c->def_tables, 0, sizeof(c->def_tables));
557 |   c->shutdown = 1;
558 |   c->gr_down = gr;
559 | 
560 |   config_commit(c, RECONFIG_HARD, 0);
561 |   shutting_down = 1;
562 | }
563 | 
564 | /**
565 |  * cf_error - report a configuration error
566 |  * @msg: printf-like format string
567 |  *
568 |  * cf_error() can be called during execution of config_parse(), that is
569 |  * from the parser, a preconfig hook or a postconfig hook, to report an
570 |  * error in the configuration.
571 |  */
572 | void
573 | cf_error(const char *msg, ...)
574 | {
575 |   char buf[1024];
576 |   va_list args;
577 | 
578 |   va_start(args, msg);
579 |   if (bvsnprintf(buf, sizeof(buf), msg, args) < 0)
580 |     strcpy(buf, "<bug: error message too long>");
581 |   va_end(args);
582 |   new_config->err_msg = cfg_strdup(buf);
583 |   new_config->err_lino = ifs->lino;
584 |   new_config->err_chno = ifs->chno - ifs->toklen + 1;
585 |   new_config->err_file_name = ifs->file_name;
586 |   cf_lex_unwind();
587 |   longjmp(conf_jmpbuf, 1);
588 | }
