 67 | static struct config *old_config;	/* Old configuration */
 68 | static struct config *future_config;	/* New config held here if recon requested during recon */
 69 | static int old_cftype;			/* Type of transition old_config -> config (RECONFIG_SOFT/HARD) */
 70 | static int future_cftype;		/* Type of scheduled transition, may also be RECONFIG_UNDO */
 71 | /* Note that when future_cftype is RECONFIG_UNDO, then future_config is NULL,
 72 |    therefore proper check for future scheduled config checks future_cftype */
 73 | 
