505 | extern void cmd_reconfig_undo_notify(void);
506 | 
507 | static void
508 | config_timeout(timer *t UNUSED)
509 | {
510 |   log(L_INFO "Config timeout expired, starting undo");
511 |   cmd_reconfig_undo_notify();
512 | 
