117 | /**
118 |  * config_parse - parse a configuration
119 |  * @c: configuration
120 |  *
121 |  * config_parse() reads input by calling a hook function pointed to
122 |  * by @cf_read_hook and parses it according to the configuration
123 |  * grammar. It also calls all the preconfig and postconfig hooks
124 |  * before, resp. after parsing.
125 |  *
126 |  * Result: 1 if the config has been parsed successfully, 0 if any
127 |  * error has occurred (such as anybody calling cf_error()) and
128 |  * the @err_msg field has been set to the error message.
129 |  */
130 | int
131 | config_parse(struct config *c)
132 | {
133 |   int done = 0;
134 |   DBG("Parsing configuration file `%s'\n", c->file_name);
135 |   new_config = c;
136 |   cfg_mem = c->mem;
137 |   if (setjmp(conf_jmpbuf))
138 |     goto cleanup;
139 | 
140 |   cf_lex_init(0, c);
141 |   sysdep_preconfig(c);
142 |   protos_preconfig(c);
143 |   mpls_preconfig(c);
144 |   rt_preconfig(c);
145 |   cf_parse();
146 |   rt_postconfig(c);
147 | 
148 |   if (EMPTY_LIST(c->protos))
149 |     cf_error("No protocol is specified in the config file");
150 | 
151 |   /*
152 |   if (!c->router_id)
153 |     cf_error("Router ID must be configured manually");
154 |   */
155 | 
156 |   done = 1;
157 | 
158 | cleanup:
159 |   new_config = NULL;
160 |   cfg_mem = NULL;
161 |   return done;
162 | }
