564 | /**
565 |  * cf_error - report a configuration error
566 |  * @msg: printf-like format string
567 |  *
568 |  * cf_error() can be called during execution of config_parse(), that is
569 |  * from the parser, a preconfig hook or a postconfig hook, to report an
570 |  * error in the configuration.
571 |  */
572 | void
573 | cf_error(const char *msg, ...)
574 | {
575 |   char buf[1024];
576 |   va_list args;
577 | 
578 |   va_start(args, msg);
579 |   if (bvsnprintf(buf, sizeof(buf), msg, args) < 0)
580 |     strcpy(buf, "<bug: error message too long>");
