276 | static int
277 | config_do_commit(struct config *c, int type)
278 | {
279 |   if (type == RECONFIG_UNDO)
280 |     {
281 |       c = old_config;
282 |       type = old_cftype;
283 |     }
284 |   else
285 |     config_free(old_config);
286 | 
287 |   old_config = config;
288 |   old_cftype = type;
289 |   config = c;
290 | 
291 |   configuring = 1;
292 |   if (old_config && !config->shutdown)
293 |     log(L_INFO "Reconfiguring");
294 | 
295 |   if (old_config)
296 |     old_config->obstacle_count++;
297 | 
298 |   DBG("filter_commit\n");
299 |   filter_commit(c, old_config);
300 |   DBG("sysdep_commit\n");
301 |   int force_restart = sysdep_commit(c, old_config);
302 |   DBG("global_commit\n");
303 |   force_restart |= global_commit(c, old_config);
304 |   mpls_commit(c, old_config);
305 |   DBG("rt_commit\n");
306 |   rt_commit(c, old_config);
307 |   DBG("protos_commit\n");
308 |   protos_commit(c, old_config, force_restart, type);
309 | 
310 |   int obs = 0;
311 |   if (old_config)
312 |     obs = --old_config->obstacle_count;
313 | 
314 |   DBG("do_commit finished with %d obstacles remaining\n", obs);
315 |   return !obs;
316 | }
