556 |   memset(c->def_tables, 0, sizeof(c->def_tables));
557 |   c->shutdown = 1;
558 |   c->gr_down = gr;
559 | 
560 |   config_commit(c, RECONFIG_HARD, 0);
561 |   shutting_down = 1;
562 | }
