229 | void
230 | config_add_obstacle(struct config *c)
231 | {
232 |   DBG("+++ adding obstacle %d\n", c->obstacle_count);
233 |   c->obstacle_count++;
234 | }
235 | 
236 | void
237 | config_del_obstacle(struct config *c)
238 | {
239 |   DBG("+++ deleting obstacle %d\n", c->obstacle_count);
240 |   c->obstacle_count--;
241 |   if (!c->obstacle_count && (c != config))
242 |     ev_schedule(config_event);
243 | }
