615 |   WALK_LIST(sn, *src)
616 |   {
617 |     dn = cfg_alloc(node_size);
618 |     memcpy(dn, sn, node_size);
619 |     memset(dn, 0, sizeof(node));
620 |     add_tail(dest, dn);
621 |   }
622 | }

