193 | {
194 | #define AX(...)  do { struct f_inst *_tmp = f_new_inst(__VA_ARGS__); _tmp->next = output; output = _tmp; } while (0)
195 |   struct f_inst *output = NULL;
196 |   if (fret != F_NOP)
197 |     AX(FI_DIE, fret);
