202 |   while (vars)
203 |   {
204 |     struct f_inst *tmp = vars;
205 |     vars = vars->next;
206 |     tmp->next = NULL;
207 | 
208 |     AX(FI_PRINT, tmp);
209 |   }
210 | 
211 |   return output;
212 | #undef AX
