 61 | static struct f_tree *
 62 | build_tree_rec(struct f_tree **buf, int l, int h)
 63 | {
 64 |   struct f_tree *n;
 65 |   int pos;
 66 | 
 67 |   if (l >= h)
 68 |     return NULL;
 69 | 
 70 |   pos = (l+h)/2;
 71 |   n = buf[pos];
 72 |   n->left = build_tree_rec(buf, l, pos);
 73 |   n->right = build_tree_rec(buf, pos+1, h);
 74 |   return n;
 75 | }
 76 | 
 77 | static int 
 78 | tree_compare(const void *p1, const void *p2)
 79 | {
 80 |   return val_compare(&((* (struct f_tree **) p1)->from), &((* (struct f_tree **) p2)->from));
 81 | }
 82 | 
 83 | /**
 84 |  * build_tree
 85 |  * @from: degenerated tree (linked by @tree->left) to be transformed into form suitable for find_tree()
 86 |  *
 87 |  * Transforms degenerated tree into balanced tree.
 88 |  */
 89 | struct f_tree *
 90 | build_tree(struct f_tree *from)
 91 | {
 92 |   struct f_tree *tmp, *root;
 93 |   struct f_tree **buf;
 94 |   int len, i;
 95 | 
 96 |   if (from == NULL)
 97 |     return NULL;
 98 | 
 99 |   len = 0;
100 |   for (tmp = from; tmp != NULL; tmp = tmp->left)
101 |     len++;
102 | 
103 |   if (len <= 1024)
104 |     buf = alloca(len * sizeof(struct f_tree *));
105 |   else
106 |     buf = xmalloc(len * sizeof(struct f_tree *));
107 | 
108 |   /* Convert a degenerated tree into an sorted array */
109 |   i = 0;
110 |   for (tmp = from; tmp != NULL; tmp = tmp->left)
111 |     buf[i++] = tmp;
112 | 
113 |   qsort(buf, len, sizeof(struct f_tree *), tree_compare);
114 | 
115 |   root = build_tree_rec(buf, 0, len);
116 | 
117 |   if (len > 1024)
118 |     xfree(buf);
119 | 
120 |   return root;
121 | }
