135 |  * Compares two trees and returns 1 if they are same
136 |  */
137 | int
138 | same_tree(const struct f_tree *t1, const struct f_tree *t2)
139 | {
140 |   if ((!!t1) != (!!t2))
141 |     return 0;
142 |   if (!t1)
143 |     return 1;
144 |   if (val_compare(&(t1->from), &(t2->from)))
145 |     return 0;
146 |   if (val_compare(&(t1->to), &(t2->to)))
147 |     return 0;
148 |   if (!same_tree(t1->left, t2->left))
149 |     return 0;
150 |   if (!same_tree(t1->right, t2->right))
151 |     return 0;
152 |   if (!f_same(t1->data, t2->data))
153 |     return 0;
154 |   return 1;
155 | }
