1133 |  * @buf: destination buffer
1134 |  *
1135 |  * Prints the trie to the supplied buffer.
1136 |  */
1137 | void
1138 | trie_format(const struct f_trie *t, buffer *buf)
1139 | {
1140 |   buffer_puts(buf, "[");
1141 | 
1142 |   if (t->zero)
1143 |     buffer_print(buf, "%I/%d, ", t->ipv4 ? IPA_NONE4 : IPA_NONE6, 0);
