1145 |   trie_node_format(&t->root, buf, t->ipv4);
1146 | 
1147 |   if (buf->pos == buf->end)
1148 |     return;
1149 | 
1150 |   /* Undo last separator */
1151 |   if (buf->pos[-1] != '[')
1152 |     buf->pos -= 2;
1153 | 
1154 |   buffer_puts(buf, "]");
1155 | }

