1007 |     return 1;
1008 | 
1009 |   if ((t1 == NULL) || (t2 == NULL))
1010 |     return 0;
1011 | 
1012 |   if ((t1->plen != t2->plen) ||
1013 |       (! ip4_equal(t1->addr, t2->addr)) ||
1014 |       (! ip4_equal(t1->accept, t2->accept)))
1015 |     return 0;
1016 | 
1017 |   for (uint i = 0; i < (1 << TRIE_STEP); i++)
1018 |     if (! trie_node_same4(t1->c[i], t2->c[i]))
1019 |       return 0;
1020 | 
1021 |   return 1;
