 199 | static inline void
 200 | attach_node(struct f_trie_node *parent, struct f_trie_node *child, int v4)
 201 | {
 202 |   if (v4)
 203 |     attach_node4(&parent->v4, &child->v4);
 204 |   else
 205 |     attach_node6(&parent->v6, &child->v6);
 206 | }
