 94 | int
 95 | rd_format(const vpn_rd rd_, char *buf, int buflen)
 96 | {
 97 |   u64 rd = rd_to_u64(rd_);
 98 | 
 99 |   switch (rd >> 48)
100 |   {
101 |     case 0: return bsnprintf(buf, buflen, "%u:%u", (u32) (rd >> 32), (u32) rd);
102 |     case 1: return bsnprintf(buf, buflen, "%I4:%u", ip4_from_u32(rd >> 16), (u32) (rd & 0xffff));
103 |     case 2: if (((u32) (rd >> 16)) >> 16)
104 | 	      return bsnprintf(buf, buflen, "%u:%u", (u32) (rd >> 16), (u32) (rd & 0xffff));
105 | 	    else
106 | 	      return bsnprintf(buf, buflen, "2:%u:%u", (u32) (rd >> 16), (u32) (rd & 0xffff));
107 |     default: return bsnprintf(buf, buflen, "X:%08x:%08x", (u32) (rd >> 32), (u32) rd);
108 |   }
109 | }
