111 | int
112 | net_format(const net_addr *N, char *buf, int buflen)
113 | {
114 |   net_addr_union *n = (void *) N;
115 |   buf[0] = 0;
116 | 
117 |   switch (n->n.type)
118 |   {
119 |   case NET_IP4:
120 |     return (buflen < IP4_PX_BUFFER_SIZE) ? -1 : ip4_px_ntop(n->ip4.prefix, n->ip4.pxlen, buf) - buf;
121 |   case NET_IP6:
122 |     return bsnprintf(buf, buflen, "%I6/%d", n->ip6.prefix, n->ip6.pxlen);
123 |   case NET_VPN4:
124 |     {
125 |     int c = rd_format(n->vpn4.rd, buf, buflen);
126 |     ADVANCE(buf, buflen, c);
127 |     return bsnprintf(buf, buflen, " %I4/%d", n->vpn4.prefix, n->vpn4.pxlen);
128 |     }
129 |   case NET_VPN6:
130 |     {
131 |     /* XXX: RD format is specified for VPN4; not found any for VPN6, reusing the same as for VPN4 */
132 |     int c = rd_format(n->vpn6.rd, buf, buflen);
133 |     ADVANCE(buf, buflen, c);
134 |     return bsnprintf(buf, buflen, " %I6/%d", n->vpn6.prefix, n->vpn6.pxlen);
135 |     }
136 |   case NET_ROA4:
137 |     return bsnprintf(buf, buflen, "%I4/%u-%u AS%u",  n->roa4.prefix, n->roa4.pxlen, n->roa4.max_pxlen, n->roa4.asn);
138 |   case NET_ROA6:
139 |     return bsnprintf(buf, buflen, "%I6/%u-%u AS%u",  n->roa6.prefix, n->roa6.pxlen, n->roa6.max_pxlen, n->roa6.asn);
140 |   case NET_FLOW4:
141 |     return flow4_net_format(buf, buflen, &n->flow4);
142 |   case NET_FLOW6:
143 |     return flow6_net_format(buf, buflen, &n->flow6);
144 |   case NET_IP6_SADR:
145 |     return bsnprintf(buf, buflen, "%I6/%d from %I6/%d", n->ip6_sadr.dst_prefix, n->ip6_sadr.dst_pxlen, n->ip6_sadr.src_prefix, n->ip6_sadr.src_pxlen);
146 |   case NET_MPLS:
147 |     return bsnprintf(buf, buflen, "%u", n->mpls.label);
148 |   case NET_ASPA:
149 |     return bsnprintf(buf, buflen, "%u", n->aspa.asn);
150 |   }
151 | 
152 |   bug("unknown network type");
153 | }
