182 | {
183 |   if (a->type != b->type)
184 |     return uint_cmp(a->type, b->type);
185 | 
186 |   switch (a->type)
187 |   {
188 |   case NET_IP4:
189 |     return net_compare_ip4((const net_addr_ip4 *) a, (const net_addr_ip4 *) b);
190 |   case NET_IP6:
191 |     return net_compare_ip6((const net_addr_ip6 *) a, (const net_addr_ip6 *) b);
192 |   case NET_VPN4:
193 |     return net_compare_vpn4((const net_addr_vpn4 *) a, (const net_addr_vpn4 *) b);
194 |   case NET_VPN6:
195 |     return net_compare_vpn6((const net_addr_vpn6 *) a, (const net_addr_vpn6 *) b);
196 |   case NET_ROA4:
197 |     return net_compare_roa4((const net_addr_roa4 *) a, (const net_addr_roa4 *) b);
198 |   case NET_ROA6:
199 |     return net_compare_roa6((const net_addr_roa6 *) a, (const net_addr_roa6 *) b);
200 |   case NET_FLOW4:
201 |     return net_compare_flow4((const net_addr_flow4 *) a, (const net_addr_flow4 *) b);
202 |   case NET_FLOW6:
203 |     return net_compare_flow6((const net_addr_flow6 *) a, (const net_addr_flow6 *) b);
204 |   case NET_IP6_SADR:
205 |     return net_compare_ip6_sadr((const net_addr_ip6_sadr *) a, (const net_addr_ip6_sadr *) b);
