288 | net_classify(const net_addr *N)
289 | {
290 |   net_addr_union *n = (void *) N;
291 | 
292 |   switch (n->n.type)
293 |   {
294 |   case NET_IP4:
295 |   case NET_VPN4:
296 |   case NET_ROA4:
297 |   case NET_FLOW4:
298 |     return ip4_zero(n->ip4.prefix) ? (IADDR_HOST | SCOPE_UNIVERSE) : ip4_classify(n->ip4.prefix);
299 | 
300 |   case NET_IP6:
301 |   case NET_VPN6:
302 |   case NET_ROA6:
303 |   case NET_FLOW6:
304 |     return ip6_zero(n->ip6.prefix) ? (IADDR_HOST | SCOPE_UNIVERSE) : ip6_classify(&n->ip6.prefix);
305 | 
306 |   case NET_IP6_SADR:
307 |     return ip6_zero(n->ip6_sadr.dst_prefix) ? (IADDR_HOST | SCOPE_UNIVERSE) : ip6_classify(&n->ip6_sadr.dst_prefix);
308 | 
309 |   case NET_MPLS:
310 |   case NET_ASPA:
311 |     return IADDR_HOST | SCOPE_UNIVERSE;
312 |   }
313 | 
314 |   return IADDR_INVALID;
