317 | int
318 | ipa_in_netX(const ip_addr a, const net_addr *n)
319 | {
320 |   switch (n->type)
321 |   {
322 |   case NET_IP4:
323 |   case NET_VPN4:
324 |   case NET_ROA4:
325 |   case NET_FLOW4:
326 |     if (!ipa_is_ip4(a)) return 0;
327 |     return ip4_zero(ip4_and(ip4_xor(ipa_to_ip4(a), net4_prefix(n)),
328 | 			    ip4_mkmask(net4_pxlen(n))));
329 | 
330 |   case NET_IP6:
331 |   case NET_VPN6:
332 |   case NET_ROA6:
333 |   case NET_FLOW6:
334 |     if (ipa_is_ip4(a)) return 0;
335 |     return ip6_zero(ip6_and(ip6_xor(ipa_to_ip6(a), net6_prefix(n)),
336 | 			    ip6_mkmask(net6_pxlen(n))));
337 | 
338 |   case NET_IP6_SADR:
339 |     if (ipa_is_ip4(a)) return 0;
340 |     return ip6_zero(ip6_and(ip6_xor(ipa_to_ip6(a), net6_prefix(n)),
341 | 			    ip6_mkmask(net6_pxlen(n))));
342 | 
343 |   case NET_MPLS:
344 |   case NET_ASPA:
345 |   default:
346 |     return 0;
347 |   }
348 | }
349 | 
350 | int
351 | net_in_netX(const net_addr *a, const net_addr *n)
352 | {
353 |   if (a->type != n->type)
354 |     return 0;
355 | 
356 |   return (net_pxlen(n) <= net_pxlen(a)) && ipa_in_netX(net_prefix(a), n);
357 | }

