111 | int
112 | net_format(const net_addr *N, char *buf, int buflen)
113 | {
114 |   net_addr_union *n = (void *) N;
115 |   buf[0] = 0;
116 | 
117 |   switch (n->n.type)
118 |   {
119 |   case NET_IP4:
120 |     return (buflen < IP4_PX_BUFFER_SIZE) ? -1 : ip4_px_ntop(n->ip4.prefix, n->ip4.pxlen, buf) - buf;
121 |   case NET_IP6:
122 |     return bsnprintf(buf, buflen, "%I6/%d", n->ip6.prefix, n->ip6.pxlen);
123 |   case NET_VPN4:
124 |     {
125 |     int c = rd_format(n->vpn4.rd, buf, buflen);
126 |     ADVANCE(buf, buflen, c);
127 |     return bsnprintf(buf, buflen, " %I4/%d", n->vpn4.prefix, n->vpn4.pxlen);
128 |     }
129 |   case NET_VPN6:
130 |     {
