132 |     int c = rd_format(n->vpn6.rd, buf, buflen);
133 |     ADVANCE(buf, buflen, c);
134 |     return bsnprintf(buf, buflen, " %I6/%d", n->vpn6.prefix, n->vpn6.pxlen);
135 |     }
