284 | 
285 | /**
286 |  * resource_init - initialize the resource manager
287 |  *
288 |  * This function is called during BIRD startup. It initializes
289 |  * all data structures of the resource manager and creates the
290 |  * root pool.
291 |  */
292 | void
293 | resource_init(void)
294 | {
295 |   resource_sys_init();
296 | 
297 |   root_pool.r.class = &pool_class;
298 |   root_pool.name = "Root";
299 |   init_list(&root_pool.inside);
300 |   tmp_init(&root_pool);
301 | }
302 | 
303 | /**
304 |  * DOC: Memory blocks
305 |  *
306 |  * Memory blocks are pieces of contiguous allocated memory.
307 |  * They are a bit non-standard since they are represented not by a pointer
308 |  * to &resource, but by a void pointer to the start of data of the
309 |  * memory block. All memory block functions know how to locate the header
310 |  * given the data pointer.
311 |  *
312 |  * Example: All "unique" data structures such as hash tables are allocated
313 |  * as memory blocks.
314 |  */
315 | 
316 | struct mblock {
317 |   resource r;
318 |   unsigned size;
319 |   max_align_t data_align[0];
320 |   byte data[0];
321 | };
322 | 
323 | static void mbl_free(resource *r UNUSED)
324 | {
325 | }
326 | 
327 | static void mbl_debug(struct dump_request *dreq, resource *r)
328 | {
329 |   struct mblock *m = (struct mblock *) r;
330 | 
331 |   RDUMP("(size=%d)\n", m->size);
332 | }
333 | 
334 | static resource *
335 | mbl_lookup(resource *r, unsigned long a)
336 | {
337 |   struct mblock *m = (struct mblock *) r;
338 | 
339 |   if ((unsigned long) m->data <= a && (unsigned long) m->data + m->size > a)
340 |     return r;
341 |   return NULL;
342 | }
343 | 
344 | static struct resmem
345 | mbl_memsize(resource *r)
346 | {
347 |   struct mblock *m = (struct mblock *) r;
348 |   return (struct resmem) {
349 |     .effective = m->size,
350 |     .overhead = ALLOC_OVERHEAD + sizeof(struct mblock),
351 |   };
352 | }
353 | 
354 | static struct resclass mb_class = {
355 |   "Memory",
356 |   0,
357 |   mbl_free,
358 |   mbl_debug,
359 |   mbl_lookup,
360 |   mbl_memsize
361 | };
362 | 
363 | /**
364 |  * mb_alloc - allocate a memory block
365 |  * @p: pool
366 |  * @size: size of the block
367 |  *
368 |  * mb_alloc() allocates memory of a given size and creates
369 |  * a memory block resource representing this memory chunk
370 |  * in the pool @p.
371 |  *
372 |  * Please note that mb_alloc() returns a pointer to the memory
373 |  * chunk, not to the resource, hence you have to free it using
374 |  * mb_free(), not rfree().
375 |  */
376 | void *
377 | mb_alloc(pool *p, unsigned size)
378 | {
379 |   struct mblock *b = xmalloc(sizeof(struct mblock) + size);
380 | 
381 |   b->r.class = &mb_class;
382 |   b->r.n = (node) {};
383 |   add_tail(&p->inside, &b->r.n);
384 |   b->size = size;
385 |   return b->data;
386 | }
387 | 
388 | /**
389 |  * mb_allocz - allocate and clear a memory block
390 |  * @p: pool
391 |  * @size: size of the block
392 |  *
393 |  * mb_allocz() allocates memory of a given size, initializes it to
394 |  * zeroes and creates a memory block resource representing this memory
395 |  * chunk in the pool @p.
396 |  *
397 |  * Please note that mb_allocz() returns a pointer to the memory
398 |  * chunk, not to the resource, hence you have to free it using
399 |  * mb_free(), not rfree().
400 |  */
401 | void *
402 | mb_allocz(pool *p, unsigned size)
403 | {
404 |   void *x = mb_alloc(p, size);
405 |   bzero(x, size);
406 |   return x;
407 | }
408 | 
409 | /**
410 |  * mb_realloc - reallocate a memory block
411 |  * @m: memory block
412 |  * @size: new size of the block
413 |  *
414 |  * mb_realloc() changes the size of the memory block @m to a given size.
415 |  * The contents will be unchanged to the minimum of the old and new sizes;
416 |  * newly allocated memory will be uninitialized. Contrary to realloc()
417 |  * behavior, @m must be non-NULL, because the resource pool is inherited
418 |  * from it.
419 |  *
420 |  * Like mb_alloc(), mb_realloc() also returns a pointer to the memory
421 |  * chunk, not to the resource, hence you have to free it using
422 |  * mb_free(), not rfree().
423 |  */
424 | void *
425 | mb_realloc(void *m, unsigned size)
426 | {
427 |   struct mblock *b = SKIP_BACK(struct mblock, data, m);
428 | 
429 |   b = xrealloc(b, sizeof(struct mblock) + size);
430 |   update_node(&b->r.n);
431 |   b->size = size;
432 |   return b->data;
433 | }
434 | 
