436 | /**
437 |  * mb_free - free a memory block
438 |  * @m: memory block
439 |  *
440 |  * mb_free() frees all memory associated with the block @m.
441 |  */
442 | void
443 | mb_free(void *m)
444 | {
445 |   if (!m)
446 |     return;
447 | 
448 |   struct mblock *b = SKIP_BACK(struct mblock, data, m);
449 |   rfree(b);
450 | }
