190 | /**
191 |  * rdump - dump a resource
192 |  * @res: resource
193 |  *
194 |  * This function prints out all available information about the given
195 |  * resource to the debugging output.
196 |  *
197 |  * It works by calling a class-specific dump function.
198 |  */
199 | void
200 | rdump(struct dump_request *dreq, void *res)
201 | {
202 |   char x[16];
203 |   resource *r = res;
204 | 
205 |   bsprintf(x, "%%%ds%%p ", dreq->indent);
206 |   RDUMP(x, "", r);
207 |   if (r)
208 |     {
209 |       RDUMP("%s ", r->class->name);
210 |       r->class->dump(dreq, r);
211 |     }
212 |   else
213 |     RDUMP("NULL\n");
214 | }
