 10 | #include <stdio.h>
 11 | #include <stdlib.h>
 12 | #include <stdint.h>
 13 | 
 14 | #include "nest/bird.h"
 15 | #include "lib/resource.h"
 16 | #include "lib/string.h"
 17 | 
 18 | /**
 19 |  * DOC: Resource pools
 20 |  *
 21 |  * Resource pools (&pool) are just containers holding a list of
 22 |  * other resources. Freeing a pool causes all the listed resources
 23 |  * to be freed as well. Each existing &resource is linked to some pool
 24 |  * except for a root pool which isn't linked anywhere, so all the
 25 |  * resources form a tree structure with internal nodes corresponding
 26 |  * to pools and leaves being the other resources.
 27 |  *
 28 |  * Example: Almost all modules of BIRD have their private pool which
 29 |  * is freed upon shutdown of the module.
 30 |  */
 31 | 
 32 | struct pool {
 33 |   resource r;
 34 |   list inside;
 35 |   const char *name;
 36 | };
 37 | 
 38 | static void pool_dump(struct dump_request *, resource *);
 39 | static void pool_free(resource *);
 40 | static resource *pool_lookup(resource *, unsigned long);
 41 | static struct resmem pool_memsize(resource *P);
 42 | 
 43 | static struct resclass pool_class = {
 44 |   "Pool",
 45 |   sizeof(pool),
 46 |   pool_free,
 47 |   pool_dump,
 48 |   pool_lookup,
 49 |   pool_memsize
 50 | };
 51 | 
 52 | pool root_pool;
 53 | 
 54 | /**
 55 |  * rp_new - create a resource pool
 56 |  * @p: parent pool
 57 |  * @name: pool name (to be included in debugging dumps)
 58 |  *
 59 |  * rp_new() creates a new resource pool inside the specified
 60 |  * parent pool.
 61 |  */
 62 | pool *
 63 | rp_new(pool *p, const char *name)
 64 | {
 65 |   pool *z = ralloc(p, &pool_class);
 66 |   z->name = name;
 67 |   init_list(&z->inside);
 68 |   return z;
 69 | }
 70 | 
 71 | pool *
 72 | rp_newf(pool *p, const char *fmt, ...)
 73 | {
 74 |   pool *z = rp_new(p, NULL);
 75 | 
 76 |   va_list args;
 77 |   va_start(args, fmt);
 78 |   z->name = mb_vsprintf(p, fmt, args);
 79 |   va_end(args);
 80 | 
 81 |   return z;
 82 | }
 83 | 
 84 | 
 85 | static void
 86 | pool_free(resource *P)
 87 | {
 88 |   pool *p = (pool *) P;
 89 |   resource *r, *rr;
 90 | 
 91 |   r = HEAD(p->inside);
 92 |   while (rr = (resource *) r->n.next)
 93 |     {
 94 |       r->class->free(r);
 95 |       xfree(r);
 96 |       r = rr;
 97 |     }
 98 | }
 99 | 
100 | static void
101 | pool_dump(struct dump_request *dreq, resource *P)
102 | {
103 |   pool *p = (pool *) P;
104 |   resource *r;
105 | 
106 |   RDUMP("%s\n", p->name);
107 |   dreq->indent += 3;
108 |   WALK_LIST(r, p->inside)
109 |     rdump(dreq, r);
110 |   dreq->indent -= 3;
111 | }
112 | 
113 | static struct resmem
114 | pool_memsize(resource *P)
115 | {
116 |   pool *p = (pool *) P;
117 |   resource *r;
118 |   struct resmem sum = {
119 |     .effective = 0,
120 |     .overhead = sizeof(pool) + ALLOC_OVERHEAD,
121 |   };
122 | 
123 |   WALK_LIST(r, p->inside)
124 |   {
125 |     struct resmem add = rmemsize(r);
126 |     sum.effective += add.effective;
127 |     sum.overhead += add.overhead;
128 |   }
129 | 
130 |   return sum;
131 | }
132 | 
133 | static resource *
134 | pool_lookup(resource *P, unsigned long a)
135 | {
136 |   pool *p = (pool *) P;
137 |   resource *r, *q;
138 | 
139 |   WALK_LIST(r, p->inside)
140 |     if (r->class->lookup && (q = r->class->lookup(r, a)))
141 |       return q;
142 |   return NULL;
143 | }
144 | 
145 | /**
146 |  * rmove - move a resource
147 |  * @res: resource
148 |  * @p: pool to move the resource to
149 |  *
150 |  * rmove() moves a resource from one pool to another.
151 |  */
152 | 
153 | void rmove(void *res, pool *p)
154 | {
155 |   resource *r = res;
156 | 
157 |   if (r)
158 |     {
159 |       if (r->n.next)
160 |         rem_node(&r->n);
161 |       add_tail(&p->inside, &r->n);
162 |     }
163 | }
164 | 
165 | /**
166 |  * rfree - free a resource
167 |  * @res: resource
168 |  *
169 |  * rfree() frees the given resource and all information associated
170 |  * with it. In case it's a resource pool, it also frees all the objects
171 |  * living inside the pool.
172 |  *
173 |  * It works by calling a class-specific freeing function.
174 |  */
175 | void
176 | rfree(void *res)
177 | {
178 |   resource *r = res;
179 | 
180 |   if (!r)
181 |     return;
182 | 
183 |   if (r->n.next)
184 |     rem_node(&r->n);
185 |   r->class->free(r);
186 |   r->class = NULL;
187 |   xfree(r);
188 | }
189 | 
190 | /**
191 |  * rdump - dump a resource
192 |  * @res: resource
193 |  *
194 |  * This function prints out all available information about the given
195 |  * resource to the debugging output.
196 |  *
197 |  * It works by calling a class-specific dump function.
198 |  */
199 | void
200 | rdump(struct dump_request *dreq, void *res)
201 | {
202 |   char x[16];
203 |   resource *r = res;
204 | 
205 |   bsprintf(x, "%%%ds%%p ", dreq->indent);
206 |   RDUMP(x, "", r);
207 |   if (r)
208 |     {
209 |       RDUMP("%s ", r->class->name);
210 |       r->class->dump(dreq, r);
211 |     }
212 |   else
213 |     RDUMP("NULL\n");
214 | }
215 | 
216 | void page_dump(struct dump_request *req);
217 | 
218 | void resource_dump(struct dump_request *req)
219 | {
220 |   rdump(req, &root_pool);
221 |   page_dump(req);
222 | }
223 | 
224 | struct resmem
225 | rmemsize(void *res)
226 | {
227 |   resource *r = res;
228 |   if (!r)
229 |     return (struct resmem) {};
230 |   if (!r->class->memsize)
231 |     return (struct resmem) {
232 |       .effective = r->class->size - sizeof(resource),
233 |       .overhead = ALLOC_OVERHEAD + sizeof(resource),
234 |     };
235 |   return r->class->memsize(r);
236 | }
