238 | /**
239 |  * ralloc - create a resource
240 |  * @p: pool to create the resource in
241 |  * @c: class of the new resource
242 |  *
243 |  * This function is called by the resource classes to create a new
244 |  * resource of the specified class and link it to the given pool.
245 |  * Allocated memory is zeroed. Size of the resource structure is taken
246 |  * from the @size field of the &resclass.
247 |  */
248 | void *
249 | ralloc(pool *p, struct resclass *c)
250 | {
251 |   resource *r = xmalloc(c->size);
252 |   bzero(r, c->size);
253 | 
254 |   r->class = c;
255 |   if (p)
256 |     add_tail(&p->inside, &r->n);
257 |   return r;
258 | }
