 10 |  */
 11 | 
 12 | /**
 13 |  * DOC: Slabs
 14 |  *
 15 |  * Slabs are collections of memory blocks of a fixed size.
 16 |  * They support very fast allocation and freeing of such blocks, prevent memory
 17 |  * fragmentation and optimize L2 cache usage. Slabs have been invented by Jeff Bonwick
 18 |  * and published in USENIX proceedings as `The Slab Allocator: An Object-Caching Kernel
 19 |  * Memory Allocator'. Our implementation follows this article except that we don't use
 20 |  * constructors and destructors.
 21 |  *
 22 |  * When the |DEBUGGING| switch is turned on, we automatically fill all
 23 |  * newly allocated and freed blocks with a special pattern to make detection
 24 |  * of use of uninitialized or already freed memory easier.
 25 |  *
 26 |  * Example: Nodes of a FIB are allocated from a per-FIB Slab.
 27 |  */
 28 | 
 29 | #include <stdlib.h>
 30 | #include <stdint.h>
 31 | 
 32 | #include "nest/bird.h"
 33 | #include "lib/resource.h"
 34 | #include "lib/string.h"
 35 | #include "lib/tlists.h"
 36 | 
 37 | #undef FAKE_SLAB	/* Turn on if you want to debug memory allocations */
 38 | 
 39 | #ifdef DEBUGGING
 40 | #define POISON		/* Poison all regions after they are freed */
 41 | #endif
 42 | 
 43 | static void slab_free(resource *r);
 44 | static void slab_dump(struct dump_request *dreq, resource *r);
 45 | static resource *slab_lookup(resource *r, unsigned long addr);
 46 | static struct resmem slab_memsize(resource *r);
 47 | 
 48 | #ifdef FAKE_SLAB
 49 | 
 50 | /*
 51 |  *  Fake version used for debugging.
 52 |  */
 53 | 
 54 | struct slab {
 55 |   resource r;
 56 |   uint size;
 57 |   list objs;
 58 | };
 59 | 
 60 | static struct resclass sl_class = {
 61 |   "FakeSlab",
 62 |   sizeof(struct slab),
 63 |   slab_free,
 64 |   slab_dump,
 65 |   NULL,
 66 |   slab_memsize
 67 | };
 68 | 
 69 | struct sl_obj {
 70 |   node n;
 71 |   max_align_t data_align[0];
 72 |   byte data[0];
 73 | };
 74 | 
 75 | slab *
 76 | sl_new(pool *p, uint size)
 77 | {
 78 |   slab *s = ralloc(p, &sl_class);
 79 |   s->size = size;
 80 |   init_list(&s->objs);
 81 |   return s;
 82 | }
 83 | 
 84 | void *
 85 | sl_alloc(slab *s)
 86 | {
 87 |   struct sl_obj *o = xmalloc(sizeof(struct sl_obj) + s->size);
 88 | 
 89 |   add_tail(&s->objs, &o->n);
 90 |   return o->data;
 91 | }
 92 | 
 93 | void *
 94 | sl_allocz(slab *s)
 95 | {
 96 |   void *obj = sl_alloc(s);
 97 |   memset(obj, 0, s->size);
 98 |   return obj;
 99 | }
100 | 
101 | void
102 | sl_free(void *oo)
103 | {
104 |   struct sl_obj *o = SKIP_BACK(struct sl_obj, data, oo);
105 | 
106 |   rem_node(&o->n);
107 |   xfree(o);
108 | }
109 | 
110 | static void
111 | slab_free(resource *r)
112 | {
113 |   slab *s = (slab *) r;
114 |   struct sl_obj *o, *p;
115 | 
116 |   for(o = HEAD(s->objs); p = (struct sl_obj *) o->n.next; o = p)
117 |     xfree(o);
118 | }
119 | 
120 | static void
121 | slab_dump(resource *r)
122 | {
123 |   slab *s = (slab *) r;
124 |   int cnt = 0;
125 |   struct sl_obj *o;
126 | 
127 |   WALK_LIST(o, s->objs)
128 |     cnt++;
129 |   debug("(%d objects per %d bytes)\n", cnt, s->size);
130 | }
131 | 
132 | static struct resmem
133 | slab_memsize(resource *r)
134 | {
135 |   slab *s = (slab *) r;
136 |   size_t cnt = 0;
137 |   struct sl_obj *o;
138 | 
139 |   WALK_LIST(o, s->objs)
140 |     cnt++;
141 | 
142 |   return (struct resmem) {
143 |     .effective = cnt * s->size,
144 |     .overhead = ALLOC_OVERHEAD + sizeof(struct slab) + cnt * ALLOC_OVERHEAD,
145 |   };
146 | }
