195 | #define SL_GET_HEAD(x)	((struct sl_head *) (((uintptr_t) (x)) & ~(page_size-1)))
196 | 
197 | #define SL_HEAD_CHANGE_STATE(_s, _h, _from, _to) ({ \
198 |     ASSERT_DIE(_h->state == slh_##_from); \
199 |     sl_head_rem_node(&_s->_from##_heads, _h); \
200 |     sl_head_add_head(&_s->_to##_heads, _h); \
201 |     _h->state = slh_##_to; \
202 |     })
