205 | /**
206 |  * sl_new - create a new Slab
207 |  * @p: resource pool
208 |  * @size: block size
209 |  *
210 |  * This function creates a new Slab resource from which
211 |  * objects of size @size can be allocated.
212 |  */
213 | slab *
214 | sl_new(pool *p, uint size)
215 | {
216 |   slab *s = ralloc(p, &sl_class);
217 |   uint align = CPU_STRUCT_ALIGN;
218 |   s->data_size = size;
219 |   size = (size + align - 1) / align * align;
220 |   s->obj_size = size;
221 | 
222 |   s->head_size = sizeof(struct sl_head);
223 | 
224 |   do {
225 |     s->objs_per_slab = (page_size - s->head_size) / size;
226 |     s->head_bitfield_len = (s->objs_per_slab + 31) / 32;
227 |     s->head_size = (
228 | 	sizeof(struct sl_head)
229 |       + sizeof(u32) * s->head_bitfield_len
230 |       + align - 1)
231 |     / align * align;
232 |   } while (s->objs_per_slab * size + s->head_size > page_size);
233 | 
234 |   if (!s->objs_per_slab)
235 |     bug("Slab: object too large");
236 |   s->num_empty_heads = 0;
237 | 
238 |   return s;
239 | }
240 | 
241 | /**
242 |  * sl_alloc - allocate an object from Slab
243 |  * @s: slab
244 |  *
245 |  * sl_alloc() allocates space for a single object from the
246 |  * Slab and returns a pointer to the object.
247 |  */
248 | void *
249 | sl_alloc(slab *s)
250 | {
251 |   struct sl_head *h;
252 | 
253 | redo:
