260 |       uint pos = u32_ctz(~h->used_bits[i]);
261 |       if (i * 32 + pos >= s->objs_per_slab)
262 | 	break;
263 | 
264 |       h->used_bits[i] |= 1 << pos;
265 |       h->num_full++;
266 | 
267 |       void *out = ((void *) h) + s->head_size + (i * 32 + pos) * s->obj_size;
268 | #ifdef POISON
