298 | /**
299 |  * sl_allocz - allocate an object from Slab and zero it
300 |  * @s: slab
301 |  *
302 |  * sl_allocz() allocates space for a single object from the
303 |  * Slab and returns a pointer to the object after zeroing out
304 |  * the object memory.
305 |  */
306 | void *
307 | sl_allocz(slab *s)
308 | {
309 |   void *obj = sl_alloc(s);
