314 | /**
315 |  * sl_free - return a free object back to a Slab
316 |  * @s: slab
317 |  * @oo: object returned by sl_alloc()
318 |  *
319 |  * This function frees memory associated with the object @oo
320 |  * and returns it back to the Slab @s.
321 |  */
322 | void
323 | sl_free(void *oo)
324 | {
325 |   struct sl_head *h = SL_GET_HEAD(oo);
326 |   struct slab *s = h->slab;
327 | 
328 | #ifdef POISON
329 |   memset(oo, 0xdb, s->data_size);
330 | #endif
331 | 
332 |   uint offset = oo - ((void *) h) - s->head_size;
333 |   ASSERT_DIE(offset % s->obj_size == 0);
334 |   uint pos = offset / s->obj_size;
335 |   ASSERT_DIE(pos < s->objs_per_slab);
336 | 
337 |   h->used_bits[pos / 32] &= ~(1 << (pos % 32));
338 | 
339 |   if ((h->num_full-- == s->objs_per_slab) && (h->state == slh_full))
340 |     SL_HEAD_CHANGE_STATE(s, h, full, partial);
341 |   else if (!h->num_full)
342 |     {
343 |       sl_head_rem_node(&s->partial_heads, h);
344 |       if (s->num_empty_heads >= MAX_EMPTY_HEADS)
345 |       {
346 | #ifdef POISON
347 | 	memset(h, 0xde, page_size);
348 | #endif
349 | 	free_page(h);
350 |       }
351 |       else
352 | 	{
353 | 	  sl_head_add_head(&s->empty_heads, h);
354 | 	  h->state = slh_empty;
