409 | slab_memsize(resource *r)
410 | {
411 |   slab *s = (slab *) r;
412 |   size_t heads = 0;
413 | 
414 |   WALK_TLIST(sl_head, h, &s->full_heads)
415 |     heads++;
416 | 
417 |   size_t items = heads * s->objs_per_slab;
418 | 
419 |   WALK_TLIST(sl_head, h, &s->partial_heads)
