 16 | 
 17 | u64
 18 | bstrtoul10(const char *str, char **end)
 19 | {
 20 |   u64 out = 0;
 21 |   for (*end = (char *) str; (**end >= '0') && (**end <= '9'); (*end)++) {
 22 |     u64 digit = **end - '0';
 23 |     if ((out > ULI_MAX_DIV10) ||
 24 | 	(out == ULI_MAX_DIV10) && (digit > ULI_MAX_MOD10)) {
 25 |       errno = ERANGE;
 26 |       return UINT64_MAX;
 27 |     }
 28 | 
 29 |     out *= 10;
 30 |     out += (**end) - '0';
 31 |   }
 32 |   return out;
 33 | }
 34 | 
 35 | u64
 36 | bstrtoul16(const char *str, char **end)
 37 | {
 38 |   u64 out = 0;
 39 |   for (int i=0; i<=(64/4); i++) {
 40 |     switch (str[i]) {
 41 |       case '0' ... '9':
 42 | 	out *= 16;
 43 | 	out += str[i] - '0';
 44 | 	break;
 45 |       case 'a' ... 'f':
 46 | 	out *= 16;
 47 | 	out += str[i] + 10 - 'a';
 48 | 	break;
 49 |       case 'A' ... 'F':
 50 | 	out *= 16;
 51 | 	out += str[i] + 10 - 'A';
 52 | 	break;
 53 |       default:
 54 | 	*end = (char *) &(str[i]);
 55 | 	return out;
 56 |     }
 57 |   }
 58 | 
 59 |   errno = ERANGE;
 60 |   return UINT64_MAX;
 61 | }
 62 | 
 63 | static int
 64 | fromxdigit(char c)
 65 | {
 66 |   switch (c)
 67 |   {
 68 |   case '0' ... '9':
 69 |     return c - '0';
 70 |   case 'a' ... 'f':
 71 |     return c + 10 - 'a';
 72 |   case 'A' ... 'F':
 73 |     return c + 10 - 'A';
 74 |   default:
 75 |     return -1;
 76 |   }
 77 | }
 78 | 
 79 | int
 80 | bstrhextobin(const char *s, byte *b)
 81 | {
 82 |   int len = 0;
 83 |   int hi = 0;
 84 | 
 85 |   for (; *s; s++)
 86 |   {
 87 |     int v = fromxdigit(*s);
 88 |     if (v < 0)
 89 |     {
 90 |       if (strchr(" -.:", *s) && !hi)
 91 | 	continue;
 92 |       else
 93 | 	return -1;
 94 |     }
 95 | 
 96 |     if (len == INT32_MAX)
 97 |       return -1;
 98 | 
 99 |     if (b)
100 |     {
101 |       if (!hi)
102 | 	b[len] = (v << 4);
103 |       else
104 | 	b[len] |= v;
105 |     }
106 | 
107 |     len += hi;
108 |     hi = !hi;
109 |   }
110 | 
111 |   return !hi ? len : -1;
112 | }
113 | 
114 | static char
115 | toxdigit(uint b)
116 | {
117 |   if (b < 10)
118 |     return ('0' + b);
119 |   else if (b < 16)
120 |     return ('a' + b - 10);
121 |   else
122 |     return 0;
123 | }
124 | 
125 | int
126 | bstrbintohex(const byte *b, size_t len, char *buf, size_t size, char delim)
127 | {
128 |   ASSERT(size >= 6);
129 |   char *bound = buf + size - 3;
130 | 
131 |   size_t i;
132 |   for (i = 0; i < len; i++)
133 |   {
134 |     if (buf > bound)
135 |     {
136 |       strcpy(buf - 4, "...");
137 |       return -1;
138 |     }
139 | 
140 |     uint x = b[i];
141 |     buf[0] = toxdigit(x >> 4);
142 |     buf[1] = toxdigit(x & 0xF);
143 |     buf[2] = delim;
144 |     buf += 3;
145 |   }
146 | 
147 |   buf[i ? -1 : 0] = 0;
148 | 
149 |   return 0;
150 | }

