175 | void
176 | tm_stop(timer *t)
177 | {
178 |   if (!t->expires)
179 |     return;
180 | 
181 |   struct timeloop *loop = timeloop_current();
182 |   uint tc = timers_count(loop);
183 | 
184 |   HEAP_DELETE(loop->timers.data, tc, timer *, TIMER_LESS, TIMER_SWAP, t->index);
185 |   BUFFER_POP(loop->timers);
186 | 
187 |   t->index = -1;
188 |   t->expires = 0;
189 | }
