248 | /**
249 |  * tm_parse_time - parse a date and time
250 |  * @x: time string
251 |  *
252 |  * tm_parse_time() takes a textual representation of a date and time
253 |  * (yyyy-mm-dd[ hh:mm:ss[.sss]]) and converts it to the corresponding value of
254 |  * type &btime.
255 |  */
256 | btime
257 | tm_parse_time(const char *x)
258 | {
259 |   struct tm tm = {};
260 |   int usec, n1, n2, n3, r;
261 | 
262 |   r = sscanf(x, "%d-%d-%d%n %d:%d:%d%n.%d%n",
263 | 	     &tm.tm_year, &tm.tm_mon, &tm.tm_mday, &n1,
264 | 	     &tm.tm_hour, &tm.tm_min, &tm.tm_sec, &n2,
265 | 	     &usec, &n3);
266 | 
267 |   if ((r == 3) && !x[n1])
268 |     tm.tm_hour = tm.tm_min = tm.tm_sec = usec = 0;
269 |   else if ((r == 6) && !x[n2])
270 |     usec = 0;
271 |   else if ((r == 7) && !x[n3])
272 |   {
273 |     /* Convert subsecond digits to proper precision */
274 |     int digits = n3 - n2 - 1;
275 |     if ((usec < 0) || (usec > 999999) || (digits < 1) || (digits > 6))
276 |       return 0;
277 | 
278 |     while (digits++ < 6)
279 |       usec *= 10;
280 |   }
281 |   else
282 |     return 0;
283 | 
284 |   tm.tm_mon--;
285 |   tm.tm_year -= 1900;
286 |   s64 ts = mktime(&tm);
287 |   if ((ts == (s64) (time_t) -1) || (ts < 0) || (ts > ((s64) 1 << 40)))
288 |     return 0;
289 | 
290 |   return ts S + usec;
291 | }
