  1 | /*
  2 |  *	BIRD -- Timers
  3 |  *
  4 |  *	(c) 2013--2017 Ondrej Zajicek <santiago@crfreenet.org>
  5 |  *	(c) 2013--2017 CZ.NIC z.s.p.o.
  6 |  *
  7 |  *	Can be freely distributed and used under the terms of the GNU GPL.
  8 |  */
  9 | 
 10 | /**
 11 |  * DOC: Timers
 12 |  *
 13 |  * Timers are resources which represent a wish of a module to call a function at
 14 |  * the specified time. The timer code does not guarantee exact timing, only that
 15 |  * a timer function will not be called before the requested time.
 16 |  *
 17 |  * In BIRD, time is represented by values of the &btime type which is signed
 18 |  * 64-bit integer interpreted as a relative number of microseconds since some
 19 |  * fixed time point in past. The current time can be obtained by current_time()
 20 |  * function with reasonable accuracy and is monotonic. There is also a current
 21 |  * 'wall-clock' real time obtainable by current_real_time() reported by OS.
 22 |  *
 23 |  * Each timer is described by a &timer structure containing a pointer to the
 24 |  * handler function (@hook), data private to this function (@data), time the
 25 |  * function should be called at (@expires, 0 for inactive timers), for the other
 26 |  * fields see |timer.h|.
 27 |  */
 28 | 
 29 | #include <stdio.h>
 30 | #include <stdlib.h>
 31 | #include <time.h>
 32 | 
 33 | #include "nest/bird.h"
 34 | 
 35 | #include "lib/heap.h"
 36 | #include "lib/resource.h"
 37 | #include "lib/timer.h"
 38 | 
 39 | 
 40 | struct timeloop main_timeloop;
 41 | 
 42 | 
 43 | #ifdef USE_PTHREADS
 44 | 
 45 | #include <pthread.h>
 46 | 
 47 | /* Data accessed and modified from proto/bfd/io.c */
 48 | pthread_key_t current_time_key;
 49 | 
 50 | static inline struct timeloop *
 51 | timeloop_current(void)
 52 | {
 53 |   return pthread_getspecific(current_time_key);
 54 | }
 55 | 
 56 | static inline void
 57 | timeloop_init_current(void)
 58 | {
 59 |   pthread_key_create(&current_time_key, NULL);
 60 |   pthread_setspecific(current_time_key, &main_timeloop);
 61 | }
 62 | 
 63 | void wakeup_kick_current(void);
 64 | 
 65 | #else
 66 | 
 67 | /* Just use main timelooop */
 68 | static inline struct timeloop * timeloop_current(void) { return &main_timeloop; }
 69 | static inline void timeloop_init_current(void) { }
 70 | 
 71 | #endif
 72 | 
 73 | btime
 74 | current_time(void)
 75 | {
 76 |   return timeloop_current()->last_time;
 77 | }
 78 | 
 79 | btime
 80 | current_real_time(void)
 81 | {
 82 |   struct timeloop *loop = timeloop_current();
 83 | 
 84 |   if (!loop->real_time)
 85 |     times_update_real_time(loop);
 86 | 
 87 |   return loop->real_time;
 88 | }
 89 | 
 90 | 
 91 | #define TIMER_LESS(a,b)		((a)->expires < (b)->expires)
 92 | #define TIMER_SWAP(heap,a,b,t)	(t = heap[a], heap[a] = heap[b], heap[b] = t, \
 93 | 				   heap[a]->index = (a), heap[b]->index = (b))
 94 | 
 95 | 
 96 | static void
 97 | tm_free(resource *r)
 98 | {
 99 |   timer *t = (void *) r;
100 | 
101 |   tm_stop(t);
102 | }
103 | 
104 | static void
105 | tm_dump(struct dump_request *dreq, resource *r)
106 | {
107 |   timer *t = (void *) r;
108 | 
109 |   RDUMP("(code %p, data %p, ", t->hook, t->data);
110 |   if (t->randomize)
111 |     RDUMP("rand %d, ", t->randomize);
112 |   if (t->recurrent)
113 |     RDUMP("recur %ld, ", t->recurrent);
114 |   if (t->expires)
115 |     RDUMP("expires in %ld ms)\n", (t->expires - current_time()) TO_MS);
116 |   else
117 |     RDUMP("inactive)\n");
118 | }
119 | 
120 | 
121 | static struct resclass tm_class = {
122 |   "Timer",
123 |   sizeof(timer),
124 |   tm_free,
125 |   tm_dump,
126 |   NULL,
127 |   NULL
128 | };
129 | 
130 | timer *
131 | tm_new(pool *p)
132 | {
133 |   timer *t = ralloc(p, &tm_class);
134 |   t->index = -1;
135 |   return t;
136 | }
137 | 
138 | void
139 | tm_set(timer *t, btime when)
140 | {
141 |   struct timeloop *loop = timeloop_current();
142 |   uint tc = timers_count(loop);
143 | 
144 |   if (!t->expires)
145 |   {
146 |     t->index = ++tc;
147 |     t->expires = when;
148 |     BUFFER_PUSH(loop->timers) = t;
149 |     HEAP_INSERT(loop->timers.data, tc, timer *, TIMER_LESS, TIMER_SWAP);
150 |   }
151 |   else if (t->expires < when)
152 |   {
153 |     t->expires = when;
154 |     HEAP_INCREASE(loop->timers.data, tc, timer *, TIMER_LESS, TIMER_SWAP, t->index);
155 |   }
156 |   else if (t->expires > when)
157 |   {
158 |     t->expires = when;
159 |     HEAP_DECREASE(loop->timers.data, tc, timer *, TIMER_LESS, TIMER_SWAP, t->index);
160 |   }
161 | 
162 | #ifdef CONFIG_BFD
163 |   /* Hack to notify BFD loops */
164 |   if ((loop != &main_timeloop) && (t->index == 1))
165 |     wakeup_kick_current();
166 | #endif
167 | }
168 | 
169 | void
170 | tm_start(timer *t, btime after)
171 | {
172 |   tm_set(t, current_time() + MAX(after, 0));
173 | }
174 | 
175 | void
176 | tm_stop(timer *t)
177 | {
178 |   if (!t->expires)
179 |     return;
180 | 
181 |   struct timeloop *loop = timeloop_current();
182 |   uint tc = timers_count(loop);
183 | 
184 |   HEAP_DELETE(loop->timers.data, tc, timer *, TIMER_LESS, TIMER_SWAP, t->index);
185 |   BUFFER_POP(loop->timers);
186 | 
187 |   t->index = -1;
188 |   t->expires = 0;
189 | }
190 | 
191 | void
192 | timers_init(struct timeloop *loop, pool *p)
193 | {
194 |   times_init(loop);
195 | 
196 |   BUFFER_INIT(loop->timers, p, 4);
197 |   BUFFER_PUSH(loop->timers) = NULL;
198 | }
199 | 
200 | void io_log_event(void *hook, void *data);
201 | 
202 | void
203 | timers_fire(struct timeloop *loop)
204 | {
205 |   btime base_time;
206 |   timer *t;
207 | 
208 |   times_update(loop);
209 |   base_time = loop->last_time;
210 | 
211 |   while (t = timers_first(loop))
212 |   {
213 |     if (t->expires > base_time)
214 |       return;
215 | 
216 |     if (t->recurrent)
217 |     {
218 |       btime when = t->expires + t->recurrent;
219 | 
220 |       if (when <= loop->last_time)
221 | 	when = loop->last_time + t->recurrent;
222 | 
223 |       if (t->randomize)
224 | 	when += random() % (t->randomize + 1);
225 | 
226 |       tm_set(t, when);
227 |     }
228 |     else
229 |       tm_stop(t);
230 | 
231 |     /* This is ugly hack, we want to log just timers executed from the main I/O loop */
232 |     if (loop == &main_timeloop)
233 |       io_log_event(t->hook, t->data);
234 | 
235 |     t->hook(t);
236 |     tmp_flush();
237 |   }
238 | }
239 | 
240 | void
241 | timer_init(void)
242 | {
243 |   timers_init(&main_timeloop, &root_pool);
244 |   timeloop_init_current();
245 | }
246 | 
247 | 
248 | /**
249 |  * tm_parse_time - parse a date and time
250 |  * @x: time string
251 |  *
252 |  * tm_parse_time() takes a textual representation of a date and time
253 |  * (yyyy-mm-dd[ hh:mm:ss[.sss]]) and converts it to the corresponding value of
254 |  * type &btime.
255 |  */
256 | btime
257 | tm_parse_time(const char *x)
258 | {
259 |   struct tm tm = {};
260 |   int usec, n1, n2, n3, r;
261 | 
262 |   r = sscanf(x, "%d-%d-%d%n %d:%d:%d%n.%d%n",
263 | 	     &tm.tm_year, &tm.tm_mon, &tm.tm_mday, &n1,
264 | 	     &tm.tm_hour, &tm.tm_min, &tm.tm_sec, &n2,
265 | 	     &usec, &n3);
266 | 
267 |   if ((r == 3) && !x[n1])
268 |     tm.tm_hour = tm.tm_min = tm.tm_sec = usec = 0;
269 |   else if ((r == 6) && !x[n2])
270 |     usec = 0;
271 |   else if ((r == 7) && !x[n3])
272 |   {
273 |     /* Convert subsecond digits to proper precision */
274 |     int digits = n3 - n2 - 1;
275 |     if ((usec < 0) || (usec > 999999) || (digits < 1) || (digits > 6))
276 |       return 0;
277 | 
278 |     while (digits++ < 6)
279 |       usec *= 10;
280 |   }
281 |   else
282 |     return 0;
283 | 
284 |   tm.tm_mon--;
285 |   tm.tm_year -= 1900;
286 |   s64 ts = mktime(&tm);
287 |   if ((ts == (s64) (time_t) -1) || (ts < 0) || (ts > ((s64) 1 << 40)))
288 |     return 0;
289 | 
290 |   return ts S + usec;
291 | }
292 | 
293 | /**
294 |  * tm_format_time - convert date and time to textual representation
295 |  * @x: destination buffer of size %TM_DATETIME_BUFFER_SIZE
296 |  * @fmt: specification of resulting textual representation of the time
297 |  * @t: time
298 |  *
299 |  * This function formats the given relative time value @t to a textual
300 |  * date/time representation (dd-mm-yyyy hh:mm:ss) in real time.
301 |  */
302 | void
303 | tm_format_time(char *x, struct timeformat *fmt, btime t)
304 | {
305 |   btime dt = current_time() - t;
306 |   btime rt = current_real_time() - dt;
307 |   int v1 = !fmt->limit || (dt < fmt->limit);
308 | 
309 |   if (!tm_format_real_time(x, TM_DATETIME_BUFFER_SIZE, v1 ? fmt->fmt1 : fmt->fmt2, rt))
310 |     strcpy(x, "<error>");
311 | }
312 | 
313 | /* Replace %f in format string with usec scaled to requested precision */
314 | static int
315 | strfusec(char *buf, int size, const char *fmt, uint usec)
316 | {
317 |   char *str = buf;
318 |   int parity = 0;
319 | 
320 |   while (*fmt)
321 |   {
322 |     if (!size)
323 |       return 0;
324 | 
325 |     if ((fmt[0] == '%') && (!parity) &&
326 | 	((fmt[1] == 'f') || (fmt[1] >= '1') && (fmt[1] <= '6') && (fmt[2] == 'f')))
327 |     {
328 |       int digits = (fmt[1] == 'f') ? 6 : (fmt[1] - '0');
329 |       uint d = digits, u = usec;
330 | 
331 |       /* Convert microseconds to requested precision */
332 |       while (d++ < 6)
333 | 	u /= 10;
334 | 
335 |       int num = bsnprintf(str, size, "%0*u", digits, u);
336 |       if (num < 0)
337 | 	return 0;
338 | 
339 |       fmt += (fmt[1] == 'f') ? 2 : 3;
340 |       ADVANCE(str, size, num);
341 |     }
342 |     else
343 |     {
344 |       /* Handle '%%' expression */
345 |       parity = (*fmt == '%') ? !parity : 0;
346 |       *str++ = *fmt++;
347 |       size--;
348 |     }
349 |   }
350 | 
351 |   if (!size)
352 |     return 0;
353 | 
354 |   *str = 0;
355 |   return str - buf;
356 | }
357 | 
358 | int
359 | tm_format_real_time(char *x, size_t max, const char *fmt, btime t)
360 | {
361 |   s64 t1 = t TO_S;
362 |   s64 t2 = t - t1 S;
363 | 
364 |   time_t ts = t1;
365 |   struct tm tm;
366 |   if (!localtime_r(&ts, &tm))
367 |     return 0;
368 | 
369 |   size_t tbuf_size = MIN(max, 4096);
370 |   byte *tbuf = alloca(tbuf_size);
371 |   if (!strfusec(tbuf, tbuf_size, fmt, t2))
372 |     return 0;
373 | 
374 |   if (!strftime(x, max, tbuf, &tm))
375 |     return 0;
376 | 
377 |   return 1;
378 | }

