 52 | static inline u64
 53 | get_u64(const void *p)
 54 | {
 55 |   u32 xh, xl;
 56 |   memcpy(&xh, p, 4);
 57 |   memcpy(&xl, p+4, 4);
 58 |   return (((u64) ntohl(xh)) << 32) | ntohl(xl);
 59 | }
