384 |       buffer_print(b, len ? "%u " : "%u", get_as(pos));
385 |       pos += BS;
386 |     }
387 | 
388 |     if (cls)
389 |       buffer_puts(b, cls);
390 | 
391 |     if (pos < end)
392 |       buffer_puts(b, " ");
393 |   }
394 | 
395 |   /* Handle overflow */
396 |   if (b->pos == b->end)
397 |     strcpy(b->end - 12, "...");
