604 | const struct adata *
605 | as_path_filter(struct linpool *pool, const struct adata *path, const struct f_val *set, int pos)
606 | {
607 |   ASSERT((set->type == T_SET) || (set->type == T_INT));
608 | 
609 |   if (!path)
610 |     return NULL;
611 | 
612 |   int len = path->length;
613 |   const u8 *p = path->data;
614 |   const u8 *q = path->data + len;
615 |   u8 *d, *d2;
616 |   int i, bt, sn, dn;
617 |   u8 buf[len];
618 | 
619 |   d = buf;
620 |   while (p<q)
621 |     {
622 |       /* Read block header (type and length) */
623 |       bt = p[0];
624 |       sn = p[1];
625 |       dn = 0;
626 |       p += 2;
627 |       d2 = d + 2;
628 | 
629 |       for (i = 0; i < sn; i++)
630 | 	{
631 | 	  u32 as = get_as(p);
632 | 	  int match;
633 | 
634 | 	  if (set->type == T_SET)
635 | 	    {
636 | 	      struct f_val v = { .type = T_INT, .val.i = as};
637 | 	      match = !!find_tree(set->val.t, &v);
638 | 	    }
639 | 	  else /* T_INT */
640 | 	    match = (as == set->val.i);
641 | 
642 | 	  if (match == pos)
643 | 	    {
644 | 	      put_as(d2, as);
645 | 	      d2 += BS;
646 | 	      dn++;
647 | 	    }
648 | 
649 | 	  p += BS;
650 | 	}
651 | 
652 |       if (dn > 0)
653 | 	{
654 | 	  /* Nonempty block, set block header and advance */
655 | 	  d[0] = bt;
656 | 	  d[1] = dn;
657 | 	  d = d2;
658 | 	}
659 |   }
660 | 
661 |   uint nl = d - buf;
662 |   if (nl == path->length)
663 |     return path;
664 | 
665 |   struct adata *res = lp_alloc(pool, sizeof(struct adata) + nl);
666 |   res->length = nl;
667 |   memcpy(res->data, buf, nl);
668 | 
669 |   return res;
670 | }
