681 |   {
682 |     int res1 = as_path_walk(path1, &pos1, &val1);
683 |     int res2 = as_path_walk(path2, &pos2, &val2);
684 | 
685 |     if (res1 == 0 && res2 == 0)
686 |       return 0;
687 | 
688 |     if (val1 == val2)
689 |       continue;
690 | 
691 |     return val1 < val2 ? -1 : 1;
692 |   }
693 | }
