695 | int
696 | as_path_walk(const struct adata *path, uint *pos, uint *val)
697 | {
698 |   if (!path)
699 |     return 0;
700 | 
701 |   const u8 *p = path->data;
702 |   const u8 *q = p + path->length;
703 |   uint n, x = *pos;
704 | 
705 |   while (p < q)
706 |   {
707 |     n = p[1];
708 |     p += 2;
709 | 
710 |     if (x < n)
711 |     {
712 |       *val = get_as(p + x * BS);
713 |       *pos += 1;
714 |       return 1;
715 |     }
716 | 
717 |     p += n * BS;
718 |     x -= n;
719 |   }
720 | 
721 |   return 0;
722 | }
