736 | static int
737 | parse_path(const struct adata *path, struct pm_pos *pp)
738 | {
739 |   const byte *pos = path->data;
740 |   const byte *end = pos + path->length;
741 |   struct pm_pos *op = pp;
742 |   uint i;
743 | 
744 |   while (pos < end)
745 |   {
746 |     uint type = pos[0];
747 |     uint len  = pos[1];
748 |     pos += 2;
749 | 
750 |     switch (type)
751 |     {
752 |     case AS_PATH_SET:
753 |     case AS_PATH_CONFED_SET:
754 |       pp->set = 1;
755 |       pp->mark = 0;
756 |       pp->val.sp = pos - 1;
757 |       pp++;
758 | 
759 |       pos += BS * len;
760 |       break;
761 | 
762 |     case AS_PATH_SEQUENCE:
763 |     case AS_PATH_CONFED_SEQUENCE:
764 |       for (i = 0; i < len; i++)
765 |       {
766 | 	pp->set = 0;
767 | 	pp->mark = 0;
768 | 	pp->val.asn = get_as(pos);
769 | 	pp++;
770 | 
771 | 	pos += BS;
772 |       }
773 |       break;
774 | 
775 |     default:
776 |       bug("Invalid path segment");
777 |     }
778 |   }
779 | 
780 |   return pp - op;
781 | }
