783 | static int
784 | pm_match_val(const struct pm_pos *pos, u32 asn, u32 asn2)
785 | {
786 |   u32 gas;
787 |   if (! pos->set)
788 |     return ((pos->val.asn >= asn) && (pos->val.asn <= asn2));
789 | 
790 |   const u8 *p = pos->val.sp;
791 |   int len = *p++;
792 |   int i;
793 | 
794 |   for (i = 0; i < len; i++)
795 |   {
796 |     gas = get_as(p + i * BS);
797 | 
798 |     if ((gas >= asn) && (gas <= asn2))
799 |       return 1;
800 |   }
801 | 
802 |   return 0;
803 | }
