805 | static int
806 | pm_match_set(const struct pm_pos *pos, const struct f_tree *set)
807 | {
808 |   struct f_val asn = { .type = T_INT };
809 | 
810 |   if (! pos->set)
811 |   {
812 |     asn.val.i = pos->val.asn;
813 |     return !!find_tree(set, &asn);
814 |   }
815 | 
816 |   const u8 *p = pos->val.sp;
817 |   int len = *p++;
818 |   int i;
819 | 
820 |   for (i = 0; i < len; i++)
821 |   {
822 |     asn.val.i = get_as(p + i * BS);
823 |     if (find_tree(set, &asn))
824 |       return 1;
825 |   }
826 | 
827 |   return 0;
828 | }
