830 | static inline int
831 | pm_match(const struct pm_pos *pos, const struct f_path_mask_item *mask, u32 asn, u32 asn2)
832 | {
833 |   return ((mask->kind == PM_QUESTION) ||
834 | 	  ((mask->kind != PM_ASN_SET) ?
835 | 	   pm_match_val(pos, asn, asn2) :
836 | 	   pm_match_set(pos, mask->set)));
