839 | static void
840 | pm_mark(struct pm_pos *pos, int *i, int plen, int *nl, int *nh)
841 | {
842 |   int j = *i;
843 | 
844 |   if (pos[j].set)
845 |     do { pos[j].mark = 1; j++; }
846 |     while ((j < plen) && pos[j].set);
847 |   else
848 |     j++;
849 | 
850 |   pos[j].mark = 1;
851 | 
852 |   /* Update low, high based on first and last marked pos */
853 |   int l = pos[*i].set ? *i : j;
854 | 
855 |   *nl = (*nl < 0) ? l : MIN(*nl, l);
856 |   *nh = MAX(*nh, j);
857 |   *i = j;
858 | }
