860 | /* AS path matching is nontrivial. Because AS path can
861 |  * contain sets, it is not a plain wildcard matching. A set
862 |  * in an AS path is interpreted as it might represent any
863 |  * sequence of AS numbers from that set (possibly with
864 |  * repetitions). So it is also a kind of a pattern,
865 |  * more complicated than a path mask.
866 |  *
867 |  * The algorithm for AS path matching is a variant
868 |  * of nondeterministic finite state machine, where
869 |  * positions in AS path are states, and items in
870 |  * path mask are input for that finite state machine.
871 |  * During execution of the algorithm we maintain a set
872 |  * of marked states - a state is marked if it can be
873 |  * reached by any walk through NFSM with regard to
874 |  * currently processed part of input. When we process
875 |  * next part of mask, we advance each marked state.
876 |  * We start with marked first position, when we
877 |  * run out of marked positions, we reject. When
878 |  * we process the whole mask, we accept if final position
879 |  * (auxiliary position after last real position in AS path)
880 |  * is marked.
881 |  */
882 | int
883 | as_path_match(const struct adata *path, const struct f_path_mask *mask)
884 | {
885 |   struct pm_pos pos[2048 + 1];
886 |   int plen = parse_path(path, pos);
887 |   int l, h, i, nh, nl, last, loop;
888 |   u32 val = 0;
889 |   u32 val2 = 0;
890 | 
891 |   /* l and h are bound of interval of positions where
892 |      are marked states */
893 | 
894 |   pos[plen].set = 0;
895 |   pos[plen].mark = 0;
896 | 
897 |   l = h = loop = 0;
898 |   pos[0].mark = 1;
899 | 
900 |   for (uint m=0; m < mask->len; m++)
901 |     {
902 |       /* We remove this mark to not step after pos[plen] */
903 |       pos[plen].mark = 0;
904 | 
905 |       switch (mask->item[m].kind)
906 | 	{
907 | 	case PM_ASTERISK:
908 | 	  for (i = l; i <= plen; i++)
909 | 	    pos[i].mark = 1;
910 | 	  h = plen;
911 | 	  break;
912 | 
913 | 	case PM_LOOP:
914 | 	  loop = 1;
915 | 	  break;
916 | 
917 | 	case PM_ASN:	/* Define single ASN as ASN..ASN - very narrow interval */
918 | 	  val2 = val = mask->item[m].asn;
919 | 	  goto step;
920 | 	case PM_ASN_EXPR:
921 | 	  bug("Expressions should be evaluated on AS path mask construction.");
922 | 	case PM_ASN_RANGE:
923 | 	  val = mask->item[m].from;
924 | 	  val2 = mask->item[m].to;
925 | 	  goto step;
926 | 	case PM_QUESTION:
927 | 	case PM_ASN_SET:
928 | 	step:
929 | 	  nh = nl = -1;
930 | 	  last = plen;
931 | 	  for (i = h; i >= l; i--)
932 | 	    if (pos[i].mark)
933 | 	      {
934 | 		pos[i].mark = 0;
935 | 		int j = i;
936 | 
937 | 	      match:
938 | 		if (pm_match(pos + j, &mask->item[m], val, val2))
939 | 		{
940 | 		  pm_mark(pos, &j, plen, &nl, &nh);
941 | 		  if (loop && (j < last))
942 | 		    goto match;
943 | 		}
944 | 
945 | 		last = i;
946 | 	      }
947 | 
948 | 	  if (nh < 0)
949 | 	    return 0;
950 | 
951 | 	  h = nh;
952 | 	  l = nl;
953 | 	  loop = 0;
954 | 	  break;
955 | 	}
956 |     }
957 | 
958 |   return pos[plen].mark;
959 | }

