 76 | int
 77 | ec_format(byte *buf, u64 ec)
 78 | {
 79 |   u32 type, key, val;
 80 |   char tbuf[16];
 81 |   const char *kind;
 82 | 
 83 |   type = ec >> 48;
 84 |   kind = ec_subtype_str(type & 0xf0ff);
 85 | 
 86 |   if (!kind) {
 87 |     bsprintf(tbuf, "unknown 0x%x", type);
 88 |     kind = tbuf;
 89 |   }
 90 | 
 91 |   switch (ec >> 56)
 92 |     {
 93 |       /* RFC 4360 3.1.  Two-Octet AS Specific Extended Community */
 94 |     case 0x00:
 95 |     case 0x40:
 96 |       key = (ec >> 32) & 0xFFFF;
 97 |       val = ec;
 98 |       return bsprintf(buf, "(%s, %u, %u)", kind, key, val);
 99 | 
100 |       /* RFC 4360 3.2.  IPv4 Address Specific Extended Community */
101 |     case 0x01:
102 |     case 0x41:
103 |       key = ec >> 16;
104 |       val = ec & 0xFFFF;
105 |       return bsprintf(buf, "(%s, %R, %u)", kind, key, val);
106 | 
107 |       /* RFC 5668  4-Octet AS Specific BGP Extended Community */
108 |     case 0x02:
109 |     case 0x42:
110 |       key = ec >> 16;
111 |       val = ec & 0xFFFF;
112 |       return bsprintf(buf, "(%s, %u, %u)", kind, key, val);
113 | 
114 |       /* Generic format for unknown kinds of extended communities */
115 |     default:
116 |       key = ec >> 32;
117 |       val = ec;
118 |       return bsprintf(buf, "(generic, 0x%x, 0x%x)", key, val);
119 |     }
120 | 
121 | }
