 76 | int
 77 | ec_format(byte *buf, u64 ec)
 78 | {
 79 |   u32 type, key, val;
 80 |   char tbuf[16];
 81 |   const char *kind;
 82 | 
 83 |   type = ec >> 48;
 84 |   kind = ec_subtype_str(type & 0xf0ff);
 85 | 
 86 |   if (!kind) {
 87 |     bsprintf(tbuf, "unknown 0x%x", type);
 88 |     kind = tbuf;
 89 |   }
 90 | 
 91 |   switch (ec >> 56)
 92 |     {
 93 |       /* RFC 4360 3.1.  Two-Octet AS Specific Extended Community */
 94 |     case 0x00:
 95 |     case 0x40:
 96 |       key = (ec >> 32) & 0xFFFF;
 97 |       val = ec;
