 76 | int
 77 | ec_format(byte *buf, u64 ec)
 78 | {
 79 |   u32 type, key, val;
 80 |   char tbuf[16];
 81 |   const char *kind;
 82 | 
 83 |   type = ec >> 48;
 84 |   kind = ec_subtype_str(type & 0xf0ff);
 85 | 
 86 |   if (!kind) {
