110 |       key = ec >> 16;
111 |       val = ec & 0xFFFF;
112 |       return bsprintf(buf, "(%s, %u, %u)", kind, key, val);
113 | 
114 |       /* Generic format for unknown kinds of extended communities */
115 |     default:
116 |       key = ec >> 32;
