101 | /**
102 |  * cli_printf - send reply to a CLI connection
103 |  * @c: CLI connection
104 |  * @code: numeric code of the reply, negative for continuation lines
105 |  * @msg: a printf()-like formatting string.
106 |  *
107 |  * This function send a single line of reply to a given CLI connection.
108 |  * In works in all aspects like bsprintf() except that it automatically
109 |  * prepends the reply line prefix.
110 |  *
111 |  * Please note that if the connection can be already busy sending some
112 |  * data in which case cli_printf() stores the output to a temporary buffer,
113 |  * so please avoid sending a large batch of replies without waiting
114 |  * for the buffers to be flushed.
115 |  *
116 |  * If you want to write to the current CLI output, you can use the cli_msg()
117 |  * macro instead.
118 |  */
119 | void
120 | cli_vprintf(cli *c, int code, const char *msg, va_list args)
121 | {
122 |   byte buf[CLI_LINE_SIZE];
123 |   int cd = code;
124 |   int errcode;
125 |   int size, cnt;
126 | 
127 |   if (cd < 0)
128 |     {
129 |       cd = -cd;
130 |       if (cd == c->last_reply)
131 | 	size = bsprintf(buf, " ");
132 |       else
133 | 	size = bsprintf(buf, "%04d-", cd);
134 |       errcode = -8000;
135 |     }
136 |   else if (cd == CLI_ASYNC_CODE)
137 |     {
138 |       size = 1; buf[0] = '+';
139 |       errcode = cd;
140 |     }
141 |   else
142 |     {
143 |       size = bsprintf(buf, "%04d ", cd);
144 |       errcode = 8000;
145 |       cd = 0;	/* Final message - no more continuation lines */
146 |     }
147 | 
148 |   c->last_reply = cd;
149 |   cnt = bvsnprintf(buf+size, sizeof(buf)-size-1, msg, args);
150 |   if (cnt < 0)
151 |     {
152 |       cli_printf(c, errcode, "<line overflow>");
153 |       return;
154 |     }
155 |   size += cnt;
156 |   buf[size++] = '\n';
157 |   memcpy(cli_alloc_out(c, size), buf, size);
158 | }
