160 | static void
161 | cli_copy_message(cli *c)
162 | {
163 |   byte *p, *q;
164 |   uint cnt = 2;
165 | 
166 |   if (c->ring_overflow)
167 |     {
168 |       byte buf[64];
169 |       int n = bsprintf(buf, "<%d messages lost>\n", c->ring_overflow);
170 |       c->ring_overflow = 0;
171 |       memcpy(cli_alloc_out(c, n), buf, n);
172 |     }
173 |   p = c->ring_read;
174 |   while (*p)
175 |     {
176 |       cnt++;
177 |       p++;
178 |       if (p == c->ring_end)
179 | 	p = c->ring_buf;
180 |       ASSERT(p != c->ring_write);
181 |     }
182 |   c->async_msg_size += cnt;
183 |   q = cli_alloc_out(c, cnt);
184 |   *q++ = '+';
185 |   p = c->ring_read;
186 |   do
187 |     {
188 |       *q = *p++;
189 |       if (p == c->ring_end)
190 | 	p = c->ring_buf;
191 |     }
192 |   while (*q++);
193 |   c->ring_read = p;
194 |   q[-1] = '\n';
195 | }
