230 | static byte *cli_rh_pos;
231 | static uint cli_rh_len;
232 | static int cli_rh_trick_flag;
233 | struct cli *this_cli;
234 | 
235 | static int
236 | cli_cmd_read_hook(byte *buf, uint max, UNUSED int fd)
237 | {
238 |   if (!cli_rh_trick_flag)
239 |     {
240 |       cli_rh_trick_flag = 1;
241 |       buf[0] = '!';
242 |       return 1;
243 |     }
244 |   if (max > cli_rh_len)
245 |     max = cli_rh_len;
246 |   memcpy(buf, cli_rh_pos, max);
247 |   cli_rh_pos += max;
248 |   cli_rh_len -= max;
249 |   return max;
250 | }
251 | 
252 | static void
253 | cli_command(struct cli *c)
254 | {
255 |   struct config f;
256 |   int res;
257 | 
258 |   if (config->cli_debug > 1)
259 |     log(L_TRACE "CLI: %s", c->rx_buf);
260 |   bzero(&f, sizeof(f));
261 |   f.mem = c->parser_pool;
262 |   f.pool = rp_new(c->pool, "Config");
263 |   init_list(&f.symbols);
264 |   cf_read_hook = cli_cmd_read_hook;
265 |   cli_rh_pos = c->rx_buf;
266 |   cli_rh_len = strlen(c->rx_buf);
267 |   cli_rh_trick_flag = 0;
268 |   this_cli = c;
269 |   lp_flush(c->parser_pool);
270 |   res = cli_parse(&f);
271 |   if (!res)
272 |     cli_printf(c, 9001, f.err_msg);
273 | 
274 |   config_free(&f);
275 | }
276 | 
277 | static void
278 | cli_event(void *data)
279 | {
280 |   cli *c = data;
281 |   int err;
282 | 
283 |   while (c->ring_read != c->ring_write &&
284 |       c->async_msg_size < CLI_MAX_ASYNC_QUEUE)
285 |     cli_copy_message(c);
286 | 
287 |   if (c->tx_pos)
288 |     ;
289 |   else if (c->cont)
290 |     c->cont(c);
291 |   else
292 |     {
293 |       err = cli_get_command(c);
294 |       if (!err)
295 | 	return;
296 |       if (err < 0)
297 | 	cli_printf(c, 9000, "Command too long");
298 |       else
299 | 	cli_command(c);
300 |     }
301 | 
302 |   cli_write_trigger(c);
303 | }
304 | 
305 | cli *
306 | cli_new(void *priv, struct cli_config *cf)
307 | {
308 |   pool *p = rp_new(cli_pool, "CLI");
309 |   cli *c = mb_alloc(p, sizeof(cli));
310 | 
311 |   bzero(c, sizeof(cli));
312 |   c->pool = p;
313 |   c->priv = priv;
314 |   c->event = ev_new(p);
315 |   c->event->hook = cli_event;
316 |   c->event->data = c;
317 |   c->cont = cli_hello;
318 |   c->parser_pool = lp_new_default(c->pool);
319 |   c->show_pool = lp_new_default(c->pool);
320 |   c->rx_buf = mb_alloc(c->pool, CLI_RX_BUF_SIZE);
321 | 
322 |   if (cf->restricted)
323 |     c->restricted = 1;
324 | 
325 |   ev_schedule(c->event);
326 |   return c;
327 | }
328 | 
329 | void
330 | cli_kick(cli *c)
331 | {
332 |   if (!c->cont && !c->tx_pos)
333 |     ev_schedule(c->event);
334 | }
