336 | static list cli_log_hooks;
337 | static int cli_log_inited;
338 | 
339 | void
340 | cli_set_log_echo(cli *c, uint mask, uint size)
341 | {
342 |   if (c->ring_buf)
343 |     {
344 |       mb_free(c->ring_buf);
345 |       c->ring_buf = c->ring_end = c->ring_read = c->ring_write = NULL;
346 |       rem_node(&c->n);
347 |     }
348 |   c->log_mask = mask;
349 |   if (mask && size)
350 |     {
351 |       c->ring_buf = mb_alloc(c->pool, size);
352 |       c->ring_end = c->ring_buf + size;
353 |       c->ring_read = c->ring_write = c->ring_buf;
354 |       add_tail(&cli_log_hooks, &c->n);
355 |       c->log_threshold = size / 8;
356 |     }
357 |   c->ring_overflow = 0;
358 | }
359 | 
360 | void
361 | cli_echo(uint class, byte *msg)
362 | {
363 |   unsigned len, free, i, l;
364 |   cli *c;
365 |   byte *m;
366 | 
367 |   if (!cli_log_inited || EMPTY_LIST(cli_log_hooks))
368 |     return;
369 |   len = strlen(msg) + 1;
370 |   WALK_LIST(c, cli_log_hooks)
371 |     {
372 |       if (!(c->log_mask & (1 << class)))
373 | 	continue;
374 |       if (c->ring_read <= c->ring_write)
375 | 	free = (c->ring_end - c->ring_buf) - (c->ring_write - c->ring_read + 1);
376 |       else
377 | 	free = c->ring_read - c->ring_write - 1;
378 |       if ((len > free) ||
379 | 	  (free < c->log_threshold && class < (unsigned) L_INFO[0]))
380 | 	{
381 | 	  c->ring_overflow++;
382 | 	  continue;
383 | 	}
384 |       if (c->ring_read == c->ring_write)
385 | 	ev_schedule(c->event);
386 |       m = msg;
387 |       l = len;
388 |       while (l)
389 | 	{
390 | 	  if (c->ring_read <= c->ring_write)
391 | 	    i = c->ring_end - c->ring_write;
392 | 	  else
393 | 	    i = c->ring_read - c->ring_write;
394 | 	  if (i > l)
395 | 	    i = l;
396 | 	  memcpy(c->ring_write, m, i);
397 | 	  m += i;
398 | 	  l -= i;
399 | 	  c->ring_write += i;
400 | 	  if (c->ring_write == c->ring_end)
401 | 	    c->ring_write = c->ring_buf;
402 | 	}
403 |     }
404 | }
