406 | /* Set time format override for the current session */
407 | void
408 | cli_set_timeformat(cli *c, const struct timeformat tf)
409 | {
410 |   size_t len1 = strlen(tf.fmt1) + 1;
411 |   size_t len2 = tf.fmt2 ? strlen(tf.fmt2) + 1 : 0;
412 | 
413 |   if (len1 > TM_DATETIME_BUFFER_SIZE || len2 > TM_DATETIME_BUFFER_SIZE)
414 |   {
415 |     cli_msg(9003, "Format string too long");
416 |     return;
417 |   }
418 | 
419 |   struct timeformat *old_tf = c->tf;
420 |   struct timeformat *new_tf = mb_allocz(c->pool, sizeof(struct timeformat));
421 |   new_tf->fmt1 = memcpy(mb_alloc(c->pool, len1), tf.fmt1, len1);
422 |   new_tf->fmt2 = tf.fmt2 ? memcpy(mb_alloc(c->pool, len2), tf.fmt2, len2) : NULL;
423 |   new_tf->limit = tf.limit;
424 |   c->tf = new_tf;
425 | 
426 |   if (old_tf)
427 |   {
428 |     mb_free((void *) old_tf->fmt1);
429 |     mb_free((void *) old_tf->fmt2);
430 |     mb_free(old_tf);
431 |   }
432 | 
433 |   cli_msg(0, "");
434 | }
