441 | {
442 |   cli_set_log_echo(c, 0, 0);
443 |   if (c->cleanup)
444 |     c->cleanup(c);
445 |   if (c == cmd_reconfig_stored_cli)
446 |     cmd_reconfig_stored_cli = NULL;
447 |   rfree(c->pool);
