 51 | {
 52 |   RDUMP("\t%I, net %N bc %I -> %I%s%s%s%s\n", a->ip, &a->prefix, a->brd, a->opposite,
 53 | 	(a->flags & IA_PRIMARY) ? " PRIMARY" : "",
 54 | 	(a->flags & IA_SECONDARY) ? " SEC" : "",
 55 | 	(a->flags & IA_HOST) ? " HOST" : "",
