136 | static inline void
137 | if_copy(struct iface *to, struct iface *from)
138 | {
139 |   to->flags = from->flags | (to->flags & IF_TMP_DOWN);
140 |   to->mtu = from->mtu;
141 |   to->master_index = from->master_index;
142 |   to->master = from->master;
143 | }
