341 | void
342 | if_start_update(void)
343 | {
344 |   struct iface *i;
345 |   struct ifa *a;
346 | 
347 |   WALK_LIST(i, iface_list)
348 |     {
349 |       i->flags &= ~IF_UPDATED;
350 |       WALK_LIST(a, i->addrs)
351 | 	a->flags &= ~IA_UPDATED;
352 |     }
353 | }
