476 | static inline void
477 | if_set_preferred(struct ifa **pos, struct ifa *new)
478 | {
479 |   if (*pos)
480 |     (*pos)->flags &= ~IA_PRIMARY;
481 |   if (new)
482 |     new->flags |= IA_PRIMARY;
483 | 
484 |   *pos = new;
