 392 | static int
 393 | mpls_reconfigure_range(struct mpls_domain *m, struct mpls_range *r, struct mpls_range_config *cf)
 394 | {
 395 |   uint last = lmap_last_one_in_range(&m->labels, r->lo, r->hi);
 396 |   if (last == r->hi) last = 0;
 397 | 
 398 |   if ((cf->start > r->lo) || (cf->start + cf->length <= last))
 399 |     return 0;
 400 | 
 401 |   cf->range = r;
 402 |   r->cf->range = NULL;
 403 |   r->cf = cf;
 404 |   r->name = cf->name;
 405 |   r->lo = cf->start;
 406 |   r->hi = cf->start + cf->length;
 407 | 
 408 |   return 1;
 409 | }
