 411 | static void
 412 | mpls_free_range(struct mpls_range *r)
 413 | {
 414 |   ASSERT(r->use_count == 0);
 415 |   ASSERT(r->label_count == 0);
 416 | 
 417 |   rem_node(&r->n);
 418 |   mb_free(r);
 419 | }
