 802 | static slab *
 803 | mpls_slab(struct mpls_fec_map *m, uint type)
 804 | {
 805 |   ASSERT(type <= NET_VPN6);
 806 |   int pos = type ? (type - 1) : 0;
 807 | 
 808 |   if (!m->slabs[pos])
 809 |     m->slabs[pos] = sl_new(m->pool, sizeof(struct mpls_fec) + net_addr_length[pos + 1]);
 810 | 
 811 |   return m->slabs[pos];
 812 | }
