 200 |   init_list(&m->handles);
 201 | 
 202 |   struct mpls_range_config *rc;
 203 |   WALK_LIST(rc, cf->ranges)
 204 |     mpls_new_range(m, rc);
 205 | 
 206 |   add_tail(&mpls_domains, &m->n);
 207 |   cf->domain = m;
 208 | 
 209 |   return m;
 210 | }
