 327 |       add_tail(&mpls_domains, &m->n);
 328 |       continue;
 329 |     }
 330 | 
 331 |     mpls_new_domain(mc);
 332 |   }
 333 | 
 334 |   struct mpls_domain *m, *m2;
 335 |   WALK_LIST_DELSAFE(m, m2, old_domains)
 336 |     mpls_remove_domain(m, old);
 337 | 
 338 |   add_tail_list(&mpls_domains, &old_domains);
 339 | }
