 586 | mpls_channel_reconfigure(struct channel *C, struct channel_config *CC, int *import_changed, int *export_changed UNUSED)
 587 | {
 588 |   struct mpls_channel *c = (void *) C;
 589 |   struct mpls_channel_config *new = (void *) CC;
 590 | 
 591 |   if (new->domain->domain != c->domain)
 592 |     return 0;
