 138 | static int
 139 | mpls_compare_range_configs(const void *r1_, const void *r2_)
 140 | {
 141 |   const struct mpls_range_config * const *r1 = r1_;
 142 |   const struct mpls_range_config * const *r2 = r2_;
 143 | 
 144 |   return uint_cmp((*r1)->start, (*r2)->start);
 145 | }
