 265 | {
 266 |   ASSERT(m->use_count == 0);
 267 |   ASSERT(m->label_count == 0);
 268 |   ASSERT(EMPTY_LIST(m->handles));
 269 | 
 270 |   struct config *cfg = m->removed;
 271 | 
 272 |   m->cf->domain = NULL;
 273 |   rem_node(&m->n);
 274 |   rfree(m->pool);
 275 | 
 276 |   config_del_obstacle(cfg);
 277 | }
