 279 | static void
 280 | mpls_remove_domain(struct mpls_domain *m, struct config *cfg)
 281 | {
 282 |   m->removed = cfg;
 283 |   config_add_obstacle(cfg);
 284 | 
 285 |   if (!m->use_count)
 286 |     mpls_free_domain(m);
 287 | }
