1097 |     r->attrs = rta_do_cow(r->attrs, lp);
1098 | 
1099 |   *ea = (struct ea_list) {
1100 |     .next = r->attrs->eattrs,
1101 |     .flags = EALF_SORTED,
1102 |     .count = 2,
1103 |   };
