 249 | static void
 250 | channel_schedule_feed(struct channel *c, int initial)
 251 | {
 252 |   // DBG("%s: Scheduling meal\n", p->name);
 253 |   ASSERT(c->channel_state == CS_UP);
 254 | 
 255 |   c->export_state = ES_FEEDING;
