 701 | /**
 702 |  * channel_request_feeding - request feeding routes to the channel
 703 |  * @c: given channel
 704 |  *
 705 |  * Sometimes it is needed to send again all routes to the channel. This is
 706 |  * called feeding and can be requested by this function. This would cause
 707 |  * channel export state transition to ES_FEEDING (during feeding) and when
 708 |  * completed, it will switch back to ES_READY. This function can be called
 709 |  * even when feeding is already running, in that case it is restarted.
 710 |  */
 711 | void
 712 | channel_request_feeding(struct channel *c)
 713 | {
 714 |   ASSERT(c->channel_state == CS_UP);
 715 | 
 716 |   CD(c, "Feeding requested");
 717 | 
 718 |   /* Do nothing if we are still waiting for feeding */
 719 |   if (c->export_state == ES_DOWN)
 720 |     return;
 721 | 
 722 |   /* If we are already feeding, we want to restart it */
 723 |   if (c->export_state == ES_FEEDING)
 724 |   {
 725 |     /* Unless feeding is in initial state */
 726 |     if (!c->feed_active)
 727 | 	return;
 728 | 
 729 |     rt_feed_channel_abort(c);
 730 |   }
 731 | 
 732 |   /* Track number of exported routes during refeed */
 733 |   c->refeed_count = 0;
 734 | 
 735 |   channel_schedule_feed(c, 0);	/* Sets ES_FEEDING */
 736 |   channel_log_state_change(c);
 737 | }
