 835 | static int reconfigure_type;  /* Hack to propagate type info to channel_reconfigure() */
 836 | 
 837 | int
 838 | channel_reconfigure(struct channel *c, struct channel_config *cf)
 839 | {
 840 |   /* Touched by reconfiguration */
 841 |   c->stale = 0;
 842 | 
 843 |   /* FIXME: better handle these changes, also handle in_keep_filtered */
 844 |   if ((c->table != cf->table->table) || (cf->ra_mode && (c->ra_mode != cf->ra_mode)))
 845 |     return 0;
 846 | 
 847 |   /* Note that filter_same() requires arguments in (new, old) order */
 848 |   int import_changed = !filter_same(cf->in_filter, c->in_filter);
 849 |   int export_changed = !filter_same(cf->out_filter, c->out_filter);
 850 |   int rpki_reload_changed = (cf->rpki_reload != c->rpki_reload);
 851 | 
 852 |   if (c->preference != cf->preference)
 853 |     import_changed = 1;
 854 | 
 855 |   if (c->merge_limit != cf->merge_limit)
 856 |     export_changed = 1;
 857 | 
 858 |   /* Reconfigure channel fields */
 859 |   c->in_filter = cf->in_filter;
 860 |   c->out_filter = cf->out_filter;
 861 |   c->rx_limit = cf->rx_limit;
 862 |   c->in_limit = cf->in_limit;
 863 |   c->out_limit = cf->out_limit;
 864 | 
 865 |   // c->ra_mode = cf->ra_mode;
 866 |   c->merge_limit = cf->merge_limit;
 867 |   c->preference = cf->preference;
 868 |   c->debug = cf->debug;
 869 |   c->in_keep_filtered = cf->in_keep_filtered;
 870 |   c->rpki_reload = cf->rpki_reload;
 871 | 
 872 |   channel_verify_limits(c);
 873 | 
 874 |   /* Execute channel-specific reconfigure hook */
 875 |   if (c->channel->reconfigure && !c->channel->reconfigure(c, cf, &import_changed, &export_changed))
 876 |     return 0;
 877 | 
 878 |   /* If the channel is not open, it has no routes and we cannot reload it anyways */
 879 |   if (c->channel_state != CS_UP)
 880 |     goto done;
 881 | 
 882 |   /* Update RPKI/ROA subscriptions */
 883 |   if (import_changed || export_changed || rpki_reload_changed)
 884 |   {
 885 |     channel_roa_unsubscribe_all(c);
 886 | 
 887 |     if (c->rpki_reload)
 888 |     {
 889 |       channel_roa_subscribe_filter(c, 1);
 890 |       channel_roa_subscribe_filter(c, 0);
 891 |     }
 892 |   }
 893 | 
 894 |   if (reconfigure_type == RECONFIG_SOFT)
 895 |   {
 896 |     if (import_changed)
 897 |       log(L_INFO "Channel %s.%s changed import", c->proto->name, c->name);
 898 | 
 899 |     if (export_changed)
 900 |       log(L_INFO "Channel %s.%s changed export", c->proto->name, c->name);
 901 | 
 902 |     goto done;
 903 |   }
 904 | 
 905 |   /* Route reload may be not supported */
 906 |   if (import_changed && !channel_reloadable(c))
 907 |     return 0;
 908 | 
 909 |   if (import_changed || export_changed)
 910 |     log(L_INFO "Reloading channel %s.%s", c->proto->name, c->name);
 911 | 
 912 |   if (import_changed)
 913 |     channel_request_reload(c);
 914 | 
 915 |   if (export_changed)
 916 |     channel_request_feeding(c);
 917 | 
 918 | done:
 919 |   CD(c, "Reconfigured");
 920 |   return 1;
 921 | }
