 964 | /**
 965 |  * proto_setup_mpls_map - automatically setup FEC map for protocol
 966 |  * @p: affected protocol
 967 |  * @rts: RTS_* value for generated MPLS routes
 968 |  * @hooks: whether to update rte_insert / rte_remove hooks
 969 |  *
 970 |  * Add, remove or reconfigure MPLS FEC map of the protocol @p, depends on
 971 |  * whether MPLS channel exists, and setup rte_insert / rte_remove hooks with
 972 |  * default MPLS handlers. It is a convenience function supposed to be called
 973 |  * from the protocol start and configure hooks, after reconfiguration of
 974 |  * channels. For shutdown, use proto_shutdown_mpls_map(). If caller uses its own
 975 |  * rte_insert / rte_remove hooks, it is possible to disable updating hooks and
 976 |  * doing that manually.
 977 |  */
 978 | void
 979 | proto_setup_mpls_map(struct proto *p, uint rts, int hooks)
 980 | {
 981 |   struct mpls_fec_map *m = p->mpls_map;
 982 |   struct channel *c = p->mpls_channel;
 983 | 
 984 |   if (!m && c)
 985 |   {
 986 |     /*
 987 |      * Note that when called from a protocol start hook, it is called before
 988 |      * mpls_channel_start(). But FEC map locks MPLS domain internally so it does
 989 |      * not depend on lock from MPLS channel.
 990 |      */
 991 |     p->mpls_map = mpls_fec_map_new(p->pool, c, rts);
 992 |   }
 993 |   else if (m && !c)
 994 |   {
 995 |     /*
 996 |      * Note that for reconfiguration, it is called after the MPLS channel has
 997 |      * been already removed. But removal of active MPLS channel would trigger
 998 |      * protocol restart anyways.
 999 |      */
1000 |     mpls_fec_map_free(m);
1001 |     p->mpls_map = NULL;
1002 |   }
1003 |   else if (m && c)
1004 |   {
1005 |     mpls_fec_map_reconfigure(m, c);
1006 |   }
1007 | 
1008 |   if (hooks)
1009 |   {
1010 |     p->rte_insert = p->mpls_map ? mpls_rte_insert : NULL;
1011 |     p->rte_remove = p->mpls_map ? mpls_rte_remove : NULL;
1012 |   }
1013 | }
1014 | 
1015 | /**
1016 |  * proto_shutdown_mpls_map - automatically shutdown FEC map for protocol
1017 |  * @p: affected protocol
1018 |  * @hooks: whether to update rte_insert / rte_remove hooks
1019 |  *
1020 |  * Remove MPLS FEC map of the protocol @p during protocol shutdown.
1021 |  */
1022 | void
1023 | proto_shutdown_mpls_map(struct proto *p, int hooks)
1024 | {
1025 |   struct mpls_fec_map *m = p->mpls_map;
1026 | 
1027 |   if (!m)
1028 |     return;
1029 | 
1030 |   mpls_fec_map_free(m);
1031 |   p->mpls_map = NULL;
1032 | 
1033 |   if (hooks)
1034 |   {
1035 |     p->rte_insert = NULL;
1036 |     p->rte_remove = NULL;
1037 |   }
1038 | }
