1298 | /**
1299 |  * protos_commit - commit new protocol configuration
1300 |  * @new: new configuration
1301 |  * @old: old configuration or %NULL if it's boot time config
1302 |  * @force_reconfig: force restart of all protocols (used for example
1303 |  * when the router ID changes)
1304 |  * @type: type of reconfiguration (RECONFIG_SOFT or RECONFIG_HARD)
1305 |  *
1306 |  * Scan differences between @old and @new configuration and adjust all
1307 |  * protocol instances to conform to the new configuration.
1308 |  *
1309 |  * When a protocol exists in the new configuration, but it doesn't in the
1310 |  * original one, it's immediately started. When a collision with the other
1311 |  * running protocol would arise, the new protocol will be temporarily stopped
1312 |  * by the locking mechanism.
1313 |  *
1314 |  * When a protocol exists in the old configuration, but it doesn't in the
1315 |  * new one, it's shut down and deleted after the shutdown completes.
1316 |  *
1317 |  * When a protocol exists in both configurations, the core decides
1318 |  * whether it's possible to reconfigure it dynamically - it checks all
1319 |  * the core properties of the protocol (changes in filters are ignored
1320 |  * if type is RECONFIG_SOFT) and if they match, it asks the
1321 |  * reconfigure() hook of the protocol to see if the protocol is able
1322 |  * to switch to the new configuration.  If it isn't possible, the
1323 |  * protocol is shut down and a new instance is started with the new
1324 |  * configuration after the shutdown is completed.
1325 |  */
1326 | void
1327 | protos_commit(struct config *new, struct config *old, int force_reconfig, int type)
1328 | {
1329 |   struct proto_config *oc, *nc;
1330 |   struct symbol *sym;
1331 |   struct proto *p;
1332 |   node *n;
1333 | 
1334 | 
1335 |   DBG("protos_commit:\n");
1336 |   if (old)
1337 |   {
1338 |     WALK_LIST(oc, old->protos)
1339 |     {
1340 |       p = oc->proto;
1341 |       sym = cf_find_symbol(new, oc->name);
1342 | 
1343 |       /* Handle dynamic protocols */
1344 |       if (!sym && oc->parent && !new->shutdown)
1345 |       {
1346 | 	struct symbol *parsym = cf_find_symbol(new, oc->parent->name);
1347 | 	if (parsym && parsym->class == SYM_PROTO)
1348 | 	{
1349 | 	  /* This is hack, we would like to share config, but we need to copy it now */
1350 | 	  new_config = new;
1351 | 	  cfg_mem = new->mem;
1352 | 	  new->current_scope = new->root_scope;
1353 | 	  sym = cf_get_symbol(new, oc->name);
1354 | 	  proto_clone_config(sym, parsym->proto);
1355 | 	  new_config = NULL;
1356 | 	  cfg_mem = NULL;
1357 | 	}
1358 |       }
1359 | 
1360 |       if (sym && sym->class == SYM_PROTO && !new->shutdown)
1361 |       {
1362 | 	/* Found match, let's check if we can smoothly switch to new configuration */
1363 | 	/* No need to check description */
1364 | 	nc = sym->proto;
1365 | 	nc->proto = p;
1366 | 
1367 | 	/* We will try to reconfigure protocol p */
1368 | 	if (! force_reconfig && proto_reconfigure(p, oc, nc, type))
1369 | 	  continue;
1370 | 
1371 | 	if (nc->parent)
1372 | 	{
1373 | 	  proto_undef_clone(sym, nc);
1374 | 	  goto remove;
1375 | 	}
1376 | 
1377 | 	/* Unsuccessful, we will restart it */
1378 | 	if (!p->disabled && !nc->disabled)
1379 | 	  log(L_INFO "Restarting protocol %s", p->name);
1380 | 	else if (p->disabled && !nc->disabled)
1381 | 	  log(L_INFO "Enabling protocol %s", p->name);
1382 | 	else if (!p->disabled && nc->disabled)
1383 | 	  log(L_INFO "Disabling protocol %s", p->name);
1384 | 
1385 | 	p->down_code = nc->disabled ? PDC_CF_DISABLE : PDC_CF_RESTART;
1386 | 	p->cf_new = nc;
1387 |       }
1388 |       else if (!new->shutdown)
1389 |       {
1390 |       remove:
1391 | 	log(L_INFO "Removing protocol %s", p->name);
1392 | 	p->down_code = PDC_CF_REMOVE;
1393 | 	p->cf_new = NULL;
1394 |       }
1395 |       else if (new->gr_down)
1396 |       {
1397 | 	p->down_code = PDC_CMD_GR_DOWN;
1398 | 	p->cf_new = NULL;
1399 |       }
1400 |       else /* global shutdown */
1401 |       {
1402 | 	p->down_code = PDC_CMD_SHUTDOWN;
1403 | 	p->cf_new = NULL;
1404 |       }
1405 | 
1406 |       p->reconfiguring = 1;
1407 |       config_add_obstacle(old);
1408 |       proto_rethink_goal(p);
1409 |     }
1410 |   }
1411 | 
1412 |   struct proto *first_dev_proto = NULL;
1413 | 
1414 |   n = NODE &(proto_list.head);
1415 |   WALK_LIST(nc, new->protos)
1416 |     if (!nc->proto)
1417 |     {
1418 |       /* Not a first-time configuration */
1419 |       if (old)
1420 | 	log(L_INFO "Adding protocol %s", nc->name);
1421 | 
1422 |       p = proto_init(nc, n);
1423 |       n = NODE p;
1424 | 
1425 |       if (p->proto == &proto_unix_iface)
1426 | 	first_dev_proto = p;
1427 |     }
1428 |     else
1429 |       n = NODE nc->proto;
1430 | 
1431 |   DBG("Protocol start\n");
1432 | 
1433 |   /* Start device protocol first */
1434 |   if (first_dev_proto)
1435 |     proto_rethink_goal(first_dev_proto);
1436 | 
1437 |   /* Determine router ID for the first time - it has to be here and not in
1438 |      global_commit() because it is postponed after start of device protocol */
1439 |   if (!config->router_id)
1440 |   {
1441 |     config->router_id = if_choose_router_id(config->router_id_from, 0);
1442 |     if (!config->router_id)
1443 |       die("Cannot determine router ID, please configure it manually");
1444 |   }
1445 | 
1446 |   /* Start all new protocols */
1447 |   WALK_LIST_DELSAFE(p, n, proto_list)
1448 |     proto_rethink_goal(p);
1449 | }
1450 | 
1451 | static void
1452 | proto_rethink_goal(struct proto *p)
1453 | {
1454 |   struct protocol *q;
1455 |   byte goal;
1456 | 
1457 |   if (p->reconfiguring && !p->active)
1458 |   {
1459 |     struct proto_config *nc = p->cf_new;
1460 |     node *n = p->n.prev;
1461 |     DBG("%s has shut down for reconfiguration\n", p->name);
1462 |     p->cf->proto = NULL;
1463 |     config_del_obstacle(p->cf->global);
1464 |     proto_remove_channels(p);
1465 |     rem_node(&p->n);
1466 |     rfree(p->event);
1467 |     mb_free(p->message);
1468 |     mb_free(p);
1469 |     if (!nc)
1470 |       return;
1471 |     p = proto_init(nc, n);
1472 |   }
1473 | 
1474 |   /* Determine what state we want to reach */
1475 |   if (p->disabled || p->reconfiguring)
1476 |     goal = PS_DOWN;
1477 |   else
1478 |     goal = PS_UP;
1479 | 
1480 |   q = p->proto;
1481 |   if (goal == PS_UP)
1482 |   {
1483 |     if (!p->active)
1484 |     {
1485 |       /* Going up */
1486 |       DBG("Kicking %s up\n", p->name);
1487 |       PD(p, "Starting");
1488 |       proto_start(p);
1489 |       proto_notify_state(p, (q->start ? q->start(p) : PS_UP));
1490 |     }
1491 |   }
1492 |   else
1493 |   {
1494 |     if (p->proto_state == PS_START || p->proto_state == PS_UP)
1495 |     {
1496 |       /* Going down */
1497 |       DBG("Kicking %s down\n", p->name);
1498 |       PD(p, "Shutting down");
1499 |       proto_notify_state(p, (q->shutdown ? q->shutdown(p) : PS_DOWN));
1500 |     }
1501 |   }
1502 | }
1503 | 
1504 | struct proto *
1505 | proto_spawn(struct proto_config *cf, uint disabled)
1506 | {
1507 |   struct proto *p = proto_init(cf, TAIL(proto_list));
1508 |   p->disabled = disabled;
1509 |   proto_rethink_goal(p);
1510 |   return p;
1511 | }
