1785 | static inline void
1786 | proto_schedule_down(struct proto *p, byte restart, byte code)
1787 | {
1788 |   /* Does not work for other states (even PS_START) */
1789 |   ASSERT(p->proto_state == PS_UP);
1790 | 
1791 |   /* Scheduled restart may change to shutdown, but not otherwise */
1792 |   if (p->down_sched == PDS_DISABLE)
1793 |     return;
1794 | 
1795 |   p->down_sched = restart ? PDS_RESTART : PDS_DISABLE;
1796 |   p->down_code = code;
1797 |   tm_start_max(proto_shutdown_timer, restart ? 250 MS : 0);
1798 | }
