1800 | /**
1801 |  * proto_set_message - set administrative message to protocol
1802 |  * @p: protocol
1803 |  * @msg: message
1804 |  * @len: message length (-1 for NULL-terminated string)
1805 |  *
1806 |  * The function sets administrative message (string) related to protocol state
1807 |  * change. It is called by the nest code for manual enable/disable/restart
1808 |  * commands all routes to the protocol, and by protocol-specific code when the
1809 |  * protocol state change is initiated by the protocol. Using NULL message clears
1810 |  * the last message. The message string may be either NULL-terminated or with an
1811 |  * explicit length.
1812 |  */
1813 | void
1814 | proto_set_message(struct proto *p, char *msg, int len)
1815 | {
1816 |   mb_free(p->message);
1817 |   p->message = NULL;
1818 | 
1819 |   if (!msg || !len)
1820 |     return;
1821 | 
1822 |   if (len < 0)
1823 |     len = strlen(msg);
1824 | 
1825 |   if (!len)
1826 |     return;
1827 | 
1828 |   p->message = mb_alloc(proto_pool, len + 1);
1829 |   memcpy(p->message, msg, len);
1830 |   p->message[len] = 0;
1831 | }
