1834 | static const char *
1835 | channel_limit_name(struct channel_limit *l)
1836 | {
1837 |   const char *actions[] = {
1838 |     [PLA_WARN] = "warn",
1839 |     [PLA_BLOCK] = "block",
1840 |     [PLA_RESTART] = "restart",
1841 |     [PLA_DISABLE] = "disable",
1842 |   };
