1977 | /**
1978 |  * proto_notify_state - notify core about protocol state change
1979 |  * @p: protocol the state of which has changed
1980 |  * @ps: the new status
1981 |  *
1982 |  * Whenever a state of a protocol changes due to some event internal
1983 |  * to the protocol (i.e., not inside a start() or shutdown() hook),
1984 |  * it should immediately notify the core about the change by calling
1985 |  * proto_notify_state() which will write the new state to the &proto
1986 |  * structure and take all the actions necessary to adapt to the new
1987 |  * state. State change to PS_DOWN immediately frees resources of protocol
1988 |  * and might execute start callback of protocol; therefore,
1989 |  * it should be used at tail positions of protocol callbacks.
1990 |  */
1991 | void
1992 | proto_notify_state(struct proto *p, uint state)
1993 | {
1994 |   uint ps = p->proto_state;
1995 | 
1996 |   DBG("%s reporting state transition %s -> %s\n", p->name, p_states[ps], p_states[state]);
1997 |   if (state == ps)
1998 |     return;
1999 | 
2000 |   p->proto_state = state;
2001 |   p->last_state_change = current_time();
2002 | 
2003 |   switch (state)
2004 |   {
2005 |   case PS_START:
2006 |     ASSERT(ps == PS_DOWN || ps == PS_UP);
2007 | 
2008 |     if (ps == PS_DOWN)
2009 |       proto_do_start(p);
2010 |     else
2011 |       proto_do_pause(p);
2012 |     break;
2013 | 
2014 |   case PS_UP:
2015 |     ASSERT(ps == PS_DOWN || ps == PS_START);
2016 | 
2017 |     if (ps == PS_DOWN)
2018 |       proto_do_start(p);
2019 | 
2020 |     proto_do_up(p);
2021 |     break;
2022 | 
2023 |   case PS_STOP:
2024 |     ASSERT(ps == PS_START || ps == PS_UP);
2025 | 
2026 |     proto_do_stop(p);
2027 |     break;
2028 | 
2029 |   case PS_DOWN:
2030 |     if (ps != PS_STOP)
2031 |       proto_do_stop(p);
2032 | 
2033 |     proto_do_down(p);
2034 |     break;
2035 | 
2036 |   default:
2037 |     bug("%s: Invalid state %d", p->name, ps);
2038 |   }
2039 | 
2040 |   proto_log_state_change(p);
2041 | }
