 144 | /**
 145 |  * proto_add_channel - connect protocol to a routing table
 146 |  * @p: protocol instance
 147 |  * @cf: channel configuration
 148 |  *
 149 |  * This function creates a channel between the protocol instance @p and the
 150 |  * routing table specified in the configuration @cf, making the protocol hear
 151 |  * all changes in the table and allowing the protocol to update routes in the
 152 |  * table.
 153 |  *
 154 |  * The channel is linked in the protocol channel list and when active also in
 155 |  * the table channel list. Channels are allocated from the global resource pool
 156 |  * (@proto_pool) and they are automatically freed when the protocol is removed.
 157 |  */
 158 | 
 159 | struct channel *
 160 | proto_add_channel(struct proto *p, struct channel_config *cf)
 161 | {
 162 |   struct channel *c = mb_allocz(proto_pool, cf->channel->channel_size);
 163 | 
 164 |   c->name = cf->name;
 165 |   c->channel = cf->channel;
 166 |   c->proto = p;
 167 |   c->table = cf->table->table;
 168 |   rt_lock_table(c->table);
 169 | 
 170 |   c->in_filter = cf->in_filter;
 171 |   c->out_filter = cf->out_filter;
 172 |   c->rx_limit = cf->rx_limit;
 173 |   c->in_limit = cf->in_limit;
 174 |   c->out_limit = cf->out_limit;
 175 | 
 176 |   c->net_type = cf->net_type;
 177 |   c->ra_mode = cf->ra_mode;
 178 |   c->preference = cf->preference;
 179 |   c->debug = cf->debug;
 180 |   c->merge_limit = cf->merge_limit;
 181 |   c->in_keep_filtered = cf->in_keep_filtered;
 182 |   c->rpki_reload = cf->rpki_reload;
 183 |   c->bmp_hack = cf->bmp_hack;
 184 | 
 185 |   c->channel_state = CS_DOWN;
 186 |   c->export_state = ES_DOWN;
 187 |   c->last_state_change = current_time();
 188 |   c->reloadable = 1;
 189 | 
 190 |   init_list(&c->roa_subscriptions);
 191 | 
 192 |   CALL(c->channel->init, c, cf);
 193 | 
 194 |   add_tail(&p->channels, &c->n);
 195 | 
 196 |   CD(c, "Connected to table %s", c->table->name);
 197 | 
 198 |   return c;
 199 | }
