 261 | static void
 262 | channel_feed_loop(void *ptr)
 263 | {
 264 |   struct channel *c = ptr;
 265 | 
 266 |   if (c->export_state != ES_FEEDING)
 267 |     return;
 268 | 
 269 |   /* Start feeding */
 270 |   if (!c->feed_active)
 271 |   {
 272 |     if (c->proto->feed_begin)
 273 |       c->proto->feed_begin(c, !c->refeeding);
 274 | 
 275 |     c->refeed_pending = 0;
 276 |   }
 277 | 
 278 |   // DBG("Feeding protocol %s continued\n", p->name);
 279 |   if (!rt_feed_channel(c))
 280 |   {
 281 |     ev_schedule_work(c->feed_event);
 282 |     return;
 283 |   }
 284 | 
 285 |   /* Reset export limit if the feed ended with acceptable number of exported routes */
 286 |   struct channel_limit *l = &c->out_limit;
 287 |   if (c->refeeding &&
 288 |       (l->state == PLS_BLOCKED) &&
 289 |       (c->refeed_count <= l->limit) &&
 290 |       (c->stats.exp_routes <= l->limit))
 291 |   {
 292 |     log(L_INFO "Protocol %s resets route export limit (%u)", c->proto->name, l->limit);
 293 |     channel_reset_limit(&c->out_limit);
 294 | 
 295 |     /* Continue in feed - it will process routing table again from beginning */
 296 |     c->refeed_count = 0;
 297 |     ev_schedule_work(c->feed_event);
 298 |     return;
 299 |   }
 300 | 
 301 |   // DBG("Feeding protocol %s finished\n", p->name);
 302 |   c->export_state = ES_READY;
 303 |   channel_log_state_change(c);
 304 | 
 305 |   if (c->proto->feed_end)
 306 |     c->proto->feed_end(c);
 307 | 
 308 |   /* Restart feeding */
 309 |   if (c->refeed_pending)
 310 |     channel_request_feeding(c);
 311 | }
