 388 | static void
 389 | channel_roa_subscribe_filter(struct channel *c, int dir)
 390 | {
 391 |   const struct filter *f = dir ? c->in_filter : c->out_filter;
 392 |   struct rtable *tab;
 393 |   int valid = 1, found = 0;
 394 | 
 395 |   if ((f == FILTER_ACCEPT) || (f == FILTER_REJECT))
 396 |     return;
 397 | 
 398 |   /* No automatic reload for non-reloadable channels */
 399 |   if (dir && !channel_reloadable(c))
 400 |     valid = 0;
 401 | 
 402 | #ifdef CONFIG_BGP
 403 |   /* No automatic reload for BGP channels without in_table / out_table */
 404 |   if (c->channel == &channel_bgp)
 405 |     valid = dir ? !!c->in_table : !!c->out_table;
 406 | #endif
 407 | 
 408 |   struct filter_iterator fit;
 409 |   FILTER_ITERATE_INIT(&fit, f, c->proto->pool);
 410 | 
 411 |   FILTER_ITERATE(&fit, fi)
 412 |   {
 413 |     switch (fi->fi_code)
 414 |     {
 415 |     case FI_ROA_CHECK_IMPLICIT:
 416 |       tab = fi->i_FI_ROA_CHECK_IMPLICIT.rtc->table;
 417 |       if (valid) channel_roa_subscribe(c, tab, dir);
 418 |       found = 1;
 419 |       break;
 420 | 
 421 |     case FI_ROA_CHECK_EXPLICIT:
 422 |       tab = fi->i_FI_ROA_CHECK_EXPLICIT.rtc->table;
 423 |       if (valid) channel_roa_subscribe(c, tab, dir);
 424 |       found = 1;
 425 |       break;
 426 | 
 427 |     case FI_ASPA_CHECK_EXPLICIT:
 428 |       tab = fi->i_FI_ASPA_CHECK_EXPLICIT.rtc->table;
 429 |       if (valid) channel_roa_subscribe(c, tab, dir);
 430 |       found = 1;
 431 |       break;
 432 |     default:
 433 |       break;
 434 |     }
 435 |   }
 436 |   FILTER_ITERATE_END;
 437 | 
 438 |   FILTER_ITERATE_CLEANUP(&fit);
 439 | 
 440 |   if (!valid && found)
 441 |     log(L_WARN "%s.%s: Automatic RPKI reload not active for %s",
 442 | 	c->proto->name, c->name ?: "?", dir ? "import" : "export");
 443 | }
