 552 | static void
 553 | channel_do_start(struct channel *c)
 554 | {
 555 |   add_tail(&c->table->channels, &c->table_node);
 556 |   c->proto->active_channels++;
 557 | 
 558 |   c->feed_event = ev_new_init(c->proto->pool, channel_feed_loop, c);
 559 | 
 560 |   bmap_init(&c->export_map, c->proto->pool, 1024);
 561 |   memset(&c->stats, 0, sizeof(struct proto_stats));
 562 | 
 563 |   channel_reset_limit(&c->rx_limit);
 564 |   channel_reset_limit(&c->in_limit);
 565 |   channel_reset_limit(&c->out_limit);
 566 | 
 567 |   CALL(c->channel->start, c);
 568 | }
