 570 | static void
 571 | channel_do_up(struct channel *c)
 572 | {
 573 |   /* Register RPKI/ROA subscriptions */
 574 |   if (c->rpki_reload)
 575 |   {
 576 |     channel_roa_subscribe_filter(c, 1);
 577 |     channel_roa_subscribe_filter(c, 0);
 578 |   }
 579 | }
