 581 | static void
 582 | channel_do_flush(struct channel *c)
 583 | {
 584 |   if (!c->bmp_hack)
 585 |     rt_schedule_prune(c->table);
 586 | 
 587 |   c->gr_wait = 0;
 588 |   if (c->gr_lock)
 589 |     channel_graceful_restart_unlock(c);
 590 | 
 591 |   CALL(c->channel->shutdown, c);
 592 | 
 593 |   /* This have to be done in here, as channel pool is freed before channel_do_down() */
 594 |   bmap_free(&c->export_map);
 595 |   c->in_table = NULL;
 596 |   c->reload_event = NULL;
 597 |   c->out_table = NULL;
 598 | 
 599 |   channel_roa_unsubscribe_all(c);
 600 | }
