 602 | static void
 603 | channel_do_down(struct channel *c)
 604 | {
 605 |   ASSERT(!c->feed_active && !c->reload_active);
 606 | 
 607 |   rem_node(&c->table_node);
 608 |   c->proto->active_channels--;
 609 | 
 610 |   if ((c->stats.imp_routes + c->stats.filt_routes) != 0)
 611 |     log(L_ERR "%s: Channel %s is down but still has some routes", c->proto->name, c->name);
 612 | 
 613 |   // bmap_free(&c->export_map);
 614 |   memset(&c->stats, 0, sizeof(struct proto_stats));
 615 | 
 616 |   c->in_table = NULL;
 617 |   c->reload_event = NULL;
 618 |   c->out_table = NULL;
 619 | 
 620 |   /* The in_table and out_table are going to be freed by freeing their resource pools. */
 621 | 
 622 |   CALL(c->channel->cleanup, c);
 623 | 
 624 |   /* Schedule protocol shutddown */
 625 |   if (proto_is_done(c->proto))
 626 |     ev_schedule(c->proto->event);
 627 | }
