 629 | void
 630 | channel_set_state(struct channel *c, uint state)
 631 | {
 632 |   uint cs = c->channel_state;
 633 |   uint es = c->export_state;
 634 | 
 635 |   DBG("%s reporting channel %s state transition %s -> %s\n", c->proto->name, c->name, c_states[cs], c_states[state]);
 636 |   if (state == cs)
 637 |     return;
 638 | 
 639 |   c->channel_state = state;
 640 |   c->last_state_change = current_time();
 641 | 
 642 |   switch (state)
 643 |   {
 644 |   case CS_START:
 645 |     ASSERT(cs == CS_DOWN || cs == CS_UP);
 646 | 
 647 |     if (cs == CS_DOWN)
 648 |       channel_do_start(c);
 649 | 
 650 |     if (es != ES_DOWN)
 651 |       channel_stop_export(c);
 652 | 
 653 |     if (c->in_table && (cs == CS_UP))
 654 |       channel_reset_import(c);
 655 | 
 656 |     if (c->out_table && (cs == CS_UP))
 657 |       channel_reset_export(c);
 658 | 
 659 |     break;
 660 | 
 661 |   case CS_UP:
 662 |     ASSERT(cs == CS_DOWN || cs == CS_START);
 663 | 
 664 |     if (cs == CS_DOWN)
 665 |       channel_do_start(c);
 666 | 
 667 |     if (!c->gr_wait && c->proto->rt_notify)
 668 |       channel_start_export(c);
 669 | 
 670 |     channel_do_up(c);
 671 |     break;
 672 | 
 673 |   case CS_FLUSHING:
 674 |     ASSERT(cs == CS_START || cs == CS_UP);
 675 | 
 676 |     if (es != ES_DOWN)
 677 |       channel_stop_export(c);
 678 | 
 679 |     if (c->in_table && (cs == CS_UP))
 680 |       channel_reset_import(c);
 681 | 
 682 |     if (c->out_table && (cs == CS_UP))
 683 |       channel_reset_export(c);
 684 | 
 685 |     channel_do_flush(c);
 686 |     break;
 687 | 
 688 |   case CS_DOWN:
 689 |     ASSERT(cs == CS_FLUSHING);
 690 | 
 691 |     channel_do_down(c);
 692 |     break;
 693 | 
 694 |   default:
 695 |     ASSERT(0);
 696 |   }
 697 | 
 698 |   channel_log_state_change(c);
 699 | }
