 924 | int
 925 | proto_configure_channel(struct proto *p, struct channel **pc, struct channel_config *cf)
 926 | {
 927 |   struct channel *c = *pc;
 928 | 
 929 |   if (!c && cf)
 930 |   {
 931 |     /* We could add the channel, but currently it would just stay in down state
 932 |        until protocol is restarted, so it is better to force restart anyways. */
 933 |     if (p->proto_state != PS_DOWN)
 934 |     {
 935 |       log(L_INFO "Cannot add channel %s.%s", p->name, cf->name);
 936 |       return 0;
 937 |     }
 938 | 
 939 |     *pc = proto_add_channel(p, cf);
 940 |   }
 941 |   else if (c && !cf)
 942 |   {
 943 |     if (c->channel_state != CS_DOWN)
 944 |     {
 945 |       log(L_INFO "Cannot remove channel %s.%s", c->proto->name, c->name);
 946 |       return 0;
 947 |     }
 948 | 
 949 |     proto_remove_channel(p, c);
 950 |     *pc = NULL;
 951 |   }
 952 |   else if (c && cf)
 953 |   {
 954 |     if (!channel_reconfigure(c, cf))
 955 |     {
 956 |       log(L_INFO "Cannot reconfigure channel %s.%s", c->proto->name, c->name);
 957 |       return 0;
 958 |     }
 959 |   }
 960 | 
 961 |   return 1;
 962 | }
