1131 | /**
1132 |  * proto_config_new - create a new protocol configuration
1133 |  * @pr: protocol the configuration will belong to
1134 |  * @class: SYM_PROTO or SYM_TEMPLATE
1135 |  *
1136 |  * Whenever the configuration file says that a new instance
1137 |  * of a routing protocol should be created, the parser calls
1138 |  * proto_config_new() to create a configuration entry for this
1139 |  * instance (a structure staring with the &proto_config header
1140 |  * containing all the generic items followed by protocol-specific
1141 |  * ones). Also, the configuration entry gets added to the list
1142 |  * of protocol instances kept in the configuration.
1143 |  *
1144 |  * The function is also used to create protocol templates (when class
1145 |  * SYM_TEMPLATE is specified), the only difference is that templates
1146 |  * are not added to the list of protocol instances and therefore not
1147 |  * initialized during protos_commit()).
1148 |  */
1149 | void *
1150 | proto_config_new(struct protocol *pr, int class)
1151 | {
1152 |   struct proto_config *cf = cfg_allocz(pr->config_size);
1153 | 
1154 |   if (class == SYM_PROTO)
1155 |     add_tail(&new_config->protos, &cf->n);
1156 | 
1157 |   cf->global = new_config;
1158 |   cf->protocol = pr;
1159 |   cf->name = pr->name;
1160 |   cf->class = class;
1161 |   cf->debug = new_config->proto_default_debug;
1162 |   cf->mrtdump = new_config->proto_default_mrtdump;
1163 | 
1164 |   init_list(&cf->channels);
