1170 | /**
1171 |  * proto_copy_config - copy a protocol configuration
1172 |  * @dest: destination protocol configuration
1173 |  * @src: source protocol configuration
1174 |  *
1175 |  * Whenever a new instance of a routing protocol is created from the
1176 |  * template, proto_copy_config() is called to copy a content of
1177 |  * the source protocol configuration to the new protocol configuration.
1178 |  * Name, class and a node in protos list of @dest are kept intact.
1179 |  * copy_config() protocol hook is used to copy protocol-specific data.
1180 |  */
1181 | void
1182 | proto_copy_config(struct proto_config *dest, struct proto_config *src)
1183 | {
1184 |   struct channel_config *cc;
1185 |   node old_node;
1186 |   int old_class;
1187 |   const char *old_name;
1188 | 
1189 |   if (dest->protocol != src->protocol)
1190 |     cf_error("Can't copy configuration from a different protocol type");
1191 | 
1192 |   if (dest->protocol->copy_config == NULL)
1193 |     cf_error("Inheriting configuration for %s is not supported", src->protocol->name);
1194 | 
1195 |   DBG("Copying configuration from %s to %s\n", src->name, dest->name);
1196 | 
1197 |   /*
1198 |    * Copy struct proto_config here. Keep original node, class and name.
1199 |    * protocol-specific config copy is handled by protocol copy_config() hook
1200 |    */
1201 | 
1202 |   old_node = dest->n;
1203 |   old_class = dest->class;
1204 |   old_name = dest->name;
1205 | 
1206 |   memcpy(dest, src, src->protocol->config_size);
1207 | 
1208 |   dest->n = old_node;
1209 |   dest->class = old_class;
1210 |   dest->name = old_name;
1211 |   init_list(&dest->channels);
1212 | 
1213 |   WALK_LIST(cc, src->channels)
1214 |     channel_copy_config(cc, dest);
1215 | 
1216 |   /* FIXME: allow for undefined copy_config */
1217 |   dest->protocol->copy_config(dest, src);
1218 | }
