1220 | void
1221 | proto_clone_config(struct symbol *sym, struct proto_config *parent)
1222 | {
1223 |   struct proto_config *cf = proto_config_new(parent->protocol, SYM_PROTO);
1224 |   proto_copy_config(cf, parent);
1225 |   cf->name = sym->name;
1226 |   cf->proto = NULL;
1227 |   cf->parent = parent;
1228 | 
1229 |   sym->class = cf->class;
1230 |   sym->proto = cf;
1231 | }
