1267 | static int
1268 | proto_reconfigure(struct proto *p, struct proto_config *oc, struct proto_config *nc, int type)
1269 | {
1270 |   /* If the protocol is DOWN, we just restart it */
1271 |   if (p->proto_state == PS_DOWN)
1272 |     return 0;
1273 | 
1274 |   /* If there is a too big change in core attributes, ... */
1275 |   if ((nc->protocol != oc->protocol) ||
1276 |       (nc->net_type != oc->net_type) ||
1277 |       (nc->disabled != p->disabled) ||
1278 |       (nc->vrf != oc->vrf) ||
1279 |       (nc->vrf_set != oc->vrf_set))
1280 |     return 0;
1281 | 
1282 |   p->name = nc->name;
1283 |   p->debug = nc->debug;
1284 |   p->mrtdump = nc->mrtdump;
1285 |   reconfigure_type = type;
1286 | 
1287 |   /* Execute protocol specific reconfigure hook */
1288 |   if (!p->proto->reconfigure || !p->proto->reconfigure(p, nc))
1289 |     return 0;
1290 | 
1291 |   DBG("\t%s: same\n", oc->name);
1292 |   PD(p, "Reconfigured");
1293 |   p->cf = nc;
1294 | 
1295 |   return 1;
1296 | }
