1514 | /**
1515 |  * DOC: Graceful restart recovery
1516 |  *
1517 |  * Graceful restart of a router is a process when the routing plane (e.g. BIRD)
1518 |  * restarts but both the forwarding plane (e.g kernel routing table) and routing
1519 |  * neighbors keep proper routes, and therefore uninterrupted packet forwarding
1520 |  * is maintained.
1521 |  *
1522 |  * BIRD implements graceful restart recovery by deferring export of routes to
1523 |  * protocols until routing tables are refilled with the expected content. After
1524 |  * start, protocols generate routes as usual, but routes are not propagated to
1525 |  * them, until protocols report that they generated all routes. After that,
1526 |  * graceful restart recovery is finished and the export (and the initial feed)
1527 |  * to protocols is enabled.
1528 |  *
1529 |  * When graceful restart recovery need is detected during initialization, then
1530 |  * enabled protocols are marked with @gr_recovery flag before start. Such
1531 |  * protocols then decide how to proceed with graceful restart, participation is
1532 |  * voluntary. Protocols could lock the recovery for each channel by function
1533 |  * channel_graceful_restart_lock() (state stored in @gr_lock flag), which means
1534 |  * that they want to postpone the end of the recovery until they converge and
1535 |  * then unlock it. They also could set @gr_wait before advancing to %PS_UP,
1536 |  * which means that the core should defer route export to that channel until
1537 |  * the end of the recovery. This should be done by protocols that expect their
1538 |  * neigbors to keep the proper routes (kernel table, BGP sessions with BGP
1539 |  * graceful restart capability).
1540 |  *
1541 |  * The graceful restart recovery is finished when either all graceful restart
1542 |  * locks are unlocked or when graceful restart wait timer fires.
1543 |  *
1544 |  */
1545 | 
1546 | static void graceful_restart_done(timer *t);
1547 | 
1548 | /**
1549 |  * graceful_restart_recovery - request initial graceful restart recovery
1550 |  *
1551 |  * Called by the platform initialization code if the need for recovery
1552 |  * after graceful restart is detected during boot. Have to be called
1553 |  * before protos_commit().
1554 |  */
1555 | void
1556 | graceful_restart_recovery(void)
1557 | {
1558 |   graceful_restart_state = GRS_INIT;
1559 | }
1560 | 
1561 | /**
1562 |  * graceful_restart_init - initialize graceful restart
1563 |  *
1564 |  * When graceful restart recovery was requested, the function starts an active
1565 |  * phase of the recovery and initializes graceful restart wait timer. The
1566 |  * function have to be called after protos_commit().
1567 |  */
1568 | void
1569 | graceful_restart_init(void)
1570 | {
1571 |   if (!graceful_restart_state)
1572 |     return;
1573 | 
1574 |   log(L_INFO "Graceful restart started");
1575 | 
1576 |   if (!graceful_restart_locks)
1577 |   {
1578 |     graceful_restart_done(NULL);
1579 |     return;
1580 |   }
1581 | 
1582 |   graceful_restart_state = GRS_ACTIVE;
1583 |   gr_wait_timer = tm_new_init(proto_pool, graceful_restart_done, NULL, 0, 0);
1584 |   tm_start(gr_wait_timer, config->gr_wait S);
1585 | }
1586 | 
1587 | /**
1588 |  * graceful_restart_done - finalize graceful restart
1589 |  * @t: unused
1590 |  *
1591 |  * When there are no locks on graceful restart, the functions finalizes the
1592 |  * graceful restart recovery. Protocols postponing route export until the end of
1593 |  * the recovery are awakened and the export to them is enabled. All other
1594 |  * related state is cleared. The function is also called when the graceful
1595 |  * restart wait timer fires (but there are still some locks).
1596 |  */
1597 | static void
1598 | graceful_restart_done(timer *t UNUSED)
1599 | {
1600 |   log(L_INFO "Graceful restart done");
1601 |   graceful_restart_state = GRS_DONE;
1602 | 
1603 |   struct proto *p;
1604 |   WALK_LIST(p, proto_list)
1605 |   {
1606 |     if (!p->gr_recovery)
1607 |       continue;
1608 | 
1609 |     struct channel *c;
1610 |     WALK_LIST(c, p->channels)
1611 |     {
1612 |       /* Resume postponed export of routes */
1613 |       if ((c->channel_state == CS_UP) && c->gr_wait && c->proto->rt_notify)
1614 | 	channel_start_export(c);
1615 | 
1616 |       /* Cleanup */
1617 |       c->gr_wait = 0;
1618 |       c->gr_lock = 0;
1619 |     }
1620 | 
1621 |     p->gr_recovery = 0;
1622 |   }
1623 | 
1624 |   graceful_restart_locks = 0;
1625 | }
1626 | 
1627 | void
1628 | graceful_restart_show_status(void)
1629 | {
1630 |   if (graceful_restart_state != GRS_ACTIVE)
1631 |     return;
1632 | 
1633 |   cli_msg(-24, "Graceful restart recovery in progress");
1634 |   cli_msg(-24, "  Waiting for %d channels to recover", graceful_restart_locks);
1635 |   cli_msg(-24, "  Wait timer is %t/%u", tm_remains(gr_wait_timer), config->gr_wait);
1636 | }
1637 | 
1638 | /**
1639 |  * channel_graceful_restart_lock - lock graceful restart by channel
1640 |  * @p: channel instance
1641 |  *
1642 |  * This function allows a protocol to postpone the end of graceful restart
1643 |  * recovery until it converges. The lock is removed when the protocol calls
1644 |  * channel_graceful_restart_unlock() or when the channel is closed.
1645 |  *
1646 |  * The function have to be called during the initial phase of graceful restart
1647 |  * recovery and only for protocols that are part of graceful restart (i.e. their
1648 |  * @gr_recovery is set), which means it should be called from protocol start
1649 |  * hooks.
1650 |  */
1651 | void
1652 | channel_graceful_restart_lock(struct channel *c)
1653 | {
1654 |   ASSERT(graceful_restart_state == GRS_INIT);
1655 |   ASSERT(c->proto->gr_recovery);
1656 | 
1657 |   if (c->gr_lock)
1658 |     return;
1659 | 
1660 |   c->gr_lock = 1;
1661 |   graceful_restart_locks++;
1662 | }
1663 | 
1664 | /**
1665 |  * channel_graceful_restart_unlock - unlock graceful restart by channel
1666 |  * @p: channel instance
1667 |  *
1668 |  * This function unlocks a lock from channel_graceful_restart_lock(). It is also
1669 |  * automatically called when the lock holding protocol went down.
1670 |  */
1671 | void
1672 | channel_graceful_restart_unlock(struct channel *c)
1673 | {
1674 |   if (!c->gr_lock)
1675 |     return;
1676 | 
1677 |   c->gr_lock = 0;
1678 |   graceful_restart_locks--;
1679 | 
1680 |   if ((graceful_restart_state == GRS_ACTIVE) && !graceful_restart_locks)
1681 |     tm_start(gr_wait_timer, 0);
1682 | }
