1765 | static void
1766 | proto_shutdown_loop(timer *t UNUSED)
1767 | {
1768 |   struct proto *p, *p_next;
1769 | 
1770 |   WALK_LIST_DELSAFE(p, p_next, proto_list)
1771 |     if (p->down_sched)
1772 |     {
1773 |       proto_restart = (p->down_sched == PDS_RESTART);
1774 | 
1775 |       p->disabled = 1;
1776 |       proto_rethink_goal(p);
1777 |       if (proto_restart)
1778 |       {
1779 | 	p->disabled = 0;
1780 | 	proto_rethink_goal(p);
1781 |       }
1782 |     }
