1849 |  * @c: channel
1850 |  * @l: limit being hit
1851 |  * @dir: limit direction (PLD_*)
1852 |  * @rt_count: the number of routes
1853 |  *
1854 |  * The function is called by the route processing core when limit @l
1855 |  * is breached. It activates the limit and tooks appropriate action
1856 |  * according to @l->action.
1857 |  */
1858 | void
1859 | channel_notify_limit(struct channel *c, struct channel_limit *l, int dir, u32 rt_count)
1860 | {
1861 |   const char *dir_name[PLD_MAX] = { "receive", "import" , "export" };
1862 |   const byte dir_down[PLD_MAX] = { PDC_RX_LIMIT_HIT, PDC_IN_LIMIT_HIT, PDC_OUT_LIMIT_HIT };
1863 |   struct proto *p = c->proto;
1864 | 
1865 |   if (l->state == PLS_BLOCKED)
1866 |     return;
1867 | 
1868 |   /* For warning action, we want the log message every time we hit the limit */
1869 |   if (!l->state || ((l->action == PLA_WARN) && (rt_count == l->limit)))
1870 |     log(L_WARN "Protocol %s hits route %s limit (%d), action: %s",
1871 | 	p->name, dir_name[dir], l->limit, channel_limit_name(l));
1872 | 
1873 |   switch (l->action)
1874 |   {
1875 |   case PLA_WARN:
1876 |     l->state = PLS_ACTIVE;
1877 |     break;
1878 | 
1879 |   case PLA_BLOCK:
1880 |     l->state = PLS_BLOCKED;
1881 |     break;
1882 | 
1883 |   case PLA_RESTART:
1884 |   case PLA_DISABLE:
1885 |     l->state = PLS_BLOCKED;
1886 |     if (p->proto_state == PS_UP)
1887 |       proto_schedule_down(p, l->action == PLA_RESTART, dir_down[dir]);
1888 |     break;
1889 |   }
