168 |   char *name;				/* Name of this table */
169 |   list channels;			/* List of attached channels (struct channel) */
170 |   uint addr_type;			/* Type of address data stored in table (NET_*) */
171 |   u32 debug;				/* Debugging flags (D_*) */
172 |   int pipe_busy;			/* Pipe loop detection */
173 |   int use_count;			/* Number of protocols using this table */
174 |   u32 rt_count;				/* Number of routes in the table */
175 | 
176 |   byte internal;			/* Internal table of a protocol */
177 | 
178 |   struct hmap id_map;
179 |   struct hostcache *hostcache;
180 |   struct rtable_config *config;		/* Configuration of this table */
181 |   struct config *deleted;		/* Table doesn't exist in current configuration,
182 | 					 * delete as soon as use_count becomes 0 and remove
183 | 					 * obstacle from this routing table.
184 | 					 */
185 |   struct event *rt_event;		/* Routing table event */
186 |   struct timer *prune_timer;		/* Timer for periodic pruning / GC */
187 |   btime last_rt_change;			/* Last time when route changed */
188 |   btime base_settle_time;		/* Start time of rtable settling interval */
189 |   btime gc_time;			/* Time of last GC */
190 |   uint gc_counter;			/* Number of operations since last GC */
191 |   byte prune_state;			/* Table prune state, 1 -> scheduled, 2-> running */
192 |   byte prune_trie;			/* Prune prefix trie during next table prune */
193 |   byte hcu_scheduled;			/* Hostcache update is scheduled */
194 |   byte nhu_state;			/* Next Hop Update state */
