729 | static inline void
730 | rta_set_recursive_next_hop(rtable *dep, rta *a, rtable *tab, ip_addr gw, ip_addr ll, mpls_label_stack *mls)
731 | {
732 |   rta_apply_hostentry(a, rt_get_hostentry(tab, gw, ll, dep), mls);
