 215 | int
 216 | nexthop__same(struct nexthop *x, struct nexthop *y)
 217 | {
 218 |   for (; x && y; x = x->next, y = y->next)
 219 |     if (!nexthop_equal_1(x, y) ||
 220 | 	(x->labels_orig != y->labels_orig))
 221 |       return 0;
 222 | 
 223 |   return x == y;
 224 | }
