 288 |  * that case the caller should not access these lists after that. To eliminate
 289 |  * issues with deallocation of these lists, the caller should use some form of
 290 |  * bulk deallocation (e.g. stack or linpool) to free these nodes when the
 291 |  * resulting list is no longer needed. When reusability is not set, the
 292 |  * corresponding lists are not modified nor linked from the resulting list.
 293 |  */
 294 | struct nexthop *
 295 | nexthop_merge(struct nexthop *x, struct nexthop *y, int rx, int ry, int max, linpool *lp)
 296 | {
 297 |   struct nexthop *root = NULL;
 298 |   struct nexthop **n = &root;
 299 | 
 300 |   while ((x || y) && max--)
 301 |   {
 302 |     int cmp = nexthop_compare_node(x, y);
 303 | 
 304 |     if (cmp < 0)
 305 |     {
 306 |       ASSUME(x);
 307 |       *n = rx ? x : nexthop_copy_node(x, lp);
 308 |       x = x->next;
 309 |     }
 310 |     else if (cmp > 0)
 311 |     {
 312 |       ASSUME(y);
 313 |       *n = ry ? y : nexthop_copy_node(y, lp);
 314 |       y = y->next;
 315 |     }
 316 |     else
 317 |     {
 318 |       ASSUME(x && y);
 319 |       *n = rx ? x : (ry ? y : nexthop_copy_node(x, lp));
 320 |       x = x->next;
 321 |       y = y->next;
 322 |     }
 323 |     n = &((*n)->next);
 324 |   }
 325 |   *n = NULL;
 326 | 
 327 |   return root;
 328 | }
 329 | 
 330 | void
 331 | nexthop_insert(struct nexthop **n, struct nexthop *x)
 332 | {
 333 |   for (; *n; n = &((*n)->next))
 334 |   {
 335 |     int cmp = nexthop_compare_node(*n, x);
 336 | 
 337 |     if (cmp < 0)
 338 |       continue;
 339 |     else if (cmp > 0)
 340 |       break;
 341 |     else
 342 |       return;
 343 |   }
 344 | 
 345 |   x->next = *n;
 346 |   *n = x;
 347 | }
 348 | 
 349 | struct nexthop *
 350 | nexthop_sort(struct nexthop *x)
 351 | {
 352 |   struct nexthop *s = NULL;
 353 | 
 354 |   /* Simple insert-sort */
 355 |   while (x)
 356 |   {
 357 |     struct nexthop *n = x;
 358 |     x = n->next;
 359 |     n->next = NULL;
 360 | 
 361 |     nexthop_insert(&s, n);
 362 |   }
 363 | 
 364 |   return s;
 365 | }
 366 | 
 367 | int
 368 | nexthop_is_sorted(struct nexthop *x)
 369 | {
 370 |   for (; x && x->next; x = x->next)
 371 |     if (nexthop_compare_node(x, x->next) >= 0)
 372 |       return 0;
 373 | 
 374 |   return 1;
 375 | }
