 897 | 	  return;
 898 | 	}
 899 |       if (i)
 900 | 	*buf++ = ' ';
 901 | 
 902 |       buf += bsprintf(buf, "%02x", ad->data[i]);
 903 |     }
 904 | 
 905 |   *buf = 0;
 906 |   return;
