 426 | 
 427 | static inline eattr *
 428 | ea__find(ea_list *e, unsigned id)
 429 | {
 430 |   eattr *a;
 431 |   int l, r, m;
 432 | 
 433 |   while (e)
 434 |     {
 435 |       if (e->flags & EALF_BISECT)
 436 | 	{
 437 | 	  l = 0;
 438 | 	  r = e->count - 1;
 439 | 	  while (l <= r)
 440 | 	    {
 441 | 	      m = (l+r) / 2;
 442 | 	      a = &e->attrs[m];
 443 | 	      if (a->id == id)
 444 | 		return a;
 445 | 	      else if (a->id < id)
 446 | 		l = m+1;
 447 | 	      else
 448 | 		r = m-1;
 449 | 	    }
 450 | 	}
 451 |       else
 452 | 	for(m=0; m<e->count; m++)
 453 | 	  if (e->attrs[m].id == id)
 454 | 	    return &e->attrs[m];
 455 |       e = e->next;
 456 |     }
 457 |   return NULL;
 458 | }
