 945 | /**
 946 |  * ea_show - print an &eattr to CLI
 947 |  * @c: destination CLI
 948 |  * @e: attribute to be printed
 949 |  *
 950 |  * This function takes an extended attribute represented by its &eattr
 951 |  * structure and prints it to the CLI according to the type information.
 952 |  *
 953 |  * If the protocol defining the attribute provides its own
 954 |  * get_attr() hook, it's consulted first.
 955 |  */
 956 | void
 957 | ea_show(struct cli *c, const eattr *e)
 958 | {
 959 |   struct protocol *p;
 960 |   int status = GA_UNKNOWN;
 961 |   const struct adata *ad = (e->type & EAF_EMBEDDED) ? NULL : e->u.ptr;
 962 |   byte buf[CLI_MSG_SIZE];
 963 |   byte *pos = buf, *end = buf + sizeof(buf);
 964 | 
 965 |   if (EA_IS_CUSTOM(e->id))
 966 |     {
 967 |       const char *name = ea_custom_name(e->id);
 968 |       if (name)
 969 |         {
 970 | 	  pos += bsprintf(pos, "%s", name);
 971 | 	  status = GA_NAME;
 972 | 	}
 973 |       else
 974 | 	pos += bsprintf(pos, "%02x.", EA_PROTO(e->id));
 975 |     }
 976 |   else if (p = class_to_protocol[EA_PROTO(e->id)])
 977 |     {
 978 |       pos += bsprintf(pos, "%s.", p->name);
 979 |       if (p->get_attr)
 980 | 	status = p->get_attr(e, pos, end - pos);
 981 |       pos += strlen(pos);
 982 |     }
 983 |   else if (EA_PROTO(e->id))
 984 |     pos += bsprintf(pos, "%02x.", EA_PROTO(e->id));
 985 |   else
 986 |     status = get_generic_attr(e, &pos, end - pos);
 987 | 
 988 |   if (status < GA_NAME)
 989 |     pos += bsprintf(pos, "%02x", EA_ID(e->id));
 990 |   if (status < GA_FULL)
 991 |     {
 992 |       *pos++ = ':';
 993 |       *pos++ = ' ';
 994 | 
 995 |       if (e->undef)
 996 | 	bsprintf(pos, "undefined");
 997 |       else
 998 |       switch (e->type & EAF_TYPE_MASK)
 999 | 	{
1000 | 	case EAF_TYPE_INT:
1001 | 	  bsprintf(pos, "%u", e->u.data);
1002 | 	  break;
1003 | 	case EAF_TYPE_OPAQUE:
1004 | 	  opaque_format(ad, pos, end - pos);
1005 | 	  break;
1006 | 	case EAF_TYPE_IP_ADDRESS:
1007 | 	  bsprintf(pos, "%I", *(ip_addr *) ad->data);
1008 | 	  break;
1009 | 	case EAF_TYPE_ROUTER_ID:
1010 | 	  bsprintf(pos, "%R", e->u.data);
1011 | 	  break;
1012 | 	case EAF_TYPE_AS_PATH:
1013 | 	  as_path_format(ad, pos, end - pos);
1014 | 	  break;
1015 | 	case EAF_TYPE_BITFIELD:
1016 | 	  bsprintf(pos, "%08x", e->u.data);
1017 | 	  break;
1018 | 	case EAF_TYPE_INT_SET:
1019 | 	  ea_show_int_set(c, ad, ISF_COMMUNITY_LIST, pos, buf, end);
1020 | 	  return;
1021 | 	case EAF_TYPE_EC_SET:
1022 | 	  ea_show_ec_set(c, ad, pos, buf, end);
1023 | 	  return;
1024 | 	case EAF_TYPE_LC_SET:
1025 | 	  ea_show_lc_set(c, ad, pos, buf, end);
1026 | 	  return;
1027 | 	case EAF_TYPE_STRING:
1028 | 	  bsnprintf(pos, end - pos, "%s", (const char *) ad->data);
1029 | 	  break;
1030 | 	default:
1031 | 	  bsprintf(pos, "<type %02x>", e->type);
1032 | 	}
1033 |     }
1034 | 
1035 |   if (status != GA_HIDDEN)
1036 |     cli_printf(c, -1012, "\t%s", buf);
1037 | }
