1117 | /**
1118 |  * ea_append - concatenate &ea_list's
1119 |  * @to: destination list (can be %NULL)
1120 |  * @what: list to be appended (can be %NULL)
1121 |  *
1122 |  * This function appends the &ea_list @what at the end of
1123 |  * &ea_list @to and returns a pointer to the resulting list.
1124 |  */
1125 | ea_list *
1126 | ea_append(ea_list *to, ea_list *what)
1127 | {
1128 |   ea_list *res;
1129 | 
1130 |   if (!to)
1131 |     return what;
1132 |   res = to;
1133 |   while (to->next)
1134 |     to = to->next;
1135 |   to->next = what;
1136 |   return res;
1137 | }
