1297 | rta *
1298 | rta_do_cow(rta *o, linpool *lp)
1299 | {
1300 |   rta *r = lp_alloc(lp, RTA_MAX_SIZE);
1301 |   memcpy(r, o, rta_size(o));
1302 |   for (struct nexthop **nhn = &(r->nh.next), *nho = o->nh.next; nho; nho = nho->next)
1303 |     {
1304 |       *nhn = lp_alloc(lp, nexthop_size(nho));
1305 |       memcpy(*nhn, nho, nexthop_size(nho));
1306 |       nhn = &((*nhn)->next);
1307 |     }
1308 |   r->cached = 0;
1309 |   r->uc = 0;
1310 |   return r;
1311 | }
