 173 | static inline u32
 174 | nexthop_hash(struct nexthop *x)
 175 | {
 176 |   u32 h = 0;
 177 |   for (; x; x = x->next)
 178 |   {
 179 |     h ^= ipa_hash(x->gw) ^ (h << 5) ^ (h >> 9);
 180 | 
 181 |     for (int i = 0; i < x->labels; i++)
 182 |       h ^= x->label[i] ^ (h << 6) ^ (h >> 7);
 183 |   }
 184 | 
 185 |   return h;
 186 | }
