 226 | static int
 227 | nexthop_compare_node(const struct nexthop *x, const struct nexthop *y)
 228 | {
 229 |   int r;
 230 | 
 231 |   if (!x)
 232 |     return 1;
 233 | 
 234 |   if (!y)
 235 |     return -1;
 236 | 
 237 |   /* Should we also compare flags ? */
 238 | 
 239 |   r = ((int) y->weight) - ((int) x->weight);
 240 |   if (r)
 241 |     return r;
 242 | 
 243 |   r = ipa_compare(x->gw, y->gw);
 244 |   if (r)
 245 |     return r;
 246 | 
 247 |   r = ((int) y->labels) - ((int) x->labels);
 248 |   if (r)
 249 |     return r;
 250 | 
 251 |   for (int i = 0; i < y->labels; i++)
 252 |   {
 253 |     r = ((int) y->label[i]) - ((int) x->label[i]);
 254 |     if (r)
 255 |       return r;
 256 |   }
 257 | 
 258 |   return ((int) x->iface->index) - ((int) y->iface->index);
 259 | }
