 330 | void
 331 | nexthop_insert(struct nexthop **n, struct nexthop *x)
 332 | {
 333 |   for (; *n; n = &((*n)->next))
 334 |   {
 335 |     int cmp = nexthop_compare_node(*n, x);
 336 | 
 337 |     if (cmp < 0)
 338 |       continue;
 339 |     else if (cmp > 0)
 340 |       break;
 341 |     else
 342 |       return;
 343 |   }
 344 | 
 345 |   x->next = *n;
 346 |   *n = x;
 347 | }
