 383 | static struct nexthop *
 384 | nexthop_copy(struct nexthop *o)
 385 | {
 386 |   struct nexthop *first = NULL;
 387 |   struct nexthop **last = &first;
 388 | 
 389 |   for (; o; o = o->next)
 390 |     {
 391 |       struct nexthop *n = sl_allocz(nexthop_slab(o));
 392 |       n->gw = o->gw;
 393 |       n->iface = o->iface;
 394 |       n->next = NULL;
 395 |       n->flags = o->flags;
 396 |       n->weight = o->weight;
 397 |       n->labels_orig = o->labels_orig;
 398 |       n->labels = o->labels;
 399 |       for (int i=0; i<o->labels; i++)
 400 | 	n->label[i] = o->label[i];
 401 | 
 402 |       *last = n;
 403 |       last = &(n->next);
 404 |     }
 405 | 
 406 |   return first;
 407 | }
