 892 |   for(i = 0; i < ad->length; i++)
 893 |     {
 894 |       if (buf > bound)
 895 | 	{
 896 | 	  strcpy(buf, " ...");
 897 | 	  return;
 898 | 	}
 899 |       if (i)
 900 | 	*buf++ = ' ';
 901 | 
 902 |       buf += bsprintf(buf, "%02x", ad->data[i]);
 903 |     }
 904 | 
 905 |   *buf = 0;
