 203 | int
 204 | nexthop_equal_(struct nexthop *x, struct nexthop *y)
 205 | {
 206 |   /* Like nexthop_same(), but ignores difference between local labels and labels from hostentry */
 207 | 
 208 |   for (; x && y; x = x->next, y = y->next)
 209 |     if (!nexthop_equal_1(x, y))
 210 |       return 0;
 211 | 
 212 |   return x == y;
 213 | }
