 860 | void
 861 | ea_format_bitfield(const struct eattr *a, byte *buf, int bufsize, const char **names, int min, int max)
 862 | {
 863 |   byte *bound = buf + bufsize - 32;
 864 |   u32 data = a->u.data;
 865 |   int i;
 866 | 
 867 |   for (i = min; i < max; i++)
 868 |     if ((data & (1u << i)) && names[i])
 869 |     {
 870 |       if (buf > bound)
 871 |       {
 872 | 	strcpy(buf, " ...");
 873 | 	return;
 874 |       }
 875 | 
 876 |       buf += bsprintf(buf, " %s", names[i]);
 877 |       data &= ~(1u << i);
 878 |     }
 879 | 
 880 |   if (data)
 881 |     bsprintf(buf, " %08x", data);
 882 | 
 883 |   return;
 884 | }
