1160 | static inline uint
1161 | rta_hash(rta *a)
1162 | {
1163 |   u64 h;
1164 |   mem_hash_init(&h);
1165 | #define MIX(f) mem_hash_mix(&h, &(a->f), sizeof(a->f));
1166 | #define BMIX(f) mem_hash_mix_num(&h, a->f);
1167 |   MIX(hostentry);
1168 |   MIX(from);
1169 |   MIX(igp_metric);
1170 |   BMIX(source);
1171 |   BMIX(scope);
1172 |   BMIX(dest);
1173 |   MIX(pref);
1174 | #undef MIX
1175 | 
1176 |   return mem_hash_value(&h) ^ nexthop_hash(&(a->nh)) ^ ea_hash(a->eattrs);
1177 | }
1178 | 
1179 | static inline int
1180 | rta_same(rta *x, rta *y)
1181 | {
1182 |   return (x->source == y->source &&
1183 | 	  x->scope == y->scope &&
1184 | 	  x->dest == y->dest &&
1185 | 	  x->igp_metric == y->igp_metric &&
1186 | 	  ipa_equal(x->from, y->from) &&
1187 | 	  x->hostentry == y->hostentry &&
1188 | 	  nexthop_same(&(x->nh), &(y->nh)) &&
1189 | 	  ea_same(x->eattrs, y->eattrs));
1190 | }
1191 | 
1192 | static inline slab *
1193 | rta_slab(rta *a)
1194 | {
1195 |   return rta_slab_[a->nh.labels > 2 ? 3 : a->nh.labels];
1196 | }
1197 | 
1198 | static rta *
1199 | rta_copy(rta *o)
1200 | {
1201 |   rta *r = sl_alloc(rta_slab(o));
1202 | 
1203 |   memcpy(r, o, rta_size(o));
1204 |   r->uc = 1;
1205 |   r->nh.next = nexthop_copy(o->nh.next);
1206 |   r->eattrs = ea_list_copy(o->eattrs);
1207 |   return r;
1208 | }
1209 | 
1210 | static inline void
1211 | rta_insert(rta *r)
1212 | {
1213 |   uint h = r->hash_key & rta_cache_mask;
1214 |   r->next = rta_hash_table[h];
1215 |   if (r->next)
1216 |     r->next->pprev = &r->next;
1217 |   r->pprev = &rta_hash_table[h];
1218 |   rta_hash_table[h] = r;
1219 | }
1220 | 
1221 | static void
1222 | rta_rehash(void)
1223 | {
1224 |   uint ohs = rta_cache_size;
1225 |   uint h;
1226 |   rta *r, *n;
1227 |   rta **oht = rta_hash_table;
1228 | 
1229 |   rta_cache_size = 2*rta_cache_size;
1230 |   DBG("Rehashing rta cache from %d to %d entries.\n", ohs, rta_cache_size);
1231 |   rta_alloc_hash();
1232 |   for(h=0; h<ohs; h++)
1233 |     for(r=oht[h]; r; r=n)
1234 |       {
1235 | 	n = r->next;
1236 | 	rta_insert(r);
1237 |       }
1238 |   mb_free(oht);
1239 | }
1240 | 
1241 | /**
1242 |  * rta_lookup - look up a &rta in attribute cache
1243 |  * @o: a un-cached &rta
1244 |  *
1245 |  * rta_lookup() gets an un-cached &rta structure and returns its cached
1246 |  * counterpart. It starts with examining the attribute cache to see whether
1247 |  * there exists a matching entry. If such an entry exists, it's returned and
1248 |  * its use count is incremented, else a new entry is created with use count
1249 |  * set to 1.
1250 |  *
1251 |  * The extended attribute lists attached to the &rta are automatically
1252 |  * converted to the normalized form.
1253 |  */
1254 | rta *
1255 | rta_lookup(rta *o)
1256 | {
1257 |   rta *r;
1258 |   uint h;
1259 | 
1260 |   ASSERT(!o->cached);
1261 |   if (o->eattrs)
1262 |     ea_normalize(o->eattrs);
1263 | 
1264 |   h = rta_hash(o);
1265 |   for(r=rta_hash_table[h & rta_cache_mask]; r; r=r->next)
1266 |     if (r->hash_key == h && rta_same(r, o))
1267 |       return rta_clone(r);
1268 | 
1269 |   r = rta_copy(o);
1270 |   r->hash_key = h;
1271 |   r->cached = 1;
1272 |   rt_lock_hostentry(r->hostentry);
1273 |   rta_insert(r);
1274 | 
1275 |   if (++rta_cache_count > rta_cache_limit)
1276 |     rta_rehash();
1277 | 
1278 |   return r;
1279 | }
1280 | 
1281 | void
1282 | rta__free(rta *a)
1283 | {
1284 |   ASSERT(rta_cache_count && a->cached);
1285 |   rta_cache_count--;
1286 |   *a->pprev = a->next;
1287 |   if (a->next)
1288 |     a->next->pprev = a->pprev;
1289 |   rt_unlock_hostentry(a->hostentry);
1290 |   if (a->nh.next)
1291 |     nexthop_free(a->nh.next);
1292 |   ea_free(a->eattrs);
1293 |   a->cached = 0;
1294 |   sl_free(a);
1295 | }
1296 | 
1297 | rta *
1298 | rta_do_cow(rta *o, linpool *lp)
1299 | {
1300 |   rta *r = lp_alloc(lp, RTA_MAX_SIZE);
1301 |   memcpy(r, o, rta_size(o));
1302 |   for (struct nexthop **nhn = &(r->nh.next), *nho = o->nh.next; nho; nho = nho->next)
1303 |     {
1304 |       *nhn = lp_alloc(lp, nexthop_size(nho));
1305 |       memcpy(*nhn, nho, nexthop_size(nho));
1306 |       nhn = &((*nhn)->next);
1307 |     }
1308 |   r->cached = 0;
1309 |   r->uc = 0;
1310 |   return r;
1311 | }
