 261 | static inline struct nexthop *
 262 | nexthop_copy_node(const struct nexthop *src, linpool *lp)
 263 | {
 264 |   struct nexthop *n = lp_alloc(lp, nexthop_size(src));
 265 | 
 266 |   memcpy(n, src, nexthop_size(src));
 267 |   n->next = NULL;
 268 | 
 269 |   return n;
 270 | }
