 409 | static void
 410 | nexthop_free(struct nexthop *o)
 411 | {
 412 |   struct nexthop *n;
 413 | 
 414 |   while (o)
 415 |     {
 416 |       n = o->next;
 417 |       sl_free(o);
 418 |       o = n;
 419 |     }
 420 | }
