1328 | 
1329 |   RDUMP("pref=%d uc=%d %s %s%s h=%04x",
1330 | 	a->pref, a->uc, rts[a->source], ip_scope_text(a->scope),
1331 | 	rtd[a->dest], a->hash_key);
