 367 | int
 368 | nexthop_is_sorted(struct nexthop *x)
 369 | {
 370 |   for (; x && x->next; x = x->next)
 371 |     if (nexthop_compare_node(x, x->next) >= 0)
 372 |       return 0;
 373 | 
 374 |   return 1;
 375 | }
