 399 |       for (int i=0; i<o->labels; i++)
 400 | 	n->label[i] = o->label[i];
 401 | 
 402 |       *last = n;
 403 |       last = &(n->next);
 404 |     }
 405 | 
 406 |   return first;
 407 | }
