 574 | static inline void
 575 | ea_do_sort(ea_list *e)
 576 | {
 577 |   unsigned n = e->count;
 578 |   eattr *a = e->attrs;
 579 |   eattr *b = alloca(n * sizeof(eattr));
 580 |   unsigned s, ss;
 581 | 
 582 |   /* We need to use a stable sorting algorithm, hence mergesort */
 583 |   do
 584 |     {
 585 |       s = ss = 0;
 586 |       while (s < n)
 587 | 	{
 588 | 	  eattr *p, *q, *lo, *hi;
 589 | 	  p = b;
 590 | 	  ss = s;
 591 | 	  *p++ = a[s++];
 592 | 	  while (s < n && p[-1].id <= a[s].id)
 593 | 	    *p++ = a[s++];
 594 | 	  if (s < n)
 595 | 	    {
 596 | 	      q = p;
 597 | 	      *p++ = a[s++];
 598 | 	      while (s < n && p[-1].id <= a[s].id)
 599 | 		*p++ = a[s++];
 600 | 	      lo = b;
 601 | 	      hi = q;
 602 | 	      s = ss;
 603 | 	      while (lo < q && hi < p)
 604 | 		if (lo->id <= hi->id)
 605 | 		  a[s++] = *lo++;
 606 | 		else
 607 | 		  a[s++] = *hi++;
 608 | 	      while (lo < q)
 609 | 		a[s++] = *lo++;
 610 | 	      while (hi < p)
 611 | 		a[s++] = *hi++;
 612 | 	    }
 613 | 	}
 614 |     }
 615 |   while (ss);
 616 | }
