1084 | /**
1085 |  * ea_hash - calculate an &ea_list hash key
1086 |  * @e: attribute list
1087 |  *
1088 |  * ea_hash() takes an extended attribute list and calculated a hopefully
1089 |  * uniformly distributed hash value from its contents.
1090 |  */
1091 | inline uint
1092 | ea_hash(ea_list *e)
1093 | {
1094 |   const u64 mul = 0x68576150f3d6847;
1095 |   u64 h = 0xafcef24eda8b29;
1096 |   int i;
1097 | 
1098 |   if (e)			/* Assuming chain of length 1 */
1099 |     {
1100 |       for(i=0; i<e->count; i++)
1101 | 	{
1102 | 	  struct eattr *a = &e->attrs[i];
1103 | 	  h ^= a->id; h *= mul;
1104 | 	  if (a->type & EAF_EMBEDDED)
1105 | 	    h ^= a->u.data;
1106 | 	  else
1107 | 	    {
1108 | 	      const struct adata *d = a->u.ptr;
1109 | 	      h ^= mem_hash(d->data, d->length);
1110 | 	    }
1111 | 	  h *= mul;
1112 | 	}
1113 |     }
1114 |   return (h >> 32) ^ (h & 0xffffffff);
1115 | }
