625 | /**
626 |  * fib_check - audit a FIB
627 |  * @f: FIB to be checked
628 |  *
629 |  * This debugging function audits a FIB by checking its internal consistency.
630 |  * Use when you suspect somebody of corrupting innocent data structures.
631 |  */
632 | void
633 | fib_check(struct fib *f)
634 | {
635 |   uint i, ec, nulls;
636 | 
637 |   ec = 0;
638 |   for(i=0; i<f->hash_size; i++)
639 |     {
640 |       struct fib_node *n;
641 |       for(n=f->hash_table[i]; n; n=n->next)
642 | 	{
643 | 	  struct fib_iterator *j, *j0;
644 | 	  uint h0 = fib_hash(f, n->addr);
645 | 	  if (h0 != i)
646 | 	    bug("fib_check: mishashed %x->%x (order %d)", h0, i, f->hash_order);
647 | 	  j0 = (struct fib_iterator *) n;
648 | 	  nulls = 0;
649 | 	  for(j=n->readers; j; j=j->next)
650 | 	    {
651 | 	      if (j->prev != j0)
