443 | /**
444 |  * fib_delete - delete a FIB node
445 |  * @f: FIB to delete from
446 |  * @E: entry to delete
447 |  *
448 |  * This function removes the given entry from the FIB,
449 |  * taking care of all the asynchronous readers by shifting
450 |  * them to the next node in the canonical reading order.
451 |  */
452 | void
453 | fib_delete(struct fib *f, void *E)
454 | {
455 |   struct fib_node *e = fib_user_to_node(f, E);
456 |   uint h = fib_hash(f, e->addr);
457 |   struct fib_node **ee = f->hash_table + h;
458 |   struct fib_iterator *it;
459 | 
460 |   while (*ee)
461 |     {
462 |       if (*ee == e)
463 | 	{
464 | 	  *ee = e->next;
465 | 	  if (it = e->readers)
466 | 	    {
467 | 	      struct fib_node *l = e->next;
468 | 	      while (!l)
469 | 		{
470 | 		  h++;
471 | 		  if (h >= f->hash_size)
472 | 		    break;
473 | 		  else
474 | 		    l = f->hash_table[h];
475 | 		}
476 | 	      fib_merge_readers(it, l);
477 | 	    }
478 | 
479 | 	  if (f->fib_slab)
480 | 	    sl_free(E);
481 | 	  else
482 | 	    mb_free(E);
483 | 
484 | 	  if (f->entries-- < f->entries_min)
485 | 	    fib_rehash(f, -HASH_LO_STEP);
486 | 	  return;
487 | 	}
488 |       ee = &((*ee)->next);
489 |     }
490 |   bug("fib_delete() called for invalid node");
491 | }
492 | 
493 | /**
494 |  * fib_free - delete a FIB
495 |  * @f: FIB to be deleted
496 |  *
497 |  * This function deletes a FIB -- it frees all memory associated
498 |  * with it and all its entries.
499 |  */
500 | void
501 | fib_free(struct fib *f)
502 | {
503 |   fib_ht_free(f->hash_table);
504 |   rfree(f->fib_slab);
505 | }
