248 | void *
249 | fib_get_chain(struct fib *f, const net_addr *a)
250 | {
251 |   ASSERT(f->addr_type == a->type);
252 | 
253 |   struct fib_node *e = f->hash_table[fib_hash(f, a)];
254 |   return e;
