372 | /**
373 |  * fib_route - CIDR routing lookup
374 |  * @f: FIB to search in
375 |  * @n: network address
376 |  *
377 |  * Search for a FIB node with longest prefix matching the given
378 |  * network, that is a node which a CIDR router would use for routing
379 |  * that network.
380 |  */
381 | void *
382 | fib_route(struct fib *f, const net_addr *n)
383 | {
384 |   ASSERT(f->addr_type == n->type);
385 | 
386 |   net_addr *n0 = alloca(n->length);
387 |   net_copy(n0, n);
388 | 
389 |   switch (n->type)
390 |   {
391 |   case NET_IP4:
392 |   case NET_VPN4:
393 |   case NET_ROA4:
394 |   case NET_FLOW4:
395 |     return fib_route_ip4(f, (net_addr_ip4 *) n0);
396 | 
397 |   case NET_IP6:
398 |   case NET_VPN6:
399 |   case NET_ROA6:
400 |   case NET_FLOW6:
401 |     return fib_route_ip6(f, (net_addr_ip6 *) n0);
402 | 
403 |   default:
404 |     return NULL;
405 |   }
406 | }
