408 | 
409 | static inline void
410 | fib_merge_readers(struct fib_iterator *i, struct fib_node *to)
411 | {
412 |   if (to)
413 |     {
414 |       struct fib_iterator *j = to->readers;
415 |       if (!j)
416 | 	{
417 | 	  /* Fast path */
418 | 	  to->readers = i;
419 | 	  i->prev = (struct fib_iterator *) to;
420 | 	}
421 |       else
422 | 	{
423 | 	  /* Really merging */
424 | 	  while (j->next)
425 | 	    j = j->next;
426 | 	  j->next = i;
427 | 	  i->prev = j;
428 | 	}
429 |       while (i && i->node)
430 | 	{
431 | 	  i->node = NULL;
432 | 	  i = i->next;
433 | 	}
434 |     }
435 |   else					/* No more nodes */
436 |     while (i)
437 |       {
438 | 	i->prev = NULL;
439 | 	i = i->next;
440 |       }
441 | }
