287 | static void
288 | fib_insert(struct fib *f, const net_addr *a, struct fib_node *e)
289 | {
290 |   ASSERT(f->addr_type == a->type);
291 | 
292 |   switch (f->addr_type)
293 |   {
294 |   case NET_IP4: FIB_INSERT(f, a, e, ip4); return;
295 |   case NET_IP6: FIB_INSERT(f, a, e, ip6); return;
296 |   case NET_VPN4: FIB_INSERT(f, a, e, vpn4); return;
297 |   case NET_VPN6: FIB_INSERT(f, a, e, vpn6); return;
298 |   case NET_ROA4: FIB_INSERT(f, a, e, roa4); return;
299 |   case NET_ROA6: FIB_INSERT(f, a, e, roa6); return;
300 |   case NET_FLOW4: FIB_INSERT(f, a, e, flow4); return;
301 |   case NET_FLOW6: FIB_INSERT(f, a, e, flow6); return;
302 |   case NET_IP6_SADR: FIB_INSERT(f, a, e, ip6_sadr); return;
303 |   case NET_MPLS: FIB_INSERT(f, a, e, mpls); return;
304 |   case NET_ASPA: FIB_INSERT(f, a, e, aspa); return;
305 |   default: bug("invalid type");
306 |   }
307 | }
