372 | /**
373 |  * fib_route - CIDR routing lookup
374 |  * @f: FIB to search in
375 |  * @n: network address
376 |  *
377 |  * Search for a FIB node with longest prefix matching the given
378 |  * network, that is a node which a CIDR router would use for routing
379 |  * that network.
380 |  */
381 | void *
382 | fib_route(struct fib *f, const net_addr *n)
383 | {
384 |   ASSERT(f->addr_type == n->type);
385 | 
386 |   net_addr *n0 = alloca(n->length);
387 |   net_copy(n0, n);
388 | 
389 |   switch (n->type)
390 |   {
391 |   case NET_IP4:
392 |   case NET_VPN4:
393 |   case NET_ROA4:
394 |   case NET_FLOW4:
395 |     return fib_route_ip4(f, (net_addr_ip4 *) n0);
396 | 
397 |   case NET_IP6:
398 |   case NET_VPN6:
399 |   case NET_ROA6:
400 |   case NET_FLOW6:
401 |     return fib_route_ip6(f, (net_addr_ip6 *) n0);
402 | 
403 |   default:
404 |     return NULL;
405 |   }
406 | }
407 | 
408 | 
409 | static inline void
410 | fib_merge_readers(struct fib_iterator *i, struct fib_node *to)
411 | {
412 |   if (to)
413 |     {
414 |       struct fib_iterator *j = to->readers;
415 |       if (!j)
416 | 	{
417 | 	  /* Fast path */
418 | 	  to->readers = i;
419 | 	  i->prev = (struct fib_iterator *) to;
420 | 	}
421 |       else
422 | 	{
423 | 	  /* Really merging */
424 | 	  while (j->next)
425 | 	    j = j->next;
426 | 	  j->next = i;
427 | 	  i->prev = j;
428 | 	}
429 |       while (i && i->node)
430 | 	{
431 | 	  i->node = NULL;
432 | 	  i = i->next;
433 | 	}
434 |     }
435 |   else					/* No more nodes */
436 |     while (i)
437 |       {
438 | 	i->prev = NULL;
439 | 	i = i->next;
440 |       }
441 | }
442 | 
443 | /**
444 |  * fib_delete - delete a FIB node
445 |  * @f: FIB to delete from
446 |  * @E: entry to delete
447 |  *
448 |  * This function removes the given entry from the FIB,
449 |  * taking care of all the asynchronous readers by shifting
450 |  * them to the next node in the canonical reading order.
451 |  */
452 | void
453 | fib_delete(struct fib *f, void *E)
454 | {
455 |   struct fib_node *e = fib_user_to_node(f, E);
456 |   uint h = fib_hash(f, e->addr);
457 |   struct fib_node **ee = f->hash_table + h;
458 |   struct fib_iterator *it;
459 | 
460 |   while (*ee)
461 |     {
462 |       if (*ee == e)
463 | 	{
464 | 	  *ee = e->next;
465 | 	  if (it = e->readers)
466 | 	    {
467 | 	      struct fib_node *l = e->next;
468 | 	      while (!l)
469 | 		{
470 | 		  h++;
471 | 		  if (h >= f->hash_size)
472 | 		    break;
473 | 		  else
474 | 		    l = f->hash_table[h];
475 | 		}
476 | 	      fib_merge_readers(it, l);
477 | 	    }
478 | 
479 | 	  if (f->fib_slab)
480 | 	    sl_free(E);
481 | 	  else
482 | 	    mb_free(E);
483 | 
484 | 	  if (f->entries-- < f->entries_min)
485 | 	    fib_rehash(f, -HASH_LO_STEP);
486 | 	  return;
487 | 	}
488 |       ee = &((*ee)->next);
489 |     }
490 |   bug("fib_delete() called for invalid node");
491 | }
492 | 
493 | /**
494 |  * fib_free - delete a FIB
495 |  * @f: FIB to be deleted
496 |  *
497 |  * This function deletes a FIB -- it frees all memory associated
498 |  * with it and all its entries.
499 |  */
500 | void
501 | fib_free(struct fib *f)
502 | {
503 |   fib_ht_free(f->hash_table);
504 |   rfree(f->fib_slab);
505 | }
