310 | /**
311 |  * fib_get - find or create a FIB node
312 |  * @f: FIB to work with
313 |  * @n: network address
314 |  *
315 |  * Search for a FIB node corresponding to the given prefix and
316 |  * return a pointer to it. If no such node exists, create it.
317 |  */
318 | void *
319 | fib_get(struct fib *f, const net_addr *a)
320 | {
321 |   void *b = fib_find(f, a);
322 |   if (b)
323 |     return b;
324 | 
325 |   if (f->fib_slab)
326 |     b = sl_alloc(f->fib_slab);
327 |   else
328 |     b = mb_alloc(f->fib_pool, f->node_size + a->length);
329 | 
330 |   struct fib_node *e = fib_user_to_node(f, b);
331 |   e->readers = NULL;
332 |   fib_insert(f, a, e);
333 | 
334 |   memset(b, 0, f->node_offset);
335 |   if (f->init)
336 |     f->init(f, b);
337 | 
338 |   if (f->entries++ > f->entries_max)
339 |     fib_rehash(f, HASH_HI_STEP);
340 | 
341 |   return b;
342 | }
