529 | struct fib_node *
530 | fit_get(struct fib *f, struct fib_iterator *i)
531 | {
532 |   struct fib_node *n;
533 |   struct fib_iterator *j, *k;
534 | 
535 |   if (!i->prev)
536 |     {
537 |       /* We are at the end */
538 |       i->hash = ~0 - 1;
539 |       return NULL;
540 |     }
541 |   if (!(n = i->node))
542 |     {
543 |       /* No node info available, we are a victim of merging. Try harder. */
544 |       j = i;
545 |       while (j->efef == 0xff)
546 | 	j = j->prev;
547 |       n = (struct fib_node *) j;
548 |     }
549 |   j = i->prev;
550 |   if (k = i->next)
551 |     k->prev = j;
552 |   j->next = k;
553 |   i->hash = fib_hash(f, n->addr);
554 |   return n;
555 | }
556 | 
557 | void
558 | fit_put(struct fib_iterator *i, struct fib_node *n)
559 | {
560 |   struct fib_iterator *j;
561 | 
562 |   i->node = n;
563 |   if (j = n->readers)
564 |     j->prev = i;
565 |   i->next = j;
566 |   n->readers = i;
567 |   i->prev = (struct fib_iterator *) n;
568 | }
569 | 
570 | void
571 | fit_put_next(struct fib *f, struct fib_iterator *i, struct fib_node *n, uint hpos)
572 | {
573 |   if (n = n->next)
574 |     goto found;
575 | 
576 |   while (++hpos < f->hash_size)
577 |     if (n = f->hash_table[hpos])
578 |       goto found;
579 | 
580 |   /* We are at the end */
581 |   i->prev = i->next = NULL;
582 |   i->node = NULL;
583 |   return;
584 | 
585 | found:
586 |   fit_put(i, n);
587 | }
588 | 
589 | void
590 | fit_put_end(struct fib_iterator *i)
591 | {
592 |   i->prev = i->next = NULL;
593 |   i->node = NULL;
594 |   i->hash = ~0 - 1;
595 | }
596 | 
597 | void
598 | fit_copy(struct fib *f, struct fib_iterator *dst, struct fib_iterator *src)
599 | {
600 |   struct fib_iterator *nxt = src->next;
601 | 
602 |   fit_get(f, dst);
603 | 
604 |   if (!src->prev)
605 |   {
606 |     /* We are at the end */
607 |     fit_put_end(dst);
608 |     return;
609 |   }
610 | 
611 |   src->next = dst;
612 |   dst->prev = src;
613 | 
614 |   dst->next = nxt;
615 |   if (nxt)
616 |     nxt->prev = dst;
617 | 
618 |   dst->node = src->node;
619 |   dst->hash = src->hash;
620 | }
