257 | /**
258 |  * fib_find - search for FIB node by prefix
259 |  * @f: FIB to search in
260 |  * @n: network address
261 |  *
262 |  * Search for a FIB node corresponding to the given prefix, return
263 |  * a pointer to it or %NULL if no such node exists.
264 |  */
265 | void *
266 | fib_find(struct fib *f, const net_addr *a)
267 | {
268 |   ASSERT(f->addr_type == a->type);
269 | 
270 |   switch (f->addr_type)
271 |   {
272 |   case NET_IP4: return FIB_FIND(f, a, ip4);
273 |   case NET_IP6: return FIB_FIND(f, a, ip6);
274 |   case NET_VPN4: return FIB_FIND(f, a, vpn4);
275 |   case NET_VPN6: return FIB_FIND(f, a, vpn6);
276 |   case NET_ROA4: return FIB_FIND(f, a, roa4);
277 |   case NET_ROA6: return FIB_FIND(f, a, roa6);
278 |   case NET_FLOW4: return FIB_FIND(f, a, flow4);
279 |   case NET_FLOW6: return FIB_FIND(f, a, flow6);
280 |   case NET_IP6_SADR: return FIB_FIND(f, a, ip6_sadr);
281 |   case NET_MPLS: return FIB_FIND(f, a, mpls);
282 |   case NET_ASPA: return FIB_FIND(f, a, aspa);
283 |   default: bug("invalid type");
284 |   }
285 | }
286 | 
287 | static void
288 | fib_insert(struct fib *f, const net_addr *a, struct fib_node *e)
289 | {
290 |   ASSERT(f->addr_type == a->type);
291 | 
292 |   switch (f->addr_type)
293 |   {
294 |   case NET_IP4: FIB_INSERT(f, a, e, ip4); return;
295 |   case NET_IP6: FIB_INSERT(f, a, e, ip6); return;
296 |   case NET_VPN4: FIB_INSERT(f, a, e, vpn4); return;
297 |   case NET_VPN6: FIB_INSERT(f, a, e, vpn6); return;
298 |   case NET_ROA4: FIB_INSERT(f, a, e, roa4); return;
299 |   case NET_ROA6: FIB_INSERT(f, a, e, roa6); return;
300 |   case NET_FLOW4: FIB_INSERT(f, a, e, flow4); return;
301 |   case NET_FLOW6: FIB_INSERT(f, a, e, flow6); return;
302 |   case NET_IP6_SADR: FIB_INSERT(f, a, e, ip6_sadr); return;
303 |   case NET_MPLS: FIB_INSERT(f, a, e, mpls); return;
304 |   case NET_ASPA: FIB_INSERT(f, a, e, aspa); return;
305 |   default: bug("invalid type");
306 |   }
307 | }
308 | 
309 | 
310 | /**
311 |  * fib_get - find or create a FIB node
312 |  * @f: FIB to work with
313 |  * @n: network address
314 |  *
315 |  * Search for a FIB node corresponding to the given prefix and
316 |  * return a pointer to it. If no such node exists, create it.
317 |  */
318 | void *
319 | fib_get(struct fib *f, const net_addr *a)
320 | {
321 |   void *b = fib_find(f, a);
322 |   if (b)
323 |     return b;
324 | 
325 |   if (f->fib_slab)
326 |     b = sl_alloc(f->fib_slab);
327 |   else
328 |     b = mb_alloc(f->fib_pool, f->node_size + a->length);
329 | 
330 |   struct fib_node *e = fib_user_to_node(f, b);
331 |   e->readers = NULL;
332 |   fib_insert(f, a, e);
333 | 
334 |   memset(b, 0, f->node_offset);
335 |   if (f->init)
336 |     f->init(f, b);
337 | 
338 |   if (f->entries++ > f->entries_max)
339 |     fib_rehash(f, HASH_HI_STEP);
340 | 
341 |   return b;
342 | }
343 | 
344 | static inline void *
345 | fib_route_ip4(struct fib *f, net_addr_ip4 *n)
346 | {
347 |   void *r;
348 | 
349 |   while (!(r = fib_find(f, (net_addr *) n)) && (n->pxlen > 0))
350 |   {
351 |     n->pxlen--;
352 |     ip4_clrbit(&n->prefix, n->pxlen);
353 |   }
354 | 
355 |   return r;
356 | }
357 | 
358 | static inline void *
359 | fib_route_ip6(struct fib *f, net_addr_ip6 *n)
360 | {
361 |   void *r;
362 | 
363 |   while (!(r = fib_find(f, (net_addr *) n)) && (n->pxlen > 0))
364 |   {
365 |     n->pxlen--;
366 |     ip6_clrbit(&n->prefix, n->pxlen);
367 |   }
368 | 
369 |   return r;
370 | }
