2717 |     }
2718 | 
2719 |   /* Relink the new best route to the first position */
2720 |   new = *new_best;
2721 |   if (new != n->routes)
2722 |     {
2723 |       *new_best = new->next;
2724 |       new->next = n->routes;
2725 |       n->routes = new;

