403 | #define AGGR_RTE_KEY(n)			(&(n)->rte)
404 | #define AGGR_RTE_NEXT(n)		((n)->next_hash)
405 | #define AGGR_RTE_EQ(a,b)		(((a)->src == (b)->src) && ((a)->net == (b)->net))
406 | #define AGGR_RTE_FN(_n)			aggr_route_hash(_n)
407 | #define AGGR_RTE_ORDER			4 /* Initial */
408 | 
409 | #define AGGR_RTE_REHASH			aggr_rte_rehash
410 | #define AGGR_RTE_PARAMS			/8, *2, 2, 2, 4, 24
411 | 
412 | HASH_DEFINE_REHASH_FN(AGGR_RTE, struct aggregator_route);
413 | 
414 | 
415 | #define AGGR_BUCK_KEY(n)		(n)
416 | #define AGGR_BUCK_NEXT(n)		((n)->next_hash)
417 | #define AGGR_BUCK_EQ(a,b)		(((a)->hash == (b)->hash) && (same_val_list((a)->aggr_data, (b)->aggr_data, p->aggr_on_count)))
418 | #define AGGR_BUCK_FN(n)			((n)->hash)
419 | #define AGGR_BUCK_ORDER			4 /* Initial */
420 | 
421 | #define AGGR_BUCK_REHASH		aggr_buck_rehash
422 | #define AGGR_BUCK_PARAMS		/8, *2, 2, 2, 4, 24
423 | 
424 | HASH_DEFINE_REHASH_FN(AGGR_BUCK, struct aggregator_bucket);
425 | 
426 | 
427 | #define AGGR_DATA_MEMSIZE	(sizeof(struct f_val) * p->aggr_on_count)
428 | 
429 | static void
430 | aggregator_rt_notify(struct proto *P, struct channel *src_ch, net *net, rte *new, rte *old)
431 | {
432 |   struct aggregator_proto *p = SKIP_BACK(struct aggregator_proto, p, P);
433 |   ASSERT_DIE(src_ch == p->src);
434 |   struct aggregator_bucket *new_bucket = NULL, *old_bucket = NULL;
435 |   struct aggregator_route *old_route = NULL;
436 | 
437 |   /* Find the objects for the old route */
438 |   if (old)
439 |     old_route = HASH_FIND(p->routes, AGGR_RTE, old);
440 | 
441 |   if (old_route)
442 |     old_bucket = old_route->bucket;
443 | 
444 |   /* Find the bucket for the new route */
445 |   if (new)
446 |   {
447 |     /* Routes are identical, do nothing */
448 |     if (old_route && rte_same(&old_route->rte, new))
449 |       return;
450 | 
451 |     /* Evaluate route attributes. */
452 |     struct aggregator_bucket *tmp_bucket = sl_allocz(p->bucket_slab);
453 | 
454 |     for (uint val_idx = 0; val_idx < p->aggr_on_count; val_idx++)
455 |     {
456 |       int type = p->aggr_on[val_idx].type;
457 |       struct f_val *pos = &tmp_bucket->aggr_data[val_idx];
458 | 
459 |       switch (type)
460 |       {
461 |         case AGGR_ITEM_TERM: {
462 |           const struct f_line *line = p->aggr_on[val_idx].line;
463 |           struct rte *rt1 = new;
464 |           enum filter_return fret = f_eval_rte(line, &new, rte_update_pool, 0, NULL, pos);
465 | 
466 |           if (rt1 != new)
467 |           {
468 |             rte_free(rt1);
469 |             log(L_WARN "Aggregator rule modifies the route, reverting");
470 |           }
471 | 
472 |           if (fret > F_RETURN)
473 |             log(L_WARN "%s.%s: Wrong number of items left on stack after evaluation of aggregation list", rt1->src->proto->name, rt1->sender->name);
474 | 
475 | 	  switch (pos->type) {
476 | 	    case T_VOID:
477 | 	    case T_INT:
478 | 	    case T_BOOL:
479 | 	    case T_PAIR:
480 | 	    case T_QUAD:
481 | 	    case T_ENUM:
482 | 	    case T_IP:
483 | 	    case T_EC:
484 | 	    case T_LC:
485 | 	    case T_RD:
486 | 	      /* Fits, OK */
487 | 	      break;
488 | 
489 | 	    default:
490 | 	      log(L_WARN "%s.%s: Expression evaluated to type %s unsupported by aggregator. Store this value as a custom attribute instead", new->src->proto->name, new->sender->name, f_type_name(pos->type));
491 | 	      *pos = (struct f_val) { .type = T_INT, .val.i = 0 };
492 | 	  }
493 | 
494 |           break;
495 |         }
496 | 
497 |         case AGGR_ITEM_STATIC_ATTR: {
498 |           eval_static_attr(new, p->aggr_on[val_idx].sa, pos);
499 |           break;
500 |         }
501 | 
502 |         case AGGR_ITEM_DYNAMIC_ATTR: {
503 |           eval_dynamic_attr(new, p->aggr_on[val_idx].da, pos);
504 |           break;
505 |         }
506 | 
507 |         default:
508 |           break;
509 |       }
510 |     }
511 | 
512 |     /* Compute the hash */
513 |     u64 haux;
514 |     mem_hash_init(&haux);
515 |     for (uint i = 0; i < p->aggr_on_count; i++)
516 |     {
517 |       mem_hash_mix_num(&haux, tmp_bucket->aggr_data[i].type);
518 | 
519 | #define MX(k) mem_hash_mix(&haux, &IT(k), sizeof IT(k));
520 | #define IT(k) tmp_bucket->aggr_data[i].val.k
521 | 
522 |       switch (tmp_bucket->aggr_data[i].type)
523 |       {
524 | 	case T_VOID:
525 | 	  break;
526 | 	case T_INT:
527 | 	case T_BOOL:
528 | 	case T_PAIR:
529 | 	case T_QUAD:
530 | 	case T_ENUM:
531 | 	  MX(i);
532 | 	  break;
533 | 	case T_EC:
534 | 	case T_RD:
535 | 	  MX(ec);
536 | 	  break;
537 | 	case T_LC:
538 | 	  MX(lc);
539 | 	  break;
540 | 	case T_IP:
541 | 	  MX(ip);
542 | 	  break;
543 | 	case T_NET:
544 | 	  mem_hash_mix_num(&haux, net_hash(IT(net)));
545 | 	  break;
546 | 	case T_STRING:
547 | 	  mem_hash_mix_str(&haux, IT(s));
548 | 	  break;
549 | 	case T_PATH_MASK:
550 | 	  mem_hash_mix(&haux, IT(path_mask), sizeof(*IT(path_mask)) + IT(path_mask)->len * sizeof (IT(path_mask)->item));
551 | 	  break;
552 | 	case T_PATH:
553 | 	case T_CLIST:
554 | 	case T_ECLIST:
555 | 	case T_LCLIST:
556 | 	case T_BYTESTRING:
557 | 	  mem_hash_mix(&haux, IT(ad)->data, IT(ad)->length);
558 | 	  break;
559 | 	case T_NONE:
560 | 	case T_PATH_MASK_ITEM:
561 | 	case T_ROUTE:
562 | 	case T_ROUTES_BLOCK:
563 | 	  bug("Invalid type %s in hashing", f_type_name(tmp_bucket->aggr_data[i].type));
564 | 	case T_SET:
565 | 	  MX(t);
566 | 	  break;
567 | 	case T_PREFIX_SET:
568 | 	  MX(ti);
569 | 	  break;
570 |       }
571 |     }
572 | 
573 |     tmp_bucket->hash = mem_hash_value(&haux);
574 | 
575 |     /* Find the existing bucket */
576 |     if (new_bucket = HASH_FIND(p->buckets, AGGR_BUCK, tmp_bucket))
577 |       sl_free(tmp_bucket);
578 |     else
579 |     {
580 |       new_bucket = tmp_bucket;
581 |       HASH_INSERT2(p->buckets, AGGR_BUCK, p->p.pool, new_bucket);
582 |     }
583 | 
584 |     /* Store the route attributes */
585 |     if (rta_is_cached(new->attrs))
586 |       rta_clone(new->attrs);
587 |     else
588 |       new->attrs = rta_lookup(new->attrs);
589 | 
590 |     /* Insert the new route into the bucket */
591 |     struct aggregator_route *arte = sl_alloc(p->route_slab);
592 |     *arte = (struct aggregator_route) {
593 |       .bucket = new_bucket,
594 |       .rte = *new,
595 |     };
596 |     arte->rte.next = new_bucket->rte,
597 |     new_bucket->rte = &arte->rte;
598 |     new_bucket->count++;
599 |     HASH_INSERT2(p->routes, AGGR_RTE, p->p.pool, arte);
600 |   }
601 | 
602 |   /* Remove the old route from its bucket */
603 |   if (old_bucket)
604 |   {
605 |     for (struct rte **k = &old_bucket->rte; *k; k = &(*k)->next)
606 |       if (*k == &old_route->rte)
607 |       {
608 | 	*k = (*k)->next;
609 | 	break;
610 |       }
611 | 
612 |     old_bucket->count--;
613 |     HASH_REMOVE2(p->routes, AGGR_RTE, p->p.pool, old_route);
614 |     rta_free(old_route->rte.attrs);
615 |     sl_free(old_route);
616 |   }
617 | 
618 |   /* Announce changes */
619 |   if (old_bucket)
620 |     aggregator_bucket_update(p, old_bucket, net);
621 | 
622 |   if (new_bucket && (new_bucket != old_bucket))
623 |     aggregator_bucket_update(p, new_bucket, net);
624 | 
625 |   /* Cleanup the old bucket if empty */
626 |   if (old_bucket && (!old_bucket->rte || !old_bucket->count))
627 |   {
628 |     ASSERT_DIE(!old_bucket->rte && !old_bucket->count);
629 |     HASH_REMOVE2(p->buckets, AGGR_BUCK, p->p.pool, old_bucket);
630 |     sl_free(old_bucket);
631 |   }
632 | }
633 | 
634 | static int
635 | aggregator_preexport(struct channel *C, struct rte *new)
636 | {
637 |   struct aggregator_proto *p = SKIP_BACK(struct aggregator_proto, p, C->proto);
638 |   /* Reject our own routes */
639 |   if (new->sender == p->dst)
640 |     return -1;
641 | 
642 |   /* Disallow aggregating already aggregated routes */
643 |   if (new->attrs->source == RTS_AGGREGATED)
644 |   {
645 |     log(L_ERR "Multiple aggregations of the same route not supported in BIRD 2.");
646 |     return -1;
647 |   }
648 | 
649 |   return 0;
650 | }
651 | 
652 | static void
653 | aggregator_postconfig(struct proto_config *CF)
654 | {
655 |   struct aggregator_config *cf = SKIP_BACK(struct aggregator_config, c, CF);
656 | 
657 |   if (!cf->dst->table)
658 |     cf_error("Source table not specified");
659 | 
660 |   if (!cf->src->table)
661 |     cf_error("Destination table not specified");
662 | 
663 |   if (cf->dst->table->addr_type != cf->src->table->addr_type)
664 |     cf_error("Both tables must be of the same type");
665 | 
666 |   cf->dst->in_filter = cf->src->in_filter;
667 | 
668 |   cf->src->in_filter = FILTER_REJECT;
669 |   cf->dst->out_filter = FILTER_REJECT;
670 | 
671 |   cf->dst->debug = cf->src->debug;
672 | }
673 | 
674 | static struct proto *
675 | aggregator_init(struct proto_config *CF)
676 | {
677 |   struct proto *P = proto_new(CF);
678 |   struct aggregator_proto *p = SKIP_BACK(struct aggregator_proto, p, P);
679 |   struct aggregator_config *cf = SKIP_BACK(struct aggregator_config, c, CF);
680 | 
681 |   proto_configure_channel(P, &p->src, cf->src);
682 |   proto_configure_channel(P, &p->dst, cf->dst);
683 | 
684 |   p->aggr_on_count = cf->aggr_on_count;
685 |   p->aggr_on_da_count = cf->aggr_on_da_count;
686 |   p->aggr_on = cf->aggr_on;
687 |   p->merge_by = cf->merge_by;
688 | 
689 |   P->rt_notify = aggregator_rt_notify;
690 |   P->preexport = aggregator_preexport;
691 | 
692 |   return P;
693 | }
694 | 
695 | static int
696 | aggregator_start(struct proto *P)
697 | {
698 |   struct aggregator_proto *p = SKIP_BACK(struct aggregator_proto, p, P);
699 | 
700 |   p->bucket_slab = sl_new(P->pool, sizeof(struct aggregator_bucket) + AGGR_DATA_MEMSIZE);
701 |   HASH_INIT(p->buckets, P->pool, AGGR_BUCK_ORDER);
702 | 
703 |   p->route_slab = sl_new(P->pool, sizeof(struct aggregator_route));
704 |   HASH_INIT(p->routes, P->pool, AGGR_RTE_ORDER);
705 | 
706 |   p->reload_buckets = (event) {
707 |     .hook = aggregator_reload_buckets,
708 |     .data = p,
709 |   };
710 | 
711 |   return PS_UP;
712 | }
713 | 
714 | static int
715 | aggregator_shutdown(struct proto *P)
716 | {
717 |   struct aggregator_proto *p = SKIP_BACK(struct aggregator_proto, p, P);
718 | 
719 |   HASH_WALK_DELSAFE(p->buckets, next_hash, b)
720 |   {
721 |     while (b->rte)
722 |     {
723 |       struct aggregator_route *arte = SKIP_BACK(struct aggregator_route, rte, b->rte);
724 |       b->rte = arte->rte.next;
725 |       b->count--;
726 |       HASH_REMOVE(p->routes, AGGR_RTE, arte);
727 |       rta_free(arte->rte.attrs);
728 |       sl_free(arte);
729 |     }
730 | 
731 |     ASSERT_DIE(b->count == 0);
732 |     HASH_REMOVE(p->buckets, AGGR_BUCK, b);
733 |     sl_free(b);
734 |   }
735 |   HASH_WALK_END;
736 | 
737 |   return PS_DOWN;
738 | }
739 | 
740 | static int
741 | aggregator_reconfigure(struct proto *P, struct proto_config *CF)
742 | {
743 |   struct aggregator_proto *p = SKIP_BACK(struct aggregator_proto, p, P);
744 |   struct aggregator_config *cf = SKIP_BACK(struct aggregator_config, c, CF);
745 | 
746 |   TRACE(D_EVENTS, "Reconfiguring");
747 | 
748 |   /* Compare numeric values (shortcut) */
749 |   if (cf->aggr_on_count != p->aggr_on_count)
750 |     return 0;
751 | 
752 |   if (cf->aggr_on_da_count != p->aggr_on_da_count)
753 |     return 0;
754 | 
755 |   /* Compare aggregator rule */
756 |   for (uint i = 0; i < p->aggr_on_count; i++)
757 |     switch (cf->aggr_on[i].type)
758 |     {
759 |       case AGGR_ITEM_TERM:
760 | 	if (!f_same(cf->aggr_on[i].line, p->aggr_on[i].line))
761 | 	  return 0;
762 | 	break;
763 |       case AGGR_ITEM_STATIC_ATTR:
764 | 	if (memcmp(&cf->aggr_on[i].sa, &p->aggr_on[i].sa, sizeof(struct f_static_attr)) != 0)
765 | 	  return 0;
766 | 	break;
767 |       case AGGR_ITEM_DYNAMIC_ATTR:
768 | 	if (memcmp(&cf->aggr_on[i].da, &p->aggr_on[i].da, sizeof(struct f_dynamic_attr)) != 0)
769 | 	  return 0;
770 | 	break;
771 |       default:
772 | 	bug("Broken aggregator rule");
773 |     }
774 | 
775 |   /* Compare merge filter */
776 |   if (!f_same(cf->merge_by, p->merge_by))
777 |     ev_schedule(&p->reload_buckets);
778 | 
779 |   p->aggr_on = cf->aggr_on;
780 |   p->merge_by = cf->merge_by;
781 | 
782 |   return 1;
783 | }
