 67 | /*
 68 |  * Set static attribute in @rta from static attribute in @old according to @sa.
 69 |  */
 70 | static void
 71 | rta_set_static_attr(struct rta *rta, const struct rta *old, struct f_static_attr sa)
 72 | {
 73 |   switch (sa.sa_code)
 74 |   {
 75 |     case SA_NET:
 76 |       break;
 77 | 
 78 |     case SA_FROM:
 79 |       rta->from = old->from;
 80 |       break;
 81 | 
 82 |     case SA_GW:
 83 |       rta->dest = RTD_UNICAST;
 84 |       rta->nh.gw = old->nh.gw;
 85 |       rta->nh.iface = old->nh.iface;
 86 |       rta->nh.next = NULL;
 87 |       rta->hostentry = NULL;
 88 |       rta->nh.labels = 0;
 89 |       break;
 90 | 
 91 |     case SA_SCOPE:
 92 |       rta->scope = old->scope;
 93 |       break;
 94 | 
 95 |     case SA_DEST:
 96 |       rta->dest = old->dest;
 97 |       rta->nh.gw = IPA_NONE;
 98 |       rta->nh.iface = NULL;
 99 |       rta->nh.next = NULL;
100 |       rta->hostentry = NULL;
101 |       rta->nh.labels = 0;
102 |       break;
103 | 
104 |     case SA_IFNAME:
105 |       rta->dest = RTD_UNICAST;
106 |       rta->nh.gw = IPA_NONE;
107 |       rta->nh.iface = old->nh.iface;
108 |       rta->nh.next = NULL;
109 |       rta->hostentry = NULL;
110 |       rta->nh.labels = 0;
111 |       break;
112 | 
113 |     case SA_GW_MPLS:
114 |       rta->nh.labels = old->nh.labels;
115 |       memcpy(&rta->nh.label, &old->nh.label, sizeof(u32) * old->nh.labels);
116 |       break;
117 | 
118 |     case SA_WEIGHT:
119 |       rta->nh.weight = old->nh.weight;
120 |       break;
121 | 
122 |     case SA_PREF:
123 |       rta->pref = old->pref;
124 |       break;
125 | 
126 |     default:
127 |       bug("Invalid static attribute access (%u/%u)", sa.f_type, sa.sa_code);
128 |   }
129 | }
