242 | /*
243 |  * Reload all the buckets on reconfiguration if merge filter has changed.
244 |  * TODO: make this splitted
245 |  */
246 | static void
247 | aggregator_reload_buckets(void *data)
248 | {
249 |   struct aggregator_proto *p = data;
250 | 
251 |   HASH_WALK(p->buckets, next_hash, b)
252 |     if (b->rte)
253 |     {
254 |       aggregator_bucket_update(p, b, b->rte->net);
255 |       lp_flush(rte_update_pool);
256 |     }
257 |   HASH_WALK_END;
258 | }
