145 | /*
146 |  * Create and export new merged route.
147 |  * @old: first route in a sequence of equivalent routes that are to be merged
148 |  * @rte_val: first element in a sequence of equivalent rte_val_list entries
149 |  * @length: number of equivalent routes that are to be merged (at least 1)
150 |  * @ail: aggregation list
151 |  */
152 | static void
153 | aggregator_bucket_update(struct aggregator_proto *p, struct aggregator_bucket *bucket, struct network *net)
154 | {
155 |   /* Empty bucket */
156 |   if (!bucket->rte)
157 |   {
158 |     rte_update2(p->dst, net->n.addr, NULL, bucket->last_src);
159 |     bucket->last_src = NULL;
160 |     return;
161 |   }
162 | 
163 |   /* Allocate RTA and EA list */
164 |   struct rta *rta = allocz(rta_size(bucket->rte->attrs));
165 |   rta->dest = RTD_UNREACHABLE;
166 |   rta->source = RTS_AGGREGATED;
167 |   rta->scope = SCOPE_UNIVERSE;
168 | 
169 |   struct ea_list *eal = allocz(sizeof(struct ea_list) + sizeof(struct eattr) * p->aggr_on_da_count);
170 |   eal->next = NULL;
171 |   eal->count = 0;
172 |   rta->eattrs = eal;
173 | 
174 |   /* Seed the attributes from aggregator rule */
175 |   for (uint i = 0; i < p->aggr_on_count; i++)
176 |   {
177 |     if (p->aggr_on[i].type == AGGR_ITEM_DYNAMIC_ATTR)
178 |     {
179 |       u32 ea_code = p->aggr_on[i].da.ea_code;
180 |       const struct eattr *e = ea_find(bucket->rte->attrs->eattrs, ea_code);
181 | 
182 |       if (e)
183 |         eal->attrs[eal->count++] = *e;
184 |     }
185 |     else if (p->aggr_on[i].type == AGGR_ITEM_STATIC_ATTR)
186 |       rta_set_static_attr(rta, bucket->rte->attrs, p->aggr_on[i].sa);
187 |   }
188 | 
189 |   struct rte *new = rte_get_temp(rta, bucket->rte->src);
190 |   new->net = net;
191 | 
192 |   /*
193 |   log("=============== CREATE MERGED ROUTE ===============");
194 |   log("New route created: id = %d, protocol: %s", new->src->global_id, new->src->proto->name);
195 |   log("===================================================");
196 |   */
197 | 
198 |   /* merge filter needs one argument called "routes" */
199 |   struct f_val val = {
200 |     .type = T_ROUTES_BLOCK,
201 |     .val.rte = bucket->rte,
202 |   };
203 | 
204 |   /* Actually run the filter */
205 |   enum filter_return fret = f_eval_rte(p->merge_by, &new, rte_update_pool, 1, &val, 0);
206 | 
207 |   /* Src must be stored now, rte_update2() may return new */
208 |   struct rte_src *new_src = new ? new->src : NULL;
209 | 
210 |   /* Finally import the route */
211 |   switch (fret)
212 |   {
213 |     /* Pass the route to the protocol */
214 |     case F_ACCEPT:
215 |       rte_update2(p->dst, net->n.addr, new, bucket->last_src ?: new->src);
216 |       break;
217 | 
218 |     /* Something bad happened */
219 |     default:
220 |       ASSERT_DIE(fret == F_ERROR);
221 |       /* fall through */
222 | 
223 |     /* We actually don't want this route */
224 |     case F_REJECT:
225 |       if (bucket->last_src)
226 | 	rte_update2(p->dst, net->n.addr, NULL, bucket->last_src);
227 |       break;
228 |   }
229 | 
230 |   /* Switch source lock for bucket->last_src */
231 |   if (bucket->last_src != new_src)
232 |   {
233 |     if (new_src)
234 |       rt_lock_source(new_src);
235 |     if (bucket->last_src)
236 |       rt_unlock_source(bucket->last_src);
237 | 
238 |     bucket->last_src = new_src;
239 |   }
240 | }
