  1 | /*
  2 |  *	BIRD Internet Routing Daemon -- Route aggregation
  3 |  *
  4 |  *	(c) 2023--2023 Igor Putovny <igor.putovny@nic.cz>
  5 |  *	(c) 2023       CZ.NIC, z.s.p.o.
