390 | static inline u32 aggr_route_hash(const rte *e)
391 | {
392 |   struct {
393 |     net *net;
394 |     struct rte_src *src;
395 |   } obj = {
396 |     .net = e->net,
397 |     .src = e->src,
398 |   };
399 | 
400 |   return mem_hash(&obj, sizeof obj);
401 | }
