787 |   .template =		"aggregator%d",
788 |   .class =		PROTOCOL_AGGREGATOR,
789 |   .preference =		1,
790 |   .channel_mask =	NB_ANY,
791 |   .proto_size =		sizeof(struct aggregator_proto),
792 |   .config_size =	sizeof(struct aggregator_config),
793 |   .postconfig =		aggregator_postconfig,
794 |   .init =		aggregator_init,
795 |   .start =		aggregator_start,
796 |   .shutdown =		aggregator_shutdown,
797 |   .reconfigure =	aggregator_reconfigure,
798 | };
