261 | /*
262 |  * Evaluate static attribute of @rt1 according to @sa
263 |  * and store result in @pos.
264 |  */
265 | static void
266 | eval_static_attr(const struct rte *rt1, struct f_static_attr sa, struct f_val *pos)
267 | {
268 |   const struct rta *rta = rt1->attrs;
269 | 
270 | #define RESULT(_type, value, result)    \
271 |   do {                                  \
272 |     pos->type = _type;                  \
273 |     pos->val.value = result;            \
274 |   } while (0)
275 | 
276 |   switch (sa.sa_code)
277 |   {
278 |     case SA_NET:	RESULT(sa.f_type, net, rt1->net->n.addr); break;
279 |     case SA_FROM:       RESULT(sa.f_type, ip, rta->from); break;
280 |     case SA_GW:	        RESULT(sa.f_type, ip, rta->nh.gw); break;
281 |     case SA_PROTO:	    RESULT(sa.f_type, s, rt1->src->proto->name); break;
282 |     case SA_SOURCE:	    RESULT(sa.f_type, i, rta->source); break;
283 |     case SA_SCOPE:	    RESULT(sa.f_type, i, rta->scope); break;
284 |     case SA_DEST:	    RESULT(sa.f_type, i, rta->dest); break;
285 |     case SA_IFNAME:	    RESULT(sa.f_type, s, rta->nh.iface ? rta->nh.iface->name : ""); break;
286 |     case SA_IFINDEX:	RESULT(sa.f_type, i, rta->nh.iface ? rta->nh.iface->index : 0); break;
287 |     case SA_WEIGHT:	    RESULT(sa.f_type, i, rta->nh.weight + 1); break;
288 |     case SA_PREF:	    RESULT(sa.f_type, i, rta->pref); break;
289 |     case SA_GW_MPLS:    RESULT(sa.f_type, i, rta->nh.labels ? rta->nh.label[0] : MPLS_NULL); break;
290 |     default:
291 |       bug("Invalid static attribute access (%u/%u)", sa.f_type, sa.sa_code);
292 |   }
293 | 
294 | #undef RESULT
295 | }
