297 | /*
298 |  * Evaluate dynamic attribute of @rt1 according to @da
299 |  * and store result in @pos.
300 |  */
301 | static void
302 | eval_dynamic_attr(const struct rte *rt1, struct f_dynamic_attr da, struct f_val *pos)
303 | {
304 |   const struct rta *rta = rt1->attrs;
305 |   const struct eattr *e = ea_find(rta->eattrs, da.ea_code);
306 | 
307 | #define RESULT(_type, value, result)    \
308 |   do {                                  \
309 |     pos->type = _type;                  \
310 |     pos->val.value = result;            \
311 |   } while (0)
312 | 
313 | #define RESULT_VOID         \
314 |   do {                      \
315 |     pos->type = T_VOID;     \
316 |   } while (0)
317 | 
318 |   if (!e)
319 |   {
320 |     /* A special case: undefined as_path looks like empty as_path */
321 |     if (da.type == EAF_TYPE_AS_PATH)
322 |     {
323 |       RESULT(T_PATH, ad, &null_adata);
324 |       return;
325 |     }
326 | 
327 |     /* The same special case for int_set */
328 |     if (da.type == EAF_TYPE_INT_SET)
329 |     {
330 |       RESULT(T_CLIST, ad, &null_adata);
331 |       return;
332 |     }
333 | 
334 |     /* The same special case for ec_set */
335 |     if (da.type == EAF_TYPE_EC_SET)
336 |     {
337 |       RESULT(T_ECLIST, ad, &null_adata);
338 |       return;
339 |     }
340 | 
341 |     /* The same special case for lc_set */
342 |     if (da.type == EAF_TYPE_LC_SET)
343 |     {
344 |       RESULT(T_LCLIST, ad, &null_adata);
345 |       return;
346 |     }
347 | 
348 |     /* Undefined value */
349 |     RESULT_VOID;
350 |     return;
351 |   }
352 | 
353 |   switch (e->type & EAF_TYPE_MASK)
354 |   {
355 |     case EAF_TYPE_INT:
356 |       RESULT(da.f_type, i, e->u.data);
357 |       break;
358 |     case EAF_TYPE_ROUTER_ID:
359 |       RESULT(T_QUAD, i, e->u.data);
360 |       break;
361 |     case EAF_TYPE_OPAQUE:
362 |       RESULT(T_ENUM_EMPTY, i, 0);
363 |       break;
364 |     case EAF_TYPE_IP_ADDRESS:
365 |       RESULT(T_IP, ip, *((ip_addr *) e->u.ptr->data));
366 |       break;
367 |     case EAF_TYPE_AS_PATH:
368 |       RESULT(T_PATH, ad, e->u.ptr);
369 |       break;
370 |     case EAF_TYPE_BITFIELD:
371 |       RESULT(T_BOOL, i, !!(e->u.data & (1u << da.bit)));
372 |       break;
373 |     case EAF_TYPE_INT_SET:
374 |       RESULT(T_CLIST, ad, e->u.ptr);
375 |       break;
376 |     case EAF_TYPE_EC_SET:
377 |       RESULT(T_ECLIST, ad, e->u.ptr);
378 |       break;
379 |     case EAF_TYPE_LC_SET:
380 |       RESULT(T_LCLIST, ad, e->u.ptr);
381 |       break;
382 |     default:
383 |       bug("Unknown dynamic attribute type");
384 |   }
385 | 
386 | #undef RESULT
387 | #undef RESULT_VOID
388 | }
