695 | static int
696 | aggregator_start(struct proto *P)
697 | {
698 |   struct aggregator_proto *p = SKIP_BACK(struct aggregator_proto, p, P);
699 | 
700 |   p->bucket_slab = sl_new(P->pool, sizeof(struct aggregator_bucket) + AGGR_DATA_MEMSIZE);
701 |   HASH_INIT(p->buckets, P->pool, AGGR_BUCK_ORDER);
702 | 
703 |   p->route_slab = sl_new(P->pool, sizeof(struct aggregator_route));
704 |   HASH_INIT(p->routes, P->pool, AGGR_RTE_ORDER);
705 | 
706 |   p->reload_buckets = (event) {
707 |     .hook = aggregator_reload_buckets,
708 |     .data = p,
709 |   };
710 | 
711 |   return PS_UP;
