  13 | 
  14 | /**
  15 |  * DOC: The Babel protocol
  16 |  *
  17 |  * The Babel is a loop-avoiding distance-vector routing protocol that is robust
  18 |  * and efficient both in ordinary wired networks and in wireless mesh networks.
  19 |  *
  20 |  * The Babel protocol keeps state for each neighbour in a &babel_neighbor
  21 |  * struct, tracking received Hello and I Heard You (IHU) messages. A
  22 |  * &babel_interface struct keeps hello and update times for each interface, and
  23 |  * a separate hello seqno is maintained for each interface.
  24 |  *
  25 |  * For each prefix, Babel keeps track of both the possible routes (with next hop
  26 |  * and router IDs), as well as the feasibility distance for each prefix and
  27 |  * router id. The prefix itself is tracked in a &babel_entry struct, while the
  28 |  * possible routes for the prefix are tracked as &babel_route entries and the
  29 |  * feasibility distance is maintained through &babel_source structures.
  30 |  *
  31 |  * The main route selection is done in babel_select_route(). This is called when
  32 |  * an entry is updated by receiving updates from the network or when modified by
  33 |  * internal timers. The function selects from feasible and reachable routes the
  34 |  * one with the lowest metric to be announced to the core.
  35 |  *
  36 |  * Supported standards:
  37 |  * RFC 8966 - The Babel Routing Protocol
  38 |  * RFC 8967 - MAC Authentication for Babel
  39 |  * RFC 9079 - Source Specific Routing for Babel
  40 |  * RFC 9229 - IPv4 Routes with IPv6 Next Hop for Babel
  41 |  */
  42 | 
  43 | #include <stdlib.h>
  44 | #include "babel.h"
  45 | 
  46 | #define LOG_PKT_AUTH(msg, args...) \
  47 |   log_rl(&p->log_pkt_tbf, L_AUTH "%s: " msg, p->p.name, args)
  48 | 
  49 | /*
  50 |  * Is one number greater or equal than another mod 2^16? This is based on the
  51 |  * definition of serial number space in RFC 1982. Note that arguments are of
  52 |  * uint type to avoid integer promotion to signed integer.
  53 |  */
  54 | static inline int ge_mod64k(uint a, uint b)
  55 | { return (u16)(a - b) < 0x8000; }
  56 | 
  57 | /* Strict inequality version of the above */
  58 | static inline int gt_mod64k(uint a, uint b)
  59 | { return ge_mod64k(a, b) && a != b; }
  60 | 
  61 | static void babel_expire_requests(struct babel_proto *p, struct babel_entry *e);
  62 | static void babel_select_route(struct babel_proto *p, struct babel_entry *e, struct babel_route *mod);
  63 | static inline void babel_announce_retraction(struct babel_proto *p, struct babel_entry *e);
  64 | static void babel_send_route_request(struct babel_proto *p, struct babel_entry *e, struct babel_neighbor *n);
  65 | static void babel_send_seqno_request(struct babel_proto *p, struct babel_entry *e, struct babel_seqno_request *sr, struct babel_neighbor *n);
  66 | static void babel_update_cost(struct babel_neighbor *n);
  67 | static inline void babel_kick_timer(struct babel_proto *p);
  68 | static inline void babel_iface_kick_timer(struct babel_iface *ifa);
