  70 | /*
  71 |  *	Functions to maintain data structures
  72 |  */
  73 | 
  74 | static void
  75 | babel_init_entry(struct fib *f UNUSED, void *E)
  76 | {
  77 |   struct babel_entry *e = E;
  78 | 
  79 |   e->updated = current_time();
  80 |   init_list(&e->requests);
  81 |   init_list(&e->sources);
  82 |   init_list(&e->routes);
  83 | }
  84 | 
  85 | static inline struct babel_entry *
  86 | babel_find_entry(struct babel_proto *p, const net_addr *n)
  87 | {
  88 |   struct fib *rtable = (n->type == NET_IP4) ? &p->ip4_rtable : &p->ip6_rtable;
  89 |   return fib_find(rtable, n);
  90 | }
  91 | 
  92 | static struct babel_entry *
  93 | babel_get_entry(struct babel_proto *p, const net_addr *n)
  94 | {
  95 |   struct fib *rtable = (n->type == NET_IP4) ? &p->ip4_rtable : &p->ip6_rtable;
  96 |   struct babel_entry *e = fib_get(rtable, n);
  97 |   return e;
  98 | }
  99 | 
 100 | static struct babel_source *
 101 | babel_find_source(struct babel_entry *e, u64 router_id)
 102 | {
 103 |   struct babel_source *s;
 104 | 
 105 |   WALK_LIST(s, e->sources)
 106 |     if (s->router_id == router_id)
 107 |       return s;
 108 | 
 109 |   return NULL;
 110 | }
 111 | 
 112 | static struct babel_source *
 113 | babel_get_source(struct babel_proto *p, struct babel_entry *e, u64 router_id,
 114 |                  u16 initial_seqno)
 115 | {
 116 |   struct babel_source *s = babel_find_source(e, router_id);
 117 | 
 118 |   if (s)
 119 |     return s;
 120 | 
 121 |   s = sl_allocz(p->source_slab);
 122 |   s->router_id = router_id;
 123 |   s->expires = current_time() + BABEL_GARBAGE_INTERVAL;
 124 |   s->seqno = initial_seqno;
 125 |   s->metric = BABEL_INFINITY;
 126 |   add_tail(&e->sources, NODE s);
 127 | 
 128 |   return s;
 129 | }
