 131 | static void
 132 | babel_expire_sources(struct babel_proto *p UNUSED, struct babel_entry *e)
 133 | {
 134 |   struct babel_source *n, *nx;
 135 |   btime now_ = current_time();
 136 | 
 137 |   WALK_LIST_DELSAFE(n, nx, e->sources)
 138 |   {
 139 |     if (n->expires && n->expires <= now_)
 140 |     {
 141 |       rem_node(NODE n);
 142 |       sl_free(n);
 143 |     }
 144 |   }
 145 | }
 146 | 
 147 | static struct babel_route *
 148 | babel_find_route(struct babel_entry *e, struct babel_neighbor *n)
 149 | {
 150 |   struct babel_route *r;
 151 | 
 152 |   WALK_LIST(r, e->routes)
 153 |     if (r->neigh == n)
 154 |       return r;
 155 | 
 156 |   return NULL;
 157 | }
 158 | 
 159 | static struct babel_route *
 160 | babel_get_route(struct babel_proto *p, struct babel_entry *e, struct babel_neighbor *nbr)
 161 | {
 162 |   struct babel_route *r = babel_find_route(e, nbr);
 163 | 
 164 |   if (r)
 165 |     return r;
 166 | 
 167 |   r = sl_allocz(p->route_slab);
 168 | 
 169 |   r->e = e;
 170 |   r->neigh = nbr;
 171 |   add_tail(&e->routes, NODE r);
 172 |   add_tail(&nbr->routes, NODE &r->neigh_route);
 173 | 
 174 |   return r;
 175 | }
