 177 | static inline void
 178 | babel_retract_route(struct babel_proto *p, struct babel_route *r)
 179 | {
 180 |   r->metric = r->advert_metric = BABEL_INFINITY;
 181 | 
 182 |   if (r == r->e->selected)
 183 |     babel_select_route(p, r->e, r);
 184 | }
 185 | 
 186 | static void
 187 | babel_flush_route(struct babel_proto *p UNUSED, struct babel_route *r)
 188 | {
 189 |   DBG("Babel: Flush route %N router_id %lR neigh %I\n",
 190 |       r->e->n.addr, r->router_id, r->neigh->addr);
 191 | 
 192 |   rem_node(NODE r);
 193 |   rem_node(&r->neigh_route);
 194 | 
 195 |   if (r->e->selected == r)
 196 |     r->e->selected = NULL;
 197 | 
 198 |   sl_free(r);
 199 | }
 200 | 
 201 | static void
 202 | babel_expire_route(struct babel_proto *p, struct babel_route *r)
 203 | {
 204 |   struct babel_config *cf = (void *) p->p.cf;
 205 | 
 206 |   TRACE(D_EVENTS, "Route expiry timer for %N router-id %lR fired",
 207 | 	r->e->n.addr, r->router_id);
 208 | 
 209 |   if (r->metric < BABEL_INFINITY)
 210 |   {
 211 |     r->metric = r->advert_metric = BABEL_INFINITY;
 212 |     r->expires = current_time() + cf->hold_time;
 213 |   }
 214 |   else
 215 |   {
 216 |     babel_flush_route(p, r);
 217 |   }
 218 | }
 219 | 
 220 | static void
 221 | babel_refresh_route(struct babel_proto *p, struct babel_route *r)
 222 | {
 223 |   if (r == r->e->selected)
 224 |     babel_send_route_request(p, r->e, r->neigh);
 225 | 
 226 |   r->refresh_time = 0;
 227 | }
 228 | 
 229 | static void
 230 | babel_expire_routes_(struct babel_proto *p, struct fib *rtable)
 231 | {
 232 |   struct babel_config *cf = (void *) p->p.cf;
 233 |   struct babel_route *r, *rx;
 234 |   struct fib_iterator fit;
 235 |   btime now_ = current_time();
 236 | 
 237 |   FIB_ITERATE_INIT(&fit, rtable);
 238 | 
 239 | loop:
 240 |   FIB_ITERATE_START(rtable, &fit, struct babel_entry, e)
 241 |   {
 242 |     int changed = 0;
 243 | 
 244 |     WALK_LIST_DELSAFE(r, rx, e->routes)
 245 |     {
 246 |       if (r->refresh_time && r->refresh_time <= now_)
 247 | 	babel_refresh_route(p, r);
 248 | 
 249 |       if (r->expires && r->expires <= now_)
 250 |       {
 251 | 	changed = changed || (r == e->selected);
 252 | 	babel_expire_route(p, r);
 253 |       }
 254 |     }
 255 | 
 256 |     if (changed)
 257 |     {
 258 |       /*
 259 |        * We have to restart the iteration because there may be a cascade of
 260 |        * synchronous events babel_select_route() -> nest table change ->
 261 |        * babel_rt_notify() -> rtable change, invalidating hidden variables.
 262 |        */
 263 |       FIB_ITERATE_PUT(&fit);
 264 |       babel_select_route(p, e, NULL);
 265 |       goto loop;
 266 |     }
 267 | 
 268 |     /* Clean up stale entries */
 269 |     if ((e->valid == BABEL_ENTRY_STALE) && ((e->updated + cf->hold_time) <= now_))
 270 |       e->valid = BABEL_ENTRY_DUMMY;
 271 | 
 272 |     /* Clean up unreachable route */
 273 |     if (e->unreachable && (!e->valid || (e->router_id == p->router_id)))
 274 |     {
 275 |       FIB_ITERATE_PUT(&fit);
 276 |       babel_announce_retraction(p, e);
 277 |       goto loop;
 278 |     }
 279 | 
 280 |     babel_expire_sources(p, e);
 281 |     babel_expire_requests(p, e);
 282 | 
 283 |     /* Remove empty entries */
 284 |     if (!e->valid && EMPTY_LIST(e->routes) && EMPTY_LIST(e->sources) && EMPTY_LIST(e->requests))
 285 |     {
 286 |       FIB_ITERATE_PUT(&fit);
 287 |       fib_delete(rtable, e);
 288 |       goto loop;
 289 |     }
 290 |   }
 291 |   FIB_ITERATE_END;
 292 | }
 293 | 
 294 | static void
 295 | babel_expire_routes(struct babel_proto *p)
 296 | {
 297 |   babel_expire_routes_(p, &p->ip4_rtable);
 298 |   babel_expire_routes_(p, &p->ip6_rtable);
 299 | }
