 301 | /*
 302 |  * Add seqno request to the table of pending requests (RFC 8966 3.2.6) and send
 303 |  * it to network. Do nothing if it is already in the table.
 304 |  */
 305 | 
 306 | static void
 307 | babel_add_seqno_request(struct babel_proto *p, struct babel_entry *e,
 308 | 			u64 router_id, u16 seqno, u8 hop_count,
 309 | 			struct babel_neighbor *target)
 310 | {
 311 |   struct babel_seqno_request *sr;
 312 |   btime now_ = current_time();
 313 | 
 314 |   WALK_LIST(sr, e->requests)
 315 |     if (sr->router_id == router_id)
 316 |     {
 317 |       /*
 318 |        * To suppress duplicates, check if we already have a newer (higher seqno)
 319 |        * outstanding request. If we do, suppress this request if the outstanding
 320 |        * request is one we originated ourselves. If the outstanding request is
 321 |        * forwarded, suppress only if this request is also one we're forwarding
 322 |        * *and* we're within the duplicate suppression time of that request (see
 323 |        * below).
 324 |        */
 325 |       if (ge_mod64k(sr->seqno, seqno) &&
 326 |           (!sr->forwarded || (target && now_ < sr->dup_suppress_time)))
 327 | 	return;
 328 | 
 329 |       rem_node(NODE sr);
 330 | 
 331 |       /* Allow upgrading from forwarded to non-forwarded */
 332 |       if (!target)
 333 |         sr->forwarded = 0;
 334 | 
 335 |       goto found;
 336 |     }
 337 | 
 338 |   /* No entries found */
 339 |   sr = sl_allocz(p->seqno_slab);
 340 |   sr->forwarded = !!target;
 341 | 
 342 | found:
 343 |   sr->router_id = router_id;
 344 |   sr->seqno = seqno;
 345 |   sr->hop_count = hop_count ?: BABEL_INITIAL_HOP_COUNT;
 346 |   sr->count = 0;
 347 | 
 348 |   if (sr->forwarded)
 349 |   {
 350 |     /*
 351 |      * We want to keep the entry around for a reasonable period of time so it
 352 |      * can be used to trigger an update (through babel_satisfy_seqno_request()).
 353 |      * However, duplicate suppression should only trigger for a short period of
 354 |      * time so it suppresses duplicates from multiple sources, but not
 355 |      * retransmissions from the same source. Hence we keep two timers.
 356 |      */
 357 |     sr->expires = now_ + BABEL_SEQNO_FORWARD_EXPIRY;
 358 |     sr->dup_suppress_time = now_ + BABEL_SEQNO_DUP_SUPPRESS_TIME;
 359 |   }
 360 |   else
 361 |   {
 362 |     sr->expires = now_ + BABEL_SEQNO_REQUEST_EXPIRY;
 363 |   }
 364 | 
 365 |   add_tail(&e->requests, NODE sr);
 366 |   babel_send_seqno_request(p, e, sr, target);
 367 | }
 368 | 
 369 | static void
 370 | babel_generate_seqno_request(struct babel_proto *p, struct babel_entry *e,
 371 |                              u64 router_id, u16 seqno, struct babel_neighbor *target)
 372 | {
 373 |   struct babel_seqno_request req = {
 374 |     .router_id = router_id,
 375 |     .seqno = seqno,
 376 |     .hop_count = BABEL_INITIAL_HOP_COUNT,
 377 |   };
 378 | 
 379 |   babel_send_seqno_request(p, e, &req, target);
 380 | }
 381 | 
 382 | static void
 383 | babel_remove_seqno_request(struct babel_proto *p UNUSED, struct babel_seqno_request *sr)
 384 | {
 385 |   rem_node(NODE sr);
 386 |   sl_free(sr);
 387 | }
 388 | 
 389 | static int
 390 | babel_satisfy_seqno_request(struct babel_proto *p, struct babel_entry *e,
 391 | 			   u64 router_id, u16 seqno)
 392 | {
 393 |   struct babel_seqno_request *sr;
 394 | 
 395 |   WALK_LIST(sr, e->requests)
 396 |     if ((sr->router_id == router_id) && ge_mod64k(seqno, sr->seqno))
 397 |     {
 398 |       /* Found the request, remove it */
 399 |       babel_remove_seqno_request(p, sr);
 400 |       return 1;
 401 |     }
 402 | 
 403 |   return 0;
 404 | }
 405 | 
 406 | static void
 407 | babel_expire_requests(struct babel_proto *p, struct babel_entry *e)
 408 | {
 409 |   struct babel_seqno_request *sr, *srx;
 410 |   btime now_ = current_time();
 411 | 
 412 |   WALK_LIST_DELSAFE(sr, srx, e->requests)
 413 |   {
 414 |     /* Handle expired requests - resend or remove */
 415 |     if (sr->expires && sr->expires <= now_)
 416 |     {
 417 |       if (!sr->forwarded && sr->count < BABEL_SEQNO_REQUEST_RETRY)
 418 |       {
 419 | 	sr->count++;
 420 | 	sr->expires += (BABEL_SEQNO_REQUEST_EXPIRY << sr->count);
 421 |         babel_send_seqno_request(p, e, sr, NULL);
 422 |       }
 423 |       else
 424 |       {
 425 | 	TRACE(D_EVENTS, "Seqno request for %N router-id %lR expired",
 426 | 	      e->n.addr, sr->router_id);
 427 | 
 428 | 	babel_remove_seqno_request(p, sr);
 429 | 	continue;
 430 |       }
 431 |     }
 432 |   }
 433 | }
