 436 | babel_find_neighbor(struct babel_iface *ifa, ip_addr addr)
 437 | {
 438 |   struct babel_neighbor *nbr;
 439 | 
 440 |   WALK_LIST(nbr, ifa->neigh_list)
 441 |     if (ipa_equal(nbr->addr, addr))
 442 |       return nbr;
