 447 | static struct babel_neighbor *
 448 | babel_get_neighbor(struct babel_iface *ifa, ip_addr addr)
 449 | {
 450 |   struct babel_proto *p = ifa->proto;
 451 |   struct babel_neighbor *nbr = babel_find_neighbor(ifa, addr);
 452 | 
 453 |   if (nbr)
 454 |     return nbr;
 455 | 
 456 |   TRACE(D_EVENTS, "New neighbor %I on %s", addr, ifa->iface->name);
 457 | 
 458 |   nbr = mb_allocz(ifa->pool, sizeof(struct babel_neighbor));
 459 |   nbr->ifa = ifa;
 460 |   nbr->addr = addr;
 461 |   nbr->rxcost = BABEL_INFINITY;
 462 |   nbr->txcost = BABEL_INFINITY;
 463 |   nbr->cost = BABEL_INFINITY;
 464 |   nbr->init_expiry = current_time() + BABEL_INITIAL_NEIGHBOR_TIMEOUT;
 465 |   init_list(&nbr->routes);
 466 |   add_tail(&ifa->neigh_list, NODE nbr);
 467 | 
 468 |   return nbr;
