 471 | static void
 472 | babel_flush_neighbor(struct babel_proto *p, struct babel_neighbor *nbr)
 473 | {
 474 |   struct babel_route *r;
 475 |   node *n;
 476 | 
 477 |   TRACE(D_EVENTS, "Removing neighbor %I on %s", nbr->addr, nbr->ifa->iface->name);
 478 | 
 479 |   WALK_LIST_FIRST(n, nbr->routes)
 480 |   {
 481 |     r = SKIP_BACK(struct babel_route, neigh_route, n);
 482 |     babel_retract_route(p, r);
 483 |     babel_flush_route(p, r);
 484 |   }
 485 | 
 486 |   nbr->ifa = NULL;
 487 |   rem_node(NODE nbr);
 488 |   mb_free(nbr);
