 491 | static void
 492 | babel_expire_ihu(struct babel_proto *p, struct babel_neighbor *nbr)
 493 | {
 494 |   TRACE(D_EVENTS, "IHU from nbr %I on %s expired", nbr->addr, nbr->ifa->iface->name);
 495 | 
 496 |   nbr->txcost = BABEL_INFINITY;
 497 |   nbr->ihu_expiry = 0;
 498 |   babel_update_cost(nbr);
 499 | }
