 501 | static void
 502 | babel_expire_hello(struct babel_proto *p, struct babel_neighbor *nbr, btime now_)
 503 | {
 504 | again:
 505 |   nbr->hello_map <<= 1;
 506 | 
 507 |   if (nbr->hello_cnt < 16)
 508 |     nbr->hello_cnt++;
 509 | 
 510 |   nbr->hello_expiry += nbr->last_hello_int;
 511 | 
 512 |   /* We may expire multiple hellos if last_hello_int is too short */
 513 |   if (nbr->hello_map && nbr->hello_expiry <= now_)
 514 |     goto again;
 515 | 
 516 |   TRACE(D_EVENTS, "Hello from nbr %I on %s expired, %d left",
 517 | 	nbr->addr, nbr->ifa->iface->name, u32_popcount(nbr->hello_map));
 518 | 
 519 |   if (nbr->hello_map)
 520 |     babel_update_cost(nbr);
 521 |   else
 522 |     babel_flush_neighbor(p, nbr);
 523 | }
 524 | 
 525 | static void
 526 | babel_expire_neighbors(struct babel_proto *p)
 527 | {
 528 |   struct babel_iface *ifa;
 529 |   struct babel_neighbor *nbr, *nbx;
 530 |   btime now_ = current_time();
 531 | 
 532 |   WALK_LIST(ifa, p->interfaces)
 533 |   {
 534 |     WALK_LIST_DELSAFE(nbr, nbx, ifa->neigh_list)
 535 |     {
 536 |       if (nbr->ihu_expiry && nbr->ihu_expiry <= now_)
 537 |         babel_expire_ihu(p, nbr);
 538 | 
 539 |       if (nbr->init_expiry && nbr->init_expiry <= now_)
 540 |       { babel_flush_neighbor(p, nbr); continue; }
 541 | 
 542 |       if (nbr->hello_expiry && nbr->hello_expiry <= now_)
 543 |       { babel_expire_hello(p, nbr, now_); continue; }
 544 |     }
 545 |   }
 546 | }
