 548 | /*
 549 |  *	Best route selection
 550 |  */
 551 | 
 552 | /*
 553 |  * From the RFC (section 3.5.1):
 554 |  *
 555 |  * a route advertisement carrying the quintuple (prefix, plen, router-id, seqno,
 556 |  * metric) is feasible if one of the following conditions holds:
 557 |  *
 558 |  * - metric is infinite; or
 559 |  *
 560 |  * - no entry exists in the source table indexed by (id, prefix, plen); or
 561 |  *
 562 |  * - an entry (prefix, plen, router-id, seqno', metric') exists in the source
 563 |  *   table, and either
 564 |  *   - seqno' < seqno or
 565 |  *   - seqno = seqno' and metric < metric'.
 566 |  */
 567 | static inline int
 568 | babel_is_feasible(struct babel_source *s, u16 seqno, u16 metric)
 569 | {
 570 |   return !s ||
 571 |     (metric == BABEL_INFINITY) ||
 572 |     gt_mod64k(seqno, s->seqno) ||
 573 |     ((seqno == s->seqno) && (metric < s->metric));
 574 | }
 575 | 
 576 | /* Simple additive metric - Appendix 3.1 in the RFC */
 577 | static inline u16
 578 | babel_compute_metric(struct babel_neighbor *n, uint metric)
 579 | {
 580 |   return MIN(metric + n->cost, BABEL_INFINITY);
 581 | }
 582 | 
 583 | static void
 584 | babel_update_cost(struct babel_neighbor *nbr)
 585 | {
 586 |   struct babel_proto *p = nbr->ifa->proto;
 587 |   struct babel_iface_config *cf = nbr->ifa->cf;
 588 |   uint rcv = u32_popcount(nbr->hello_map); // number of bits set
 589 |   uint max = nbr->hello_cnt;
 590 |   uint rxcost = BABEL_INFINITY;	/* Cost to announce in IHU */
 591 |   uint txcost = BABEL_INFINITY;	/* Effective cost for route selection */
 592 | 
 593 |   if (!rcv || !nbr->ifa->up)
 594 |     goto done;
 595 | 
 596 |   switch (cf->type)
 597 |   {
 598 |   case BABEL_IFACE_TYPE_WIRED:
 599 |   case BABEL_IFACE_TYPE_TUNNEL:
 600 |     /* k-out-of-j selection - Appendix 2.1 in the RFC. */
 601 | 
 602 |     /* Link is bad if less than cf->limit/16 of expected hellos were received */
 603 |     if (rcv * 16 < cf->limit * max)
 604 |       break;
 605 | 
 606 |     rxcost =  cf->rxcost;
 607 |     txcost = nbr->txcost;
 608 |     break;
 609 | 
 610 |   case BABEL_IFACE_TYPE_WIRELESS:
 611 |     /*
 612 |      * ETX - Appendix 2.2 in the RFC.
 613 |      *
 614 |      * alpha  = prob. of successful transmission estimated by the neighbor
 615 |      * beta   = prob. of successful transmission estimated by the router
 616 |      * rxcost = nominal rxcost of the router / beta
 617 |      * txcost = nominal rxcost of the neighbor / (alpha * beta)
 618 |      *        = received txcost / beta
 619 |      *
 620 |      * Note that received txcost is just neighbor's rxcost. Beta is rcv/max,
 621 |      * we use inverse values of beta (i.e. max/rcv) to stay in integers.
 622 |      */
 623 |     rxcost = MIN( cf->rxcost * max / rcv, BABEL_INFINITY);
 624 |     txcost = MIN(nbr->txcost * max / rcv, BABEL_INFINITY);
 625 |     break;
 626 |   }
 627 | 
 628 |   if (cf->rtt_cost && nbr->srtt > cf->rtt_min)
 629 |   {
 630 |     uint rtt_cost = cf->rtt_cost;
 631 | 
 632 |     if (nbr->srtt < cf->rtt_max)
 633 |     {
 634 |       uint rtt_interval = cf->rtt_max TO_US - cf->rtt_min TO_US;
 635 |       uint rtt_diff = (nbr->srtt TO_US - cf->rtt_min TO_US);
 636 | 
 637 |       rtt_cost = (rtt_cost * rtt_diff) / rtt_interval;
 638 |     }
 639 | 
 640 |     txcost = MIN(txcost + rtt_cost, BABEL_INFINITY);
 641 | 
 642 |     TRACE(D_EVENTS, "Added RTT cost %u to nbr %I on %s with srtt %t ms",
 643 | 	  rtt_cost, nbr->addr, nbr->ifa->iface->name, nbr->srtt * 1000);
 644 |   }
 645 | 
 646 | done:
 647 |   /* If RX cost changed, send IHU with next Hello */
 648 |   if (rxcost != nbr->rxcost)
 649 |   {
 650 |     nbr->rxcost = rxcost;
 651 |     nbr->ihu_cnt = 0;
 652 |   }
 653 | 
 654 |   /* If link cost changed, run route selection */
 655 |   if (txcost != nbr->cost)
 656 |   {
 657 |     TRACE(D_EVENTS, "Cost of nbr %I on %s changed from %u to %u",
 658 | 	  nbr->addr, nbr->ifa->iface->name, nbr->cost, txcost);
 659 | 
 660 |     nbr->cost = txcost;
 661 | 
 662 |     struct babel_route *r; node *n;
 663 |     WALK_LIST2(r, n, nbr->routes, neigh_route)
 664 |     {
 665 |       r->metric = babel_compute_metric(nbr, r->advert_metric);
 666 |       babel_select_route(p, r->e, r);
 667 |     }
 668 |   }
 669 | }
 670 | 
 671 | /**
 672 |  * babel_announce_rte - announce selected route to the core
 673 |  * @p: Babel protocol instance
 674 |  * @e: Babel route entry to announce
 675 |  *
 676 |  * This function announces a Babel entry to the core if it has a selected
 677 |  * incoming path, and retracts it otherwise. If there is no selected route but
 678 |  * the entry is valid and ours, the unreachable route is announced instead.
 679 |  */
 680 | static void
 681 | babel_announce_rte(struct babel_proto *p, struct babel_entry *e)
 682 | {
 683 |   struct babel_route *r = e->selected;
 684 |   struct channel *c = (e->n.addr->type == NET_IP4) ? p->ip4_channel : p->ip6_channel;
 685 | 
 686 |   if (r)
 687 |   {
 688 |     rta a0 = {
 689 |       .source = RTS_BABEL,
 690 |       .scope = SCOPE_UNIVERSE,
 691 |       .dest = RTD_UNICAST,
 692 |       .pref = c->preference,
 693 |       .from = r->neigh->addr,
 694 |       .nh.gw = r->next_hop,
 695 |       .nh.iface = r->neigh->ifa->iface,
 696 |       .eattrs = alloca(sizeof(ea_list) + 3*sizeof(eattr)),
 697 |     };
 698 | 
 699 |     *a0.eattrs = (ea_list) { .count = 3 };
 700 |     a0.eattrs->attrs[0] = (eattr) {
 701 |       .id = EA_BABEL_METRIC,
 702 |       .type = EAF_TYPE_INT,
 703 |       .u.data = r->metric,
 704 |     };
 705 | 
 706 |     struct adata *ad = alloca(sizeof(struct adata) + sizeof(u64));
 707 |     ad->length = sizeof(u64);
 708 |     memcpy(ad->data, &(r->router_id), sizeof(u64));
 709 |     a0.eattrs->attrs[1] = (eattr) {
 710 |       .id = EA_BABEL_ROUTER_ID,
 711 |       .type = EAF_TYPE_OPAQUE,
 712 |       .u.ptr = ad,
 713 |     };
 714 | 
 715 |     a0.eattrs->attrs[2] = (eattr) {
 716 |       .id = EA_BABEL_SEQNO,
 717 |       .type = EAF_TYPE_INT,
 718 |       .u.data = r->seqno,
 719 |     };
 720 | 
 721 |     /*
 722 |      * If we cannot find a reachable neighbour, set the entry to be onlink. This
 723 |      * makes it possible to, e.g., assign /32 addresses on a mesh interface and
 724 |      * have routing work.
 725 |      */
 726 |     if (!neigh_find(&p->p, r->next_hop, r->neigh->ifa->iface, 0))
 727 |       a0.nh.flags = RNF_ONLINK;
 728 | 
 729 |     rta *a = rta_lookup(&a0);
 730 |     rte *rte = rte_get_temp(a, p->p.main_source);
 731 | 
 732 |     e->unreachable = 0;
 733 |     rte_update2(c, e->n.addr, rte, p->p.main_source);
 734 |   }
 735 |   else if (e->valid && (e->router_id != p->router_id))
 736 |   {
 737 |     /* Unreachable */
 738 |     rta a0 = {
 739 |       .source = RTS_BABEL,
 740 |       .scope = SCOPE_UNIVERSE,
 741 |       .dest = RTD_UNREACHABLE,
 742 |       .pref = 1,
 743 |     };
 744 | 
 745 |     rta *a = rta_lookup(&a0);
 746 |     rte *rte = rte_get_temp(a, p->p.main_source);
 747 | 
 748 |     e->unreachable = 1;
 749 |     rte_update2(c, e->n.addr, rte, p->p.main_source);
 750 |   }
 751 |   else
 752 |   {
 753 |     /* Retraction */
 754 |     e->unreachable = 0;
 755 |     rte_update2(c, e->n.addr, NULL, p->p.main_source);
 756 |   }
 757 | }
 758 | 
 759 | /* Special case of babel_announce_rte() just for retraction */
 760 | static inline void
 761 | babel_announce_retraction(struct babel_proto *p, struct babel_entry *e)
 762 | {
 763 |   struct channel *c = (e->n.addr->type == NET_IP4) ? p->ip4_channel : p->ip6_channel;
 764 |   e->unreachable = 0;
 765 |   rte_update2(c, e->n.addr, NULL, p->p.main_source);
 766 | }
