 769 | /**
 770 |  * babel_select_route - select best route for given route entry
 771 |  * @p: Babel protocol instance
 772 |  * @e: Babel entry to select the best route for
 773 |  * @mod: Babel route that was modified or NULL if unspecified
 774 |  *
 775 |  * Select the best reachable and feasible route for a given prefix among the
 776 |  * routes received from peers, and propagate it to the nest. This just selects
 777 |  * the reachable and feasible route with the lowest metric, but keeps selected
 778 |  * the old one in case of tie.
 779 |  *
 780 |  * If no feasible route is available for a prefix that previously had a route
 781 |  * selected, a seqno request is sent to try to get a valid route. If the entry
 782 |  * is valid and not owned by us, the unreachable route is announced to the nest
 783 |  * (to blackhole packets going to it, as per section 2.8). It is later removed
 784 |  * by babel_expire_routes(). Otherwise, the route is just removed from the nest.
 785 |  *
 786 |  * Argument @mod is used to optimize best route calculation. When specified, the
 787 |  * function can assume that only the @mod route was modified to avoid full best
 788 |  * route selection and announcement when non-best route was modified in minor
 789 |  * way. The caller is advised to not call babel_select_route() when no change is
 790 |  * done (e.g. periodic route updates) to avoid unnecessary announcements of the
 791 |  * same best route. The caller is not required to call the function in case of a
 792 |  * retraction of a non-best route.
 793 |  *
 794 |  * Note that the function does not active triggered updates. That is done by
 795 |  * babel_rt_notify() when the change is propagated back to Babel.
 796 |  */
 797 | static void
 798 | babel_select_route(struct babel_proto *p, struct babel_entry *e, struct babel_route *mod)
 799 | {
 800 |   struct babel_route *r, *best = e->selected;
 801 | 
 802 |   /* Shortcut if only non-best was modified */
 803 |   if (mod && (mod != best))
 804 |   {
 805 |     /* Either select modified route, or keep old best route */
 806 |     if ((mod->metric < (best ? best->metric : BABEL_INFINITY)) && mod->feasible)
 807 |       best = mod;
 808 |     else
 809 |       return;
 810 |   }
 811 |   else
 812 |   {
 813 |     /* Selected route may be modified and no longer admissible */
 814 |     if (!best || (best->metric == BABEL_INFINITY) || !best->feasible)
 815 |       best = NULL;
 816 | 
 817 |     /* Find the best feasible route from all routes */
 818 |     WALK_LIST(r, e->routes)
 819 |       if ((r->metric < (best ? best->metric : BABEL_INFINITY)) && r->feasible)
 820 | 	best = r;
 821 |   }
 822 | 
 823 |   if (best)
 824 |   {
 825 |     if (best != e->selected)
 826 |       TRACE(D_EVENTS, "Picked new route for prefix %N: router-id %lR metric %d",
 827 | 	    e->n.addr, best->router_id, best->metric);
 828 |   }
 829 |   else if (e->selected)
 830 |   {
 831 |     /*
 832 |      * We have lost all feasible routes. We have to broadcast seqno request
 833 |      * (Section 3.8.2.1) and keep unreachable route for a while (section 2.8).
 834 |      * The later is done automatically by babel_announce_rte().
 835 |      */
 836 | 
 837 |     TRACE(D_EVENTS, "Lost feasible route for prefix %N", e->n.addr);
 838 |     if (e->valid && (e->selected->router_id == e->router_id))
 839 |       babel_add_seqno_request(p, e, e->selected->router_id, e->selected->seqno + 1, 0, NULL);
 840 |   }
 841 |   else
 842 |     return;
 843 | 
 844 |   e->selected = best;
 845 |   babel_announce_rte(p, e);
 846 | }
