 851 | 
 852 | static void
 853 | babel_send_ack(struct babel_iface *ifa, ip_addr dest, u16 nonce)
 854 | {
 855 |   struct babel_proto *p = ifa->proto;
 856 |   union babel_msg msg = {};
 857 | 
 858 |   TRACE(D_PACKETS, "Sending ACK to %I with nonce %d", dest, nonce);
 859 | 
 860 |   msg.type = BABEL_TLV_ACK;
 861 |   msg.ack.nonce = nonce;
 862 | 
 863 |   babel_send_unicast(&msg, ifa, dest);
 864 | }
