 866 | static void
 867 | babel_build_ihu(union babel_msg *msg, struct babel_iface *ifa, struct babel_neighbor *n)
 868 | {
 869 |   struct babel_proto *p = ifa->proto;
 870 | 
 871 |   msg->type = BABEL_TLV_IHU;
 872 |   msg->ihu.addr = n->addr;
 873 |   msg->ihu.rxcost = n->rxcost;
 874 |   msg->ihu.interval = ifa->cf->ihu_interval;
 875 | 
 876 |   if (n->last_tstamp_rcvd && ifa->cf->rtt_send)
 877 |   {
 878 |     msg->ihu.tstamp = n->last_tstamp;
 879 |     msg->ihu.tstamp_rcvd = n->last_tstamp_rcvd TO_US;
 880 |   }
 881 | 
 882 |   TRACE(D_PACKETS, "Sending IHU for %I with rxcost %d interval %t",
 883 |         msg->ihu.addr, msg->ihu.rxcost, (btime) msg->ihu.interval);
 884 | }
 885 | 
 886 | static void
 887 | babel_send_ihu(struct babel_iface *ifa, struct babel_neighbor *n)
 888 | {
 889 |   union babel_msg msg = {};
 890 |   babel_build_ihu(&msg, ifa, n);
 891 |   babel_send_unicast(&msg, ifa, n->addr);
 892 |   n->ihu_cnt = BABEL_IHU_INTERVAL_FACTOR;
 893 | }
 894 | 
 895 | static void
 896 | babel_send_ihus(struct babel_iface *ifa)
 897 | {
 898 |   struct babel_neighbor *n;
 899 |   WALK_LIST(n, ifa->neigh_list)
 900 |   {
 901 |     if (n->hello_cnt && (--n->ihu_cnt <= 0))
 902 |     {
 903 |       union babel_msg msg = {};
 904 |       babel_build_ihu(&msg, ifa, n);
 905 |       babel_enqueue(&msg, ifa);
 906 |       n->ihu_cnt = BABEL_IHU_INTERVAL_FACTOR;
 907 |     }
 908 |   }
