 989 | /**
 990 |  * babel_send_update - send route table updates
 991 |  * @ifa: Interface to transmit on
 992 |  * @changed: Only send entries changed since this time
 993 |  *
 994 |  * This function produces update TLVs for all entries changed since the time
 995 |  * indicated by the &changed parameter and queues them for transmission on the
 996 |  * selected interface. During the process, the feasibility distance for each
 997 |  * transmitted entry is updated.
 998 |  */
 999 | static void
1000 | babel_send_update_(struct babel_iface *ifa, btime changed, struct fib *rtable)
1001 | {
1002 |   struct babel_proto *p = ifa->proto;
1003 | 
1004 |   /* Update increase was requested */
1005 |   if (p->update_seqno_inc)
1006 |   {
1007 |     p->update_seqno++;
1008 |     p->update_seqno_inc = 0;
1009 |   }
1010 | 
1011 |   FIB_WALK(rtable, struct babel_entry, e)
1012 |   {
1013 |     if (!e->valid)
1014 |       continue;
1015 | 
1016 |     /* Our own seqno might have changed, in which case we update the routes we
1017 |        originate. */
1018 |     if ((e->router_id == p->router_id) && gt_mod64k(p->update_seqno, e->seqno))
1019 |     {
1020 |       e->seqno = p->update_seqno;
1021 |       e->updated = current_time();
1022 |     }
1023 | 
1024 |     /* Skip routes that weren't updated since 'changed' time */
1025 |     if (e->updated < changed)
1026 |       continue;
1027 | 
1028 |     TRACE(D_PACKETS, "Sending update for %N router-id %lR seqno %d metric %d",
1029 | 	  e->n.addr, e->router_id, e->seqno, e->metric);
1030 | 
1031 |     union babel_msg msg = {};
1032 |     msg.type = BABEL_TLV_UPDATE;
1033 |     msg.update.interval = ifa->cf->update_interval;
1034 |     msg.update.seqno = e->seqno;
1035 |     msg.update.metric = e->metric;
1036 |     msg.update.router_id = e->router_id;
1037 |     net_copy(&msg.update.net, e->n.addr);
1038 | 
1039 |     if (e->n.addr->type == NET_IP4)
1040 |     {
1041 |       /* Use IPv4 nexthop if available and preferred */
1042 |       if (ipa_nonzero(ifa->next_hop_ip4) &&
1043 | 	  (ifa->cf->next_hop_prefer == BABEL_NHP_NATIVE))
1044 |         msg.update.next_hop = ifa->next_hop_ip4;
1045 | 
1046 |       /* Only send IPv6 nexthop if enabled */
1047 |       else if (ifa->cf->ext_next_hop)
1048 |         msg.update.next_hop = ifa->next_hop_ip6;
1049 | 
1050 |       /* Fallback (prefer IPv6 but !ext_next_hop) */
1051 |       else
1052 | 	msg.update.next_hop = ifa->next_hop_ip4;
1053 |     }
1054 |     else
1055 |       msg.update.next_hop = ifa->next_hop_ip6;
1056 | 
1057 |     /* Do not send route if next hop is unknown, e.g. no configured IPv4 address */
1058 |     if (ipa_zero(msg.update.next_hop))
1059 |       continue;
1060 | 
1061 |     babel_enqueue(&msg, ifa);
1062 | 
1063 |     /* RFC 8966 3.7.3 - update feasibility distance for redistributed routes */
1064 |     if (e->router_id != p->router_id)
1065 |     {
1066 |       struct babel_source *s = babel_get_source(p, e, e->router_id, msg.update.seqno);
1067 |       s->expires = current_time() + BABEL_GARBAGE_INTERVAL;
1068 | 
1069 |       if (gt_mod64k(msg.update.seqno, s->seqno) ||
1070 | 	  ((msg.update.seqno == s->seqno) && (msg.update.metric < s->metric)))
1071 |       {
1072 | 	s->seqno = msg.update.seqno;
1073 | 	s->metric = msg.update.metric;
1074 |       }
1075 |     }
1076 |   }
1077 |   FIB_WALK_END;
1078 | }
1079 | 
1080 | static void
1081 | babel_send_update(struct babel_iface *ifa, btime changed)
1082 | {
1083 |   struct babel_proto *p = ifa->proto;
1084 | 
1085 |   babel_send_update_(ifa, changed, &p->ip4_rtable);
1086 |   babel_send_update_(ifa, changed, &p->ip6_rtable);
1087 | }
