1155 | /*
1156 |  *	TLV handler helpers
1157 |  */
1158 | 
1159 | /* Update hello history according to Appendix A1 of the RFC */
1160 | static void
1161 | babel_update_hello_history(struct babel_neighbor *n, u16 seqno, uint interval)
1162 | {
1163 |   /*
1164 |    * Compute the difference between expected and received seqno (modulo 2^16).
1165 |    * If the expected and received seqnos are within 16 of each other, the modular
1166 |    * difference is going to be less than 16 for one of the directions. Otherwise,
1167 |    * the values differ too much, so just reset the state.
1168 |    */
1169 | 
1170 |   u16 delta = ((uint) seqno - (uint) n->next_hello_seqno);
1171 | 
1172 |   if ((delta == 0) || (n->hello_cnt == 0))
1173 |   {
1174 |     /* Do nothing */
1175 |   }
1176 |   else if (delta <= 16)
1177 |   {
1178 |     /* Sending node decreased interval; fast-forward */
1179 |     n->hello_map <<= delta;
1180 |     n->hello_cnt = MIN(n->hello_cnt + delta, 16);
1181 |   }
1182 |   else if (delta >= 0xfff0)
1183 |   {
1184 |     u8 diff = (0xffff - delta);
1185 |     /* Sending node increased interval; undo history */
1186 |     n->hello_map >>= diff;
1187 |     n->hello_cnt = (diff < n->hello_cnt) ? n->hello_cnt - diff : 0;
1188 |   }
1189 |   else
1190 |   {
1191 |     /* Note state reset - flush entries */
1192 |     n->hello_map = n->hello_cnt = 0;
1193 |   }
1194 | 
1195 |   /* Current entry */
1196 |   n->hello_map = (n->hello_map << 1) | 1;
1197 |   n->next_hello_seqno = seqno+1;
1198 |   if (n->hello_cnt < 16) n->hello_cnt++;
1199 | 
1200 |   /* Update expiration */
1201 |   n->hello_expiry = current_time() + BABEL_HELLO_EXPIRY_FACTOR(interval);
1202 |   n->last_hello_int = interval;
1203 | 
1204 |   /* Disable initial timeout */
1205 |   n->init_expiry = 0;
1206 | }
