1225 | void
1226 | babel_handle_hello(union babel_msg *m, struct babel_iface *ifa)
1227 | {
1228 |   struct babel_proto *p = ifa->proto;
1229 |   struct babel_msg_hello *msg = &m->hello;
1230 | 
1231 |   TRACE(D_PACKETS, "Handling hello seqno %d interval %t",
1232 | 	msg->seqno, (btime) msg->interval);
1233 | 
1234 |   struct babel_neighbor *n = babel_get_neighbor(ifa, msg->sender);
1235 |   struct babel_iface_config *cf = n->ifa->cf;
1236 |   int first_hello = !n->hello_cnt;
1237 | 
1238 |   if (msg->tstamp)
1239 |   {
1240 |     n->last_tstamp = msg->tstamp;
1241 |     n->last_tstamp_rcvd = msg->pkt_received;
1242 |   }
1243 |   babel_update_hello_history(n, msg->seqno, msg->interval);
1244 |   babel_update_cost(n);
1245 | 
1246 |   /* Speed up session establishment by sending IHU immediately */
1247 |   if (first_hello)
1248 |   {
1249 |     /* if using RTT, all IHUs must be paired with hellos */
1250 |     if(cf->rtt_send)
1251 |       babel_send_hello(ifa, 0);
1252 |     else
1253 |       babel_send_ihu(ifa, n);
1254 |   }
1255 | }
