1257 | void
1258 | babel_handle_ihu(union babel_msg *m, struct babel_iface *ifa)
1259 | {
1260 |   struct babel_proto *p = ifa->proto;
1261 |   struct babel_msg_ihu *msg = &m->ihu;
1262 | 
1263 |   /* Ignore IHUs that are not about us */
1264 |   if ((msg->ae != BABEL_AE_WILDCARD) && !ipa_equal(msg->addr, ifa->addr))
1265 |     return;
1266 | 
1267 |   TRACE(D_PACKETS, "Handling IHU rxcost %d interval %t",
1268 | 	msg->rxcost, (btime) msg->interval);
1269 | 
1270 |   struct babel_neighbor *n = babel_get_neighbor(ifa, msg->sender);
1271 |   n->txcost = msg->rxcost;
1272 |   n->ihu_expiry = current_time() + BABEL_IHU_EXPIRY_FACTOR(msg->interval);
1273 | 
1274 |   if (msg->tstamp)
1275 |   {
1276 |     u32 rtt_sample = 0, pkt_received = msg->pkt_received TO_US;
1277 |     int remote_time, full_time;
1278 | 
1279 |     /* processing time reported by peer */
1280 |     remote_time = (n->last_tstamp - msg->tstamp_rcvd);
1281 |     /* time since we sent the last timestamp - RTT including remote time */
1282 |     full_time = (pkt_received - msg->tstamp);
1283 | 
1284 |     /* sanity checks */
1285 |     if (remote_time < 0 || full_time < 0 ||
1286 |         remote_time US_ > BABEL_RTT_MAX_VALUE || full_time US_ > BABEL_RTT_MAX_VALUE)
1287 |       goto out;
1288 | 
1289 |     if (remote_time < full_time)
1290 |       rtt_sample = full_time - remote_time;
1291 | 
1292 |     if (n->srtt)
1293 |     {
1294 |       uint decay = n->ifa->cf->rtt_decay;
1295 | 
1296 |       n->srtt = (decay * rtt_sample + (256 - decay) * n->srtt) / 256;
1297 |     }
1298 |     else
1299 |       n->srtt = rtt_sample;
1300 | 
1301 |     TRACE(D_EVENTS, "RTT sample for neighbour %I on %s: %u us (srtt %t ms)",
1302 |           n->addr, ifa->ifname, rtt_sample, n->srtt * 1000);
1303 |   }
1304 | 
1305 | out:
1306 |   babel_update_cost(n);
1307 | }
