1309 | /**
1310 |  * babel_handle_update - handle incoming route updates
1311 |  * @m: Incoming update TLV
1312 |  * @ifa: Interface the update was received on
1313 |  *
1314 |  * This function is called as a handler for update TLVs and handles the updating
1315 |  * and maintenance of route entries in Babel's internal routing cache. The
1316 |  * handling follows the actions described in the Babel RFC, and at the end of
1317 |  * each update handling, babel_select_route() is called on the affected entry to
1318 |  * optionally update the selected routes and propagate them to the core.
1319 |  */
1320 | void
1321 | babel_handle_update(union babel_msg *m, struct babel_iface *ifa)
1322 | {
1323 |   struct babel_proto *p = ifa->proto;
1324 |   struct babel_msg_update *msg = &m->update;
1325 | 
1326 |   struct babel_neighbor *nbr;
1327 |   struct babel_entry *e;
1328 |   struct babel_source *s;
1329 |   struct babel_route *r, *best;
1330 |   node *n;
1331 |   int feasible, metric;
1332 | 
1333 |   if (msg->wildcard)
1334 |     TRACE(D_PACKETS, "Handling wildcard retraction", msg->seqno);
1335 |   else
1336 |     TRACE(D_PACKETS, "Handling update for %N with seqno %d metric %d",
1337 | 	  &msg->net, msg->seqno, msg->metric);
1338 | 
1339 |   nbr = babel_find_neighbor(ifa, msg->sender);
1340 |   if (!nbr)
1341 |   {
1342 |     DBG("Babel: Haven't heard from neighbor %I; ignoring update.\n", msg->sender);
1343 |     return;
1344 |   }
1345 | 
1346 |   if (msg->router_id == p->router_id)
1347 |   {
1348 |     DBG("Babel: Ignoring update for our own router ID.\n");
1349 |     return;
1350 |   }
1351 | 
1352 |   struct channel *c = (msg->net.type == NET_IP4) ? p->ip4_channel : p->ip6_channel;
1353 |   if (!c || (c->channel_state != CS_UP))
1354 |   {
1355 |     DBG("Babel: Ignoring update for inactive address family.\n");
1356 |     return;
1357 |   }
1358 | 
1359 |   /* Reject IPv4 via IPv6 routes if disabled */
1360 |   if ((msg->net.type == NET_IP4) && ipa_is_ip6(msg->next_hop) && !ifa->cf->ext_next_hop)
1361 |   {
1362 |     DBG("Babel: Ignoring disabled IPv4 via IPv6 route.\n");
1363 |     return;
1364 |   }
1365 | 
1366 |   /* Retraction */
1367 |   if (msg->metric == BABEL_INFINITY)
1368 |   {
1369 |     if (msg->wildcard)
1370 |     {
1371 |       /*
1372 |        * Special case: This is a retraction of all prefixes announced by this
1373 |        * neighbour (see second-to-last paragraph of section 4.4.9 in the RFC).
1374 |        */
1375 |       WALK_LIST(n, nbr->routes)
1376 |       {
1377 | 	r = SKIP_BACK(struct babel_route, neigh_route, n);
1378 | 	babel_retract_route(p, r);
1379 |       }
1380 |     }
1381 |     else
1382 |     {
1383 |       e = babel_find_entry(p, &msg->net);
1384 | 
1385 |       if (!e)
1386 | 	return;
1387 | 
1388 |       /* The route entry indexed by neighbour */
1389 |       r = babel_find_route(e, nbr);
1390 | 
1391 |       if (!r)
1392 | 	return;
1393 | 
1394 |       /* Router-id, next-hop and seqno are ignored for retractions */
1395 |       babel_retract_route(p, r);
1396 |     }
1397 | 
1398 |     /* Done with retractions */
1399 |     return;
1400 |   }
1401 | 
1402 |   /* Regular update */
1403 |   e = babel_get_entry(p, &msg->net);
1404 |   r = babel_get_route(p, e, nbr); /* the route entry indexed by neighbour */
1405 |   s = babel_find_source(e, msg->router_id); /* for feasibility */
1406 |   feasible = babel_is_feasible(s, msg->seqno, msg->metric);
1407 |   metric = babel_compute_metric(nbr, msg->metric);
1408 |   best = e->selected;
1409 | 
1410 |   /*
1411 |    * RFC 8966 3.8.2.2 - dealing with unfeasible updates. Generate a one-off
1412 |    * (not retransmitted) unicast seqno request to the originator of this update.
1413 |    * Note: !feasible -> s exists, check for 's' is just for clarity / safety.
1414 |    */
1415 |   if (!feasible && s && (metric != BABEL_INFINITY) &&
1416 |       (!best || (r == best) || (metric < best->metric)))
1417 |     babel_generate_seqno_request(p, e, s->router_id, s->seqno + 1, nbr);
1418 | 
1419 |   /* Special case - ignore unfeasible update to best route */
1420 |   if (r == best && !feasible && (msg->router_id == r->router_id))
1421 |     return;
1422 | 
1423 |   r->expires = current_time() + BABEL_ROUTE_EXPIRY_FACTOR(msg->interval);
1424 |   r->refresh_time = current_time() + BABEL_ROUTE_REFRESH_FACTOR(msg->interval);
1425 | 
1426 |   /* No further processing if there is no change */
1427 |   if ((r->feasible == feasible) && (r->seqno == msg->seqno) &&
1428 |       (r->metric == metric) && (r->advert_metric == msg->metric) &&
1429 |       (r->router_id == msg->router_id) && ipa_equal(r->next_hop, msg->next_hop))
1430 |     return;
1431 | 
1432 |   /* Last paragraph above - update the entry */
1433 |   r->feasible = feasible;
1434 |   r->seqno = msg->seqno;
1435 |   r->metric = metric;
1436 |   r->advert_metric = msg->metric;
1437 |   r->router_id = msg->router_id;
1438 |   r->next_hop = msg->next_hop;
1439 | 
1440 |   /* If received update satisfies seqno request, we send triggered updates */
1441 |   if (babel_satisfy_seqno_request(p, e, msg->router_id, msg->seqno))
1442 |   {
1443 |     babel_trigger_update(p);
1444 |     e->updated = current_time();
1445 |   }
1446 | 
1447 |   babel_select_route(p, e, r);
1448 | }
1449 | 
1450 | void
1451 | babel_handle_route_request(union babel_msg *m, struct babel_iface *ifa)
1452 | {
1453 |   struct babel_proto *p = ifa->proto;
1454 |   struct babel_msg_route_request *msg = &m->route_request;
1455 | 
1456 |   /* RFC 8966 3.8.1.1 */
1457 | 
1458 |   /* Wildcard request - full update on the interface */
1459 |   if (msg->full)
1460 |   {
1461 |     TRACE(D_PACKETS, "Handling wildcard route request");
1462 |     ifa->want_triggered = 1;
1463 |     return;
1464 |   }
1465 | 
1466 |   TRACE(D_PACKETS, "Handling route request for %N", &msg->net);
1467 | 
1468 |   /* Non-wildcard request - see if we have an entry for the route.
1469 |      If not, send a retraction, otherwise send an update. */
1470 |   struct babel_entry *e = babel_find_entry(p, &msg->net);
1471 |   if (!e)
1472 |   {
1473 |     babel_send_retraction(ifa, &msg->net);
1474 |   }
1475 |   else
1476 |   {
1477 |     babel_trigger_iface_update(ifa);
1478 |     e->updated = current_time();
1479 |   }
1480 | }
1481 | 
1482 | static struct babel_neighbor *
1483 | babel_find_seqno_request_target(struct babel_entry *e, struct babel_neighbor *skip)
1484 | {
1485 |   struct babel_route *r, *best_feasible = NULL, *best_any = NULL;
1486 | 
1487 |   WALK_LIST(r, e->routes)
1488 |   {
1489 |     if (r->neigh == skip)
1490 |       continue;
1491 | 
1492 |     if (r->feasible && (!best_feasible || r->metric < best_feasible->metric))
1493 |       best_feasible = r;
1494 | 
1495 |     if (!best_any || r->metric < best_any->metric)
1496 |       best_any = r;
1497 |   }
1498 | 
1499 |   if (best_feasible)
1500 |     return best_feasible->neigh;
1501 | 
1502 |   if (best_any)
1503 |     return best_any->neigh;
1504 | 
1505 |   return NULL;
1506 | }
1507 | 
1508 | void
1509 | babel_handle_seqno_request(union babel_msg *m, struct babel_iface *ifa)
1510 | {
1511 |   struct babel_proto *p = ifa->proto;
1512 |   struct babel_msg_seqno_request *msg = &m->seqno_request;
1513 | 
1514 |   /* RFC 8966 3.8.1.2 */
1515 | 
1516 |   TRACE(D_PACKETS, "Handling seqno request for %N router-id %lR seqno %d hop count %d",
1517 | 	&msg->net, msg->router_id, msg->seqno, msg->hop_count);
1518 | 
1519 |   /* Ignore if we have no such entry or entry has infinite metric */
1520 |   struct babel_entry *e = babel_find_entry(p, &msg->net);
1521 |   if (!e || !e->valid || (e->metric == BABEL_INFINITY))
1522 |     return;
1523 | 
1524 |   /* Trigger update on incoming interface if we have a selected route with
1525 |      different router id or seqno no smaller than requested */
1526 |   if ((e->router_id != msg->router_id) || ge_mod64k(e->seqno, msg->seqno))
1527 |   {
1528 |     babel_trigger_iface_update(ifa);
1529 |     e->updated = current_time();
1530 |     return;
1531 |   }
1532 | 
1533 |   /* Seqno is larger; check if we own the router id */
1534 |   if (msg->router_id == p->router_id)
1535 |   {
1536 |     /* Ours; seqno increase and trigger global update */
1537 |     p->update_seqno_inc = 1;
1538 |     babel_trigger_update(p);
1539 |   }
1540 |   else if (msg->hop_count > 1)
1541 |   {
1542 |     /* Not ours; forward if TTL allows it */
1543 | 
1544 |     struct babel_neighbor *nbr, *target;
1545 | 
1546 |     nbr = babel_find_neighbor(ifa, msg->sender);
1547 |     if (!nbr)
1548 |       return;
1549 | 
1550 |     target = babel_find_seqno_request_target(e, nbr);
1551 |     if (!target)
1552 |     {
1553 |       TRACE(D_PACKETS, "No neighbor to forward seqno request for %N router-id %lR seqno %d to",
1554 |             e->n.addr, msg->router_id, msg->seqno);
1555 |       return;
1556 |     }
1557 | 
1558 |     babel_add_seqno_request(p, e, msg->router_id, msg->seqno, msg->hop_count-1, target);
1559 |   }
1560 | }
