1581 | static void
1582 | babel_auth_send_challenge_request(struct babel_iface *ifa, struct babel_neighbor *n)
1583 | {
1584 |   struct babel_proto *p = ifa->proto;
1585 |   union babel_msg msg = {};
1586 | 
1587 |   TRACE(D_PACKETS, "Sending challenge request to %I on %s",
1588 | 	n->addr, ifa->ifname);
1589 | 
1590 |   random_bytes(n->auth_nonce, BABEL_AUTH_NONCE_LEN);
1591 |   n->auth_nonce_expiry = current_time() + BABEL_AUTH_CHALLENGE_TIMEOUT;
1592 |   n->auth_next_challenge = current_time() + BABEL_AUTH_CHALLENGE_INTERVAL;
1593 | 
1594 |   msg.type = BABEL_TLV_CHALLENGE_REQUEST;
1595 |   msg.challenge.nonce_len = BABEL_AUTH_NONCE_LEN;
1596 |   msg.challenge.nonce = n->auth_nonce;
1597 | 
1598 |   babel_send_unicast(&msg, ifa, n->addr);
1599 | }
