1601 | static void
1602 | babel_auth_send_challenge_reply(struct babel_iface *ifa, struct babel_neighbor *n, struct babel_msg_auth *rcv)
1603 | {
1604 |   struct babel_proto *p = ifa->proto;
1605 |   union babel_msg msg = {};
1606 | 
1607 |   TRACE(D_PACKETS, "Sending challenge reply to %I on %s",
1608 | 	n->addr, ifa->ifname);
1609 | 
1610 |   n->auth_next_challenge_reply = current_time() + BABEL_AUTH_CHALLENGE_INTERVAL;
1611 | 
1612 |   msg.type = BABEL_TLV_CHALLENGE_REPLY;
1613 |   msg.challenge.nonce_len = rcv->challenge_len;
1614 |   msg.challenge.nonce = rcv->challenge;
1615 | 
1616 |   babel_send_unicast(&msg, ifa, n->addr);
1617 | }
1618 | 
1619 | int
1620 | babel_auth_check_pc(struct babel_iface *ifa, struct babel_msg_auth *msg)
1621 | {
1622 |   struct babel_proto *p = ifa->proto;
1623 |   struct babel_neighbor *n;
1624 | 
1625 |   /*
1626 |    * We create the neighbour entry at this point because it makes it easier to
1627 |    * rate limit challenge replies; this is explicitly allowed by the spec (see
1628 |    * Section 4.3).
1629 |    */
1630 |   n = babel_get_neighbor(ifa, msg->sender);
1631 | 
1632 |   /* (3b) Handle challenge request */
1633 |   if (msg->challenge_seen && (n->auth_next_challenge_reply <= current_time()))
1634 |     babel_auth_send_challenge_reply(ifa, n, msg);
1635 | 
1636 |   /* (4a) If PC TLV is missing, drop the packet */
1637 |   if (!msg->pc_seen)
1638 |   {
1639 |     LOG_PKT_AUTH("Authentication failed for %I on %s - missing or invalid PC",
1640 |                  msg->sender, ifa->ifname);
1641 |     return 0;
1642 |   }
1643 | 
1644 |   /* (4b) On successful challenge, update PC and index to current values */
1645 |   if (msg->challenge_reply_seen &&
1646 |       (n->auth_nonce_expiry > current_time()) &&
1647 |       !memcmp(msg->challenge_reply, n->auth_nonce, BABEL_AUTH_NONCE_LEN))
1648 |   {
1649 |     n->auth_index_len = msg->index_len;
1650 |     memcpy(n->auth_index, msg->index, msg->index_len);
1651 | 
1652 |     n->auth_pc_unicast = msg->pc;
1653 |     n->auth_pc_multicast = msg->pc;
1654 |     n->auth_passed = 1;
1655 | 
1656 |     return 1;
1657 |   }
1658 | 
1659 |   /* (5) If index differs, send challenge and drop the packet */
1660 |   if ((n->auth_index_len != msg->index_len) ||
1661 |       memcmp(n->auth_index, msg->index, msg->index_len))
1662 |   {
1663 |     TRACE(D_PACKETS, "Index mismatch for packet from %I via %s",
1664 | 	  msg->sender, ifa->ifname);
1665 | 
1666 |     if (n->auth_next_challenge <= current_time())
1667 |       babel_auth_send_challenge_request(ifa, n);
1668 | 
1669 |     return 0;
1670 |   }
1671 | 
1672 |   /*
1673 |    * (6) Index matches; only accept if PC is greater than last. We keep separate
1674 |    * counters for unicast and multicast because multicast packets can be delayed
1675 |    * significantly on wireless networks (enough to be received out of order).
1676 |    * Separate counters are safe because the packet destination address is part
1677 |    * of the MAC pseudo-header (so unicast packets can't be replayed as multicast
1678 |    * and vice versa).
1679 |    */
1680 |   u32 auth_pc = msg->unicast ? n->auth_pc_unicast : n->auth_pc_multicast;
1681 |   if (auth_pc >= msg->pc)
1682 |   {
1683 |     LOG_PKT_AUTH("Authentication failed for %I on %s - "
1684 | 		 "lower %s packet counter (rcv %u, old %u)",
1685 |                  msg->sender, ifa->ifname,
1686 | 		 msg->unicast ? "unicast" : "multicast",
1687 | 		 msg->pc, auth_pc);
1688 |     return 0;
1689 |   }
1690 | 
1691 |   if (msg->unicast)
1692 |     n->auth_pc_unicast = msg->pc;
1693 |   else
1694 |     n->auth_pc_multicast = msg->pc;
1695 | 
1696 |   n->auth_passed = 1;
1697 | 
1698 |   return 1;
1699 | }
