1702 | /*
1703 |  *	Babel interfaces
1704 |  */
1705 | 
1706 | /**
1707 |  * babel_iface_timer - Babel interface timer handler
1708 |  * @t: Timer
1709 |  *
1710 |  * This function is called by the per-interface timer and triggers sending of
1711 |  * periodic Hello's and both triggered and periodic updates. Periodic Hello's
1712 |  * and updates are simply handled by setting the next_{hello,regular} variables
1713 |  * on the interface, and triggering an update (and resetting the variable)
1714 |  * whenever 'now' exceeds that value.
1715 |  *
1716 |  * For triggered updates, babel_trigger_iface_update() will set the
1717 |  * want_triggered field on the interface to a timestamp value. If this is set
1718 |  * (and the next_triggered time has passed; this is a rate limiting mechanism),
1719 |  * babel_send_update() will be called with this timestamp as the second
1720 |  * parameter. This causes updates to be send consisting of only the routes that
1721 |  * have changed since the time saved in want_triggered.
1722 |  *
1723 |  * Mostly when an update is triggered, the route being modified will be set to
1724 |  * the value of 'now' at the time of the trigger; the >= comparison for
1725 |  * selecting which routes to send in the update will make sure this is included.
1726 |  */
1727 | static void
1728 | babel_iface_timer(timer *t)
1729 | {
1730 |   struct babel_iface *ifa = t->data;
1731 |   struct babel_proto *p = ifa->proto;
1732 |   btime hello_period = ifa->cf->hello_interval;
1733 |   btime update_period = ifa->cf->update_interval;
1734 |   btime now_ = current_time();
1735 | 
1736 |   if (now_ >= ifa->next_hello)
1737 |   {
1738 |     babel_send_hello(ifa, 0);
1739 |     ifa->next_hello += hello_period * (1 + (now_ - ifa->next_hello) / hello_period);
1740 |   }
1741 | 
1742 |   if (now_ >= ifa->next_regular)
1743 |   {
1744 |     TRACE(D_EVENTS, "Sending regular updates on %s", ifa->ifname);
1745 |     babel_send_update(ifa, 0);
1746 |     ifa->next_regular += update_period * (1 + (now_ - ifa->next_regular) / update_period);
1747 |     ifa->want_triggered = 0;
1748 |     p->triggered = 0;
1749 |   }
1750 |   else if (ifa->want_triggered && (now_ >= ifa->next_triggered))
1751 |   {
1752 |     TRACE(D_EVENTS, "Sending triggered updates on %s", ifa->ifname);
1753 |     babel_send_update(ifa, ifa->want_triggered);
1754 |     ifa->next_triggered = now_ + MIN(1 S, update_period / 2);
1755 |     ifa->want_triggered = 0;
1756 |     p->triggered = 0;
1757 |   }
1758 | 
1759 |   btime next_event = MIN(ifa->next_hello, ifa->next_regular);
1760 |   if (ifa->want_triggered) next_event = MIN(next_event, ifa->next_triggered);
1761 |   tm_set(ifa->timer, next_event);
1762 | }
1763 | 
1764 | static inline void
1765 | babel_iface_kick_timer(struct babel_iface *ifa)
1766 | {
1767 |   if (ifa->timer->expires > (current_time() + 100 MS))
1768 |     tm_start(ifa->timer, 100 MS);
1769 | }
1770 | 
1771 | static void
1772 | babel_iface_start(struct babel_iface *ifa)
1773 | {
1774 |   struct babel_proto *p = ifa->proto;
1775 | 
1776 |   TRACE(D_EVENTS, "Starting interface %s", ifa->ifname);
1777 | 
1778 |   ifa->next_hello = current_time() + (random() % ifa->cf->hello_interval);
1779 |   ifa->next_regular = current_time() + (random() % ifa->cf->update_interval);
1780 |   ifa->next_triggered = current_time() + MIN(1 S, ifa->cf->update_interval / 2);
1781 |   ifa->want_triggered = 0;	/* We send an immediate update (below) */
1782 |   tm_start(ifa->timer, 100 MS);
1783 |   ifa->up = 1;
1784 | 
1785 |   babel_send_hello(ifa, 0);
1786 |   babel_send_wildcard_retraction(ifa);
1787 |   babel_send_wildcard_request(ifa);
1788 |   babel_send_update(ifa, 0);	/* Full update */
1789 | }
1790 | 
1791 | static void
1792 | babel_iface_stop(struct babel_iface *ifa)
1793 | {
1794 |   struct babel_proto *p = ifa->proto;
1795 |   struct babel_neighbor *nbr;
1796 |   struct babel_route *r;
1797 |   node *n;
1798 | 
1799 |   TRACE(D_EVENTS, "Stopping interface %s", ifa->ifname);
1800 | 
1801 |   /*
1802 |    * Rather than just flushing the neighbours, we set the metric of their routes
1803 |    * to infinity. This allows us to keep the neighbour hello state for when the
1804 |    * interface comes back up. The routes will also be kept until they expire.
1805 |    */
1806 |   WALK_LIST(nbr, ifa->neigh_list)
1807 |   {
1808 |     WALK_LIST(n, nbr->routes)
1809 |     {
1810 |       r = SKIP_BACK(struct babel_route, neigh_route, n);
1811 |       babel_retract_route(p, r);
1812 |     }
1813 |   }
1814 | 
1815 |   tm_stop(ifa->timer);
1816 |   ifa->up = 0;
1817 | }
1818 | 
1819 | static inline int
1820 | babel_iface_link_up(struct babel_iface *ifa)
1821 | {
1822 |   return !ifa->cf->check_link || (ifa->iface->flags & IF_LINK_UP);
1823 | }
1824 | 
1825 | static void
1826 | babel_iface_update_state(struct babel_iface *ifa)
1827 | {
1828 |   int up = ifa->sk && babel_iface_link_up(ifa);
1829 | 
1830 |   if (up == ifa->up)
1831 |     return;
1832 | 
1833 |   if (up)
1834 |     babel_iface_start(ifa);
1835 |   else
1836 |     babel_iface_stop(ifa);
1837 | }
1838 | 
1839 | static void
1840 | babel_iface_update_addr4(struct babel_iface *ifa)
1841 | {
1842 |   struct babel_proto *p = ifa->proto;
1843 | 
1844 |   ip_addr addr4 = ifa->iface->addr4 ? ifa->iface->addr4->ip : IPA_NONE;
1845 |   ifa->next_hop_ip4 = ipa_nonzero(ifa->cf->next_hop_ip4) ? ifa->cf->next_hop_ip4 : addr4;
1846 | 
1847 |   if (ipa_zero(ifa->next_hop_ip4) && p->ip4_channel && !ifa->cf->ext_next_hop)
1848 |     log(L_WARN "%s: Missing IPv4 next hop address for %s", p->p.name, ifa->ifname);
1849 | 
1850 |   if (ifa->up)
1851 |     babel_iface_kick_timer(ifa);
1852 | }
1853 | 
1854 | static void
1855 | babel_iface_update_buffers(struct babel_iface *ifa)
1856 | {
1857 |   if (!ifa->sk)
1858 |     return;
1859 | 
1860 |   uint mtu = MAX(BABEL_MIN_MTU, ifa->iface->mtu);
1861 |   uint rbsize = ifa->cf->rx_buffer ?: mtu;
1862 |   uint tbsize = ifa->cf->tx_length ?: mtu;
1863 |   rbsize = MAX(rbsize, tbsize);
1864 | 
1865 |   sk_set_rbsize(ifa->sk, rbsize);
1866 |   sk_set_tbsize(ifa->sk, tbsize);
1867 | 
1868 |   ifa->tx_length = tbsize - BABEL_OVERHEAD;
1869 | 
1870 |   babel_auth_set_tx_overhead(ifa);
1871 | }
