1873 | static struct babel_iface*
1874 | babel_find_iface(struct babel_proto *p, struct iface *what)
1875 | {
1876 |   struct babel_iface *ifa;
1877 | 
1878 |   WALK_LIST (ifa, p->interfaces)
1879 |     if (ifa->iface == what)
1880 |       return ifa;
1881 | 
1882 |   return NULL;
1883 | }
