1885 | static void
1886 | babel_iface_locked(struct object_lock *lock)
1887 | {
1888 |   struct babel_iface *ifa = lock->data;
1889 |   struct babel_proto *p = ifa->proto;
1890 | 
1891 |   if (!babel_open_socket(ifa))
1892 |   {
1893 |     log(L_ERR "%s: Cannot open socket for %s", p->p.name, ifa->iface->name);
1894 |     return;
1895 |   }
1896 | 
1897 |   babel_iface_update_buffers(ifa);
1898 |   babel_iface_update_state(ifa);
