1901 | static void
1902 | babel_add_iface(struct babel_proto *p, struct iface *new, struct babel_iface_config *ic)
1903 | {
1904 |   struct babel_iface *ifa;
1905 | 
1906 |   TRACE(D_EVENTS, "Adding interface %s", new->name);
1907 | 
1908 |   pool *pool = rp_new(p->p.pool, new->name);
1909 | 
1910 |   ifa = mb_allocz(pool, sizeof(struct babel_iface));
1911 |   ifa->proto = p;
1912 |   ifa->iface = new;
1913 |   ifa->cf = ic;
1914 |   ifa->pool = pool;
1915 |   ifa->ifname = new->name;
1916 |   ifa->addr = new->llv6->ip;
1917 | 
1918 |   add_tail(&p->interfaces, NODE ifa);
1919 | 
1920 |   ip_addr addr4 = new->addr4 ? new->addr4->ip : IPA_NONE;
1921 |   ifa->next_hop_ip4 = ipa_nonzero(ic->next_hop_ip4) ? ic->next_hop_ip4 : addr4;
1922 |   ifa->next_hop_ip6 = ipa_nonzero(ic->next_hop_ip6) ? ic->next_hop_ip6 : ifa->addr;
1923 | 
1924 |   if (ipa_zero(ifa->next_hop_ip4) && p->ip4_channel && !ic->ext_next_hop)
1925 |     log(L_WARN "%s: Missing IPv4 next hop address for %s", p->p.name, ifa->ifname);
1926 | 
1927 |   init_list(&ifa->neigh_list);
1928 |   ifa->hello_seqno = 1;
1929 | 
1930 |   if (ic->auth_type != BABEL_AUTH_NONE)
1931 |     babel_auth_reset_index(ifa);
1932 | 
1933 |   ifa->timer = tm_new_init(ifa->pool, babel_iface_timer, ifa, 0, 0);
1934 | 
1935 |   init_list(&ifa->msg_queue);
1936 |   ifa->send_event = ev_new_init(ifa->pool, babel_send_queue, ifa);
1937 | 
1938 |   struct object_lock *lock = olock_new(ifa->pool);
1939 |   lock->type = OBJLOCK_UDP;
1940 |   lock->addr = IP6_BABEL_ROUTERS;
1941 |   lock->port = ifa->cf->port;
1942 |   lock->iface = ifa->iface;
1943 |   lock->hook = babel_iface_locked;
1944 |   lock->data = ifa;
1945 | 
1946 |   olock_acquire(lock);
1947 | }
