1949 | static void
1950 | babel_remove_iface(struct babel_proto *p, struct babel_iface *ifa)
1951 | {
1952 |   TRACE(D_EVENTS, "Removing interface %s", ifa->iface->name);
1953 | 
1954 |   struct babel_neighbor *n;
1955 |   WALK_LIST_FIRST(n, ifa->neigh_list)
1956 |     babel_flush_neighbor(p, n);
1957 | 
1958 |   rem_node(NODE ifa);
1959 | 
1960 |   rfree(ifa->pool); /* contains ifa itself, locks, socket, etc */
1961 | }
