1963 | static int
1964 | iface_is_valid(struct babel_proto *p, struct iface *iface)
1965 | {
1966 |   if (!(iface->flags & IF_MULTICAST))
1967 |   {
1968 |     log(L_ERR "%s: Interface %s does not support multicast",
1969 | 	p->p.name, iface->name);
1970 | 
1971 |     return 0;
1972 |   }
1973 | 
1974 |   return 1;
1975 | }
