1977 | static void
1978 | babel_if_notify(struct proto *P, unsigned flags, struct iface *iface)
1979 | {
1980 |   struct babel_proto *p = (void *) P;
1981 |   struct babel_config *cf = (void *) P->cf;
1982 |   struct babel_iface *ifa = babel_find_iface(p, iface);
1983 | 
1984 |   if (iface->flags & IF_IGNORE)
1985 |     return;
1986 | 
1987 |   /* Add, remove or restart interface */
1988 |   if (flags & (IF_CHANGE_UPDOWN | IF_CHANGE_LLV6))
1989 |   {
1990 |     if (ifa)
1991 |       babel_remove_iface(p, ifa);
1992 | 
1993 |     if (!(iface->flags & IF_UP))
1994 |       return;
1995 | 
1996 |     /* Ignore ifaces without link-local address */
1997 |     if (!iface->llv6)
1998 |       return;
1999 | 
2000 |     struct babel_iface_config *ic = (void *) iface_patt_find(&cf->iface_list, iface, NULL);
2001 | 
2002 |     if (ic && iface_is_valid(p, iface))
2003 |       babel_add_iface(p, iface, ic);
2004 | 
2005 |     return;
2006 |   }
2007 | 
2008 |   if (!ifa)
2009 |     return;
2010 | 
2011 |   if (flags & IF_CHANGE_ADDR4)
2012 |     babel_iface_update_addr4(ifa);
2013 | 
2014 |   if (flags & IF_CHANGE_MTU)
2015 |     babel_iface_update_buffers(ifa);
2016 | 
2017 |   if (flags & IF_CHANGE_LINK)
2018 |     babel_iface_update_state(ifa);
2019 | }
2020 | 
2021 | static int
2022 | babel_reconfigure_iface(struct babel_proto *p, struct babel_iface *ifa, struct babel_iface_config *new)
2023 | {
2024 |   struct babel_iface_config *old = ifa->cf;
2025 | 
2026 |   /* Change of these options would require to reset the iface socket */
2027 |   if ((new->port != old->port) ||
2028 |       (new->tx_tos != old->tx_tos) ||
2029 |       (new->tx_priority != old->tx_priority))
2030 |     return 0;
2031 | 
2032 |   TRACE(D_EVENTS, "Reconfiguring interface %s", ifa->iface->name);
2033 | 
2034 |   ifa->cf = new;
2035 | 
2036 |   ip_addr addr4 = ifa->iface->addr4 ? ifa->iface->addr4->ip : IPA_NONE;
2037 |   ifa->next_hop_ip4 = ipa_nonzero(new->next_hop_ip4) ? new->next_hop_ip4 : addr4;
2038 |   ifa->next_hop_ip6 = ipa_nonzero(new->next_hop_ip6) ? new->next_hop_ip6 : ifa->addr;
2039 | 
2040 |   babel_iface_update_buffers(ifa);
2041 | 
2042 |   if ((new->auth_type != BABEL_AUTH_NONE) && (new->auth_type != old->auth_type))
2043 |     babel_auth_reset_index(ifa);
2044 | 
2045 |   if (ipa_zero(ifa->next_hop_ip4) && p->ip4_channel && !new->ext_next_hop)
2046 |     log(L_WARN "%s: Missing IPv4 next hop address for %s", p->p.name, ifa->ifname);
2047 | 
2048 |   if (ifa->next_hello > (current_time() + new->hello_interval))
2049 |     ifa->next_hello = current_time() + (random() % new->hello_interval);
2050 | 
2051 |   if (ifa->next_regular > (current_time() + new->update_interval))
2052 |     ifa->next_regular = current_time() + (random() % new->update_interval);
2053 | 
2054 |   if (new->check_link != old->check_link)
2055 |     babel_iface_update_state(ifa);
2056 | 
2057 |   if (ifa->up)
2058 |     babel_iface_kick_timer(ifa);
2059 | 
2060 |   return 1;
2061 | }
