2063 | static void
2064 | babel_reconfigure_ifaces(struct babel_proto *p, struct babel_config *cf)
2065 | {
2066 |   struct iface *iface;
2067 | 
2068 |   WALK_LIST(iface, iface_list)
2069 |   {
2070 |     if (p->p.vrf_set && !if_in_vrf(iface, p->p.vrf))
2071 |       continue;
2072 | 
2073 |     if (!(iface->flags & IF_UP))
2074 |       continue;
2075 | 
2076 |     /* Ignore ifaces without link-local address */
2077 |     if (!iface->llv6)
2078 |       continue;
2079 | 
2080 |     struct babel_iface *ifa = babel_find_iface(p, iface);
2081 |     struct babel_iface_config *ic = (void *) iface_patt_find(&cf->iface_list, iface, NULL);
2082 | 
2083 |     if (ic && !iface_is_valid(p, iface))
2084 |       ic = NULL;
2085 | 
2086 |     if (ifa && ic)
2087 |     {
2088 |       if (babel_reconfigure_iface(p, ifa, ic))
2089 | 	continue;
2090 | 
2091 |       /* Hard restart */
2092 |       log(L_INFO "%s: Restarting interface %s", p->p.name, ifa->iface->name);
2093 |       babel_remove_iface(p, ifa);
2094 |       babel_add_iface(p, iface, ic);
2095 |     }
2096 | 
2097 |     if (ifa && !ic)
2098 |       babel_remove_iface(p, ifa);
2099 | 
2100 |     if (!ifa && ic)
2101 |       babel_add_iface(p, iface, ic);
2102 |   }
2103 | }
