2435 | /*
2436 |  * babel_rt_notify - core tells us about new route (possibly our own),
2437 |  * so store it into our data structures.
2438 |  */
2439 | static void
2440 | babel_rt_notify(struct proto *P, struct channel *c UNUSED, struct network *net,
2441 | 		struct rte *new, struct rte *old UNUSED)
2442 | {
2443 |   struct babel_proto *p = (void *) P;
2444 |   struct babel_entry *e;
2445 | 
2446 |   if (new)
2447 |   {
2448 |     /* Update */
2449 |     uint rt_seqno;
2450 |     uint rt_metric = ea_get_int(new->attrs->eattrs, EA_BABEL_METRIC, 0);
2451 |     u64 rt_router_id = 0;
2452 | 
2453 |     if (new->src->proto == P)
2454 |     {
2455 |       rt_seqno = ea_find(new->attrs->eattrs, EA_BABEL_SEQNO)->u.data;
2456 |       eattr *e = ea_find(new->attrs->eattrs, EA_BABEL_ROUTER_ID);
2457 |       if (e)
2458 | 	memcpy(&rt_router_id, e->u.ptr->data, sizeof(u64));
2459 |     }
2460 |     else
2461 |     {
2462 |       rt_seqno = p->update_seqno;
2463 |       rt_router_id = p->router_id;
2464 |     }
2465 | 
2466 |     if (rt_metric > BABEL_INFINITY)
2467 |     {
2468 |       log(L_WARN "%s: Invalid babel_metric value %u for route %N",
2469 | 	  p->p.name, rt_metric, net->n.addr);
2470 |       rt_metric = BABEL_INFINITY;
2471 |     }
2472 | 
2473 |     e = babel_get_entry(p, net->n.addr);
2474 | 
2475 |     /* Activate triggered updates */
2476 |     if ((e->valid != BABEL_ENTRY_VALID) ||
2477 | 	(e->router_id != rt_router_id))
2478 |     {
2479 |       babel_trigger_update(p);
2480 |       e->updated = current_time();
2481 |     }
2482 | 
2483 |     e->valid = BABEL_ENTRY_VALID;
2484 |     e->seqno = rt_seqno;
2485 |     e->metric = rt_metric;
2486 |     e->router_id = rt_router_id;
2487 |   }
2488 |   else
2489 |   {
2490 |     /* Withdraw */
2491 |     e = babel_find_entry(p, net->n.addr);
2492 | 
2493 |     if (!e || e->valid != BABEL_ENTRY_VALID)
2494 |       return;
2495 | 
2496 |     e->valid = BABEL_ENTRY_STALE;
2497 |     e->metric = BABEL_INFINITY;
2498 | 
2499 |     babel_trigger_update(p);
2500 |     e->updated = current_time();
2501 |   }
2502 | }
