2564 | static int
2565 | babel_start(struct proto *P)
2566 | {
2567 |   struct babel_proto *p = (void *) P;
2568 |   struct babel_config *cf = (void *) P->cf;
2569 |   u8 ip6_type = cf->ip6_channel ? cf->ip6_channel->net_type : NET_IP6;
2570 | 
2571 |   fib_init(&p->ip4_rtable, P->pool, NET_IP4, sizeof(struct babel_entry),
2572 | 	   OFFSETOF(struct babel_entry, n), 0, babel_init_entry);
2573 |   fib_init(&p->ip6_rtable, P->pool, ip6_type, sizeof(struct babel_entry),
2574 | 	   OFFSETOF(struct babel_entry, n), 0, babel_init_entry);
2575 | 
2576 |   init_list(&p->interfaces);
2577 |   p->timer = tm_new_init(P->pool, babel_timer, p, 1 S, 0);
2578 |   tm_start(p->timer, 1 S);
2579 |   p->update_seqno = 1;
2580 |   p->router_id = proto_get_router_id(&cf->c);
2581 | 
2582 |   if (cf->randomize_router_id)
2583 |     babel_randomize_router_id(p);
2584 | 
2585 |   p->route_slab = sl_new(P->pool, sizeof(struct babel_route));
