 170 | {
 171 |   return (struct bfd_session_config) {
 172 |     .min_rx_int = opts->min_rx_int ?: cf->min_rx_int,
 173 |     .min_tx_int = opts->min_tx_int ?: cf->min_tx_int,
 174 |     .idle_tx_int = opts->idle_tx_int ?: cf->idle_tx_int,
 175 |     .multiplier = opts->multiplier ?: cf->multiplier,
 176 |     .passive = opts->passive_set ? opts->passive : cf->passive,
 177 |     .auth_type = opts->auth_type ?: cf->auth_type,
 178 |     .passwords = opts->passwords ?: cf->passwords,
 179 |   };
 180 | }
