 182 | static void
 183 | bfd_session_update_state(struct bfd_session *s, uint state, uint diag)
 184 | {
 185 |   struct bfd_proto *p = s->ifa->bfd;
 186 |   uint old_state = s->loc_state;
 187 |   int notify;
 188 | 
 189 |   if (state == old_state)
 190 |     return;
 191 | 
 192 |   TRACE(D_EVENTS, "Session to %I changed state from %s to %s",
 193 | 	s->addr, bfd_state_names[old_state], bfd_state_names[state]);
 194 | 
 195 |   bfd_lock_sessions(p);
 196 |   s->loc_state = state;
 197 |   s->loc_diag = diag;
 198 |   s->last_state_change = current_time();
 199 | 
 200 |   notify = !NODE_VALID(&s->n);
 201 |   if (notify)
 202 |     add_tail(&p->notify_list, &s->n);
 203 |   bfd_unlock_sessions(p);
 204 | 
 205 |   if (state == BFD_STATE_UP)
 206 |     bfd_session_set_min_tx(s, s->cf.min_tx_int);
 207 | 
 208 |   if (old_state == BFD_STATE_UP)
 209 |     bfd_session_set_min_tx(s, s->cf.idle_tx_int);
 210 | 
 211 |   if (notify)
 212 |     bfd_notify_kick(p);
 213 | }
 214 | 
 215 | static void
 216 | bfd_session_update_tx_interval(struct bfd_session *s)
 217 | {
 218 |   u32 tx_int = MAX(s->des_min_tx_int, s->rem_min_rx_int);
 219 |   u32 tx_int_l = tx_int - (tx_int / 4);	 // 75 %
 220 |   u32 tx_int_h = tx_int - (tx_int / 10); // 90 %
 221 | 
 222 |   s->tx_timer->recurrent = tx_int_l;
 223 |   s->tx_timer->randomize = tx_int_h - tx_int_l;
 224 | 
 225 |   /* Do not set timer if no previous event */
 226 |   if (!s->last_tx)
 227 |     return;
 228 | 
 229 |   /* Set timer relative to last tx_timer event */
 230 |   tm_set(s->tx_timer, s->last_tx + tx_int_l);
 231 | }
 232 | 
 233 | static void
 234 | bfd_session_update_detection_time(struct bfd_session *s, int kick)
 235 | {
 236 |   btime timeout = (btime) MAX(s->req_min_rx_int, s->rem_min_tx_int) * s->rem_detect_mult;
 237 | 
 238 |   if (kick)
 239 |     s->last_rx = current_time();
 240 | 
 241 |   if (!s->last_rx)
 242 |     return;
 243 | 
 244 |   tm_set(s->hold_timer, s->last_rx + timeout);
 245 | }
 246 | 
 247 | static void
 248 | bfd_session_control_tx_timer(struct bfd_session *s, int reset)
 249 | {
 250 |   // if (!s->opened) goto stop;
 251 | 
 252 |   if (s->passive && (s->rem_id == 0))
 253 |     goto stop;
 254 | 
 255 |   if (s->rem_demand_mode &&
 256 |       !s->poll_active &&
 257 |       (s->loc_state == BFD_STATE_UP) &&
 258 |       (s->rem_state == BFD_STATE_UP))
 259 |     goto stop;
 260 | 
 261 |   if (s->rem_min_rx_int == 0)
 262 |     goto stop;
 263 | 
 264 |   /* So TX timer should run */
 265 |   if (reset || !tm_active(s->tx_timer))
 266 |   {
 267 |     s->last_tx = 0;
 268 |     tm_start(s->tx_timer, 0);
 269 |   }
 270 | 
 271 |   return;
 272 | 
 273 | stop:
 274 |   tm_stop(s->tx_timer);
 275 |   s->last_tx = 0;
 276 | }
