 357 | static void
 358 | bfd_session_timeout(struct bfd_session *s)
 359 | {
 360 |   struct bfd_proto *p = s->ifa->bfd;
 361 | 
 362 |   TRACE(D_EVENTS, "Session to %I expired", s->addr);
 363 | 
 364 |   s->rem_state = BFD_STATE_DOWN;
 365 |   s->rem_id = 0;
 366 |   s->rem_min_tx_int = 0;
 367 |   s->rem_min_rx_int = 1;
 368 |   s->rem_demand_mode = 0;
 369 |   s->rem_detect_mult = 0;
 370 |   s->rx_csn_known = 0;
 371 | 
 372 |   s->poll_active = 0;
 373 |   s->poll_scheduled = 0;
 374 | 
 375 |   bfd_session_update_state(s, BFD_STATE_DOWN, BFD_DIAG_TIMEOUT);
 376 | 
 377 |   bfd_session_control_tx_timer(s, 1);
 378 | }
