 557 | static void
 558 | bfd_reconfigure_session(struct bfd_proto *p, struct bfd_session *s)
 559 | {
 560 |   if (EMPTY_LIST(s->request_list))
 561 |     return;
 562 | 
 563 |   birdloop_enter(p->loop);
 564 | 
 565 |   struct bfd_request *req = SKIP_BACK(struct bfd_request, n, HEAD(s->request_list));
 566 |   s->cf = bfd_merge_options(s->ifa->cf, &req->opts);
 567 | 
 568 |   u32 tx = (s->loc_state == BFD_STATE_UP) ? s->cf.min_tx_int : s->cf.idle_tx_int;
 569 |   bfd_session_set_min_tx(s, tx);
 570 |   bfd_session_set_min_rx(s, s->cf.min_rx_int);
 571 |   s->detect_mult = s->cf.multiplier;
 572 |   s->passive = s->cf.passive;
 573 | 
 574 |   bfd_session_control_tx_timer(s, 0);
 575 | 
 576 |   birdloop_leave(p->loop);
 577 | 
 578 |   TRACE(D_EVENTS, "Session to %I reconfigured", s->addr);
 579 | }
