 593 | static inline struct bfd_iface_config *
 594 | bfd_find_iface_config(struct bfd_config *cf, struct iface *iface)
 595 | {
 596 |   struct bfd_iface_config *ic;
 597 | 
 598 |   ic = iface ? (void *) iface_patt_find(&cf->patt_list, iface, NULL) : cf->multihop;
 599 | 
 600 |   return ic ? ic : &bfd_default_iface;
 601 | }
