 632 | static void
 633 | bfd_free_iface(struct bfd_iface *ifa)
 634 | {
 635 |   if (!ifa || --ifa->uc)
 636 |     return;
 637 | 
 638 |   if (ifa->sk)
 639 |   {
 640 |     sk_stop(ifa->sk);
 641 |     rfree(ifa->sk);
 642 |   }
 643 | 
 644 |   if (ifa->rx)
 645 |   {
 646 |     sk_stop(ifa->rx);
 647 |     rfree(ifa->rx);
 648 |   }
 649 | 
 650 |   rem_node(&ifa->n);
 651 |   mb_free(ifa);
 652 | }
