 654 | static void
 655 | bfd_reconfigure_iface(struct bfd_proto *p, struct bfd_iface *ifa, struct bfd_config *nc)
 656 | {
 657 |   struct bfd_iface_config *new = bfd_find_iface_config(nc, ifa->iface);
 658 |   struct bfd_iface_config *old = ifa->cf;
 659 | 
 660 |   /* Any configuration change should trigger bfd_reconfigure_session() */
 661 |   ifa->changed =
 662 |     (new->min_rx_int != old->min_rx_int) ||
 663 |     (new->min_tx_int != old->min_tx_int) ||
 664 |     (new->idle_tx_int != old->idle_tx_int) ||
 665 |     (new->multiplier != old->multiplier) ||
 666 |     (new->passive != old->passive) ||
 667 |     (new->auth_type != old->auth_type) ||
 668 |     (new->passwords != old->passwords);
 669 | 
 670 |   /* This should be probably changed to not access ifa->cf from the BFD thread */
 671 |   birdloop_enter(p->loop);
 672 |   ifa->cf = new;
 673 |   birdloop_leave(p->loop);
 674 | }
