 772 | static struct resclass bfd_request_class;
 773 | 
 774 | struct bfd_request *
 775 | bfd_request_session(pool *p, ip_addr addr, ip_addr local,
 776 | 		    struct iface *iface, struct iface *vrf,
 777 | 		    void (*hook)(struct bfd_request *), void *data,
 778 | 		    const struct bfd_options *opts)
 779 | {
 780 |   struct bfd_request *req = ralloc(p, &bfd_request_class);
 781 | 
 782 |   /* Hack: self-link req->n, we will call rem_node() on it */
