 925 | static void
 926 | bfd_reconfigure_neighbors(struct bfd_proto *p, struct bfd_config *new)
 927 | {
 928 |   struct bfd_config *old = (struct bfd_config *) (p->p.cf);
 929 |   struct bfd_neighbor *on, *nn;
 930 | 
 931 |   WALK_LIST(on, old->neigh_list)
 932 |   {
 933 |     WALK_LIST(nn, new->neigh_list)
 934 |       if (bfd_same_neighbor(nn, on))
 935 |       {
 936 | 	nn->neigh = on->neigh;
 937 | 	if (nn->neigh)
 938 | 	  nn->neigh->data = nn;
 939 | 
 940 | 	nn->req = on->req;
 941 | 	nn->active = 1;
 942 | 	goto next;
 943 |       }
 944 | 
 945 |     bfd_stop_neighbor(p, on);
 946 |   next:;
 947 |   }
 948 | 
 949 |   WALK_LIST(nn, new->neigh_list)
 950 |     if (!nn->active)
 951 |       bfd_start_neighbor(p, nn);
 952 | }
