1023 |   int rv = pipe(pfds);
1024 |   if (rv < 0)
1025 |     die("pipe: %m");
1026 | 
1027 |   sk = sk_new(p->p.pool);
1028 |   sk->type = SK_MAGIC;
1029 |   sk->rx_hook = bfd_notify_hook;
1030 |   sk->err_hook = bfd_noterr_hook;
1031 |   sk->fd = pfds[0];
1032 |   sk->data = p;
