1083 | 
1084 |   birdloop_enter(p->loop);
1085 | 
1086 |   if (!cf->strict_bind)
1087 |   {
1088 |     if (cf->accept_ipv4 && cf->accept_direct)
1089 |       p->rx4_1 = bfd_open_rx_sk(p, 0, SK_IPV4);
1090 | 
1091 |     if (cf->accept_ipv4 && cf->accept_multihop)
