 182 | static void
 183 | bfd_session_update_state(struct bfd_session *s, uint state, uint diag)
 184 | {
 185 |   struct bfd_proto *p = s->ifa->bfd;
 186 |   uint old_state = s->loc_state;
 187 |   int notify;
 188 | 
 189 |   if (state == old_state)
 190 |     return;
 191 | 
 192 |   TRACE(D_EVENTS, "Session to %I changed state from %s to %s",
 193 | 	s->addr, bfd_state_names[old_state], bfd_state_names[state]);
 194 | 
 195 |   bfd_lock_sessions(p);
 196 |   s->loc_state = state;
 197 |   s->loc_diag = diag;
 198 |   s->last_state_change = current_time();
 199 | 
 200 |   notify = !NODE_VALID(&s->n);
 201 |   if (notify)
 202 |     add_tail(&p->notify_list, &s->n);
 203 |   bfd_unlock_sessions(p);
 204 | 
 205 |   if (state == BFD_STATE_UP)
 206 |     bfd_session_set_min_tx(s, s->cf.min_tx_int);
 207 | 
 208 |   if (old_state == BFD_STATE_UP)
 209 |     bfd_session_set_min_tx(s, s->cf.idle_tx_int);
 210 | 
 211 |   if (notify)
 212 |     bfd_notify_kick(p);
 213 | }
