 297 | bfd_session_terminate_poll(struct bfd_session *s)
 298 | {
 299 |   u8 poll_done = s->poll_active & ~s->poll_scheduled;
 300 | 
 301 |   if (poll_done & BFD_POLL_TX)
 302 |     s->des_min_tx_int = s->des_min_tx_new;
 303 | 
 304 |   if (poll_done & BFD_POLL_RX)
 305 |     s->req_min_rx_int = s->req_min_rx_new;
 306 | 
 307 |   s->poll_active = s->poll_scheduled;
 308 |   s->poll_scheduled = 0;
 309 | 
 310 |   /* Timers are updated by caller - bfd_session_process_ctl() */
 311 | }
