 313 | void
 314 | bfd_session_process_ctl(struct bfd_session *s, u8 flags, u32 old_tx_int, u32 old_rx_int)
 315 | {
 316 |   if (s->poll_active && (flags & BFD_FLAG_FINAL))
 317 |     bfd_session_terminate_poll(s);
 318 | 
 319 |   if ((s->des_min_tx_int != old_tx_int) || (s->rem_min_rx_int != old_rx_int))
 320 |     bfd_session_update_tx_interval(s);
 321 | 
 322 |   bfd_session_update_detection_time(s, 1);
 323 | 
 324 |   /* Update session state */
 325 |   int next_state = 0;
 326 |   int diag = BFD_DIAG_NOTHING;
 327 | 
 328 |   switch (s->loc_state)
 329 |   {
 330 |   case BFD_STATE_ADMIN_DOWN:
 331 |     return;
 332 | 
 333 |   case BFD_STATE_DOWN:
 334 |     if (s->rem_state == BFD_STATE_DOWN)		next_state = BFD_STATE_INIT;
 335 |     else if (s->rem_state == BFD_STATE_INIT)	next_state = BFD_STATE_UP;
 336 |     break;
 337 | 
 338 |   case BFD_STATE_INIT:
 339 |     if (s->rem_state == BFD_STATE_ADMIN_DOWN)	next_state = BFD_STATE_DOWN, diag = BFD_DIAG_NEIGHBOR_DOWN;
 340 |     else if (s->rem_state >= BFD_STATE_INIT)	next_state = BFD_STATE_UP;
 341 |     break;
 342 | 
 343 |   case BFD_STATE_UP:
 344 |     if (s->rem_state <= BFD_STATE_DOWN)		next_state = BFD_STATE_DOWN, diag = BFD_DIAG_NEIGHBOR_DOWN;
 345 |     break;
 346 |   }
 347 | 
 348 |   if (next_state)
 349 |     bfd_session_update_state(s, next_state, diag);
 350 | 
 351 |   bfd_session_control_tx_timer(s, 0);
 352 | 
 353 |   if (flags & BFD_FLAG_POLL)
 354 |     bfd_send_ctl(s->ifa->bfd, s, 1);
 355 | }
