 380 | static void
 381 | bfd_session_set_min_tx(struct bfd_session *s, u32 val)
 382 | {
 383 |   /* Note that des_min_tx_int <= des_min_tx_new */
 384 | 
 385 |   if (val == s->des_min_tx_new)
 386 |     return;
 387 | 
 388 |   s->des_min_tx_new = val;
 389 | 
 390 |   /* Postpone timer update if des_min_tx_int increases and the session is up */
 391 |   if ((s->loc_state != BFD_STATE_UP) || (val < s->des_min_tx_int))
 392 |   {
 393 |     s->des_min_tx_int = val;
 394 |     bfd_session_update_tx_interval(s);
 395 |   }
 396 | 
 397 |   bfd_session_request_poll(s, BFD_POLL_TX);
 398 | }
 399 | 
 400 | static void
 401 | bfd_session_set_min_rx(struct bfd_session *s, u32 val)
 402 | {
 403 |   /* Note that req_min_rx_int >= req_min_rx_new */
 404 | 
 405 |   if (val == s->req_min_rx_new)
 406 |     return;
 407 | 
 408 |   s->req_min_rx_new = val;
 409 | 
 410 |   /* Postpone timer update if req_min_rx_int decreases and the session is up */
 411 |   if ((s->loc_state != BFD_STATE_UP) || (val > s->req_min_rx_int))
 412 |   {
 413 |     s->req_min_rx_int = val;
 414 |     bfd_session_update_detection_time(s, 0);
 415 |   }
 416 | 
 417 |   bfd_session_request_poll(s, BFD_POLL_RX);
 418 | }
