 458 | static struct bfd_session *
 459 | bfd_add_session(struct bfd_proto *p, ip_addr addr, ip_addr local, struct iface *iface, struct bfd_options *opts)
 460 | {
 461 |   birdloop_enter(p->loop);
 462 | 
 463 |   struct bfd_iface *ifa = bfd_get_iface(p, local, iface);
 464 | 
 465 |   struct bfd_session *s = sl_allocz(p->session_slab);
 466 |   s->addr = addr;
 467 |   s->ifa = ifa;
 468 |   s->ifindex = iface ? iface->index : 0;
 469 |   s->loc_id = bfd_get_free_id(p);
 470 | 
 471 |   HASH_INSERT(p->session_hash_id, HASH_ID, s);
 472 |   HASH_INSERT(p->session_hash_ip, HASH_IP, s);
 473 | 
 474 |   s->cf = bfd_merge_options(ifa->cf, opts);
 475 | 
 476 |   /* Initialization of state variables - see RFC 5880 6.8.1 */
 477 |   s->loc_state = BFD_STATE_DOWN;
 478 |   s->rem_state = BFD_STATE_DOWN;
 479 |   s->des_min_tx_int = s->des_min_tx_new = s->cf.idle_tx_int;
 480 |   s->req_min_rx_int = s->req_min_rx_new = s->cf.min_rx_int;
 481 |   s->rem_min_rx_int = 1;
 482 |   s->detect_mult = s->cf.multiplier;
 483 |   s->passive = s->cf.passive;
 484 |   s->tx_csn = random_u32();
 485 | 
 486 |   s->tx_timer = tm_new_init(p->tpool, bfd_tx_timer_hook, s, 0, 0);
 487 |   s->hold_timer = tm_new_init(p->tpool, bfd_hold_timer_hook, s, 0, 0);
 488 |   bfd_session_update_tx_interval(s);
 489 |   bfd_session_control_tx_timer(s, 1);
 490 | 
 491 |   init_list(&s->request_list);
 492 |   s->last_state_change = current_time();
 493 | 
 494 |   TRACE(D_EVENTS, "Session to %I added", s->addr);
 495 | 
 496 |   birdloop_leave(p->loop);
 497 | 
 498 |   return s;
 499 | }
