 528 | static void
 529 | bfd_remove_session(struct bfd_proto *p, struct bfd_session *s)
 530 | {
 531 |   ip_addr ip = s->addr;
 532 | 
 533 |   /* Caller should ensure that request list is empty */
 534 | 
 535 |   birdloop_enter(p->loop);
 536 | 
 537 |   /* Remove session from notify list if scheduled for notification */
 538 |   /* No need for bfd_lock_sessions(), we are already protected by birdloop_enter() */
 539 |   if (NODE_VALID(&s->n))
 540 |     rem_node(&s->n);
 541 | 
 542 |   bfd_free_iface(s->ifa);
 543 | 
 544 |   rfree(s->tx_timer);
 545 |   rfree(s->hold_timer);
 546 | 
 547 |   HASH_REMOVE(p->session_hash_id, HASH_ID, s);
 548 |   HASH_REMOVE(p->session_hash_ip, HASH_IP, s);
 549 | 
 550 |   sl_free(s);
 551 | 
 552 |   TRACE(D_EVENTS, "Session to %I removed", ip);
 553 | 
 554 |   birdloop_leave(p->loop);
 555 | }
