 603 | static struct bfd_iface *
 604 | bfd_get_iface(struct bfd_proto *p, ip_addr local, struct iface *iface)
 605 | {
 606 |   struct bfd_iface *ifa;
 607 | 
 608 |   WALK_LIST(ifa, p->iface_list)
 609 |     if (ipa_equal(ifa->local, local) && (ifa->iface == iface))
 610 |       return ifa->uc++, ifa;
 611 | 
 612 |   struct bfd_config *cf = (struct bfd_config *) (p->p.cf);
 613 |   struct bfd_iface_config *ic = bfd_find_iface_config(cf, iface);
 614 | 
 615 |   ifa = mb_allocz(p->tpool, sizeof(struct bfd_iface));
 616 |   ifa->local = local;
 617 |   ifa->iface = iface;
 618 |   ifa->cf = ic;
 619 |   ifa->bfd = p;
 620 | 
 621 |   ifa->sk = bfd_open_tx_sk(p, local, iface);
 622 |   ifa->uc = 1;
 623 | 
 624 |   if (cf->strict_bind)
 625 |     ifa->rx = bfd_open_rx_sk_bound(p, local, iface);
 626 | 
 627 |   add_tail(&p->iface_list, &ifa->n);
 628 | 
 629 |   return ifa;
 630 | }
