 677 | /*
 678 |  *	BFD requests
 679 |  */
 680 | 
 681 | static void
 682 | bfd_request_notify(struct bfd_request *req, u8 state, u8 remote, u8 diag)
 683 | {
 684 |   u8 old_state = req->state;
 685 | 
 686 |   if (state == old_state)
 687 |     return;
 688 | 
 689 |   req->state = state;
 690 |   req->diag = diag;
 691 |   req->old_state = old_state;
 692 |   req->down = (old_state == BFD_STATE_UP) && (state == BFD_STATE_DOWN) && (remote != BFD_STATE_ADMIN_DOWN);
 693 | 
 694 |   if (req->hook)
 695 |     req->hook(req);
 696 | }
 697 | 
 698 | static int
 699 | bfd_add_request(struct bfd_proto *p, struct bfd_request *req)
 700 | {
 701 |   struct bfd_config *cf = (struct bfd_config *) (p->p.cf);
 702 | 
 703 |   if (p->p.vrf_set && (p->p.vrf != req->vrf))
 704 |     return 0;
 705 | 
 706 |   if (ipa_is_ip4(req->addr) ? !cf->accept_ipv4 : !cf->accept_ipv6)
 707 |     return 0;
 708 | 
 709 |   if (req->iface ? !cf->accept_direct : !cf->accept_multihop)
 710 |     return 0;
 711 | 
 712 |   uint ifindex = req->iface ? req->iface->index : 0;
 713 |   struct bfd_session *s = bfd_find_session_by_addr(p, req->addr, ifindex);
 714 |   u8 loc_state, rem_state, diag;
 715 | 
 716 |   if (!s)
 717 |     s = bfd_add_session(p, req->addr, req->local, req->iface, &req->opts);
 718 | 
 719 |   rem_node(&req->n);
 720 |   add_tail(&s->request_list, &req->n);
 721 |   req->session = s;
 722 | 
 723 |   bfd_lock_sessions(p);
 724 |   loc_state = s->loc_state;
 725 |   rem_state = s->rem_state;
 726 |   diag = s->loc_diag;
 727 |   bfd_unlock_sessions(p);
 728 | 
 729 |   bfd_request_notify(req, loc_state, rem_state, diag);
 730 | 
 731 |   return 1;
 732 | }
 733 | 
 734 | static void
 735 | bfd_submit_request(struct bfd_request *req)
 736 | {
 737 |   node *n;
 738 | 
 739 |   WALK_LIST(n, bfd_proto_list)
 740 |     if (bfd_add_request(SKIP_BACK(struct bfd_proto, bfd_node, n), req))
 741 |       return;
 742 | 
 743 |   rem_node(&req->n);
 744 |   add_tail(&bfd_wait_list, &req->n);
 745 |   req->session = NULL;
 746 |   bfd_request_notify(req, BFD_STATE_ADMIN_DOWN, BFD_STATE_ADMIN_DOWN, 0);
 747 | }
 748 | 
 749 | static void
 750 | bfd_take_requests(struct bfd_proto *p)
 751 | {
 752 |   node *n, *nn;
 753 | 
 754 |   WALK_LIST_DELSAFE(n, nn, bfd_wait_list)
 755 |     bfd_add_request(p, SKIP_BACK(struct bfd_request, n, n));
 756 | }
 757 | 
 758 | static void
 759 | bfd_drop_requests(struct bfd_proto *p)
 760 | {
 761 |   node *n;
 762 | 
 763 |   HASH_WALK(p->session_hash_id, next_id, s)
 764 |   {
 765 |     /* We assume that p is not in bfd_proto_list */
 766 |     WALK_LIST_FIRST(n, s->request_list)
 767 |       bfd_submit_request(SKIP_BACK(struct bfd_request, n, n));
 768 |   }
 769 |   HASH_WALK_END;
 770 | }
