 801 | void
 802 | bfd_update_request(struct bfd_request *req, const struct bfd_options *opts)
 803 | {
 804 |   struct bfd_session *s = req->session;
 805 | 
 806 |   if (!memcmp(opts, &req->opts, sizeof(const struct bfd_options)))
 807 |     return;
 808 | 
 809 |   req->opts = *opts;
 810 | 
 811 |   if (s)
 812 |     bfd_reconfigure_session(s->ifa->bfd, s);
 813 | }
