 815 | static void
 816 | bfd_request_free(resource *r)
 817 | {
 818 |   struct bfd_request *req = (struct bfd_request *) r;
 819 |   struct bfd_session *s = req->session;
 820 | 
 821 |   rem_node(&req->n);
 822 | 
 823 |   /* Remove the session if there is no request for it. Skip that if
 824 |      inside notify hooks, will be handled by bfd_notify_hook() itself */
 825 | 
 826 |   if (s && EMPTY_LIST(s->request_list) && !s->notify_running)
 827 |     bfd_remove_session(s->ifa->bfd, s);
 828 | }
