 830 | static void
 831 | bfd_request_dump(struct dump_request *dreq, resource *r)
 832 | {
 833 |   struct bfd_request *req = (struct bfd_request *) r;
 834 | 
 835 |   RDUMP("(code %p, data %p)\n", req->hook, req->data);
 836 | }
