 848 | /*
 849 |  *	BFD neighbors
 850 |  */
 851 | 
 852 | static void
 853 | bfd_neigh_notify(struct neighbor *nb)
 854 | {
 855 |   struct bfd_proto *p = (struct bfd_proto *) nb->proto;
 856 |   struct bfd_neighbor *n = nb->data;
 857 | 
 858 |   if (!n)
 859 |     return;
 860 | 
 861 |   if ((nb->scope > 0) && !n->req)
 862 |   {
 863 |     ip_addr local = ipa_nonzero(n->local) ? n->local : nb->ifa->ip;
 864 |     n->req = bfd_request_session(p->p.pool, n->addr, local, nb->iface, p->p.vrf, NULL, NULL, NULL);
 865 |   }
 866 | 
 867 |   if ((nb->scope <= 0) && n->req)
 868 |   {
 869 |     rfree(n->req);
 870 |     n->req = NULL;
 871 |   }
 872 | }
 873 | 
 874 | static void
 875 | bfd_start_neighbor(struct bfd_proto *p, struct bfd_neighbor *n)
 876 | {
 877 |   n->active = 1;
 878 | 
 879 |   if (n->multihop)
 880 |   {
 881 |     n->req = bfd_request_session(p->p.pool, n->addr, n->local, NULL, p->p.vrf, NULL, NULL, NULL);
 882 |     return;
 883 |   }
 884 | 
 885 |   struct neighbor *nb = neigh_find(&p->p, n->addr, n->iface, NEF_STICKY);
 886 |   if (!nb)
 887 |   {
 888 |     log(L_ERR "%s: Invalid remote address %I%J", p->p.name, n->addr, n->iface);
 889 |     return;
 890 |   }
 891 | 
 892 |   if (nb->data)
 893 |   {
 894 |     log(L_ERR "%s: Duplicate neighbor %I", p->p.name, n->addr);
 895 |     return;
 896 |   }
 897 | 
 898 |   n->neigh = nb;
 899 |   nb->data = n;
 900 | 
 901 |   if (nb->scope > 0)
 902 |     bfd_neigh_notify(nb);
 903 |   else
 904 |     TRACE(D_EVENTS, "Waiting for %I%J to become my neighbor", n->addr, n->iface);
 905 | }
 906 | 
 907 | static void
 908 | bfd_stop_neighbor(struct bfd_proto *p UNUSED, struct bfd_neighbor *n)
 909 | {
 910 |   if (n->neigh)
 911 |     n->neigh->data = NULL;
 912 |   n->neigh = NULL;
 913 | 
 914 |   rfree(n->req);
 915 |   n->req = NULL;
 916 | }
 917 | 
 918 | static inline int
 919 | bfd_same_neighbor(struct bfd_neighbor *x, struct bfd_neighbor *y)
 920 | {
 921 |   return ipa_equal(x->addr, y->addr) && ipa_equal(x->local, y->local) &&
 922 |     (x->iface == y->iface) && (x->multihop == y->multihop);
 923 | }
 924 | 
 925 | static void
 926 | bfd_reconfigure_neighbors(struct bfd_proto *p, struct bfd_config *new)
 927 | {
 928 |   struct bfd_config *old = (struct bfd_config *) (p->p.cf);
 929 |   struct bfd_neighbor *on, *nn;
 930 | 
 931 |   WALK_LIST(on, old->neigh_list)
 932 |   {
