 965 | static int
 966 | bfd_notify_hook(sock *sk, uint len UNUSED)
 967 | {
 968 |   struct bfd_proto *p = sk->data;
 969 |   struct bfd_session *s;
 970 |   list tmp_list;
 971 |   u8 loc_state, rem_state, diag;
 972 |   node *n, *nn;
 973 | 
 974 |   pipe_drain(sk->fd);
 975 | 
 976 |   bfd_lock_sessions(p);
 977 |   init_list(&tmp_list);
 978 |   add_tail_list(&tmp_list, &p->notify_list);
 979 |   init_list(&p->notify_list);
 980 |   bfd_unlock_sessions(p);
 981 | 
 982 |   WALK_LIST_FIRST(s, tmp_list)
 983 |   {
 984 |     bfd_lock_sessions(p);
 985 |     rem_node(&s->n);
 986 |     loc_state = s->loc_state;
 987 |     rem_state = s->rem_state;
 988 |     diag = s->loc_diag;
 989 |     bfd_unlock_sessions(p);
 990 | 
 991 |     s->notify_running = 1;
 992 |     WALK_LIST_DELSAFE(n, nn, s->request_list)
 993 |       bfd_request_notify(SKIP_BACK(struct bfd_request, n, n), loc_state, rem_state, diag);
 994 |     s->notify_running = 0;
 995 | 
 996 |     /* Remove the session if all requests were removed in notify hooks */
 997 |     if (EMPTY_LIST(s->request_list))
 998 |       bfd_remove_session(p, s);
 999 |   }
1000 | 
1001 |   return 0;
1002 | }
