1067 |   struct bfd_config *cf = (struct bfd_config *) (P->cf);
1068 | 
1069 |   p->loop = birdloop_new();
1070 |   p->tpool = rp_new(NULL, "BFD thread root");
1071 |   pthread_spin_init(&p->lock, PTHREAD_PROCESS_PRIVATE);
1072 | 
1073 |   p->session_slab = sl_new(P->pool, sizeof(struct bfd_session));
1074 |   HASH_INIT(p->session_hash_id, P->pool, 8);
1075 |   HASH_INIT(p->session_hash_ip, P->pool, 8);
1076 | 
1077 |   init_list(&p->iface_list);
1078 | 
1079 |   init_list(&p->notify_list);
1080 |   bfd_notify_init(p);
1081 | 
1082 |   add_tail(&bfd_proto_list, &p->bfd_node);
1083 | 
1084 |   birdloop_enter(p->loop);
1085 | 
1086 |   if (!cf->strict_bind)
1087 |   {
1088 |     if (cf->accept_ipv4 && cf->accept_direct)
1089 |       p->rx4_1 = bfd_open_rx_sk(p, 0, SK_IPV4);
1090 | 
1091 |     if (cf->accept_ipv4 && cf->accept_multihop)
1092 |       p->rx4_m = bfd_open_rx_sk(p, 1, SK_IPV4);
1093 | 
1094 |     if (cf->accept_ipv6 && cf->accept_direct)
1095 |       p->rx6_1 = bfd_open_rx_sk(p, 0, SK_IPV6);
1096 | 
1097 |     if (cf->accept_ipv6 && cf->accept_multihop)
1098 |       p->rx6_m = bfd_open_rx_sk(p, 1, SK_IPV6);
1099 |   }
1100 | 
1101 |   birdloop_leave(p->loop);
1102 | 
1103 |   bfd_take_requests(p);
1104 | 
1105 |   struct bfd_neighbor *n;
1106 |   WALK_LIST(n, cf->neigh_list)
1107 |     bfd_start_neighbor(p, n);
1108 | 
1109 |   birdloop_start(p->loop);
1110 | 
1111 |   return PS_UP;
