416 | sock *
417 | bfd_open_rx_sk(struct bfd_proto *p, int multihop, int af)
418 | {
419 |   struct bfd_config *cf = (struct bfd_config *) (p->p.cf);
420 | 
421 |   sock *sk = sk_new(p->tpool);
422 |   sk->type = SK_UDP;
423 |   sk->subtype = af;
424 |   sk->sport = !multihop ? BFD_CONTROL_PORT : BFD_MULTI_CTL_PORT;
425 |   sk->vrf = p->p.vrf;
426 |   sk->data = p;
427 | 
428 |   sk->rbsize = BFD_MAX_LEN;
429 |   sk->rx_hook = bfd_rx_hook;
430 |   sk->err_hook = bfd_err_hook;
431 | 
432 |   /* TODO: configurable ToS and priority */
433 |   sk->tos = IP_PREC_INTERNET_CONTROL;
434 |   sk->priority = sk_priority_control;
435 |   sk->flags = SKF_THREAD | SKF_LADDR_RX | (!multihop ? SKF_TTL_RX : 0);
436 | 
437 |   if (cf->zero_udp6_checksum_rx)
438 |     sk->flags |= SKF_UDP6_NO_CSUM_RX;
439 | 
440 |   if (sk_open(sk) < 0)
441 |     goto err;
442 | 
443 |   sk_start(sk);
444 |   return sk;
445 | 
446 | err:
447 |   sk_log_error(sk, p->p.name);
448 |   rfree(sk);
449 |   return NULL;
450 | }
