452 | sock *
453 | bfd_open_rx_sk_bound(struct bfd_proto *p, ip_addr local, struct iface *ifa)
454 | {
455 |   struct bfd_config *cf = (struct bfd_config *) (p->p.cf);
456 | 
457 |   sock *sk = sk_new(p->tpool);
458 |   sk->type = SK_UDP;
459 |   sk->saddr = local;
460 |   sk->sport = ifa ? BFD_CONTROL_PORT : BFD_MULTI_CTL_PORT;
461 |   sk->iface = ifa;
462 |   sk->vrf = p->p.vrf;
