180 | bfd_check_authentication(struct bfd_proto *p, struct bfd_session *s, struct bfd_ctl_packet *pkt)
181 | {
182 |   struct bfd_session_config *cf = &s->cf;
183 |   const char *err_dsc = NULL;
184 |   uint err_val = 0;
185 |   uint auth_type = 0;
186 |   uint meticulous = 0;
