321 | static int
322 | bfd_rx_hook(sock *sk, uint len)
323 | {
324 |   struct bfd_proto *p = sk->data;
325 |   struct bfd_ctl_packet *pkt = (struct bfd_ctl_packet *) sk->rbuf;
326 |   const char *err_dsc = NULL;
327 |   uint err_val = 0;
328 |   char fb[8];
329 | 
330 |   if ((sk->sport == BFD_CONTROL_PORT) && (sk->rcv_ttl < 255))
331 |     DROP("wrong TTL", sk->rcv_ttl);
332 | 
333 |   if (len < BFD_BASE_LEN)
334 |     DROP("too short", len);
335 | 
336 |   u8 version = bfd_pkt_get_version(pkt);
337 |   if (version != 1)
338 |     DROP("version mismatch", version);
339 | 
340 |   if ((pkt->length < BFD_BASE_LEN) || (pkt->length > len))
341 |     DROP("length mismatch", pkt->length);
342 | 
343 |   if (pkt->detect_mult == 0)
344 |     DROP("invalid detect mult", 0);
345 | 
346 |   if ((pkt->flags & BFD_FLAG_MULTIPOINT) ||
347 |       ((pkt->flags & BFD_FLAG_POLL) && (pkt->flags & BFD_FLAG_FINAL)))
348 |     DROP("invalid flags", pkt->flags);
349 | 
350 |   if (pkt->snd_id == 0)
351 |     DROP("invalid my discriminator", 0);
352 | 
353 |   struct bfd_session *s;
354 |   u32 id = ntohl(pkt->rcv_id);
355 | 
356 |   if (id)
357 |   {
358 |     s = bfd_find_session_by_id(p, id);
359 | 
360 |     if (!s)
361 |       DROP("unknown session id", id);
362 |   }
363 |   else
364 |   {
365 |     u8 ps = bfd_pkt_get_state(pkt);
366 |     if (ps > BFD_STATE_DOWN)
367 |       DROP("invalid init state", ps);
368 | 
369 |     uint ifindex = (sk->sport == BFD_CONTROL_PORT) ?
370 |       (sk->iface ? sk->iface->index : sk->lifindex) :
371 |       0;
372 |     s = bfd_find_session_by_addr(p, sk->faddr, ifindex);
373 | 
374 |     /* FIXME: better session matching and message */
375 |     if (!s)
376 |       return 1;
377 | 
378 |     /* For active sessions we require matching remote id */
379 |     if ((s->loc_state == BFD_STATE_UP) && (ntohl(pkt->snd_id) != s->rem_id))
380 |       DROP("mismatched remote id", ntohl(pkt->snd_id));
381 |   }
382 | 
383 |   /* bfd_check_authentication() has its own error logging */
384 |   if (!bfd_check_authentication(p, s, pkt))
385 |     return 1;
386 | 
387 |   u32 old_tx_int = s->des_min_tx_int;
388 |   u32 old_rx_int = s->rem_min_rx_int;
389 | 
390 |   s->rem_id = ntohl(pkt->snd_id);
391 |   s->rem_state = bfd_pkt_get_state(pkt);
392 |   s->rem_diag = bfd_pkt_get_diag(pkt);
393 |   s->rem_demand_mode = pkt->flags & BFD_FLAG_DEMAND;
394 |   s->rem_min_tx_int = ntohl(pkt->des_min_tx_int);
395 |   s->rem_min_rx_int = ntohl(pkt->req_min_rx_int);
396 |   s->rem_detect_mult = pkt->detect_mult;
397 | 
398 |   TRACE(D_PACKETS, "CTL received from %I [%s%s]", sk->faddr,
399 | 	bfd_state_names[s->rem_state], bfd_format_flags(pkt->flags, fb));
400 | 
401 |   bfd_session_process_ctl(s, pkt->flags, old_tx_int, old_rx_int);
402 |   return 1;
403 | 
404 | drop:
405 |   LOG_PKT("Bad packet from %I - %s (%u)", sk->faddr, err_dsc, err_val);
406 |   return 1;
407 | }
