 122 | static inline int
 123 | bgp_put_attr_hdr3(byte *buf, uint code, uint flags, uint len)
 124 | {
 125 |   *buf++ = flags & ~BAF_EXT_LEN;
 126 |   *buf++ = code;
 127 |   *buf++ = len;
 128 |   return 3;
 129 | }
