 131 | static inline int
 132 | bgp_put_attr_hdr4(byte *buf, uint code, uint flags, uint len)
 133 | {
 134 |   *buf++ = flags | BAF_EXT_LEN;
 135 |   *buf++ = code;
 136 |   put_u16(buf, len);
 137 |   return 4;
