 140 | static inline int
 141 | bgp_put_attr_hdr(byte *buf, uint code, uint flags, uint len)
 142 | {
 143 |   if (len < 256)
 144 |     return bgp_put_attr_hdr3(buf, code, flags, len);
 145 |   else
 146 |     return bgp_put_attr_hdr4(buf, code, flags, len);
