 149 | static int
 150 | bgp_encode_u8(struct bgp_write_state *s UNUSED, eattr *a, byte *buf, uint size)
 151 | {
 152 |   if (size < (3+1))
 153 |     return -1;
 154 | 
 155 |   bgp_put_attr_hdr3(buf, EA_ID(a->id), a->flags, 1);
 156 |   buf[3] = a->u.data;
 157 | 
