 173 | static int
 174 | bgp_encode_u32s(struct bgp_write_state *s UNUSED, eattr *a, byte *buf, uint size)
 175 | {
 176 |   uint len = a->u.ptr->length;
 177 | 
 178 |   if (size < (4+len))
