 418 | static inline int
 419 | bgp_as_path_first_as_equal(const byte *data, uint len, u32 asn)
 420 | {
 421 |   return (len >= 6) &&
 422 |     ((data[0] == AS_PATH_SEQUENCE) || (data[0] == AS_PATH_CONFED_SEQUENCE)) &&
 423 |     (data[1] > 0) &&
 424 |     (get_u32(data+2) == asn);
 425 | }
