 826 | 
 827 |   char err[128];
 828 | 
 829 |   if (s->as4_session)
 830 |     DISCARD(NEW_BGP, "AS4_PATH");
 831 | 
 832 |   if (len < 6)
 833 |     DISCARD(BAD_LENGTH, "AS4_PATH", len);
