1243 | /*
1244 |  *	Attribute encoding
1245 |  */
1246 | 
1247 | static inline int
1248 | bgp_encode_attr(struct bgp_write_state *s, eattr *a, byte *buf, uint size)
1249 | {
1250 |   if (EA_PROTO(a->id) != PROTOCOL_BGP)
1251 |     if (s->ignore_non_bgp_attrs)
1252 |       return 0;
1253 |     else
1254 |       bug("Tried to encode a non-BGP attribute");
1255 | 
1256 |   uint code = EA_ID(a->id);
1257 | 
1258 |   if (bgp_attr_known(code))
1259 |     return bgp_attr_table[code].encode(s, a, buf, size);
1260 |   else
1261 |     return bgp_encode_raw(s, a, buf, size);
1262 | }
1263 | 
1264 | /**
1265 |  * bgp_encode_attrs - encode BGP attributes
1266 |  * @s: BGP write state
1267 |  * @attrs: a list of extended attributes
1268 |  * @buf: buffer
1269 |  * @end: buffer end
1270 |  *
1271 |  * The bgp_encode_attrs() function takes a list of extended attributes
1272 |  * and converts it to its BGP representation (a part of an Update message).
1273 |  * BGP write state may be fake when called from MRT protocol.
1274 |  *
1275 |  * Result: Length of the attribute block generated or -1 if not enough space.
1276 |  */
1277 | int
1278 | bgp_encode_attrs(struct bgp_write_state *s, ea_list *attrs, byte *buf, byte *end)
1279 | {
1280 |   byte *pos = buf;
1281 |   int i, len;
1282 | 
1283 |   for (i = 0; i < attrs->count; i++)
1284 |   {
1285 |     len = bgp_encode_attr(s, &attrs->attrs[i], pos, end - pos);
1286 | 
1287 |     if (len < 0)
1288 |       return -1;
1289 | 
1290 |     pos += len;
1291 |   }
1292 | 
1293 |   return pos - buf;
1294 | }
