1735 | /*
1736 |  *	BGP protocol glue
1737 |  */
1738 | 
1739 | int
1740 | bgp_preexport(struct channel *C, rte *e)
1741 | {
1742 |   struct proto *SRC = e->src->proto;
1743 |   struct bgp_proto *p = (struct bgp_proto *) C->proto;
1744 |   struct bgp_proto *src = (SRC->proto == &proto_bgp) ? (struct bgp_proto *) SRC : NULL;
1745 |   struct bgp_channel *c = (struct bgp_channel *) C;
1746 | 
1747 |   /* Ignore non-BGP channels */
1748 |   if (C->channel != &channel_bgp)
1749 |     return -1;
1750 | 
1751 |   /* Reject our routes */
1752 |   if (src == p)
1753 |     return -1;
1754 | 
1755 |   /* Accept non-BGP routes */
1756 |   if (src == NULL)
1757 |     return 0;
1758 | 
1759 |   /* Reject flowspec that failed validation */
1760 |   if ((e->attrs->dest == RTD_UNREACHABLE) && net_is_flow(e->net->n.addr))
1761 |       return -1;
1762 | 
1763 |   /* IBGP route reflection, RFC 4456 */
1764 |   if (p->is_internal && src->is_internal && (p->local_as == src->local_as))
1765 |   {
1766 |     /* Rejected unless configured as route reflector */
1767 |     if (!p->rr_client && !src->rr_client)
1768 |       return -1;
1769 | 
1770 |     /* Generally, this should be handled when path is received, but we check it
1771 |        also here as rr_cluster_id may be undefined or different in src. */
1772 |     if (p->rr_cluster_id && bgp_cluster_list_loopy(p, e->attrs->eattrs))
1773 |       return -1;
1774 |   }
1775 | 
1776 |   /* Handle well-known communities, RFC 1997 */
1777 |   struct eattr *a;
1778 |   if (p->cf->interpret_communities &&
1779 |       (a = bgp_find_attr(e->attrs->eattrs, BA_COMMUNITY)))
1780 |   {
1781 |     const struct adata *d = a->u.ptr;
1782 | 
1783 |     /* Do not export anywhere */
1784 |     if (int_set_contains(d, BGP_COMM_NO_ADVERTISE))
1785 |       return -1;
1786 | 
1787 |     /* Do not export outside of AS (or member-AS) */
1788 |     if (!p->is_internal && int_set_contains(d, BGP_COMM_NO_EXPORT_SUBCONFED))
1789 |       return -1;
1790 | 
1791 |     /* Do not export outside of AS (or confederation) */
1792 |     if (!p->is_interior && int_set_contains(d, BGP_COMM_NO_EXPORT))
1793 |       return -1;
1794 | 
1795 |     /* Do not export LLGR_STALE routes to LLGR-ignorant peers */
1796 |     if (!p->conn->remote_caps->llgr_aware && int_set_contains(d, BGP_COMM_LLGR_STALE))
1797 |       return -1;
1798 |   }
1799 | 
1800 |   /* Do not export routes marked with OTC to upstream, RFC 9234 */
1801 |   if (bgp_channel_is_role_applicable(c))
1802 |   {
1803 |     a = bgp_find_attr(e->attrs->eattrs, BA_ONLY_TO_CUSTOMER);
1804 |     if (a && (p->cf->local_role==BGP_ROLE_CUSTOMER ||
1805 | 	      p->cf->local_role==BGP_ROLE_PEER ||
1806 | 	      p->cf->local_role==BGP_ROLE_RS_CLIENT))
1807 |       return -1;
1808 |   }
1809 | 
1810 |   return 0;
1811 | }
1812 | 
1813 | static ea_list *
1814 | bgp_update_attrs(struct bgp_proto *p, struct bgp_channel *c, rte *e, ea_list *attrs0, struct linpool *pool)
1815 | {
1816 |   struct proto *SRC = e->src->proto;
1817 |   struct bgp_proto *src = (SRC->proto == &proto_bgp) ? (void *) SRC : NULL;
1818 |   struct bgp_export_state s = { .proto = p, .channel = c, .pool = pool, .src = src, .route = e, .mpls = c->desc->mpls };
1819 |   ea_list *attrs = attrs0;
1820 |   eattr *a;
1821 |   const adata *ad;
1822 | 
1823 |   /* ORIGIN attribute - mandatory, attach if missing */
1824 |   if (! bgp_find_attr(attrs0, BA_ORIGIN))
1825 |     bgp_set_attr_u32(&attrs, pool, BA_ORIGIN, 0, src ? ORIGIN_INCOMPLETE : ORIGIN_IGP);
1826 | 
1827 |   /* AS_PATH attribute - mandatory */
1828 |   a = bgp_find_attr(attrs0, BA_AS_PATH);
1829 |   ad = a ? a->u.ptr : &null_adata;
1830 | 
1831 |   /* AS_PATH attribute - strip AS_CONFED* segments outside confederation */
1832 |   if ((!p->cf->confederation || !p->is_interior) && as_path_contains_confed(ad))
1833 |     ad = as_path_strip_confed(pool, ad);
1834 | 
1835 |   /* AS_PATH attribute - keep or prepend ASN */
1836 |   if (p->is_internal || p->rs_client)
1837 |   {
1838 |     /* IBGP or route server -> just ensure there is one */
1839 |     if (!a)
1840 |       bgp_set_attr_ptr(&attrs, pool, BA_AS_PATH, 0, &null_adata);
1841 |   }
1842 |   else if (p->is_interior)
1843 |   {
1844 |     /* Confederation -> prepend ASN as AS_CONFED_SEQUENCE */
1845 |     ad = as_path_prepend2(pool, ad, AS_PATH_CONFED_SEQUENCE, p->public_as);
1846 |     bgp_set_attr_ptr(&attrs, pool, BA_AS_PATH, 0, ad);
1847 |   }
1848 |   else /* Regular EBGP (no RS, no confederation) */
1849 |   {
1850 |     /* Regular EBGP -> prepend ASN as regular sequence */
1851 |     ad = as_path_prepend2(pool, ad, AS_PATH_SEQUENCE, p->public_as);
1852 |     bgp_set_attr_ptr(&attrs, pool, BA_AS_PATH, 0, ad);
1853 | 
1854 |     /* MULTI_EXIT_DESC attribute - accept only if set in export filter */
1855 |     a = bgp_find_attr(attrs0, BA_MULTI_EXIT_DISC);
1856 |     if (a && !a->fresh && !p->cf->allow_med)
1857 |       bgp_unset_attr(&attrs, pool, BA_MULTI_EXIT_DISC);
1858 |   }
1859 | 
1860 |   /* NEXT_HOP attribute - delegated to AF-specific hook */
1861 |   a = bgp_find_attr(attrs0, BA_NEXT_HOP);
1862 |   bgp_update_next_hop(&s, a, &attrs);
1863 | 
1864 |   /* LOCAL_PREF attribute - required for IBGP, attach if missing */
1865 |   if (p->is_interior && ! bgp_find_attr(attrs0, BA_LOCAL_PREF))
1866 |     bgp_set_attr_u32(&attrs, pool, BA_LOCAL_PREF, 0, p->cf->default_local_pref);
1867 | 
1868 |   /* AIGP attribute - accumulate local metric or originate new one */
1869 |   u64 metric;
1870 |   if (s.local_next_hop &&
1871 |       (bgp_total_aigp_metric_(e, &metric, &ad) ||
1872 |        (c->cf->aigp_originate && bgp_init_aigp_metric(e, &metric, &ad))))
1873 |   {
1874 |     ad = bgp_aigp_set_metric(pool, ad, metric);
1875 |     bgp_set_attr_ptr(&attrs, pool, BA_AIGP, 0, ad);
1876 |   }
1877 | 
1878 |   /* IBGP route reflection, RFC 4456 */
1879 |   if (src && src->is_internal && p->is_internal && (src->local_as == p->local_as))
1880 |   {
1881 |     /* ORIGINATOR_ID attribute - attach if not already set */
1882 |     if (! bgp_find_attr(attrs0, BA_ORIGINATOR_ID))
1883 |       bgp_set_attr_u32(&attrs, pool, BA_ORIGINATOR_ID, 0, src->remote_id);
1884 | 
1885 |     /* CLUSTER_LIST attribute - prepend cluster ID */
1886 |     a = bgp_find_attr(attrs0, BA_CLUSTER_LIST);
1887 |     ad = a ? a->u.ptr : NULL;
1888 | 
1889 |     /* Prepend src cluster ID */
1890 |     if (src->rr_cluster_id)
1891 |       ad = int_set_prepend(pool, ad, src->rr_cluster_id);
1892 | 
1893 |     /* Prepend dst cluster ID if src and dst clusters are different */
1894 |     if (p->rr_cluster_id && (src->rr_cluster_id != p->rr_cluster_id))
1895 |       ad = int_set_prepend(pool, ad, p->rr_cluster_id);
1896 | 
1897 |     /* Should be at least one prepended cluster ID */
1898 |     bgp_set_attr_ptr(&attrs, pool, BA_CLUSTER_LIST, 0, ad);
1899 |   }
1900 | 
1901 |   /* AS4_* transition attributes, RFC 6793 4.2.2 */
1902 |   if (! p->as4_session)
1903 |   {
1904 |     a = bgp_find_attr(attrs, BA_AS_PATH);
1905 |     if (a && as_path_contains_as4(a->u.ptr))
1906 |     {
1907 |       bgp_set_attr_ptr(&attrs, pool, BA_AS_PATH, 0, as_path_to_old(pool, a->u.ptr));
1908 |       bgp_set_attr_ptr(&attrs, pool, BA_AS4_PATH, 0, as_path_strip_confed(pool, a->u.ptr));
1909 |     }
1910 | 
1911 |     a = bgp_find_attr(attrs, BA_AGGREGATOR);
1912 |     if (a && aggregator_contains_as4(a->u.ptr))
1913 |     {
1914 |       bgp_set_attr_ptr(&attrs, pool, BA_AGGREGATOR, 0, aggregator_to_old(pool, a->u.ptr));
1915 |       bgp_set_attr_ptr(&attrs, pool, BA_AS4_AGGREGATOR, 0, a->u.ptr);
1916 |     }
1917 |   }
1918 | 
1919 |   /* Mark routes for downstream with OTC, RFC 9234 */
1920 |   if (bgp_channel_is_role_applicable(c))
1921 |   {
1922 |     a = bgp_find_attr(attrs, BA_ONLY_TO_CUSTOMER);
1923 |     if (!a && (p->cf->local_role == BGP_ROLE_PROVIDER ||
1924 | 	       p->cf->local_role == BGP_ROLE_PEER ||
1925 | 	       p->cf->local_role == BGP_ROLE_RS_SERVER))
1926 |       bgp_set_attr_u32(&attrs, pool, BA_ONLY_TO_CUSTOMER, 0, p->public_as);
1927 |   }
1928 | 
1929 |   /*
1930 |    * Presence of mandatory attributes ORIGIN and AS_PATH is ensured by above
1931 |    * conditions. Presence and validity of quasi-mandatory NEXT_HOP attribute
1932 |    * should be checked in AF-specific hooks.
1933 |    */
1934 | 
1935 |   /* Apply per-attribute export hooks for validatation and normalization */
1936 |   return bgp_export_attrs(&s, attrs);
1937 | }
