1939 | void
1940 | bgp_rt_notify(struct proto *P, struct channel *C, net *n, rte *new, rte *old)
1941 | {
1942 |   struct bgp_proto *p = (void *) P;
1943 |   struct bgp_channel *c = (void *) C;
1944 |   struct bgp_bucket *buck;
1945 |   struct bgp_prefix *px;
1946 |   u32 path;
1947 | 
1948 |   /* Ignore non-BGP channels */
1949 |   if (C->channel != &channel_bgp)
1950 |     return;
1951 | 
1952 |   if (new)
1953 |   {
1954 |     struct ea_list *attrs = bgp_update_attrs(p, c, new, new->attrs->eattrs, tmp_linpool);
1955 | 
1956 |     /* Error during attribute processing */
1957 |     if (!attrs)
1958 |       log(L_ERR "%s: Invalid route %N withdrawn", p->p.name, n->n.addr);
1959 | 
1960 |     /* If attributes are invalid, we fail back to withdraw */
1961 |     buck = attrs ? bgp_get_bucket(c, attrs) : bgp_get_withdraw_bucket(c);
1962 |     path = new->src->global_id;
1963 |   }
1964 |   else
1965 |   {
1966 |     buck = bgp_get_withdraw_bucket(c);
1967 |     path = old->src->global_id;
1968 |   }
1969 | 
1970 |   px = bgp_get_prefix(c, n->n.addr, c->add_path_tx ? path : 0);
1971 |   add_tail(&buck->prefixes, &px->buck_node);
1972 | 
1973 |   bgp_schedule_packet(p->conn, c, PKT_UPDATE);
1974 | }
