1977 | static inline u32
1978 | bgp_get_neighbor(rte *r)
1979 | {
1980 |   eattr *e = ea_find(r->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
1981 |   u32 as;
1982 | 
1983 |   if (e && as_path_get_first_regular(e->u.ptr, &as))
1984 |     return as;
1985 | 
1986 |   /* If AS_PATH is not defined, we treat rte as locally originated */
1987 |   struct bgp_proto *p = (void *) r->src->proto;
1988 |   return p->cf->confederation ?: p->local_as;
1989 | }
