2158 | 
2159 | int
2160 | bgp_rte_mergable(rte *pri, rte *sec)
2161 | {
2162 |   struct bgp_proto *pri_bgp = (struct bgp_proto *) pri->src->proto;
2163 |   struct bgp_proto *sec_bgp = (struct bgp_proto *) sec->src->proto;
2164 |   eattr *x, *y;
2165 |   u32 p, s;
2166 | 
2167 |   /* Skip suppressed routes (see bgp_rte_recalculate()) */
2168 |   if ((pri->pflags ^ sec->pflags) & BGP_REF_SUPPRESSED)
2169 |     return 0;
2170 | 
2171 |   /* RFC 4271 9.1.2.1. Route resolvability test */
2172 |   if (rte_resolvable(pri) != rte_resolvable(sec))
2173 |     return 0;
2174 | 
2175 |   /* LLGR 9494 - depreference stale routes */
2176 |   if (rte_stale(pri) != rte_stale(sec))
2177 |     return 0;
2178 | 
2179 |   /* Start with local preferences */
2180 |   x = ea_find(pri->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_LOCAL_PREF));
2181 |   y = ea_find(sec->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_LOCAL_PREF));
2182 |   p = x ? x->u.data : pri_bgp->cf->default_local_pref;
2183 |   s = y ? y->u.data : sec_bgp->cf->default_local_pref;
2184 |   if (p != s)
2185 |     return 0;
2186 | 
2187 |   /* RFC 4271 9.1.2.2. a)  Use AS path lengths */
2188 |   if (pri_bgp->cf->compare_path_lengths || sec_bgp->cf->compare_path_lengths)
2189 |   {
2190 |     x = ea_find(pri->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
2191 |     y = ea_find(sec->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
2192 |     p = x ? as_path_getlen(x->u.ptr) : AS_PATH_MAXLEN;
2193 |     s = y ? as_path_getlen(y->u.ptr) : AS_PATH_MAXLEN;
2194 | 
2195 |     if (p != s)
2196 |       return 0;
2197 | 
2198 | //    if (DELTA(p, s) > pri_bgp->cf->relax_multipath)
2199 | //      return 0;
2200 |   }
2201 | 
2202 |   /* RFC 4271 9.1.2.2. b) Use origins */
2203 |   x = ea_find(pri->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGIN));
2204 |   y = ea_find(sec->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGIN));
2205 |   p = x ? x->u.data : ORIGIN_INCOMPLETE;
2206 |   s = y ? y->u.data : ORIGIN_INCOMPLETE;
2207 |   if (p != s)
2208 |     return 0;
2209 | 
2210 |   /* RFC 4271 9.1.2.2. c) Compare MED's */
2211 |   if (pri_bgp->cf->med_metric || sec_bgp->cf->med_metric ||
2212 |       (bgp_get_neighbor(pri) == bgp_get_neighbor(sec)))
2213 |   {
2214 |     x = ea_find(pri->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_MULTI_EXIT_DISC));
2215 |     y = ea_find(sec->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_MULTI_EXIT_DISC));
2216 |     p = x ? x->u.data : pri_bgp->cf->default_med;
2217 |     s = y ? y->u.data : sec_bgp->cf->default_med;
2218 |     if (p != s)
2219 |       return 0;
2220 |   }
2221 | 
2222 |   /* RFC 4271 9.1.2.2. d) Prefer external peers */
2223 |   if (pri_bgp->is_interior != sec_bgp->is_interior)
2224 |     return 0;
2225 | 
2226 |   /* RFC 4271 9.1.2.2. e) Compare IGP metrics */
2227 |   p = pri_bgp->cf->igp_metric ? pri->attrs->igp_metric : 0;
2228 |   s = sec_bgp->cf->igp_metric ? sec->attrs->igp_metric : 0;
2229 |   if (p != s)
2230 |     return 0;
2231 | 
2232 |   /* Remaining criteria are ignored */
2233 | 
2234 |   return 1;
2235 | }
