2446 | int
2447 | bgp_get_attr(const eattr *a, byte *buf, int buflen)
2448 | {
2449 |   uint i = EA_ID(a->id);
2450 |   const struct bgp_attr_desc *d;
2451 |   int len;
2452 | 
2453 |   if (bgp_attr_known(i))
2454 |   {
2455 |     d = &bgp_attr_table[i];
2456 |     len = bsprintf(buf, "%s", d->name);
2457 |     buf += len;
2458 |     if (d->format)
2459 |     {
2460 |       *buf++ = ':';
2461 |       *buf++ = ' ';
2462 |       d->format(a, buf, buflen - len - 2);
2463 |       return GA_FULL;
2464 |     }
2465 |     return GA_NAME;
2466 |   }
2467 | 
2468 |   bsprintf(buf, "%02x%s", i, (a->flags & BAF_TRANSITIVE) ? " [t]" : "");
2469 |   return GA_NAME;
2470 | }
