2472 | void
2473 | bgp_get_route_info(rte *e, byte *buf)
2474 | {
2475 |   eattr *p = ea_find(e->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
2476 |   eattr *o = ea_find(e->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGIN));
2477 |   u32 origas;
2478 | 
2479 |   buf += bsprintf(buf, " (%d", e->attrs->pref);
2480 | 
2481 |   if (e->pflags & BGP_REF_SUPPRESSED)
2482 |     buf += bsprintf(buf, "-");
2483 | 
2484 |   if (rte_stale(e))
2485 |     buf += bsprintf(buf, "s");
2486 | 
2487 |   u64 metric = bgp_total_aigp_metric(e);
2488 |   if (metric < BGP_AIGP_MAX)
2489 |   {
2490 |     buf += bsprintf(buf, "/%lu", metric);
2491 |   }
2492 |   else if (e->attrs->igp_metric)
2493 |   {
2494 |     if (!rte_resolvable(e))
2495 |       buf += bsprintf(buf, "/-");
2496 |     else if (e->attrs->igp_metric >= IGP_METRIC_UNKNOWN)
2497 |       buf += bsprintf(buf, "/?");
2498 |     else
2499 |       buf += bsprintf(buf, "/%d", e->attrs->igp_metric);
2500 |   }
2501 |   buf += bsprintf(buf, ") [");
2502 | 
2503 |   if (p && as_path_get_last(p->u.ptr, &origas))
2504 |     buf += bsprintf(buf, "AS%u", origas);
2505 |   if (o)
2506 |     buf += bsprintf(buf, "%c", "ie?"[o->u.data]);
2507 |   strcpy(buf, "]");
2508 | }

