 122 | static inline int
 123 | bgp_put_attr_hdr3(byte *buf, uint code, uint flags, uint len)
 124 | {
 125 |   *buf++ = flags & ~BAF_EXT_LEN;
 126 |   *buf++ = code;
 127 |   *buf++ = len;
 128 |   return 3;
 129 | }
 130 | 
 131 | static inline int
 132 | bgp_put_attr_hdr4(byte *buf, uint code, uint flags, uint len)
 133 | {
 134 |   *buf++ = flags | BAF_EXT_LEN;
 135 |   *buf++ = code;
 136 |   put_u16(buf, len);
 137 |   return 4;
 138 | }
 139 | 
 140 | static inline int
 141 | bgp_put_attr_hdr(byte *buf, uint code, uint flags, uint len)
 142 | {
 143 |   if (len < 256)
 144 |     return bgp_put_attr_hdr3(buf, code, flags, len);
 145 |   else
 146 |     return bgp_put_attr_hdr4(buf, code, flags, len);
 147 | }
 148 | 
 149 | static int
 150 | bgp_encode_u8(struct bgp_write_state *s UNUSED, eattr *a, byte *buf, uint size)
 151 | {
 152 |   if (size < (3+1))
 153 |     return -1;
 154 | 
 155 |   bgp_put_attr_hdr3(buf, EA_ID(a->id), a->flags, 1);
 156 |   buf[3] = a->u.data;
 157 | 
 158 |   return 3+1;
 159 | }
 160 | 
 161 | static int
 162 | bgp_encode_u32(struct bgp_write_state *s UNUSED, eattr *a, byte *buf, uint size)
 163 | {
 164 |   if (size < (3+4))
 165 |     return -1;
 166 | 
 167 |   bgp_put_attr_hdr3(buf, EA_ID(a->id), a->flags, 4);
 168 |   put_u32(buf+3, a->u.data);
 169 | 
 170 |   return 3+4;
 171 | }
 172 | 
 173 | static int
 174 | bgp_encode_u32s(struct bgp_write_state *s UNUSED, eattr *a, byte *buf, uint size)
 175 | {
 176 |   uint len = a->u.ptr->length;
 177 | 
 178 |   if (size < (4+len))
 179 |     return -1;
 180 | 
 181 |   uint hdr = bgp_put_attr_hdr(buf, EA_ID(a->id), a->flags, len);
 182 |   put_u32s(buf + hdr, (u32 *) a->u.ptr->data, len / 4);
 183 | 
 184 |   return hdr + len;
 185 | }
 186 | 
 187 | static int
 188 | bgp_put_attr(byte *buf, uint size, uint code, uint flags, const byte *data, uint len)
 189 | {
 190 |   if (size < (4+len))
 191 |     return -1;
 192 | 
 193 |   uint hdr = bgp_put_attr_hdr(buf, code, flags, len);
 194 |   memcpy(buf + hdr, data, len);
 195 | 
 196 |   return hdr + len;
 197 | }
 198 | 
 199 | static int
 200 | bgp_encode_raw(struct bgp_write_state *s UNUSED, eattr *a, byte *buf, uint size)
 201 | {
 202 |   return bgp_put_attr(buf, size, EA_ID(a->id), a->flags, a->u.ptr->data, a->u.ptr->length);
 203 | }
