 378 | u32
 379 | bgp_rte_igp_metric(struct rte *rt)
 380 | {
 381 |   u64 metric = bgp_total_aigp_metric(rt);
 382 |   return (u32) MIN(metric, (u64) IGP_METRIC_UNKNOWN);
 383 | }
