 511 | static void
 512 | bgp_decode_next_hop(struct bgp_parse_state *s, uint code UNUSED, uint flags UNUSED, byte *data, uint len, ea_list **to UNUSED)
 513 | {
 514 |   if (len != 4)
 515 |     WITHDRAW(BAD_LENGTH, "NEXT_HOP", len);
 516 | 
 517 |   /* Semantic checks are done later */
 518 |   s->ip_next_hop_len = len;
 519 |   s->ip_next_hop_data = data;
 520 | }
