1298 |  *	Attribute decoding
1299 |  */
1300 | 
1301 | static void bgp_process_as4_attrs(ea_list **attrs, struct linpool *pool);
1302 | 
1303 | static inline int
1304 | bgp_as_path_loopy(struct bgp_proto *p, ea_list *attrs, u32 asn)
1305 | {
1306 |   eattr *e = bgp_find_attr(attrs, BA_AS_PATH);
1307 |   int num = p->cf->allow_local_as + 1;
1308 |   return (e && (num > 0) && as_path_contains(e->u.ptr, asn, num));
1309 | }
1310 | 
1311 | static inline int
1312 | bgp_originator_id_loopy(struct bgp_proto *p, ea_list *attrs)
1313 | {
1314 |   eattr *e = bgp_find_attr(attrs, BA_ORIGINATOR_ID);
1315 |   return (e && (e->u.data == p->local_id));
1316 | }
1317 | 
1318 | static inline int
1319 | bgp_cluster_list_loopy(struct bgp_proto *p, ea_list *attrs)
1320 | {
1321 |   eattr *e = bgp_find_attr(attrs, BA_CLUSTER_LIST);
1322 |   return (e && int_set_contains(e->u.ptr, p->rr_cluster_id));
1323 | }
