1519 | /*
1520 |  *	Route bucket hash table
1521 |  */
1522 | 
1523 | #define RBH_KEY(b)		b->eattrs, b->hash
1524 | #define RBH_NEXT(b)		b->next
1525 | #define RBH_EQ(a1,h1,a2,h2)	h1 == h2 && ea_same(a1, a2)
1526 | #define RBH_FN(a,h)		h
1527 | 
1528 | #define RBH_REHASH		bgp_rbh_rehash
1529 | #define RBH_PARAMS		/8, *2, 2, 2, 12, 20
1530 | 
1531 | 
1532 | HASH_DEFINE_REHASH_FN(RBH, struct bgp_bucket)
1533 | 
1534 | void
1535 | bgp_init_bucket_table(struct bgp_channel *c)
1536 | {
1537 |   HASH_INIT(c->bucket_hash, c->pool, 8);
1538 | 
1539 |   init_list(&c->bucket_queue);
1540 |   c->withdraw_bucket = NULL;
1541 | }
1542 | 
1543 | void
1544 | bgp_free_bucket_table(struct bgp_channel *c)
1545 | {
1546 |   HASH_FREE(c->bucket_hash);
1547 | 
1548 |   struct bgp_bucket *b;
1549 |   WALK_LIST_FIRST(b, c->bucket_queue)
1550 |   {
1551 |     rem_node(&b->send_node);
1552 |     mb_free(b);
1553 |   }
1554 | 
1555 |   mb_free(c->withdraw_bucket);
1556 |   c->withdraw_bucket = NULL;
1557 | }
1558 | 
1559 | static struct bgp_bucket *
1560 | bgp_get_bucket(struct bgp_channel *c, ea_list *new)
1561 | {
1562 |   /* Hash and lookup */
1563 |   u32 hash = ea_hash(new);
1564 |   struct bgp_bucket *b = HASH_FIND(c->bucket_hash, RBH, new, hash);
1565 | 
1566 |   if (b)
1567 |     return b;
1568 | 
1569 |   uint ea_size = sizeof(ea_list) + new->count * sizeof(eattr);
1570 |   uint ea_size_aligned = BIRD_ALIGN(ea_size, CPU_STRUCT_ALIGN);
1571 |   uint size = sizeof(struct bgp_bucket) + ea_size_aligned;
1572 |   uint i;
1573 |   byte *dest;
1574 | 
1575 |   /* Gather total size of non-inline attributes */
1576 |   for (i = 0; i < new->count; i++)
1577 |   {
1578 |     eattr *a = &new->attrs[i];
1579 | 
1580 |     if (!(a->type & EAF_EMBEDDED))
1581 |       size += BIRD_ALIGN(sizeof(struct adata) + a->u.ptr->length, CPU_STRUCT_ALIGN);
1582 |   }
1583 | 
1584 |   /* Create the bucket */
1585 |   b = mb_alloc(c->pool, size);
1586 |   *b = (struct bgp_bucket) { };
1587 |   init_list(&b->prefixes);
1588 |   b->hash = hash;
1589 | 
1590 |   /* Copy list of extended attributes */
1591 |   memcpy(b->eattrs, new, ea_size);
1592 |   dest = ((byte *) b->eattrs) + ea_size_aligned;
1593 | 
1594 |   /* Copy values of non-inline attributes */
1595 |   for (i = 0; i < new->count; i++)
1596 |   {
1597 |     eattr *a = &b->eattrs->attrs[i];
1598 | 
1599 |     if (!(a->type & EAF_EMBEDDED))
1600 |     {
1601 |       const struct adata *oa = a->u.ptr;
1602 |       struct adata *na = (struct adata *) dest;
1603 |       memcpy(na, oa, sizeof(struct adata) + oa->length);
1604 |       a->u.ptr = na;
1605 |       dest += BIRD_ALIGN(sizeof(struct adata) + na->length, CPU_STRUCT_ALIGN);
1606 |     }
1607 |   }
1608 | 
1609 |   /* Insert the bucket to send queue and bucket hash */
1610 |   add_tail(&c->bucket_queue, &b->send_node);
1611 |   HASH_INSERT2(c->bucket_hash, RBH, c->pool, b);
1612 | 
1613 |   return b;
1614 | }
1615 | 
1616 | static struct bgp_bucket *
1617 | bgp_get_withdraw_bucket(struct bgp_channel *c)
1618 | {
1619 |   if (!c->withdraw_bucket)
1620 |   {
1621 |     c->withdraw_bucket = mb_allocz(c->pool, sizeof(struct bgp_bucket));
1622 |     init_list(&c->withdraw_bucket->prefixes);
1623 |   }
1624 | 
1625 |   return c->withdraw_bucket;
1626 | }
1627 | 
1628 | void
1629 | bgp_free_bucket(struct bgp_channel *c, struct bgp_bucket *b)
1630 | {
1631 |   rem_node(&b->send_node);
1632 |   HASH_REMOVE2(c->bucket_hash, RBH, c->pool, b);
1633 |   mb_free(b);
1634 | }
1635 | 
1636 | void
1637 | bgp_defer_bucket(struct bgp_channel *c, struct bgp_bucket *b)
1638 | {
1639 |   rem_node(&b->send_node);
1640 |   add_tail(&c->bucket_queue, &b->send_node);
1641 | }
1642 | 
1643 | void
1644 | bgp_withdraw_bucket(struct bgp_channel *c, struct bgp_bucket *b)
1645 | {
1646 |   struct bgp_proto *p = (void *) c->c.proto;
1647 |   struct bgp_bucket *wb = bgp_get_withdraw_bucket(c);
1648 | 
1649 |   log(L_ERR "%s: Attribute list too long", p->p.name);
1650 |   while (!EMPTY_LIST(b->prefixes))
1651 |   {
1652 |     struct bgp_prefix *px = HEAD(b->prefixes);
1653 | 
1654 |     log(L_ERR "%s: - withdrawing %N", p->p.name, &px->net);
1655 |     rem_node(&px->buck_node);
1656 |     add_tail(&wb->prefixes, &px->buck_node);
1657 |   }
1658 | }
