1662 |  *	Prefix hash table
1663 |  */
1664 | 
1665 | #define PXH_KEY(px)		px->net, px->path_id, px->hash
1666 | #define PXH_NEXT(px)		px->next
1667 | #define PXH_EQ(n1,i1,h1,n2,i2,h2) h1 == h2 && i1 == i2 && net_equal(n1, n2)
1668 | #define PXH_FN(n,i,h)		h
1669 | 
1670 | #define PXH_REHASH		bgp_pxh_rehash
1671 | #define PXH_PARAMS		/8, *2, 2, 2, 12, 24
