1676 | void
1677 | bgp_init_prefix_table(struct bgp_channel *c)
1678 | {
1679 |   HASH_INIT(c->prefix_hash, c->pool, 8);
1680 | 
1681 |   uint alen = net_addr_length[c->c.net_type];
1682 |   c->prefix_slab = alen ? sl_new(c->pool, sizeof(struct bgp_prefix) + alen) : NULL;
1683 | }
