1694 | static struct bgp_prefix *
1695 | bgp_get_prefix(struct bgp_channel *c, net_addr *net, u32 path_id)
1696 | {
1697 |   /* We must use a different hash function than the rtable */
1698 |   u32 hash = u32_hash(net_hash(net) ^ u32_hash(path_id));
1699 |   struct bgp_prefix *px = HASH_FIND(c->prefix_hash, PXH, net, path_id, hash);
1700 | 
1701 |   if (px)
1702 |   {
1703 |     rem_node(&px->buck_node);
1704 |     return px;
1705 |   }
1706 | 
1707 |   if (c->prefix_slab)
1708 |     px = sl_alloc(c->prefix_slab);
1709 |   else
1710 |     px = mb_alloc(c->pool, sizeof(struct bgp_prefix) + net->length);
1711 | 
1712 |   *px = (struct bgp_prefix) { };
1713 |   px->hash = hash;
1714 |   px->path_id = path_id;
1715 |   net_copy(px->net, net);
1716 | 
1717 |   HASH_INSERT2(c->prefix_hash, PXH, c->pool, px);
1718 | 
1719 |   return px;
1720 | }
1721 | 
1722 | void
1723 | bgp_free_prefix(struct bgp_channel *c, struct bgp_prefix *px)
1724 | {
1725 |   rem_node(&px->buck_node);
1726 |   HASH_REMOVE2(c->prefix_hash, PXH, c->pool, px);
1727 | 
1728 |   if (c->prefix_slab)
1729 |     sl_free(px);
1730 |   else
1731 |     mb_free(px);
1732 | }
