1991 | static inline int
1992 | rte_stale(rte *r)
1993 | {
1994 |   if (r->pflags & BGP_REF_STALE)
1995 |     return 1;
1996 | 
1997 |   if (r->pflags & BGP_REF_NOT_STALE)
1998 |     return 0;
1999 | 
2000 |   /* If staleness is unknown, compute and cache it */
2001 |   eattr *a = ea_find(r->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_COMMUNITY));
2002 |   if (a && int_set_contains(a->u.ptr, BGP_COMM_LLGR_STALE))
2003 |   {
2004 |     r->pflags |= BGP_REF_STALE;
2005 |     return 1;
2006 |   }
2007 |   else
2008 |   {
2009 |     r->pflags |= BGP_REF_NOT_STALE;
2010 |     return 0;
2011 |   }
2012 | }
