2014 | int
2015 | bgp_rte_better(rte *new, rte *old)
2016 | {
2017 |   struct bgp_proto *new_bgp = (struct bgp_proto *) new->src->proto;
2018 |   struct bgp_proto *old_bgp = (struct bgp_proto *) old->src->proto;
2019 |   eattr *x, *y;
2020 |   u32 n, o;
2021 | 
2022 |   /* Skip suppressed routes (see bgp_rte_recalculate()) */
2023 |   n = new->pflags & BGP_REF_SUPPRESSED;
2024 |   o = old->pflags & BGP_REF_SUPPRESSED;
2025 |   if (n > o)
2026 |     return 0;
2027 |   if (n < o)
2028 |     return 1;
2029 | 
2030 |   /* RFC 4271 9.1.2.1. Route resolvability test */
2031 |   n = rte_resolvable(new);
2032 |   o = rte_resolvable(old);
2033 |   if (n > o)
2034 |     return 1;
2035 |   if (n < o)
2036 |     return 0;
2037 | 
2038 |   /* LLGR 9494 - depreference stale routes */
2039 |   n = rte_stale(new);
2040 |   o = rte_stale(old);
2041 |   if (n > o)
2042 |     return 0;
2043 |   if (n < o)
2044 |     return 1;
2045 | 
2046 |  /* Start with local preferences */
2047 |   x = ea_find(new->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_LOCAL_PREF));
2048 |   y = ea_find(old->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_LOCAL_PREF));
2049 |   n = x ? x->u.data : new_bgp->cf->default_local_pref;
2050 |   o = y ? y->u.data : old_bgp->cf->default_local_pref;
2051 |   if (n > o)
2052 |     return 1;
2053 |   if (n < o)
2054 |     return 0;
2055 | 
2056 |   /* RFC 7311 4.1 - Apply AIGP metric */
2057 |   u64 n2 = bgp_total_aigp_metric(new);
2058 |   u64 o2 = bgp_total_aigp_metric(old);
2059 |   if (n2 < o2)
2060 |     return 1;
2061 |   if (n2 > o2)
2062 |     return 0;
2063 | 
2064 |   /* RFC 4271 9.1.2.2. a)  Use AS path lengths */
2065 |   if (new_bgp->cf->compare_path_lengths || old_bgp->cf->compare_path_lengths)
2066 |   {
2067 |     x = ea_find(new->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
2068 |     y = ea_find(old->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
2069 |     n = x ? as_path_getlen(x->u.ptr) : AS_PATH_MAXLEN;
2070 |     o = y ? as_path_getlen(y->u.ptr) : AS_PATH_MAXLEN;
2071 |     if (n < o)
2072 |       return 1;
2073 |     if (n > o)
2074 |       return 0;
2075 |   }
2076 | 
2077 |   /* RFC 4271 9.1.2.2. b) Use origins */
2078 |   x = ea_find(new->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGIN));
2079 |   y = ea_find(old->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGIN));
2080 |   n = x ? x->u.data : ORIGIN_INCOMPLETE;
2081 |   o = y ? y->u.data : ORIGIN_INCOMPLETE;
2082 |   if (n < o)
2083 |     return 1;
2084 |   if (n > o)
2085 |     return 0;
2086 | 
2087 |   /* RFC 4271 9.1.2.2. c) Compare MED's */
2088 |   /* Proper RFC 4271 path selection cannot be interpreted as finding
2089 |    * the best path in some ordering. It is implemented partially in
2090 |    * bgp_rte_recalculate() when deterministic_med option is
2091 |    * active. Without that option, the behavior is just an
2092 |    * approximation, which in specific situations may lead to
2093 |    * persistent routing loops, because it is nondeterministic - it
2094 |    * depends on the order in which routes appeared. But it is also the
2095 |    * same behavior as used by default in Cisco routers, so it is
2096 |    * probably not a big issue.
2097 |    */
2098 |   if (new_bgp->cf->med_metric || old_bgp->cf->med_metric ||
2099 |       (bgp_get_neighbor(new) == bgp_get_neighbor(old)))
2100 |   {
2101 |     x = ea_find(new->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_MULTI_EXIT_DISC));
2102 |     y = ea_find(old->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_MULTI_EXIT_DISC));
2103 |     n = x ? x->u.data : new_bgp->cf->default_med;
2104 |     o = y ? y->u.data : old_bgp->cf->default_med;
2105 |     if (n < o)
2106 |       return 1;
2107 |     if (n > o)
2108 |       return 0;
2109 |   }
2110 | 
2111 |   /* RFC 4271 9.1.2.2. d) Prefer external peers */
2112 |   if (new_bgp->is_interior > old_bgp->is_interior)
2113 |     return 0;
2114 |   if (new_bgp->is_interior < old_bgp->is_interior)
2115 |     return 1;
2116 | 
2117 |   /* RFC 4271 9.1.2.2. e) Compare IGP metrics */
2118 |   n = new_bgp->cf->igp_metric ? new->attrs->igp_metric : 0;
2119 |   o = old_bgp->cf->igp_metric ? old->attrs->igp_metric : 0;
2120 |   if (n < o)
2121 |     return 1;
2122 |   if (n > o)
2123 |     return 0;
2124 | 
2125 |   /* RFC 4271 9.1.2.2. f) Compare BGP identifiers */
2126 |   /* RFC 4456 9. a) Use ORIGINATOR_ID instead of local neighbor ID */
2127 |   x = ea_find(new->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGINATOR_ID));
2128 |   y = ea_find(old->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGINATOR_ID));
2129 |   n = x ? x->u.data : new_bgp->remote_id;
2130 |   o = y ? y->u.data : old_bgp->remote_id;
2131 | 
2132 |   /* RFC 5004 - prefer older routes */
2133 |   /* (if both are external and from different peer) */
2134 |   if ((new_bgp->cf->prefer_older || old_bgp->cf->prefer_older) &&
2135 |       !new_bgp->is_internal && n != o)
2136 |     return 0;
2137 | 
2138 |   /* rest of RFC 4271 9.1.2.2. f) */
2139 |   if (n < o)
2140 |     return 1;
2141 |   if (n > o)
2142 |     return 0;
2143 | 
2144 |   /* RFC 4456 9. b) Compare cluster list lengths */
2145 |   x = ea_find(new->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_CLUSTER_LIST));
2146 |   y = ea_find(old->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_CLUSTER_LIST));
2147 |   n = x ? int_set_get_size(x->u.ptr) : 0;
2148 |   o = y ? int_set_get_size(y->u.ptr) : 0;
2149 |   if (n < o)
2150 |     return 1;
2151 |   if (n > o)
2152 |     return 0;
2153 | 
2154 |   /* RFC 4271 9.1.2.2. g) Compare peer IP adresses */
2155 |   return ipa_compare(new_bgp->remote_ip, old_bgp->remote_ip) < 0;
2156 | }
