2159 | int
2160 | bgp_rte_mergable(rte *pri, rte *sec)
2161 | {
2162 |   struct bgp_proto *pri_bgp = (struct bgp_proto *) pri->src->proto;
2163 |   struct bgp_proto *sec_bgp = (struct bgp_proto *) sec->src->proto;
2164 |   eattr *x, *y;
