2179 |   /* Start with local preferences */
2180 |   x = ea_find(pri->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_LOCAL_PREF));
2181 |   y = ea_find(sec->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_LOCAL_PREF));
2182 |   p = x ? x->u.data : pri_bgp->cf->default_local_pref;
2183 |   s = y ? y->u.data : sec_bgp->cf->default_local_pref;
2184 |   if (p != s)
2185 |     return 0;
2186 | 
2187 |   /* RFC 4271 9.1.2.2. a)  Use AS path lengths */
2188 |   if (pri_bgp->cf->compare_path_lengths || sec_bgp->cf->compare_path_lengths)
2189 |   {
2190 |     x = ea_find(pri->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
2191 |     y = ea_find(sec->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_AS_PATH));
2192 |     p = x ? as_path_getlen(x->u.ptr) : AS_PATH_MAXLEN;
2193 |     s = y ? as_path_getlen(y->u.ptr) : AS_PATH_MAXLEN;
2194 | 
2195 |     if (p != s)
2196 |       return 0;
2197 | 
2198 | //    if (DELTA(p, s) > pri_bgp->cf->relax_multipath)
2199 | //      return 0;
2200 |   }
2201 | 
2202 |   /* RFC 4271 9.1.2.2. b) Use origins */
2203 |   x = ea_find(pri->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGIN));
2204 |   y = ea_find(sec->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_ORIGIN));
2205 |   p = x ? x->u.data : ORIGIN_INCOMPLETE;
2206 |   s = y ? y->u.data : ORIGIN_INCOMPLETE;
2207 |   if (p != s)
2208 |     return 0;
2209 | 
2210 |   /* RFC 4271 9.1.2.2. c) Compare MED's */
