2250 | 
2251 | int
2252 | bgp_rte_recalculate(rtable *table, net *net, rte *new, rte *old, rte *old_best)
2253 | {
2254 |   rte *r, *s;
2255 |   rte *key = new ? new : old;
2256 |   u32 lpref = key->attrs->pref;
2257 |   u32 lasn = bgp_get_neighbor(key);
2258 |   int old_suppressed = old ? !!(old->pflags & BGP_REF_SUPPRESSED) : 0;
2259 | 
2260 |   /*
2261 |    * Proper RFC 4271 path selection is a bit complicated, it cannot be
2262 |    * implemented just by rte_better(), because it is not a linear
2263 |    * ordering. But it can be splitted to two levels, where the lower
2264 |    * level chooses the best routes in each group of routes from the
2265 |    * same neighboring AS and higher level chooses the best route (with
2266 |    * a slightly different ordering) between the best-in-group routes.
2267 |    *
2268 |    * When deterministic_med is disabled, we just ignore this issue and
2269 |    * choose the best route by bgp_rte_better() alone. If enabled, the
2270 |    * lower level of the route selection is done here (for the group
2271 |    * to which the changed route belongs), all routes in group are
2272 |    * marked as suppressed, just chosen best-in-group is not.
2273 |    *
2274 |    * Global best route selection then implements higher level by
2275 |    * choosing between non-suppressed routes (as they are always
2276 |    * preferred over suppressed routes). Routes from BGP protocols
2277 |    * that do not set deterministic_med are just never suppressed. As
2278 |    * they do not participate in the lower level selection, it is OK
2279 |    * that this fn is not called for them.
2280 |    *
2281 |    * The idea is simple, the implementation is more problematic,
2282 |    * mostly because of optimizations in rte_recalculate() that
2283 |    * avoids full recalculation in most cases.
2284 |    *
2285 |    * We can assume that at least one of new, old is non-NULL and both
2286 |    * are from the same protocol with enabled deterministic_med. We
2287 |    * group routes by both neighbor AS (lasn) and preference (lpref),
2288 |    * because bgp_rte_better() does not handle preference itself.
2289 |    */
2290 | 
2291 |   /* If new and old are from different groups, we just process that
2292 |      as two independent events */
2293 |   if (new && old && !same_group(old, lpref, lasn))
2294 |   {
2295 |     int i1, i2;
2296 |     i1 = bgp_rte_recalculate(table, net, NULL, old, old_best);
2297 |     i2 = bgp_rte_recalculate(table, net, new, NULL, old_best);
2298 |     return i1 || i2;
2299 |   }
2300 | 
2301 |   /*
2302 |    * We could find the best-in-group and then make some shortcuts like
2303 |    * in rte_recalculate, but as we would have to walk through all
2304 |    * net->routes just to find it, it is probably not worth. So we
2305 |    * just have one simple fast case that use just the old route.
2306 |    * We also set suppressed flag to avoid using it in bgp_rte_better().
2307 |    */
2308 | 
2309 |   if (new)
2310 |     new->pflags |= BGP_REF_SUPPRESSED;
2311 | 
2312 |   if (old)
2313 |   {
2314 |     old->pflags |= BGP_REF_SUPPRESSED;
2315 | 
2316 |     /* The fast case - replace not best with worse (or remove not best) */
2317 |     if (old_suppressed && !(new && bgp_rte_better(new, old)))
2318 |       return 0;
2319 |   }
2320 | 
2321 |   /* The default case - find a new best-in-group route */
2322 |   r = new; /* new may not be in the list */
2323 |   for (s=net->routes; rte_is_valid(s); s=s->next)
2324 |     if (use_deterministic_med(s) && same_group(s, lpref, lasn))
2325 |     {
2326 |       s->pflags |= BGP_REF_SUPPRESSED;
2327 |       if (!r || bgp_rte_better(s, r))
2328 | 	r = s;
2329 |     }
2330 | 
2331 |   /* Simple case - the last route in group disappears */
2332 |   if (!r)
2333 |     return 0;
2334 | 
2335 |   /* Found if new is mergable with best-in-group */
2336 |   if (new && (new != r) && bgp_rte_mergable(r, new))
2337 |     new->pflags &= ~BGP_REF_SUPPRESSED;
2338 | 
2339 |   /* Found all existing routes mergable with best-in-group */
2340 |   for (s=net->routes; rte_is_valid(s); s=s->next)
2341 |     if (use_deterministic_med(s) && same_group(s, lpref, lasn))
2342 |       if ((s != r) && bgp_rte_mergable(r, s))
2343 | 	s->pflags &= ~BGP_REF_SUPPRESSED;
2344 | 
2345 |   /* Found best-in-group */
2346 |   r->pflags &= ~BGP_REF_SUPPRESSED;
2347 | 
2348 |   /*
2349 |    * There are generally two reasons why we have to force
2350 |    * recalculation (return 1): First, the new route may be wrongfully
2351 |    * chosen to be the best in the first case check in
2352 |    * rte_recalculate(), this may happen only if old_best is from the
2353 |    * same group. Second, another (different than new route)
2354 |    * best-in-group is chosen and that may be the proper best (although
2355 |    * rte_recalculate() without ignore that possibility).
2356 |    *
2357 |    * There are three possible cases according to whether the old route
2358 |    * was the best in group (OBG, i.e. !old_suppressed) and whether the
2359 |    * new route is the best in group (NBG, tested by r == new). These
2360 |    * cases work even if old or new is NULL.
2361 |    *
2362 |    * NBG -> new is a possible candidate for the best route, so we just
2363 |    *        check for the first reason using same_group().
2364 |    *
2365 |    * !NBG && OBG -> Second reason applies, return 1
2366 |    *
2367 |    * !NBG && !OBG -> Best in group does not change, old != old_best,
2368 |    *                 rte_better(new, old_best) is false and therefore
2369 |    *                 the first reason does not apply, return 0
2370 |    */
2371 | 
2372 |   if (r == new)
2373 |     return old_best && same_group(old_best, lpref, lasn);
2374 |   else
2375 |     return !old_suppressed;
2376 | }
