2400 | /*
2401 |  * Reconstruct AS_PATH and AGGREGATOR according to RFC 6793 4.2.3
2402 |  */
2403 | static void
2404 | bgp_process_as4_attrs(ea_list **attrs, struct linpool *pool)
2405 | {
2406 |   eattr *p2 = bgp_find_attr(*attrs, BA_AS_PATH);
2407 |   eattr *p4 = bgp_find_attr(*attrs, BA_AS4_PATH);
2408 |   eattr *a2 = bgp_find_attr(*attrs, BA_AGGREGATOR);
2409 |   eattr *a4 = bgp_find_attr(*attrs, BA_AS4_AGGREGATOR);
2410 | 
2411 |   /* First, unset AS4_* attributes */
2412 |   if (p4) bgp_unset_attr(attrs, pool, BA_AS4_PATH);
2413 |   if (a4) bgp_unset_attr(attrs, pool, BA_AS4_AGGREGATOR);
2414 | 
2415 |   /* Handle AGGREGATOR attribute */
2416 |   if (a2 && a4)
2417 |   {
2418 |     u32 a2_asn = get_u32(a2->u.ptr->data);
2419 | 
2420 |     /* If routes were aggregated by an old router, then AS4_PATH and
2421 |        AS4_AGGREGATOR are invalid. In that case we give up. */
2422 |     if (a2_asn != AS_TRANS)
2423 |       return;
2424 | 
2425 |     /* Use AS4_AGGREGATOR instead of AGGREGATOR */
2426 |     a2->u.ptr = a4->u.ptr;
2427 |   }
2428 | 
2429 |   /* Handle AS_PATH attribute */
2430 |   if (p2 && p4)
2431 |   {
2432 |     /* Both as_path_getlen() and as_path_cut() take AS_CONFED* as zero length */
2433 |     int p2_len = as_path_getlen(p2->u.ptr);
2434 |     int p4_len = as_path_getlen(p4->u.ptr);
2435 | 
2436 |     /* AS_PATH is too short, give up */
2437 |     if (p2_len < p4_len)
2438 |       return;
2439 | 
2440 |     /* Merge AS_PATH and AS4_PATH */
2441 |     struct adata *apc = as_path_cut(pool, p2->u.ptr, p2_len - p4_len);
2442 |     p2->u.ptr = as_path_merge(pool, apc, p4->u.ptr);
2443 |   }
2444 | }
