  83 | eattr *
  84 | bgp_set_attr(ea_list **attrs, struct linpool *pool, uint code, uint flags, uintptr_t val)
  85 | {
  86 |   ASSERT(bgp_attr_known(code));
  87 | 
  88 |   return ea_set_attr(
  89 |       attrs,
  90 |       pool,
  91 |       EA_CODE(PROTOCOL_BGP, code),
  92 |       bgp_attr_table[code].flags | (flags & BAF_PARTIAL),
  93 |       bgp_attr_table[code].type,
  94 |       val
  95 |   );
  96 | }
