 250 | static const byte *
 251 | bgp_aigp_get_tlv(const struct adata *ad, uint type)
 252 | {
 253 |   if (!ad)
 254 |     return NULL;
 255 | 
 256 |   uint len = ad->length;
 257 |   const byte *pos = ad->data;
 258 | 
 259 |   while (len)
 260 |   {
 261 |     uint ptype = pos[0];
 262 |     uint plen = get_u16(pos + 1);
 263 | 
 264 |     if (ptype == type)
 265 |       return pos;
 266 | 
 267 |     ADVANCE(pos, len, plen);
 268 |   }
 269 | 
 270 |   return NULL;
 271 | }
