 368 | bgp_init_aigp_metric(rte *e, u64 *metric, const struct adata **ad)
 369 | {
 370 |   if (e->attrs->source == RTS_BGP)
 371 |     return 0;
 372 | 
 373 |   *metric = rt_get_igp_metric(e);
 374 |   *ad = NULL;
 375 |   return *metric < IGP_METRIC_UNKNOWN;
