 875 | static void
 876 | bgp_format_aigp(const eattr *a, byte *buf, uint size UNUSED)
 877 | {
 878 |   const byte *b = bgp_aigp_get_tlv(a->u.ptr, BGP_AIGP_METRIC);
 879 | 
 880 |   if (!b)
 881 |     bsprintf(buf, "?");
 882 |   else
 883 |     bsprintf(buf, "%lu", get_u64(b + 3));
