 951 |    * MPLS labels are encoded as a part of the NLRI in MP_REACH_NLRI attribute,
 952 |    * so we store MPLS_LABEL_STACK and encode it later by AFI-specific hooks.
 953 |    */
 954 | 
 955 |   s->mpls_labels = a->u.ptr;
 956 |   return 0;
 957 | }
