1325 | static inline void
1326 | bgp_decode_attr(struct bgp_parse_state *s, uint code, uint flags, byte *data, uint len, ea_list **to)
1327 | {
1328 |   /* Handle duplicate attributes; RFC 7606 3 (g) */
1329 |   if (BIT32_TEST(s->attrs_seen, code))
1330 |   {
1331 |     if ((code == BA_MP_REACH_NLRI) || (code == BA_MP_UNREACH_NLRI))
1332 |       bgp_parse_error(s, 1);
1333 |     else
1334 |       DISCARD("Discarding duplicate attribute (code %u)", code);
1335 |   }
1336 |   BIT32_SET(s->attrs_seen, code);
1337 | 
1338 |   if (bgp_attr_known(code))
1339 |   {
1340 |     const struct bgp_attr_desc *desc = &bgp_attr_table[code];
1341 | 
1342 |     /* Handle conflicting flags; RFC 7606 3 (c) */
1343 |     if (((flags ^ desc->flags) & (BAF_OPTIONAL | BAF_TRANSITIVE)) &&
1344 | 	!(desc->flags & BAF_DECODE_FLAGS))
1345 |       WITHDRAW("Malformed %s attribute - conflicting flags (%02x)", desc->name, flags);
1346 | 
1347 |     desc->decode(s, code, flags, data, len, to);
1348 |   }
1349 |   else /* Unknown attribute */
1350 |   {
1351 |     if (!(flags & BAF_OPTIONAL))
1352 |       WITHDRAW("Unknown attribute (code %u) - conflicting flags (%02x)", code, flags);
1353 | 
1354 |     bgp_decode_unknown(s, code, flags, data, len, to);
1355 |   }
1356 | }
1357 | 
1358 | /**
1359 |  * bgp_decode_attrs - check and decode BGP attributes
1360 |  * @s: BGP parse state
1361 |  * @data: start of attribute block
1362 |  * @len: length of attribute block
1363 |  *
1364 |  * This function takes a BGP attribute block (a part of an Update message), checks
1365 |  * its consistency and converts it to a list of BIRD route attributes represented
1366 |  * by an (uncached) &rta.
1367 |  */
1368 | ea_list *
1369 | bgp_decode_attrs(struct bgp_parse_state *s, byte *data, uint len)
1370 | {
1371 |   struct bgp_proto *p = s->proto;
1372 |   ea_list *attrs = NULL;
1373 |   uint code, flags, alen;
1374 |   byte *pos = data;
1375 | 
1376 |   /* Parse the attributes */
1377 |   while (len)
1378 |   {
1379 |     alen = 0;
1380 | 
1381 |     /* Read attribute type */
1382 |     if (len < 2)
1383 |       goto framing_error;
1384 |     flags = pos[0];
1385 |     code = pos[1];
1386 |     ADVANCE(pos, len, 2);
1387 | 
1388 |     /* Read attribute length */
1389 |     if (flags & BAF_EXT_LEN)
1390 |     {
1391 |       if (len < 2)
1392 | 	goto framing_error;
1393 |       alen = get_u16(pos);
1394 |       ADVANCE(pos, len, 2);
1395 |     }
1396 |     else
1397 |     {
1398 |       if (len < 1)
1399 | 	goto framing_error;
1400 |       alen = *pos;
1401 |       ADVANCE(pos, len, 1);
1402 |     }
1403 | 
1404 |     if (alen > len)
1405 |       goto framing_error;
1406 | 
1407 |     DBG("Attr %02x %02x %u\n", code, flags, alen);
1408 | 
1409 |     bgp_decode_attr(s, code, flags, pos, alen, &attrs);
1410 |     ADVANCE(pos, len, alen);
1411 |   }
1412 | 
1413 |   if (s->err_withdraw)
1414 |     goto withdraw;
1415 | 
1416 |   /* If there is no reachability NLRI, we are finished */
1417 |   if (!s->ip_reach_len && !s->mp_reach_len)
1418 |     return NULL;
1419 | 
1420 | 
1421 |   /* Handle missing mandatory attributes; RFC 7606 3 (d) */
1422 |   if (!BIT32_TEST(s->attrs_seen, BA_ORIGIN))
1423 |   { REPORT(NO_MANDATORY, "ORIGIN"); goto withdraw; }
1424 | 
1425 |   if (!BIT32_TEST(s->attrs_seen, BA_AS_PATH))
1426 |   { REPORT(NO_MANDATORY, "AS_PATH"); goto withdraw; }
1427 | 
1428 |   if (s->ip_reach_len && !BIT32_TEST(s->attrs_seen, BA_NEXT_HOP))
1429 |   { REPORT(NO_MANDATORY, "NEXT_HOP"); goto withdraw; }
1430 | 
1431 |   /* When receiving attributes from non-AS4-aware BGP speaker, we have to
1432 |      reconstruct AS_PATH and AGGREGATOR attributes; RFC 6793 4.2.3 */
1433 |   if (!p->as4_session)
1434 |     bgp_process_as4_attrs(&attrs, s->pool);
1435 | 
1436 |   /* Reject routes with our ASN in AS_PATH attribute */
1437 |   if (bgp_as_path_loopy(p, attrs, p->local_as))
1438 |     goto loop;
1439 | 
1440 |   /* Reject routes with our Confederation ID in AS_PATH attribute; RFC 5065 4.0 */
1441 |   if ((p->public_as != p->local_as) && bgp_as_path_loopy(p, attrs, p->public_as))
1442 |     goto loop;
1443 | 
1444 |   /* Reject routes with our Router ID in ORIGINATOR_ID attribute; RFC 4456 8 */
1445 |   if (p->is_internal && bgp_originator_id_loopy(p, attrs))
1446 |     goto loop;
1447 | 
1448 |   /* Reject routes with our Cluster ID in CLUSTER_LIST attribute; RFC 4456 8 */
1449 |   if (p->rr_client && bgp_cluster_list_loopy(p, attrs))
1450 |     goto loop;
1451 | 
1452 |   /* If there is no local preference, define one */
1453 |   if (!BIT32_TEST(s->attrs_seen, BA_LOCAL_PREF))
1454 |     bgp_set_attr_u32(&attrs, s->pool, BA_LOCAL_PREF, 0, p->cf->default_local_pref);
1455 | 
1456 |   return attrs;
1457 | 
1458 | 
1459 | framing_error:
1460 |   /* RFC 7606 4 - handle attribute framing errors */
1461 |   REPORT("Malformed attribute list - framing error (%u/%u) at %d",
1462 | 	 alen, len, (int) (pos - s->attrs));
1463 | 
1464 | withdraw:
1465 |   /* RFC 7606 5.2 - handle missing NLRI during errors */
1466 |   if (!s->ip_reach_len && !s->mp_reach_len)
1467 |     bgp_parse_error(s, 1);
1468 | 
1469 |   s->err_withdraw = 1;
1470 |   return NULL;
1471 | 
1472 | loop:
1473 |   /* Loops are handled as withdraws, but ignored silently. Do not set err_withdraw. */
1474 |   return NULL;
1475 | }
1476 | 
1477 | void
1478 | bgp_finish_attrs(struct bgp_parse_state *s, rta *a)
1479 | {
1480 |   /* AIGP test here instead of in bgp_decode_aigp() - we need to know channel */
1481 |   if (BIT32_TEST(s->attrs_seen, BA_AIGP) && !s->channel->cf->aigp)
1482 |   {
1483 |     REPORT("Discarding AIGP attribute received on non-AIGP session");
1484 |     bgp_unset_attr(&a->eattrs, s->pool, BA_AIGP);
1485 |   }
1486 | 
1487 |   /* Handle OTC ingress procedure, RFC 9234 */
1488 |   if (bgp_channel_is_role_applicable(s->channel))
1489 |   {
1490 |     struct bgp_proto *p = s->proto;
1491 |     eattr *e = bgp_find_attr(a->eattrs, BA_ONLY_TO_CUSTOMER);
1492 | 
1493 |     /* Reject routes from downstream if they are leaked */
1494 |     if (e && (p->cf->local_role == BGP_ROLE_PROVIDER ||
1495 | 	      p->cf->local_role == BGP_ROLE_RS_SERVER))
1496 |       WITHDRAW("Route leak detected - OTC attribute from downstream");
1497 | 
1498 |     /* Reject routes from peers if they are leaked */
1499 |     if (e && (p->cf->local_role == BGP_ROLE_PEER) && (e->u.data != p->cf->remote_as))
1500 |       WITHDRAW("Route leak detected - OTC attribute with mismatched ASN (%u)",
1501 | 	       (uint) e->u.data);
1502 | 
1503 |     /* Mark routes from upstream if it did not happened before */
1504 |     if (!e && (p->cf->local_role == BGP_ROLE_CUSTOMER ||
1505 | 	       p->cf->local_role == BGP_ROLE_PEER ||
1506 | 	       p->cf->local_role == BGP_ROLE_RS_CLIENT))
1507 |       bgp_set_attr_u32(&a->eattrs, s->pool, BA_ONLY_TO_CUSTOMER, 0, p->cf->remote_as);
1508 |   }
1509 | 
1510 |   /* Apply MPLS policy for labeled SAFIs */
1511 |   if (s->mpls && s->proto->p.mpls_channel)
1512 |   {
1513 |     struct mpls_channel *mc = (void *) s->proto->p.mpls_channel;
1514 |     ea_set_attr_u32(&a->eattrs, s->pool, EA_MPLS_POLICY, 0, EAF_TYPE_INT, mc->label_policy);
1515 |   }
1516 | }
