1661 | /*
1662 |  *	Prefix hash table
1663 |  */
1664 | 
1665 | #define PXH_KEY(px)		px->net, px->path_id, px->hash
1666 | #define PXH_NEXT(px)		px->next
1667 | #define PXH_EQ(n1,i1,h1,n2,i2,h2) h1 == h2 && i1 == i2 && net_equal(n1, n2)
1668 | #define PXH_FN(n,i,h)		h
1669 | 
1670 | #define PXH_REHASH		bgp_pxh_rehash
1671 | #define PXH_PARAMS		/8, *2, 2, 2, 12, 24
1672 | 
1673 | 
1674 | HASH_DEFINE_REHASH_FN(PXH, struct bgp_prefix)
1675 | 
1676 | void
1677 | bgp_init_prefix_table(struct bgp_channel *c)
1678 | {
1679 |   HASH_INIT(c->prefix_hash, c->pool, 8);
1680 | 
1681 |   uint alen = net_addr_length[c->c.net_type];
1682 |   c->prefix_slab = alen ? sl_new(c->pool, sizeof(struct bgp_prefix) + alen) : NULL;
1683 | }
1684 | 
1685 | void
1686 | bgp_free_prefix_table(struct bgp_channel *c)
1687 | {
1688 |   HASH_FREE(c->prefix_hash);
1689 | 
1690 |   rfree(c->prefix_slab);
1691 |   c->prefix_slab = NULL;
