2238 | static inline int
2239 | same_group(rte *r, u32 lpref, u32 lasn)
2240 | {
2241 |   return (r->attrs->pref == lpref) && (bgp_get_neighbor(r) == lasn);
2242 | }
2243 | 
2244 | static inline int
2245 | use_deterministic_med(rte *r)
2246 | {
