2378 | struct rte *
2379 | bgp_rte_modify_stale(struct rte *r, struct linpool *pool)
2380 | {
2381 |   eattr *a = ea_find(r->attrs->eattrs, EA_CODE(PROTOCOL_BGP, BA_COMMUNITY));
2382 |   const struct adata *ad = a ? a->u.ptr : NULL;
2383 |   uint flags = a ? a->flags : BAF_PARTIAL;
2384 | 
2385 |   if (ad && int_set_contains(ad, BGP_COMM_NO_LLGR))
2386 |     return NULL;
2387 | 
2388 |   if (ad && int_set_contains(ad, BGP_COMM_LLGR_STALE))
2389 |     return r;
2390 | 
2391 |   r = rte_cow_rta(r, pool);
2392 |   bgp_set_attr_ptr(&(r->attrs->eattrs), pool, BA_COMMUNITY, flags,
2393 | 		   int_set_add(pool, ad, BGP_COMM_LLGR_STALE));
2394 |   r->pflags |= BGP_REF_STALE;
2395 | 
2396 |   return r;
2397 | }
