 753 | static void
 754 | bgp_initiate(struct bgp_proto *p)
 755 | {
 756 |   int err_val;
 757 | 
 758 |   if (bgp_open(p) < 0)
 759 |   { err_val = BEM_NO_SOCKET; goto err1; }
 760 | 
 761 |   if (bgp_setup_auth(p, 1) < 0)
 762 |   { err_val = BEM_INVALID_AUTH; goto err2; }
 763 | 
 764 |   if (p->cf->bfd)
 765 |     bgp_update_bfd(p, p->cf->bfd);
 766 | 
 767 |   if (p->startup_delay)
 768 |   {
 769 |     p->start_state = BSS_DELAY;
 770 |     BGP_TRACE(D_EVENTS, "Startup delayed by %d seconds due to errors", p->startup_delay);
 771 |     bgp_start_timer(p->startup_timer, p->startup_delay);
 772 |   }
 773 |   else
 774 |     bgp_startup(p);
 775 | 
 776 |   return;
 777 | 
 778 | err2:
 779 |   bgp_close(p);
 780 | err1:
 781 |   p->p.disabled = 1;
 782 |   bgp_store_error(p, NULL, BE_MISC, err_val);
 783 | 
 784 |   p->neigh = NULL;
 785 |   proto_notify_state(&p->p, PS_DOWN);
 786 | 
 787 |   return;
 788 | }
