1355 | /**
1356 |  * bgp_refresh_begin - start incoming enhanced route refresh sequence
1357 |  * @c: BGP channel
1358 |  *
1359 |  * This function is called when an incoming enhanced route refresh sequence is
1360 |  * started by the neighbor, demarcated by the BoRR packet. The function updates
1361 |  * the load state and starts the routing table refresh cycle. Note that graceful
1362 |  * restart also uses routing table refresh cycle, but RFC 7313 and load states
1363 |  * ensure that these two sequences do not overlap.
1364 |  */
1365 | void
1366 | bgp_refresh_begin(struct bgp_channel *c)
1367 | {
1368 |   struct bgp_proto *p = (void *) c->c.proto;
1369 | 
1370 |   if (c->load_state == BFS_LOADING)
1371 |   { log(L_WARN "%s: BEGIN-OF-RR received before END-OF-RIB, ignoring", p->p.name); return; }
1372 | 
1373 |   c->load_state = BFS_REFRESHING;
1374 |   rt_refresh_begin(c->c.table, &c->c);
1375 | 
1376 |   if (c->c.in_table)
1377 |     rt_refresh_begin(c->c.in_table, &c->c);
1378 | }
1379 | 
1380 | /**
1381 |  * bgp_refresh_end - finish incoming enhanced route refresh sequence
1382 |  * @c: BGP channel
1383 |  *
1384 |  * This function is called when an incoming enhanced route refresh sequence is
1385 |  * finished by the neighbor, demarcated by the EoRR packet. The function updates
1386 |  * the load state and ends the routing table refresh cycle. Routes not received
1387 |  * during the sequence are removed by the nest.
1388 |  */
1389 | void
1390 | bgp_refresh_end(struct bgp_channel *c)
1391 | {
1392 |   struct bgp_proto *p = (void *) c->c.proto;
1393 | 
1394 |   if (c->load_state != BFS_REFRESHING)
1395 |   { log(L_WARN "%s: END-OF-RR received without prior BEGIN-OF-RR, ignoring", p->p.name); return; }
1396 | 
1397 |   c->load_state = BFS_NONE;
1398 |   rt_refresh_end(c->c.table, &c->c);
1399 | 
1400 |   if (c->c.in_table)
1401 |     rt_prune_sync(c->c.in_table, 0);
1402 | }
