1926 | static void
1927 | bgp_reload_routes(struct channel *C)
1928 | {
1929 |   struct bgp_proto *p = (void *) C->proto;
1930 |   struct bgp_channel *c = (void *) C;
1931 | 
1932 |   /* For MPLS channel, reload all MPLS-aware channels */
1933 |   if (C == p->p.mpls_channel)
1934 |   {
1935 |     BGP_WALK_CHANNELS(p, c)
1936 |       if ((c->desc->mpls) && (p->route_refresh || c->c.in_table))
1937 | 	bgp_reload_routes(&c->c);
1938 | 
1939 |     return;
1940 |   }
1941 | 
1942 |   /* Ignore non-BGP channels */
1943 |   if (C->channel != &channel_bgp)
1944 |     return;
1945 | 
1946 |   ASSERT(p->conn && (p->route_refresh || c->c.in_table));
1947 | 
1948 |   if (c->c.in_table)
1949 |     channel_schedule_reload(C);
1950 |   else
1951 |     bgp_schedule_packet(p->conn, c, PKT_ROUTE_REFRESH);
1952 | }
1953 | 
1954 | static void
1955 | bgp_feed_begin(struct channel *C, int initial)
1956 | {
1957 |   struct bgp_proto *p = (void *) C->proto;
1958 |   struct bgp_channel *c = (void *) C;
1959 | 
1960 |   /* Ignore non-BGP channels */
1961 |   if (C->channel != &channel_bgp)
1962 |     return;
1963 | 
1964 |   /* This should not happen */
1965 |   if (!p->conn)
1966 |     return;
1967 | 
1968 |   if (initial && p->cf->gr_mode)
1969 |     c->feed_state = BFS_LOADING;
1970 | 
1971 |   /* It is refeed and both sides support enhanced route refresh */
1972 |   if (!initial && p->enhanced_refresh)
1973 |   {
1974 |     /* BoRR must not be sent before End-of-RIB */
1975 |     if (c->feed_state == BFS_LOADING || c->feed_state == BFS_LOADED)
1976 |       return;
1977 | 
1978 |     c->feed_state = BFS_REFRESHING;
1979 |     bgp_schedule_packet(p->conn, c, PKT_BEGIN_REFRESH);
1980 |   }
1981 | }
1982 | 
1983 | static void
1984 | bgp_feed_end(struct channel *C)
1985 | {
1986 |   struct bgp_proto *p = (void *) C->proto;
1987 |   struct bgp_channel *c = (void *) C;
1988 | 
1989 |   /* Ignore non-BGP channels */
1990 |   if (C->channel != &channel_bgp)
1991 |     return;
1992 | 
1993 |   /* This should not happen */
1994 |   if (!p->conn)
1995 |     return;
1996 | 
1997 |   /* Non-demarcated feed ended, nothing to do */
1998 |   if (c->feed_state == BFS_NONE)
1999 |     return;
2000 | 
2001 |   /* Schedule End-of-RIB packet */
2002 |   if (c->feed_state == BFS_LOADING)
2003 |     c->feed_state = BFS_LOADED;
2004 | 
2005 |   /* Schedule EoRR packet */
2006 |   if (c->feed_state == BFS_REFRESHING)
2007 |     c->feed_state = BFS_REFRESHED;
2008 | 
2009 |   /* Kick TX hook */
2010 |   bgp_schedule_packet(p->conn, c, PKT_UPDATE);
2011 | }
