2150 | static int
2151 | bgp_shutdown(struct proto *P)
2152 | {
2153 |   struct bgp_proto *p = (struct bgp_proto *) P;
2154 |   int subcode = 0;
2155 | 
2156 |   char *message = NULL;
2157 |   byte *data = NULL;
2158 |   uint len = 0;
2159 | 
2160 |   BGP_TRACE(D_EVENTS, "Shutdown requested");
2161 | 
2162 |   switch (P->down_code)
2163 |   {
2164 |   case PDC_CF_REMOVE:
2165 |   case PDC_CF_DISABLE:
2166 |     subcode = 3; // Errcode 6, 3 - peer de-configured
2167 |     break;
2168 | 
2169 |   case PDC_CF_RESTART:
2170 |     subcode = 6; // Errcode 6, 6 - other configuration change
2171 |     break;
2172 | 
2173 |   case PDC_CMD_DISABLE:
2174 |   case PDC_CMD_SHUTDOWN:
2175 |   shutdown:
2176 |     subcode = 2; // Errcode 6, 2 - administrative shutdown
2177 |     message = P->message;
2178 |     break;
2179 | 
2180 |   case PDC_CMD_RESTART:
2181 |     subcode = 4; // Errcode 6, 4 - administrative reset
2182 |     message = P->message;
2183 |     break;
2184 | 
2185 |   case PDC_CMD_GR_DOWN:
2186 |     if ((p->cf->gr_mode != BGP_GR_ABLE) &&
2187 | 	(p->cf->llgr_mode != BGP_LLGR_ABLE))
2188 |       goto shutdown;
2189 | 
2190 |     subcode = -1; // Do not send NOTIFICATION, just close the connection
2191 |     break;
2192 | 
2193 |   case PDC_RX_LIMIT_HIT:
2194 |   case PDC_IN_LIMIT_HIT:
2195 |     subcode = 1; // Errcode 6, 1 - max number of prefixes reached
2196 |     /* log message for compatibility */
2197 |     log(L_WARN "%s: Route limit exceeded, shutting down", p->p.name);
2198 |     goto limit;
2199 | 
2200 |   case PDC_OUT_LIMIT_HIT:
2201 |     subcode = proto_restart ? 4 : 2; // Administrative reset or shutdown
2202 | 
2203 |   limit:
2204 |     bgp_store_error(p, NULL, BE_AUTO_DOWN, BEA_ROUTE_LIMIT_EXCEEDED);
2205 |     if (proto_restart)
2206 |       bgp_update_startup_delay(p);
2207 |     else
2208 |       p->startup_delay = 0;
2209 |     goto done;
2210 |   }
2211 | 
2212 |   bgp_store_error(p, NULL, BE_MAN_DOWN, 0);
2213 |   p->startup_delay = 0;
2214 | 
2215 |   /* RFC 9003 - shutdown communication */
2216 |   if (message)
2217 |   {
2218 |     uint msg_len = strlen(message);
2219 |     msg_len = MIN(msg_len, 255);
2220 | 
2221 |     /* Buffer will be freed automatically by protocol shutdown */
2222 |     data = mb_alloc(p->p.pool, msg_len + 1);
2223 |     len = msg_len + 1;
2224 | 
2225 |     data[0] = msg_len;
2226 |     memcpy(data+1, message, msg_len);
2227 |   }
2228 | 
2229 | done:
2230 |   bgp_stop(p, subcode, data, len);
2231 |   return p->p.proto_state;
2232 | }
