2477 | void
2478 | bgp_postconfig(struct proto_config *CF)
2479 | {
2480 |   struct bgp_config *cf = (void *) CF;
2481 | 
2482 |   /* Do not check templates at all */
2483 |   if (cf->c.class == SYM_TEMPLATE)
2484 |     return;
2485 | 
2486 | 
2487 |   /* Handle undefined remote_as, zero should mean unspecified external */
2488 |   if (!cf->remote_as && (cf->peer_type == BGP_PT_INTERNAL))
2489 |     cf->remote_as = cf->local_as;
2490 | 
2491 |   int internal = (cf->local_as == cf->remote_as);
2492 |   int interior = internal || cf->confederation_member;
2493 | 
2494 |   /* EBGP direct by default, IBGP multihop by default */
2495 |   if (cf->multihop < 0)
2496 |     cf->multihop = internal ? 64 : 0;
2497 | 
2498 |   /* LLGR mode default based on GR mode */
2499 |   if (cf->llgr_mode < 0)
2500 |     cf->llgr_mode = cf->gr_mode ? BGP_LLGR_AWARE : 0;
2501 | 
2502 |   /* Link check for single-hop BGP by default */
2503 |   if (cf->check_link < 0)
2504 |     cf->check_link = !cf->multihop;
2505 | 
2506 | 
2507 |   if (!cf->local_as)
2508 |     cf_error("Local AS number must be set");
2509 | 
2510 |   if (ipa_zero(cf->remote_ip) && !cf->remote_range)
2511 |     cf_error("Neighbor must be configured");
2512 | 
2513 |   if (ipa_zero(cf->local_ip) && cf->strict_bind)
2514 |     cf_error("Local address must be configured for strict bind");
2515 | 
2516 |   if (!cf->remote_as && !cf->peer_type)
2517 |     cf_error("Remote AS number (or peer type) must be set");
2518 | 
2519 |   if ((cf->peer_type == BGP_PT_INTERNAL) && !internal)
2520 |     cf_error("IBGP cannot have different ASNs");
2521 | 
2522 |   if ((cf->peer_type == BGP_PT_EXTERNAL) &&  internal)
2523 |     cf_error("EBGP cannot have the same ASNs");
2524 | 
2525 |   if (!cf->iface && (ipa_is_link_local(cf->local_ip) ||
2526 | 		     ipa_is_link_local(cf->remote_ip)))
2527 |     cf_error("Link-local addresses require defined interface");
2528 | 
2529 |   if (!(cf->capabilities && cf->enable_as4) && (cf->remote_as > 0xFFFF))
2530 |     cf_error("Neighbor AS number out of range (AS4 not available)");
2531 | 
2532 |   if (!internal && cf->rr_client)
2533 |     cf_error("Only internal neighbor can be RR client");
2534 | 
2535 |   if (internal && cf->rs_client)
2536 |     cf_error("Only external neighbor can be RS client");
2537 | 
2538 |   if (internal && (cf->local_role != BGP_ROLE_UNDEFINED))
2539 |     cf_error("Local role cannot be set on IBGP sessions");
2540 | 
2541 |   if (interior && (cf->local_role != BGP_ROLE_UNDEFINED))
2542 |     log(L_WARN "BGP roles are not recommended to be used within AS confederations");
2543 | 
2544 |   if (cf->require_enhanced_refresh && !(cf->enable_refresh && cf->enable_enhanced_refresh))
2545 |     cf_warn("Enhanced refresh required but disabled");
2546 | 
2547 |   if (cf->require_as4 && !cf->enable_as4)
2548 |     cf_warn("AS4 support required but disabled");
2549 | 
2550 |   if (cf->require_extended_messages && !cf->enable_extended_messages)
2551 |     cf_warn("Extended messages required but not enabled");
2552 | 
2553 |   if (cf->require_gr && !cf->gr_mode)
2554 |     cf_warn("Graceful restart required but not enabled");
2555 | 
2556 |   if (cf->require_llgr && !cf->llgr_mode)
2557 |     cf_warn("Long-lived graceful restart required but not enabled");
2558 | 
2559 |   if (cf->require_roles && (cf->local_role == BGP_ROLE_UNDEFINED))
2560 |     cf_error("Local role must be set if roles are required");
2561 | 
2562 |   if (!cf->confederation && cf->confederation_member)
2563 |     cf_error("Confederation ID must be set for member sessions");
2564 | 
2565 |   if (cf->multihop && (ipa_is_link_local(cf->local_ip) ||
2566 | 		       ipa_is_link_local(cf->remote_ip)))
2567 |     cf_error("Multihop BGP cannot be used with link-local addresses");
2568 | 
2569 |   if (cf->multihop && cf->iface)
2570 |     cf_error("Multihop BGP cannot be bound to interface");
2571 | 
2572 |   if (cf->multihop && cf->check_link)
2573 |     cf_error("Multihop BGP cannot depend on link state");
2574 | 
2575 |   if (cf->multihop && cf->bfd && ipa_zero(cf->local_ip))
2576 |     cf_error("Multihop BGP with BFD requires specified local address");
2577 | 
2578 |   if (!cf->gr_mode && cf->llgr_mode)
2579 |     cf_error("Long-lived graceful restart requires basic graceful restart");
2580 | 
2581 |   if (internal && cf->enforce_first_as)
2582 |     cf_error("Enforce first AS check is requires EBGP sessions");
2583 | 
2584 |   if (cf->keepalive_time > cf->hold_time)
2585 |     cf_error("Keepalive time must be at most hold time");
2586 | 
2587 |   if (cf->keepalive_time > (cf->hold_time / 2))
2588 |     log(L_WARN "Keepalive time should be at most 1/2 of hold time");
2589 | 
2590 |   if (cf->min_hold_time > cf->hold_time)
2591 |     cf_error("Min hold time (%u) exceeds hold time (%u)",
2592 | 	     cf->min_hold_time, cf->hold_time);
2593 | 
2594 |   uint keepalive_time = cf->keepalive_time ?: cf->hold_time / 3;
2595 |   if (cf->min_keepalive_time > keepalive_time)
2596 |     cf_error("Min keepalive time (%u) exceeds keepalive time (%u)",
2597 | 	     cf->min_keepalive_time, keepalive_time);
2598 | 
2599 |   if (cf->min_gr_time > cf->max_gr_time)
2600 |     cf_error("Min graceful restart time (%u) exceeds max graceful restart time (%u)",
2601 | 	     cf->min_gr_time, cf->max_gr_time);
2602 | 
2603 |   if (cf->min_llgr_time > cf->max_llgr_time)
2604 |     cf_error("Min long-lived stale time (%u) exceeds max long-lived stale time (%u)",
2605 | 	     cf->min_llgr_time, cf->max_llgr_time);
2606 | 
2607 |   /* Legacy case: password option without authentication option */
2608 |   if ((cf->auth_type == BGP_AUTH_NONE) && cf->password && !cf->ao_keys)
2609 |   {
2610 |     cf_warn("Missing authentication option, assuming MD5");
2611 |     cf->auth_type = BGP_AUTH_MD5;
2612 |   }
2613 | 
2614 |   if ((cf->auth_type == BGP_AUTH_MD5) != !!cf->password)
2615 |     cf_error("MD5 authentication and password option should be used together");
2616 | 
2617 |   if ((cf->auth_type == BGP_AUTH_AO) != !!cf->ao_keys)
2618 |     cf_error("AO authentication and keys option should be used together");
2619 | 
2620 |   if ((cf->auth_type == BGP_AUTH_AO) && cf->remote_range)
2621 |     cf_error("AO authentication not supported on dynamic BGP sessions");
2622 | 
2623 |   struct bgp_channel_config *cc;
2624 |   BGP_CF_WALK_CHANNELS(cf, cc)
2625 |   {
2626 |     /* Handle undefined import filter */
2627 |     if (cc->c.in_filter == FILTER_UNDEF)
2628 |       if (interior)
2629 | 	cc->c.in_filter = FILTER_ACCEPT;
2630 |       else
2631 | 	cf_error("EBGP requires explicit import policy");
2632 | 
2633 |     /* Handle undefined export filter */
2634 |     if (cc->c.out_filter == FILTER_UNDEF)
2635 |       if (interior)
2636 | 	cc->c.out_filter = FILTER_REJECT;
2637 |       else
2638 | 	cf_error("EBGP requires explicit export policy");
2639 | 
2640 |     /* Disable after error incompatible with restart limit action */
2641 |     if ((cc->c.in_limit.action == PLA_RESTART) && cf->disable_after_error)
2642 |       cc->c.in_limit.action = PLA_DISABLE;
2643 | 
2644 |     /* Different default based on rr_client, rs_client */
2645 |     if (cc->next_hop_keep == 0xff)
2646 |       cc->next_hop_keep = cf->rr_client ? NH_IBGP : (cf->rs_client ? NH_ALL : NH_NO);
2647 | 
2648 |     /* Different default for gw_mode */
2649 |     if (!cc->gw_mode)
2650 |       cc->gw_mode = cf->multihop ? GW_RECURSIVE : GW_DIRECT;
2651 | 
2652 |     /* Different default for next_hop_prefer */
2653 |     if (!cc->next_hop_prefer)
2654 |       cc->next_hop_prefer = (cc->gw_mode == GW_DIRECT) ? NHP_GLOBAL : NHP_LOCAL;
2655 | 
2656 |     /* Defaults based on proto config */
2657 |     if (cc->gr_able == 0xff)
2658 |       cc->gr_able = (cf->gr_mode == BGP_GR_ABLE);
2659 | 
2660 |     if (cc->llgr_able == 0xff)
2661 |       cc->llgr_able = (cf->llgr_mode == BGP_LLGR_ABLE);
2662 | 
2663 |     if (cc->llgr_time == ~0U)
2664 |       cc->llgr_time = cf->llgr_time;
2665 | 
2666 |     if (cc->min_llgr_time == ~0U)
2667 |       cc->min_llgr_time = cf->min_llgr_time;
2668 | 
2669 |     if (cc->max_llgr_time == ~0U)
2670 |       cc->max_llgr_time = cf->max_llgr_time;
2671 | 
2672 |     /* AIGP enabled by default on interior sessions */
2673 |     if (cc->aigp == 0xff)
2674 |       cc->aigp = interior;
2675 | 
2676 |     /* Default values of IGP tables */
2677 |     if ((cc->gw_mode == GW_RECURSIVE) && !cc->desc->no_igp)
2678 |     {
2679 |       if (!cc->igp_table_ip4 && (bgp_cc_is_ipv4(cc) || cc->ext_next_hop))
2680 | 	cc->igp_table_ip4 = bgp_default_igp_table(cf, cc, NET_IP4);
2681 | 
2682 |       if (!cc->igp_table_ip6 && (bgp_cc_is_ipv6(cc) || cc->ext_next_hop))
2683 | 	cc->igp_table_ip6 = bgp_default_igp_table(cf, cc, NET_IP6);
2684 | 
2685 |       if (cc->igp_table_ip4 && bgp_cc_is_ipv6(cc) && !cc->ext_next_hop)
2686 | 	cf_error("Mismatched IGP table type");
2687 | 
2688 |       if (cc->igp_table_ip6 && bgp_cc_is_ipv4(cc) && !cc->ext_next_hop)
2689 | 	cf_error("Mismatched IGP table type");
2690 |     }
2691 | 
2692 |     /* Default value of base table */
2693 |     if ((BGP_SAFI(cc->afi) == BGP_SAFI_FLOW) && cc->validate && !cc->base_table)
2694 |       cc->base_table = bgp_default_base_table(cf, cc);
2695 | 
2696 |     if (cc->base_table && !cc->base_table->trie_used)
2697 |       cf_error("Flowspec validation requires base table (%s) with trie",
2698 | 	       cc->base_table->name);
2699 | 
2700 |     if (cf->multihop && (cc->gw_mode == GW_DIRECT))
2701 |       cf_error("Multihop BGP cannot use direct gateway mode");
2702 | 
2703 |     if ((cc->gw_mode == GW_RECURSIVE) && cc->c.table->sorted)
2704 |       cf_error("BGP in recursive mode prohibits sorted table");
2705 | 
2706 |     if (cf->deterministic_med && cc->c.table->sorted)
2707 |       cf_error("BGP with deterministic MED prohibits sorted table");
2708 | 
2709 |     if (cc->secondary && !cc->c.table->sorted)
2710 |       cf_error("BGP with secondary option requires sorted table");
2711 | 
2712 |     if (cc->require_ext_next_hop && !cc->ext_next_hop)
2713 |       cf_warn("Extended next hop required but not enabled");
2714 | 
2715 |     if (cc->require_add_path && !cc->add_path)
2716 |       cf_warn("ADD-PATH required but not enabled");
2717 | 
2718 |     if (cc->min_llgr_time > cc->max_llgr_time)
2719 |       cf_error("Min long-lived stale time (%u) exceeds max long-lived stale time (%u)",
2720 | 	       cc->min_llgr_time, cc->max_llgr_time);
2721 | 
2722 |   }
