2725 | static int
2726 | bgp_reconfigure(struct proto *P, struct proto_config *CF)
2727 | {
2728 |   struct bgp_proto *p = (void *) P;
2729 |   const struct bgp_config *new = (void *) CF;
2730 |   const struct bgp_config *old = p->cf;
2731 | 
2732 |   if (proto_get_router_id(CF) != p->local_id)
2733 |     return 0;
2734 | 
2735 |   if (bstrcmp(proto_get_hostname(CF), p->hostname))
2736 |     return 0;
2737 | 
2738 |   int same = !memcmp(((byte *) old) + sizeof(struct proto_config),
2739 | 		     ((byte *) new) + sizeof(struct proto_config),
2740 | 		     // password item is last and must be checked separately
2741 | 		     OFFSETOF(struct bgp_config, password) - sizeof(struct proto_config))
2742 |     && !bstrcmp(old->password, new->password)
2743 |     && ((!old->remote_range && !new->remote_range)
2744 | 	|| (old->remote_range && new->remote_range && net_equal(old->remote_range, new->remote_range)))
2745 |     && !bstrcmp(old->dynamic_name, new->dynamic_name)
2746 |     && (old->dynamic_name_digits == new->dynamic_name_digits);
2747 | 
2748 |   /* Reconfigure TCP-AP */
2749 |   same = same && bgp_reconfigure_ao_keys(p, new);
2750 | 
2751 |   /* FIXME: Move channel reconfiguration to generic protocol code ? */
2752 |   struct channel *C, *C2;
2753 |   struct bgp_channel_config *cc;
2754 | 
2755 |   WALK_LIST(C, p->p.channels)
2756 |     C->stale = 1;
2757 | 
2758 |   /* Reconfigure BGP channels */
2759 |   BGP_CF_WALK_CHANNELS(new, cc)
2760 |   {
2761 |     C = (struct channel *) bgp_find_channel(p, cc->afi);
2762 |     same = proto_configure_channel(P, &C, &cc->c) && same;
2763 |   }
2764 | 
2765 |   /* Reconfigure MPLS channel */
2766 |   same = proto_configure_channel(P, &P->mpls_channel, proto_cf_mpls_channel(CF)) && same;
2767 | 
2768 |   WALK_LIST_DELSAFE(C, C2, p->p.channels)
2769 |     if (C->stale)
2770 |       same = proto_configure_channel(P, &C, NULL) && same;
2771 | 
2772 |   /* Reset name counter */
2773 |   p->dynamic_name_counter = 0;
2774 | 
2775 |   if (!same)
2776 |     return 0;
2777 | 
2778 |   /* We should update our copy of configuration ptr as old configuration will be freed */
2779 |   p->cf = new;
2780 |   p->hostname = proto_get_hostname(CF);
2781 | 
2782 |   /* Check whether existing connections are compatible with required capabilities */
2783 |   struct bgp_conn *ci = &p->incoming_conn;
2784 |   if (((ci->state == BS_OPENCONFIRM) || (ci->state == BS_ESTABLISHED)) && !bgp_check_capabilities(ci))
2785 |     return 0;
2786 | 
2787 |   struct bgp_conn *co = &p->outgoing_conn;
2788 |   if (((co->state == BS_OPENCONFIRM) || (co->state == BS_ESTABLISHED)) && !bgp_check_capabilities(co))
2789 |     return 0;
2790 | 
2791 |   proto_setup_mpls_map(P, RTS_BGP, 1);
2792 | 
2793 |   if (p->start_state > BSS_PREPARE)
2794 |     bgp_update_bfd(p, new->bfd);
2795 | 
2796 |   return 1;
2797 | }
