2870 | /**
2871 |  * bgp_error - report a protocol error
2872 |  * @c: connection
2873 |  * @code: error code (according to the RFC)
2874 |  * @subcode: error sub-code
2875 |  * @data: data to be passed in the Notification message
2876 |  * @len: length of the data
2877 |  *
2878 |  * bgp_error() sends a notification packet to tell the other side that a protocol
2879 |  * error has occurred (including the data considered erroneous if possible) and
2880 |  * closes the connection.
2881 |  */
2882 | void
2883 | bgp_error(struct bgp_conn *c, uint code, uint subcode, byte *data, int len)
2884 | {
2885 |   struct bgp_proto *p = c->bgp;
2886 | 
2887 |   if (c->state == BS_CLOSE)
2888 |     return;
2889 | 
2890 |   bgp_log_error(p, BE_BGP_TX, "Error", code, subcode, data, ABS(len));
2891 |   bgp_store_error(p, c, BE_BGP_TX, (code << 16) | subcode);
2892 | 
2893 |   c->notify_code = code;
2894 |   c->notify_subcode = subcode;
2895 |   c->notify_data = data;
2896 |   c->notify_size = (len > 0) ? len : 0;
2897 | 
2898 |   bgp_conn_enter_close_state(c);
2899 |   bgp_schedule_packet(c, NULL, PKT_NOTIFICATION);
2900 | 
2901 |   if (code != 6)
2902 |   {
2903 |     bgp_update_startup_delay(p);
2904 |     bgp_stop(p, 0, NULL, 0);
2905 |   }
2906 | }
