2908 | /**
2909 |  * bgp_store_error - store last error for status report
2910 |  * @p: BGP instance
2911 |  * @c: connection
2912 |  * @class: error class (BE_xxx constants)
2913 |  * @code: error code (class specific)
2914 |  *
2915 |  * bgp_store_error() decides whether given error is interesting enough
2916 |  * and store that error to last_error variables of @p
2917 |  */
2918 | void
2919 | bgp_store_error(struct bgp_proto *p, struct bgp_conn *c, u8 class, u32 code)
2920 | {
2921 |   /* During PS_UP, we ignore errors on secondary connection */
2922 |   if ((p->p.proto_state == PS_UP) && c && (c != p->conn))
2923 |     return;
2924 | 
2925 |   /* During PS_STOP, we ignore any errors, as we want to report
2926 |    * the error that caused transition to PS_STOP
2927 |    */
2928 |   if (p->p.proto_state == PS_STOP)
2929 |     return;
2930 | 
2931 |   p->last_error_class = class;
2932 |   p->last_error_code = code;
2933 | }
