 148 | /**
 149 |  * bgp_open - open a BGP instance
 150 |  * @p: BGP instance
 151 |  *
 152 |  * This function allocates and configures shared BGP resources, mainly listening
 153 |  * sockets. Should be called as the last step during initialization (when lock
 154 |  * is acquired and neighbor is ready). When error, caller should change state to
 155 |  * PS_DOWN and return immediately.
 156 |  */
 157 | static int
 158 | bgp_open(struct bgp_proto *p)
 159 | {
 160 |   struct bgp_socket *bs = NULL;
 161 |   struct iface *ifa = p->cf->strict_bind ? p->cf->iface : NULL;
 162 |   ip_addr addr = p->cf->strict_bind ? p->cf->local_ip :
 163 |     (p->ipv4 ? IPA_NONE4 : IPA_NONE6);
 164 |   uint port = p->cf->local_port;
 165 |   uint flags = p->cf->free_bind ? SKF_FREEBIND : 0;
 166 |   uint flag_mask = SKF_FREEBIND;
 167 | 
 168 |   /* We assume that cf->iface is defined iff cf->local_ip is link-local */
 169 | 
 170 |   WALK_LIST(bs, bgp_sockets)
 171 |     if (ipa_equal(bs->sk->saddr, addr) &&
 172 | 	(bs->sk->sport == port) &&
 173 | 	(bs->sk->iface == ifa) &&
 174 | 	(bs->sk->vrf == p->p.vrf) &&
 175 | 	((bs->sk->flags & flag_mask) == flags))
 176 |     {
 177 |       bs->uc++;
 178 |       p->sock = bs;
 179 |       return 0;
 180 |     }
 181 | 
 182 |   sock *sk = sk_new(proto_pool);
 183 |   sk->type = SK_TCP_PASSIVE;
 184 |   sk->ttl = 255;
 185 |   sk->saddr = addr;
 186 |   sk->sport = port;
 187 |   sk->iface = ifa;
 188 |   sk->vrf = p->p.vrf;
 189 |   sk->flags = flags;
 190 |   sk->tos = IP_PREC_INTERNET_CONTROL;
 191 |   sk->rbsize = BGP_RX_BUFFER_SIZE;
 192 |   sk->tbsize = BGP_TX_BUFFER_SIZE;
 193 |   sk->rx_hook = bgp_incoming_connection;
 194 |   sk->err_hook = bgp_listen_sock_err;
 195 | 
 196 |   if (sk_open(sk) < 0)
 197 |     goto err;
 198 | 
 199 |   bs = mb_allocz(proto_pool, sizeof(struct bgp_socket));
 200 |   bs->sk = sk;
 201 |   bs->uc = 1;
 202 |   p->sock = bs;
 203 |   sk->data = bs;
 204 | 
 205 |   add_tail(&bgp_sockets, &bs->n);
 206 | 
 207 |   return 0;
 208 | 
 209 | err:
 210 |   sk_log_error(sk, p->p.name);
 211 |   log(L_ERR "%s: Cannot open listening socket", p->p.name);
 212 |   rfree(sk);
 213 |   return -1;
 214 | }
