 216 | /**
 217 |  * bgp_close - close a BGP instance
 218 |  * @p: BGP instance
 219 |  *
 220 |  * This function frees and deconfigures shared BGP resources.
 221 |  */
 222 | static void
 223 | bgp_close(struct bgp_proto *p)
 224 | {
 225 |   struct bgp_socket *bs = p->sock;
 226 | 
 227 |   ASSERT(bs && bs->uc);
 228 | 
 229 |   if (--bs->uc)
 230 |     return;
 231 | 
 232 |   rfree(bs->sk);
 233 |   rem_node(&bs->n);
 234 |   mb_free(bs);
 235 | }
