 278 | static inline int
 279 | bgp_sk_add_ao_key(struct bgp_proto *p, sock *sk, struct bgp_ao_key *key)
 280 | {
 281 |   ip_addr prefix = p->cf->remote_ip;
 282 |   int pxlen = -1;
 283 | 
 284 |   int rv = sk_add_ao_key(sk, prefix, pxlen, p->cf->iface, &key->key, false, false);
 285 |   if (rv < 0)
 286 |   {
 287 |     sk_log_error(sk, p->p.name);
 288 |     log(L_ERR "%s: Cannot add TCP-AO key %d/%d to BGP %s socket",
 289 | 	p->p.name, key->key.send_id, key->key.recv_id,
 290 | 	((sk == p->sock->sk) ? "listening" : "session"));
 291 |   }
 292 | 
 293 |   return rv;
 294 | }
 295 | 
 296 | static int
 297 | bgp_enable_ao_key(struct bgp_proto *p, struct bgp_ao_key *key)
 298 | {
 299 |   ASSERT(!key->active);
 300 | 
 301 |   BGP_TRACE(D_EVENTS, "Adding TCP-AO key %d/%d", key->key.send_id, key->key.recv_id);
 302 | 
 303 |   /* Handle listening socket */
 304 |   if (bgp_sk_add_ao_key(p, p->sock->sk, key) < 0)
 305 |   {
 306 |     key->failed = 1;
 307 |     return -1;
 308 |   }
 309 | 
 310 |   key->active = 1;
 311 | 
 312 |   /* Handle incoming socket */
 313 |   if (p->incoming_conn.sk)
 314 |     if (bgp_sk_add_ao_key(p, p->incoming_conn.sk, key) < 0)
 315 |       return -1;
 316 | 
 317 |   /* Handle outgoing socket */
 318 |   if (p->outgoing_conn.sk)
 319 |     if (bgp_sk_add_ao_key(p, p->outgoing_conn.sk, key) < 0)
 320 |       return -1;
 321 | 
 322 |   return 0;
 323 | }
