 331 | static int
 332 | bgp_sk_delete_ao_key(struct bgp_proto *p, sock *sk, struct bgp_ao_key *key,
 333 | 		     struct bgp_ao_key *backup, int current_key_id, int rnext_key_id)
 334 | {
 335 |   struct ao_key *set_current = NULL, *set_rnext = NULL;
 336 | 
 337 |   if ((key->key.send_id == current_key_id) && backup)
 338 |   {
 339 |     log(L_WARN "%s: Deleting TCP-AO Current key %d/%d, setting Current key to %d/%d",
 340 | 	p->p.name, key->key.send_id, key->key.recv_id, backup->key.send_id, backup->key.recv_id);
 341 | 
 342 |     set_current = &backup->key;
 343 |   }
 344 | 
 345 |   if ((key->key.recv_id == rnext_key_id) && backup)
 346 |   {
 347 |     log(L_WARN "%s: Deleting TCP-AO RNext key %d/%d, setting RNext key to %d/%d",
 348 | 	p->p.name, key->key.send_id, key->key.recv_id, backup->key.send_id, backup->key.recv_id);
 349 | 
 350 |     set_rnext = &backup->key;
 351 |   }
 352 | 
 353 |   ip_addr prefix = p->cf->remote_ip;
 354 |   int pxlen = -1;
 355 | 
 356 |   int rv = sk_delete_ao_key(sk, prefix, pxlen, p->cf->iface, &key->key, set_current, set_rnext);
 357 |   if (rv < 0)
 358 |   {
 359 |     sk_log_error(sk, p->p.name);
 360 |     log(L_ERR "%s: Cannot delete TCP-AO key %d/%d from BGP %s socket",
 361 | 	p->p.name, key->key.send_id, key->key.recv_id,
 362 | 	((sk == p->sock->sk) ? "listening" : "session"));
 363 |   }
 364 | 
 365 |   return rv;
 366 | }
