 368 | static int
 369 | bgp_disable_ao_key(struct bgp_proto *p, struct bgp_ao_key *key, struct bgp_active_keys *info)
 370 | {
 371 |   ASSERT(key->active);
 372 | 
 373 |   BGP_TRACE(D_EVENTS, "Deleting TCP-AO key %d/%d", key->key.send_id, key->key.recv_id);
 374 | 
 375 |   /* Handle listening socket */
 376 |   if (bgp_sk_delete_ao_key(p, p->sock->sk, key, NULL, -1, -1) < 0)
 377 |     return -1;
 378 | 
 379 |   key->active = 0;
 380 | 
 381 |   /* Handle incoming socket */
 382 |   if (p->incoming_conn.sk && info)
 383 |     if (bgp_sk_delete_ao_key(p, p->incoming_conn.sk, key, info->backup, info->in_current, info->in_rnext) < 0)
 384 |       return -1;
 385 | 
 386 |   /* Handle outgoing socket */
 387 |   if (p->outgoing_conn.sk && info)
 388 |     if (bgp_sk_delete_ao_key(p, p->outgoing_conn.sk, key, info->backup, info->out_current, info->out_rnext) < 0)
 389 |       return -1;
 390 | 
 391 |   return 0;
 392 | }
