 409 | static struct bgp_ao_key *
 410 | bgp_select_best_ao_key(struct bgp_proto *p)
 411 | {
 412 |   struct bgp_ao_key *best = NULL;
 413 | 
 414 |   WALK_LIST_(struct bgp_ao_key, key, p->ao.keys)
 415 |   {
 416 |     if (!key->active)
 417 |       continue;
 418 | 
 419 |     /* Never select deprecated keys */
 420 |     if (key->key.preference < 0)
 421 |       continue;
 422 | 
 423 |     if (!best || (best->key.preference < key->key.preference))
 424 |       best = key;
 425 |   }
 426 | 
 427 |   return best;
 428 | }
