 924 | static void
 925 | bgp_down(struct bgp_proto *p)
 926 | {
 927 |   if (p->start_state > BSS_PREPARE)
 928 |   {
 929 |     bgp_setup_auth(p, 0);
 930 |     bgp_close(p);
 931 |   }
 932 | 
 933 |   p->neigh = NULL;
 934 | 
 935 |   BGP_TRACE(D_EVENTS, "Down");
 936 |   proto_notify_state(&p->p, PS_DOWN);
