 944 |   DBG("BGP: Decision start\n");
 945 |   if ((p->p.proto_state == PS_START) &&
 946 |       (p->outgoing_conn.state == BS_IDLE) &&
 947 |       (p->incoming_conn.state != BS_OPENCONFIRM) &&
 948 |       !p->passive)
 949 |     bgp_active(p);
 950 | 
 951 |   if ((p->p.proto_state == PS_STOP) &&
 952 |       (p->outgoing_conn.state == BS_IDLE) &&
 953 |       (p->incoming_conn.state == BS_IDLE))
