1150 | static void
1151 | bgp_conn_leave_established_state(struct bgp_conn *conn, struct bgp_proto *p)
1152 | {
1153 |   BGP_TRACE(D_EVENTS, "BGP session closed");
1154 |   p->last_established = current_time();
1155 |   p->conn = NULL;
1156 | 
1157 |   if (p->p.proto_state == PS_UP)
1158 |     bgp_stop(p, 0, NULL, 0);
1159 | 
1160 |   bmp_peer_down(p, p->last_error_class,
1161 | 		conn->notify_code, conn->notify_subcode,
1162 | 		conn->notify_data, conn->notify_size);
1163 | }
