1165 | void
1166 | bgp_conn_enter_close_state(struct bgp_conn *conn)
1167 | {
1168 |   struct bgp_proto *p = conn->bgp;
1169 |   int os = conn->state;
1170 | 
1171 |   bgp_conn_set_state(conn, BS_CLOSE);
1172 |   tm_stop(conn->keepalive_timer);
1173 |   conn->sk->rx_hook = NULL;
1174 | 
1175 |   /* Timeout for CLOSE state, if we cannot send notification soon then we just hangup */
1176 |   bgp_start_timer(conn->hold_timer, 10);
1177 | 
1178 |   if (os == BS_ESTABLISHED)
1179 |     bgp_conn_leave_established_state(conn, p);
1180 | }
