1196 | /**
1197 |  * bgp_handle_graceful_restart - handle detected BGP graceful restart
1198 |  * @p: BGP instance
1199 |  *
1200 |  * This function is called when a BGP graceful restart of the neighbor is
1201 |  * detected (when the TCP connection fails or when a new TCP connection
1202 |  * appears). The function activates processing of the restart - starts routing
1203 |  * table refresh cycle and activates BGP restart timer. The protocol state goes
1204 |  * back to %PS_START, but changing BGP state back to %BS_IDLE is left for the
1205 |  * caller.
1206 |  */
1207 | void
1208 | bgp_handle_graceful_restart(struct bgp_proto *p)
1209 | {
1210 |   ASSERT(p->conn && (p->conn->state == BS_ESTABLISHED) && p->gr_ready);
1211 | 
1212 |   BGP_TRACE(D_EVENTS, "Neighbor graceful restart detected%s",
1213 | 	    p->gr_active_num ? " - already pending" : "");
1214 | 
1215 |   p->gr_active_num = 0;
1216 | 
1217 |   struct bgp_channel *c;
1218 |   BGP_WALK_CHANNELS(p, c)
1219 |   {
1220 |     /* FIXME: perhaps check for channel state instead of disabled flag? */
1221 |     if (c->c.disabled)
1222 |       continue;
1223 | 
1224 |     if (c->gr_ready)
1225 |     {
1226 |       p->gr_active_num++;
1227 | 
1228 |       switch (c->gr_active)
1229 |       {
1230 |       case BGP_GRS_NONE:
1231 | 	c->gr_active = BGP_GRS_ACTIVE;
1232 | 	rt_refresh_begin(c->c.table, &c->c);
1233 | 	break;
1234 | 
1235 |       case BGP_GRS_ACTIVE:
1236 | 	rt_refresh_end(c->c.table, &c->c);
1237 | 	rt_refresh_begin(c->c.table, &c->c);
1238 | 	break;
1239 | 
1240 |       case BGP_GRS_LLGR:
1241 | 	rt_refresh_begin(c->c.table, &c->c);
1242 | 	rt_modify_stale(c->c.table, &c->c);
1243 | 	break;
1244 |       }
1245 |     }
1246 |     else
1247 |     {
1248 |       /* Just flush the routes */
1249 |       rt_refresh_begin(c->c.table, &c->c);
1250 |       rt_refresh_end(c->c.table, &c->c);
1251 |     }
1252 | 
1253 |     /* Reset bucket and prefix tables */
1254 |     bgp_free_bucket_table(c);
1255 |     bgp_free_prefix_table(c);
1256 |     bgp_init_bucket_table(c);
1257 |     bgp_init_prefix_table(c);
1258 |     c->packets_to_send = 0;
1259 |   }
1260 | 
1261 |   /* p->gr_ready -> at least one active channel is c->gr_ready */
1262 |   ASSERT(p->gr_active_num > 0);
1263 | 
1264 |   uint gr_time = CLAMP(p->conn->remote_caps->gr_time,
1265 | 		       p->cf->min_gr_time, p->cf->max_gr_time);
1266 | 
1267 |   proto_notify_state(&p->p, PS_START);
1268 |   tm_start(p->gr_timer, gr_time S);
1269 | }
1270 | 
1271 | /**
1272 |  * bgp_graceful_restart_done - finish active BGP graceful restart
1273 |  * @c: BGP channel
1274 |  *
1275 |  * This function is called when the active BGP graceful restart of the neighbor
1276 |  * should be finished for channel @c - either successfully (the neighbor sends
1277 |  * all paths and reports end-of-RIB for given AFI/SAFI on the new session) or
1278 |  * unsuccessfully (the neighbor does not support BGP graceful restart on the new
1279 |  * session). The function ends the routing table refresh cycle.
1280 |  */
1281 | void
1282 | bgp_graceful_restart_done(struct bgp_channel *c)
1283 | {
1284 |   struct bgp_proto *p = (void *) c->c.proto;
1285 | 
1286 |   ASSERT(c->gr_active);
1287 |   c->gr_active = 0;
1288 |   p->gr_active_num--;
1289 | 
1290 |   if (!p->gr_active_num)
1291 |     BGP_TRACE(D_EVENTS, "Neighbor graceful restart done");
1292 | 
1293 |   tm_stop(c->stale_timer);
1294 |   rt_refresh_end(c->c.table, &c->c);
1295 | }
1296 | 
1297 | /**
1298 |  * bgp_graceful_restart_timeout - timeout of graceful restart 'restart timer'
1299 |  * @t: timer
1300 |  *
1301 |  * This function is a timeout hook for @gr_timer, implementing BGP restart time
1302 |  * limit for reestablisment of the BGP session after the graceful restart. When
1303 |  * fired, we just proceed with the usual protocol restart.
1304 |  */
1305 | 
1306 | static void
1307 | bgp_graceful_restart_timeout(timer *t)
1308 | {
1309 |   struct bgp_proto *p = t->data;
1310 | 
1311 |   BGP_TRACE(D_EVENTS, "Neighbor graceful restart timeout");
1312 | 
1313 |   if (p->llgr_ready)
1314 |   {
1315 |     struct bgp_channel *c;
1316 |     BGP_WALK_CHANNELS(p, c)
1317 |     {
1318 |       /* Channel is not in GR and is already flushed */
1319 |       if (!c->gr_active)
1320 | 	continue;
1321 | 
1322 |       /* Channel is already in LLGR from past restart */
1323 |       if (c->gr_active == BGP_GRS_LLGR)
1324 | 	continue;
1325 | 
1326 |       /* Channel is in GR, but does not support LLGR -> stop GR */
1327 |       if (!c->stale_time)
1328 |       {
1329 | 	bgp_graceful_restart_done(c);
1330 | 	continue;
1331 |       }
1332 | 
1333 |       /* Channel is in GR, and supports LLGR -> start LLGR */
1334 |       c->gr_active = BGP_GRS_LLGR;
1335 |       tm_start(c->stale_timer, c->stale_time S);
1336 |       rt_modify_stale(c->c.table, &c->c);
1337 |     }
1338 |   }
1339 |   else
1340 |     bgp_stop(p, 0, NULL, 0);
1341 | }
1342 | 
1343 | static void
1344 | bgp_long_lived_stale_timeout(timer *t)
1345 | {
1346 |   struct bgp_channel *c = t->data;
1347 |   struct bgp_proto *p = (void *) c->c.proto;
1348 | 
1349 |   BGP_TRACE(D_EVENTS, "Long-lived stale timeout");
1350 | 
1351 |   bgp_graceful_restart_done(c);
1352 | }
