1557 | static void
1558 | bgp_setup_sk(struct bgp_conn *conn, sock *s)
1559 | {
1560 |   s->data = conn;
1561 |   s->err_hook = bgp_sock_err;
1562 |   s->fast_rx = 1;
1563 |   conn->sk = s;
1564 | }
1565 | 
1566 | static void
1567 | bgp_active(struct bgp_proto *p)
1568 | {
1569 |   int delay = MAX(1, p->cf->connect_delay_time);
1570 |   struct bgp_conn *conn = &p->outgoing_conn;
1571 | 
1572 |   BGP_TRACE(D_EVENTS, "Connect delayed by %d seconds", delay);
1573 |   bgp_setup_conn(p, conn);
1574 |   bgp_conn_set_state(conn, BS_ACTIVE);
1575 |   bgp_start_timer(conn->connect_timer, delay);
1576 | }
