1578 | /**
1579 |  * bgp_connect - initiate an outgoing connection
1580 |  * @p: BGP instance
1581 |  *
1582 |  * The bgp_connect() function creates a new &bgp_conn and initiates
1583 |  * a TCP connection to the peer. The rest of connection setup is governed
1584 |  * by the BGP state machine as described in the standard.
1585 |  */
1586 | static void
1587 | bgp_connect(struct bgp_proto *p)	/* Enter Connect state and start establishing connection */
1588 | {
1589 |   struct bgp_conn *conn = &p->outgoing_conn;
1590 |   int hops = p->cf->multihop ?: 1;
1591 | 
1592 |   DBG("BGP: Connecting\n");
1593 |   sock *s = sk_new(p->p.pool);
1594 |   s->type = SK_TCP_ACTIVE;
1595 |   s->saddr = p->local_ip;
1596 |   s->daddr = p->remote_ip;
1597 |   s->dport = p->cf->remote_port;
1598 |   s->iface = p->neigh ? p->neigh->iface : NULL;
1599 |   s->vrf = p->p.vrf;
1600 |   s->ttl = p->cf->ttl_security ? 255 : hops;
1601 |   s->rbsize = p->cf->enable_extended_messages ? BGP_RX_BUFFER_EXT_SIZE : BGP_RX_BUFFER_SIZE;
1602 |   s->tbsize = p->cf->enable_extended_messages ? BGP_TX_BUFFER_EXT_SIZE : BGP_TX_BUFFER_SIZE;
1603 |   s->tos = IP_PREC_INTERNET_CONTROL;
1604 |   s->tx_hook = bgp_connected;
1605 |   s->flags = p->cf->free_bind ? SKF_FREEBIND : 0;
1606 |   BGP_TRACE(D_EVENTS, "Connecting to %I%J from local address %I%J",
1607 | 	    s->daddr, ipa_is_link_local(s->daddr) ? p->cf->iface : NULL,
1608 | 	    s->saddr, ipa_is_link_local(s->saddr) ? s->iface : NULL);
1609 |   bgp_setup_conn(p, conn);
1610 |   bgp_setup_sk(conn, s);
1611 |   bgp_conn_set_state(conn, BS_CONNECT);
1612 | 
1613 |   if (p->cf->auth_type == BGP_AUTH_MD5)
1614 |     s->password = p->cf->password;
1615 | 
1616 |   if (p->cf->auth_type == BGP_AUTH_AO)
1617 |     if (bgp_list_ao_keys(p, &s->ao_keys_init, &s->ao_keys_num) < 0)
1618 |       goto err2;
1619 | 
1620 |   if (sk_open(s) < 0)
1621 |     goto err;
1622 | 
1623 |   /* Set minimal receive TTL if needed */
1624 |   if (p->cf->ttl_security)
1625 |     if (sk_set_min_ttl(s, 256 - hops) < 0)
1626 |       goto err;
1627 | 
1628 |   s->ao_keys_num = 0;
1629 |   s->ao_keys_init = NULL;
1630 | 
1631 |   DBG("BGP: Waiting for connect success\n");
1632 |   bgp_start_timer(conn->connect_timer, p->cf->connect_retry_time);
1633 |   return;
1634 | 
1635 | err:
1636 |   sk_log_error(s, p->p.name);
1637 | err2:
1638 |   bgp_sock_err(s, 0);
1639 |   return;
1640 | }
1641 | 
1642 | static inline int bgp_is_dynamic(struct bgp_proto *p)
1643 | { return ipa_zero(p->remote_ip); }
1644 | 
1645 | /**
1646 |  * bgp_find_proto - find existing proto for incoming connection
1647 |  * @sk: TCP socket
1648 |  *
1649 |  */
1650 | static struct bgp_proto *
1651 | bgp_find_proto(sock *sk)
1652 | {
1653 |   struct bgp_proto *best = NULL;
1654 |   struct bgp_proto *p;
1655 | 
1656 |   /* sk->iface is valid only if src or dst address is link-local */
1657 |   int link = ipa_is_link_local(sk->saddr) || ipa_is_link_local(sk->daddr);
1658 | 
1659 |   WALK_LIST(p, proto_list)
1660 |     if ((p->p.proto == &proto_bgp) &&
1661 | 	(ipa_equal(p->remote_ip, sk->daddr) || bgp_is_dynamic(p)) &&
1662 | 	(!p->cf->remote_range || ipa_in_netX(sk->daddr, p->cf->remote_range)) &&
1663 | 	(p->p.vrf == sk->vrf) &&
1664 | 	(p->cf->local_port == sk->sport) &&
1665 | 	(!link || (p->cf->iface == sk->iface)) &&
1666 | 	(ipa_zero(p->cf->local_ip) || ipa_equal(p->cf->local_ip, sk->saddr)))
1667 |     {
1668 |       best = p;
1669 | 
1670 |       if (!bgp_is_dynamic(p))
1671 | 	break;
1672 |     }
1673 | 
1674 |   return best;
1675 | }
1676 | 
1677 | /**
1678 |  * bgp_incoming_connection - handle an incoming connection
1679 |  * @sk: TCP socket
1680 |  * @dummy: unused
1681 |  *
1682 |  * This function serves as a socket hook for accepting of new BGP
1683 |  * connections. It searches a BGP instance corresponding to the peer
1684 |  * which has connected and if such an instance exists, it creates a
1685 |  * &bgp_conn structure, attaches it to the instance and either sends
1686 |  * an Open message or (if there already is an active connection) it
1687 |  * closes the new connection by sending a Notification message.
1688 |  */
1689 | static int
1690 | bgp_incoming_connection(sock *sk, uint dummy UNUSED)
1691 | {
1692 |   struct bgp_proto *p;
1693 |   int acc, hops;
1694 | 
1695 |   DBG("BGP: Incoming connection from %I port %d\n", sk->daddr, sk->dport);
1696 |   p = bgp_find_proto(sk);
1697 |   if (!p)
1698 |   {
1699 |     log(L_WARN "BGP: Unexpected connect from unknown address %I%J (port %d)",
1700 | 	sk->daddr, ipa_is_link_local(sk->daddr) ? sk->iface : NULL, sk->dport);
1701 |     rfree(sk);
1702 |     return 0;
1703 |   }
1704 | 
1705 |   if ((p->p.proto_state != PS_DOWN) && !EMPTY_LIST(p->ao.keys))
1706 |   {
1707 |     int current = -1, rnext = -1;
1708 |     sk_get_active_ao_keys(sk, &current, &rnext);
1709 | 
1710 |     if (current < 0)
1711 |     {
1712 |       log(L_WARN "%s: Connection from address %I%J (port %d) has no TCP-AO key",
1713 |           p->p.name, sk->daddr, ipa_is_link_local(sk->daddr) ? sk->iface : NULL, sk->dport);
1714 |       rfree(sk);
1715 |       return 0;
1716 |     }
1717 |   }
1718 | 
1719 |   /*
1720 |    * BIRD should keep multiple incoming connections in OpenSent state (for
1721 |    * details RFC 4271 8.2.1 par 3), but it keeps just one. Duplicate incoming
1722 |    * connections are rejected istead. The exception is the case where an
1723 |    * incoming connection triggers a graceful restart.
1724 |    */
1725 | 
1726 |   acc = (p->p.proto_state == PS_START || p->p.proto_state == PS_UP) &&
1727 |     (p->start_state >= BSS_CONNECT) && (!p->incoming_conn.sk);
1728 | 
1729 |   if (p->conn && (p->conn->state == BS_ESTABLISHED) && p->gr_ready)
1730 |   {
1731 |     bgp_store_error(p, NULL, BE_MISC, BEM_GRACEFUL_RESTART);
1732 |     bgp_handle_graceful_restart(p);
1733 |     bgp_conn_enter_idle_state(p->conn);
1734 |     acc = 1;
1735 | 
1736 |     /* There might be separate incoming connection in OpenSent state */
1737 |     if (p->incoming_conn.state > BS_ACTIVE)
1738 |       bgp_close_conn(&p->incoming_conn);
1739 |   }
1740 | 
1741 |   BGP_TRACE(D_EVENTS, "Incoming connection from %I%J (port %d) %s",
1742 | 	    sk->daddr, ipa_is_link_local(sk->daddr) ? sk->iface : NULL,
1743 | 	    sk->dport, acc ? "accepted" : "rejected");
1744 | 
1745 |   if (!acc)
1746 |   {
1747 |     rfree(sk);
1748 |     return 0;
1749 |   }
1750 | 
1751 |   hops = p->cf->multihop ?: 1;
1752 | 
1753 |   if (sk_set_ttl(sk, p->cf->ttl_security ? 255 : hops) < 0)
1754 |     goto err;
1755 | 
1756 |   if (p->cf->ttl_security)
1757 |     if (sk_set_min_ttl(sk, 256 - hops) < 0)
1758 |       goto err;
1759 | 
1760 |   if (!EMPTY_LIST(p->ao.keys))
1761 |   {
1762 |     const struct ao_key **ao_keys;
1763 |     int ao_keys_num;
1764 | 
1765 |     if (bgp_list_ao_keys(p, &ao_keys, &ao_keys_num) < 0)
1766 |       goto err2;
1767 | 
1768 |     if (sk_check_ao_keys(sk, ao_keys, ao_keys_num, p->p.name) < 0)
1769 |       goto err2;
1770 | 
1771 |     if (sk_set_rnext_ao_key(sk, ao_keys[0]) < 0)
1772 |       goto err;
1773 |   }
1774 | 
1775 |   if (p->cf->enable_extended_messages)
1776 |   {
1777 |     sk->rbsize = BGP_RX_BUFFER_EXT_SIZE;
1778 |     sk->tbsize = BGP_TX_BUFFER_EXT_SIZE;
1779 |     sk_reallocate(sk);
1780 |   }
1781 | 
1782 |   /* For dynamic BGP, spawn new instance and postpone the socket */
1783 |   if (bgp_is_dynamic(p))
1784 |   {
1785 |     p = bgp_spawn(p, sk->daddr);
1786 |     p->postponed_sk = sk;
1787 |     rmove(sk, p->p.pool);
1788 |     return 0;
1789 |   }
1790 | 
1791 |   rmove(sk, p->p.pool);
1792 |   bgp_setup_conn(p, &p->incoming_conn);
1793 |   bgp_setup_sk(&p->incoming_conn, sk);
1794 |   bgp_send_open(&p->incoming_conn);
1795 |   return 0;
1796 | 
1797 | err:
1798 |   sk_log_error(sk, p->p.name);
1799 | err2:
1800 |   log(L_ERR "%s: Incoming connection aborted", p->p.name);
1801 |   rfree(sk);
1802 |   return 0;
1803 | }
