1908 | static void
1909 | bgp_update_bfd(struct bgp_proto *p, const struct bfd_options *bfd)
1910 | {
1911 |   if (bfd && p->bfd_req)
1912 |     bfd_update_request(p->bfd_req, bfd);
1913 | 
1914 |   if (bfd && !p->bfd_req && !bgp_is_dynamic(p))
1915 |     p->bfd_req = bfd_request_session(p->p.pool, p->remote_ip, p->local_ip,
1916 | 				     p->cf->multihop ? NULL : p->neigh->iface,
1917 | 				     p->p.vrf, bgp_bfd_notify, p, bfd);
1918 | 
1919 |   if (!bfd && p->bfd_req)
1920 |   {
1921 |     rfree(p->bfd_req);
1922 |     p->bfd_req = NULL;
1923 |   }
1924 | }
