2013 | 
2014 | static void
2015 | bgp_start_locked(struct object_lock *lock)
2016 | {
2017 |   struct bgp_proto *p = lock->data;
2018 |   const struct bgp_config *cf = p->cf;
2019 | 
2020 |   if (p->p.proto_state != PS_START)
2021 |   {
2022 |     DBG("BGP: Got lock in different state %d\n", p->p.proto_state);
2023 |     return;
2024 |   }
2025 | 
2026 |   DBG("BGP: Got lock\n");
2027 | 
2028 |   if (cf->multihop || bgp_is_dynamic(p))
2029 |   {
2030 |     /* Multi-hop sessions do not use neighbor entries */
2031 |     bgp_initiate(p);
2032 |     return;
2033 |   }
2034 | 
2035 |   neighbor *n = neigh_find(&p->p, p->remote_ip, cf->iface, NEF_STICKY);
2036 |   if (!n)
2037 |   {
2038 |     log(L_ERR "%s: Invalid remote address %I%J", p->p.name, p->remote_ip, cf->iface);
2039 |     /* As we do not start yet, we can just disable protocol */
2040 |     p->p.disabled = 1;
2041 |     bgp_store_error(p, NULL, BE_MISC, BEM_INVALID_NEXT_HOP);
2042 |     proto_notify_state(&p->p, PS_DOWN);
2043 |     return;
2044 |   }
2045 | 
2046 |   p->neigh = n;
2047 | 
2048 |   if (n->scope <= 0)
2049 |     BGP_TRACE(D_EVENTS, "Waiting for %I%J to become my neighbor", p->remote_ip, cf->iface);
2050 |   else if (p->cf->check_link && !(n->iface->flags & IF_LINK_UP))
2051 |     BGP_TRACE(D_EVENTS, "Waiting for link on %s", n->iface->name);
2052 |   else
2053 |     bgp_start_neighbor(p);
2054 | }
