2062 |   p->local_ip = cf->local_ip;
2063 |   p->local_as = cf->local_as;
2064 |   p->remote_as = cf->remote_as;
2065 |   p->public_as = cf->local_as;
2066 | 
2067 |   /* For dynamic BGP childs, remote_ip is already set */
2068 |   if (ipa_nonzero(cf->remote_ip))
2069 |     p->remote_ip = cf->remote_ip;
2070 | 
2071 |   /* Confederation ID is used for truly external peers */
2072 |   if (p->cf->confederation && !p->is_interior)
2073 |     p->public_as = cf->confederation;
2074 | 
2075 |   p->passive = cf->passive || bgp_is_dynamic(p);
2076 | 
2077 |   p->start_state = BSS_PREPARE;
2078 |   p->outgoing_conn.state = BS_IDLE;
2079 |   p->incoming_conn.state = BS_IDLE;
2080 |   p->neigh = NULL;
2081 |   p->bfd_req = NULL;
2082 |   p->postponed_sk = NULL;
2083 |   p->gr_ready = 0;
2084 |   p->gr_active_num = 0;
2085 | 
2086 |   /* Reset some stats */
2087 |   p->stats.rx_messages = p->stats.tx_messages = 0;
2088 |   p->stats.rx_updates = p->stats.tx_updates = 0;
2089 |   p->stats.rx_bytes = p->stats.tx_bytes = 0;
2090 |   p->last_rx_update = 0;
2091 | 
2092 |   p->event = ev_new_init(p->p.pool, bgp_decision, p);
2093 |   p->startup_timer = tm_new_init(p->p.pool, bgp_startup_timeout, p, 0, 0);
2094 |   p->gr_timer = tm_new_init(p->p.pool, bgp_graceful_restart_timeout, p, 0, 0);
2095 | 
2096 |   p->hostname = proto_get_hostname(P->cf);
2097 | 
2098 |   p->local_id = proto_get_router_id(P->cf);
2099 |   if (p->rr_client)
2100 |     p->rr_cluster_id = p->cf->rr_cluster_id ? p->cf->rr_cluster_id : p->local_id;
2101 | 
2102 |   p->remote_id = 0;
2103 |   p->link_addr = IPA_NONE;
2104 | 
2105 |   /* Initialize TCP-AO keys */
2106 |   init_list(&p->ao.keys);
2107 |   if (cf->auth_type == BGP_AUTH_AO)
2108 |     for (struct ao_config *key_cf = cf->ao_keys; key_cf; key_cf = key_cf->next)
2109 |       bgp_new_ao_key(p, key_cf);
2110 | 
2111 |   proto_setup_mpls_map(P, RTS_BGP, 1);
2112 | 
2113 |   /* Lock all channels when in GR recovery mode */
2114 |   if (p->p.gr_recovery && p->cf->gr_mode)
2115 |   {
2116 |     struct bgp_channel *c;
2117 |     BGP_WALK_CHANNELS(p, c)
2118 |       channel_graceful_restart_lock(&c->c);
2119 |   }
2120 | 
2121 |   /*
2122 |    * Before attempting to create the connection, we need to lock the port,
2123 |    * so that we are the only instance attempting to talk with that neighbor.
2124 |    */
2125 |   struct object_lock *lock;
2126 |   lock = p->lock = olock_new(P->pool);
2127 |   lock->addr = p->remote_ip;
2128 |   lock->addr_local = p->cf->local_ip;
2129 |   lock->port = p->cf->remote_port;
2130 |   lock->iface = p->cf->iface;
2131 |   lock->vrf = p->cf->iface ? NULL : p->p.vrf;
2132 |   lock->type = OBJLOCK_TCP;
2133 |   lock->hook = bgp_start_locked;
2134 |   lock->data = p;
2135 | 
2136 |   /* For dynamic BGP, we use inst 1 to avoid collisions with regular BGP */
2137 |   if (bgp_is_dynamic(p))
2138 |   {
2139 |     lock->addr = net_prefix(p->cf->remote_range);
2140 |     lock->inst = 1;
2141 |   }
2142 | 
2143 |   olock_acquire(lock);
2144 | 
2145 |   return PS_START;
2146 | }
