2636 | 	cc->c.out_filter = FILTER_REJECT;
2637 |       else
2638 | 	cf_error("EBGP requires explicit export policy");
2639 | 
2640 |     /* Disable after error incompatible with restart limit action */
2641 |     if ((cc->c.in_limit.action == PLA_RESTART) && cf->disable_after_error)
2642 |       cc->c.in_limit.action = PLA_DISABLE;
2643 | 
2644 |     /* Different default based on rr_client, rs_client */
2645 |     if (cc->next_hop_keep == 0xff)
