2801 | static int
2802 | bgp_channel_reconfigure(struct channel *C, struct channel_config *CC, int *import_changed, int *export_changed)
2803 | {
2804 |   struct bgp_proto *p = (void *) C->proto;
2805 |   struct bgp_channel *c = (void *) C;
2806 |   struct bgp_channel_config *new = (void *) CC;
2807 |   struct bgp_channel_config *old = c->cf;
2808 | 
2809 |   if ((new->secondary != old->secondary) ||
2810 |       (new->validate != old->validate) ||
2811 |       (new->gr_able != old->gr_able) ||
2812 |       (new->llgr_able != old->llgr_able) ||
2813 |       (new->llgr_time != old->llgr_time) ||
2814 |       (new->ext_next_hop != old->ext_next_hop) ||
2815 |       (new->add_path != old->add_path) ||
2816 |       (new->import_table != old->import_table) ||
2817 |       (new->export_table != old->export_table) ||
2818 |       (TABLE(new, igp_table_ip4) != TABLE(old, igp_table_ip4)) ||
2819 |       (TABLE(new, igp_table_ip6) != TABLE(old, igp_table_ip6)) ||
2820 |       (TABLE(new, base_table) != TABLE(old, base_table)))
2821 |     return 0;
2822 | 
2823 |   if (c->stale_time && ((new->min_llgr_time > c->stale_time) ||
2824 | 			(new->max_llgr_time < c->stale_time)))
2825 |     return 0;
2826 | 
2827 |   if (new->mandatory && !old->mandatory && (C->channel_state != CS_UP))
2828 |     return 0;
2829 | 
2830 |   if ((new->gw_mode != old->gw_mode) ||
2831 |       (new->next_hop_prefer != old->next_hop_prefer) ||
2832 |       (new->aigp != old->aigp) ||
2833 |       (new->cost != old->cost))
2834 |   {
2835 |     /* import_changed itself does not force ROUTE_REFRESH when import_table is active */
2836 |     if (c->c.in_table && (c->c.channel_state == CS_UP))
2837 |       bgp_schedule_packet(p->conn, c, PKT_ROUTE_REFRESH);
2838 | 
2839 |     *import_changed = 1;
2840 |   }
2841 | 
2842 |   if (!ipa_equal(new->next_hop_addr, old->next_hop_addr) ||
2843 |       (new->next_hop_self != old->next_hop_self) ||
2844 |       (new->next_hop_keep != old->next_hop_keep) ||
2845 |       (new->llnh_format != old->llnh_format) ||
2846 |       (new->aigp != old->aigp) ||
2847 |       (new->aigp_originate != old->aigp_originate))
2848 |     *export_changed = 1;
2849 | 
2850 |   c->cf = new;
2851 |   return 1;
2852 | }
