2941 | static const char *
2942 | bgp_last_errmsg(struct bgp_proto *p)
2943 | {
2944 |   switch (p->last_error_class)
2945 |   {
2946 |   case BE_MISC:
2947 |     return bgp_misc_errors[p->last_error_code];
2948 |   case BE_SOCKET:
2949 |     return (p->last_error_code == 0) ? "Connection closed" : strerror(p->last_error_code);
2950 |   case BE_BGP_RX:
2951 |   case BE_BGP_TX:
2952 |     return bgp_error_dsc(p->last_error_code >> 16, p->last_error_code & 0xFF);
2953 |   case BE_AUTO_DOWN:
2954 |     return bgp_auto_errors[p->last_error_code];
2955 |   default:
2956 |     return "";
2957 |   }
2958 | }
