2960 | static const char *
2961 | bgp_state_dsc(struct bgp_proto *p)
2962 | {
2963 |   if (p->p.proto_state == PS_DOWN)
2964 |     return "Down";
2965 | 
2966 |   int state = MAX(p->incoming_conn.state, p->outgoing_conn.state);
2967 |   if ((state == BS_IDLE) && (p->start_state >= BSS_CONNECT) && p->passive)
2968 |     return "Passive";
2969 | 
2970 |   return bgp_state_names[state];
2971 | }
