2973 | static void
2974 | bgp_get_status(struct proto *P, byte *buf)
2975 | {
2976 |   struct bgp_proto *p = (struct bgp_proto *) P;
2977 | 
2978 |   const char *err1 = bgp_err_classes[p->last_error_class];
2979 |   const char *err2 = bgp_last_errmsg(p);
2980 | 
2981 |   if (P->proto_state == PS_DOWN)
2982 |     bsprintf(buf, "%s%s", err1, err2);
2983 |   else
2984 |     bsprintf(buf, "%-14s%s%s", bgp_state_dsc(p), err1, err2);
