3044 | 
3045 |     afn1 = 0;
3046 |     WALK_AF_CAPS(caps, ac)
3047 |       if (ac->ready)
3048 | 	afl1[afn1++] = ac->afi;
3049 | 
3050 |     bgp_show_afis(-1006, "        AF announced:", afl1, afn1);
3051 |   }
3052 | 
3053 |   if (caps->route_refresh)
3054 |     cli_msg(-1006, "      Route refresh");
3055 | 
3056 |   if (any_ext_next_hop)
3057 |   {
3058 |     cli_msg(-1006, "      Extended next hop");
3059 | 
3060 |     afn1 = 0;
3061 |     WALK_AF_CAPS(caps, ac)
3062 |       if (ac->ext_next_hop)
3063 | 	afl1[afn1++] = ac->afi;
3064 | 
3065 |     bgp_show_afis(-1006, "        IPv6 nexthop:", afl1, afn1);
3066 |   }
3067 | 
3068 |   if (caps->ext_messages)
3069 |     cli_msg(-1006, "      Extended message");
3070 | 
3071 |   if (caps->gr_aware)
3072 |     cli_msg(-1006, "      Graceful restart");
3073 | 
3074 |   if (any_gr_able)
3075 |   {
3076 |     /* Continues from gr_aware */
