3078 |     if (caps->gr_flags & BGP_GRF_RESTART)
3079 |       cli_msg(-1006, "        Restart recovery");
3080 | 
3081 |     afn1 = afn2 = 0;
3082 |     WALK_AF_CAPS(caps, ac)
3083 |     {
3084 |       if (ac->gr_able)
3085 | 	afl1[afn1++] = ac->afi;
3086 | 
3087 |       if (ac->gr_af_flags & BGP_GRF_FORWARDING)
3088 | 	afl2[afn2++] = ac->afi;
3089 |     }
3090 | 
3091 |     bgp_show_afis(-1006, "        AF supported:", afl1, afn1);
3092 |     bgp_show_afis(-1006, "        AF preserved:", afl2, afn2);
3093 |   }
3094 | 
3095 |   if (caps->as4_support)
3096 |     cli_msg(-1006, "      4-octet AS numbers");
3097 | 
3098 |   if (any_add_path)
3099 |   {
3100 |     cli_msg(-1006, "      ADD-PATH");
3101 | 
3102 |     afn1 = afn2 = 0;
3103 |     WALK_AF_CAPS(caps, ac)
3104 |     {
3105 |       if (ac->add_path & BGP_ADD_PATH_RX)
3106 | 	afl1[afn1++] = ac->afi;
3107 | 
3108 |       if (ac->add_path & BGP_ADD_PATH_TX)
3109 | 	afl2[afn2++] = ac->afi;
3110 |     }
3111 | 
3112 |     bgp_show_afis(-1006, "        RX:", afl1, afn1);
3113 |     bgp_show_afis(-1006, "        TX:", afl2, afn2);
3114 |   }
3115 | 
3116 |   if (caps->enhanced_refresh)
3117 |     cli_msg(-1006, "      Enhanced refresh");
3118 | 
3119 |   if (caps->llgr_aware)
3120 |     cli_msg(-1006, "      Long-lived graceful restart");
3121 | 
3122 |   if (any_llgr_able)
3123 |   {
3124 |     u32 stale_time = 0;
3125 | 
3126 |     afn1 = afn2 = 0;
3127 |     WALK_AF_CAPS(caps, ac)
3128 |     {
3129 |       stale_time = MAX(stale_time, ac->llgr_time);
3130 | 
3131 |       if (ac->llgr_able && ac->llgr_time)
3132 | 	afl1[afn1++] = ac->afi;
3133 | 
3134 |       if (ac->llgr_flags & BGP_GRF_FORWARDING)
3135 | 	afl2[afn2++] = ac->afi;
3136 |     }
3137 | 
3138 |     /* Continues from llgr_aware */
3139 |     cli_msg(-1006, "        LL stale time: %u", stale_time);
3140 | 
3141 |     bgp_show_afis(-1006, "        AF supported:", afl1, afn1);
3142 |     bgp_show_afis(-1006, "        AF preserved:", afl2, afn2);
3143 |   }
3144 | 
3145 |   if (caps->hostname)
3146 |     cli_msg(-1006, "      Hostname: %s", caps->hostname);
3147 | 
3148 |   if (caps->role != BGP_ROLE_UNDEFINED)
3149 |     cli_msg(-1006, "      Role: %s", bgp_format_role_name(caps->role));
3150 | }
