 267 | static int
 268 | bgp_same_ao_key(struct ao_key *a, struct ao_key *b)
 269 | {
 270 |   return
 271 |     (a->send_id == b->send_id) &&
 272 |     (a->recv_id == b->recv_id) &&
 273 |     (a->algorithm == b->algorithm) &&
 274 |     (a->keylen == b->keylen) &&
 275 |     !memcmp(a->key, b->key, a->keylen);
 276 | }
