 394 | static int
 395 | bgp_remove_ao_key(struct bgp_proto *p, struct bgp_ao_key *key, struct bgp_active_keys *info)
 396 | {
 397 |   ASSERT(key != p->ao.best_key);
 398 | 
 399 |   if (key->active)
 400 |     if (bgp_disable_ao_key(p, key, info) < 0)
 401 |       return -1;
 402 | 
 403 |   rem_node(&key->n);
 404 |   mb_free(key);
 405 |   return 0;
 406 | }
