 430 | static int
 431 | bgp_sk_set_rnext_ao_key(struct bgp_proto *p, sock *sk, struct bgp_ao_key *key)
 432 | {
 433 |   int rv = sk_set_rnext_ao_key(sk, &key->key);
 434 |   if (rv < 0)
 435 |   {
 436 |     sk_log_error(sk, p->p.name);
 437 |     log(L_ERR "%s: Cannot set TCP-AO key %d/%d as RNext key",
 438 | 	p->p.name, key->key.send_id, key->key.recv_id);
 439 |   }
 440 | 
 441 |   return rv;
 442 | }
 443 | 
 444 | static int
 445 | bgp_update_rnext_ao_key(struct bgp_proto *p)
 446 | {
 447 |   struct bgp_ao_key *best = bgp_select_best_ao_key(p);
 448 | 
 449 |   if (!best)
 450 |   {
 451 |     log(L_ERR "%s: No usable TCP-AO key", p->p.name);
 452 |     return -1;
 453 |   }
 454 | 
 455 |   if (best == p->ao.best_key)
 456 |     return 0;
 457 | 
 458 |   BGP_TRACE(D_EVENTS, "Setting TCP-AO key %d/%d as RNext key", best->key.send_id, best->key.recv_id);
 459 | 
 460 |   p->ao.best_key = best;
 461 | 
 462 |   /* Handle incoming socket */
 463 |   if (p->incoming_conn.sk)
 464 |     if (bgp_sk_set_rnext_ao_key(p, p->incoming_conn.sk, best) < 0)
 465 |       return -1;
 466 | 
 467 |   /* Handle outgoing socket */
 468 |   if (p->outgoing_conn.sk)
 469 |     if (bgp_sk_set_rnext_ao_key(p, p->outgoing_conn.sk, best) < 0)
 470 |       return -1;
 471 | 
 472 |   /* Schedule Keepalive to trigger RNext ID exchange */
 473 |   if (p->conn)
 474 |     bgp_schedule_packet(p->conn, NULL, PKT_KEEPALIVE);
 475 | 
 476 |   /* RFC 4271 4.4 says that Keepalive messages MUST NOT be sent more frequently
 477 |      than one per second, but since key change is rare, this is harmless. */
 478 | 
 479 |   return 0;
 480 | }
