 483 | /**
 484 |  * bgp_enable_ao_keys - Enable TCP-AO keys
 485 |  * @p: BGP instance
 486 |  *
 487 |  * Enable all TCP-AO keys for the listening socket. We accept if some fail in
 488 |  * non-fatal way (e.g. kernel does not support specific algorithm), but there
 489 |  * must be at least one usable (non-deprecated) active key. In case of failure,
 490 |  * we remove all keys, so there is no lasting effect on the listening socket.
 491 |  * Returns: 0 for okay, -1 for failure.
 492 |  */
 493 | static int
 494 | bgp_enable_ao_keys(struct bgp_proto *p)
 495 | {
 496 |   ASSERT(!p->incoming_conn.sk && !p->outgoing_conn.sk);
 497 | 
 498 |   WALK_LIST_(struct bgp_ao_key, key, p->ao.keys)
 499 |     if (bgp_enable_ao_key(p, key) < 0)
 500 |       goto fail;
 501 | 
 502 |   p->ao.best_key = bgp_select_best_ao_key(p);
 503 | 
 504 |   if (!p->ao.best_key)
 505 |   {
 506 |     log(L_ERR "%s: No usable TCP-AO key", p->p.name);
 507 |     goto fail;
 508 |   }
 509 | 
 510 |   return 0;
 511 | 
 512 | fail:
 513 |   bgp_disable_ao_keys(p);
 514 |   return -1;
 515 | }
 516 | 
 517 | /**
 518 |  * bgp_disable_ao_keys - Disable TCP-AO keys
 519 |  * @p: BGP instance
 520 |  *
 521 |  * Disable all TCP-AO keys for the listening socket. We assume there are no
 522 |  * active connection, so no issue with removal of the current key. Errors are
 523 |  * ignored.
 524 |  */
 525 | static int
 526 | bgp_disable_ao_keys(struct bgp_proto *p)
 527 | {
 528 |   ASSERT(!p->incoming_conn.sk && !p->outgoing_conn.sk);
 529 | 
 530 |   WALK_LIST_(struct bgp_ao_key, key, p->ao.keys)
 531 |     if (key->active)
 532 |       bgp_disable_ao_key(p, key, NULL);
 533 | 
 534 |   return 0;
 535 | }
 536 | 
 537 | static int
 538 | bgp_reconfigure_ao_keys(struct bgp_proto *p, const struct bgp_config *cf)
 539 | {
 540 |   /* TCP-AO not used */
 541 |   if (EMPTY_LIST(p->ao.keys) && !cf->ao_keys)
 542 |     return 1;
 543 | 
 544 |   /* Cannot enable/disable TCP-AO */
 545 |   if (EMPTY_LIST(p->ao.keys) || !cf->ao_keys)
 546 |     return 0;
 547 | 
 548 |   /* Too early, TCP-AO not yet enabled */
 549 |   if (p->start_state == BSS_PREPARE)
 550 |     return 0;
 551 | 
 552 |   /* Move existing keys to temporary list */
 553 |   list old_keys;
 554 |   init_list(&old_keys);
 555 |   add_tail_list(&old_keys, &p->ao.keys);
 556 |   init_list(&p->ao.keys);
 557 | 
 558 |   /* Clean up the best key */
 559 |   struct bgp_ao_key *old_best = p->ao.best_key;
 560 |   p->ao.best_key = NULL;
 561 | 
 562 |   /* Prepare new set of keys */
 563 |   for (struct ao_config *key_cf = cf->ao_keys; key_cf; key_cf = key_cf->next)
 564 |   {
 565 |     struct bgp_ao_key *key = bgp_find_ao_key_(&old_keys, key_cf->key.send_id, key_cf->key.recv_id);
 566 | 
 567 |     if (key && bgp_same_ao_key(&key->key, &key_cf->key))
 568 |     {
 569 |       /* Update key ptr and preference */
 570 |       key->key = key_cf->key;
 571 | 
 572 |       rem_node(&key->n);
 573 |       add_tail(&p->ao.keys, &key->n);
 574 | 
 575 |       if (key == old_best)
 576 | 	p->ao.best_key = key;
 577 | 
 578 |       continue;
 579 |     }
 580 | 
 581 |     bgp_new_ao_key(p, key_cf);
 582 |   }
 583 | 
 584 |   /* Remove old keys */
 585 |   if (!EMPTY_LIST(old_keys))
 586 |   {
 587 |     struct bgp_active_keys info = { -1, -1, -1, -1, NULL};
 588 | 
 589 |     /* Find current/rnext keys on incoming connection */
 590 |     if (p->incoming_conn.sk)
 591 |       if (sk_get_active_ao_keys(p->incoming_conn.sk, &info.in_current, &info.in_rnext) < -1)
 592 | 	sk_log_error(p->incoming_conn.sk, p->p.name);
 593 | 
 594 |     /* Find current/rnext keys on outgoing connection */
 595 |     if (p->outgoing_conn.sk)
 596 |       if (sk_get_active_ao_keys(p->outgoing_conn.sk, &info.out_current, &info.out_rnext) < -1)
 597 | 	sk_log_error(p->outgoing_conn.sk, p->p.name);
 598 | 
 599 |     /*
 600 |      * Select backup key in case of removal of current/rnext key.
 601 |      *
 602 |      * It is possible that we cannot select an intermediate best key (e.g. when
 603 |      * the reconfiguration deprecates the old best key and adds the new one).
 604 |      * That is not necessary bad, we may not even need the backup key anyways.
 605 |      * In this case we use the old best key (ao.best_key) instead even if it may
 606 |      * be deprecated (but not removed).
 607 |      *
 608 |      * If neither one is available, that means we are going to remove rnext key
 609 |      * and we have no intermediate best key to switch to, therefore we fail
 610 |      * later during bgp_remove_ao_key().
 611 |      */
 612 |     info.backup = bgp_select_best_ao_key(p) ?: p->ao.best_key;
 613 |     if (!info.backup)
 614 |       log(L_WARN "%s: No usable backup key", p->p.name);
 615 | 
 616 |     struct bgp_ao_key *key, *key2;
 617 |     WALK_LIST_DELSAFE(key, key2, old_keys)
 618 |       bgp_remove_ao_key(p, key, &info);
 619 | 
 620 |     /* If some key removals failed */
 621 |     if (!EMPTY_LIST(old_keys))
 622 |       return 0;
 623 |   }
 624 | 
 625 |   /* Enable new keys */
 626 |   WALK_LIST_(struct bgp_ao_key, key, p->ao.keys)
 627 |     if (!key->active && !key->failed)
 628 |       if (bgp_enable_ao_key(p, key) < 0)
 629 | 	return 0;
 630 | 
 631 |   /* Update RNext key */
 632 |   if (bgp_update_rnext_ao_key(p) < 0)
 633 |     return 0;
 634 | 
 635 |   return 1;
 636 | }
 637 | 
 638 | /**
 639 |  * bgp_list_ao_keys - List active TCP-AO keys
 640 |  * @p: BGP instance
 641 |  * @ao_keys: Returns array of keys
 642 |  * @ao_keys_num: Returns number of keys
 643 |  *
 644 |  * Returns an array of pointers to active TCP-AO keys, for usage with socket
 645 |  * functions. The best key is at the first position. The array is allocated from
 646 |  * the temporary linpool. If there are no keys (or just no best key), the error
 647 |  * is logged and the function fails. Returns: 0 for success, -1 for failure.
 648 |  */
 649 | static int
 650 | bgp_list_ao_keys(struct bgp_proto *p, const struct ao_key ***ao_keys, int *ao_keys_num)
 651 | {
 652 |   int num = 0;
 653 |   WALK_LIST_(const struct bgp_ao_key, key, p->ao.keys)
 654 |     if (key->active)
 655 |       num++;
 656 | 
 657 |   const struct bgp_ao_key *best = p->ao.best_key;
 658 | 
 659 |   if (!num || !best)
 660 |   {
 661 |     log(L_ERR "%s: No usable TCP-AO key", p->p.name);
 662 |     return -1;
 663 |   }
 664 | 
 665 |   const struct ao_key **keys = tmp_alloc(num * sizeof(const struct ao_key *));
 666 |   int i = 0;
 667 | 
 668 |   keys[i++] = &best->key;
 669 |   WALK_LIST_(const struct bgp_ao_key, key, p->ao.keys)
 670 |     if (key->active && (key != best) && (i < num))
 671 |       keys[i++] = &key->key;
 672 | 
 673 |   *ao_keys = keys;
 674 |   *ao_keys_num = i;
 675 |   return 0;
 676 | }
