 681 | static int
 682 | bgp_setup_auth(struct bgp_proto *p, int enable)
 683 | {
 684 |   if (p->cf->auth_type == BGP_AUTH_AO)
 685 |   {
 686 |     if (enable)
 687 |       return bgp_enable_ao_keys(p);
 688 |     else
 689 |       return bgp_disable_ao_keys(p);
 690 |   }
 691 | 
 692 |   if (p->cf->auth_type == BGP_AUTH_MD5)
 693 |   {
 694 |     ip_addr prefix = p->cf->remote_ip;
 695 |     int pxlen = -1;
 696 | 
 697 |     if (p->cf->remote_range)
 698 |     {
 699 |       prefix = net_prefix(p->cf->remote_range);
 700 |       pxlen = net_pxlen(p->cf->remote_range);
 701 |     }
 702 | 
 703 |     int rv = sk_set_md5_auth(p->sock->sk,
 704 | 			     p->cf->local_ip, prefix, pxlen, p->cf->iface,
 705 | 			     enable ? p->cf->password : NULL, p->cf->setkey);
 706 | 
 707 |     if (rv < 0)
 708 |       sk_log_error(p->sock->sk, p->p.name);
 709 | 
 710 |     return rv;
 711 |   }
 712 | 
 713 |   return 0;
 714 | }
