 727 | static void
 728 | bgp_startup(struct bgp_proto *p)
 729 | {
 730 |   BGP_TRACE(D_EVENTS, "Started");
 731 |   p->start_state = BSS_CONNECT;
 732 | 
 733 |   if (!p->passive)
 734 |     bgp_active(p);
 735 | 
 736 |   if (p->postponed_sk)
 737 |   {
 738 |     /* Apply postponed incoming connection */
 739 |     bgp_setup_conn(p, &p->incoming_conn);
 740 |     bgp_setup_sk(&p->incoming_conn, p->postponed_sk);
 741 |     bgp_send_open(&p->incoming_conn);
 742 |     p->postponed_sk = NULL;
 743 |   }
 744 | }
