 790 | /**
 791 |  * bgp_start_timer - start a BGP timer
 792 |  * @t: timer
 793 |  * @value: time (in seconds) to fire (0 to disable the timer)
 794 |  *
 795 |  * This functions calls tm_start() on @t with time @value and the amount of
 796 |  * randomization suggested by the BGP standard. Please use it for all BGP
 797 |  * timers.
 798 |  */
 799 | void
 800 | bgp_start_timer(timer *t, uint value)
 801 | {
 802 |   if (value)
 803 |   {
 804 |     /* The randomization procedure is specified in RFC 4271 section 10 */
 805 |     btime time = value S;
 806 |     btime randomize = random() % ((time / 4) + 1);
 807 |     tm_start(t, time - randomize);
 808 |   }
 809 |   else
 810 |     tm_stop(t);
 811 | }
