 858 | /**
 859 |  * bgp_update_startup_delay - update a startup delay
 860 |  * @p: BGP instance
 861 |  *
 862 |  * This function updates a startup delay that is used to postpone next BGP
 863 |  * connect. It also handles disable_after_error and might stop BGP instance
 864 |  * when error happened and disable_after_error is on.
 865 |  *
 866 |  * It should be called when BGP protocol error happened.
 867 |  */
 868 | void
 869 | bgp_update_startup_delay(struct bgp_proto *p)
 870 | {
 871 |   const struct bgp_config *cf = p->cf;
 872 | 
 873 |   DBG("BGP: Updating startup delay\n");
 874 | 
 875 |   if (p->last_proto_error && ((current_time() - p->last_proto_error) >= cf->error_amnesia_time S))
 876 |     p->startup_delay = 0;
 877 | 
 878 |   p->last_proto_error = current_time();
 879 | 
 880 |   if (cf->disable_after_error)
 881 |   {
 882 |     p->startup_delay = 0;
 883 |     p->p.disabled = 1;
 884 |     return;
 885 |   }
 886 | 
 887 |   if (!p->startup_delay)
 888 |     p->startup_delay = cf->error_delay_time_min;
 889 |   else
 890 |     p->startup_delay = MIN(2 * p->startup_delay, cf->error_delay_time_max);
 891 | }
