1007 | void
1008 | bgp_conn_enter_established_state(struct bgp_conn *conn)
1009 | {
1010 |   struct bgp_proto *p = conn->bgp;
1011 |   struct bgp_caps *local = conn->local_caps;
1012 |   struct bgp_caps *peer = conn->remote_caps;
1013 |   struct bgp_channel *c;
1014 | 
1015 |   BGP_TRACE(D_EVENTS, "BGP session established");
1016 |   p->last_established = current_time();
1017 |   p->stats.fsm_established_transitions++;
1018 | 
1019 |   /* For multi-hop BGP sessions */
1020 |   if (ipa_zero(p->local_ip))
1021 |     p->local_ip = conn->sk->saddr;
1022 | 
1023 |   /* For promiscuous sessions */
1024 |   if (!p->remote_as)
1025 |     p->remote_as = conn->received_as;
1026 | 
1027 |   /* In case of LLv6 is not valid during BGP start */
1028 |   if (ipa_zero(p->link_addr) && p->neigh && p->neigh->iface && p->neigh->iface->llv6)
1029 |     p->link_addr = p->neigh->iface->llv6->ip;
1030 | 
1031 |   conn->sk->fast_rx = 0;
1032 | 
1033 |   p->conn = conn;
1034 |   p->last_error_class = 0;
1035 |   p->last_error_code = 0;
1036 | 
1037 |   p->as4_session = conn->as4_session;
1038 | 
1039 |   p->route_refresh = peer->route_refresh;
1040 |   p->enhanced_refresh = local->enhanced_refresh && peer->enhanced_refresh;
1041 | 
1042 |   /* Whether we may handle possible GR/LLGR of peer (it has some AF GR-able) */
1043 |   p->gr_ready = p->llgr_ready = 0;	/* Updated later */
1044 | 
1045 |   /* Whether peer is ready to handle our GR recovery */
1046 |   int peer_gr_ready = peer->gr_aware && !(peer->gr_flags & BGP_GRF_RESTART);
1047 | 
1048 |   if (p->gr_active_num)
1049 |     tm_stop(p->gr_timer);
1050 | 
1051 |   /* Number of active channels */
1052 |   int num = 0;
1053 | 
1054 |   /* Summary state of ADD_PATH RX for active channels */
1055 |   uint summary_add_path_rx = 0;
1056 | 
1057 |   BGP_WALK_CHANNELS(p, c)
1058 |   {
1059 |     const struct bgp_af_caps *loc = bgp_find_af_caps(local, c->afi);
1060 |     const struct bgp_af_caps *rem = bgp_find_af_caps(peer,  c->afi);
1061 | 
1062 |     int active = loc->ready && rem->ready;
1063 |     c->c.disabled = !active;
1064 |     c->c.reloadable = p->route_refresh || c->cf->import_table;
1065 | 
1066 |     c->index = active ? num++ : 0;
1067 | 
1068 |     c->feed_state = BFS_NONE;
1069 |     c->load_state = BFS_NONE;
1070 | 
1071 |     /* Channels where peer may do GR */
1072 |     uint gr_ready = active && local->gr_aware && rem->gr_able;
1073 |     uint llgr_ready = active && local->llgr_aware && rem->llgr_able;
1074 | 
1075 |     c->gr_ready = gr_ready || llgr_ready;
1076 |     p->gr_ready = p->gr_ready || c->gr_ready;
1077 |     p->llgr_ready = p->llgr_ready || llgr_ready;
1078 | 
1079 |     /* Remember last LLGR stale time */
1080 |     c->stale_time = local->llgr_aware ?
1081 |       CLAMP(rem->llgr_time, c->cf->min_llgr_time, c->cf->max_llgr_time) : 0;
1082 | 
1083 |     /* Channels not able to recover gracefully */
1084 |     if (p->p.gr_recovery && (!active || !peer_gr_ready))
1085 |       channel_graceful_restart_unlock(&c->c);
1086 | 
1087 |     /* Channels waiting for local convergence */
1088 |     if (p->p.gr_recovery && loc->gr_able && peer_gr_ready)
1089 |       c->c.gr_wait = 1;
1090 | 
1091 |     /* Channels where regular graceful restart failed */
1092 |     if ((c->gr_active == BGP_GRS_ACTIVE) &&
1093 | 	!(active && rem->gr_able && (rem->gr_af_flags & BGP_GRF_FORWARDING)))
1094 |       bgp_graceful_restart_done(c);
1095 | 
1096 |     /* Channels where regular long-lived restart failed */
1097 |     if ((c->gr_active == BGP_GRS_LLGR) &&
1098 | 	!(active && rem->llgr_able && (rem->gr_af_flags & BGP_LLGRF_FORWARDING)))
1099 |       bgp_graceful_restart_done(c);
1100 | 
1101 |     /* GR capability implies that neighbor will send End-of-RIB */
1102 |     if (peer->gr_aware)
1103 |       c->load_state = BFS_LOADING;
1104 | 
1105 |     c->ext_next_hop = c->cf->ext_next_hop && (bgp_channel_is_ipv6(c) || rem->ext_next_hop);
1106 |     c->add_path_rx = (loc->add_path & BGP_ADD_PATH_RX) && (rem->add_path & BGP_ADD_PATH_TX);
1107 |     c->add_path_tx = (loc->add_path & BGP_ADD_PATH_TX) && (rem->add_path & BGP_ADD_PATH_RX);
1108 | 
1109 |     if (active)
1110 |       summary_add_path_rx |= !c->add_path_rx ? 1 : 2;
1111 | 
1112 |     /* Update RA mode */
1113 |     if (c->add_path_tx)
1114 |       c->c.ra_mode = RA_ANY;
1115 |     else if (c->cf->secondary)
1116 |       c->c.ra_mode = RA_ACCEPTED;
1117 |     else
1118 |       c->c.ra_mode = RA_OPTIMAL;
1119 |   }
1120 | 
1121 |   p->afi_map = mb_alloc(p->p.pool, num * sizeof(u32));
1122 |   p->channel_map = mb_alloc(p->p.pool, num * sizeof(void *));
1123 |   p->channel_count = num;
1124 |   p->summary_add_path_rx = summary_add_path_rx;
1125 | 
1126 |   BGP_WALK_CHANNELS(p, c)
1127 |   {
1128 |     if (c->c.disabled)
1129 |       continue;
1130 | 
1131 |     p->afi_map[c->index] = c->afi;
1132 |     p->channel_map[c->index] = c;
1133 |   }
1134 | 
1135 |   /* Breaking rx_hook for simulating receive problem */
1136 |   if (p->cf->disable_rx)
1137 |   {
1138 |     conn->sk->rx_hook = NULL;
1139 |     tm_stop(conn->hold_timer);
1140 |   }
1141 | 
1142 |   /* proto_notify_state() will likely call bgp_feed_begin(), setting c->feed_state */
1143 | 
1144 |   bgp_conn_set_state(conn, BS_ESTABLISHED);
1145 |   proto_notify_state(&p->p, PS_UP);
1146 |   bmp_peer_up(p, conn->local_open_msg, conn->local_open_length,
1147 | 	      conn->remote_open_msg, conn->remote_open_length);
1148 | }
