1187 | 
1188 |   bgp_close_conn(conn);
1189 |   bgp_conn_set_state(conn, BS_IDLE);
1190 |   ev_schedule(p->event);
1191 | 
1192 |   if (os == BS_ESTABLISHED)
1193 |     bgp_conn_leave_established_state(conn, p);
