1444 | static void
1445 | bgp_sock_err(sock *sk, int err)
1446 | {
1447 |   struct bgp_conn *conn = sk->data;
1448 |   struct bgp_proto *p = conn->bgp;
1449 | 
1450 |   /*
1451 |    * This error hook may be called either asynchronously from main
1452 |    * loop, or synchronously from sk_send().  But sk_send() is called
1453 |    * only from bgp_tx() and bgp_kick_tx(), which are both called
1454 |    * asynchronously from main loop. Moreover, they end if err hook is
1455 |    * called. Therefore, we could suppose that it is always called
1456 |    * asynchronously.
1457 |    */
1458 | 
1459 |   bgp_store_error(p, conn, BE_SOCKET, err);
1460 | 
1461 |   if (err)
1462 |     BGP_TRACE(D_EVENTS, "Connection lost (%M)", err);
1463 |   else
1464 |     BGP_TRACE(D_EVENTS, "Connection closed");
1465 | 
1466 |   if ((conn->state == BS_ESTABLISHED) && p->gr_ready)
1467 |     bgp_handle_graceful_restart(p);
1468 | 
1469 |   bgp_conn_enter_idle_state(conn);
1470 | }
1471 | 
1472 | static void
1473 | bgp_hold_timeout(timer *t)
1474 | {
1475 |   struct bgp_conn *conn = t->data;
1476 |   struct bgp_proto *p = conn->bgp;
1477 | 
1478 |   DBG("BGP: Hold timeout\n");
1479 | 
1480 |   /* We are already closing the connection - just do hangup */
1481 |   if (conn->state == BS_CLOSE)
1482 |   {
1483 |     BGP_TRACE(D_EVENTS, "Connection stalled");
1484 |     bgp_conn_enter_idle_state(conn);
1485 |     return;
1486 |   }
1487 | 
1488 |   /* If there is something in input queue, we are probably congested
1489 |      and perhaps just not processed BGP packets in time. */
1490 | 
1491 |   if (sk_rx_ready(conn->sk) > 0)
1492 |     bgp_start_timer(conn->hold_timer, 10);
1493 |   else if ((conn->state == BS_ESTABLISHED) && p->llgr_ready)
1494 |   {
1495 |     BGP_TRACE(D_EVENTS, "Hold timer expired");
1496 |     bgp_handle_graceful_restart(p);
1497 |     bgp_conn_enter_idle_state(conn);
1498 |   }
1499 |   else
1500 |     bgp_error(conn, 4, 0, NULL, 0);
1501 | }
1502 | 
1503 | static void
1504 | bgp_keepalive_timeout(timer *t)
1505 | {
1506 |   struct bgp_conn *conn = t->data;
1507 | 
1508 |   DBG("BGP: Keepalive timer\n");
1509 |   bgp_schedule_packet(conn, NULL, PKT_KEEPALIVE);
1510 | 
1511 |   /* Kick TX a bit faster */
1512 |   if (ev_active(conn->tx_ev))
1513 |     ev_run(conn->tx_ev);
1514 | }
1515 | 
1516 | void
1517 | bgp_send_hold_timeout(timer *t)
1518 | {
1519 |   struct bgp_conn *conn = t->data;
1520 |   struct bgp_proto *p = conn->bgp;
1521 | 
1522 |   DBG("BGP: Send hold timeout\n");
1523 | 
1524 |   if (conn->state == BS_CLOSE)
1525 |     return;
1526 | 
1527 |   uint code = 8;
1528 |   uint subcode = 0;
1529 | 
1530 |   /* Like bgp_error() but without NOTIFICATION */
1531 |   bgp_log_error(p, BE_BGP_TX, "Error", code, subcode, NULL, 0);
1532 |   bgp_store_error(p, conn, BE_BGP_TX, (code << 16) | subcode);
1533 |   bgp_conn_enter_idle_state(conn);
1534 |   bgp_update_startup_delay(p);
1535 |   bgp_stop(p, 0, NULL, 0);
1536 | }
