1538 | static void
1539 | bgp_setup_conn(struct bgp_proto *p, struct bgp_conn *conn)
1540 | {
1541 |   conn->sk = NULL;
1542 |   conn->bgp = p;
1543 | 
1544 |   conn->packets_to_send = 0;
1545 |   conn->channels_to_send = 0;
1546 |   conn->last_channel = 0;
1547 |   conn->last_channel_count = 0;
1548 | 
1549 |   conn->connect_timer	= tm_new_init(p->p.pool, bgp_connect_timeout,	 conn, 0, 0);
1550 |   conn->hold_timer 	= tm_new_init(p->p.pool, bgp_hold_timeout,	 conn, 0, 0);
1551 |   conn->keepalive_timer	= tm_new_init(p->p.pool, bgp_keepalive_timeout, conn, 0, 0);
1552 |   conn->send_hold_timer = tm_new_init(p->p.pool, bgp_send_hold_timeout, conn, 0, 0);
1553 | 
1554 |   conn->tx_ev = ev_new_init(p->p.pool, bgp_kick_tx, conn);
1555 | }
