1814 | static void
1815 | bgp_start_neighbor(struct bgp_proto *p)
1816 | {
1817 |   /* Called only for single-hop BGP sessions */
1818 | 
1819 |   if (ipa_zero(p->local_ip))
1820 |     p->local_ip = p->neigh->ifa->ip;
1821 | 
1822 |   if (ipa_is_link_local(p->local_ip))
1823 |     p->link_addr = p->local_ip;
1824 |   else if (p->neigh->iface->llv6)
1825 |     p->link_addr = p->neigh->iface->llv6->ip;
1826 | 
1827 |   bgp_initiate(p);
1828 | }
1829 | 
1830 | static void
1831 | bgp_neigh_notify(neighbor *n)
1832 | {
1833 |   struct bgp_proto *p = (struct bgp_proto *) n->proto;
1834 |   int ps = p->p.proto_state;
1835 | 
1836 |   if (n != p->neigh)
1837 |     return;
1838 | 
1839 |   if ((ps == PS_DOWN) || (ps == PS_STOP))
1840 |     return;
1841 | 
1842 |   int prepare = (ps == PS_START) && (p->start_state == BSS_PREPARE);
1843 | 
1844 |   if (n->scope <= 0)
1845 |   {
1846 |     if (!prepare)
1847 |     {
1848 |       BGP_TRACE(D_EVENTS, "Neighbor lost");
1849 |       bgp_store_error(p, NULL, BE_MISC, BEM_NEIGHBOR_LOST);
1850 |       /* Perhaps also run bgp_update_startup_delay(p)? */
1851 |       bgp_stop(p, 0, NULL, 0);
1852 |     }
1853 |   }
1854 |   else if (p->cf->check_link && !(n->iface->flags & IF_LINK_UP))
1855 |   {
1856 |     if (!prepare)
1857 |     {
1858 |       BGP_TRACE(D_EVENTS, "Link down");
1859 |       bgp_store_error(p, NULL, BE_MISC, BEM_LINK_DOWN);
1860 |       if (ps == PS_UP)
1861 | 	bgp_update_startup_delay(p);
1862 |       bgp_stop(p, 0, NULL, 0);
1863 |     }
1864 |   }
1865 |   else
1866 |   {
1867 |     if (prepare)
1868 |     {
1869 |       BGP_TRACE(D_EVENTS, "Neighbor ready");
1870 |       bgp_start_neighbor(p);
1871 |     }
1872 |   }
1873 | }
1874 | 
1875 | static void
1876 | bgp_bfd_notify(struct bfd_request *req)
1877 | {
1878 |   struct bgp_proto *p = req->data;
1879 |   int ps = p->p.proto_state;
1880 | 
1881 |   if (req->down && ((ps == PS_START) || (ps == PS_UP)))
1882 |   {
1883 |     BGP_TRACE(D_EVENTS, "BFD session down");
1884 |     bgp_store_error(p, NULL, BE_MISC, BEM_BFD_DOWN);
1885 | 
1886 |     if (req->opts.mode == BGP_BFD_GRACEFUL)
1887 |     {
1888 |       /* Trigger graceful restart */
1889 |       if (p->conn && (p->conn->state == BS_ESTABLISHED) && p->gr_ready)
1890 | 	bgp_handle_graceful_restart(p);
1891 | 
1892 |       if (p->incoming_conn.state > BS_IDLE)
1893 | 	bgp_conn_enter_idle_state(&p->incoming_conn);
1894 | 
1895 |       if (p->outgoing_conn.state > BS_IDLE)
1896 | 	bgp_conn_enter_idle_state(&p->outgoing_conn);
1897 |     }
1898 |     else
1899 |     {
1900 |       /* Trigger session down */
1901 |       if (ps == PS_UP)
1902 | 	bgp_update_startup_delay(p);
1903 |       bgp_stop(p, 0, NULL, 0);
1904 |     }
1905 |   }
1906 | }
