2301 | static int
2302 | bgp_channel_start(struct channel *C)
2303 | {
2304 |   struct bgp_proto *p = (void *) C->proto;
2305 |   struct bgp_channel *c = (void *) C;
2306 |   ip_addr src = p->local_ip;
2307 | 
2308 |   if (c->igp_table_ip4)
2309 |     rt_lock_table(c->igp_table_ip4);
2310 | 
2311 |   if (c->igp_table_ip6)
2312 |     rt_lock_table(c->igp_table_ip6);
2313 | 
2314 |   if (c->base_table)
2315 |   {
2316 |     rt_lock_table(c->base_table);
2317 |     rt_flowspec_link(c->base_table, c->c.table);
2318 |   }
2319 | 
2320 |   c->pool = p->p.pool; // XXXX
2321 |   bgp_init_bucket_table(c);
2322 |   bgp_init_prefix_table(c);
2323 | 
2324 |   if (c->cf->import_table)
2325 |     channel_setup_in_table(C);
2326 | 
2327 |   if (c->cf->export_table)
2328 |     channel_setup_out_table(C);
2329 | 
2330 |   c->stale_timer = tm_new_init(c->pool, bgp_long_lived_stale_timeout, c, 0, 0);
2331 | 
2332 |   c->next_hop_addr = c->cf->next_hop_addr;
2333 |   c->link_addr = IPA_NONE;
2334 |   c->packets_to_send = 0;
2335 | 
2336 |   /* Try to use source address as next hop address */
2337 |   if (ipa_zero(c->next_hop_addr))
2338 |   {
2339 |     if (bgp_channel_is_ipv4(c) && (ipa_is_ip4(src) || c->ext_next_hop))
2340 |       c->next_hop_addr = src;
2341 | 
2342 |     if (bgp_channel_is_ipv6(c) && (ipa_is_ip6(src) || c->ext_next_hop))
2343 |       c->next_hop_addr = src;
2344 |   }
2345 | 
2346 |   /* Use preferred addresses associated with interface / source address */
2347 |   if (ipa_zero(c->next_hop_addr))
2348 |   {
2349 |     /* We know the iface for single-hop, we make lookup for multihop */
2350 |     struct neighbor *nbr = p->neigh ?: neigh_find(&p->p, src, NULL, 0);
2351 |     struct iface *iface = nbr ? nbr->iface : NULL;
2352 | 
2353 |     if (bgp_channel_is_ipv4(c) && iface && iface->addr4)
2354 |       c->next_hop_addr = iface->addr4->ip;
2355 | 
2356 |     if (bgp_channel_is_ipv6(c) && iface && iface->addr6)
2357 |       c->next_hop_addr = iface->addr6->ip;
2358 |   }
2359 | 
2360 |   /* Exit if no feasible next hop address is found */
2361 |   if (ipa_zero(c->next_hop_addr))
2362 |   {
2363 |     log(L_WARN "%s: Missing next hop address", p->p.name);
2364 |     return 0;
2365 |   }
2366 | 
2367 |   /* Set link-local address for IPv6 single-hop BGP */
2368 |   if (ipa_is_ip6(c->next_hop_addr) && p->neigh)
2369 |   {
2370 |     c->link_addr = p->link_addr;
2371 | 
2372 |     if (ipa_zero(c->link_addr))
2373 |       log(L_WARN "%s: Missing link-local address", p->p.name);
2374 |   }
2375 | 
2376 |   /* Link local address is already in c->link_addr */
2377 |   if (ipa_is_link_local(c->next_hop_addr))
2378 |     c->next_hop_addr = IPA_NONE;
2379 | 
2380 |   return 0; /* XXXX: Currently undefined */
2381 | }
