2428 | struct rtable_config *
2429 | bgp_default_igp_table(struct bgp_config *cf, struct bgp_channel_config *cc, u32 type)
2430 | {
2431 |   struct bgp_channel_config *cc2;
2432 |   struct rtable_config *tab;
2433 | 
2434 |   /* First, try table connected by the channel */
2435 |   if (cc->c.table->addr_type == type)
2436 |     return cc->c.table;
2437 | 
2438 |   /* Find paired channel with the same SAFI but the other AFI */
2439 |   u32 afi2 = cc->afi ^ 0x30000;
2440 |   cc2 = bgp_find_channel_config(cf, afi2);
2441 | 
2442 |   /* Second, try IGP table configured in the paired channel */
2443 |   if (cc2 && (tab = (type == NET_IP4) ? cc2->igp_table_ip4 : cc2->igp_table_ip6))
2444 |     return tab;
2445 | 
2446 |   /* Third, try table connected by the paired channel */
2447 |   if (cc2 && (cc2->c.table->addr_type == type))
2448 |     return cc2->c.table;
2449 | 
2450 |   /* Last, try default table of given type */
2451 |   if (tab = cf->c.global->def_tables[type])
2452 |     return tab;
2453 | 
2454 |   cf_error("Undefined IGP table");
2455 | }
