2457 | static struct rtable_config *
2458 | bgp_default_base_table(struct bgp_config *cf, struct bgp_channel_config *cc)
2459 | {
2460 |   /* Expected table type */
2461 |   u32 type = (cc->afi == BGP_AF_FLOW4) ? NET_IP4 : NET_IP6;
2462 | 
2463 |   /* First, try appropriate IP channel */
2464 |   u32 afi2 = BGP_AF(BGP_AFI(cc->afi), BGP_SAFI_UNICAST);
2465 |   struct bgp_channel_config *cc2 = bgp_find_channel_config(cf, afi2);
2466 |   if (cc2 && (cc2->c.table->addr_type == type))
2467 |     return cc2->c.table;
2468 | 
2469 |   /* Last, try default table of given type */
2470 |   struct rtable_config *tab = cf->c.global->def_tables[type];
2471 |   if (tab)
2472 |     return tab;
2473 | 
2474 |   cf_error("Undefined base table");
2475 | }
