2714 | 
2715 |     if (cc->require_add_path && !cc->add_path)
2716 |       cf_warn("ADD-PATH required but not enabled");
2717 | 
2718 |     if (cc->min_llgr_time > cc->max_llgr_time)
2719 |       cf_error("Min long-lived stale time (%u) exceeds max long-lived stale time (%u)",
2720 | 	       cc->min_llgr_time, cc->max_llgr_time);
2721 | 
2722 |   }
