  55 | static struct bgp_channel *
  56 | bgp_get_channel(struct bgp_proto *p, u32 afi)
  57 | {
  58 |   uint i;
  59 | 
  60 |   for (i = 0; i < p->channel_count; i++)
  61 |     if (p->afi_map[i] == afi)
  62 |       return p->channel_map[i];
  63 | 
  64 |   return NULL;
  65 | }
