 112 | static int
 113 | bgp_estimate_add_path(struct bgp_proto *p, byte *pkt, uint len)
 114 | {
 115 |   /* No need to estimate it for other messages than UPDATE */
 116 |   if (pkt[18] != PKT_UPDATE)
 117 |     return 0;
 118 | 
 119 |   /* 1 -> no channel, 2 -> all channels, 3 -> some channels */
 120 |   if (p->summary_add_path_rx < 3)
 121 |     return p->summary_add_path_rx == 2;
 122 | 
 123 |   uint afi = bgp_find_update_afi(pkt, len);
 124 |   struct bgp_channel *c = bgp_get_channel(p, afi);
 125 |   if (!c)
 126 |   {
 127 |     /* Either frame error (if !afi) or unknown AFI/SAFI,
 128 |        will be reported later in regular parsing */
 129 |     BGP_TRACE(D_PACKETS, "MRT processing noticed invalid packet");
 130 |     return 0;
 131 |   }
 132 | 
 133 |   return c->add_path_rx;
 134 | }
