 136 | static void
 137 | bgp_dump_message(struct bgp_conn *conn, byte *pkt, uint len)
 138 | {
 139 |   struct mrt_bgp_data d;
 140 |   init_mrt_bgp_data(conn, &d);
 141 | 
 142 |   d.message = pkt;
 143 |   d.msg_len = len;
 144 |   d.add_path = bgp_estimate_add_path(conn->bgp, pkt, len);
