1125 | bgp_apply_mpls_labels(struct bgp_parse_state *s, rta *a, u32 *labels, uint lnum)
1126 | {
1127 |   if (lnum > MPLS_MAX_LABEL_STACK)
1128 |   {
1129 |     REPORT("Too many MPLS labels ($u)", lnum);
1130 | 
1131 |     a->dest = RTD_UNREACHABLE;
1132 |     a->hostentry = NULL;
1133 |     a->nh = (struct nexthop) { };
1134 |     return;
1135 |   }
