1184 | static inline int
1185 | bgp_use_next_hop(struct bgp_export_state *s, eattr *a)
1186 | {
1187 |   struct bgp_proto *p = s->proto;
1188 |   struct bgp_channel *c = s->channel;
1189 |   ip_addr *nh = (void *) a->u.ptr->data;
1190 | 
1191 |   /* Handle next hop self option */
1192 |   if (c->cf->next_hop_self && bgp_match_src(s, c->cf->next_hop_self))
1193 |     return 0;
1194 | 
1195 |   /* Handle next hop keep option */
1196 |   if (c->cf->next_hop_keep && bgp_match_src(s, c->cf->next_hop_keep))
1197 |     return 1;
1198 | 
1199 |   /* Keep it when explicitly set in export filter */
1200 |   if (a->fresh)
1201 |     return 1;
1202 | 
1203 |   /* Check for non-matching AF */
1204 |   if ((ipa_is_ip4(*nh) != bgp_channel_is_ipv4(c)) && !c->ext_next_hop)
1205 |     return 0;
1206 | 
1207 |   /* Do not pass NEXT_HOP between different VRFs */
1208 |   if (p->p.vrf_set && s->src && s->src->p.vrf_set && (p->p.vrf != s->src->p.vrf))
1209 |     return 0;
1210 | 
1211 |   /* Keep it when exported to internal peers */
1212 |   if (p->is_interior && ipa_nonzero(*nh))
1213 |     return 1;
1214 | 
1215 |   /* Keep it when forwarded between single-hop BGPs on the same iface */
1216 |   struct iface *ifa = (s->src && s->src->neigh && (s->src->p.proto_state != PS_DOWN)) ?
1217 |     s->src->neigh->iface : NULL;
1218 |   return p->neigh && (p->neigh->iface == ifa);
1219 | }
1220 | 
1221 | static inline int
1222 | bgp_use_gateway(struct bgp_export_state *s)
1223 | {
1224 |   struct bgp_proto *p = s->proto;
1225 |   struct bgp_channel *c = s->channel;
1226 |   rta *ra = s->route->attrs;
1227 | 
1228 |   /* Handle next hop self option - also applies to gateway */
1229 |   if (c->cf->next_hop_self && bgp_match_src(s, c->cf->next_hop_self))
1230 |     return 0;
1231 | 
1232 |   /* We need one valid global gateway */
1233 |   if ((ra->dest != RTD_UNICAST) || ra->nh.next || ipa_zero(ra->nh.gw) || ipa_is_link_local(ra->nh.gw))
1234 |     return 0;
1235 | 
1236 |   /* Check for non-matching AF */
1237 |   if ((ipa_is_ip4(ra->nh.gw) != bgp_channel_is_ipv4(c)) && !c->ext_next_hop)
1238 |     return 0;
1239 | 
1240 |   /* Do not use gateway from different VRF */
1241 |   if (p->p.vrf_set && ra->nh.iface && !if_in_vrf(ra->nh.iface, p->p.vrf))
1242 |     return 0;
1243 | 
1244 |   /* Use it when exported to internal peers */
1245 |   if (p->is_interior)
1246 |     return 1;
1247 | 
1248 |   /* Use it when forwarded to single-hop BGP peer on on the same iface */
1249 |   return p->neigh && (p->neigh->iface == ra->nh.iface);
1250 | }
1251 | 
1252 | static void
1253 | bgp_update_next_hop_ip(struct bgp_export_state *s, eattr *a, ea_list **to)
1254 | {
1255 |   if (!a || !bgp_use_next_hop(s, a))
1256 |   {
1257 |     if (bgp_use_gateway(s))
1258 |     {
1259 |       rta *ra = s->route->attrs;
1260 |       ip_addr nh[1] = { ra->nh.gw };
1261 |       bgp_set_attr_data(to, s->pool, BA_NEXT_HOP, 0, nh, 16);
1262 | 
1263 |       if (s->mpls)
1264 |       {
1265 | 	u32 implicit_null = BGP_MPLS_NULL;
1266 | 	u32 *labels = ra->nh.labels ? ra->nh.label : &implicit_null;
1267 | 	uint lnum = ra->nh.labels ? ra->nh.labels : 1;
1268 | 	bgp_set_attr_data(to, s->pool, BA_MPLS_LABEL_STACK, 0, labels, lnum * 4);
1269 |       }
1270 |       else
1271 | 	bgp_unset_attr(to, s->pool, BA_MPLS_LABEL_STACK);
1272 |     }
1273 |     else
1274 |     {
1275 |       ip_addr nh[2] = { s->channel->next_hop_addr, s->channel->link_addr };
1276 |       bgp_set_attr_data(to, s->pool, BA_NEXT_HOP, 0, nh, ipa_nonzero(nh[1]) ? 32 : 16);
1277 |       s->local_next_hop = 1;
1278 | 
1279 |       if (s->mpls)
1280 |       {
1281 | 	u32 label = ea_get_int(s->route->attrs->eattrs, EA_MPLS_LABEL, BGP_MPLS_NULL);
1282 | 	bgp_set_attr_data(to, s->pool, BA_MPLS_LABEL_STACK, 0, &label, 4);
1283 |       }
1284 |       else
1285 | 	bgp_unset_attr(to, s->pool, BA_MPLS_LABEL_STACK);
1286 |     }
1287 |   }
1288 | 
1289 |   /* Check if next hop is valid */
1290 |   a = bgp_find_attr(*to, BA_NEXT_HOP);
1291 |   if (!a)
1292 |     REJECT(NO_NEXT_HOP);
1293 | 
1294 |   ip_addr *nh = (void *) a->u.ptr->data;
1295 |   ip_addr peer = s->proto->remote_ip;
1296 |   uint len = a->u.ptr->length;
1297 | 
1298 |   /* Forbid zero next hop */
1299 |   if (ipa_zero2(nh[0]) && ((len != 32) || ipa_zero(nh[1])))
1300 |     REJECT(BAD_NEXT_HOP " - zero address");
1301 | 
1302 |   /* Forbid next hop equal to neighbor IP */
1303 |   if (ipa_equal(peer, nh[0]) || ((len == 32) && ipa_equal(peer, nh[1])))
1304 |     REJECT(BAD_NEXT_HOP " - neighbor address %I", peer);
1305 | 
1306 |   /* Forbid next hop with non-matching AF */
1307 |   if ((ipa_is_ip4(nh[0]) != bgp_channel_is_ipv4(s->channel)) &&
1308 |       !s->channel->ext_next_hop)
1309 |     REJECT(BAD_NEXT_HOP MISMATCHED_AF, nh[0], s->channel->desc->name);
1310 | 
1311 |   /* Just check if MPLS stack */
1312 |   if (s->mpls && !bgp_find_attr(*to, BA_MPLS_LABEL_STACK))
1313 |     REJECT(NO_LABEL_STACK);
1314 | }
