1316 | static uint
1317 | bgp_prepare_link_local_next_hop(struct bgp_write_state *s, ip_addr *nh)
1318 | {
1319 |   /*
1320 |    * We have link-local next-hop in nh[1]
1321 |    *
1322 |    * Possible variants:
1323 |    * [ ::, fe80::XX ] - BIRD's default/internal (LLNH_NATIVE)
1324 |    * [ fe80::XX ] - draft-white-linklocal-capability (LLNH_SINGLE)
1325 |    * [ fe80::XX, fe80::XX ] - Used in JunoOS (LLNH_DOUBLE)
1326 |    */
1327 | 
1328 |   switch (s->llnh_format)
1329 |   {
1330 |   case LLNH_NATIVE:
1331 |     return 32;
1332 | 
1333 |   case LLNH_SINGLE:
1334 |     nh[0] = nh[1];
1335 |     return 16;
1336 | 
1337 |   case LLNH_DOUBLE:
1338 |     nh[0] = nh[1];
1339 |     return 32;
1340 | 
1341 |   default:
1342 |     ASSERT(0);
1343 |     return 32;
1344 |   }
1345 | }
