1553 | 
1554 | static void
1555 | bgp_rte_update(struct bgp_parse_state *s, const net_addr *n, u32 path_id, rta *a0)
1556 | {
1557 |   if (path_id != s->last_id)
1558 |   {
1559 |     s->last_src = rt_get_source(&s->proto->p, path_id);
1560 |     s->last_id = path_id;
1561 | 
1562 |     rta_free(s->cached_rta);
1563 |     s->cached_rta = NULL;
1564 |   }
1565 | 
1566 |   if (!a0)
1567 |   {
1568 |     /* Route update was changed to withdraw */
1569 |     if (s->err_withdraw && s->reach_nlri_step)
1570 |       REPORT("Invalid route %N withdrawn", n);
1571 | 
1572 |     /* Route withdraw */
1573 |     rte_update3(&s->channel->c, n, NULL, s->last_src);
1574 |     return;
1575 |   }
1576 | 
1577 |   /* Prepare cached route attributes */
1578 |   if (s->cached_rta == NULL)
1579 |   {
1580 |     /* Workaround for rta_lookup() breaking eattrs */
1581 |     ea_list *ea = a0->eattrs;
1582 |     s->cached_rta = rta_lookup(a0);
1583 |     a0->eattrs = ea;
1584 |   }
1585 | 
1586 |   rta *a = rta_clone(s->cached_rta);
1587 |   rte *e = rte_get_temp(a, s->last_src);
1588 | 
1589 |   rte_update3(&s->channel->c, n, e, s->last_src);
1590 | }
