1592 | static void
1593 | bgp_encode_mpls_labels(struct bgp_write_state *s UNUSED, const adata *mpls, byte **pos, uint *size, byte *pxlen)
1594 | {
1595 |   const u32 dummy = 0;
1596 |   const u32 *labels = mpls ? (const u32 *) mpls->data : &dummy;
1597 |   uint lnum = mpls ? (mpls->length / 4) : 1;
1598 | 
1599 |   for (uint i = 0; i < lnum; i++)
1600 |   {
1601 |     put_u24(*pos, labels[i] << 4);
1602 |     ADVANCE(*pos, *size, 3);
1603 |   }
1604 | 
1605 |   /* Add bottom-of-stack flag */
1606 |   (*pos)[-1] |= BGP_MPLS_BOS;
1607 | 
1608 |   *pxlen += 24 * lnum;
1609 | }
1610 | 
1611 | static void
1612 | bgp_decode_mpls_labels(struct bgp_parse_state *s, byte **pos, uint *len, uint *pxlen, rta *a)
1613 | {
1614 |   u32 labels[BGP_MPLS_MAX], label;
1615 |   uint lnum = 0;
1616 | 
1617 |   do {
1618 |     if (*pxlen < 24)
1619 |       bgp_parse_error(s, 1);
1620 | 
1621 |     label = get_u24(*pos);
1622 |     labels[lnum++] = label >> 4;
1623 |     ADVANCE(*pos, *len, 3);
1624 |     *pxlen -= 24;
1625 | 
1626 |     /* RFC 8277 2.4 - withdraw does not have variable-size MPLS stack but
1627 |        fixed-size 24-bit Compatibility field, which MUST be ignored */
1628 |     if (!s->reach_nlri_step)
1629 |       return;
1630 |   }
1631 |   while (!(label & BGP_MPLS_BOS));
1632 | 
1633 |   if (!a)
1634 |     return;
1635 | 
1636 |   /* Attach MPLS attribute unless we already have one */
1637 |   if (!s->mpls_labels)
1638 |   {
1639 |     s->mpls_labels = lp_alloc_adata(s->pool, 4*BGP_MPLS_MAX);
1640 |     bgp_set_attr_ptr(&(a->eattrs), s->pool, BA_MPLS_LABEL_STACK, 0, s->mpls_labels);
1641 |   }
1642 | 
1643 |   /* Overwrite data in the attribute */
1644 |   s->mpls_labels->length = 4*lnum;
1645 |   memcpy(s->mpls_labels->data, labels, 4*lnum);
1646 | 
1647 |   /* Update next hop entry in rta */
1648 |   bgp_apply_mpls_labels(s, a, labels, lnum);
1649 | 
1650 |   /* Attributes were changed, invalidate cached entry */
1651 |   rta_free(s->cached_rta);
1652 |   s->cached_rta = NULL;
1653 | 
1654 |   return;
1655 | }
1656 | 
1657 | static uint
1658 | bgp_encode_nlri_ip4(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, uint size)
1659 | {
1660 |   byte *pos = buf;
1661 | 
1662 |   while (!EMPTY_LIST(buck->prefixes) && (size >= BGP_NLRI_MAX))
1663 |   {
1664 |     struct bgp_prefix *px = HEAD(buck->prefixes);
1665 |     struct net_addr_ip4 *net = (void *) px->net;
1666 | 
1667 |     /* Encode path ID */
1668 |     if (s->add_path)
1669 |     {
1670 |       put_u32(pos, px->path_id);
1671 |       ADVANCE(pos, size, 4);
1672 |     }
1673 | 
1674 |     /* Encode prefix length */
1675 |     *pos = net->pxlen;
1676 |     ADVANCE(pos, size, 1);
1677 | 
1678 |     /* Encode MPLS labels */
1679 |     if (s->mpls)
1680 |       bgp_encode_mpls_labels(s, s->mpls_labels, &pos, &size, pos - 1);
1681 | 
1682 |     /* Encode prefix body */
1683 |     ip4_addr a = ip4_hton(net->prefix);
1684 |     uint b = (net->pxlen + 7) / 8;
1685 |     memcpy(pos, &a, b);
1686 |     ADVANCE(pos, size, b);
1687 | 
1688 |     if (!s->sham)
1689 |       bgp_free_prefix(s->channel, px);
1690 |     else
1691 |       rem_node(&px->buck_node);
1692 |   }
1693 | 
1694 |   return pos - buf;
1695 | }
1696 | 
1697 | static void
1698 | bgp_decode_nlri_ip4(struct bgp_parse_state *s, byte *pos, uint len, rta *a)
1699 | {
1700 |   while (len)
1701 |   {
1702 |     net_addr_ip4 net;
1703 |     u32 path_id = 0;
1704 | 
1705 |     /* Decode path ID */
1706 |     if (s->add_path)
1707 |     {
1708 |       if (len < 5)
1709 | 	bgp_parse_error(s, 1);
1710 | 
1711 |       path_id = get_u32(pos);
1712 |       ADVANCE(pos, len, 4);
1713 |     }
1714 | 
1715 |     /* Decode prefix length */
1716 |     uint l = *pos;
1717 |     ADVANCE(pos, len, 1);
1718 | 
1719 |     if (len < ((l + 7) / 8))
1720 |       bgp_parse_error(s, 1);
1721 | 
1722 |     /* Decode MPLS labels */
1723 |     if (s->mpls)
1724 |       bgp_decode_mpls_labels(s, &pos, &len, &l, a);
1725 | 
1726 |     if (l > IP4_MAX_PREFIX_LENGTH)
1727 |       bgp_parse_error(s, 10);
1728 | 
1729 |     /* Decode prefix body */
1730 |     ip4_addr addr = IP4_NONE;
1731 |     uint b = (l + 7) / 8;
1732 |     memcpy(&addr, pos, b);
1733 |     ADVANCE(pos, len, b);
1734 | 
1735 |     net = NET_ADDR_IP4(ip4_ntoh(addr), l);
1736 |     net_normalize_ip4(&net);
1737 | 
1738 |     // XXXX validate prefix
1739 | 
1740 |     bgp_rte_update(s, (net_addr *) &net, path_id, a);
1741 |   }
1742 | }
1743 | 
1744 | 
1745 | static uint
1746 | bgp_encode_nlri_ip6(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, uint size)
1747 | {
1748 |   byte *pos = buf;
1749 | 
1750 |   while (!EMPTY_LIST(buck->prefixes) && (size >= BGP_NLRI_MAX))
1751 |   {
1752 |     struct bgp_prefix *px = HEAD(buck->prefixes);
1753 |     struct net_addr_ip6 *net = (void *) px->net;
