2480 | static byte *
2481 | bgp_create_ip_unreach(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, byte *end)
2482 | {
2483 |   /*
2484 |    *	2 B	Withdrawn Routes Length
2485 |    *	var	IPv4 Withdrawn Routes NLRI
2486 |    *	2 B	Total Path Attribute Length (zero)
2487 |    *	---	Path Attributes (unused)
2488 |    *	---	IPv4 Network Layer Reachability Information (unused)
2489 |    */
2490 | 
2491 |   uint len = bgp_encode_nlri(s, buck, buf+2, end);
2492 | 
