2499 | static byte *
2500 | bgp_create_mp_unreach(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, byte *end)
2501 | {
2502 |   /*
2503 |    *	2 B	Withdrawn Routes Length (zero)
2504 |    *	---	IPv4 Withdrawn Routes NLRI (unused)
2505 |    *	2 B	Total Path Attribute Length
2506 |    *	1 B	MP_UNREACH_NLRI hdr - Attribute Flags
2507 |    *	1 B	MP_UNREACH_NLRI hdr - Attribute Type Code
2508 |    *	2 B	MP_UNREACH_NLRI hdr - Length of Attribute Data
2509 |    *	2 B	MP_UNREACH_NLRI data - Address Family Identifier
2510 |    *	1 B	MP_UNREACH_NLRI data - Subsequent Address Family Identifier
2511 |    *	var	MP_UNREACH_NLRI data - Network Layer Reachability Information
2512 |    *	---	IPv4 Network Layer Reachability Information (unused)
2513 |    */
2514 | 
2515 |   uint len = bgp_encode_nlri(s, buck, buf+11, end);
2516 | 
2517 |   put_u16(buf+0, 0);
2518 |   put_u16(buf+2, 7+len);
2519 | 
2520 |   /* Begin of MP_UNREACH_NLRI atribute */
2521 |   buf[4] = BAF_OPTIONAL | BAF_EXT_LEN;
2522 |   buf[5] = BA_MP_UNREACH_NLRI;
2523 |   put_u16(buf+6, 3+len);
2524 |   put_af3(buf+8, s->channel->afi);
2525 | 
2526 |   return buf+11+len;
