2604 | static byte *
2605 | bgp_create_update(struct bgp_channel *c, byte *buf)
2606 | {
2607 |   struct bgp_proto *p = (void *) c->c.proto;
2608 |   struct bgp_bucket *buck;
2609 |   byte *end = buf + (bgp_max_packet_length(p->conn) - BGP_HEADER_LENGTH);
2610 |   byte *res = NULL;
2611 | 
2612 | again: ;
2613 | 
2614 |   struct lp_state tmpp;
2615 |   lp_save(tmp_linpool, &tmpp);
2616 | 
2617 |   /* Initialize write state */
2618 |   struct bgp_write_state s = {
2619 |     .proto = p,
2620 |     .channel = c,
2621 |     .pool = tmp_linpool,
2622 |     .mp_reach = (c->afi != BGP_AF_IPV4) || c->ext_next_hop,
2623 |     .as4_session = p->as4_session,
2624 |     .add_path = c->add_path_tx,
2625 |     .llnh_format = c->cf->llnh_format,
2626 |     .mpls = c->desc->mpls,
2627 |   };
2628 | 
2629 |   /* Try unreachable bucket */
2630 |   if ((buck = c->withdraw_bucket) && !EMPTY_LIST(buck->prefixes))
2631 |   {
2632 |     res = (c->afi == BGP_AF_IPV4) && !c->ext_next_hop ?
2633 |       bgp_create_ip_unreach(&s, buck, buf, end):
2634 |       bgp_create_mp_unreach(&s, buck, buf, end);
2635 | 
2636 |     goto done;
2637 |   }
2638 | 
2639 |   /* Try reachable buckets */
2640 |   if (!EMPTY_LIST(c->bucket_queue))
2641 |   {
2642 |     buck = HEAD(c->bucket_queue);
2643 | 
2644 |     /* Cleanup empty buckets */
2645 |     if (EMPTY_LIST(buck->prefixes))
2646 |     {
2647 |       bgp_free_bucket(c, buck);
2648 |       lp_restore(tmp_linpool, &tmpp);
2649 |       goto again;
2650 |     }
2651 | 
2652 |     res = !s.mp_reach ?
2653 |       bgp_create_ip_reach(&s, buck, buf, end):
2654 |       bgp_create_mp_reach(&s, buck, buf, end);
2655 | 
2656 |     if (EMPTY_LIST(buck->prefixes))
2657 |       bgp_free_bucket(c, buck);
2658 |     else
2659 |       bgp_defer_bucket(c, buck);
2660 | 
2661 |     if (!res)
2662 |     {
2663 |       lp_restore(tmp_linpool, &tmpp);
2664 |       goto again;
2665 |     }
2666 | 
2667 |     goto done;
2668 |   }
2669 | 
2670 |   /* No more prefixes to send */
2671 |   return NULL;
2672 | 
2673 | done:
2674 |   BGP_TRACE_RL(&rl_snd_update, D_PACKETS, "Sending UPDATE");
2675 |   p->stats.tx_updates++;
2676 |   lp_restore(tmp_linpool, &tmpp);
2677 | 
2678 |   return res;
2679 | }
