2898 | static uint
2899 | bgp_find_update_afi(byte *pos, uint len)
2900 | {
2901 |   /*
2902 |    * This is stripped-down version of bgp_rx_update(), bgp_decode_attrs() and
2903 |    * bgp_decode_mp_[un]reach_nlri() used by MRT code in order to find out which
2904 |    * AFI/SAFI is associated with incoming UPDATE. Returns 0 for framing errors.
2905 |    */
2906 |   if (len < 23)
2907 |     return 0;
2908 | 
2909 |   /* Assume there is no withrawn NLRI, read lengths and move to attribute list */
2910 |   uint wlen = get_u16(pos + 19);
2911 |   uint alen = get_u16(pos + 21);
2912 |   ADVANCE(pos, len, 23);
2913 | 
2914 |   /* Either non-zero withdrawn NLRI, non-zero reachable NLRI, or IPv4 End-of-RIB */
2915 |   if ((wlen != 0) || (alen < len) || !alen)
2916 |     return BGP_AF_IPV4;
2917 | 
2918 |   if (alen > len)
2919 |     return 0;
2920 | 
2921 |   /* Process attribute list (alen == len) */
2922 |   while (len)
2923 |   {
2924 |     if (len < 2)
2925 |       return 0;
2926 | 
2927 |     uint flags = pos[0];
2928 |     uint code = pos[1];
2929 |     ADVANCE(pos, len, 2);
2930 | 
2931 |     uint ll = !(flags & BAF_EXT_LEN) ? 1 : 2;
2932 |     if (len < ll)
2933 |       return 0;
2934 | 
2935 |     /* Read attribute length and move to attribute body */
2936 |     alen = (ll == 1) ? get_u8(pos) : get_u16(pos);
2937 |     ADVANCE(pos, len, ll);
2938 | 
2939 |     if (len < alen)
2940 |       return 0;
2941 | 
2942 |     /* Found MP NLRI */
2943 |     if ((code == BA_MP_REACH_NLRI) || (code == BA_MP_UNREACH_NLRI))
2944 |     {
2945 |       if (alen < 3)
2946 | 	return 0;
2947 | 
2948 |       return BGP_AF(get_u16(pos), pos[2]);
2949 |     }
2950 | 
2951 |     /* Move to the next attribute */
2952 |     ADVANCE(pos, len, alen);
2953 |   }
2954 | 
2955 |   /* No basic or MP NLRI, but there are some attributes -> error */
2956 |   return 0;
2957 | }
