3006 | static void
3007 | bgp_rx_route_refresh(struct bgp_conn *conn, byte *pkt, uint len)
3008 | {
3009 |   struct bgp_proto *p = conn->bgp;
3010 | 
3011 |   if (conn->state != BS_ESTABLISHED)
3012 |   { bgp_error(conn, 5, fsm_err_subcode[conn->state], NULL, 0); return; }
3013 | 
3014 |   if (!conn->local_caps->route_refresh)
3015 |   { bgp_error(conn, 1, 3, pkt+18, 1); return; }
3016 | 
3017 |   if (len < (BGP_HEADER_LENGTH + 4))
3018 |   { bgp_error(conn, 1, 2, pkt+16, 2); return; }
3019 | 
3020 |   if (len > (BGP_HEADER_LENGTH + 4))
3021 |   { bgp_error(conn, 7, 1, pkt, MIN(len, 2048)); return; }
3022 | 
3023 |   struct bgp_channel *c = bgp_get_channel(p, get_af4(pkt+19));
3024 |   if (!c)
3025 |   {
3026 |     log(L_WARN "%s: Got ROUTE-REFRESH subtype %u for AF %u.%u, ignoring",
3027 | 	p->p.name, pkt[21], get_u16(pkt+19), pkt[22]);
3028 |     return;
3029 |   }
3030 | 
3031 |   /* RFC 7313 redefined reserved field as RR message subtype */
3032 |   uint subtype = p->enhanced_refresh ? pkt[21] : BGP_RR_REQUEST;
3033 | 
3034 |   switch (subtype)
3035 |   {
3036 |   case BGP_RR_REQUEST:
3037 |     BGP_TRACE(D_PACKETS, "Got ROUTE-REFRESH");
3038 |     channel_request_feeding(&c->c);
3039 |     break;
3040 | 
3041 |   case BGP_RR_BEGIN:
3042 |     BGP_TRACE(D_PACKETS, "Got BEGIN-OF-RR");
3043 |     bgp_refresh_begin(c);
3044 |     break;
3045 | 
3046 |   case BGP_RR_END:
3047 |     BGP_TRACE(D_PACKETS, "Got END-OF-RR");
3048 |     bgp_refresh_end(c);
3049 |     break;
3050 | 
3051 |   default:
3052 |     log(L_WARN "%s: Got ROUTE-REFRESH message with unknown subtype %u, ignoring",
3053 | 	p->p.name, subtype);
3054 |     break;
3055 |   }
3056 | }
