3212 | /**
3213 |  * bgp_schedule_packet - schedule a packet for transmission
3214 |  * @conn: connection
3215 |  * @c: channel
3216 |  * @type: packet type
3217 |  *
3218 |  * Schedule a packet of type @type to be sent as soon as possible.
3219 |  */
3220 | void
3221 | bgp_schedule_packet(struct bgp_conn *conn, struct bgp_channel *c, int type)
3222 | {
3223 |   ASSERT(conn->sk);
3224 | 
3225 |   DBG("BGP: Scheduling packet type %d\n", type);
3226 | 
3227 |   if (c)
3228 |   {
3229 |     if (! conn->channels_to_send)
3230 |     {
3231 |       conn->last_channel = c->index;
3232 |       conn->last_channel_count = 0;
3233 |     }
3234 | 
3235 |     c->packets_to_send |= 1 << type;
3236 |     conn->channels_to_send |= 1 << c->index;
3237 |   }
3238 |   else
3239 |     conn->packets_to_send |= 1 << type;
3240 | 
3241 |   if ((conn->sk->tpos == conn->sk->tbuf) && !ev_active(conn->tx_ev))
3242 |     ev_schedule(conn->tx_ev);
3243 | }
3244 | void
3245 | bgp_kick_tx(void *vconn)
3246 | {
3247 |   struct bgp_conn *conn = vconn;
3248 | 
3249 |   DBG("BGP: kicking TX\n");
3250 |   uint max = 1024;
3251 |   while (--max && (bgp_fire_tx(conn) > 0))
3252 |     ;
3253 | 
3254 |   if (!max && !ev_active(conn->tx_ev))
3255 |     ev_schedule(conn->tx_ev);
3256 | }
3257 | 
3258 | void
3259 | bgp_tx(sock *sk)
3260 | {
3261 |   struct bgp_conn *conn = sk->data;
3262 | 
3263 |   /* Pending message was passed to kernel */
3264 |   if ((conn->state == BS_ESTABLISHED) || (conn->state == BS_OPENCONFIRM))
3265 |     bgp_start_timer(conn->send_hold_timer, conn->send_hold_time);
3266 | 
3267 |   DBG("BGP: TX hook\n");
3268 |   uint max = 1024;
3269 |   while (--max && (bgp_fire_tx(conn) > 0))
3270 |     ;
3271 | 
3272 |   if (!max && !ev_active(conn->tx_ev))
3273 |     ev_schedule(conn->tx_ev);
3274 | }
