3374 | void
3375 | bgp_log_error(struct bgp_proto *p, u8 class, char *msg, uint code, uint subcode, byte *data, uint len)
3376 | {
3377 |   byte argbuf[256+16], *t = argbuf;
3378 |   uint i;
3379 | 
3380 |   /* Don't report Cease messages generated by myself */
3381 |   if (code == 6 && class == BE_BGP_TX)
3382 |     return;
3383 | 
3384 |   /* Reset shutdown message */
3385 |   if ((code == 6) && ((subcode == 2) || (subcode == 4)))
3386 |     proto_set_message(&p->p, NULL, 0);
3387 | 
3388 |   if (len)
3389 |     {
3390 |       /* Bad peer AS / unacceptable hold time - print the value as decimal number */
3391 |       if ((code == 2) && ((subcode == 2) || (subcode == 6)) && ((len == 2) || (len == 4)))
3392 | 	{
3393 | 	  t += bsprintf(t, ": %u", (len == 2) ? get_u16(data) : get_u32(data));
3394 | 	  goto done;
3395 | 	}
3396 | 
3397 |       if ((code == 2) && (subcode == 11) && (len == 1))
3398 |         {
3399 | 	  t += bsprintf(t, " (%s)", bgp_format_role_name(get_u8(data)));
3400 | 	  goto done;
3401 |         }
3402 | 
3403 |       /* RFC 9003 - shutdown communication */
3404 |       if (((code == 6) && ((subcode == 2) || (subcode == 4))))
3405 | 	if (bgp_handle_message(p, data, len, &t))
3406 | 	  goto done;
3407 | 
3408 |       *t++ = ':';
3409 |       *t++ = ' ';
3410 |       if (len > 128)
3411 | 	len = 128;
3412 |       for (i=0; i<len; i++)
3413 | 	t += bsprintf(t, "%02x", data[i]);
3414 |     }
3415 | 
3416 | done:
3417 |   *t = 0;
3418 |   const byte *dsc = bgp_error_dsc(code, subcode);
3419 |   log(L_REMOTE "%s: %s: %s%s", p->p.name, msg, dsc, argbuf);
3420 | }
