3484 |  * bgp_rx_packet() takes a newly received packet and calls the corresponding
3485 |  * packet handler according to the packet type.
3486 |  */
3487 | static void
3488 | bgp_rx_packet(struct bgp_conn *conn, byte *pkt, uint len)
3489 | {
3490 |   byte type = pkt[18];
3491 | 
3492 |   DBG("BGP: Got packet %02x (%d bytes)\n", type, len);
3493 |   conn->bgp->stats.rx_messages++;
3494 |   conn->bgp->stats.rx_bytes += len;
3495 | 
3496 |   if (conn->bgp->p.mrtdump & MD_MESSAGES)
3497 |     bgp_dump_message(conn, pkt, len);
3498 | 
3499 |   switch (type)
3500 |   {
3501 |   case PKT_OPEN:		return bgp_rx_open(conn, pkt, len);
3502 |   case PKT_UPDATE:		return bgp_rx_update(conn, pkt, len);
3503 |   case PKT_NOTIFICATION:	return bgp_rx_notification(conn, pkt, len);
3504 |   case PKT_KEEPALIVE:		return bgp_rx_keepalive(conn);
3505 |   case PKT_ROUTE_REFRESH:	return bgp_rx_route_refresh(conn, pkt, len);
3506 |   default:			bgp_error(conn, 1, 3, pkt+18, 1);
3507 |   }
3508 | }
3509 | 
3510 | /**
3511 |  * bgp_rx - handle received data
3512 |  * @sk: socket
3513 |  * @size: amount of data received
3514 |  *
3515 |  * bgp_rx() is called by the socket layer whenever new data arrive from
3516 |  * the underlying TCP connection. It assembles the data fragments to packets,
3517 |  * checks their headers and framing and passes complete packets to
3518 |  * bgp_rx_packet().
3519 |  */
3520 | int
3521 | bgp_rx(sock *sk, uint size)
3522 | {
3523 |   struct bgp_conn *conn = sk->data;
3524 | 
3525 |   byte *pkt_start = sk->rbuf;
3526 |   byte *end = pkt_start + size;
3527 |   uint i, len;
3528 | 
3529 |   DBG("BGP: RX hook: Got %d bytes\n", size);
3530 |   while (end >= pkt_start + BGP_HEADER_LENGTH)
3531 |     {
3532 |       if ((conn->state == BS_CLOSE) || (conn->sk != sk))
3533 | 	return 0;
3534 |       for(i=0; i<16; i++)
3535 | 	if (pkt_start[i] != 0xff)
3536 | 	  {
3537 | 	    bgp_error(conn, 1, 1, NULL, 0);
3538 | 	    break;
3539 | 	  }
3540 |       len = get_u16(pkt_start+16);
3541 |       if ((len < BGP_HEADER_LENGTH) || (len > bgp_max_packet_length(conn)))
3542 | 	{
3543 | 	  bgp_error(conn, 1, 2, pkt_start+16, 2);
3544 | 	  break;
3545 | 	}
3546 |       if (end < pkt_start + len)
3547 | 	break;
3548 |       bgp_rx_packet(conn, pkt_start, len);
3549 |       pkt_start += len;
3550 |     }
3551 |   if (pkt_start != sk->rbuf)
3552 |     {
3553 |       memmove(sk->rbuf, pkt_start, end - pkt_start);
3554 |       sk->rpos = sk->rbuf + (end - pkt_start);
3555 |     }
3556 |   return 0;
3557 | }

