 230 | static int
 231 | bgp_af_caps_cmp(const void *X, const void *Y)
 232 | {
 233 |   const struct bgp_af_caps *x = X, *y = Y;
 234 |   return (x->afi < y->afi) ? -1 : (x->afi > y->afi) ? 1 : 0;
 235 | }
