 245 | void
 246 | bgp_prepare_capabilities(struct bgp_conn *conn)
 247 | {
 248 |   struct bgp_proto *p = conn->bgp;
 249 |   struct bgp_channel *c;
 250 |   struct bgp_caps *caps;
 251 |   struct bgp_af_caps *ac;
 252 | 
 253 |   if (!p->cf->capabilities)
 254 |   {
 255 |     /* Just prepare empty local_caps */
 256 |     conn->local_caps = bgp_alloc_capabilities(p, 0);
 257 |     return;
 258 |   }
 259 | 
 260 |   /* Prepare bgp_caps structure */
 261 |   int n = list_length(&p->p.channels);
 262 |   caps = bgp_alloc_capabilities(p, n);
 263 |   conn->local_caps = caps;
 264 | 
 265 |   caps->as4_support = p->cf->enable_as4;
 266 |   caps->ext_messages = p->cf->enable_extended_messages;
 267 |   caps->route_refresh = p->cf->enable_refresh;
 268 |   caps->enhanced_refresh = p->cf->enable_refresh && p->cf->enable_enhanced_refresh;
 269 |   caps->role = p->cf->local_role;
 270 | 
 271 |   if (caps->as4_support)
 272 |     caps->as4_number = p->public_as;
 273 | 
 274 |   if (p->cf->gr_mode)
 275 |   {
 276 |     caps->gr_aware = 1;
 277 |     caps->gr_time = p->cf->gr_time;
 278 |     caps->gr_flags = p->p.gr_recovery ? BGP_GRF_RESTART : 0;
 279 |   }
 280 | 
 281 |   if (p->cf->llgr_mode)
 282 |     caps->llgr_aware = 1;
 283 | 
 284 |   if (p->cf->enable_hostname && p->hostname)
 285 |   {
 286 |     size_t length = strlen(p->hostname);
 287 |     char *hostname = mb_allocz(p->p.pool, length+1);
 288 |     memcpy(hostname, p->hostname, length+1);
 289 |     caps->hostname = hostname;
 290 |   }
 291 | 
 292 |   /* Allocate and fill per-AF fields */
 293 |   BGP_WALK_CHANNELS(p, c)
 294 |   {
 295 |     ac = &caps->af_data[caps->af_count++];
 296 |     ac->afi = c->afi;
 297 |     ac->ready = 1;
 298 | 
 299 |     ac->ext_next_hop = bgp_channel_is_ipv4(c) && c->cf->ext_next_hop;
 300 |     caps->any_ext_next_hop |= ac->ext_next_hop;
 301 | 
 302 |     ac->add_path = c->cf->add_path;
 303 |     caps->any_add_path |= ac->add_path;
 304 | 
 305 |     if (c->cf->gr_able)
 306 |     {
 307 |       ac->gr_able = 1;
 308 | 
 309 |       if (p->p.gr_recovery)
 310 | 	ac->gr_af_flags |= BGP_GRF_FORWARDING;
 311 |     }
 312 | 
 313 |     if (c->cf->llgr_able)
 314 |     {
 315 |       ac->llgr_able = 1;
 316 |       ac->llgr_time = c->cf->llgr_time;
 317 | 
 318 |       if (p->p.gr_recovery)
 319 | 	ac->llgr_flags |= BGP_LLGRF_FORWARDING;
 320 |     }
 321 |   }
 322 | 
 323 |   /* Sort capability fields by AFI/SAFI */
 324 |   qsort(caps->af_data, caps->af_count, sizeof(struct bgp_af_caps), bgp_af_caps_cmp);
 325 | }
 326 | 
 327 | static byte *
 328 | bgp_write_capabilities(struct bgp_conn *conn, byte *buf)
 329 | {
 330 |   struct bgp_proto *p = conn->bgp;
 331 |   struct bgp_caps *caps = conn->local_caps;
 332 |   struct bgp_af_caps *ac;
 333 |   byte *buf_head = buf;
 334 |   byte *data;
 335 | 
 336 |   /* Create capability list in buffer */
 337 | 
 338 |   /*
 339 |    * Note that max length is ~ 22+21*af_count. With max 12 channels that is
 340 |    * 274. We are limited just by buffer size (4096, minus header), as we support
 341 |    * extended optional parameres. Therefore, we have enough space for expansion.
 342 |    */
 343 | 
 344 |   WALK_AF_CAPS(caps, ac)
 345 |     if (ac->ready)
 346 |     {
 347 |       *buf++ = 1;		/* Capability 1: Multiprotocol extensions */
 348 |       *buf++ = 4;		/* Capability data length */
 349 |       put_af4(buf, ac->afi);
 350 |       buf += 4;
 351 |     }
 352 | 
 353 |   if (caps->route_refresh)
 354 |   {
 355 |     *buf++ = 2;			/* Capability 2: Support for route refresh */
 356 |     *buf++ = 0;			/* Capability data length */
 357 |   }
 358 | 
 359 |   if (caps->any_ext_next_hop)
 360 |   {
 361 |     *buf++ = 5;			/* Capability 5: Support for extended next hop */
 362 |     *buf++ = 0;			/* Capability data length, will be fixed later */
 363 |     data = buf;
 364 | 
 365 |     WALK_AF_CAPS(caps, ac)
 366 |       if (ac->ext_next_hop)
 367 |       {
 368 | 	put_af4(buf, ac->afi);
 369 | 	put_u16(buf+4, BGP_AFI_IPV6);
 370 | 	buf += 6;
 371 |       }
 372 | 
 373 |     data[-1] = buf - data;
 374 |   }
 375 | 
 376 |   if (caps->ext_messages)
 377 |   {
 378 |     *buf++ = 6;			/* Capability 6: Support for extended messages */
 379 |     *buf++ = 0;			/* Capability data length */
 380 |   }
 381 | 
 382 |   if (caps->role != BGP_ROLE_UNDEFINED)
 383 |   {
 384 |     *buf++ = 9;			/* Capability 9: Announce chosen BGP role */
 385 |     *buf++ = 1;			/* Capability data length */
 386 |     *buf++ = caps->role;
 387 |   }
 388 | 
 389 |   if (caps->gr_aware)
 390 |   {
 391 |     *buf++ = 64;		/* Capability 64: Support for graceful restart */
 392 |     *buf++ = 0;			/* Capability data length, will be fixed later */
 393 |     data = buf;
 394 | 
 395 |     put_u16(buf, caps->gr_time);
 396 |     buf[0] |= caps->gr_flags;
 397 |     buf += 2;
 398 | 
 399 |     WALK_AF_CAPS(caps, ac)
 400 |       if (ac->gr_able)
 401 |       {
 402 | 	put_af3(buf, ac->afi);
 403 | 	buf[3] = ac->gr_af_flags;
 404 | 	buf += 4;
 405 |       }
 406 | 
 407 |     data[-1] = buf - data;
 408 |   }
 409 | 
 410 |   if (caps->as4_support)
 411 |   {
 412 |     *buf++ = 65;		/* Capability 65: Support for 4-octet AS number */
 413 |     *buf++ = 4;			/* Capability data length */
 414 |     put_u32(buf, p->public_as);
 415 |     buf += 4;
 416 |   }
 417 | 
 418 |   if (caps->any_add_path)
 419 |   {
 420 |     *buf++ = 69;		/* Capability 69: Support for ADD-PATH */
 421 |     *buf++ = 0;			/* Capability data length, will be fixed later */
 422 |     data = buf;
 423 | 
 424 |     WALK_AF_CAPS(caps, ac)
 425 |       if (ac->add_path)
 426 |       {
 427 | 	put_af3(buf, ac->afi);
 428 | 	buf[3] = ac->add_path;
 429 | 	buf += 4;
 430 |       }
 431 | 
 432 |     data[-1] = buf - data;
 433 |   }
 434 | 
 435 |   if (caps->enhanced_refresh)
 436 |   {
 437 |     *buf++ = 70;		/* Capability 70: Support for enhanced route refresh */
 438 |     *buf++ = 0;			/* Capability data length */
 439 |   }
 440 | 
 441 |   if (caps->llgr_aware)
 442 |   {
 443 |     *buf++ = 71;		/* Capability 71: Support for long-lived graceful restart */
 444 |     *buf++ = 0;			/* Capability data length, will be fixed later */
 445 |     data = buf;
 446 | 
 447 |     WALK_AF_CAPS(caps, ac)
 448 |       if (ac->llgr_able)
 449 |       {
 450 | 	put_af3(buf, ac->afi);
 451 | 	buf[3] = ac->llgr_flags;
 452 | 	put_u24(buf+4, ac->llgr_time);
 453 | 	buf += 7;
 454 |       }
 455 | 
 456 |     data[-1] = buf - data;
 457 |   }
 458 | 
 459 |   if (caps->hostname)
 460 |   {
 461 |     *buf++ = 73;                /* Capability 73: Hostname */
 462 |     *buf++ = 0;			/* Capability data length */
 463 |     data = buf;
 464 | 
 465 |     /* Hostname */
 466 |     size_t length = strlen(caps->hostname);
 467 |     *buf++ = length;
 468 |     memcpy(buf, caps->hostname, length);
 469 |     buf += length;
 470 | 
 471 |     /* Domain, not implemented */
 472 |     *buf++ = 0;
 473 | 
 474 |     data[-1] = buf - data;
 475 |   }
 476 | 
 477 |   caps->length = buf - buf_head;
 478 | 
 479 |   return buf;
 480 | }
 481 | 
 482 | static int
 483 | bgp_read_capabilities(struct bgp_conn *conn, byte *pos, int len)
 484 | {
 485 |   struct bgp_proto *p = conn->bgp;
 486 |   struct bgp_caps *caps;
 487 |   struct bgp_af_caps *ac;
 488 |   uint err_subcode = 0;
 489 |   int i, cl;
 490 |   u32 af;
 491 | 
 492 |   if (!conn->remote_caps)
 493 |     caps = bgp_alloc_capabilities(p, 1);
 494 |   else
 495 |   {
 496 |     caps = conn->remote_caps;
 497 |     conn->remote_caps = NULL;
 498 |   }
 499 | 
 500 |   caps->length += len;
 501 | 
 502 |   while (len > 0)
 503 |   {
 504 |     if (len < 2 || len < (2 + pos[1]))
 505 |       goto err;
 506 | 
 507 |     /* Capability length */
 508 |     cl = pos[1];
 509 | 
 510 |     /* Capability type */
 511 |     switch (pos[0])
 512 |     {
 513 |     case  1: /* Multiprotocol capability, RFC 4760 */
 514 |       if (cl != 4)
 515 | 	goto err;
 516 | 
 517 |       af = get_af4(pos+2);
 518 |       ac = bgp_get_af_caps(&caps, af);
 519 |       ac->ready = 1;
 520 |       break;
 521 | 
 522 |     case  2: /* Route refresh capability, RFC 2918 */
 523 |       if (cl != 0)
 524 | 	goto err;
 525 | 
 526 |       caps->route_refresh = 1;
 527 |       break;
 528 | 
 529 |     case  5: /* Extended next hop encoding capability, RFC 8950 */
 530 |       if (cl % 6)
 531 | 	goto err;
 532 | 
 533 |       for (i = 0; i < cl; i += 6)
 534 |       {
 535 | 	/* Specified only for IPv4 prefixes with IPv6 next hops */
 536 | 	if ((get_u16(pos+2+i+0) != BGP_AFI_IPV4) ||
 537 | 	    (get_u16(pos+2+i+4) != BGP_AFI_IPV6))
 538 | 	  continue;
 539 | 
 540 | 	af = get_af4(pos+2+i);
 541 | 	ac = bgp_get_af_caps(&caps, af);
 542 | 	ac->ext_next_hop = 1;
 543 |       }
 544 |       break;
 545 | 
 546 |     case  6: /* Extended message length capability, RFC 8654 */
 547 |       if (cl != 0)
 548 | 	goto err;
 549 | 
 550 |       caps->ext_messages = 1;
 551 |       break;
 552 | 
 553 |     case  9: /* BGP role capability, RFC 9234 */
 554 |       if (cl != 1)
 555 |         goto err;
 556 | 
 557 |       /* Reserved value */
 558 |       if (pos[2] == BGP_ROLE_UNDEFINED)
 559 |       { err_subcode = 11; goto err; }
 560 | 
 561 |       /* Multiple inconsistent values */
 562 |       if ((caps->role != BGP_ROLE_UNDEFINED) && (caps->role != pos[2]))
 563 |       { err_subcode = 11; goto err; }
 564 | 
 565 |       caps->role = pos[2];
 566 |       break;
 567 | 
 568 |     case 64: /* Graceful restart capability, RFC 4724 */
 569 |       if (cl % 4 != 2)
 570 | 	goto err;
 571 | 
 572 |       /* Only the last instance is valid */
 573 |       WALK_AF_CAPS(caps, ac)
 574 |       {
 575 | 	ac->gr_able = 0;
 576 | 	ac->gr_af_flags = 0;
 577 |       }
 578 | 
 579 |       caps->gr_aware = 1;
 580 |       caps->gr_flags = pos[2] & 0xf0;
 581 |       caps->gr_time = get_u16(pos + 2) & 0x0fff;
 582 | 
 583 |       for (i = 2; i < cl; i += 4)
 584 |       {
 585 | 	af = get_af3(pos+2+i);
 586 | 	ac = bgp_get_af_caps(&caps, af);
 587 | 	ac->gr_able = 1;
 588 | 	ac->gr_af_flags = pos[2+i+3];
 589 |       }
 590 |       break;
 591 | 
 592 |     case 65: /* AS4 capability, RFC 6793 */
 593 |       if (cl != 4)
 594 | 	goto err;
 595 | 
 596 |       caps->as4_support = 1;
 597 |       caps->as4_number = get_u32(pos + 2);
 598 |       break;
 599 | 
 600 |     case 69: /* ADD-PATH capability, RFC 7911 */
 601 |       if (cl % 4)
 602 | 	goto err;
 603 | 
 604 |       for (i = 0; i < cl; i += 4)
 605 |       {
 606 | 	byte val = pos[2+i+3];
 607 | 	if (!val || (val > BGP_ADD_PATH_FULL))
 608 | 	{
 609 | 	  log(L_WARN "%s: Got ADD-PATH capability with unknown value %u, ignoring",
 610 | 	      p->p.name, val);
 611 | 	  break;
 612 | 	}
 613 |       }
 614 | 
 615 |       for (i = 0; i < cl; i += 4)
 616 |       {
 617 | 	af = get_af3(pos+2+i);
 618 | 	ac = bgp_get_af_caps(&caps, af);
 619 | 	ac->add_path = pos[2+i+3];
 620 |       }
 621 |       break;
 622 | 
 623 |     case 70: /* Enhanced route refresh capability, RFC 7313 */
 624 |       if (cl != 0)
 625 | 	goto err;
 626 | 
 627 |       caps->enhanced_refresh = 1;
 628 |       break;
 629 | 
 630 |     case 71: /* Long lived graceful restart capability, RFC 9494 */
 631 |       if (cl % 7)
 632 | 	goto err;
 633 | 
 634 |       /* Presumably, only the last instance is valid */
 635 |       WALK_AF_CAPS(caps, ac)
 636 |       {
 637 | 	ac->llgr_able = 0;
 638 | 	ac->llgr_flags = 0;
 639 | 	ac->llgr_time = 0;
 640 |       }
 641 | 
 642 |       caps->llgr_aware = 1;
 643 | 
 644 |       for (i = 0; i < cl; i += 7)
 645 |       {
 646 | 	af = get_af3(pos+2+i);
 647 | 	ac = bgp_get_af_caps(&caps, af);
 648 | 	ac->llgr_able = 1;
 649 | 	ac->llgr_flags = pos[2+i+3];
 650 | 	ac->llgr_time = get_u24(pos + 2+i+4);
 651 |       }
 652 |       break;
 653 | 
 654 |     case 73: /* Hostname, RFC draft */
 655 |       if ((cl < 2) || (cl < 2 + pos[2]))
 656 |         goto err;
 657 | 
 658 |       int length = pos[2];
 659 |       char *hostname = mb_allocz(p->p.pool, length+1);
 660 |       memcpy(hostname, pos + 3, length);
 661 |       hostname[length] = 0;
 662 | 
 663 |       for (i = 0; i < length; i++)
 664 |         if (hostname[i] < ' ')
 665 |           hostname[i] = ' ';
 666 | 
 667 |       caps->hostname = hostname;
 668 | 
 669 |       /* We can safely ignore all other capabilities */
 670 |     }
 671 | 
 672 |     ADVANCE(pos, len, 2 + cl);
 673 |   }
 674 | 
 675 |   /* The LLGR capability must be advertised together with the GR capability,
 676 |      otherwise it must be disregarded */
 677 |   if (!caps->gr_aware && caps->llgr_aware)
 678 |   {
 679 |     caps->llgr_aware = 0;
 680 |     WALK_AF_CAPS(caps, ac)
 681 |     {
 682 |       ac->llgr_able = 0;
 683 |       ac->llgr_flags = 0;
 684 |       ac->llgr_time = 0;
 685 |     }
 686 |   }
 687 | 
 688 |   conn->remote_caps = caps;
 689 |   return 0;
 690 | 
 691 | err:
 692 |   mb_free(caps);
 693 |   bgp_error(conn, 2, err_subcode, NULL, 0);
 694 |   return -1;
 695 | }
 696 | 
 697 | int
 698 | bgp_check_capabilities(struct bgp_conn *conn)
 699 | {
 700 |   struct bgp_proto *p = conn->bgp;
 701 |   struct bgp_caps *local = conn->local_caps;
 702 |   struct bgp_caps *remote = conn->remote_caps;
 703 |   struct bgp_channel *c;
 704 |   int count = 0;
 705 | 
 706 |   /* This is partially overlapping with bgp_conn_enter_established_state(),
 707 |      but we need to run this just after we receive OPEN message */
 708 | 
 709 |   if (p->cf->require_refresh && !remote->route_refresh)
 710 |     return 0;
 711 | 
 712 |   if (p->cf->require_enhanced_refresh && !remote->enhanced_refresh)
 713 |     return 0;
 714 | 
 715 |   if (p->cf->require_as4 && !remote->as4_support)
 716 |     return 0;
 717 | 
 718 |   if (p->cf->require_extended_messages && !remote->ext_messages)
 719 |     return 0;
 720 | 
 721 |   if (p->cf->require_hostname && !remote->hostname)
 722 |     return 0;
 723 | 
 724 |   if (p->cf->require_gr && !remote->gr_aware)
 725 |     return 0;
 726 | 
 727 |   if (p->cf->require_llgr && !remote->llgr_aware)
 728 |     return 0;
 729 | 
 730 |   /* No check for require_roles, as it uses error code 2.11 instead of 2.7 */
 731 | 
 732 |   BGP_WALK_CHANNELS(p, c)
 733 |   {
 734 |     const struct bgp_af_caps *loc = bgp_find_af_caps(local,  c->afi);
 735 |     const struct bgp_af_caps *rem = bgp_find_af_caps(remote, c->afi);
 736 | 
 737 |     /* Find out whether this channel will be active */
 738 |     int active = loc->ready && rem->ready;
 739 | 
 740 |     /* Mandatory must be active */
 741 |     if (c->cf->mandatory && !active)
 742 |       return 0;
 743 | 
 744 |     if (active)
 745 |     {
 746 |       if (c->cf->require_ext_next_hop && !rem->ext_next_hop)
 747 | 	return 0;
 748 | 
 749 |       if (c->cf->require_add_path && (loc->add_path & BGP_ADD_PATH_RX) && !(rem->add_path & BGP_ADD_PATH_TX))
 750 | 	return 0;
 751 | 
 752 |       if (c->cf->require_add_path && (loc->add_path & BGP_ADD_PATH_TX) && !(rem->add_path & BGP_ADD_PATH_RX))
 753 | 	return 0;
 754 | 
 755 |       count++;
 756 |     }
 757 |   }
 758 | 
 759 |   /* We need at least one channel active */
 760 |   if (!count)
 761 |     return 0;
 762 | 
 763 |   return 1;
 764 | }
 765 | 
 766 | static int
 767 | bgp_read_options(struct bgp_conn *conn, byte *pos, uint len, uint rest)
 768 | {
 769 |   struct bgp_proto *p = conn->bgp;
 770 |   int ext = 0;
 771 | 
 772 |   /* Handle extended length, RFC 9072 */
 773 |   if ((len > 0) && (rest > 0) && (pos[0] == 255))
 774 |   {
 775 |     if (rest < 3)
 776 |       goto err;
 777 | 
 778 |     /* Update pos/len to describe optional data */
 779 |     len = get_u16(pos+1);
 780 |     ext = 1;
 781 |     pos += 3;
 782 |     rest -= 3;
 783 |   }
 784 | 
 785 |   /* Verify that optional data fits into OPEN packet */
 786 |   if (len > rest)
 787 |     goto err;
 788 | 
 789 |   /* Length of option parameter header */
 790 |   uint hlen = ext ? 3 : 2;
 791 | 
 792 |   while (len > 0)
 793 |   {
 794 |     if (len < hlen)
 795 |       goto err;
 796 | 
 797 |     uint otype = get_u8(pos);
 798 |     uint olen = ext ? get_u16(pos+1) : get_u8(pos+1);
 799 | 
 800 |     if (len < (hlen + olen))
 801 |       goto err;
 802 | 
 803 |     if (otype == 2)
 804 |     {
 805 |       /* BGP capabilities, RFC 5492 */
 806 |       if (p->cf->capabilities)
 807 | 	if (bgp_read_capabilities(conn, pos + hlen, olen) < 0)
 808 | 	  return -1;
 809 |     }
 810 |     else
 811 |     {
 812 |       /* Unknown option */
 813 |       bgp_error(conn, 2, 4, pos, hlen + olen);
 814 |       return -1;
 815 |     }
 816 | 
 817 |     ADVANCE(pos, len, hlen + olen);
 818 |   }
 819 | 
 820 |   /* Prepare empty caps if no capability option was announced */
 821 |   if (!conn->remote_caps)
 822 |     conn->remote_caps = bgp_alloc_capabilities(p, 0);
 823 | 
 824 |   return 0;
 825 | 
 826 | err:
 827 |   bgp_error(conn, 2, 0, NULL, 0);
 828 |   return -1;
 829 | }
