 831 | static byte *
 832 | bgp_copy_open(struct bgp_proto *p, const byte *pkt, uint len)
 833 | {
 834 |   char *buf = mb_alloc(p->p.pool, len - BGP_HEADER_LENGTH);
 835 |   memcpy(buf, pkt + BGP_HEADER_LENGTH, len - BGP_HEADER_LENGTH);
 836 |   return buf;
 837 | }
 838 | 
 839 | static byte *
 840 | bgp_create_open(struct bgp_conn *conn, byte *buf)
 841 | {
 842 |   struct bgp_proto *p = conn->bgp;
 843 | 
 844 |   BGP_TRACE(D_PACKETS, "Sending OPEN(ver=%d,as=%d,hold=%d,id=%08x)",
 845 | 	    BGP_VERSION, p->public_as, p->cf->hold_time, p->local_id);
 846 | 
 847 |   buf[0] = BGP_VERSION;
 848 |   put_u16(buf+1, (p->public_as < 0xFFFF) ? p->public_as : AS_TRANS);
 849 |   put_u16(buf+3, p->cf->hold_time);
 850 |   put_u32(buf+5, p->local_id);
 851 | 
 852 |   if (p->cf->capabilities)
 853 |   {
 854 |     /* Prepare local_caps and write capabilities to buffer */
 855 |     byte *pos = buf+12;
 856 |     byte *end = bgp_write_capabilities(conn, pos);
 857 |     uint len = end - pos;
 858 | 
 859 |     if (len < 254)
 860 |     {
 861 |       buf[9] = len + 2;		/* Optional parameters length */
 862 |       buf[10] = 2;		/* Option 2: Capability list */
 863 |       buf[11] = len;		/* Option data length */
 864 |     }
 865 |     else /* Extended length, RFC 9072 */
 866 |     {
 867 |       /* Move capabilities 4 B forward */
 868 |       memmove(buf + 16, pos, len);
 869 |       pos = buf + 16;
 870 |       end = pos + len;
 871 | 
 872 |       buf[9] = 255;		/* Non-ext OP length, fake */
 873 |       buf[10] = 255;		/* Non-ext OP type, signals extended length */
 874 |       put_u16(buf+11, len + 3);	/* Extended optional parameters length */
 875 |       buf[13] = 2;		/* Option 2: Capability list */
 876 |       put_u16(buf+14, len);	/* Option extended data length */
 877 |     }
 878 | 
 879 |     return end;
 880 |   }
 881 |   else
 882 |   {
 883 |     buf[9] = 0;			/* No optional parameters */
 884 |     return buf + 10;
 885 |   }
 886 | 
 887 |   return buf;
 888 | }
