 890 | static void
 891 | bgp_rx_open(struct bgp_conn *conn, byte *pkt, uint len)
 892 | {
 893 |   struct bgp_proto *p = conn->bgp;
 894 |   struct bgp_conn *other;
 895 |   u32 asn, hold, id;
 896 | 
 897 |   /* Check state */
 898 |   if (conn->state != BS_OPENSENT)
 899 |   { bgp_error(conn, 5, fsm_err_subcode[conn->state], NULL, 0); return; }
 900 | 
 901 |   /* Check message length */
 902 |   if (len < 29)
 903 |   { bgp_error(conn, 1, 2, pkt+16, 2); return; }
 904 | 
 905 |   if (pkt[19] != BGP_VERSION)
 906 |   { u16 val = BGP_VERSION; bgp_error(conn, 2, 1, (byte *) &val, 2); return; }
 907 | 
 908 |   asn = get_u16(pkt+20);
 909 |   hold = get_u16(pkt+22);
 910 |   id = get_u32(pkt+24);
 911 |   BGP_TRACE(D_PACKETS, "Got OPEN(as=%d,hold=%d,id=%R)", asn, hold, id);
 912 | 
 913 |   conn->remote_open_msg = bgp_copy_open(p, pkt, len);
 914 |   conn->remote_open_length = len - BGP_HEADER_LENGTH;
 915 | 
 916 |   if (bgp_read_options(conn, pkt+29, pkt[28], len-29) < 0)
 917 |     return;
 918 | 
 919 |   /* RFC 4271 4.2 - hold time must be either 0 or at least 3 */
 920 |   if (hold > 0 && hold < 3)
 921 |   { bgp_error(conn, 2, 6, pkt+22, 2); return; }
 922 | 
 923 |   /* Compute effective hold and keepalive times */
 924 |   uint hold_time = MIN(hold, p->cf->hold_time);
 925 |   uint keepalive_time = p->cf->keepalive_time ?
 926 |     (p->cf->keepalive_time * hold_time / p->cf->hold_time) :
 927 |     hold_time / 3;
 928 | 
 929 |   uint send_hold_time = (p->cf->send_hold_time >= 0) ?
 930 |     (p->cf->send_hold_time * hold_time / p->cf->hold_time) :
 931 |     2 * hold_time;
 932 | 
 933 |   /* Keepalive time might be rounded down to zero */
 934 |   if (hold_time && !keepalive_time)
 935 |     keepalive_time = 1;
 936 | 
 937 |   /* Check effective values against configured minimums */
 938 |   if ((hold_time < p->cf->min_hold_time) ||
 939 |       (keepalive_time < p->cf->min_keepalive_time))
 940 |   { bgp_error(conn, 2, 6, pkt+22, 2); return; }
 941 | 
 942 |   /* RFC 6286 2.2 - router ID is nonzero and AS-wide unique */
 943 |   if (!id || (p->is_internal && id == p->local_id))
 944 |   { bgp_error(conn, 2, 3, pkt+24, -4); return; }
 945 | 
 946 |   /* RFC 5492 5 - check for required capabilities */
 947 |   if (p->cf->capabilities && !bgp_check_capabilities(conn))
 948 |   { bgp_error(conn, 2, 7, NULL, 0); return; }
 949 | 
 950 |   struct bgp_caps *caps = conn->remote_caps;
 951 | 
 952 |   if (caps->as4_support)
 953 |   {
 954 |     u32 as4 = caps->as4_number;
 955 | 
 956 |     if ((as4 != asn) && (asn != AS_TRANS))
 957 |       log(L_WARN "%s: Peer advertised inconsistent AS numbers", p->p.name);
 958 | 
 959 |     /* When remote ASN is unspecified, it must be external one */
 960 |     if (p->remote_as ? (as4 != p->remote_as) : (as4 == p->local_as))
 961 |     { as4 = htonl(as4); bgp_error(conn, 2, 2, (byte *) &as4, 4); return; }
 962 | 
 963 |     conn->received_as = as4;
 964 |   }
 965 |   else
 966 |   {
 967 |     if (p->remote_as ? (asn != p->remote_as) : (asn == p->local_as))
 968 |     { bgp_error(conn, 2, 2, pkt+20, 2); return; }
 969 | 
 970 |     conn->received_as = asn;
 971 |   }
 972 | 
 973 |   /* RFC 9234 4.2 - check role agreement */
 974 |   u8 local_role = p->cf->local_role;
 975 |   u8 neigh_role = caps->role;
 976 | 
 977 |   if ((local_role != BGP_ROLE_UNDEFINED) &&
 978 |       (neigh_role != BGP_ROLE_UNDEFINED) &&
 979 |       !((local_role == BGP_ROLE_PEER && neigh_role == BGP_ROLE_PEER) ||
 980 | 	(local_role == BGP_ROLE_CUSTOMER && neigh_role == BGP_ROLE_PROVIDER) ||
 981 | 	(local_role == BGP_ROLE_PROVIDER && neigh_role == BGP_ROLE_CUSTOMER) ||
 982 | 	(local_role == BGP_ROLE_RS_CLIENT && neigh_role == BGP_ROLE_RS_SERVER) ||
 983 | 	(local_role == BGP_ROLE_RS_SERVER && neigh_role == BGP_ROLE_RS_CLIENT)))
 984 |   { bgp_error(conn, 2, 11, &neigh_role, -1); return; }
 985 | 
 986 |   if ((p->cf->require_roles) && (neigh_role == BGP_ROLE_UNDEFINED))
 987 |   { bgp_error(conn, 2, 11, &neigh_role, -1); return; }
 988 | 
 989 |   /* Check the other connection */
 990 |   other = (conn == &p->outgoing_conn) ? &p->incoming_conn : &p->outgoing_conn;
 991 |   switch (other->state)
 992 |   {
 993 |   case BS_CONNECT:
 994 |   case BS_ACTIVE:
 995 |     /* Stop outgoing connection attempts */
 996 |     bgp_conn_enter_idle_state(other);
 997 |     break;
 998 | 
 999 |   case BS_IDLE:
1000 |   case BS_OPENSENT:
1001 |   case BS_CLOSE:
1002 |     break;
1003 | 
1004 |   case BS_OPENCONFIRM:
1005 |     /*
1006 |      * Description of collision detection rules in RFC 4271 is confusing and
1007 |      * contradictory, but it is essentially:
1008 |      *
1009 |      * 1. Router with higher ID is dominant
1010 |      * 2. If both have the same ID, router with higher ASN is dominant [RFC6286]
1011 |      * 3. When both connections are in OpenConfirm state, one initiated by
1012 |      *    the dominant router is kept.
1013 |      *
1014 |      * The first line in the expression below evaluates whether the neighbor
1015 |      * is dominant, the second line whether the new connection was initiated
1016 |      * by the neighbor. If both are true (or both are false), we keep the new
1017 |      * connection, otherwise we keep the old one.
1018 |      */
1019 |     if (((p->local_id < id) || ((p->local_id == id) && (p->public_as < p->remote_as)))
1020 | 	== (conn == &p->incoming_conn))
1021 |     {
1022 |       /* Should close the other connection */
1023 |       BGP_TRACE(D_EVENTS, "Connection collision, giving up the other connection");
1024 |       bgp_error(other, 6, 7, NULL, 0);
1025 |       break;
1026 |     }
1027 |     /* Fall thru */
1028 |   case BS_ESTABLISHED:
1029 |     /* Should close this connection */
1030 |     BGP_TRACE(D_EVENTS, "Connection collision, giving up this connection");
1031 |     bgp_error(conn, 6, 7, NULL, 0);
1032 |     return;
1033 | 
1034 |   default:
1035 |     bug("bgp_rx_open: Unknown state");
1036 |   }
1037 | 
1038 |   /* Update our local variables */
1039 |   conn->hold_time = hold_time;
1040 |   conn->keepalive_time = keepalive_time;
1041 |   conn->send_hold_time = send_hold_time;
1042 |   conn->as4_session = conn->local_caps->as4_support && caps->as4_support;
1043 |   conn->ext_messages = conn->local_caps->ext_messages && caps->ext_messages;
1044 |   p->remote_id = id;
1045 | 
1046 |   DBG("BGP: Hold timer set to %d, keepalive to %d, AS to %d, ID to %x, AS4 session to %d\n",
1047 |       conn->hold_time, conn->keepalive_time, p->remote_as, p->remote_id, conn->as4_session);
1048 | 
1049 |   bgp_schedule_packet(conn, NULL, PKT_KEEPALIVE);
1050 |   bgp_start_timer(conn->hold_timer, conn->hold_time);
1051 |   bgp_start_timer(conn->send_hold_timer, conn->send_hold_time);
1052 |   bgp_conn_enter_openconfirm_state(conn);
1053 | }
