1124 | static void
1125 | bgp_apply_mpls_labels(struct bgp_parse_state *s, rta *a, u32 *labels, uint lnum)
1126 | {
1127 |   if (lnum > MPLS_MAX_LABEL_STACK)
1128 |   {
1129 |     REPORT("Too many MPLS labels ($u)", lnum);
1130 | 
1131 |     a->dest = RTD_UNREACHABLE;
1132 |     a->hostentry = NULL;
1133 |     a->nh = (struct nexthop) { };
1134 |     return;
1135 |   }
1136 | 
1137 |   /* Handle implicit NULL as empty MPLS stack */
1138 |   if ((lnum == 1) && (labels[0] == BGP_MPLS_NULL))
1139 |     lnum = 0;
1140 | 
1141 |   if (s->channel->cf->gw_mode == GW_DIRECT)
1142 |   {
1143 |     a->nh.labels = lnum;
1144 |     memcpy(a->nh.label, labels, 4*lnum);
1145 |   }
1146 |   else /* GW_RECURSIVE */
1147 |   {
1148 |     mpls_label_stack ms;
1149 | 
1150 |     ms.len = lnum;
1151 |     memcpy(ms.stack, labels, 4*lnum);
1152 |     rta_apply_hostentry(a, s->hostentry, &ms);
1153 |   }
1154 | }
