1384 | static void
1385 | bgp_decode_next_hop_ip(struct bgp_parse_state *s, byte *data, uint len, rta *a)
1386 | {
1387 |   struct bgp_channel *c = s->channel;
1388 |   struct adata *ad = lp_alloc_adata(s->pool, 32);
1389 |   ip_addr *nh = (void *) ad->data;
1390 | 
1391 |   if (len == 4)
1392 |   {
1393 |     nh[0] = ipa_from_ip4(get_ip4(data));
1394 |     nh[1] = IPA_NONE;
1395 |   }
1396 |   else if (len == 16)
1397 |   {
1398 |     nh[0] = ipa_from_ip6(get_ip6(data));
1399 |     nh[1] = IPA_NONE;
1400 | 
1401 |     if (ipa_is_link_local(nh[0]))
1402 |     { nh[1] = nh[0]; nh[0] = IPA_NONE; }
1403 |   }
1404 |   else if (len == 32)
1405 |   {
1406 |     nh[0] = ipa_from_ip6(get_ip6(data));
1407 |     nh[1] = ipa_from_ip6(get_ip6(data+16));
1408 | 
1409 |     if (ipa_is_link_local(nh[0]))
1410 |     { nh[1] = nh[0]; nh[0] = IPA_NONE; }
1411 | 
1412 |     if (ipa_is_ip4(nh[0]) || !ipa_is_link_local(nh[1]))
1413 |       nh[1] = IPA_NONE;
1414 |   }
1415 |   else
1416 |     bgp_parse_error(s, 9);
1417 | 
1418 |   if (ipa_zero(nh[1]))
1419 |     ad->length = 16;
1420 | 
1421 |   if ((bgp_channel_is_ipv4(c) != ipa_is_ip4(nh[0])) && !c->ext_next_hop)
1422 |     WITHDRAW(BAD_NEXT_HOP MISMATCHED_AF, nh[0], c->desc->name);
1423 | 
1424 |   // XXXX validate next hop
1425 | 
1426 |   bgp_set_attr_ptr(&(a->eattrs), s->pool, BA_NEXT_HOP, 0, ad);
1427 |   bgp_apply_next_hop(s, a, nh[0], nh[1]);
1428 | }
