1657 | static uint
1658 | bgp_encode_nlri_ip4(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, uint size)
1659 | {
1660 |   byte *pos = buf;
1661 | 
1662 |   while (!EMPTY_LIST(buck->prefixes) && (size >= BGP_NLRI_MAX))
1663 |   {
1664 |     struct bgp_prefix *px = HEAD(buck->prefixes);
1665 |     struct net_addr_ip4 *net = (void *) px->net;
1666 | 
1667 |     /* Encode path ID */
1668 |     if (s->add_path)
1669 |     {
1670 |       put_u32(pos, px->path_id);
1671 |       ADVANCE(pos, size, 4);
1672 |     }
1673 | 
1674 |     /* Encode prefix length */
1675 |     *pos = net->pxlen;
1676 |     ADVANCE(pos, size, 1);
1677 | 
1678 |     /* Encode MPLS labels */
1679 |     if (s->mpls)
1680 |       bgp_encode_mpls_labels(s, s->mpls_labels, &pos, &size, pos - 1);
1681 | 
1682 |     /* Encode prefix body */
1683 |     ip4_addr a = ip4_hton(net->prefix);
1684 |     uint b = (net->pxlen + 7) / 8;
1685 |     memcpy(pos, &a, b);
1686 |     ADVANCE(pos, size, b);
1687 | 
1688 |     if (!s->sham)
1689 |       bgp_free_prefix(s->channel, px);
1690 |     else
1691 |       rem_node(&px->buck_node);
1692 |   }
1693 | 
1694 |   return pos - buf;
1695 | }
