1987 |       if (len < 5)
1988 | 	bgp_parse_error(s, 1);
1989 | 
1990 |       path_id = get_u32(pos);
1991 |       ADVANCE(pos, len, 4);
1992 |     }
1993 | 
1994 |     /* Decode prefix length */
1995 |     uint l = *pos;
1996 |     ADVANCE(pos, len, 1);
1997 | 
1998 |     if (len < ((l + 7) / 8))
1999 |       bgp_parse_error(s, 1);
2000 | 
2001 |     /* Decode MPLS labels */
2002 |     if (s->mpls)
2003 |       bgp_decode_mpls_labels(s, &pos, &len, &l, a);
2004 | 
2005 |     /* Decode route distinguisher */
2006 |     if (l < 64)
2007 |       bgp_parse_error(s, 1);
2008 | 
2009 |     vpn_rd rd = get_rd(pos);
2010 |     ADVANCE(pos, len, 8);
2011 |     l -= 64;
2012 | 
2013 |     if (l > IP6_MAX_PREFIX_LENGTH)
2014 |       bgp_parse_error(s, 10);
2015 | 
2016 |     /* Decode prefix body */
2017 |     ip6_addr addr = IP6_NONE;
2018 |     uint b = (l + 7) / 8;
2019 |     memcpy(&addr, pos, b);
2020 |     ADVANCE(pos, len, b);
2021 | 
2022 |     net = NET_ADDR_VPN6(ip6_ntoh(addr), l, rd);
2023 |     net_normalize_vpn6(&net);
2024 | 
2025 |     // XXXX validate prefix
2026 | 
2027 |     bgp_rte_update(s, (net_addr *) &net, path_id, a);
2028 |   }
2029 | }
