2032 | static uint
2033 | bgp_encode_nlri_flow4(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, uint size)
2034 | {
2035 |   byte *pos = buf;
2036 | 
2037 |   while (!EMPTY_LIST(buck->prefixes) && (size >= 4))
2038 |   {
2039 |     struct bgp_prefix *px = HEAD(buck->prefixes);
2040 |     struct net_addr_flow4 *net = (void *) px->net;
2041 |     uint flen = net->length - sizeof(net_addr_flow4);
2042 | 
2043 |     /* Encode path ID */
2044 |     if (s->add_path)
2045 |     {
2046 |       put_u32(pos, px->path_id);
2047 |       ADVANCE(pos, size, 4);
2048 |     }
2049 | 
2050 |     if (flen > size)
2051 |       break;
2052 | 
2053 |     /* Copy whole flow data including length */
2054 |     memcpy(pos, net->data, flen);
2055 |     ADVANCE(pos, size, flen);
2056 | 
2057 |     if (!s->sham)
2058 |       bgp_free_prefix(s->channel, px);
