2066 | static void
2067 | bgp_decode_nlri_flow4(struct bgp_parse_state *s, byte *pos, uint len, rta *a)
2068 | {
2069 |   while (len)
2070 |   {
2071 |     u32 path_id = 0;
2072 | 
2073 |     /* Decode path ID */
2074 |     if (s->add_path)
2075 |     {
2076 |       if (len < 4)
2077 | 	bgp_parse_error(s, 1);
2078 | 
2079 |       path_id = get_u32(pos);
2080 |       ADVANCE(pos, len, 4);
2081 |     }
2082 | 
2083 |     if (len < 2)
2084 |       bgp_parse_error(s, 1);
2085 | 
2086 |     /* Decode flow length */
2087 |     uint hlen = flow_hdr_length(pos);
2088 |     uint dlen = flow_read_length(pos);
2089 |     uint flen = hlen + dlen;
2090 |     byte *data = pos + hlen;
2091 | 
2092 |     if (len < flen)
2093 |       bgp_parse_error(s, 1);
2094 | 
2095 |     /* Validate flow data */
2096 |     enum flow_validated_state r = flow4_validate(data, dlen);
2097 |     if (r != FLOW_ST_VALID)
2098 |     {
2099 |       log(L_REMOTE "%s: Invalid flow route: %s", s->proto->p.name, flow_validated_state_str(r));
2100 |       bgp_parse_error(s, 1);
2101 |     }
2102 | 
2103 |     ip4_addr px = IP4_NONE;
2104 |     uint pxlen = 0;
2105 | 
2106 |     /* Decode dst prefix */
2107 |     if (data[0] == FLOW_TYPE_DST_PREFIX)
2108 |     {
2109 |       px = flow_read_ip4_part(data);
2110 |       pxlen = flow_read_pxlen(data);
2111 |     }
2112 | 
2113 |     /* Prepare the flow */
2114 |     net_addr *n = alloca(sizeof(struct net_addr_flow4) + flen);
2115 |     net_fill_flow4(n, px, pxlen, pos, flen);
2116 |     ADVANCE(pos, len, flen);
2117 | 
2118 |     /* Apply validation procedure per RFC 8955 (6) */
2119 |     if (a && s->channel->cf->validate)
2120 |       bgp_apply_flow_validation(s, n, a);
2121 | 
2122 |     bgp_rte_update(s, n, path_id, a);
2123 |   }
