2412 | static byte *
2413 | bgp_create_mp_reach(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, byte *end)
2414 | {
2415 |   /*
2416 |    *	2 B	IPv4 Withdrawn Routes Length (zero)
2417 |    *	---	IPv4 Withdrawn Routes NLRI (unused)
2418 |    *	2 B	Total Path Attribute Length
2419 |    *	1 B	MP_REACH_NLRI hdr - Attribute Flags
2420 |    *	1 B	MP_REACH_NLRI hdr - Attribute Type Code
2421 |    *	2 B	MP_REACH_NLRI hdr - Length of Attribute Data
2422 |    *	2 B	MP_REACH_NLRI data - Address Family Identifier
2423 |    *	1 B	MP_REACH_NLRI data - Subsequent Address Family Identifier
2424 |    *	1 B	MP_REACH_NLRI data - Length of Next Hop Network Address
2425 |    *	var	MP_REACH_NLRI data - Network Address of Next Hop
2426 |    *	1 B	MP_REACH_NLRI data - Reserved (zero)
2427 |    *	var	MP_REACH_NLRI data - Network Layer Reachability Information
2428 |    *	var	Rest of Path Attributes
2429 |    *	---	IPv4 Network Layer Reachability Information (unused)
2430 |    */
2431 | 
2432 |   int lh, lr, la;	/* Lengths of next hop, NLRI and attributes */
2433 | 
2434 |   /* Begin of MP_REACH_NLRI atribute */
2435 |   buf[4] = BAF_OPTIONAL | BAF_EXT_LEN;
2436 |   buf[5] = BA_MP_REACH_NLRI;
2437 |   put_u16(buf+6, 0);		/* Will be fixed later */
2438 |   put_af3(buf+8, s->channel->afi);
2439 |   byte *pos = buf+11;
2440 | 
2441 |   /* Encode attributes to temporary buffer */
2442 |   byte *abuf = alloca(MAX_ATTRS_LENGTH);
2443 |   la = bgp_encode_attrs(s, buck->eattrs, abuf, abuf + MAX_ATTRS_LENGTH);
2444 |   if (la < 0)
2445 |   {
2446 |     /* Attribute list too long */
2447 |     if (!s->sham)
2448 |       bgp_withdraw_bucket(s->channel, buck);
2449 |     return NULL;
2450 |   }
2451 | 
2452 |   /* Encode the next hop */
2453 |   lh = bgp_encode_next_hop(s, s->mp_next_hop, pos+1);
2454 |   *pos = lh;
2455 |   pos += 1+lh;
2456 | 
2457 |   /* Reserved field */
2458 |   *pos++ = 0;
2459 | 
2460 |   /* Encode the NLRI */
2461 |   lr = bgp_encode_nlri(s, buck, pos, end - la);
2462 |   pos += lr;
2463 | 
2464 |   /* End of MP_REACH_NLRI atribute, update data length */
2465 |   put_u16(buf+6, pos-buf-8);
2466 | 
2467 |   /* Copy remaining attributes */
2468 |   memcpy(pos, abuf, la);
2469 |   pos += la;
2470 | 
2471 |   /* Initial UPDATE fields */
2472 |   put_u16(buf+0, 0);
2473 |   put_u16(buf+2, pos-buf-4);
2474 | 
2475 |   return pos;
2476 | }
