2745 | static inline void
2746 | bgp_decode_nlri(struct bgp_parse_state *s, u32 afi, byte *nlri, uint len, ea_list *ea, byte *nh, uint nh_len)
2747 | {
2748 |   struct bgp_channel *c = bgp_get_channel(s->proto, afi);
2749 |   rta *a = NULL;
2750 | 
2751 |   if (!c)
2752 |     DISCARD(BAD_AFI, BGP_AFI(afi), BGP_SAFI(afi));
2753 | 
2754 |   s->channel = c;
2755 |   s->add_path = c->add_path_rx;
2756 |   s->mpls = c->desc->mpls;
2757 | 
2758 |   s->last_id = 0;
2759 |   s->last_src = s->proto->p.main_source;
2760 | 
2761 |   /*
2762 |    * IPv4 BGP and MP-BGP may be used together in one update, therefore we do not
2763 |    * add BA_NEXT_HOP in bgp_decode_attrs(), but we add it here independently for
2764 |    * IPv4 BGP and MP-BGP. We undo the attribute (and possibly others attached by
2765 |    * decode_next_hop hooks) by restoring a->eattrs afterwards.
2766 |    */
2767 | 
2768 |   if (ea)
2769 |   {
2770 |     a = allocz(RTA_MAX_SIZE);
2771 | 
2772 |     a->source = RTS_BGP;
2773 |     a->scope = SCOPE_UNIVERSE;
2774 |     a->from = s->proto->remote_ip;
2775 |     a->eattrs = ea;
2776 |     a->pref = c->c.preference;
2777 | 
2778 |     c->desc->decode_next_hop(s, nh, nh_len, a);
2779 |     bgp_finish_attrs(s, a);
2780 | 
2781 |     /* Handle withdraw during next hop decoding */
2782 |     if (s->err_withdraw)
2783 |       a = NULL;
2784 |   }
2785 | 
2786 |   c->desc->decode_nlri(s, nlri, len, a);
2787 | 
2788 |   rta_free(s->cached_rta);
2789 |   s->cached_rta = NULL;
2790 | }
