3106 | /**
3107 |  * bgp_fire_tx - transmit packets
3108 |  * @conn: connection
3109 |  *
3110 |  * Whenever the transmit buffers of the underlying TCP connection
3111 |  * are free and we have any packets queued for sending, the socket functions
3112 |  * call bgp_fire_tx() which takes care of selecting the highest priority packet
3113 |  * queued (Notification > Keepalive > Open > Update), assembling its header
3114 |  * and body and sending it to the connection.
3115 |  */
3116 | static int
3117 | bgp_fire_tx(struct bgp_conn *conn)
3118 | {
3119 |   struct bgp_proto *p = conn->bgp;
3120 |   struct bgp_channel *c;
3121 |   byte *buf, *pkt, *end;
3122 |   uint s;
3123 | 
3124 |   if (!conn->sk)
