1056 | /*
1057 |  *	Next hop handling
1058 |  */
1059 | 
1060 | #define REPORT(msg, args...) \
1061 |   ({ log(L_REMOTE "%s: " msg, s->proto->p.name, ## args); })
1062 | 
1063 | #define DISCARD(msg, args...) \
1064 |   ({ REPORT(msg, ## args); return; })
1065 | 
1066 | #define WITHDRAW(msg, args...) \
1067 |   ({ REPORT(msg, ## args); s->err_withdraw = 1; return; })
1068 | 
1069 | #define REJECT(msg, args...)						\
1070 |   ({ log(L_ERR "%s: " msg, s->proto->p.name, ## args); s->err_reject = 1; return; })
1071 | 
1072 | #define BAD_AFI		"Unexpected AF <%u/%u> in UPDATE"
1073 | #define BAD_NEXT_HOP	"Invalid NEXT_HOP attribute"
1074 | #define NO_NEXT_HOP	"Missing NEXT_HOP attribute"
1075 | #define NO_LABEL_STACK	"Missing MPLS stack"
1076 | 
1077 | #define MISMATCHED_AF	" - mismatched address family (%I for %s)"
1078 | 
1079 | static void
1080 | bgp_apply_next_hop(struct bgp_parse_state *s, rta *a, ip_addr gw, ip_addr ll)
1081 | {
1082 |   struct bgp_proto *p = s->proto;
1083 |   struct bgp_channel *c = s->channel;
1084 | 
1085 |   if (c->cf->gw_mode == GW_DIRECT)
1086 |   {
1087 |     neighbor *nbr = NULL;
1088 | 
1089 |     /* GW_DIRECT -> single_hop -> p->neigh != NULL */
1090 |     if (ipa_nonzero2(gw))
1091 |       nbr = neigh_find(&p->p, gw, NULL, 0);
1092 |     else if (ipa_nonzero(ll))
1093 |       nbr = neigh_find(&p->p, ll, p->neigh->iface, 0);
1094 |     else
1095 |       WITHDRAW(BAD_NEXT_HOP " - zero address");
1096 | 
1097 |     if (!nbr)
1098 |       WITHDRAW(BAD_NEXT_HOP " - address %I not directly reachable", ipa_nonzero(gw) ? gw : ll);
1099 | 
1100 |     if (nbr->scope == SCOPE_HOST)
1101 |       WITHDRAW(BAD_NEXT_HOP " - address %I is local", nbr->addr);
1102 | 
1103 |     a->dest = RTD_UNICAST;
1104 |     a->nh.gw = nbr->addr;
1105 |     a->nh.iface = nbr->iface;
1106 |     a->igp_metric = c->cf->cost;
1107 |   }
1108 |   else /* GW_RECURSIVE */
1109 |   {
1110 |     if (ipa_zero2(gw))
1111 |       WITHDRAW(BAD_NEXT_HOP " - zero address");
1112 | 
1113 |     rtable *tab = ipa_is_ip4(gw) ? c->igp_table_ip4 : c->igp_table_ip6;
1114 |     ip_addr lla = (c->cf->next_hop_prefer == NHP_LOCAL) ? ll : IPA_NONE;
1115 |     s->hostentry = rt_get_hostentry(tab, gw, lla, c->c.table);
1116 | 
1117 |     if (!s->mpls)
1118 |       rta_apply_hostentry(a, s->hostentry, NULL);
1119 | 
1120 |     /* With MPLS, hostentry is applied later in bgp_apply_mpls_labels() */
1121 |   }
1122 | }
1123 | 
1124 | static void
1125 | bgp_apply_mpls_labels(struct bgp_parse_state *s, rta *a, u32 *labels, uint lnum)
1126 | {
1127 |   if (lnum > MPLS_MAX_LABEL_STACK)
1128 |   {
1129 |     REPORT("Too many MPLS labels ($u)", lnum);
1130 | 
1131 |     a->dest = RTD_UNREACHABLE;
1132 |     a->hostentry = NULL;
1133 |     a->nh = (struct nexthop) { };
1134 |     return;
1135 |   }
1136 | 
1137 |   /* Handle implicit NULL as empty MPLS stack */
1138 |   if ((lnum == 1) && (labels[0] == BGP_MPLS_NULL))
1139 |     lnum = 0;
1140 | 
1141 |   if (s->channel->cf->gw_mode == GW_DIRECT)
1142 |   {
1143 |     a->nh.labels = lnum;
1144 |     memcpy(a->nh.label, labels, 4*lnum);
1145 |   }
1146 |   else /* GW_RECURSIVE */
1147 |   {
1148 |     mpls_label_stack ms;
1149 | 
1150 |     ms.len = lnum;
1151 |     memcpy(ms.stack, labels, 4*lnum);
1152 |     rta_apply_hostentry(a, s->hostentry, &ms);
1153 |   }
1154 | }
