1316 | static uint
1317 | bgp_prepare_link_local_next_hop(struct bgp_write_state *s, ip_addr *nh)
1318 | {
1319 |   /*
1320 |    * We have link-local next-hop in nh[1]
1321 |    *
1322 |    * Possible variants:
1323 |    * [ ::, fe80::XX ] - BIRD's default/internal (LLNH_NATIVE)
1324 |    * [ fe80::XX ] - draft-white-linklocal-capability (LLNH_SINGLE)
1325 |    * [ fe80::XX, fe80::XX ] - Used in JunoOS (LLNH_DOUBLE)
1326 |    */
1327 | 
1328 |   switch (s->llnh_format)
1329 |   {
1330 |   case LLNH_NATIVE:
1331 |     return 32;
1332 | 
1333 |   case LLNH_SINGLE:
1334 |     nh[0] = nh[1];
1335 |     return 16;
1336 | 
1337 |   case LLNH_DOUBLE:
1338 |     nh[0] = nh[1];
1339 |     return 32;
1340 | 
1341 |   default:
1342 |     ASSERT(0);
1343 |     return 32;
1344 |   }
1345 | }
1346 | 
1347 | static uint
1348 | bgp_encode_next_hop_ip(struct bgp_write_state *s, eattr *a, byte *buf, uint size UNUSED)
1349 | {
1350 |   /* This function is used only for MP-BGP, see bgp_encode_next_hop() for IPv4 BGP */
1351 |   ip_addr *nh = (void *) a->u.ptr->data;
1352 |   uint len = a->u.ptr->length;
1353 | 
1354 |   ASSERT((len == 16) || (len == 32));
1355 | 
1356 |   /*
1357 |    * Both IPv4 and IPv6 next hops can be used (with ext_next_hop enabled). This
1358 |    * is specified in RFC 8950 for IPv4 and in RFC 4798 for IPv6. The difference
1359 |    * is that IPv4 address is directly encoded with IPv4 NLRI, but as IPv4-mapped
1360 |    * IPv6 address with IPv6 NLRI.
1361 |    */
1362 | 
1363 |   if (bgp_channel_is_ipv4(s->channel) && ipa_is_ip4(nh[0]))
1364 |   {
1365 |     put_ip4(buf, ipa_to_ip4(nh[0]));
1366 |     return 4;
1367 |   }
1368 | 
1369 |   /* Handle variants of link-local-only next hop */
1370 |   if (ipa_zero(nh[0]) && (len == 32))
1371 |   {
1372 |     nh = alloca_copy(nh, 32);
1373 |     len = bgp_prepare_link_local_next_hop(s, nh);
1374 |   }
1375 | 
1376 |   put_ip6(buf, ipa_to_ip6(nh[0]));
1377 | 
1378 |   if (len == 32)
1379 |     put_ip6(buf+16, ipa_to_ip6(nh[1]));
1380 | 
1381 |   return len;
1382 | }
1383 | 
1384 | static void
1385 | bgp_decode_next_hop_ip(struct bgp_parse_state *s, byte *data, uint len, rta *a)
1386 | {
1387 |   struct bgp_channel *c = s->channel;
1388 |   struct adata *ad = lp_alloc_adata(s->pool, 32);
1389 |   ip_addr *nh = (void *) ad->data;
1390 | 
1391 |   if (len == 4)
1392 |   {
1393 |     nh[0] = ipa_from_ip4(get_ip4(data));
1394 |     nh[1] = IPA_NONE;
1395 |   }
1396 |   else if (len == 16)
1397 |   {
1398 |     nh[0] = ipa_from_ip6(get_ip6(data));
1399 |     nh[1] = IPA_NONE;
1400 | 
1401 |     if (ipa_is_link_local(nh[0]))
1402 |     { nh[1] = nh[0]; nh[0] = IPA_NONE; }
1403 |   }
1404 |   else if (len == 32)
1405 |   {
1406 |     nh[0] = ipa_from_ip6(get_ip6(data));
1407 |     nh[1] = ipa_from_ip6(get_ip6(data+16));
1408 | 
1409 |     if (ipa_is_link_local(nh[0]))
1410 |     { nh[1] = nh[0]; nh[0] = IPA_NONE; }
1411 | 
1412 |     if (ipa_is_ip4(nh[0]) || !ipa_is_link_local(nh[1]))
1413 |       nh[1] = IPA_NONE;
1414 |   }
1415 |   else
1416 |     bgp_parse_error(s, 9);
1417 | 
1418 |   if (ipa_zero(nh[1]))
1419 |     ad->length = 16;
1420 | 
1421 |   if ((bgp_channel_is_ipv4(c) != ipa_is_ip4(nh[0])) && !c->ext_next_hop)
1422 |     WITHDRAW(BAD_NEXT_HOP MISMATCHED_AF, nh[0], c->desc->name);
1423 | 
1424 |   // XXXX validate next hop
1425 | 
1426 |   bgp_set_attr_ptr(&(a->eattrs), s->pool, BA_NEXT_HOP, 0, ad);
1427 |   bgp_apply_next_hop(s, a, nh[0], nh[1]);
1428 | }
