2380 | #define MAX_ATTRS_LENGTH (end-buf+BGP_HEADER_LENGTH - 1024)
2381 | 
2382 | static byte *
2383 | bgp_create_ip_reach(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, byte *end)
2384 | {
2385 |   /*
2386 |    *	2 B	Withdrawn Routes Length (zero)
2387 |    *	---	IPv4 Withdrawn Routes NLRI (unused)
2388 |    *	2 B	Total Path Attribute Length
2389 |    *	var	Path Attributes
2390 |    *	var	IPv4 Network Layer Reachability Information
2391 |    */
2392 | 
2393 |   int lr, la;
2394 | 
2395 |   la = bgp_encode_attrs(s, buck->eattrs, buf+4, buf + MAX_ATTRS_LENGTH);
2396 |   if (la < 0)
2397 |   {
2398 |     /* Attribute list too long */
2399 |     if (!s->sham)
2400 |       bgp_withdraw_bucket(s->channel, buck);
2401 |     return NULL;
2402 |   }
2403 | 
2404 |   put_u16(buf+0, 0);
2405 |   put_u16(buf+2, la);
2406 | 
2407 |   lr = bgp_encode_nlri(s, buck, buf+4+la, end);
2408 | 
2409 |   return buf+4+la+lr;
2410 | }
