2792 | static void
2793 | bgp_rx_update(struct bgp_conn *conn, byte *pkt, uint len)
2794 | {
2795 |   struct bgp_proto *p = conn->bgp;
2796 |   ea_list *ea = NULL;
2797 | 
2798 |   BGP_TRACE_RL(&rl_rcv_update, D_PACKETS, "Got UPDATE");
2799 |   p->last_rx_update = current_time();
2800 |   p->stats.rx_updates++;
2801 | 
2802 |   /* Workaround for some BGP implementations that skip initial KEEPALIVE */
2803 |   if (conn->state == BS_OPENCONFIRM)
2804 |     bgp_conn_enter_established_state(conn);
2805 | 
2806 |   if (conn->state != BS_ESTABLISHED)
2807 |   { bgp_error(conn, 5, fsm_err_subcode[conn->state], NULL, 0); return; }
2808 | 
2809 |   bgp_start_timer(conn->hold_timer, conn->hold_time);
2810 | 
2811 |   struct lp_state tmpp;
2812 |   lp_save(tmp_linpool, &tmpp);
2813 | 
2814 |   /* Initialize parse state */
2815 |   struct bgp_parse_state s = {
2816 |     .proto = p,
2817 |     .pool = tmp_linpool,
2818 |     .as4_session = p->as4_session,
2819 |   };
2820 | 
2821 |   /* Parse error handler */
2822 |   if (setjmp(s.err_jmpbuf))
2823 |   {
2824 |     bgp_error(conn, 3, s.err_subcode, NULL, 0);
2825 |     goto done;
2826 |   }
2827 | 
2828 |   /* Check minimal length */
2829 |   if (len < 23)
2830 |   { bgp_error(conn, 1, 2, pkt+16, 2); return; }
2831 | 
2832 |   /* Skip fixed header */
2833 |   uint pos = 19;
2834 | 
2835 |   /*
2836 |    *	UPDATE message format
2837 |    *
2838 |    *	2 B	IPv4 Withdrawn Routes Length
2839 |    *	var	IPv4 Withdrawn Routes NLRI
2840 |    *	2 B	Total Path Attribute Length
2841 |    *	var	Path Attributes
2842 |    *	var	IPv4 Reachable Routes NLRI
2843 |    */
2844 | 
2845 |   s.ip_unreach_len = get_u16(pkt + pos);
2846 |   s.ip_unreach_nlri = pkt + pos + 2;
2847 |   pos += 2 + s.ip_unreach_len;
2848 | 
2849 |   if (pos + 2 > len)
2850 |     bgp_parse_error(&s, 1);
2851 | 
2852 |   s.attr_len = get_u16(pkt + pos);
2853 |   s.attrs = pkt + pos + 2;
2854 |   pos += 2 + s.attr_len;
2855 | 
2856 |   if (pos > len)
2857 |     bgp_parse_error(&s, 1);
2858 | 
2859 |   s.ip_reach_len = len - pos;
2860 |   s.ip_reach_nlri = pkt + pos;
2861 | 
2862 |   if (s.attr_len)
2863 |     ea = bgp_decode_attrs(&s, s.attrs, s.attr_len);
2864 |   else
2865 |     ea = NULL;
2866 | 
2867 |   /* Check for End-of-RIB marker */
2868 |   if (!s.attr_len && !s.ip_unreach_len && !s.ip_reach_len)
2869 |   { bgp_rx_end_mark(&s, BGP_AF_IPV4); goto done; }
2870 | 
2871 |   /* Check for MP End-of-RIB marker */
2872 |   if ((s.attr_len < 8) && !s.ip_unreach_len && !s.ip_reach_len &&
2873 |       !s.mp_reach_len && !s.mp_unreach_len && s.mp_unreach_af)
2874 |   { bgp_rx_end_mark(&s, s.mp_unreach_af); goto done; }
2875 | 
2876 |   if (s.ip_unreach_len)
2877 |     bgp_decode_nlri(&s, BGP_AF_IPV4, s.ip_unreach_nlri, s.ip_unreach_len, NULL, NULL, 0);
2878 | 
2879 |   if (s.mp_unreach_len)
2880 |     bgp_decode_nlri(&s, s.mp_unreach_af, s.mp_unreach_nlri, s.mp_unreach_len, NULL, NULL, 0);
2881 | 
2882 |   s.reach_nlri_step = 1;
2883 | 
2884 |   if (s.ip_reach_len)
2885 |     bgp_decode_nlri(&s, BGP_AF_IPV4, s.ip_reach_nlri, s.ip_reach_len,
2886 | 		    ea, s.ip_next_hop_data, s.ip_next_hop_len);
2887 | 
2888 |   if (s.mp_reach_len)
2889 |     bgp_decode_nlri(&s, s.mp_reach_af, s.mp_reach_nlri, s.mp_reach_len,
2890 | 		    ea, s.mp_next_hop_data, s.mp_next_hop_len);
2891 | 
2892 | done:
2893 |   rta_free(s.cached_rta);
2894 |   lp_restore(tmp_linpool, &tmpp);
2895 |   return;
2896 | }
