2964 | static inline byte *
2965 | bgp_create_route_refresh(struct bgp_channel *c, byte *buf)
2966 | {
2967 |   struct bgp_proto *p = (void *) c->c.proto;
2968 | 
2969 |   BGP_TRACE(D_PACKETS, "Sending ROUTE-REFRESH");
2970 | 
2971 |   /* Original route refresh request, RFC 2918 */
2972 |   put_af4(buf, c->afi);
2973 |   buf[2] = BGP_RR_REQUEST;
2974 | 
2975 |   return buf+4;
2976 | }
