2978 | static inline byte *
2979 | bgp_create_begin_refresh(struct bgp_channel *c, byte *buf)
2980 | {
2981 |   struct bgp_proto *p = (void *) c->c.proto;
2982 | 
2983 |   BGP_TRACE(D_PACKETS, "Sending BEGIN-OF-RR");
2984 | 
2985 |   /* Demarcation of beginning of route refresh (BoRR), RFC 7313 */
2986 |   put_af4(buf, c->afi);
2987 |   buf[2] = BGP_RR_BEGIN;
2988 | 
2989 |   return buf+4;
2990 | }
