2992 | static inline byte *
2993 | bgp_create_end_refresh(struct bgp_channel *c, byte *buf)
2994 | {
2995 |   struct bgp_proto *p = (void *) c->c.proto;
2996 | 
2997 |   BGP_TRACE(D_PACKETS, "Sending END-OF-RR");
2998 | 
2999 |   /* Demarcation of ending of route refresh (EoRR), RFC 7313 */
3000 |   put_af4(buf, c->afi);
3001 |   buf[2] = BGP_RR_END;
3002 | 
3003 |   return buf+4;
3004 | }
