3106 | /**
3107 |  * bgp_fire_tx - transmit packets
3108 |  * @conn: connection
3109 |  *
3110 |  * Whenever the transmit buffers of the underlying TCP connection
3111 |  * are free and we have any packets queued for sending, the socket functions
3112 |  * call bgp_fire_tx() which takes care of selecting the highest priority packet
3113 |  * queued (Notification > Keepalive > Open > Update), assembling its header
3114 |  * and body and sending it to the connection.
3115 |  */
3116 | static int
3117 | bgp_fire_tx(struct bgp_conn *conn)
3118 | {
3119 |   struct bgp_proto *p = conn->bgp;
3120 |   struct bgp_channel *c;
3121 |   byte *buf, *pkt, *end;
3122 |   uint s;
3123 | 
3124 |   if (!conn->sk)
3125 |     return 0;
3126 | 
3127 |   buf = conn->sk->tbuf;
3128 |   pkt = buf + BGP_HEADER_LENGTH;
3129 |   s = conn->packets_to_send;
3130 | 
3131 |   if (s & (1 << PKT_SCHEDULE_CLOSE))
3132 |   {
3133 |     /* We can finally close connection and enter idle state */
3134 |     bgp_conn_enter_idle_state(conn);
3135 |     return 0;
3136 |   }
3137 |   if (s & (1 << PKT_NOTIFICATION))
3138 |   {
3139 |     conn->packets_to_send = 1 << PKT_SCHEDULE_CLOSE;
3140 |     end = bgp_create_notification(conn, pkt);
3141 |     return bgp_send(conn, PKT_NOTIFICATION, end - buf);
3142 |   }
3143 |   else if (s & (1 << PKT_OPEN))
3144 |   {
3145 |     conn->packets_to_send &= ~(1 << PKT_OPEN);
3146 |     end = bgp_create_open(conn, pkt);
3147 | 
3148 |     conn->local_open_msg = bgp_copy_open(p, buf, end - buf);
3149 |     conn->local_open_length = end - buf - BGP_HEADER_LENGTH;
3150 | 
3151 |     return bgp_send(conn, PKT_OPEN, end - buf);
3152 |   }
3153 |   else if (s & (1 << PKT_KEEPALIVE))
3154 |   {
3155 |     conn->packets_to_send &= ~(1 << PKT_KEEPALIVE);
3156 |     BGP_TRACE(D_PACKETS, "Sending KEEPALIVE");
3157 |     bgp_start_timer(conn->keepalive_timer, conn->keepalive_time);
3158 |     return bgp_send(conn, PKT_KEEPALIVE, BGP_HEADER_LENGTH);
3159 |   }
3160 |   else while (conn->channels_to_send)
3161 |   {
3162 |     c = bgp_get_channel_to_send(p, conn);
3163 |     s = c->packets_to_send;
3164 | 
3165 |     if (s & (1 << PKT_ROUTE_REFRESH))
3166 |     {
3167 |       c->packets_to_send &= ~(1 << PKT_ROUTE_REFRESH);
3168 |       end = bgp_create_route_refresh(c, pkt);
3169 |       return bgp_send(conn, PKT_ROUTE_REFRESH, end - buf);
3170 |     }
3171 |     else if (s & (1 << PKT_BEGIN_REFRESH))
3172 |     {
3173 |       /* BoRR is a subtype of RR, but uses separate bit in packets_to_send */
3174 |       c->packets_to_send &= ~(1 << PKT_BEGIN_REFRESH);
3175 |       end = bgp_create_begin_refresh(c, pkt);
3176 |       return bgp_send(conn, PKT_ROUTE_REFRESH, end - buf);
3177 |     }
3178 |     else if (s & (1 << PKT_UPDATE))
3179 |     {
3180 |       end = bgp_create_update(c, pkt);
3181 |       if (end)
3182 | 	return bgp_send(conn, PKT_UPDATE, end - buf);
3183 | 
3184 |       /* No update to send, perhaps we need to send End-of-RIB or EoRR */
3185 |       c->packets_to_send = 0;
3186 |       conn->channels_to_send &= ~(1 << c->index);
3187 | 
3188 |       if (c->feed_state == BFS_LOADED)
3189 |       {
3190 | 	c->feed_state = BFS_NONE;
3191 | 	end = bgp_create_end_mark(c, pkt);
3192 | 	return bgp_send(conn, PKT_UPDATE, end - buf);
3193 |       }
3194 | 
3195 |       else if (c->feed_state == BFS_REFRESHED)
3196 |       {
3197 | 	c->feed_state = BFS_NONE;
3198 | 	end = bgp_create_end_refresh(c, pkt);
3199 | 	return bgp_send(conn, PKT_ROUTE_REFRESH, end - buf);
3200 |       }
3201 |     }
3202 |     else if (s)
3203 |       bug("Channel packets_to_send: %x", s);
3204 | 
3205 |     c->packets_to_send = 0;
3206 |     conn->channels_to_send &= ~(1 << c->index);
3207 |   }
3208 | 
3209 |   return 0;
3210 | }
