3348 | /* RFC 9003 - shutdown communication message */
3349 | static int
3350 | bgp_handle_message(struct bgp_proto *p, byte *data, uint len, byte **bp)
3351 | {
3352 |   byte *msg = data + 1;
3353 |   uint msg_len = data[0];
3354 |   uint i;
3355 | 
3356 |   /* Handle zero length message */
3357 |   if (msg_len == 0)
3358 |     return 1;
3359 | 
3360 |   /* Handle proper message */
3361 |   if (msg_len + 1 > len)
3362 |     return 0;
3363 | 
3364 |   /* Some elementary cleanup */
3365 |   for (i = 0; i < msg_len; i++)
3366 |     if (msg[i] < ' ')
3367 |       msg[i] = ' ';
3368 | 
3369 |   proto_set_message(&p->p, msg, msg_len);
3370 |   *bp += bsprintf(*bp, ": \"%s\"", p->p.message);
3371 |   return 1;
3372 | }
