  67 | static inline void
  68 | put_af3(byte *buf, u32 id)
  69 | {
  70 |   put_u16(buf, id >> 16);
  71 |   buf[2] = id & 0xff;
  72 | }
  73 | 
  74 | static inline void
  75 | put_af4(byte *buf, u32 id)
  76 | {
  77 |   put_u16(buf, id >> 16);
  78 |   buf[2] = 0;
  79 |   buf[3] = id & 0xff;
  80 | }
  81 | 
  82 | static inline u32
  83 | get_af3(byte *buf)
  84 | {
  85 |   return (get_u16(buf) << 16) | buf[2];
  86 | }
  87 | 
  88 | static inline u32
  89 | get_af4(byte *buf)
  90 | {
  91 |   return (get_u16(buf) << 16) | buf[3];
  92 | }
