  94 | static void
  95 | init_mrt_bgp_data(struct bgp_conn *conn, struct mrt_bgp_data *d)
  96 | {
  97 |   struct bgp_proto *p = conn->bgp;
  98 |   int p_ok = conn->state >= BS_OPENCONFIRM;
  99 | 
 100 |   memset(d, 0, sizeof(struct mrt_bgp_data));
 101 |   d->peer_as = p->remote_as;
 102 |   d->local_as = p->local_as;
 103 |   d->index = (p->neigh && p->neigh->iface) ? p->neigh->iface->index : 0;
 104 |   d->af = ipa_is_ip4(p->remote_ip) ? BGP_AFI_IPV4 : BGP_AFI_IPV6;
 105 |   d->peer_ip = conn->sk ? conn->sk->daddr : IPA_NONE;
 106 |   d->local_ip = conn->sk ? conn->sk->saddr : IPA_NONE;
 107 |   d->as4 = p_ok ? p->as4_session : 0;
 108 | }
