 174 | /* Capability negotiation as per RFC 5492 */
 175 | 
 176 | static const struct bgp_af_caps dummy_af_caps = { };
 177 | static const struct bgp_af_caps basic_af_caps = { .ready = 1 };
 178 | 
 179 | static const struct bgp_af_caps *
 180 | bgp_find_af_caps_(struct bgp_caps *caps, u32 afi)
 181 | {
 182 |   struct bgp_af_caps *ac;
 183 | 
 184 |   WALK_AF_CAPS(caps, ac)
 185 |     if (ac->afi == afi)
 186 |       return ac;
 187 | 
 188 |   return NULL;
 189 | }
 190 | 
 191 | const struct bgp_af_caps *
 192 | bgp_find_af_caps(struct bgp_caps *caps, u32 afi)
 193 | {
 194 |   const struct bgp_af_caps *ac = bgp_find_af_caps_(caps, afi);
 195 | 
 196 |   /* Return proper capability if found */
 197 |   if (ac)
 198 |     return ac;
 199 | 
 200 |   /* Use default if capabilities were not announced */
 201 |   if (!caps->length && (afi == BGP_AF_IPV4))
 202 |     return &basic_af_caps;
 203 | 
 204 |   /* Ignore AFIs that were not announced in multiprotocol capability */
 205 |   return &dummy_af_caps;
 206 | }
 207 | 
 208 | static struct bgp_af_caps *
 209 | bgp_get_af_caps(struct bgp_caps **pcaps, u32 afi)
 210 | {
 211 |   struct bgp_caps *caps = *pcaps;
 212 |   struct bgp_af_caps *ac;
 213 | 
 214 |   WALK_AF_CAPS(caps, ac)
 215 |     if (ac->afi == afi)
 216 |       return ac;
 217 | 
 218 |   uint n = caps->af_count;
 219 |   if (uint_is_pow2(n))
 220 |     *pcaps = caps = mb_realloc(caps, sizeof(struct bgp_caps) +
 221 | 			       (2 * n) * sizeof(struct bgp_af_caps));
 222 | 
 223 |   ac = &caps->af_data[caps->af_count++];
 224 |   memset(ac, 0, sizeof(struct bgp_af_caps));
 225 |   ac->afi = afi;
 226 | 
 227 |   return ac;
 228 | }
