 237 | struct bgp_caps *
 238 | bgp_alloc_capabilities(struct bgp_proto *p, int n)
 239 | {
 240 |   struct bgp_caps *caps = mb_allocz(p->p.pool, sizeof(struct bgp_caps) + n * sizeof(struct bgp_af_caps));
 241 |   caps->role = BGP_ROLE_UNDEFINED;
 242 |   return caps;
