 697 | int
 698 | bgp_check_capabilities(struct bgp_conn *conn)
 699 | {
 700 |   struct bgp_proto *p = conn->bgp;
 701 |   struct bgp_caps *local = conn->local_caps;
 702 |   struct bgp_caps *remote = conn->remote_caps;
 703 |   struct bgp_channel *c;
 704 |   int count = 0;
 705 | 
 706 |   /* This is partially overlapping with bgp_conn_enter_established_state(),
 707 |      but we need to run this just after we receive OPEN message */
 708 | 
 709 |   if (p->cf->require_refresh && !remote->route_refresh)
 710 |     return 0;
 711 | 
 712 |   if (p->cf->require_enhanced_refresh && !remote->enhanced_refresh)
 713 |     return 0;
 714 | 
 715 |   if (p->cf->require_as4 && !remote->as4_support)
 716 |     return 0;
 717 | 
 718 |   if (p->cf->require_extended_messages && !remote->ext_messages)
 719 |     return 0;
 720 | 
 721 |   if (p->cf->require_hostname && !remote->hostname)
 722 |     return 0;
 723 | 
 724 |   if (p->cf->require_gr && !remote->gr_aware)
 725 |     return 0;
 726 | 
 727 |   if (p->cf->require_llgr && !remote->llgr_aware)
 728 |     return 0;
 729 | 
 730 |   /* No check for require_roles, as it uses error code 2.11 instead of 2.7 */
 731 | 
 732 |   BGP_WALK_CHANNELS(p, c)
 733 |   {
 734 |     const struct bgp_af_caps *loc = bgp_find_af_caps(local,  c->afi);
 735 |     const struct bgp_af_caps *rem = bgp_find_af_caps(remote, c->afi);
 736 | 
 737 |     /* Find out whether this channel will be active */
 738 |     int active = loc->ready && rem->ready;
 739 | 
 740 |     /* Mandatory must be active */
 741 |     if (c->cf->mandatory && !active)
 742 |       return 0;
 743 | 
 744 |     if (active)
 745 |     {
 746 |       if (c->cf->require_ext_next_hop && !rem->ext_next_hop)
 747 | 	return 0;
 748 | 
 749 |       if (c->cf->require_add_path && (loc->add_path & BGP_ADD_PATH_RX) && !(rem->add_path & BGP_ADD_PATH_TX))
 750 | 	return 0;
 751 | 
 752 |       if (c->cf->require_add_path && (loc->add_path & BGP_ADD_PATH_TX) && !(rem->add_path & BGP_ADD_PATH_RX))
 753 | 	return 0;
 754 | 
 755 |       count++;
 756 |     }
 757 |   }
 758 | 
 759 |   /* We need at least one channel active */
 760 |   if (!count)
 761 |     return 0;
 762 | 
 763 |   return 1;
 764 | }
