1057 |  *	Next hop handling
1058 |  */
1059 | 
1060 | #define REPORT(msg, args...) \
1061 |   ({ log(L_REMOTE "%s: " msg, s->proto->p.name, ## args); })
1062 | 
1063 | #define DISCARD(msg, args...) \
1064 |   ({ REPORT(msg, ## args); return; })
1065 | 
1066 | #define WITHDRAW(msg, args...) \
1067 |   ({ REPORT(msg, ## args); s->err_withdraw = 1; return; })
1068 | 
1069 | #define REJECT(msg, args...)						\
1070 |   ({ log(L_ERR "%s: " msg, s->proto->p.name, ## args); s->err_reject = 1; return; })
1071 | 
1072 | #define BAD_AFI		"Unexpected AF <%u/%u> in UPDATE"
1073 | #define BAD_NEXT_HOP	"Invalid NEXT_HOP attribute"
1074 | #define NO_NEXT_HOP	"Missing NEXT_HOP attribute"
1075 | #define NO_LABEL_STACK	"Missing MPLS stack"
1076 | 
1077 | #define MISMATCHED_AF	" - mismatched address family (%I for %s)"
