1785 | static void
1786 | bgp_decode_nlri_ip6(struct bgp_parse_state *s, byte *pos, uint len, rta *a)
1787 | {
1788 |   while (len)
1789 |   {
1790 |     net_addr_ip6 net;
1791 |     u32 path_id = 0;
1792 | 
1793 |     /* Decode path ID */
1794 |     if (s->add_path)
1795 |     {
1796 |       if (len < 5)
1797 | 	bgp_parse_error(s, 1);
1798 | 
