2033 | bgp_encode_nlri_flow4(struct bgp_write_state *s, struct bgp_bucket *buck, byte *buf, uint size)
2034 | {
2035 |   byte *pos = buf;
2036 | 
2037 |   while (!EMPTY_LIST(buck->prefixes) && (size >= 4))
2038 |   {
2039 |     struct bgp_prefix *px = HEAD(buck->prefixes);
2040 |     struct net_addr_flow4 *net = (void *) px->net;
2041 |     uint flen = net->length - sizeof(net_addr_flow4);
2042 | 
2043 |     /* Encode path ID */
