2045 |     {
2046 |       put_u32(pos, px->path_id);
2047 |       ADVANCE(pos, size, 4);
2048 |     }
2049 | 
2050 |     if (flen > size)
2051 |       break;
2052 | 
2053 |     /* Copy whole flow data including length */
2054 |     memcpy(pos, net->data, flen);
2055 |     ADVANCE(pos, size, flen);
2056 | 
2057 |     if (!s->sham)
2058 |       bgp_free_prefix(s->channel, px);
2059 |     else
2060 |       rem_node(&px->buck_node);
2061 |   }
2062 | 
2063 |   return pos - buf;
