3058 | static inline struct bgp_channel *
3059 | bgp_get_channel_to_send(struct bgp_proto *p, struct bgp_conn *conn)
3060 | {
3061 |   uint i = conn->last_channel;
3062 | 
3063 |   /* Try the last channel, but at most several times */
3064 |   if ((conn->channels_to_send & (1 << i)) &&
3065 |       (conn->last_channel_count < 16))
3066 |     goto found;
3067 | 
3068 |   /* Find channel with non-zero channels_to_send */
3069 |   do
3070 |   {
3071 |     i++;
3072 |     if (i >= p->channel_count)
3073 |       i = 0;
3074 |   }
3075 |   while (! (conn->channels_to_send & (1 << i)));
3076 | 
3077 |   /* Use that channel */
3078 |   conn->last_channel = i;
3079 |   conn->last_channel_count = 0;
3080 | 
3081 | found:
3082 |   conn->last_channel_count++;
3083 |   return p->channel_map[i];
3084 | }
