3086 | static inline int
3087 | bgp_send(struct bgp_conn *conn, uint type, uint len)
3088 | {
3089 |   sock *sk = conn->sk;
3090 |   byte *buf = sk->tbuf;
3091 | 
3092 |   conn->bgp->stats.tx_messages++;
3093 |   conn->bgp->stats.tx_bytes += len;
3094 | 
3095 |   memset(buf, 0xff, BGP_HDR_MARKER_LENGTH);
3096 |   put_u16(buf+16, len);
3097 |   buf[18] = type;
3098 | 
3099 |   int success = sk_send(sk, len);
3100 |   if (success && ((conn->state == BS_ESTABLISHED) || (conn->state == BS_OPENCONFIRM)))
3101 |     bgp_start_timer(conn->send_hold_timer, conn->send_hold_time);
3102 | 
3103 |   return success;
3104 | }
