3422 | static void
3423 | bgp_rx_notification(struct bgp_conn *conn, byte *pkt, uint len)
3424 | {
3425 |   struct bgp_proto *p = conn->bgp;
3426 | 
3427 |   if (len < 21)
3428 |   { bgp_error(conn, 1, 2, pkt+16, 2); return; }
3429 | 
3430 |   uint code = pkt[19];
3431 |   uint subcode = pkt[20];
3432 |   int err = (code != 6);
3433 | 
3434 |   bgp_log_error(p, BE_BGP_RX, "Received", code, subcode, pkt+21, len-21);
3435 |   bgp_store_error(p, conn, BE_BGP_RX, (code << 16) | subcode);
3436 | 
3437 |   conn->notify_code = code;
3438 |   conn->notify_subcode = subcode;
3439 |   conn->notify_data = pkt+21;
3440 |   conn->notify_size = len-21;
3441 | 
3442 |   bgp_conn_enter_close_state(conn);
3443 |   bgp_schedule_packet(conn, NULL, PKT_SCHEDULE_CLOSE);
3444 | 
3445 |   if (err)
3446 |   {
3447 |     bgp_update_startup_delay(p);
3448 |     bgp_stop(p, 0, NULL, 0);
3449 |   }
3450 |   else
3451 |   {
3452 |     uint subcode_bit = 1 << ((subcode <= 8) ? subcode : 0);
3453 |     if (p->cf->disable_after_cease & subcode_bit)
3454 |     {
3455 |       log(L_INFO "%s: Disabled after Cease notification", p->p.name);
3456 |       p->startup_delay = 0;
3457 |       p->p.disabled = 1;
3458 |     }
3459 |   }
3460 | }
