1079 | static void
1080 | bgp_apply_next_hop(struct bgp_parse_state *s, rta *a, ip_addr gw, ip_addr ll)
1081 | {
1082 |   struct bgp_proto *p = s->proto;
1083 |   struct bgp_channel *c = s->channel;
1084 | 
1085 |   if (c->cf->gw_mode == GW_DIRECT)
1086 |   {
1087 |     neighbor *nbr = NULL;
1088 | 
1089 |     /* GW_DIRECT -> single_hop -> p->neigh != NULL */
1090 |     if (ipa_nonzero2(gw))
1091 |       nbr = neigh_find(&p->p, gw, NULL, 0);
1092 |     else if (ipa_nonzero(ll))
1093 |       nbr = neigh_find(&p->p, ll, p->neigh->iface, 0);
1094 |     else
1095 |       WITHDRAW(BAD_NEXT_HOP " - zero address");
1096 | 
1097 |     if (!nbr)
1098 |       WITHDRAW(BAD_NEXT_HOP " - address %I not directly reachable", ipa_nonzero(gw) ? gw : ll);
1099 | 
1100 |     if (nbr->scope == SCOPE_HOST)
1101 |       WITHDRAW(BAD_NEXT_HOP " - address %I is local", nbr->addr);
1102 | 
1103 |     a->dest = RTD_UNICAST;
1104 |     a->nh.gw = nbr->addr;
1105 |     a->nh.iface = nbr->iface;
1106 |     a->igp_metric = c->cf->cost;
1107 |   }
1108 |   else /* GW_RECURSIVE */
1109 |   {
1110 |     if (ipa_zero2(gw))
1111 |       WITHDRAW(BAD_NEXT_HOP " - zero address");
1112 | 
1113 |     rtable *tab = ipa_is_ip4(gw) ? c->igp_table_ip4 : c->igp_table_ip6;
1114 |     ip_addr lla = (c->cf->next_hop_prefer == NHP_LOCAL) ? ll : IPA_NONE;
1115 |     s->hostentry = rt_get_hostentry(tab, gw, lla, c->c.table);
1116 | 
1117 |     if (!s->mpls)
1118 |       rta_apply_hostentry(a, s->hostentry, NULL);
1119 | 
1120 |     /* With MPLS, hostentry is applied later in bgp_apply_mpls_labels() */
1121 |   }
1122 | }
