1156 | static void
1157 | bgp_apply_flow_validation(struct bgp_parse_state *s, const net_addr *n, rta *a)
1158 | {
1159 |   struct bgp_channel *c = s->channel;
1160 |   int valid = rt_flowspec_check(c->base_table, c->c.table, n, a, s->proto->is_interior);
1161 |   a->dest = valid ? RTD_NONE : RTD_UNREACHABLE;
1162 | 
1163 |   /* Invalidate cached rta if dest changes */
1164 |   if (s->cached_rta && (s->cached_rta->dest != a->dest))
1165 |   {
1166 |     rta_free(s->cached_rta);
1167 |     s->cached_rta = NULL;
1168 |   }
