1171 | static int
1172 | bgp_match_src(struct bgp_export_state *s, int mode)
1173 | {
1174 |   switch (mode)
1175 |   {
1176 |   case NH_NO:		return 0;
1177 |   case NH_ALL:		return 1;
1178 |   case NH_IBGP:		return s->src && s->src->is_internal;
1179 |   case NH_EBGP:		return s->src && !s->src->is_internal;
1180 |   default:		return 0;
1181 |   }
1182 | }
