1184 | static inline int
1185 | bgp_use_next_hop(struct bgp_export_state *s, eattr *a)
1186 | {
1187 |   struct bgp_proto *p = s->proto;
1188 |   struct bgp_channel *c = s->channel;
1189 |   ip_addr *nh = (void *) a->u.ptr->data;
1190 | 
1191 |   /* Handle next hop self option */
1192 |   if (c->cf->next_hop_self && bgp_match_src(s, c->cf->next_hop_self))
1193 |     return 0;
1194 | 
1195 |   /* Handle next hop keep option */
1196 |   if (c->cf->next_hop_keep && bgp_match_src(s, c->cf->next_hop_keep))
1197 |     return 1;
1198 | 
1199 |   /* Keep it when explicitly set in export filter */
1200 |   if (a->fresh)
1201 |     return 1;
1202 | 
1203 |   /* Check for non-matching AF */
1204 |   if ((ipa_is_ip4(*nh) != bgp_channel_is_ipv4(c)) && !c->ext_next_hop)
1205 |     return 0;
1206 | 
1207 |   /* Do not pass NEXT_HOP between different VRFs */
1208 |   if (p->p.vrf_set && s->src && s->src->p.vrf_set && (p->p.vrf != s->src->p.vrf))
1209 |     return 0;
1210 | 
1211 |   /* Keep it when exported to internal peers */
1212 |   if (p->is_interior && ipa_nonzero(*nh))
1213 |     return 1;
1214 | 
1215 |   /* Keep it when forwarded between single-hop BGPs on the same iface */
1216 |   struct iface *ifa = (s->src && s->src->neigh && (s->src->p.proto_state != PS_DOWN)) ?
1217 |     s->src->neigh->iface : NULL;
1218 |   return p->neigh && (p->neigh->iface == ifa);
1219 | }
1220 | 
1221 | static inline int
1222 | bgp_use_gateway(struct bgp_export_state *s)
1223 | {
1224 |   struct bgp_proto *p = s->proto;
1225 |   struct bgp_channel *c = s->channel;
1226 |   rta *ra = s->route->attrs;
1227 | 
1228 |   /* Handle next hop self option - also applies to gateway */
1229 |   if (c->cf->next_hop_self && bgp_match_src(s, c->cf->next_hop_self))
1230 |     return 0;
1231 | 
1232 |   /* We need one valid global gateway */
1233 |   if ((ra->dest != RTD_UNICAST) || ra->nh.next || ipa_zero(ra->nh.gw) || ipa_is_link_local(ra->nh.gw))
1234 |     return 0;
1235 | 
1236 |   /* Check for non-matching AF */
1237 |   if ((ipa_is_ip4(ra->nh.gw) != bgp_channel_is_ipv4(c)) && !c->ext_next_hop)
1238 |     return 0;
1239 | 
1240 |   /* Do not use gateway from different VRF */
1241 |   if (p->p.vrf_set && ra->nh.iface && !if_in_vrf(ra->nh.iface, p->p.vrf))
1242 |     return 0;
1243 | 
1244 |   /* Use it when exported to internal peers */
1245 |   if (p->is_interior)
1246 |     return 1;
1247 | 
1248 |   /* Use it when forwarded to single-hop BGP peer on on the same iface */
1249 |   return p->neigh && (p->neigh->iface == ra->nh.iface);
1250 | }
