1347 | static uint
1348 | bgp_encode_next_hop_ip(struct bgp_write_state *s, eattr *a, byte *buf, uint size UNUSED)
1349 | {
1350 |   /* This function is used only for MP-BGP, see bgp_encode_next_hop() for IPv4 BGP */
1351 |   ip_addr *nh = (void *) a->u.ptr->data;
1352 |   uint len = a->u.ptr->length;
1353 | 
1354 |   ASSERT((len == 16) || (len == 32));
1355 | 
1356 |   /*
1357 |    * Both IPv4 and IPv6 next hops can be used (with ext_next_hop enabled). This
1358 |    * is specified in RFC 8950 for IPv4 and in RFC 4798 for IPv6. The difference
1359 |    * is that IPv4 address is directly encoded with IPv4 NLRI, but as IPv4-mapped
1360 |    * IPv6 address with IPv6 NLRI.
1361 |    */
1362 | 
1363 |   if (bgp_channel_is_ipv4(s->channel) && ipa_is_ip4(nh[0]))
1364 |   {
1365 |     put_ip4(buf, ipa_to_ip4(nh[0]));
1366 |     return 4;
1367 |   }
1368 | 
1369 |   /* Handle variants of link-local-only next hop */
1370 |   if (ipa_zero(nh[0]) && (len == 32))
1371 |   {
1372 |     nh = alloca_copy(nh, 32);
1373 |     len = bgp_prepare_link_local_next_hop(s, nh);
1374 |   }
1375 | 
1376 |   put_ip6(buf, ipa_to_ip6(nh[0]));
1377 | 
1378 |   if (len == 32)
1379 |     put_ip6(buf+16, ipa_to_ip6(nh[1]));
1380 | 
1381 |   return len;
1382 | }
