1430 | static uint
1431 | bgp_encode_next_hop_vpn(struct bgp_write_state *s, eattr *a, byte *buf, uint size UNUSED)
1432 | {
1433 |   ip_addr *nh = (void *) a->u.ptr->data;
1434 |   uint len = a->u.ptr->length;
1435 | 
1436 |   ASSERT((len == 16) || (len == 32));
1437 | 
1438 |   /*
1439 |    * Both IPv4 and IPv6 next hops can be used (with ext_next_hop enabled). This
1440 |    * is specified in RFC 8950 for VPNv4 and in RFC 4659 for VPNv6. The difference
1441 |    * is that IPv4 address is directly encoded with VPNv4 NLRI, but as IPv4-mapped
1442 |    * IPv6 address with VPNv6 NLRI.
1443 |    */
1444 | 
1445 |   if (bgp_channel_is_ipv4(s->channel) && ipa_is_ip4(nh[0]))
1446 |   {
1447 |     put_u64(buf, 0); /* VPN RD is 0 */
1448 |     put_ip4(buf+8, ipa_to_ip4(nh[0]));
1449 |     return 12;
1450 |   }
1451 | 
1452 |   /* Handle variants of link-local-only next hop */
1453 |   if (ipa_zero(nh[0]) && (len == 32))
1454 |   {
1455 |     nh = alloca_copy(nh, 32);
1456 |     len = bgp_prepare_link_local_next_hop(s, nh);
1457 |   }
1458 | 
1459 |   put_u64(buf, 0); /* VPN RD is 0 */
1460 |   put_ip6(buf+8, ipa_to_ip6(nh[0]));
1461 | 
1462 |   if (len == 16)
1463 |     return 24;
1464 | 
1465 |   put_u64(buf+24, 0); /* VPN RD is 0 */
1466 |   put_ip6(buf+32, ipa_to_ip6(nh[1]));
1467 | 
1468 |   return 48;
1469 | }
1470 | 
1471 | static void
1472 | bgp_decode_next_hop_vpn(struct bgp_parse_state *s, byte *data, uint len, rta *a)
1473 | {
1474 |   struct bgp_channel *c = s->channel;
1475 |   struct adata *ad = lp_alloc_adata(s->pool, 32);
1476 |   ip_addr *nh = (void *) ad->data;
1477 | 
1478 |   if (len == 12)
1479 |   {
1480 |     nh[0] = ipa_from_ip4(get_ip4(data+8));
1481 |     nh[1] = IPA_NONE;
1482 |   }
1483 |   else if (len == 24)
1484 |   {
1485 |     nh[0] = ipa_from_ip6(get_ip6(data+8));
1486 |     nh[1] = IPA_NONE;
1487 | 
1488 |     if (ipa_is_link_local(nh[0]))
1489 |     { nh[1] = nh[0]; nh[0] = IPA_NONE; }
1490 |   }
1491 |   else if (len == 48)
1492 |   {
1493 |     nh[0] = ipa_from_ip6(get_ip6(data+8));
1494 |     nh[1] = ipa_from_ip6(get_ip6(data+32));
1495 | 
1496 |     if (ipa_is_link_local(nh[0]))
1497 |     { nh[1] = nh[0]; nh[0] = IPA_NONE; }
1498 | 
1499 |     if (ipa_is_ip4(nh[0]) || !ip6_is_link_local(nh[1]))
1500 |       nh[1] = IPA_NONE;
1501 |   }
1502 |   else
1503 |     bgp_parse_error(s, 9);
1504 | 
1505 |   if (ipa_zero(nh[1]))
1506 |     ad->length = 16;
1507 | 
1508 |   /* XXXX which error */
1509 |   if ((get_u64(data) != 0) || ((len == 48) && (get_u64(data+24) != 0)))
1510 |     bgp_parse_error(s, 9);
1511 | 
1512 |   if ((bgp_channel_is_ipv4(c) != ipa_is_ip4(nh[0])) && !c->ext_next_hop)
1513 |     WITHDRAW(BAD_NEXT_HOP MISMATCHED_AF, nh[0], c->desc->name);
1514 | 
1515 |   // XXXX validate next hop
1516 | 
1517 |   bgp_set_attr_ptr(&(a->eattrs), s->pool, BA_NEXT_HOP, 0, ad);
1518 |   bgp_apply_next_hop(s, a, nh[0], nh[1]);
1519 | }
