1697 | static void
1698 | bgp_decode_nlri_ip4(struct bgp_parse_state *s, byte *pos, uint len, rta *a)
1699 | {
1700 |   while (len)
1701 |   {
1702 |     net_addr_ip4 net;
1703 |     u32 path_id = 0;
1704 | 
1705 |     /* Decode path ID */
1706 |     if (s->add_path)
1707 |     {
1708 |       if (len < 5)
1709 | 	bgp_parse_error(s, 1);
1710 | 
1711 |       path_id = get_u32(pos);
1712 |       ADVANCE(pos, len, 4);
1713 |     }
1714 | 
1715 |     /* Decode prefix length */
1716 |     uint l = *pos;
1717 |     ADVANCE(pos, len, 1);
1718 | 
1719 |     if (len < ((l + 7) / 8))
1720 |       bgp_parse_error(s, 1);
1721 | 
1722 |     /* Decode MPLS labels */
1723 |     if (s->mpls)
1724 |       bgp_decode_mpls_labels(s, &pos, &len, &l, a);
1725 | 
1726 |     if (l > IP4_MAX_PREFIX_LENGTH)
1727 |       bgp_parse_error(s, 10);
1728 | 
1729 |     /* Decode prefix body */
1730 |     ip4_addr addr = IP4_NONE;
1731 |     uint b = (l + 7) / 8;
1732 |     memcpy(&addr, pos, b);
1733 |     ADVANCE(pos, len, b);
1734 | 
1735 |     net = NET_ADDR_IP4(ip4_ntoh(addr), l);
1736 |     net_normalize_ip4(&net);
1737 | 
1738 |     // XXXX validate prefix
1739 | 
1740 |     bgp_rte_update(s, (net_addr *) &net, path_id, a);
1741 |   }
1742 | }
