2532 | static byte *
2533 | bgp_create_update_bmp(struct bgp_channel *c, byte *buf, byte *end, struct bgp_bucket *buck, bool update)
2534 | {
2535 |   struct bgp_proto *p = (void *) c->c.proto;
2536 |   byte *res = NULL;
2537 | 
2538 |   struct lp_state tmpp;
2539 |   lp_save(tmp_linpool, &tmpp);
2540 | 
2541 |   struct bgp_caps *peer = p->conn->remote_caps;
2542 |   const struct bgp_af_caps *rem = bgp_find_af_caps(peer, c->afi);
2543 | 
2544 |   struct bgp_write_state s = {
2545 |     .proto = p,
2546 |     .channel = c,
2547 |     .pool = tmp_linpool,
2548 |     .mp_reach = (c->afi != BGP_AF_IPV4) || rem->ext_next_hop,
2549 |     .as4_session = 1,
2550 |     .add_path = c->add_path_rx,
2551 |     .mpls = c->desc->mpls,
2552 |     .sham = 1,
2553 |   };
2554 | 
2555 |   if (!update)
2556 |   {
2557 |     res = !s.mp_reach ?
2558 |       bgp_create_ip_unreach(&s, buck, buf, end):
2559 |       bgp_create_mp_unreach(&s, buck, buf, end);
2560 |   }
2561 |   else
2562 |   {
2563 |     res = !s.mp_reach ?
2564 |       bgp_create_ip_reach(&s, buck, buf, end):
2565 |       bgp_create_mp_reach(&s, buck, buf, end);
2566 |   }
2567 | 
2568 |   lp_restore(tmp_linpool, &tmpp);
2569 | 
2570 |   return res;
2571 | }
