2749 |   rta *a = NULL;
2750 | 
2751 |   if (!c)
2752 |     DISCARD(BAD_AFI, BGP_AFI(afi), BGP_SAFI(afi));
2753 | 
2754 |   s->channel = c;
2755 |   s->add_path = c->add_path_rx;
2756 |   s->mpls = c->desc->mpls;
2757 | 
2758 |   s->last_id = 0;
2759 |   s->last_src = s->proto->p.main_source;
