3510 | /**
3511 |  * bgp_rx - handle received data
3512 |  * @sk: socket
3513 |  * @size: amount of data received
3514 |  *
3515 |  * bgp_rx() is called by the socket layer whenever new data arrive from
3516 |  * the underlying TCP connection. It assembles the data fragments to packets,
3517 |  * checks their headers and framing and passes complete packets to
3518 |  * bgp_rx_packet().
3519 |  */
3520 | int
3521 | bgp_rx(sock *sk, uint size)
3522 | {
3523 |   struct bgp_conn *conn = sk->data;
3524 | 
3525 |   byte *pkt_start = sk->rbuf;
3526 |   byte *end = pkt_start + size;
3527 |   uint i, len;
3528 | 
3529 |   DBG("BGP: RX hook: Got %d bytes\n", size);
3530 |   while (end >= pkt_start + BGP_HEADER_LENGTH)
3531 |     {
3532 |       if ((conn->state == BS_CLOSE) || (conn->sk != sk))
3533 | 	return 0;
3534 |       for(i=0; i<16; i++)
3535 | 	if (pkt_start[i] != 0xff)
3536 | 	  {
3537 | 	    bgp_error(conn, 1, 1, NULL, 0);
3538 | 	    break;
3539 | 	  }
3540 |       len = get_u16(pkt_start+16);
3541 |       if ((len < BGP_HEADER_LENGTH) || (len > bgp_max_packet_length(conn)))
3542 | 	{
3543 | 	  bgp_error(conn, 1, 2, pkt_start+16, 2);
3544 | 	  break;
3545 | 	}
3546 |       if (end < pkt_start + len)
3547 | 	break;
3548 |       bgp_rx_packet(conn, pkt_start, len);
3549 |       pkt_start += len;
3550 |     }
3551 |   if (pkt_start != sk->rbuf)
3552 |     {
3553 |       memmove(sk->rbuf, pkt_start, end - pkt_start);
3554 |       sk->rpos = sk->rbuf + (end - pkt_start);
3555 |     }
3556 |   return 0;
3557 | }

