 175 | // Idea for following macros has been taken from |proto/mrt/mrt.c|
 176 | #define BMP_DEFINE_PUT_FUNC(S, T)                               \
 177 |   static inline void                                            \
 178 |   bmp_put_##S(buffer *b, const T x)                             \
 179 |   {                                                             \
 180 |     bmp_buffer_need(b, sizeof(T));			   \
 181 |     put_##S(b->pos, x);                                    \
 182 |     b->pos += sizeof(T);                                   \
 183 |   }
