 566 | bmp_remove_table(struct bmp_proto *p, struct bmp_table *bt)
 567 | {
 568 |   channel_set_state(bt->channel, CS_FLUSHING);
 569 |   channel_set_state(bt->channel, CS_DOWN);
 570 |   proto_remove_channel(&p->p, bt->channel);
 571 | 
 572 |   HASH_REMOVE(p->table_map, HASH_TABLE, bt);
 573 | 
 574 |   rt_unlock_table(bt->table);
 575 |   bt->table = NULL;
 576 | 
