 663 |   {
 664 |     if (p->monitoring_rib.in_pre_policy && c->c.in_table)
 665 |       bmp_add_stream(p, bp, c->afi, false, c->c.in_table, c);
 666 | 
 667 |     if (p->monitoring_rib.in_post_policy && c->c.table)
 668 |       bmp_add_stream(p, bp, c->afi, true, c->c.table, c);
 669 |   }
 670 | 
 671 |   return bp;
