 721 | bmp_peer_up(struct bgp_proto *bgp,
 722 | 	    const byte *tx_open_msg, uint tx_open_length,
 723 | 	    const byte *rx_open_msg, uint rx_open_length)
 724 | {
 725 |   struct bmp_proto *p; node *n;
 726 |   WALK_LIST2(p, n, bmp_proto_list, bmp_node)
 727 |     bmp_peer_up_(p, bgp, true, tx_open_msg, tx_open_length, rx_open_msg, rx_open_length);
 728 | }
