 839 | static void
 840 | bmp_route_monitor_notify(struct bmp_proto *p, struct bmp_stream *bs,
 841 | 			 const net_addr *n, const struct rte *new, const struct rte_src *src)
 842 | {
 843 |   struct bgp_proto *bgp = bs->bgp;
 844 |   struct bgp_channel *c = bs->sender;
 845 | 
 846 |   btime delta_t = new ? current_time() - new->lastmod : 0;
 847 | 
 848 |   struct bmp_peer_hdr_info peer = {
 849 |     .address = bgp->remote_ip,
 850 |     .as = bgp->remote_as,
 851 |     .id = bgp->remote_id,
 852 |     .global = bmp_is_peer_global_instance(bgp),
 853 |     .policy = bmp_stream_policy(bs),
 854 |     .timestamp = current_real_time() - delta_t,
 855 |   };
 856 | 
 857 |   buffer msg = bmp_default_buffer(p);
 858 |   bmp_put_common_hdr(&msg, BMP_ROUTE_MONITOR, 0);
 859 |   bmp_put_per_peer_hdr(&msg, &peer);
 860 | 
 861 |   bmp_buffer_need(&msg, BGP_MAX_EXT_MSG_LENGTH);
 862 |   byte *pos = bgp_bmp_encode_rte(c, msg.pos + BGP_HEADER_LENGTH, msg.end, n, new, src);
 863 |   if (!pos)
 864 |   {
 865 |     log(L_WARN "%s: Cannot encode update for %N", p->p.name, n);
 866 |     return;
 867 |   }
 868 |   bmp_put_bgp_hdr(&msg, PKT_UPDATE, pos - msg.pos);
 869 |   msg.pos = pos;
 870 | 
 871 |   bmp_fix_common_hdr(&msg);
 872 |   bmp_schedule_tx_packet(p, &msg);
 873 | }
 874 | 
 875 | static void
 876 | bmp_route_monitor_end_of_rib(struct bmp_proto *p, struct bmp_stream *bs)
 877 | {
 878 |   struct bgp_proto *bgp = bs->bgp;
 879 |   struct bgp_channel *c = bs->sender;
 880 | 
 881 |   struct bmp_peer_hdr_info peer = {
 882 |     .address = bgp->remote_ip,
 883 |     .as = bgp->remote_as,
 884 |     .id = bgp->remote_id,
 885 |     .global = bmp_is_peer_global_instance(bgp),
 886 |     .policy = bmp_stream_policy(bs),
 887 |     .timestamp = current_real_time(),
 888 |   };
 889 | 
 890 |   TRACE(D_PACKETS, "Sending END-OF-RIB for %s.%s", bgp->p.name, c->c.name);
 891 | 
 892 |   buffer msg = bmp_default_buffer(p);
 893 |   bmp_put_common_hdr(&msg, BMP_ROUTE_MONITOR, 0);
 894 |   bmp_put_per_peer_hdr(&msg, &peer);
 895 | 
 896 |   bmp_buffer_need(&msg, BGP_MAX_EXT_MSG_LENGTH);
 897 |   byte *pos = bgp_create_end_mark_(c, msg.pos + BGP_HEADER_LENGTH);
 898 |   bmp_put_bgp_hdr(&msg, PKT_UPDATE, pos - msg.pos);
 899 |   msg.pos = pos;
 900 | 
 901 |   bmp_fix_common_hdr(&msg);
 902 |   bmp_schedule_tx_packet(p, &msg);
 903 | }
