 980 | static void
 981 | bmp_send_termination_msg(struct bmp_proto *p, enum bmp_term_reason reason)
 982 | {
 983 |   buffer stream = bmp_default_buffer(p);
 984 | 
 985 |   bmp_put_common_hdr(&stream, BMP_TERM_MSG, 0);
 986 |   bmp_buffer_need(&stream, 6);
 987 |   bmp_put_u16(&stream, BMP_TERM_INFO_REASON);
 988 |   bmp_put_u16(&stream, 2); // Length of the reason
 989 |   bmp_put_u16(&stream, reason);
 990 |   bmp_fix_common_hdr(&stream);
 991 | 
 992 |   if (p->sk->tbuf)
 993 |     bmp_tx_buffer_free(p, SKIP_BACK(struct bmp_tx_buffer, data, p->sk->tbuf));
 994 | 
 995 |   p->sk->tbuf = stream.start;
 996 |   if (sk_send(p->sk, stream.pos - stream.start) < 0)
 997 |     log(L_WARN "%s: Cannot send BMP termination message", p->p.name);
 998 |   p->sk->tbuf = NULL;
 999 | }
