1015 | static void
1016 | bmp_rt_notify(struct proto *P, struct channel *c, struct network *net,
1017 | 		struct rte *new, struct rte *old)
1018 | {
1019 |   struct bmp_proto *p = (void *) P;
1020 | 
1021 |   struct bgp_channel *src = (void *) (new ?: old)->sender;
1022 |   struct bgp_proto *bgp = (void *) src->c.proto;
1023 |   bool policy = (c->table == src->c.table);
1024 | 
1025 |   /*
1026 |    * We assume that we receive peer_up before the first route and peer_down
1027 |    * synchronously with BGP session close. So if bmp_stream exists, the related
1028 |    * BGP session is up and could be accessed. That may not be true in
1029 |    * multithreaded setup.
1030 |    */
1031 | 
1032 |   struct bmp_stream *bs = bmp_find_stream(p, bgp, src->afi, policy);
1033 |   if (!bs)
1034 |     return;
1035 | 
1036 |   bmp_route_monitor_notify(p, bs, net->n.addr, new, (new ?: old)->src);
1037 | }
1038 | 
1039 | static void
1040 | bmp_feed_end(struct channel *c)
1041 | {
1042 |   struct bmp_proto *p = (void *) c->proto;
1043 | 
1044 |   struct bmp_table *bt = bmp_find_table(p, c->table);
1045 |   if (!bt)
1046 |     return;
1047 | 
1048 |   /*
1049 |    * Unsynced streams are added in one moment during BMP session establishment,
1050 |    * therefore we can assume that all unsynced streams (for given channel)
1051 |    * already received full feed now and are synced.
1052 |    *
1053 |    * TODO: Use more efficent way to find bmp_stream from bmp_table
1054 |    */
1055 | 
1056 |   HASH_WALK(p->stream_map, next, bs)
1057 |   {
1058 |     if ((bs->table == bt) && !bs->sync)
1059 |     {
1060 |       bmp_route_monitor_end_of_rib(p, bs);
1061 |       bs->sync = true;
1062 |     }
1063 |   }
1064 |   HASH_WALK_END;
1065 | }
