1348 | bmp_reconfigure(struct proto *P, struct proto_config *CF)
1349 | {
1350 |   struct bmp_proto *p = (void *) P;
1351 |   const struct bmp_config *new = (void *) CF;
1352 |   const struct bmp_config *old = p->cf;
1353 | 
1354 |   int needs_restart = bstrcmp(new->sys_descr, old->sys_descr)
1355 |     || bstrcmp(new->sys_name, old->sys_name)
1356 |     || !ipa_equal(new->local_addr, old->local_addr)
1357 |     || !ipa_equal(new->station_ip, old->station_ip)
1358 |     || (new->station_port != old->station_port)
1359 |     || (new->monitoring_rib_in_pre_policy != old->monitoring_rib_in_pre_policy)
1360 |     || (new->monitoring_rib_in_post_policy != old->monitoring_rib_in_post_policy);
1361 | 
1362 |   /* If there is any change, restart the protocol */
1363 |   if (needs_restart)
1364 |     return 0;
1365 | 
1366 |   /* We must update our copy of configuration ptr */
1367 |   p->cf = new;
1368 | 
1369 |   /* Reconfigure tx buffer size limits */
1370 |   p->tx_pending_limit = new->tx_pending_limit;
1371 | 
1372 |   return 1;
1373 | }
