 299 | static void
 300 | bmp_schedule_tx_packet(struct bmp_proto *p, buffer *msg)
 301 | {
 302 |   const byte *payload = msg->start;
 303 |   size_t size = msg->pos - msg->start;
 304 | 
 305 |   ASSERT(p->started);
 306 | 
 307 |   while (size)
 308 |   {
 309 |     if (!p->tx_last || !bmp_tx_remains(p->tx_last))
 310 |     {
 311 |       if (p->tx_pending_count >= p->tx_pending_limit)
 312 | 	return ev_schedule(p->tx_overflow_event);
 313 | 
 314 |       p->tx_pending_count++;
 315 | 
 316 |       struct bmp_tx_buffer *btb = alloc_page();
 317 |       btb->pos = btb->data;
 318 |       btb->next = NULL;
 319 | 
 320 |       if (p->tx_last)
 321 |       {
 322 | 	ASSERT_DIE(!p->tx_last->next);
 323 | 	p->tx_last->next = btb;
 324 |       }
 325 |       else
 326 | 	ASSERT_DIE(p->tx_pending_count == 1);
 327 | 
 328 |       p->tx_last = btb;
 329 | 
 330 |       if (!p->tx_pending)
 331 | 	p->tx_pending = btb;
 332 |     }
 333 | 
 334 |     size_t cpylen = bmp_tx_remains(p->tx_last);
 335 |     if (size < cpylen)
 336 |       cpylen = size;
 337 | 
 338 |     memcpy(p->tx_last->pos, payload, cpylen);
 339 |     p->tx_last->pos += cpylen;
 340 | 
 341 |     payload += cpylen;
 342 |     size -= cpylen;
 343 |   }
 344 | 
 345 |   if (!p->sk->tbuf && !ev_active(p->tx_ev))
 346 |     ev_schedule(p->tx_ev);
 347 | }
 348 | 
 349 | static void
 350 | bmp_tx_buffer_free(struct bmp_proto *p, struct bmp_tx_buffer *btb)
 351 | {
 352 |   if (btb == p->tx_last)
 353 |   {
 354 |     p->tx_last = NULL;
 355 |     ASSERT_DIE(!p->tx_pending_count);
 356 |   }
 357 | 
 358 |   free_page(btb);
 359 | }
 360 | 
 361 | static void
 362 | bmp_fire_tx(void *p_)
 363 | {
 364 |   struct bmp_proto *p = p_;
 365 | 
 366 |   if (!p->started)
 367 |     return;
 368 | 
 369 |   int cnt = 0;
 370 |   for (struct bmp_tx_buffer *btb; btb = p->tx_pending; )
 371 |   {
 372 |     ASSERT_DIE(!p->sk->tbuf);
 373 | 
 374 |     p->sk->tbuf = btb->data;
 375 |     u64 sz = btb->pos - btb->data;
 376 | 
 377 |     p->tx_sent += sz;
 378 |     p->tx_sent_total += sz;
 379 | 
 380 |     if (p->tx_pending == p->tx_last)
 381 |       p->tx_last = NULL;
 382 | 
 383 |     p->tx_pending = btb->next;
 384 |     p->tx_pending_count--;
 385 | 
 386 |     if (sk_send(p->sk, sz) <= 0)
 387 |       return;
 388 | 
 389 |     p->sk->tbuf = NULL;
 390 |     bmp_tx_buffer_free(p, btb);
 391 | 
 392 |     if (cnt++ > 1024)
 393 |     {
 394 |       if (!ev_active(p->tx_ev))
 395 | 	ev_schedule(p->tx_ev);
 396 |       return;
 397 |     }
 398 |   }
 399 | }
