 401 | static void
 402 | bmp_tx(struct birdsock *sk)
 403 | {
 404 |   struct bmp_proto *p = sk->data;
 405 | 
 406 |   struct bmp_tx_buffer *btb = SKIP_BACK(struct bmp_tx_buffer, data, sk->tbuf);
 407 |   bmp_tx_buffer_free(p, btb);
 408 | 
 409 |   sk->tbuf = NULL;
 410 | 
 411 |   bmp_fire_tx(sk->data);
 412 | }
