 442 | /**
 443 |  * bmp_put_per_peer_hdr - serializes Per-Peer Header
 444 |  *
 445 |  * @is_post_policy: indicate the message reflects the post-policy Adj-RIB-In
 446 |  * @peer_addr: the remote IP address associated with the TCP session
 447 |  * @peer_as: the Autonomous System number of the peer
 448 |  * @peer_bgp_id: the BGP Identifier of the peer
 449 |  * @ts_sec: the time in seconds when the encapsulated routes were received
 450 |  * @ts_usec: the time in microseconds when the encapsulated routes were received
 451 |  */
 452 | static void
 453 | bmp_put_per_peer_hdr(buffer *stream, const struct bmp_peer_hdr_info *peer)
 454 | {
 455 |   // TODO: ATM we do not support BMP_PEER_TYPE_RD_INSTANCE
 456 |   u8 peer_type = peer->global ?
 457 |     BMP_PEER_TYPE_GLOBAL_INSTANCE :
 458 |     BMP_PEER_TYPE_LOCAL_INSTANCE;
 459 | 
 460 |   u8 peer_flags =
 461 |     (ipa_is_ip6(peer->address) ? BMP_PEER_FLAG_V_IPV6 : 0) |
 462 |     (peer->policy ? BMP_PEER_FLAG_L_POLICY : 0) |
 463 |     (peer->no_as4 ? BMP_PEER_FLAG_A_NO_AS4 : 0);
 464 | 
 465 |   u32 ts_sec = peer->timestamp TO_S;
 466 |   u32 ts_usec = peer->timestamp - (ts_sec S);
 467 | 
 468 |   bmp_buffer_need(stream, BMP_PER_PEER_HDR_SIZE);
 469 |   bmp_put_u8(stream, peer_type);
 470 |   bmp_put_u8(stream, peer_flags);
 471 |   bmp_put_u64(stream, 0); // Not supported peer distinguisher
 472 |   bmp_put_ipa(stream, peer->address);
 473 |   bmp_put_u32(stream, peer->as);
 474 |   bmp_put_u32(stream, peer->id);
 475 |   bmp_put_u32(stream, ts_sec);
 476 |   bmp_put_u32(stream, ts_usec);
 477 | }
