 479 | static void
 480 | bmp_peer_up_notif_msg_serialize(buffer *stream, const struct bmp_peer_hdr_info *peer,
 481 | 				const ip_addr local_addr, const u16 local_port, const u16 remote_port,
 482 | 				const byte *sent_msg, const size_t sent_msg_length,
 483 | 				const byte *recv_msg, const size_t recv_msg_length)
 484 | {
 485 |   bmp_put_common_hdr(stream, BMP_PEER_UP_NOTIF, 0);
 486 |   bmp_put_per_peer_hdr(stream, peer);
 487 | 
 488 |   bmp_buffer_need(stream, BMP_PEER_UP_NOTIF_MSG_FIX_SIZE);
 489 |   bmp_put_ipa(stream, local_addr);
 490 |   bmp_put_u16(stream, local_port);
 491 |   bmp_put_u16(stream, remote_port);
 492 |   bmp_put_bgp_hdr(stream, PKT_OPEN, BGP_HEADER_LENGTH + sent_msg_length);
 493 |   bmp_put_data(stream, sent_msg, sent_msg_length);
 494 |   bmp_put_bgp_hdr(stream, PKT_OPEN, BGP_HEADER_LENGTH + recv_msg_length);
 495 |   bmp_put_data(stream, recv_msg, recv_msg_length);
 496 | 
 497 |   bmp_fix_common_hdr(stream);
 498 | }
