 500 | static void
 501 | bmp_peer_down_notif_msg_serialize(buffer *stream, const struct bmp_peer_hdr_info *peer,
 502 | 				  const struct bmp_peer_down_info *info)
 503 | {
 504 |   bmp_put_common_hdr(stream, BMP_PEER_DOWN_NOTIF, 0);
 505 |   bmp_put_per_peer_hdr(stream, peer);
 506 | 
 507 |   bmp_put_u8(stream, info->reason);
 508 | 
 509 |   switch (info->reason)
 510 |   {
 511 |   case BMP_PEER_DOWN_REASON_LOCAL_BGP_NOTIFICATION:
 512 |   case BMP_PEER_DOWN_REASON_REMOTE_BGP_NOTIFICATION:;
 513 |     uint bgp_msg_length = BGP_HEADER_LENGTH + 2 + info->length;
 514 |     bmp_buffer_need(stream, bgp_msg_length);
 515 |     bmp_put_bgp_hdr(stream, PKT_NOTIFICATION, bgp_msg_length);
 516 |     bmp_put_u8(stream, info->err_code);
 517 |     bmp_put_u8(stream, info->err_subcode);
 518 |     bmp_put_data(stream, info->data, info->length);
 519 |     break;
 520 | 
 521 |   case BMP_PEER_DOWN_REASON_LOCAL_NO_NOTIFICATION:
 522 |     bmp_put_u16(stream, info->fsm_code);
 523 |     break;
 524 |   }
 525 | 
 526 |   bmp_fix_common_hdr(stream);
 527 | }
