 540 | static struct bmp_table *
 541 | bmp_add_table(struct bmp_proto *p, struct rtable *tab)
 542 | {
 543 |   struct bmp_table *bt = mb_allocz(p->p.pool, sizeof(struct bmp_table));
 544 |   bt->table = tab;
 545 |   rt_lock_table(bt->table);
 546 | 
 547 |   HASH_INSERT(p->table_map, HASH_TABLE, bt);
 548 | 
 549 |   struct channel_config cc = {
 550 |     .name = "monitor",
 551 |     .channel = &channel_basic,
 552 |     .table = tab->config,
 553 |     .in_filter = FILTER_REJECT,
 554 |     .net_type = tab->addr_type,
 555 |     .ra_mode = RA_ANY,
 556 |     .bmp_hack = 1,
 557 |   };
 558 | 
 559 |   bt->channel = proto_add_channel(&p->p, &cc);
 560 |   channel_set_state(bt->channel, CS_UP);
 561 | 
 562 |   return bt;
 563 | }
