 651 | static struct bmp_peer *
 652 | bmp_add_peer(struct bmp_proto *p, struct bgp_proto *bgp)
 653 | {
 654 |   struct bmp_peer *bp = mb_allocz(p->p.pool, sizeof(struct bmp_peer));
 655 |   bp->bgp = bgp;
 656 | 
 657 |   init_list(&bp->streams);
 658 | 
 659 |   HASH_INSERT(p->peer_map, HASH_PEER, bp);
 660 | 
 661 |   struct bgp_channel *c;
 662 |   BGP_WALK_CHANNELS(bgp, c)
 663 |   {
 664 |     if (p->monitoring_rib.in_pre_policy && c->c.in_table)
 665 |       bmp_add_stream(p, bp, c->afi, false, c->c.in_table, c);
 666 | 
 667 |     if (p->monitoring_rib.in_post_policy && c->c.table)
 668 |       bmp_add_stream(p, bp, c->afi, true, c->c.table, c);
 669 |   }
 670 | 
 671 |   return bp;
 672 | }
