 686 | static void
 687 | bmp_peer_up_(struct bmp_proto *p, struct bgp_proto *bgp, bool sync,
 688 | 	    const byte *tx_open_msg, uint tx_open_length,
 689 | 	    const byte *rx_open_msg, uint rx_open_length)
 690 | {
 691 |   if (!p->started)
 692 |     return;
 693 | 
 694 |   struct bmp_peer *bp = bmp_find_peer(p, bgp);
 695 |   if (bp)
 696 |     return;
 697 | 
 698 |   TRACE(D_STATES, "Peer up for %s", bgp->p.name);
 699 | 
 700 |   bp = bmp_add_peer(p, bgp);
 701 | 
 702 |   bmp_send_peer_up_notif_msg(p, bgp, tx_open_msg, tx_open_length, rx_open_msg, rx_open_length);
 703 | 
 704 |   /*
 705 |    * We asssume peer_up() notifications are received before any route
 706 |    * notifications from that peer. Therefore, peers established after BMP
 707 |    * session coould be considered synced with empty RIB.
 708 |    */
 709 |   if (sync)
 710 |   {
 711 |     struct bmp_stream *bs;
 712 |     WALK_LIST(bs, bp->streams)
 713 |     {
 714 |       bmp_route_monitor_end_of_rib(p, bs);
 715 |       bs->sync = true;
 716 |     }
 717 |   }
 718 | }
