 736 |       !conn->local_open_msg || !conn->remote_open_msg)
 737 |     return;
 738 | 
 739 |   bmp_peer_up_(p, bgp, false, conn->local_open_msg, conn->local_open_length,
 740 | 	       conn->remote_open_msg, conn->remote_open_length);
