 801 | static bool
 802 | bmp_is_peer_global_instance(const struct bgp_proto *bgp)
 803 | {
 804 |   return (bgp->cf->peer_type != BGP_PT_EXTERNAL &&
 805 |             bgp->cf->peer_type != BGP_PT_INTERNAL)
 806 |               ? (bgp->local_as != bgp->remote_as)
 807 |               : (bgp->cf->peer_type == BGP_PT_EXTERNAL);
