 928 | static void
 929 | bmp_peer_down_(struct bmp_proto *p, const struct bgp_proto *bgp,
 930 | 	       int err_class, int err_code, int err_subcode, const byte *data, int length)
 931 | {
 932 |   if (!p->started)
 933 |     return;
 934 | 
 935 |   struct bmp_peer *bp = bmp_find_peer(p, bgp);
 936 |   if (!bp)
 937 |     return;
 938 | 
 939 |   TRACE(D_STATES, "Peer down for %s", bgp->p.name);
 940 | 
 941 |   struct bmp_peer_down_info info = {
 942 |     .err_code = err_code,
 943 |     .err_subcode = err_subcode,
 944 |     .data = data,
 945 |     .length = length,
 946 |   };
 947 | 
 948 |   switch (err_class)
 949 |   {
 950 |   case BE_BGP_RX:
 951 |     info.reason = BMP_PEER_DOWN_REASON_REMOTE_BGP_NOTIFICATION;
 952 |     break;
 953 | 
 954 |   case BE_BGP_TX:
 955 |   case BE_AUTO_DOWN:
 956 |   case BE_MAN_DOWN:
 957 |     info.reason = BMP_PEER_DOWN_REASON_LOCAL_BGP_NOTIFICATION;
 958 |     break;
 959 | 
 960 |   default:
 961 |     info.reason = BMP_PEER_DOWN_REASON_REMOTE_NO_NOTIFICATION;
 962 |     info.length = 0;
 963 |     break;
 964 |   }
 965 | 
 966 |   bmp_send_peer_down_notif_msg(p, bgp, &info);
 967 | 
 968 |   bmp_remove_peer(p, bp);
 969 | }
 970 | 
 971 | void
 972 | bmp_peer_down(const struct bgp_proto *bgp,
 973 | 	      int err_class, int code, int subcode, const byte *data, int length)
 974 | {
 975 |   struct bmp_proto *p; node *n;
 976 |   WALK_LIST2(p, n, bmp_proto_list, bmp_node)
 977 |     bmp_peer_down_(p, bgp, err_class, code, subcode, data, length);
 978 | }
