1001 | int
1002 | bmp_preexport(struct channel *C UNUSED, rte *e)
1003 | {
1004 |   /* Reject non-direct routes */
1005 |   if (e->src->proto != e->sender->proto)
1006 |     return -1;
1007 | 
1008 |   /* Reject non-BGP routes */
1009 |   if (e->sender->channel != &channel_bgp)
1010 |     return -1;
1011 | 
1012 |   return 1;
1013 | }
