1068 | /**
1069 |  * bmp_startup - enter established state
1070 |  * @p: BMP instance
1071 |  *
1072 |  * The bgp_startup() function is called when the BMP session is established.
1073 |  * It sends initiation and peer up messagages.
1074 |  */
1075 | static void
1076 | bmp_startup(struct bmp_proto *p)
1077 | {
1078 |   ASSERT(!p->started);
1079 |   p->started = true;
1080 |   p->sock_err = 0;
1081 | 
1082 |   TRACE(D_EVENTS, "BMP session established");
1083 | 
1084 |   proto_notify_state(&p->p, PS_UP);
1085 | 
1086 |   /* Send initiation message */
1087 |   buffer payload = bmp_default_buffer(p);
1088 |   bmp_init_msg_serialize(&payload, p->sys_descr, p->sys_name);
1089 |   bmp_schedule_tx_packet(p, &payload);
1090 | 
1091 |   /* Send Peer Up messages */
1092 |   struct proto *peer;
1093 |   WALK_LIST(peer, proto_list)
1094 |     if ((peer->proto->class == PROTOCOL_BGP) && (peer->proto_state == PS_UP))
1095 |       bmp_peer_init(p, (struct bgp_proto *) peer);
1096 | }
1097 | 
1098 | /**
1099 |  * bmp_down - leave established state
1100 |  * @p: BMP instance
1101 |  *
1102 |  * The bgp_down() function is called when the BMP session fails. The caller is
1103 |  * responsible for changing protocol state.
1104 |  */
1105 | static void
1106 | bmp_down(struct bmp_proto *p)
1107 | {
1108 |   ASSERT(p->started);
1109 |   p->started = false;
1110 |   p->tx_sent = 0;
1111 | 
1112 |   TRACE(D_EVENTS, "BMP session closed");
1113 | 
1114 |   /* Unregister existing peer structures */
1115 |   HASH_WALK_DELSAFE(p->peer_map, next, bp)
1116 |   {
1117 |     bmp_remove_peer(p, bp);
1118 |   }
1119 |   HASH_WALK_END;
1120 | 
1121 |   /* Removing peers should also remove all streams and tables */
1122 |   ASSERT(!p->peer_map.count && !p->stream_map.count && !p->table_map.count);
1123 | }
1124 | 
1125 | /**
1126 |  * bmp_connect - initiate an outgoing connection
1127 |  * @p: BMP instance
1128 |  *
1129 |  * The bmp_connect() function creates the socket and initiates an outgoing TCP
1130 |  * connection to the monitoring station. It is called to enter Connect state.
1131 |  */
1132 | static void
1133 | bmp_connect(struct bmp_proto *p)
1134 | {
1135 |   ASSERT(!p->started);
1136 | 
1137 |   sock *sk = sk_new(p->p.pool);
1138 |   sk->type = SK_TCP_ACTIVE;
1139 |   sk->saddr = p->local_addr;
1140 |   sk->daddr = p->station_ip;
1141 |   sk->dport = p->station_port;
1142 |   sk->ttl = IP4_MAX_TTL;
1143 |   sk->tos = IP_PREC_INTERNET_CONTROL;
1144 |   sk->tx_hook = bmp_connected;
1145 |   sk->err_hook = bmp_sock_err;
1146 | 
1147 |   p->sk = sk;
1148 |   sk->data = p;
1149 | 
1150 |   TRACE(D_EVENTS, "Connecting to %I port %u", sk->daddr, sk->dport);
1151 | 
1152 |   int rc = sk_open(sk);
1153 | 
1154 |   if (rc < 0)
1155 |     sk_log_error(sk, p->p.name);
1156 | 
1157 |   tm_start(p->connect_retry_timer, CONNECT_RETRY_TIME);
1158 | }
1159 | 
1160 | /* BMP connect successful event - switch from Connect to Established state */
1161 | static void
1162 | bmp_connected(struct birdsock *sk)
1163 | {
1164 |   struct bmp_proto *p = (void *) sk->data;
1165 | 
1166 |   TRACE(D_EVENTS, "Connected");
1167 | 
1168 |   sk->rx_hook = bmp_rx;
1169 |   sk->tx_hook = bmp_tx;
1170 |   tm_stop(p->connect_retry_timer);
1171 | 
1172 |   bmp_startup(p);
1173 | }
1174 | 
1175 | /* BMP socket error event - switch from any state to Idle state */
1176 | static void
1177 | bmp_sock_err(sock *sk, int err)
1178 | {
1179 |   struct bmp_proto *p = sk->data;
1180 | 
1181 |   p->sock_err = err;
1182 | 
1183 |   if (err)
1184 |     TRACE(D_EVENTS, "Connection lost (%M)", err);
1185 |   else
1186 |     TRACE(D_EVENTS, "Connection closed");
1187 | 
1188 |   if (p->started)
1189 |     bmp_down(p);
1190 | 
1191 |   bmp_close_socket(p);
1192 |   tm_start(p->connect_retry_timer, CONNECT_RETRY_TIME);
1193 | 
1194 |   proto_notify_state(&p->p, PS_START);
1195 | }
1196 | 
1197 | static void
1198 | bmp_tx_overflow(void *_p)
1199 | {
1200 |   struct bmp_proto *p = _p;
1201 |   if (p->tx_pending_count < p->tx_pending_limit)
1202 |     return;
1203 | 
1204 |   p->sock_err = 0;
1205 | 
1206 |   log(L_ERR "%s: Connection stalled", p->p.name);
1207 | 
1208 |   if (p->started)
1209 |     bmp_down(p);
1210 | 
1211 |   bmp_close_socket(p);
1212 |   tm_start(p->connect_retry_timer, CONNECT_RETRY_TIME);
1213 | 
1214 |   proto_notify_state(&p->p, PS_START);
1215 | }
1216 | 
1217 | /* BMP connect timeout event - switch from Idle/Connect state to Connect state */
1218 | static void
1219 | bmp_connection_retry(timer *t)
1220 | {
1221 |   struct bmp_proto *p = t->data;
1222 | 
1223 |   if (p->started)
1224 |     return;
1225 | 
1226 |   bmp_close_socket(p);
1227 |   bmp_connect(p);
1228 | }
1229 | 
1230 | static void
1231 | bmp_close_socket(struct bmp_proto *p)
1232 | {
1233 |   if (p->sk && p->sk->tbuf)
1234 |     bmp_tx_buffer_free(p, SKIP_BACK(struct bmp_tx_buffer, data, p->sk->tbuf));
1235 | 
1236 |   struct bmp_tx_buffer *btb = p->tx_pending;
1237 |   while (btb)
1238 |   {
1239 |     p->tx_pending_count--;
1240 | 
1241 |     struct bmp_tx_buffer *next = btb->next;
1242 |     bmp_tx_buffer_free(p, btb);
1243 |     btb = next;
1244 |   }
1245 | 
1246 |   p->tx_pending = NULL;
1247 | 
1248 |   ASSERT_DIE(!p->tx_last);
1249 |   ASSERT_DIE(!p->tx_pending_count);
1250 | 
1251 |   rfree(p->sk);
1252 |   p->sk = NULL;
1253 | }
