1301 | static int
1302 | bmp_start(struct proto *P)
1303 | {
1304 |   struct bmp_proto *p = (void *) P;
1305 | 
1306 |   p->tx_ev = ev_new_init(p->p.pool, bmp_fire_tx, p);
1307 |   p->tx_pending = NULL;
1308 |   p->tx_pending_count = 0;
1309 |   p->tx_overflow_event = ev_new_init(p->p.pool, bmp_tx_overflow, p);
1310 |   p->connect_retry_timer = tm_new_init(p->p.pool, bmp_connection_retry, p, 0, 0);
1311 |   p->sk = NULL;
1312 | 
1313 |   resource *r = ralloc(P->pool, &bmp_tx_resource_class);
1314 |   SKIP_BACK(struct bmp_tx_resource, r, r)->p = p;
1315 | 
1316 |   HASH_INIT(p->peer_map, P->pool, 4);
1317 |   HASH_INIT(p->stream_map, P->pool, 4);
1318 |   HASH_INIT(p->table_map, P->pool, 4);
1319 | 
1320 |   p->started = false;
1321 |   p->sock_err = 0;
1322 |   add_tail(&bmp_proto_list, &p->bmp_node);
1323 | 
1324 |   tm_start(p->connect_retry_timer, CONNECT_INIT_TIME);
1325 | 
1326 |   return PS_START;
