1375 | static void
1376 | bmp_get_status(struct proto *P, byte *buf)
1377 | {
1378 |   struct bmp_proto *p = (void *) P;
1379 | 
1380 |   if (P->proto_state == PS_DOWN)
1381 |     bsprintf(buf, "Down");
