 92 | static struct adata *
 93 | l3vpn_export_targets(struct l3vpn_proto *p, const struct adata *src)
 94 | {
 95 |   u32 *s = int_set_get_data(src);
 96 |   int len = int_set_get_size(src);
 97 | 
 98 |   struct adata *dst = lp_alloc(tmp_linpool, sizeof(struct adata) + (len + p->export_target_length) * sizeof(u32));
 99 |   u32 *d = int_set_get_data(dst);
100 |   int end = 0;
101 | 
102 |   for (int i = 0; i < len; i += 2)
103 |   {
104 |     /* Remove existing route targets */
105 |     uint type = s[i] >> 16;
106 |     if (ec_type_is_rt(type))
107 |       continue;
108 | 
109 |     d[end++] = s[i];
110 |     d[end++] = s[i+1];
111 |   }
112 | 
113 |   /* Add new route targets */
114 |   memcpy(d + end, p->export_target_data, p->export_target_length * sizeof(u32));
115 |   end += p->export_target_length;
116 | 
117 |   /* Set length */
118 |   dst->length = end * sizeof(u32);
119 | 
120 |   return dst;
121 | }
