320 | static void
321 | l3vpn_postconfig(struct proto_config *CF)
322 | {
323 |   struct l3vpn_config *cf = (void *) CF;
324 | 
325 |   if (!!proto_cf_find_channel(CF, NET_IP4) != !!proto_cf_find_channel(CF, NET_VPN4))
326 |     cf_error("For IPv4 L3VPN, both IPv4 and VPNv4 channels must be specified");
327 | 
328 |   if (!!proto_cf_find_channel(CF, NET_IP6) != !!proto_cf_find_channel(CF, NET_VPN6))
329 |     cf_error("For IPv6 L3VPN, both IPv6 and VPNv6 channels must be specified");
330 | 
331 |   if (!proto_cf_find_channel(CF, NET_MPLS))
332 |     cf_error("MPLS channel not specified");
333 | 
334 |   if (rd_zero(cf->rd))
335 |     cf_error("Route distinguisher not specified");
336 | 
337 |   if (!cf->import_target && !cf->export_target)
338 |     cf_error("Route target not specified");
339 | 
340 |   if (!cf->import_target)
341 |     cf_error("Import target not specified");
342 | 
343 |   if (!cf->export_target)
344 |     cf_error("Export target not specified");
