123 | static inline void
124 | l3vpn_prepare_import_targets(struct l3vpn_proto *p)
125 | {
126 |   const struct f_tree *t = p->import_target;
127 |   p->import_target_one = !t->left && !t->right && (t->from.val.ec == t->to.val.ec);
128 | }
129 | 
130 | static void
131 | l3vpn_add_ec(const struct f_tree *t, void *P)
132 | {
133 |   struct l3vpn_proto *p = P;
134 |   ec_put(p->export_target_data, p->export_target_length, t->from.val.ec);
135 |   p->export_target_length += 2;
136 | }
137 | 
138 | static void
139 | l3vpn_prepare_export_targets(struct l3vpn_proto *p)
140 | {
141 |   if (p->export_target_data)
142 |     mb_free(p->export_target_data);
143 | 
144 |   uint len = 2 * tree_node_count(p->export_target);
145 |   p->export_target_data = mb_alloc(p->p.pool, len * sizeof(u32));
146 |   p->export_target_length = 0;
147 |   tree_walk(p->export_target, l3vpn_add_ec, p);
148 |   ASSERT(p->export_target_length == len);
149 | }
