151 | static void
152 | l3vpn_rt_notify(struct proto *P, struct channel *c0, net *net, rte *new, rte *old UNUSED)
153 | {
154 |   struct l3vpn_proto *p = (void *) P;
155 |   struct rte_src *src = NULL;
156 |   struct channel *dst = NULL;
157 |   int export;
158 | 
159 |   const net_addr *n0 = net->n.addr;
160 |   net_addr *n = alloca(sizeof(net_addr_vpn6));
161 | 
162 |   switch (c0->net_type)
163 |   {
164 |   case NET_IP4:
165 |     net_fill_vpn4(n, net4_prefix(n0), net4_pxlen(n0), p->rd);
166 |     src = p->p.main_source;
167 |     dst = p->vpn4_channel;
168 |     export = 1;
169 |     break;
170 | 
171 |   case NET_IP6:
172 |     net_fill_vpn6(n, net6_prefix(n0), net6_pxlen(n0), p->rd);
173 |     src = p->p.main_source;
174 |     dst = p->vpn6_channel;
175 |     export = 1;
176 |     break;
177 | 
178 |   case NET_VPN4:
179 |     net_fill_ip4(n, net4_prefix(n0), net4_pxlen(n0));
180 |     src = rt_get_source(&p->p, rd_to_u64(((const net_addr_vpn4 *) n0)->rd));
181 |     dst = p->ip4_channel;
182 |     export = 0;
183 |     break;
184 | 
185 |   case NET_VPN6:
186 |     net_fill_ip6(n, net6_prefix(n0), net6_pxlen(n0));
187 |     src = rt_get_source(&p->p, rd_to_u64(((const net_addr_vpn6 *) n0)->rd));
188 |     dst = p->ip6_channel;
189 |     export = 0;
190 |     break;
191 | 
192 |   case NET_MPLS:
193 |     return;
194 |   }
195 | 
196 |   if (new)
197 |   {
198 |     const rta *a0 = new->attrs;
199 |     rta *a = alloca(RTA_MAX_SIZE);
200 |     *a = (rta) {
201 |       .source = RTS_L3VPN,
202 |       .scope = SCOPE_UNIVERSE,
203 |       .dest = a0->dest,
204 |       .pref = dst->preference,
205 |       .eattrs = a0->eattrs
206 |     };
207 | 
208 |     nexthop_link(a, &a0->nh);
209 | 
210 |     /* Do not keep original labels, we may assign new ones */
211 |     ea_unset_attr(&a->eattrs, tmp_linpool, 0, EA_MPLS_LABEL);
212 |     ea_unset_attr(&a->eattrs, tmp_linpool, 0, EA_MPLS_POLICY);
213 | 
214 |     /* We are crossing VRF boundary, NEXT_HOP is no longer valid */
215 |     ea_unset_attr(&a->eattrs, tmp_linpool, 0, EA_BGP_NEXT_HOP);
216 |     ea_unset_attr(&a->eattrs, tmp_linpool, 0, EA_BGP_MPLS_LABEL_STACK);
217 | 
218 |     if (export)
219 |     {
220 |       struct mpls_channel *mc = (void *) p->p.mpls_channel;
221 |       ea_set_attr_u32(&a->eattrs, tmp_linpool, EA_MPLS_POLICY, 0, EAF_TYPE_INT, mc->label_policy);
222 | 
223 |       struct adata *ad = l3vpn_export_targets(p, ea_get_adata(a0->eattrs, EA_BGP_EXT_COMMUNITY));
224 |       ea_set_attr_ptr(&a->eattrs, tmp_linpool, EA_BGP_EXT_COMMUNITY, BAF_OPTIONAL | BAF_TRANSITIVE, EAF_TYPE_EC_SET, ad);
225 | 
226 |       /* Replace MPLS-incompatible nexthop with lookup in VRF table */
227 |       if (!mpls_valid_nexthop(a) && p->p.vrf)
228 |       {
229 | 	a->dest = RTD_UNICAST;
230 | 	a->nh = (struct nexthop) { .iface = p->p.vrf };
231 |       }
232 |     }
233 | 
234 |     /* Keep original IGP metric as a base for L3VPN metric */
235 |     if (!export)
236 |       a->igp_metric = a0->igp_metric;
237 | 
238 |     rte *e = rte_get_temp(a, src);
239 |     rte_update2(dst, n, e, src);
240 |   }
241 |   else
242 |   {
243 |     rte_update2(dst, n, NULL, src);
244 |   }
245 | }
