275 | static void
276 | l3vpn_reload_routes(struct channel *C)
277 | {
278 |   struct l3vpn_proto *p = (void *) C->proto;
279 | 
280 |   /* Route reload on one channel is just refeed on the other */
281 |   switch (C->net_type)
282 |   {
283 |   case NET_IP4:
284 |     channel_request_feeding(p->vpn4_channel);
285 |     break;
286 | 
287 |   case NET_IP6:
288 |     channel_request_feeding(p->vpn6_channel);
289 |     break;
290 | 
291 |   case NET_VPN4:
292 |     channel_request_feeding(p->ip4_channel);
293 |     break;
294 | 
295 |   case NET_VPN6:
296 |     channel_request_feeding(p->ip6_channel);
297 |     break;
298 | 
299 |   case NET_MPLS:
300 |     channel_request_feeding(p->ip4_channel);
301 |     channel_request_feeding(p->ip6_channel);
302 |     break;
303 |   }
304 | }
