306 | static inline u32
307 | l3vpn_metric(rte *e)
308 | {
309 |   u32 metric = ea_get_int(e->attrs->eattrs, EA_GEN_IGP_METRIC, e->attrs->igp_metric);
310 |   return MIN(metric, IGP_METRIC_UNKNOWN);
311 | }
