368 | static int
369 | l3vpn_start(struct proto *P)
370 | {
371 |   struct l3vpn_proto *p = (void *) P;
372 |   struct l3vpn_config *cf = (void *) P->cf;
373 | 
374 |   p->rd = cf->rd;
375 |   p->import_target = cf->import_target;
376 |   p->export_target = cf->export_target;
377 |   p->export_target_data = NULL;
378 | 
379 |   l3vpn_prepare_import_targets(p);
380 |   l3vpn_prepare_export_targets(p);
381 | 
382 |   proto_setup_mpls_map(P, RTS_L3VPN, 1);
383 | 
384 |   if (P->vrf_set)
385 |     P->mpls_map->vrf_iface = P->vrf;
386 | 
387 |   return PS_UP;
388 | }
