248 | static int
249 | l3vpn_preexport(struct channel *C, rte *e)
250 | {
251 |   struct l3vpn_proto *p = (void *) C->proto;
252 |   struct proto *pp = e->sender->proto;
253 | 
254 |   if (pp == C->proto)
255 |     return -1;	/* Avoid local loops automatically */
256 | 
257 |   switch (C->net_type)
258 |   {
259 |   case NET_IP4:
260 |   case NET_IP6:
261 |     return 0;
262 | 
263 |   case NET_VPN4:
264 |   case NET_VPN6:
265 |     return l3vpn_import_targets(p, ea_get_adata(e->attrs->eattrs, EA_BGP_EXT_COMMUNITY)) ? 0 : -1;
266 | 
267 |   case NET_MPLS:
268 |     return -1;
269 | 
270 |   default:
271 |     bug("invalid type");
272 |   }
273 | }
