 62 | #define EA_BGP_NEXT_HOP		EA_CODE(PROTOCOL_BGP, BA_NEXT_HOP)
 63 | #define EA_BGP_EXT_COMMUNITY	EA_CODE(PROTOCOL_BGP, BA_EXT_COMMUNITY)
 64 | #define EA_BGP_MPLS_LABEL_STACK	EA_CODE(PROTOCOL_BGP, BA_MPLS_LABEL_STACK)
 65 | 
 66 | static inline const struct adata * ea_get_adata(ea_list *e, uint id)
 67 | { eattr *a = ea_find(e, id); return a ? a->u.ptr : &null_adata; }
 68 | 
 69 | static inline int
 70 | mpls_valid_nexthop(const rta *a)
 71 | {
 72 |   /* MPLS does not support special blackhole targets */
 73 |   if (a->dest != RTD_UNICAST)
 74 |     return 0;
 75 | 
 76 |   /* MPLS does not support ARP / neighbor discovery */
 77 |   for (const struct nexthop *nh = &a->nh; nh ; nh = nh->next)
 78 |     if (ipa_zero(nh->gw) && (nh->iface->flags & IF_MULTIACCESS))
 79 |       return 0;
 80 | 
 81 |   return 1;
 82 | }
 83 | 
 84 | static int
 85 | l3vpn_import_targets(struct l3vpn_proto *p, const struct adata *list)
 86 | {
 87 |   return (p->import_target_one) ?
 88 |     ec_set_contains(list, p->import_target->from.val.ec) :
 89 |     eclist_match_set(list, p->import_target);
 90 | }
 91 | 
 92 | static struct adata *
 93 | l3vpn_export_targets(struct l3vpn_proto *p, const struct adata *src)
 94 | {
 95 |   u32 *s = int_set_get_data(src);
 96 |   int len = int_set_get_size(src);
 97 | 
 98 |   struct adata *dst = lp_alloc(tmp_linpool, sizeof(struct adata) + (len + p->export_target_length) * sizeof(u32));
 99 |   u32 *d = int_set_get_data(dst);
100 |   int end = 0;
101 | 
102 |   for (int i = 0; i < len; i += 2)
103 |   {
104 |     /* Remove existing route targets */
105 |     uint type = s[i] >> 16;
106 |     if (ec_type_is_rt(type))
107 |       continue;
108 | 
109 |     d[end++] = s[i];
110 |     d[end++] = s[i+1];
111 |   }
112 | 
113 |   /* Add new route targets */
114 |   memcpy(d + end, p->export_target_data, p->export_target_length * sizeof(u32));
115 |   end += p->export_target_length;
116 | 
117 |   /* Set length */
118 |   dst->length = end * sizeof(u32);
119 | 
120 |   return dst;
121 | }
