347 | static struct proto *
348 | l3vpn_init(struct proto_config *CF)
349 | {
350 |   struct proto *P = proto_new(CF);
351 |   struct l3vpn_proto *p = (void *) P;
352 |   // struct l3vpn_config *cf = (void *) CF;
353 | 
354 |   proto_configure_channel(P, &p->ip4_channel, proto_cf_find_channel(CF, NET_IP4));
355 |   proto_configure_channel(P, &p->ip6_channel, proto_cf_find_channel(CF, NET_IP6));
356 |   proto_configure_channel(P, &p->vpn4_channel, proto_cf_find_channel(CF, NET_VPN4));
357 |   proto_configure_channel(P, &p->vpn6_channel, proto_cf_find_channel(CF, NET_VPN6));
358 |   proto_configure_channel(P, &P->mpls_channel, proto_cf_find_channel(CF, NET_MPLS));
359 | 
360 |   P->rt_notify = l3vpn_rt_notify;
361 |   P->preexport = l3vpn_preexport;
362 |   P->reload_routes = l3vpn_reload_routes;
363 |   P->rte_better = l3vpn_rte_better;
364 | 
365 |   return P;
366 | }
