390 | static int
391 | l3vpn_shutdown(struct proto *P)
392 | {
393 |   // struct l3vpn_proto *p = (void *) P;
394 | 
395 |   proto_shutdown_mpls_map(P, 1);
396 | 
397 |   return PS_DOWN;
398 | }
