400 | static int
401 | l3vpn_reconfigure(struct proto *P, struct proto_config *CF)
402 | {
403 |   struct l3vpn_proto *p = (void *) P;
404 |   struct l3vpn_config *cf = (void *) CF;
405 | 
406 |   if (!proto_configure_channel(P, &p->ip4_channel, proto_cf_find_channel(CF, NET_IP4)) ||
407 |       !proto_configure_channel(P, &p->ip6_channel, proto_cf_find_channel(CF, NET_IP6)) ||
408 |       !proto_configure_channel(P, &p->vpn4_channel, proto_cf_find_channel(CF, NET_VPN4)) ||
409 |       !proto_configure_channel(P, &p->vpn6_channel, proto_cf_find_channel(CF, NET_VPN6)) ||
410 |       !proto_configure_channel(P, &P->mpls_channel, proto_cf_find_channel(CF, NET_MPLS)))
411 |     return 0;
412 | 
413 |   if (!rd_equal(p->rd, cf->rd))
414 |     return 0;
415 | 
416 |   int import_changed = !same_tree(p->import_target, cf->import_target);
417 |   int export_changed = !same_tree(p->export_target, cf->export_target);
418 | 
419 |   /* Update pointers to config structures */
420 |   p->import_target = cf->import_target;
421 |   p->export_target = cf->export_target;
422 | 
423 |   proto_setup_mpls_map(P, RTS_L3VPN, 1);
424 | 
425 |   if (import_changed)
426 |   {
427 |     TRACE(D_EVENTS, "Import target changed");
428 | 
429 |     l3vpn_prepare_import_targets(p);
430 | 
431 |     if (p->vpn4_channel && (p->vpn4_channel->channel_state == CS_UP))
432 |       channel_request_feeding(p->vpn4_channel);
433 | 
434 |     if (p->vpn6_channel && (p->vpn6_channel->channel_state == CS_UP))
435 |       channel_request_feeding(p->vpn6_channel);
436 |   }
437 | 
438 |   if (export_changed)
439 |   {
440 |     TRACE(D_EVENTS, "Export target changed");
441 | 
442 |     l3vpn_prepare_export_targets(p);
443 | 
444 |     if (p->ip4_channel && (p->ip4_channel->channel_state == CS_UP))
445 |       channel_request_feeding(p->ip4_channel);
446 | 
447 |     if (p->ip6_channel && (p->ip6_channel->channel_state == CS_UP))
448 |       channel_request_feeding(p->ip6_channel);
449 |   }
450 | 
451 |   return 1;
452 | }
