  8 |  */
  9 | 
 10 | /**
 11 |  * DOC: Multi-Threaded Routing Toolkit (MRT) protocol
 12 |  *
 13 |  * The MRT protocol is implemented in just one file: |mrt.c|. It contains of
 14 |  * several parts: Generic functions for preparing MRT messages in a buffer,
 15 |  * functions for MRT table dump (called from timer or CLI), functions for MRT
 16 |  * BGP4MP dump (called from BGP), and the usual protocol glue. For the MRT table
 17 |  * dump, the key structure is struct mrt_table_dump_state, which contains all
 18 |  * necessary data and created when the MRT dump cycle is started for the
 19 |  * duration of the MRT dump. The MBGP4MP dump is currently not bound to MRT
 20 |  * protocol instance and uses the config->mrtdump_file fd.
 21 |  *
 22 |  * The protocol is simple, just periodically scans routing table and export it
 23 |  * to a file. It does not use the regular update mechanism, but a direct access
 24 |  * in order to handle iteration through multiple routing tables. The table dump
 25 |  * needs to dump all peers first and then use indexes to address the peers, we
 26 |  * use a hash table (@peer_hash) to find peer index based on BGP protocol key
 27 |  * attributes.
 28 |  *
 29 |  * One thing worth documenting is the locking. During processing, the currently
 30 |  * processed table (@table field in the state structure) is locked and also the
 31 |  * explicitly named table is locked (@table_ptr field in the state structure) if
 32 |  * specified. Between dumps no table is locked. Also the current config is
 33 |  * locked (by config_add_obstacle()) during table dumps as some data (strings,
 34 |  * filters) are shared from the config and the running table dump may be
 35 |  * interrupted by reconfiguration.
 36 |  *
 37 |  * Supported standards:
 38 |  * - RFC 6396 - MRT format standard
 39 |  * - RFC 8050 - ADD_PATH extension
 40 |  */
 41 | 
 42 | #include <unistd.h>
 43 | #include <limits.h>
 44 | #include <errno.h>
 45 | 
 46 | #include "mrt.h"
 47 | 
 48 | #include "nest/cli.h"
 49 | #include "filter/filter.h"
 50 | #include "proto/bgp/bgp.h"
 51 | #include "sysdep/unix/unix.h"
 52 | 
 53 | 
 54 | #ifdef PATH_MAX
 55 | #define BIRD_PATH_MAX PATH_MAX
 56 | #else
 57 | #define BIRD_PATH_MAX 4096
 58 | #endif
 59 | 
 60 | #define mrt_log(s, msg, args...)				\
 61 |   ({								\
 62 |     if (s->cli)							\
 63 |       cli_printf(s->cli, -8009, msg, ## args);			\
 64 |     if (s->proto)						\
 65 |       log(L_ERR "%s: " msg, s->proto->p.name, ## args);		\
 66 |   })
 67 | 
 68 | 
 69 | /*
 70 |  *	MRT buffer code
 71 |  */
 72 | 
 73 | static void
 74 | mrt_buffer_init(buffer *b, pool *pool, size_t n)
 75 | {
 76 |   b->start = mb_alloc(pool, n);
 77 |   b->pos = b->start;
 78 |   b->end = b->start + n;
 79 | }
 80 | 
 81 | static void
 82 | mrt_buffer_grow(buffer *b, size_t n)
 83 | {
 84 |   size_t used = b->pos - b->start;
 85 |   size_t size = b->end - b->start;
 86 |   size_t req = used + n;
 87 | 
 88 |   while (size < req)
 89 |     size = size * 3 / 2;
 90 | 
 91 |   b->start = mb_realloc(b->start, size);
 92 |   b->pos = b->start + used;
 93 |   b->end = b->start + size;
 94 | }
 95 | 
 96 | static inline void
 97 | mrt_buffer_need(buffer *b, size_t n)
 98 | {
 99 |   if (b->pos + n > b->end)
100 |     mrt_buffer_grow(b, n);
101 | }
102 | 
103 | static inline uint
104 | mrt_buffer_pos(buffer *b)
105 | {
106 |   return b->pos - b->start;
107 | }
108 | 
109 | static inline void
110 | mrt_buffer_flush(buffer *b)
111 | {
112 |   b->pos = b->start;
113 | }
114 | 
115 | #define MRT_DEFINE_TYPE(S, T)						\
116 |   static inline void UNUSED mrt_put_##S##_(buffer *b, T x)		\
117 |   {									\
118 |     put_##S(b->pos, x);							\
119 |     b->pos += sizeof(T);						\
120 |   }									\
121 | 									\
122 |   static inline void UNUSED mrt_put_##S(buffer *b, T x)			\
123 |   {									\
124 |     mrt_buffer_need(b, sizeof(T));					\
125 |     put_##S(b->pos, x);							\
126 |     b->pos += sizeof(T);						\
127 |   }
128 | 
129 | MRT_DEFINE_TYPE(u8, u8)
130 | MRT_DEFINE_TYPE(u16, u16)
131 | MRT_DEFINE_TYPE(u32, u32)
132 | MRT_DEFINE_TYPE(u64, u64)
133 | MRT_DEFINE_TYPE(ip4, ip4_addr)
134 | MRT_DEFINE_TYPE(ip6, ip6_addr)
135 | 
136 | static inline void
137 | mrt_put_ipa(buffer *b, ip_addr x)
138 | {
139 |   if (ipa_is_ip4(x))
140 |     mrt_put_ip4(b, ipa_to_ip4(x));
141 |   else
142 |     mrt_put_ip6(b, ipa_to_ip6(x));
143 | }
144 | 
145 | static inline void
146 | mrt_put_data(buffer *b, const void *src, size_t n)
147 | {
148 |   if (!n)
149 |     return;
150 | 
151 |   mrt_buffer_need(b, n);
152 |   memcpy(b->pos, src, n);
153 |   b->pos += n;
154 | }
155 | 
156 | static void
157 | mrt_init_message(buffer *b, u16 type, u16 subtype)
158 | {
159 |   /* Reset buffer */
160 |   mrt_buffer_flush(b);
161 |   mrt_buffer_need(b, MRT_HDR_LENGTH);
162 | 
163 |   /* Prepare header */
164 |   mrt_put_u32_(b, current_real_time() TO_S); /* now_real */
165 |   mrt_put_u16_(b, type);
166 |   mrt_put_u16_(b, subtype);
167 | 
168 |   /* Message length, will be fixed later */
169 |   mrt_put_u32_(b, 0);
170 | }
171 | 
172 | static void
173 | mrt_dump_message(buffer *b, int fd)
174 | {
175 |   uint len = mrt_buffer_pos(b);
176 | 
177 |   /* Fix message length */
178 |   ASSERT(len >= MRT_HDR_LENGTH);
179 |   put_u32(b->start + 8, len - MRT_HDR_LENGTH);
180 | 
181 |   if (fd < 0)
182 |     return;
183 | 
184 |   if (write(fd, b->start, len) < 0)
185 |     log(L_ERR "Write to MRT file failed: %m"); /* TODO: name of file */
186 | }
187 | 
188 | static int
189 | bstrsub(char *dst, size_t n, const char *src, const char *key, const char *val)
190 | {
191 |   const char *last, *next;
192 |   char *pos = dst;
193 |   size_t step, klen = strlen(key), vlen = strlen(val);
194 | 
195 |   for (last = src; next = strstr(last, key); last = next + klen)
196 |   {
197 |     step = next - last;
198 |     if (n <= step + vlen)
199 |       return 0;
200 | 
201 |     memcpy(pos, last, step);
202 |     ADVANCE(pos, n, step);
203 | 
204 |     memcpy(pos, val, vlen);
205 |     ADVANCE(pos, n, vlen);
206 |   }
207 | 
208 |   step = strlen(last);
209 |   if (n <= step)
210 |     return 0;
211 | 
212 |   memcpy(pos, last, step);
213 |   ADVANCE(pos, n, step);
214 | 
215 |   pos[0] = 0;
216 |   return 1;
217 | }
218 | 
219 | static inline rtable *
220 | mrt_next_table_(rtable *tab, rtable *tab_ptr, const char *pattern)
221 | {
222 |   /* Handle explicit table, return it in the first pass */
223 |   if (tab_ptr)
224 |     return !tab ? tab_ptr : NULL;
225 | 
226 |   /* Walk routing_tables list, starting after tab (if non-NULL) */
227 |   for (node *tn = tab ? tab->n.next : HEAD(routing_tables);
228 |        NODE_VALID(tn);
229 |        tn = tn->next)
230 |   {
231 |     tab = SKIP_BACK(struct rtable, n, tn);
232 |     if (patmatch(pattern, tab->name) &&
233 | 	((tab->addr_type == NET_IP4) || (tab->addr_type == NET_IP6)))
234 |       return tab;
235 |   }
236 | 
237 |   return NULL;
238 | }
239 | 
240 | static rtable *
241 | mrt_next_table(struct mrt_table_dump_state *s)
242 | {
243 |   rtable *tab = mrt_next_table_(s->table, s->table_ptr, s->table_expr);
244 | 
245 |   if (s->table)
246 |     rt_unlock_table(s->table);
247 | 
248 |   s->table = tab;
249 |   s->ipv4 = tab ? (tab->addr_type == NET_IP4) : 0;
250 | 
251 |   if (s->table)
252 |     rt_lock_table(s->table);
253 | 
254 |   return s->table;
255 | }
256 | 
257 | static int
258 | mrt_open_file(struct mrt_table_dump_state *s)
259 | {
260 |   char fmt1[BIRD_PATH_MAX];
261 |   char name[BIRD_PATH_MAX];
262 |   btime now = current_time();
263 |   btime now_real = current_real_time();
264 | 
265 |   if (!bstrsub(fmt1, sizeof(fmt1), s->filename, "%N", s->table->name) ||
266 |       !tm_format_real_time(name, sizeof(name), fmt1, now_real))
267 |   {
268 |     mrt_log(s, "Invalid filename '%s'", s->filename);
269 |     return 0;
270 |   }
271 | 
272 |   s->file = rf_open(s->pool, name, "a");
273 |   if (!s->file)
274 |   {
275 |     mrt_log(s, "Unable to open MRT file '%s': %m", name);
276 |     return 0;
277 |   }
278 | 
279 |   s->fd = rf_fileno(s->file);
280 |   s->time_offset = now_real - now;
281 | 
282 |   return 1;
283 | }
284 | 
285 | static void
286 | mrt_close_file(struct mrt_table_dump_state *s)
287 | {
288 |   rfree(s->file);
289 |   s->file = NULL;
290 |   s->fd = -1;
291 | }
292 | 
293 | 
294 | /*
295 |  *	MRT Table Dump: Peer Index Table
296 |  */
297 | 
298 | #define PEER_KEY(n)		n->peer_id, n->peer_as, n->peer_ip
299 | #define PEER_NEXT(n)		n->next
300 | #define PEER_EQ(id1,as1,ip1,id2,as2,ip2) \
301 |   id1 == id2 && as1 == as2 && ipa_equal(ip1, ip2)
302 | #define PEER_FN(id,as,ip)	ipa_hash(ip)
303 | 
304 | static void
305 | mrt_peer_table_header(struct mrt_table_dump_state *s, u32 router_id, const char *name)
306 | {
307 |   buffer *b = &s->buf;
308 | 
309 |   /* Collector BGP ID */
310 |   mrt_put_u32(b, router_id);
311 | 
312 |   /* View Name */
313 |   uint name_length = name ? strlen(name) : 0;
314 |   name_length = MIN(name_length, 65535);
315 |   mrt_put_u16(b, name_length);
316 |   mrt_put_data(b, name, name_length);
317 | 
318 |   /* Peer Count, will be fixed later */
319 |   s->peer_count = 0;
320 |   s->peer_count_offset = mrt_buffer_pos(b);
321 |   mrt_put_u16(b, 0);
322 | 
323 |   HASH_INIT(s->peer_hash, s->pool, 10);
324 | }
325 | 
326 | static void
327 | mrt_peer_table_entry(struct mrt_table_dump_state *s, u32 peer_id, u32 peer_as, ip_addr peer_ip)
328 | {
329 |   buffer *b = &s->buf;
330 | 
331 |   uint type = MRT_PEER_TYPE_32BIT_ASN;
332 |   if (ipa_is_ip6(peer_ip))
333 |     type |= MRT_PEER_TYPE_IPV6;
334 | 
335 |   /* Dump peer to buffer */
336 |   mrt_put_u8(b, type);
337 |   mrt_put_u32(b, peer_id);
338 |   mrt_put_ipa(b, peer_ip);
339 |   mrt_put_u32(b, peer_as);
340 | 
341 |   /* Add peer to hash table */
342 |   struct mrt_peer_entry *n = lp_allocz(s->peer_lp, sizeof(struct mrt_peer_entry));
343 |   n->peer_id = peer_id;
344 |   n->peer_as = peer_as;
345 |   n->peer_ip = peer_ip;
346 |   n->index = s->peer_count++;
347 | 
348 |   HASH_INSERT(s->peer_hash, PEER, n);
349 | }
350 | 
351 | static void
352 | mrt_peer_table_dump(struct mrt_table_dump_state *s)
353 | {
354 |   mrt_init_message(&s->buf, MRT_TABLE_DUMP_V2, MRT_PEER_INDEX_TABLE);
355 |   mrt_peer_table_header(s, config->router_id, s->table->name);
356 | 
357 |   /* 0 is fake peer for non-BGP routes */
358 |   mrt_peer_table_entry(s, 0, 0, IPA_NONE);
359 | 
360 | #ifdef CONFIG_BGP
361 |   struct proto *P;
362 |   WALK_LIST(P, proto_list)
363 |     if ((P->proto == &proto_bgp) && (P->proto_state != PS_DOWN))
364 |     {
365 |       struct bgp_proto *p = (void *) P;
366 |       mrt_peer_table_entry(s, p->remote_id, p->remote_as, p->remote_ip);
367 |     }
368 | #endif
369 | 
370 |   /* Fix Peer Count */
371 |   put_u16(s->buf.start + s->peer_count_offset, s->peer_count);
372 | 
373 |   mrt_dump_message(&s->buf, s->fd);
374 | }
375 | 
376 | static void
377 | mrt_peer_table_flush(struct mrt_table_dump_state *s)
378 | {
379 |   lp_flush(s->peer_lp);
380 |   HASH_FREE(s->peer_hash);
381 | }
382 | 
383 | 
384 | /*
385 |  *	MRT Table Dump: RIB Table
386 |  */
387 | 
388 | static void
389 | mrt_rib_table_header(struct mrt_table_dump_state *s, net_addr *n)
390 | {
391 |   buffer *b = &s->buf;
392 | 
393 |   /* Sequence Number */
394 |   mrt_put_u32(b, s->seqnum);
395 | 
396 |   /* Network Prefix */
397 |   if (s->ipv4)
398 |   {
399 |     ASSERT(n->type == NET_IP4);
400 |     ip4_addr a = ip4_hton(net4_prefix(n));
401 |     uint len = net4_pxlen(n);
402 | 
403 |     mrt_put_u8(b, len);
404 |     mrt_put_data(b, &a, BYTES(len));
405 |   }
406 |   else
407 |   {
408 |     ASSERT(n->type == NET_IP6);
409 |     ip6_addr a = ip6_hton(net6_prefix(n));
410 |     uint len = net6_pxlen(n);
411 | 
412 |     mrt_put_u8(b, len);
413 |     mrt_put_data(b, &a, BYTES(len));
414 |   }
415 | 
416 |   /* Entry Count, will be fixed later */
417 |   s->entry_count = 0;
418 |   s->entry_count_offset = mrt_buffer_pos(b);
419 |   mrt_put_u16(b, 0);
420 | }
421 | 
422 | #ifdef CONFIG_BGP
423 | static void
424 | mrt_rib_table_entry_bgp_attrs(struct mrt_table_dump_state *s, rte *r)
425 | {
426 |   struct ea_list *eattrs = r->attrs->eattrs;
427 |   buffer *b = &s->buf;
428 | 
429 |   if (!eattrs)
430 |     return;
431 | 
432 |   /* Attribute list must be normalized for bgp_encode_attrs() */
433 |   if (!rta_is_cached(r->attrs))
434 |     ea_normalize(eattrs);
435 | 
436 |   mrt_buffer_need(b, MRT_ATTR_BUFFER_SIZE);
437 |   byte *pos = b->pos;
438 | 
439 |   s->bws->mp_reach = !s->ipv4;
440 |   s->bws->mp_next_hop = NULL;
441 | 
442 |   /* Encode BGP attributes */
443 |   int len = bgp_encode_attrs(s->bws, eattrs, pos, b->end);
444 |   if (len < 0)
445 |     goto fail;
446 |   pos += len;
447 | 
448 |   /* Encode IPv6 next hop separately as fake MP_REACH_NLRI attribute */
449 |   if (s->bws->mp_next_hop)
450 |   {
451 |     len = bgp_encode_mp_reach_mrt(s->bws, s->bws->mp_next_hop, pos, b->end - pos);
452 |     if (len < 0)
453 |       goto fail;
454 |     pos += len;
455 |   }
456 | 
457 |   /* Update attribute length and advance buffer pos */
458 |   put_u16(b->pos - 2, pos - b->pos);
459 |   b->pos = pos;
460 |   return;
461 | 
462 | fail:
463 |   mrt_log(s, "Attribute list too long for %N", r->net->n.addr);
464 | }
465 | #endif
