467 | static void
468 | mrt_rib_table_entry(struct mrt_table_dump_state *s, rte *r)
469 | {
470 |   buffer *b = &s->buf;
471 |   uint peer = 0;
472 | 
473 | #ifdef CONFIG_BGP
474 |   /* Find peer index */
475 |   if (r->src->proto->proto == &proto_bgp)
476 |   {
477 |     struct bgp_proto *p = (void *) r->src->proto;
478 |     struct mrt_peer_entry *n =
479 |       HASH_FIND(s->peer_hash, PEER, p->remote_id, p->remote_as, p->remote_ip);
480 | 
481 |     peer = n ? n->index : 0;
482 |   }
483 | #endif
484 | 
485 |   /* Peer Index and Originated Time */
486 |   mrt_put_u16(b, peer);
487 |   mrt_put_u32(b, (r->lastmod + s->time_offset) TO_S);
488 | 
489 |   /* Path Identifier */
490 |   if (s->add_path)
491 |     mrt_put_u32(b, (u32) r->src->private_id);
492 | 
493 |   /* Route Attributes */
494 |   mrt_put_u16(b, 0);
495 | 
496 | #ifdef CONFIG_BGP
497 |   mrt_rib_table_entry_bgp_attrs(s, r);
498 | #endif
499 | 
500 |   s->entry_count++;
501 | }
