503 | static void
504 | mrt_rib_table_dump(struct mrt_table_dump_state *s, net *n, int add_path)
505 | {
506 |   s->add_path = s->bws->add_path = add_path;
507 | 
508 |   int subtype = s->ipv4 ?
509 |     (!add_path ? MRT_RIB_IPV4_UNICAST : MRT_RIB_IPV4_UNICAST_ADDPATH) :
510 |     (!add_path ? MRT_RIB_IPV6_UNICAST : MRT_RIB_IPV6_UNICAST_ADDPATH);
511 | 
512 |   mrt_init_message(&s->buf, MRT_TABLE_DUMP_V2, subtype);
513 |   mrt_rib_table_header(s, n->n.addr);
514 | 
515 |   rte *rt, *rt0;
516 |   for (rt0 = n->routes; rt = rt0; rt0 = rt0->next)
517 |   {
518 |     if (rte_is_filtered(rt))
519 |       continue;
520 | 
521 |     /* Skip routes that should be reported in the other phase */
522 |     if (!s->always_add_path && (!rt->src->private_id != !s->add_path))
523 |     {
524 |       s->want_add_path = 1;
525 |       continue;
526 |     }
527 | 
528 |     if (f_run(s->filter, &rt, s->linpool, 0) <= F_ACCEPT)
529 |       mrt_rib_table_entry(s, rt);
530 | 
531 |     if (rt != rt0)
532 |       rte_free(rt);
533 | 
534 |     lp_flush(s->linpool);
535 |   }
536 | 
537 |   /* Fix Entry Count */
538 |   put_u16(s->buf.start + s->entry_count_offset, s->entry_count);
539 | 
540 |   /* Update max counter */
541 |   s->max -= 1 + s->entry_count;
542 | 
543 |   /* Skip empty entries */
544 |   if (!s->entry_count)
545 |     return;
546 | 
547 |   s->seqnum++;
548 |   mrt_dump_message(&s->buf, s->fd);
549 | }
