555 | 
556 | static struct mrt_table_dump_state *
557 | mrt_table_dump_init(pool *pp)
558 | {
559 |   pool *pool = rp_new(pp, "MRT Table Dump");
560 |   struct mrt_table_dump_state *s = mb_allocz(pool, sizeof(struct mrt_table_dump_state));
561 | 
562 |   s->pool = pool;
563 |   s->linpool = lp_new(pool);
564 |   s->peer_lp = lp_new(pool);
565 |   mrt_buffer_init(&s->buf, pool, 2 * MRT_ATTR_BUFFER_SIZE);
566 | 
567 |   /* We lock the current config as we may reference it indirectly by filter */
568 |   s->config = config;
569 |   config_add_obstacle(s->config);
570 | 
571 |   s->fd = -1;
572 | 
573 |   return s;
