576 | static void
577 | mrt_table_dump_free(struct mrt_table_dump_state *s)
578 | {
579 |   if (s->table_open)
580 |     FIB_ITERATE_UNLINK(&s->fit, &s->table->fib);
581 | 
582 |   if (s->table)
583 |     rt_unlock_table(s->table);
584 | 
585 |   if (s->table_ptr)
586 |     rt_unlock_table(s->table_ptr);
587 | 
588 |   config_del_obstacle(s->config);
589 | 
590 |   rfree(s->pool);
