594 | static int
595 | mrt_table_dump_step(struct mrt_table_dump_state *s)
596 | {
597 |   struct bgp_write_state bws = {
598 |     .as4_session = 1,
599 |     .ignore_non_bgp_attrs = 1,
600 |   };
601 | 
602 |   s->max = 2048;
603 |   s->bws = &bws;
604 | 
605 |   if (s->table_open)
606 |     goto step;
607 | 
608 |   while (mrt_next_table(s))
609 |   {
610 |     if (!mrt_open_file(s))
611 |       continue;
612 | 
613 |     mrt_peer_table_dump(s);
614 | 
615 |     FIB_ITERATE_INIT(&s->fit, &s->table->fib);
616 |     s->table_open = 1;
617 | 
618 |   step:
619 |     FIB_ITERATE_START(&s->table->fib, &s->fit, net, n)
620 |     {
621 |       if (s->max < 0)
622 |       {
623 | 	FIB_ITERATE_PUT(&s->fit);
624 | 	return 0;
625 |       }
626 | 
627 |       /* With Always ADD_PATH option, we jump directly to second phase */
628 |       s->want_add_path = s->always_add_path;
629 | 
630 |       if (s->want_add_path == 0)
631 | 	mrt_rib_table_dump(s, n, 0);
632 | 
633 |       if (s->want_add_path == 1)
634 | 	mrt_rib_table_dump(s, n, 1);
635 |     }
636 |     FIB_ITERATE_END;
637 |     s->table_open = 0;
638 | 
639 |     mrt_close_file(s);
640 |     mrt_peer_table_flush(s);
641 |   }
642 | 
643 |   return 1;
644 | }
