767 | static void
768 | mrt_bgp_header(buffer *b, struct mrt_bgp_data *d)
769 | {
770 |   if (d->as4)
771 |   {
772 |     mrt_put_u32(b, d->peer_as);
773 |     mrt_put_u32(b, d->local_as);
774 |   }
775 |   else
776 |   {
777 |     mrt_put_u16(b, (d->peer_as <= 0xFFFF) ? d->peer_as : AS_TRANS);
778 |     mrt_put_u16(b, (d->local_as <= 0xFFFF) ? d->local_as : AS_TRANS);
779 |   }
780 | 
781 |   mrt_put_u16(b, (d->index <= 0xFFFF) ? d->index : 0);
782 |   mrt_put_u16(b, d->af);
783 | 
784 |   if (d->af == BGP_AFI_IPV4)
785 |   {
786 |     mrt_put_ip4(b, ipa_to_ip4(d->peer_ip));
787 |     mrt_put_ip4(b, ipa_to_ip4(d->local_ip));
788 |   }
789 |   else
790 |   {
791 |     mrt_put_ip6(b, ipa_to_ip6(d->peer_ip));
792 |     mrt_put_ip6(b, ipa_to_ip6(d->local_ip));
793 |   }
794 | }
