800 |     MRT_BGP4MP_MESSAGE,			MRT_BGP4MP_MESSAGE_AS4,
801 |     MRT_BGP4MP_MESSAGE_LOCAL,		MRT_BGP4MP_MESSAGE_AS4_LOCAL,
802 |     MRT_BGP4MP_MESSAGE_ADDPATH,		MRT_BGP4MP_MESSAGE_AS4_ADDPATH,
803 |     MRT_BGP4MP_MESSAGE_LOCAL_ADDPATH,	MRT_BGP4MP_MESSAGE_AS4_LOCAL_ADDPATH,
804 |   };
805 | 
806 |   buffer *b = mrt_bgp_buffer();
807 |   mrt_init_message(b, MRT_BGP4MP, subtypes[d->as4 + 4*d->add_path]);
808 |   mrt_bgp_header(b, d);
809 |   mrt_put_data(b, d->message, d->msg_len);
810 |   mrt_dump_message(b, config->mrtdump_file);
