 534 | static int
 535 | ospf_iface_stubby(struct ospf_iface_patt *ip, struct ifa *addr, int type)
 536 | {
 537 |   /* vlink cannot be stub */
 538 |   if (type == OSPF_IT_VLINK)
 539 |     return 0;
 540 | 
 541 |   /* Host address on Broadcast/NBMA */
 542 |   if (((type == OSPF_IT_BCAST) || (type == OSPF_IT_NBMA)) && (addr->flags & IA_HOST))
 543 |     return 1;
 544 | 
 545 |   /* a loopback iface */
 546 |   if (addr->iface->flags & IF_LOOPBACK)
 547 |     return 1;
 548 | 
 549 |   return ip->stub;
 550 | }
