 552 | void
 553 | ospf_iface_new(struct ospf_area *oa, struct ifa *addr, struct ospf_iface_patt *ip)
 554 | {
 555 |   struct ospf_proto *p = oa->po;
 556 |   struct iface *iface = addr->iface;
 557 |   struct ospf_iface *ifa;
 558 |   struct pool *pool;
 559 | 
 560 |   if (ospf_is_v3(p))
 561 |     OSPF_TRACE(D_EVENTS, "Adding interface %s (IID %d) to area %R",
 562 | 	       iface->name, ip->instance_id, oa->areaid);
 563 |   else if (addr->flags & IA_PEER)
 564 |     OSPF_TRACE(D_EVENTS, "Adding interface %s (peer %I) to area %R",
 565 | 	       iface->name, addr->opposite, oa->areaid);
 566 |   else
 567 |     OSPF_TRACE(D_EVENTS, "Adding interface %s (%N) to area %R",
 568 | 	       iface->name, &addr->prefix, oa->areaid);
 569 | 
 570 |   pool = rp_new(p->p.pool, "OSPF Interface");
 571 |   ifa = mb_allocz(pool, sizeof(struct ospf_iface));
 572 |   ifa->iface = iface;
 573 |   ifa->addr = addr;
 574 |   ifa->oa = oa;
 575 |   ifa->cf = ip;
 576 |   ifa->pool = pool;
 577 | 
 578 |   ifa->iface_id = iface->index;
 579 |   ifa->ifname = iface->name;
 580 | 
 581 |   ifa->cost = ip->cost;
 582 |   ifa->rxmtint = ip->rxmtint;
 583 |   ifa->inftransdelay = ip->inftransdelay;
 584 |   ifa->priority = ip->priority;
 585 |   ifa->helloint = ip->helloint;
 586 |   ifa->pollint = ip->pollint;
 587 |   ifa->strictnbma = ip->strictnbma;
 588 |   ifa->waitint = ip->waitint;
 589 |   ifa->deadint = ip->deadint;
 590 |   ifa->ioprob = OSPF_I_OK;
 591 |   ifa->check_link = ip->check_link;
 592 |   ifa->ecmp_weight = ip->ecmp_weight;
 593 |   ifa->check_ttl = (ip->ttl_security == 1);
 594 |   ifa->bfd = ip->bfd;
 595 |   ifa->autype = ip->autype;
 596 |   ifa->passwords = ip->passwords;
 597 |   ifa->instance_id = ip->instance_id;
 598 | 
 599 |   /* This must be done after relevant fields are set */
 600 |   ifa->tx_length = ifa_tx_length(ifa);
 601 |   ifa->tx_hdrlen = ifa_tx_hdrlen(ifa);
 602 | 
 603 |   ifa->ptp_netmask = !(addr->flags & (IA_HOST | IA_PEER));
 604 |   if (ip->ptp_netmask < 2)
 605 |     ifa->ptp_netmask = ip->ptp_netmask;
 606 | 
 607 |   /* For compatibility, we may use ptp_address even for unnumbered links */
 608 |   ifa->ptp_address = !(addr->flags & (IA_HOST | IA_PEER)) || (p->gr_mode != OSPF_GR_ABLE);
 609 |   if (ip->ptp_address < 2)
 610 |     ifa->ptp_address = ip->ptp_address;
 611 | 
 612 |   ifa->drip = ifa->bdrip = ospf_is_v2(p) ? IPA_NONE4 : IPA_NONE6;
 613 | 
 614 |   ifa->type = ospf_iface_classify(ip->type, addr);
 615 |   ifa->stub = ospf_iface_stubby(ip, addr, ifa->type);
 616 | 
 617 |   /* Check validity of interface type */
 618 |   int old_type = ifa->type;
 619 |   u32 if_multi_flag = ip->real_bcast ? IF_BROADCAST : IF_MULTICAST;
 620 | 
 621 |   if (ospf_is_v2(p) && (ifa->type == OSPF_IT_BCAST) && (addr->flags & IA_PEER))
 622 |     ifa->type = OSPF_IT_PTP;
 623 | 
 624 |   if (ospf_is_v2(p) && (ifa->type == OSPF_IT_NBMA) && (addr->flags & IA_PEER))
 625 |     ifa->type = OSPF_IT_PTMP;
 626 | 
 627 |   if ((ifa->type == OSPF_IT_BCAST) && !(iface->flags & if_multi_flag) && !ifa->stub)
 628 |     ifa->type = OSPF_IT_NBMA;
 629 | 
 630 |   if ((ifa->type == OSPF_IT_PTP) && !(iface->flags & if_multi_flag) && !ifa->stub)
 631 |     ifa->type = OSPF_IT_PTMP;
 632 | 
 633 |   if (ifa->type != old_type)
 634 |     log(L_WARN "%s: Cannot use interface %s as %s, forcing %s",
 635 | 	p->p.name, iface->name, ospf_it[old_type], ospf_it[ifa->type]);
 636 | 
 637 | 
 638 |   if ((ifa->type == OSPF_IT_PTP) || (ifa->type == OSPF_IT_PTMP))
 639 |     ifa->link_lsa_suppression = ip->link_lsa_suppression;
 640 | 
 641 |   ifa->state = OSPF_IS_DOWN;
 642 |   init_list(&ifa->neigh_list);
 643 |   init_list(&ifa->nbma_list);
 644 | 
 645 |   struct nbma_node *nb;
 646 |   WALK_LIST(nb, ip->nbma_list)
 647 |   {
 648 |     /* In OSPFv3, addr is link-local while configured neighbors could
 649 |        have global IP (although RFC 5340 C.5 says link-local addresses
 650 |        should be used). Because OSPFv3 iface is not subnet-specific,
 651 |        there is no need for ipa_in_net() check */
 652 | 
 653 |     if (ospf_is_v2(p) && !ospf_ipa_local(nb->ip, addr))
 654 |       continue;
 655 | 
 656 |     if (ospf_is_v3(p) && !ipa_is_link_local(nb->ip))
 657 |       log(L_WARN "%s: Configured neighbor address (%I) should be link-local",
 658 | 	  p->p.name, nb->ip);
 659 | 
 660 |     add_nbma_node(ifa, nb, 0);
 661 |   }
 662 | 
 663 |   add_tail(&oa->po->iface_list, NODE ifa);
 664 | 
 665 |   struct object_lock *lock = olock_new(pool);
 666 |   lock->addr = ospf_is_v2(p) ? ipa_from_ip4(net4_prefix(&ifa->addr->prefix)) : IPA_NONE;
 667 |   lock->type = OBJLOCK_IP;
 668 |   lock->port = OSPF_PROTO;
 669 |   lock->inst = ifa->instance_id;
 670 |   lock->iface = iface;
 671 |   lock->data = ifa;
 672 |   lock->hook = ospf_iface_add;
 673 | 
 674 |   olock_acquire(lock);
 675 | }
