 677 | void
 678 | ospf_iface_new_vlink(struct ospf_proto *p, struct ospf_iface_patt *ip)
 679 | {
 680 |   struct ospf_iface *ifa;
 681 |   struct pool *pool;
 682 | 
 683 |   if (!p->vlink_sk)
