 694 |   ifa->pool = pool;
 695 | 
 696 |   /* Assign iface ID, for vlinks, this is ugly hack */
 697 |   u32 vlink_id = p->last_vlink_id++;
 698 |   ifa->iface_id = vlink_id + OSPF_VLINK_ID_OFFSET;
 699 |   ifa->ifname = (void *) (ifa + 1);
 700 |   bsprintf(ifa->ifname, "vlink%d", vlink_id);
 701 | 
 702 |   ifa->voa = ospf_find_area(p, ip->voa);
 703 |   ifa->vid = ip->vid;
 704 |   ifa->sk = p->vlink_sk;
 705 | 
 706 |   ifa->helloint = ip->helloint;
 707 |   ifa->rxmtint = ip->rxmtint;
 708 |   ifa->waitint = ip->waitint;
 709 |   ifa->deadint = ip->deadint;
 710 |   ifa->inftransdelay = ip->inftransdelay;
 711 |   ifa->autype = ip->autype;
 712 |   ifa->passwords = ip->passwords;
 713 |   ifa->instance_id = ip->instance_id;
 714 | 
 715 |   /* This must be done after relevant fields are set */
 716 |   ifa->tx_length = ospf_is_v2(p) ? IP4_MIN_MTU : IP6_MIN_MTU;
 717 |   ifa->tx_hdrlen = ifa_tx_hdrlen(ifa);
 718 | 
 719 |   ifa->type = OSPF_IT_VLINK;
 720 | 
 721 |   ifa->state = OSPF_IS_DOWN;
 722 |   init_list(&ifa->neigh_list);
 723 |   init_list(&ifa->nbma_list);
 724 | 
 725 |   add_tail(&p->iface_list, NODE ifa);
 726 | 
 727 |   ifa->hello_timer = tm_new_init(ifa->pool, hello_timer_hook, ifa, ifa->helloint S, 0);
 728 | 
 729 |   ifa->flood_queue_size = ifa_flood_queue_size(ifa);
 730 |   ifa->flood_queue = mb_allocz(ifa->pool, ifa->flood_queue_size * sizeof(void *));
