 745 | static inline void
 746 | ospf_iface_update_flood_queue_size(struct ospf_iface *ifa)
 747 | {
 748 |   uint old_size = ifa->flood_queue_size;
 749 |   uint new_size = ifa_flood_queue_size(ifa);
 750 | 
 751 |   if (new_size <= old_size)
 752 |     return;
