 759 | int
 760 | ospf_iface_reconfigure(struct ospf_iface *ifa, struct ospf_iface_patt *new)
 761 | {
 762 |   struct ospf_proto *p = ifa->oa->po;
 763 |   struct ospf_iface_patt *old = ifa->cf;
 764 |   char *ifname = ifa->ifname;
 765 | 
 766 |   /* Type could be changed in ospf_iface_new(),
 767 |      but if config values are same then also results are same */
 768 |   int old_type = ospf_iface_classify(old->type, ifa->addr);
 769 |   int new_type = ospf_iface_classify(new->type, ifa->addr);
 770 |   if (old_type != new_type)
 771 |     return 0;
 772 | 
 773 |   int new_stub = ospf_iface_stubby(new, ifa->addr, new_type);
 774 |   if (ifa->stub != new_stub)
 775 |     return 0;
 776 | 
 777 |   /* Change of these options would require to reset the iface socket */
 778 |   if ((new->real_bcast != old->real_bcast) ||
 779 |       (new->tx_tos != old->tx_tos) ||
 780 |       (new->tx_priority != old->tx_priority) ||
 781 |       (new->ttl_security != old->ttl_security))
 782 |     return 0;
 783 | 
 784 |   ifa->cf = new;
 785 |   ifa->marked = 0;
 786 | 
 787 |   /* Cancel GR peers if GR is disabled */
 788 |   if (!p->gr_mode && p->gr_count)
 789 |   {
 790 |     struct ospf_neighbor *n, *nx;
 791 |     WALK_LIST_DELSAFE(n, nx, ifa->neigh_list)
 792 |       if (n->gr_active)
 793 | 	ospf_neigh_cancel_graceful_restart(n);
 794 |   }
 795 | 
 796 |   /* HELLO TIMER */
 797 |   if (ifa->helloint != new->helloint)
 798 |   {
 799 |     OSPF_TRACE(D_EVENTS, "Changing hello interval of %s from %d to %d",
 800 | 	       ifname, ifa->helloint, new->helloint);
 801 | 
 802 |     ifa->helloint = new->helloint;
 803 |     ospf_iface_change_timer(ifa->hello_timer, ifa->helloint);
 804 |   }
 805 | 
 806 |   /* RXMT TIMER */
 807 |   if (ifa->rxmtint != new->rxmtint)
 808 |   {
 809 |     OSPF_TRACE(D_EVENTS, "Changing retransmit interval of %s from %d to %d",
 810 | 	       ifname, ifa->rxmtint, new->rxmtint);
 811 | 
 812 |     ifa->rxmtint = new->rxmtint;
 813 |     /* FIXME: Update neighbors' timers */
 814 |   }
 815 | 
 816 |   /* POLL TIMER */
 817 |   if (ifa->pollint != new->pollint)
 818 |   {
 819 |     OSPF_TRACE(D_EVENTS, "Changing poll interval of %s from %d to %d",
 820 | 	       ifname, ifa->pollint, new->pollint);
 821 | 
 822 |     ifa->pollint = new->pollint;
 823 |     ospf_iface_change_timer(ifa->poll_timer, ifa->pollint);
 824 |   }
 825 | 
 826 |   /* WAIT TIMER */
 827 |   if (ifa->waitint != new->waitint)
 828 |   {
 829 |     OSPF_TRACE(D_EVENTS, "Changing wait interval of %s from %d to %d",
 830 | 	       ifname, ifa->waitint, new->waitint);
 831 | 
 832 |     ifa->waitint = new->waitint;
 833 |     if (ifa->wait_timer && tm_active(ifa->wait_timer))
 834 |       tm_start(ifa->wait_timer, ifa->waitint S);
 835 |   }
 836 | 
 837 |   /* DEAD TIMER */
 838 |   if (ifa->deadint != new->deadint)
 839 |   {
 840 |     OSPF_TRACE(D_EVENTS, "Changing dead interval of %s from %d to %d",
 841 | 	       ifname, ifa->deadint, new->deadint);
 842 |     ifa->deadint = new->deadint;
 843 |   }
 844 | 
 845 |   /* INFTRANS */
 846 |   if (ifa->inftransdelay != new->inftransdelay)
 847 |   {
 848 |     OSPF_TRACE(D_EVENTS, "Changing transmit delay of %s from %d to %d",
 849 | 		     ifname, ifa->inftransdelay, new->inftransdelay);
 850 |     ifa->inftransdelay = new->inftransdelay;
 851 |   }
 852 | 
 853 |   /* AUTHENTICATION */
 854 |   if (ifa->autype != new->autype)
 855 |   {
 856 |     OSPF_TRACE(D_EVENTS, "Changing authentication type of %s", ifname);
 857 |     ifa->autype = new->autype;
 858 | 
 859 |     /* For OSPFv3, we need to update checksum calculation by OS */
 860 |     if (ospf_is_v3(p) && ifa->sk)
 861 |       if (sk_set_ipv6_checksum(ifa->sk, ifa->autype ? -1 : 12) < 0)
 862 |       {
 863 | 	sk_log_error(ifa->sk, p->p.name);
 864 | 	return 0;
 865 |       }
 866 |   }
 867 | 
 868 |   /* Update passwords */
 869 |   ifa->passwords = new->passwords;
 870 | 
 871 |   /* Update header length */
 872 |   ifa->tx_hdrlen = ifa_tx_hdrlen(ifa);
 873 | 
 874 |   /* Remaining options are just for proper interfaces */
 875 |   if (ifa->type == OSPF_IT_VLINK)
 876 |     return 1;
 877 | 
 878 | 
 879 |   /* COST */
 880 |   if (ifa->cost != new->cost)
 881 |   {
 882 |     OSPF_TRACE(D_EVENTS, "Changing cost of %s from %d to %d",
 883 | 	       ifname, ifa->cost, new->cost);
 884 | 
 885 |     ifa->cost = new->cost;
 886 |   }
 887 | 
 888 |   /* PRIORITY */
 889 |   if (ifa->priority != new->priority)
 890 |   {
 891 |     OSPF_TRACE(D_EVENTS, "Changing priority of %s from %d to %d",
 892 | 	       ifname, ifa->priority, new->priority);
 893 | 
 894 |     ifa->priority = new->priority;
 895 |     ospf_iface_sm(ifa, ISM_NEICH);
 896 |     ospf_notify_link_lsa(ifa);
 897 |   }
 898 | 
 899 |   /* STRICT NBMA */
 900 |   if (ifa->strictnbma != new->strictnbma)
 901 |   {
 902 |     OSPF_TRACE(D_EVENTS, "Changing NBMA strictness of %s from %d to %d",
 903 | 	       ifname, ifa->strictnbma, new->strictnbma);
 904 |     ifa->strictnbma = new->strictnbma;
 905 |   }
 906 | 
 907 |   struct nbma_node *nb, *nbx;
 908 | 
 909 |   /* NBMA LIST - remove or update old */
 910 |   WALK_LIST_DELSAFE(nb, nbx, ifa->nbma_list)
 911 |   {
 912 |     struct nbma_node *nb2 = find_nbma_node_(&new->nbma_list, nb->ip);
 913 |     if (nb2)
 914 |     {
 915 |       if (nb->eligible != nb2->eligible)
 916 |       {
 917 | 	OSPF_TRACE(D_EVENTS, "Changing eligibility of NBMA neighbor %I on %s",
 918 | 		   nb->ip, ifname);
 919 | 	nb->eligible = nb2->eligible;
 920 |       }
 921 |     }
 922 |     else
 923 |     {
 924 |       OSPF_TRACE(D_EVENTS, "Removing NBMA neighbor %I on %s",
 925 | 		       nb->ip, ifname);
 926 |       rem_node(NODE nb);
 927 |       mb_free(nb);
 928 |     }
 929 |   }
 930 | 
 931 |   /* NBMA LIST - add new */
 932 |   WALK_LIST(nb, new->nbma_list)
 933 |   {
 934 |     /* See related note in ospf_iface_new() */
 935 |     if (ospf_is_v2(p) && !ospf_ipa_local(nb->ip, ifa->addr))
 936 |       continue;
 937 | 
 938 |     if (ospf_is_v3(p) && !ipa_is_link_local(nb->ip))
 939 |       log(L_WARN "%s: Configured neighbor address (%I) should be link-local",
 940 | 	  p->p.name, nb->ip);
 941 | 
 942 |     if (! find_nbma_node(ifa, nb->ip))
 943 |     {
 944 |       OSPF_TRACE(D_EVENTS, "Adding NBMA neighbor %I on %s",
 945 | 		 nb->ip, ifname);
 946 |       add_nbma_node(ifa, nb, !!find_neigh_by_ip(ifa, nb->ip));
 947 |     }
 948 |   }
 949 | 
 950 |   int update_buffers = 0;
 951 | 
 952 |   /* TX LENGTH */
 953 |   if (old->tx_length != new->tx_length)
 954 |   {
 955 |     OSPF_TRACE(D_EVENTS, "Changing TX length of %s from %d to %d",
 956 | 	       ifname, old->tx_length, new->tx_length);
 957 | 
 958 |     /* ifa cannot be vlink */
 959 |     ifa->tx_length = ifa_tx_length(ifa);
 960 |     update_buffers = 1;
 961 | 
 962 |     if (!ifa->stub)
 963 |       ospf_iface_update_flood_queue_size(ifa);
 964 |   }
 965 | 
 966 |   /* RX BUFFER */
 967 |   if (old->rx_buffer != new->rx_buffer)
 968 |   {
 969 |     OSPF_TRACE(D_EVENTS, "Changing buffer size of %s from %d to %d",
 970 | 	       ifname, old->rx_buffer, new->rx_buffer);
 971 | 
 972 |     /* ifa cannot be vlink */
 973 |     update_buffers = 1;
 974 |   }
 975 | 
 976 |   /* Buffer size depends on both tx_length and rx_buffer options */
 977 |   if (update_buffers && ifa->sk)
 978 |   {
 979 |     uint bsize = ifa_bufsize(ifa);
 980 |     sk_set_rbsize(ifa->sk, bsize);
 981 |     sk_set_tbsize(ifa->sk, bsize);
 982 |   }
 983 | 
 984 |   /* LINK */
 985 |   if (ifa->check_link != new->check_link)
 986 |   {
 987 |     OSPF_TRACE(D_EVENTS, "%s link check for %s",
 988 | 	       new->check_link ? "Enabling" : "Disabling", ifname);
 989 |     ifa->check_link = new->check_link;
 990 | 
 991 |     /* ifa cannot be vlink */
 992 |     if (!(ifa->iface->flags & IF_LINK_UP))
 993 |       ospf_iface_sm(ifa, ifa->check_link ? ISM_LOOP : ISM_UNLOOP);
 994 |   }
 995 | 
 996 |   /* ECMP weight */
 997 |   if (ifa->ecmp_weight != new->ecmp_weight)
 998 |   {
 999 |     OSPF_TRACE(D_EVENTS, "Changing ECMP weight of %s from %d to %d",
1000 | 	       ifname, (int)ifa->ecmp_weight + 1, (int)new->ecmp_weight + 1);
1001 |     ifa->ecmp_weight = new->ecmp_weight;
1002 |   }
1003 | 
1004 |   /* Link LSA suppression */
1005 |   if (((ifa->type == OSPF_IT_PTP) || (ifa->type == OSPF_IT_PTMP)) &&
1006 |       (ifa->link_lsa_suppression != new->link_lsa_suppression))
1007 |   {
1008 |     OSPF_TRACE(D_EVENTS, "Changing link LSA suppression of %s from %d to %d",
1009 | 	       ifname, ifa->link_lsa_suppression, new->link_lsa_suppression);
1010 | 
1011 |     ifa->link_lsa_suppression = new->link_lsa_suppression;
1012 |     ospf_notify_link_lsa(ifa);
1013 |   }
1014 | 
1015 |   /* PtP netmask */
1016 |   int new_ptp_netmask = (new->ptp_netmask < 2) ? new->ptp_netmask :
1017 |     !(ifa->addr->flags & (IA_HOST | IA_PEER));
1018 |   if (ifa->ptp_netmask != new_ptp_netmask)
1019 |   {
1020 |     OSPF_TRACE(D_EVENTS, "Changing PtP netmask option of %s from %d to %d",
1021 | 	       ifname, ifa->ptp_netmask, new_ptp_netmask);
1022 |     ifa->ptp_netmask = new_ptp_netmask;
1023 |   }
1024 | 
1025 |   /* PtP address */
1026 |   int new_ptp_address = (new->ptp_address < 2) ? new->ptp_address :
1027 |     (!(ifa->addr->flags & (IA_HOST | IA_PEER)) || (p->gr_mode != OSPF_GR_ABLE));
1028 |   if (ifa->ptp_address != new_ptp_address)
1029 |   {
1030 |     /* Keep it silent for implicit changes */
1031 |     if (new->ptp_address < 2)
1032 |       OSPF_TRACE(D_EVENTS, "Changing PtP address option of %s from %d to %d",
1033 | 		 ifname, ifa->ptp_address, new_ptp_address);
1034 | 
1035 |     ifa->ptp_address = new_ptp_address;
1036 |   }
1037 | 
1038 |   /* BFD */
1039 |   if (ifa->bfd != new->bfd)
1040 |   {
1041 |     OSPF_TRACE(D_EVENTS, "%s BFD for %s",
1042 | 	       new->bfd ? "Enabling" : "Disabling", ifname);
1043 |     ifa->bfd = new->bfd;
1044 | 
1045 |     struct ospf_neighbor *n;
1046 |     WALK_LIST(n, ifa->neigh_list)
1047 |       ospf_neigh_update_bfd(n, ifa->bfd);
1048 |   }
1049 | 
1050 | 
1051 |   /* instance_id is not updated - it is part of key */
1052 | 
1053 |   return 1;
1054 | }
