1056 | 
1057 | /*
1058 |  * State for matching iface pattterns walk
1059 |  *
1060 |  * This is significantly different in OSPFv2 and OSPFv3.
1061 |  * In OSPFv2, OSPF ifaces are created for each IP prefix (struct ifa)
1062 |  * In OSPFv3, OSPF ifaces are created based on real iface (struct iface)
1063 |  * We support instance_id for both OSPFv2 (RFC 6549) and OSPFv3.
1064 |  *
1065 |  * We process one ifa/iface and match it for all configured instance IDs. We
1066 |  * maintain bitfields to track whether given instance ID was already matched.
1067 |  * We have two bitfields, one global (active) and one per area (ignore), to
1068 |  * detect misconfigured cases where one iface with one instance ID matches in
1069 |  * multiple areas.
1070 |  */
1071 | 
1072 | struct ospf_mip_walk {
1073 |   u32 active[8];		/* Bitfield of active instance IDs */
1074 |   u32 ignore[8];		/* Bitfield of instance IDs matched in current area */
1075 |   struct ospf_area *oa;		/* Current area */
1076 |   struct ospf_iface_patt *ip;	/* Current iface pattern */
1077 |   struct iface *iface;		/* Specified iface (input) */
1078 |   struct ifa *a;		/* Specified ifa (input) */
1079 |   int warn;			/* Whether iface matched in multiple areas */
1080 | };
1081 | 
1082 | static int
1083 | ospf_walk_matching_iface_patts(struct ospf_proto *p, struct ospf_mip_walk *s)
1084 | {
1085 |   int id;
1086 | 
1087 |   if (s->ip)
1088 |     goto step;
1089 | 
1090 |   WALK_LIST(s->oa, p->area_list)
1091 |   {
1092 |     if (s->oa->marked)
1093 |       continue;
1094 | 
1095 |     WALK_LIST(s->ip, s->oa->ac->patt_list)
1096 |     {
1097 |       id = s->ip->instance_id;
1098 |       if (BIT32_TEST(s->ignore, id))
1099 | 	continue;
1100 | 
1101 |       if (iface_patt_match(&s->ip->i, s->iface, s->a))
1102 |       {
1103 | 	/* Now we matched ifa/iface/instance_id for the first time in current area */
1104 | 	BIT32_SET(s->ignore, id);
1105 | 
1106 | 	/* If we already found it in previous areas, ignore it and add warning */
1107 | 	if (BIT32_TEST(s->active, id))
1108 | 	  { s->warn = 1; continue; }
1109 | 
1110 | 	BIT32_SET(s->active, id);
1111 | 	return 1;
1112 |       step:
1113 | 	;
1114 |       }
1115 |     }
1116 |     BIT32_ZERO(s->ignore, 256);
1117 |   }
1118 | 
1119 |   if (s->warn)
1120 |     log(L_WARN "%s: Interface %s matches for multiple areas", p->p.name, s->iface->name);
1121 | 
1122 |   return 0;
1123 | }
1124 | 
1125 | 
1126 | static struct ospf_iface *
1127 | ospf_iface_find_by_key(struct ospf_proto *p, struct ifa *a, int instance_id)
1128 | {
1129 |   struct ospf_iface *ifa;
1130 | 
1131 |   WALK_LIST(ifa, p->iface_list)
1132 |     if ((ifa->addr == a) && (ifa->instance_id == instance_id) &&
1133 | 	(ifa->type != OSPF_IT_VLINK))
1134 |       return ifa;
1135 | 
1136 |   return NULL;
1137 | }
