1139 | 
1140 | void
1141 | ospf_ifa_notify2(struct proto *P, uint flags, struct ifa *a)
1142 | {
1143 |   struct ospf_proto *p = (struct ospf_proto *) P;
1144 | 
1145 |   if (a->prefix.type != NET_IP4)
1146 |     return;
1147 | 
1148 |   if (a->flags & IA_SECONDARY)
1149 |     return;
1150 | 
1151 |   if (a->scope <= SCOPE_LINK)
1152 |     return;
1153 | 
1154 |   /* In OSPFv2, we create OSPF iface for each address. */
1155 |   if (flags & IF_CHANGE_UP)
1156 |   {
1157 |     struct ospf_mip_walk s = { .iface = a->iface, .a = a };
1158 |     while (ospf_walk_matching_iface_patts(p, &s))
1159 |       ospf_iface_new(s.oa, a, s.ip);
1160 |   }
1161 | 
1162 |   if (flags & IF_CHANGE_DOWN)
1163 |   {
1164 |     struct ospf_iface *ifa, *ifx;
1165 |     WALK_LIST_DELSAFE(ifa, ifx, p->iface_list)
1166 |       if ((ifa->type != OSPF_IT_VLINK) && (ifa->addr == a))
1167 | 	ospf_iface_remove(ifa);
1168 |     /* See a note in ospf_iface_notify() */
1169 |   }
1170 | }
1171 | 
1172 | void
1173 | ospf_ifa_notify3(struct proto *P, uint flags, struct ifa *a)
1174 | {
1175 |   struct ospf_proto *p = (struct ospf_proto *) P;
1176 | 
1177 |   if (a->flags & IA_SECONDARY)
1178 |     return;
1179 | 
1180 |   if (a->scope < SCOPE_LINK)
1181 |     return;
1182 | 
1183 |   /* In OSPFv3, we create OSPF iface for link-local address,
1184 |      other addresses are used for link-LSA. */
1185 |   if (a->scope == SCOPE_LINK)
1186 |   {
1187 |     if (a->prefix.type != NET_IP6)
1188 |       return;
1189 | 
1190 |     if (flags & IF_CHANGE_UP)
1191 |     {
1192 |       struct ospf_mip_walk s = { .iface = a->iface };
1193 |       while (ospf_walk_matching_iface_patts(p, &s))
1194 | 	ospf_iface_new(s.oa, a, s.ip);
1195 |     }
1196 | 
1197 |     if (flags & IF_CHANGE_DOWN)
1198 |     {
1199 |       struct ospf_iface *ifa, *ifx;
1200 |       WALK_LIST_DELSAFE(ifa, ifx, p->iface_list)
1201 | 	if ((ifa->addr == a) && (ifa->type != OSPF_IT_VLINK))
1202 | 	  ospf_iface_remove(ifa);
1203 |     }
1204 |   }
1205 |   else
1206 |   {
1207 |     if (a->prefix.type != ospf_get_af(p))
1208 |       return;
1209 | 
1210 |     struct ospf_iface *ifa;
1211 |     WALK_LIST(ifa, p->iface_list)
1212 |       if (ifa->iface == a->iface)
1213 |       {
1214 | 	/* RFC 5340 4.4.3 Event 5 - prefix added/deleted */
1215 | 	ospf_notify_link_lsa(ifa);
1216 | 	ospf_notify_rt_lsa(ifa->oa);
1217 |       }
1218 |   }
1219 | }
