1222 | static void
1223 | ospf_reconfigure_ifaces2(struct ospf_proto *p)
1224 | {
1225 |   struct iface *iface;
1226 |   struct ifa *a;
1227 | 
1228 |   WALK_LIST(iface, iface_list)
1229 |   {
1230 |     if (p->p.vrf_set && !if_in_vrf(iface, p->p.vrf))
1231 |       continue;
1232 | 
1233 |     if (! (iface->flags & IF_UP))
1234 |       continue;
1235 | 
1236 |     WALK_LIST(a, iface->addrs)
1237 |     {
1238 |       if (a->prefix.type != NET_IP4)
1239 | 	continue;
1240 | 
1241 |       if (a->flags & IA_SECONDARY)
1242 | 	continue;
1243 | 
1244 |       if (a->scope <= SCOPE_LINK)
1245 | 	continue;
1246 | 
1247 |       struct ospf_mip_walk s = { .iface = iface, .a = a };
1248 |       while (ospf_walk_matching_iface_patts(p, &s))
1249 |       {
1250 | 	/* Main inner loop */
1251 | 	struct ospf_iface *ifa = ospf_iface_find_by_key(p, a, s.ip->instance_id);
1252 | 	if (ifa)
1253 | 	{
1254 | 	  if ((ifa->oa == s.oa) && (ifa->marked < 2) &&
1255 | 	      ospf_iface_reconfigure(ifa, s.ip))
1256 | 	    continue;
1257 | 
1258 | 	  /* Hard restart */
1259 | 	  log(L_INFO "%s: Restarting interface %s (%N) in area %R",
1260 | 	      p->p.name, ifa->ifname, &a->prefix, s.oa->areaid);
1261 | 	  ospf_iface_shutdown(ifa);
1262 | 	  ospf_iface_remove(ifa);
1263 | 	}
1264 | 
1265 | 	ospf_iface_new(s.oa, a, s.ip);
1266 |       }
1267 |     }
1268 |   }
1269 | }
1270 | 
1271 | static void
1272 | ospf_reconfigure_ifaces3(struct ospf_proto *p)
1273 | {
1274 |   struct iface *iface;
1275 |   struct ifa *a;
1276 | 
1277 |   WALK_LIST(iface, iface_list)
1278 |   {
1279 |     if (p->p.vrf_set && !if_in_vrf(iface, p->p.vrf))
1280 |       continue;
1281 | 
1282 |     if (! (iface->flags & IF_UP))
1283 |       continue;
1284 | 
1285 |     WALK_LIST(a, iface->addrs)
1286 |     {
1287 |       if (a->prefix.type != NET_IP6)
1288 | 	continue;
1289 | 
1290 |       if (a->flags & IA_SECONDARY)
1291 | 	continue;
1292 | 
1293 |       if (a->scope != SCOPE_LINK)
1294 | 	continue;
1295 | 
1296 |       struct ospf_mip_walk s = { .iface = iface };
1297 |       while (ospf_walk_matching_iface_patts(p, &s))
1298 |       {
1299 | 	/* Main inner loop */
1300 | 	struct ospf_iface *ifa = ospf_iface_find_by_key(p, a, s.ip->instance_id);
1301 | 	if (ifa)
1302 | 	{
1303 | 	  if ((ifa->oa == s.oa) && (ifa->marked < 2) &&
1304 | 	      ospf_iface_reconfigure(ifa, s.ip))
1305 | 	    continue;
1306 | 
1307 | 	  /* Hard restart */
1308 | 	  log(L_INFO "%s: Restarting interface %s (IID %d) in area %R",
1309 | 	      p->p.name, ifa->ifname, ifa->instance_id, s.oa->areaid);
1310 | 	  ospf_iface_shutdown(ifa);
1311 | 	  ospf_iface_remove(ifa);
1312 | 	}
1313 | 
1314 | 	ospf_iface_new(s.oa, a, s.ip);
1315 |       }
1316 |     }
1317 |   }
1318 | }
1319 | 
1320 | void
1321 | ospf_reconfigure_ifaces(struct ospf_proto *p)
1322 | {
1323 |   if (ospf_is_v2(p))
1324 |     ospf_reconfigure_ifaces2(p);
1325 |   else
1326 |     ospf_reconfigure_ifaces3(p);
1327 | }
