1330 | static void
1331 | ospf_iface_change_mtu(struct ospf_proto *p, struct ospf_iface *ifa)
1332 | {
1333 |   /* ifa is not vlink */
1334 | 
1335 |   OSPF_TRACE(D_EVENTS, "Interface %s changed MTU to %d",
1336 | 	     ifa->ifname, ifa->iface->mtu);
1337 | 
1338 |   ifa->tx_length = ifa_tx_length(ifa);
1339 | 
1340 |   if (!ifa->sk)
1341 |     return;
1342 | 
1343 |   /* We do not shrink dynamic buffers */
1344 |   uint bsize = ifa_bufsize(ifa);
1345 |   if (bsize > ifa->sk->rbsize)
1346 |     sk_set_rbsize(ifa->sk, bsize);
1347 |   if (bsize > ifa->sk->tbsize)
1348 |     sk_set_tbsize(ifa->sk, bsize);
1349 | 
1350 |   if (!ifa->stub)
1351 |     ospf_iface_update_flood_queue_size(ifa);
1352 | }
1353 | 
1354 | static void
1355 | ospf_iface_notify(struct ospf_proto *p, uint flags, struct ospf_iface *ifa)
1356 | {
1357 |   /* ifa is not vlink */
1358 | 
1359 |   if (flags & IF_CHANGE_DOWN)
1360 |   {
1361 |     ospf_iface_remove(ifa);
1362 |     return;
1363 |   }
1364 | 
1365 |   if (flags & IF_CHANGE_LINK)
1366 |     ospf_iface_sm(ifa, (ifa->iface->flags & IF_LINK_UP) ? ISM_UNLOOP : ISM_LOOP);
1367 | 
1368 |   if (flags & IF_CHANGE_MTU)
1369 |     ospf_iface_change_mtu(p, ifa);
1370 | }
1371 | 
1372 | void
1373 | ospf_if_notify(struct proto *P, uint flags, struct iface *iface)
1374 | {
1375 |   struct ospf_proto *p = (struct ospf_proto *) P;
1376 | 
1377 |   /*
1378 |   if (iface->flags & IF_IGNORE)
1379 |     return;
1380 |   */
1381 | 
1382 |   /* Going up means that there are no such ifaces yet */
1383 |   if (flags & IF_CHANGE_UP)
1384 |     return;
