 46 |   uint i, lsa_count;
 47 | 
 48 |   ASSERT(pkt->type == LSACK_P);
 49 |   ospf_dump_common(p, pkt);
 50 | 
 51 |   ospf_lsack_body(p, pkt, &lsas, &lsa_count);
 52 |   for (i = 0; i < lsa_count; i++)
