 58 | ospf_enqueue_lsack(struct ospf_neighbor *n, struct ospf_lsa_header *h_n, int queue)
 59 | {
 60 |   /* Note that h_n is in network endianity */
 61 |   struct lsa_node *no = mb_alloc(n->pool, sizeof(struct lsa_node));
 62 |   no->n = (node) {};
 63 |   memcpy(&no->lsa, h_n, sizeof(struct ospf_lsa_header));
 64 |   add_tail(&n->ackl[queue], NODE no);
 65 |   DBG("Adding %s ack for %R, ID: %R, RT: %R, Type: %u\n",
 66 |       (queue == ACKL_DIRECT) ? "direct" : "delayed",
 67 |       n->rid, ntohl(h_n->id), ntohl(h_n->rt), h_n->type);
