 82 | static inline void
 83 | ospf_send_lsack_(struct ospf_proto *p, struct ospf_neighbor *n, int queue)
 84 | {
 85 |   struct ospf_iface *ifa = n->ifa;
 86 |   struct ospf_lsa_header *lsas;
 87 |   struct ospf_packet *pkt;
 88 |   struct lsa_node *no;
 89 |   uint i, lsa_max, length;
 90 | 
 91 |   /* RFC 2328 13.5 */
 92 | 
 93 |   pkt = ospf_tx_buffer(ifa);
 94 |   ospf_pkt_fill_hdr(ifa, pkt, LSACK_P);
 95 |   ospf_lsack_body(p, pkt, &lsas, &lsa_max);
 96 | 
 97 |   for (i = 0; i < lsa_max && !EMPTY_LIST(n->ackl[queue]); i++)
 98 |   {
 99 |     no = (struct lsa_node *) HEAD(n->ackl[queue]);
100 |     memcpy(&lsas[i], &no->lsa, sizeof(struct ospf_lsa_header));
101 |     DBG("Iter %u ID: %R, RT: %R, Type: %04x\n",
102 | 	i, ntohl(lsas[i].id), ntohl(lsas[i].rt), lsas[i].type);
103 |     rem_node(NODE no);
104 |     mb_free(no);
105 |   }
106 | 
107 |   length = ospf_pkt_hdrlen(p) + i * sizeof(struct ospf_lsa_header);
108 |   pkt->length = htons(length);
109 | 
110 |   if (queue == ACKL_DIRECT)
111 |   {
112 |     OSPF_PACKET(ospf_dump_lsack, pkt, "LSACK packet sent to nbr %R on %s", n->rid, ifa->ifname);
113 |     ospf_send_to_nbr(ifa, n);
114 |   }
115 |   else
116 |   {
117 |     OSPF_PACKET(ospf_dump_lsack, pkt, "LSACK packet sent via %s", ifa->ifname);
118 |     ospf_send_to_iface(ifa);
119 |   }
120 | }
