 68 | lsa_flooding_allowed(u32 type, u32 domain, struct ospf_iface *ifa)
 69 | {
 70 |   /* Handle inactive vlinks */
 71 |   if (ifa->state == OSPF_IS_DOWN)
 72 |     return 0;
