 74 |   /* 4.5.2 (Case 2) */
 75 |   switch (LSA_SCOPE(type))
 76 |   {
 77 |   case LSA_SCOPE_LINK:
 78 |     return ifa->iface_id == domain;
 79 | 
 80 |   case LSA_SCOPE_AREA:
 81 |     return ifa->oa->areaid == domain;
 82 | 
 83 |   case LSA_SCOPE_AS:
 84 |     if (ifa->type == OSPF_IT_VLINK)
