307 | int
308 | lsa_validate_tlvs(byte *buf, uint len)
309 | {
310 |   byte *pos = buf;
311 |   byte *end = buf + len;
312 | 
313 |   while (pos < end)
314 |   {
315 |     if ((pos + sizeof(struct ospf_tlv)) > end)
316 |       return 0;
317 | 
318 |     struct ospf_tlv *tlv = (void *) pos;
319 |     uint len = LSA_TLV_LENGTH(tlv);
320 | 
321 |     if ((pos + len) > end)
322 |       return 0;
323 | 
324 |     pos += len;
325 |   }
326 | 
