403 |     *pxopts = (opts & OPT_DN) ? OPT_PX_DN : 0;
404 |     *metric = ls->metric & LSA_METRIC_MASK;
405 |   }
406 |   else
407 |   {
408 |     struct ospf_lsa_sum3_net *ls = en->lsa_body;
409 |     ospf3_get_prefix(ls->prefix, af, net, pxopts, NULL);
410 |     *metric = ls->metric & LSA_METRIC_MASK;
411 |   }
412 | }
