515 |   buf += sizeof(struct ospf_lsa_rt);
516 | 
517 |   while (buf < bufend)
518 |   {
519 |     struct ospf_lsa_rt3_link *l = buf;
520 |     buf += sizeof(struct ospf_lsa_rt3_link);
521 | 
522 |     if (buf > bufend)
523 |       return 0;
524 | 
525 |     if (!((l->type == LSART_PTP) ||
526 | 	  (l->type == LSART_NET) ||
527 | 	  (l->type == LSART_VLNK)))
528 |       return 0;
529 |   }
530 |   return 1;
531 | }
