100 |   {
101 |     /* Do not check NSSA-LSA here, as OPT_N is only in HELLO packets */
102 | 
103 |     if (lsa_is_opaque(type))
104 |       return !!(n->options & OPT_O);
105 | 
106 |     return 1;
