120 | static int
121 | unknown_lsa_type(u32 type)
122 | {
123 |   switch (type)
124 |   {
125 |   case LSA_T_RT:
126 |   case LSA_T_NET:
127 |   case LSA_T_SUM_NET:
128 |   case LSA_T_SUM_RT:
129 |   case LSA_T_EXT:
130 |   case LSA_T_NSSA:
131 |   case LSA_T_LINK:
132 |   case LSA_T_PREFIX:
133 |   case LSA_T_RI_LINK:
134 |   case LSA_T_RI_AREA:
135 |   case LSA_T_RI_AS:
136 |     return 0;
137 | 
138 |   default:
139 |     return 1;
