208 | int
209 | lsa_is_opaque(u32 type)
210 | {
211 |   u32 fn = LSA_FUNCTION(type);
212 |   return LOOKUP(opaque_lsa_types_inv, fn) || (fn == LSA_T_OPAQUE_);
213 | }
