332 | lsa_walk_rt2(struct ospf_lsa_rt_walk *rt)
333 | {
334 |   if (rt->buf >= rt->bufend)
335 |     return 0;
336 | 
337 |   struct ospf_lsa_rt2_link *l = rt->buf;
338 |   rt->buf += sizeof(struct ospf_lsa_rt2_link) + l->no_tos * sizeof(struct ospf_lsa_rt2_tos);
