347 | static inline int
348 | lsa_walk_rt3(struct ospf_lsa_rt_walk *rt)
349 | {
350 |   while (rt->buf >= rt->bufend)
351 |   {
352 |     rt->en = ospf_hash_find_rt3_next(rt->en);
353 |     if (!rt->en)
354 |       return 0;
