360 | 
361 |   struct ospf_lsa_rt3_link *l = rt->buf;
362 |   rt->buf += sizeof(struct ospf_lsa_rt3_link);
363 | 
364 |   rt->type = l->type;
365 |   rt->metric = l->metric;
366 |   rt->lif = l->lif;
367 |   rt->nif = l->nif;
368 |   rt->id = l->id;
