474 | lsa_validate_rt2(struct ospf_lsa_header *lsa, struct ospf_lsa_rt *body)
475 | {
476 |   if (lsa->length < (HDRLEN + sizeof(struct ospf_lsa_rt)))
477 |     return 0;
