630 |   for (i = 0; i < pxcount; i++)
631 |     {
632 |       if (offset > bound)
633 | 	return 0;
634 | 
635 |       u8 pxl = pxlen((u32 *) (pbuf + offset));
636 |       if (pxl > IP6_MAX_PREFIX_LENGTH)
637 | 	return 0;
638 | 
639 |       offset += IPV6_PREFIX_SPACE(pxl);
640 |     }
641 | 
642 |   if (lsa->length != (HDRLEN + offset))
643 |     return 0;
644 | 
