430 | ospf_rxmt_lsupd(struct ospf_proto *p, struct ospf_neighbor *n)
431 | {
432 |   uint max = 2 * n->ifa->flood_queue_size;
433 |   struct top_hash_entry *entries[max];
434 |   struct top_hash_entry *ret, *nxt, *en;
435 |   uint i = 0;
