439 |   WALK_SLIST_DELSAFE(ret, nxt, n->lsrtl)
440 |   {
441 |     if (i == max)
442 |       break;
443 | 
444 |     en = ospf_hash_find_entry(p->gr, ret);
445 |     if (!en)
