476 | void
477 | ospf_receive_lsupd(struct ospf_packet *pkt, struct ospf_iface *ifa,
478 | 		   struct ospf_neighbor *n)
479 | {
480 |   struct ospf_proto *p = ifa->oa->po;
481 |   const char *err_dsc = NULL;
482 |   uint plen, err_val = 0;
483 | 
484 |   /* RFC 2328 13. */
485 | 
486 |   plen = ntohs(pkt->length);
487 |   if (plen < ospf_lsupd_hdrlen(p))
488 |   {
489 |     LOG_PKT("Bad LSUPD packet from nbr %R on %s - %s (%u)", n->rid, ifa->ifname, "too short", plen);
490 |     return;
491 |   }
492 | 
493 |   OSPF_PACKET(ospf_dump_lsupd, pkt, "LSUPD packet received from nbr %R on %s", n->rid, ifa->ifname);
494 | 
495 |   if (n->state < NEIGHBOR_EXCHANGE)
496 |   {
497 |     OSPF_TRACE(D_PACKETS, "LSUPD packet ignored - lesser state than Exchange");
498 |     return;
499 |   }
500 | 
501 |   ospf_neigh_sm(n, INM_HELLOREC);	/* Questionable */
502 | 
503 |   uint offset, i, lsa_count;
504 |   ospf_lsupd_body(p, pkt, &offset, &lsa_count);
505 | 
506 |   for (i = 0; i < lsa_count; i++)
507 |   {
508 |     struct ospf_lsa_header lsa, *lsa_n;
509 |     struct top_hash_entry *en;
510 |     u32 lsa_len, lsa_type, lsa_domain;
511 | 
512 |     if ((offset + sizeof(struct ospf_lsa_header)) > plen)
513 |       DROP("too short", plen);
514 | 
515 |     /* LSA header in network order */
516 |     lsa_n = ((void *) pkt) + offset;
517 |     lsa_len = ntohs(lsa_n->length);
518 |     offset += lsa_len;
519 | 
520 |     if (offset > plen)
521 |       DROP("too short", plen);
522 | 
523 |     if (((lsa_len % 4) != 0) || (lsa_len <= sizeof(struct ospf_lsa_header)))
524 |       DROP("invalid LSA length", lsa_len);
525 | 
526 |     /* LSA header in host order */
527 |     lsa_ntoh_hdr(lsa_n, &lsa);
528 |     lsa_get_type_domain(&lsa, ifa, &lsa_type, &lsa_domain);
529 | 
530 |     DBG("Update Type: %04x, Id: %R, Rt: %R, Sn: 0x%08x, Age: %u, Sum: %u\n",
531 | 	lsa_type, lsa.id, lsa.rt, lsa.sn, lsa.age, lsa.checksum);
532 | 
533 |     /* RFC 2328 13. (1) - verify LSA checksum */
534 |     if ((lsa_n->checksum == 0) || !lsa_verify_checksum(lsa_n, lsa_len))
535 |       SKIP("invalid checksum");
536 | 
537 |     /* RFC 2328 13. (2) */
538 |     if (!lsa_type)
539 |       SKIP("unknown type");
540 | 
541 |     /* RFC 5340 4.5.1 (2) and RFC 2328 13. (3) */
542 |     if (!oa_is_ext(ifa->oa) && (LSA_SCOPE(lsa_type) == LSA_SCOPE_AS))
543 |       SKIP("AS scope in stub area");
544 | 
545 |     /* Errata 3746 to RFC 2328 - rt-summary-LSAs forbidden in stub areas */
546 |     if (!oa_is_ext(ifa->oa) && (lsa_type == LSA_T_SUM_RT))
547 |       SKIP("rt-summary-LSA in stub area");
548 | 
549 |     /* RFC 5340 4.5.1 (3) */
550 |     if (LSA_SCOPE(lsa_type) == LSA_SCOPE_RES)
551 |       SKIP("invalid scope");
552 | 
553 |     /* Find local copy of LSA in link state database */
554 |     en = ospf_hash_find(p->gr, lsa_domain, lsa.id, lsa.rt, lsa_type);
555 | 
556 | #ifdef LOCAL_DEBUG
557 |     if (en)
558 |       DBG("I have Type: %04x, Id: %R, Rt: %R, Sn: 0x%08x, Age: %u, Sum: %u\n",
559 | 	  en->lsa_type, en->lsa.id, en->lsa.rt, en->lsa.sn, en->lsa.age, en->lsa.checksum);
560 | #endif
561 | 
562 |     /* 13. (4) - ignore maxage LSA if i have no local copy */
563 |     if ((lsa.age == LSA_MAXAGE) && !en && (p->padj == 0))
564 |     {
565 |       /* 13.5. - schedule ACKs (tbl 19, case 5) */
566 |       ospf_enqueue_lsack(n, lsa_n, ACKL_DIRECT);
567 |       continue;
568 |     }
569 | 
570 |     /* 13. (5) - received LSA is newer (or no local copy) */
571 |     if (!en || (lsa_comp(&lsa, &en->lsa) == CMP_NEWER))
572 |     {
573 |       /* 13. (5a) - enforce minimum time between updates for received LSAs */
574 |       /* We also use this to ratelimit reactions to received self-originated LSAs */
575 |       if (en && (lsa_inst_age(en) < MINLSARRIVAL))
576 |       {
577 | 	OSPF_TRACE(D_EVENTS, "Skipping LSA received in less that MinLSArrival");
578 | 	continue;
579 |       }
580 | 
581 |       /* Copy and validate LSA body */
582 |       int blen = lsa.length - sizeof(struct ospf_lsa_header);
583 |       void *body = mb_alloc(p->p.pool, blen);
584 |       lsa_ntoh_body(lsa_n + 1, body, blen);
585 | 
586 |       if (lsa_validate(&lsa, lsa_type, ospf_is_v2(p), body) == 0)
587 |       {
588 | 	mb_free(body);
589 | 	SKIP("invalid body");
590 |       }
591 | 
592 |       /* 13. (5f) - handle self-originated LSAs, see also 13.4. */
593 |       if (!p->gr_recovery &&
594 | 	  ((lsa.rt == p->router_id) ||
595 | 	   (ospf_is_v2(p) && (lsa_type == LSA_T_NET) && ospf_addr_is_local(p, ifa->oa, ipa_from_u32(lsa.id)))))
596 |       {
597 | 	OSPF_TRACE(D_EVENTS, "Received unexpected self-originated LSA");
598 | 	ospf_advance_lsa(p, en, &lsa, lsa_type, lsa_domain, body);
599 | 	continue;
600 |       }
601 | 
602 |       /* 13. (5c) - remove old LSA from all retransmission lists
603 |        *
604 |        * We only need to remove it from the retransmission list of the neighbor
605 |        * that send us the new LSA. The old LSA is automatically replaced in
606 |        * retransmission lists by the new LSA.
607 |        */
608 |       if (en)
609 | 	ospf_lsa_lsrt_down(en, n);
610 | 
611 | #if 0
612 |       /*
613 |        * Old code for removing LSA from all retransmission lists. Must be done
614 |        * before (5b), otherwise it also removes the new entries from (5b).
615 |        */
616 |       struct ospf_iface *ifi;
617 |       struct ospf_neighbor *ni;
618 | 
619 |       WALK_LIST(ifi, p->iface_list)
620 | 	WALK_LIST(ni, ifi->neigh_list)
621 | 	  if (ni->state > NEIGHBOR_EXSTART)
622 | 	    ospf_lsa_lsrt_down(en, ni);
623 | #endif
624 | 
625 |       /* 13. (5d) - install new LSA into database */
626 |       en = ospf_install_lsa(p, &lsa, lsa_type, lsa_domain, body);
627 | 
628 |       /* RFC 5340 4.4.3 Events 6+7 - new Link LSA received */
629 |       if (lsa_type == LSA_T_LINK)
630 | 	ospf_notify_net_lsa(ifa);
631 | 
632 |       /* RFC 3623 3.1 - entering graceful restart helper mode */
633 |       if (lsa_type == LSA_T_GR)
634 | 	ospf_neigh_notify_grace_lsa(n, en);
635 | 
636 |       /* Link received pre-restart router LSA */
637 |       if (p->gr_recovery && (lsa_type == LSA_T_RT) && (lsa.rt == p->router_id))
638 | 	ifa->oa->rt = en;
639 | 
640 |       /* 13. (5b) - flood new LSA */
641 |       int flood_back = ospf_flood_lsa(p, en, n);
642 | 
643 |       /* 13.5. - schedule ACKs (tbl 19, cases 1+2) */
644 |       if (! flood_back)
645 | 	if ((ifa->state != OSPF_IS_BACKUP) || (n->rid == ifa->drid))
646 | 	  ospf_enqueue_lsack(n, lsa_n, ACKL_DELAY);
647 | 
648 |       /* FIXME: remove LSA entry if it is LSA_MAXAGE and it is possible? */
649 | 
650 |       continue;
651 |     }
652 | 
653 |     /* 13. (6) - received LSA is in Link state request list (but not newer) */
654 |     if (ospf_hash_find_entry(n->lsrqh, en) != NULL)
655 |       DROP1("error in LSA database exchange");
656 | 
657 |     /* 13. (7) - received LSA is same */
658 |     if (lsa_comp(&lsa, &en->lsa) == CMP_SAME)
659 |     {
660 |       /* Duplicate LSA, treat as implicit ACK */
661 |       int implicit_ack = ospf_lsa_lsrt_down(en, n);
662 | 
663 |       /* 13.5. - schedule ACKs (tbl 19, cases 3+4) */
664 |       if (implicit_ack)
665 |       {
666 | 	if ((ifa->state == OSPF_IS_BACKUP) && (n->rid == ifa->drid))
667 | 	  ospf_enqueue_lsack(n, lsa_n, ACKL_DELAY);
668 |       }
669 |       else
670 | 	ospf_enqueue_lsack(n, lsa_n, ACKL_DIRECT);
671 | 
672 |       continue;
673 |     }
674 | 
675 |     /* 13. (8) - received LSA is older */
676 |     {
677 |       /* Seqnum is wrapping, wait until it is flushed */
678 |       if ((en->lsa.age == LSA_MAXAGE) && (en->lsa.sn == LSA_MAXSEQNO))
679 | 	continue;
680 | 
681 |       /* Send newer local copy back to neighbor */
682 |       /* FIXME - check for MinLSArrival ? */
683 |       ospf_send_lsupd(p, &en, 1, n);
684 | 
685 |       continue;
686 |     }
687 | 
688 |   skip:
689 |     LOG_LSA1("Bad LSA (Type: %04x, Id: %R, Rt: %R) in LSUPD", lsa_type, lsa.id, lsa.rt);
690 |     LOG_LSA2("  received from nbr %R on %s - %s", n->rid, ifa->ifname, err_dsc);
691 |   }
692 | 
693 |   /* Send direct LSACKs */
694 |   ospf_send_lsack(p, n, ACKL_DIRECT);
695 | 
696 |   /* Send enqueued LSAs immediately, do not wait for flood_event */
697 |   if (ev_active(p->flood_event))
698 |   {
699 |     ev_postpone(p->flood_event);
700 |     ospf_flood_event(p);
701 |   }
702 | 
703 |   /*
704 |    * During loading, we should ask for another batch of LSAs. This is only
705 |    * vaguely mentioned in RFC 2328. We send a new LSREQ if all requests sent in
706 |    * the last packet were already answered and/or removed from the LS request
707 |    * list and therefore lsrqi is pointing to the first node of the list.
708 |    */
709 |   if (!EMPTY_SLIST(n->lsrql) && (n->lsrqi == SHEAD(n->lsrql)))
710 |   {
711 |     ospf_send_lsreq(p, n);
712 |     tm_start(n->lsrq_timer, n->ifa->rxmtint S);
713 |   }
714 | 
715 |   return;
716 | 
717 | drop:
718 |   LOG_PKT("Bad LSUPD packet from nbr %R on %s - %s (%u)",
719 | 	  n->rid, ifa->ifname, err_dsc, err_val);
720 | 
721 |   /* Malformed LSUPD - there is no defined error event, we abuse BadLSReq */
722 |   ospf_neigh_sm(n, INM_BADLSREQ);
723 |   return;
724 | }

