437 |   /* ASSERT((n->state >= NEIGHBOR_EXCHANGE) && !EMPTY_SLIST(n->lsrtl)); */
438 | 
439 |   WALK_SLIST_DELSAFE(ret, nxt, n->lsrtl)
440 |   {
