 66 | static inline void
 67 | ospf_lsupd_body(struct ospf_proto *p, struct ospf_packet *pkt,
 68 | 		uint *offset, uint *lsa_count)
 69 | {
 70 |   uint hlen = ospf_lsupd_hdrlen(p);
 71 |   *offset = hlen;
 72 |   *lsa_count = ospf_lsupd_get_lsa_count(pkt, hlen);
