 26 | void
 27 | ospf_dump_lsahdr(struct ospf_proto *p, struct ospf_lsa_header *lsa_n)
 28 | {
 29 |   struct ospf_lsa_header lsa;
 30 |   u32 lsa_etype;
 31 | 
 32 |   lsa_ntoh_hdr(lsa_n, &lsa);
 33 |   lsa_etype = lsa_get_etype(&lsa, p);
