 39 | void
 40 | ospf_dump_common(struct ospf_proto *p, struct ospf_packet *pkt)
 41 | {
 42 |   log(L_TRACE "%s:     length   %d", p->p.name, ntohs(pkt->length));
 43 |   log(L_TRACE "%s:     router   %R", p->p.name, ntohl(pkt->routerid));
 44 | }
