 52 | static inline u32
 53 | ospf_lsupd_get_lsa_count(struct ospf_packet *pkt, uint hdrlen)
 54 | {
 55 |   u32 *c = ((void *) pkt) + hdrlen - 4;
 56 |   return ntohl(*c);
 57 | }
