 59 | static inline void
 60 | ospf_lsupd_set_lsa_count(struct ospf_packet *pkt, uint hdrlen, u32 val)
 61 | {
 62 |   u32 *c = ((void *) pkt) + hdrlen - 4;
 63 |   *c = htonl(val);
 64 | }
