156 | static inline int
157 | ospf_lsa_lsrt_down(struct top_hash_entry *en, struct ospf_neighbor *n)
158 | {
159 |   struct top_hash_entry *ret = ospf_hash_find_entry(n->lsrth, en);
160 | 
161 |   if (ret)
162 |     ospf_lsa_lsrt_down_(en, n, ret);
163 | 
164 |   return ret != NULL;
165 | }
