465 | static inline int
466 | ospf_addr_is_local(struct ospf_proto *p, struct ospf_area *oa, ip_addr ip)
467 | {
468 |   struct ospf_iface *ifa;
469 |   WALK_LIST(ifa, p->iface_list)
470 |     if ((ifa->oa == oa) && ifa->addr && ipa_equal(ifa->addr->ip, ip))
471 |       return 1;
472 | 
473 |   return 0;
474 | }
