 35 | static void
 36 | init_lists(struct ospf_proto *p, struct ospf_neighbor *n)
 37 | {
 38 |   s_init_list(&(n->lsrql));
 39 |   n->lsrqi = SHEAD(n->lsrql);
 40 |   n->lsrqh = ospf_top_new(p, n->pool);
 41 | 
 42 |   s_init_list(&(n->lsrtl));
 43 |   n->lsrth = ospf_top_new(p, n->pool);
 44 | }
