 46 | static void
 47 | release_lsrtl(struct ospf_proto *p, struct ospf_neighbor *n)
 48 | {
 49 |   struct top_hash_entry *ret, *en;
 50 | 
 51 |   WALK_SLIST(ret, n->lsrtl)
 52 |   {
 53 |     en = ospf_hash_find_entry(p->gr, ret);
 54 |     if (en)
 55 |       en->ret_count--;
 56 |   }
 57 | }
