548 | static inline u32 neigh_get_id(struct ospf_proto *p, struct ospf_neighbor *n)
549 | { return ospf_is_v2(p) ? ipa_to_u32(n->ip) : n->rid; }
550 | 
551 | static struct ospf_neighbor *
552 | elect_bdr(struct ospf_proto *p, list nl)
553 | {
554 |   struct ospf_neighbor *neigh, *n1, *n2;
555 |   u32 nid;
556 | 
557 |   n1 = NULL;
558 |   n2 = NULL;
559 |   WALK_LIST(neigh, nl)			/* First try those decl. themselves */
560 |   {
561 |     nid = neigh_get_id(p, neigh);
562 | 
563 |     if (neigh->state >= NEIGHBOR_2WAY)	/* Higher than 2WAY */
564 |       if (neigh->priority > 0)		/* Eligible */
565 | 	if (neigh->dr != nid)		/* And not decl. itself DR */
566 | 	{
567 | 	  if (neigh->bdr == nid)	/* Declaring BDR */
568 | 	  {
569 | 	    if (n1 != NULL)
570 | 	    {
571 | 	      if (neigh->priority > n1->priority)
572 | 		n1 = neigh;
573 | 	      else if (neigh->priority == n1->priority)
574 | 		if (neigh->rid > n1->rid)
575 | 		  n1 = neigh;
576 | 	    }
577 | 	    else
578 | 	    {
579 | 	      n1 = neigh;
580 | 	    }
581 | 	  }
582 | 	  else			/* And NOT declaring BDR */
583 | 	  {
584 | 	    if (n2 != NULL)
585 | 	    {
586 | 	      if (neigh->priority > n2->priority)
587 | 		n2 = neigh;
588 | 	      else if (neigh->priority == n2->priority)
589 | 		if (neigh->rid > n2->rid)
590 | 		  n2 = neigh;
591 | 	    }
592 | 	    else
593 | 	    {
594 | 	      n2 = neigh;
595 | 	    }
596 | 	  }
597 | 	}
598 |   }
599 |   if (n1 == NULL)
600 |     n1 = n2;
601 | 
602 |   return (n1);
603 | }
604 | 
605 | static struct ospf_neighbor *
606 | elect_dr(struct ospf_proto *p, list nl)
607 | {
608 |   struct ospf_neighbor *neigh, *n;
609 |   u32 nid;
610 | 
611 |   n = NULL;
612 |   WALK_LIST(neigh, nl)			/* And now DR */
613 |   {
614 |     nid = neigh_get_id(p, neigh);
615 | 
616 |     if (neigh->state >= NEIGHBOR_2WAY)	/* Higher than 2WAY */
617 |       if (neigh->priority > 0)		/* Eligible */
618 | 	if (neigh->dr == nid)		/* And declaring itself DR */
619 | 	{
620 | 	  if (n != NULL)
621 | 	  {
622 | 	    if (neigh->priority > n->priority)
623 | 	      n = neigh;
624 | 	    else if (neigh->priority == n->priority)
625 | 	      if (neigh->rid > n->rid)
626 | 		n = neigh;
627 | 	  }
628 | 	  else
629 | 	  {
630 | 	    n = neigh;
631 | 	  }
632 | 	}
633 |   }
634 | 
635 |   return (n);
636 | }
637 | 
638 | /**
639 |  * ospf_dr_election - (Backup) Designed Router election
640 |  * @ifa: actual interface
641 |  *
642 |  * When the wait timer fires, it is time to elect (Backup) Designated Router.
643 |  * Structure describing me is added to this list so every electing router has
644 |  * the same list. Backup Designated Router is elected before Designated
645 |  * Router. This process is described in 9.4 of RFC 2328. The function is
646 |  * supposed to be called only from ospf_iface_sm() as a part of the interface
647 |  * state machine.
648 |  */
649 | void
650 | ospf_dr_election(struct ospf_iface *ifa)
651 | {
652 |   struct ospf_proto *p = ifa->oa->po;
653 |   struct ospf_neighbor *neigh, *ndr, *nbdr;
654 |   u32 myid = p->router_id;
655 | 
656 |   DBG("(B)DR election.\n");
657 | 
658 |   struct ospf_neighbor me = {
659 |     .state = NEIGHBOR_2WAY,
660 |     .rid = myid,
661 |     .priority = ifa->priority,
662 |     .ip = ifa->addr->ip,
663 |     .dr  = ospf_is_v2(p) ? ipa_to_u32(ifa->drip) : ifa->drid,
664 |     .bdr = ospf_is_v2(p) ? ipa_to_u32(ifa->bdrip) : ifa->bdrid,
665 |     .iface_id = ifa->iface_id,
666 |   };
667 | 
668 |   add_tail(&ifa->neigh_list, NODE & me);
669 | 
670 |   nbdr = elect_bdr(p, ifa->neigh_list);
671 |   ndr = elect_dr(p, ifa->neigh_list);
672 | 
673 |   if (ndr == NULL)
674 |     ndr = nbdr;
675 | 
676 |   /* 9.4. (4) */
677 |   if (((ifa->drid == myid) && (ndr != &me))
678 |       || ((ifa->drid != myid) && (ndr == &me))
679 |       || ((ifa->bdrid == myid) && (nbdr != &me))
680 |       || ((ifa->bdrid != myid) && (nbdr == &me)))
681 |   {
682 |     me.dr = ndr ? neigh_get_id(p, ndr) : 0;
683 |     me.bdr = nbdr ? neigh_get_id(p, nbdr) : 0;
684 | 
685 |     nbdr = elect_bdr(p, ifa->neigh_list);
686 |     ndr = elect_dr(p, ifa->neigh_list);
687 | 
688 |     if (ndr == NULL)
689 |       ndr = nbdr;
690 |   }
691 | 
692 |   rem_node(NODE & me);
693 | 
694 | 
695 |   u32 old_drid = ifa->drid;
696 |   u32 old_bdrid = ifa->bdrid;
697 |   ip_addr none = ospf_is_v2(p) ? IPA_NONE4 : IPA_NONE6;
698 | 
699 |   ifa->drid = ndr ? ndr->rid : 0;
700 |   ifa->drip = ndr ? ndr->ip  : none;
701 |   ifa->dr_iface_id = ndr ? ndr->iface_id : 0;
702 | 
703 |   ifa->bdrid = nbdr ? nbdr->rid : 0;
704 |   ifa->bdrip = nbdr ? nbdr->ip  : none;
705 | 
706 |   DBG("DR=%R, BDR=%R\n", ifa->drid, ifa->bdrid);
707 | 
708 |   /* We are part of the interface state machine */
709 |   if (ifa->drid == myid)
710 |     ospf_iface_chstate(ifa, OSPF_IS_DR);
711 |   else if (ifa->bdrid == myid)
712 |     ospf_iface_chstate(ifa, OSPF_IS_BACKUP);
713 |   else
714 |     ospf_iface_chstate(ifa, OSPF_IS_DROTHER);
715 | 
716 |   /* Review neighbor adjacencies if DR or BDR changed */
717 |   if ((ifa->drid != old_drid) || (ifa->bdrid != old_bdrid))
718 |     WALK_LIST(neigh, ifa->neigh_list)
719 |       if (neigh->state >= NEIGHBOR_2WAY)
720 | 	ospf_neigh_sm(neigh, INM_ADJOK);
721 | 
722 |   /* RFC 2328 12.4 Event 3 - DR change */
723 |   if (ifa->drid != old_drid)
724 |     ospf_notify_rt_lsa(ifa->oa);
725 | }
