728 | find_neigh(struct ospf_iface *ifa, u32 rid)
729 | {
730 |   struct ospf_neighbor *n;
731 |   WALK_LIST(n, ifa->neigh_list)
732 |     if (n->rid == rid)
733 |       return n;
734 |   return NULL;
