 243 | void
 244 | ospf_stop_gr_recovery(struct ospf_proto *p)
 245 | {
 246 |   p->gr_recovery = 0;
 247 |   p->gr_cleanup = 1;
 248 |   p->gr_timeout = 0;
 249 | 
 250 |   /* Reorigination of router/network LSAs is already scheduled */
 251 | 
 252 |   /* Rest is done in ospf_cleanup_gr_recovery() */
 253 | }
