 443 | /**
 444 |  * ospf_disp - invokes routing table calculation, aging and also area_disp()
 445 |  * @timer: timer usually called every @ospf_proto->tick second, @timer->data
 446 |  * point to @ospf_proto
 447 |  */
 448 | static void
 449 | ospf_disp(timer * timer)
 450 | {
 451 |   struct ospf_proto *p = timer->data;
 452 | 
 453 |   /* Check for end of graceful restart */
 454 |   if (p->gr_recovery)
 455 |     ospf_update_gr_recovery(p);
 456 | 
 457 |   /* Originate or flush local topology LSAs */
 458 |   ospf_update_topology(p);
 459 | 
 460 |   /* Process LSA DB */
 461 |   ospf_update_lsadb(p);
 462 | 
 463 |   /* Calculate routing table */
 464 |   if (p->calcrt)
 465 |     ospf_rt_spf(p);
 466 | 
 467 |   /* Cleanup after graceful restart */
 468 |   if (p->gr_cleanup)
 469 |     ospf_cleanup_gr_recovery(p);
 470 | }
