 473 | /**
 474 |  * ospf_preexport - accept or reject new route from nest's routing table
 475 |  * @P: OSPF protocol instance
 476 |  * @new: the new route
 477 |  * @attrs: list of attributes
 478 |  * @pool: pool for allocation of attributes
 479 |  *
 480 |  * Its quite simple. It does not accept our own routes and leaves the decision on
 481 |  * import to the filters.
 482 |  */
 483 | static int
 484 | ospf_preexport(struct channel *C, rte *e)
 485 | {
 486 |   struct ospf_proto *p = (struct ospf_proto *) C->proto;
 487 |   struct ospf_area *oa = ospf_main_area(p);
 488 | 
 489 |   /* Reject our own routes */
 490 |   if (e->src->proto == &p->p)
 491 |     return -1;
 492 | 
 493 |   /* Do not export routes to stub areas */
 494 |   if (oa_is_stub(oa))
 495 |     return -1;
 496 | 
 497 |   return 0;
 498 | }
