 567 | static void
 568 | ospf_get_route_info(rte * rte, byte * buf)
 569 | {
 570 |   char *type = "<bug>";
 571 | 
 572 |   switch (rte->attrs->source)
 573 |   {
 574 |   case RTS_OSPF:
 575 |     type = "I";
 576 |     break;
 577 |   case RTS_OSPF_IA:
 578 |     type = "IA";
 579 |     break;
 580 |   case RTS_OSPF_EXT1:
 581 |     type = "E1";
 582 |     break;
 583 |   case RTS_OSPF_EXT2:
 584 |     type = "E2";
 585 |     break;
 586 |   }
 587 | 
 588 |   buf += bsprintf(buf, " %s", type);
 589 |   buf += bsprintf(buf, " (%d/%d", rte->attrs->pref, ea_get_int(rte->attrs->eattrs, EA_OSPF_METRIC1, LSINFINITY));
 590 |   if (rte->attrs->source == RTS_OSPF_EXT2)
 591 |     buf += bsprintf(buf, "/%d", ea_get_int(rte->attrs->eattrs, EA_OSPF_METRIC2, LSINFINITY));
 592 |   buf += bsprintf(buf, ")");
 593 |   if (rte->attrs->source == RTS_OSPF_EXT1 || rte->attrs->source == RTS_OSPF_EXT2)
 594 |   {
 595 |     eattr *ea = ea_find(rte->attrs->eattrs, EA_OSPF_TAG);
 596 |     if (ea && (ea->u.data > 0))
 597 |       buf += bsprintf(buf, " [%x]", ea->u.data);
 598 |   }
 599 |   
