 628 | ospf_area_reconfigure(struct ospf_area *oa, struct ospf_area_config *nac)
 629 | {
 630 |   struct ospf_proto *p = oa->po;
 631 |   struct ospf_area_config *oac = oa->ac;
 632 |   struct ospf_iface *ifa, *ifx;
 633 | 
 634 |   oa->ac = nac;
 635 |   oa->options = nac->type | ospf_opts(p);
 636 | 
 637 |   if (nac->type != oac->type)
 638 |   {
 639 |     log(L_INFO "%s: Restarting area %R", p->p.name, oa->areaid);
 640 | 
 641 |     /* Remove area interfaces, will be re-added later */
 642 |     WALK_LIST_DELSAFE(ifa, ifx, p->iface_list)
 643 |       if (ifa->oa == oa)
 644 |       {
 645 | 	ospf_iface_shutdown(ifa);
 646 | 	ospf_iface_remove(ifa);
 647 |       }
 648 | 
 649 |     /* Flush area LSAs */
 650 |     ospf_flush_area(p, oa->areaid);
 651 |   }
 652 | 
 653 |   /* Handle net_list */
 654 |   fib_free(&oa->net_fib);
 655 |   fib_free(&oa->enet_fib);
 656 |   add_area_nets(oa, nac);
 657 | 
 658 |   /* No need to handle stubnet_list */
 659 | 
 660 |   oa->marked = 0;
 661 |   ospf_notify_rt_lsa(oa);
 662 | }
