 899 | /* lsa_compare_for_state() - Compare function for 'show ospf state'
 900 |  *
 901 |  * First we want to separate network-LSAs and other LSAs (because network-LSAs
 902 |  * will be presented as network nodes and other LSAs together as router nodes)
 903 |  * Network-LSAs are sorted according to network prefix, other LSAs are sorted
 904 |  * according to originating router id (to get all LSA needed to represent one
 905 |  * router node together). Then, according to LSA type, ID and age.
 906 |  *
 907 |  * For OSPFv3, we have to handle also Prefix-LSAs. We would like to put each
 908 |  * immediately after the referenced LSA. We will make faked LSA based on ref_
 909 |  * values
 910 |  */
 911 | 
 912 | static struct ospf_lsa_header *
 913 | fake_lsa_from_prefix_lsa(struct ospf_lsa_header *dst, struct ospf_lsa_header *src,
 914 | 			 struct ospf_lsa_prefix *px)
 915 | {
 916 |   dst->age = src->age;
 917 |   dst->type_raw = px->ref_type;
 918 |   dst->id = px->ref_id;
 919 |   dst->rt = px->ref_rt;
 920 |   dst->sn = src->sn;
 921 | 
 922 |   return dst;
 923 | }
 924 | 
 925 | 
 926 | static int lsa_compare_ospf3;
 927 | 
 928 | static int
 929 | lsa_compare_for_state(const void *p1, const void *p2)
 930 | {
 931 |   struct top_hash_entry *he1 = * (struct top_hash_entry **) p1;
 932 |   struct top_hash_entry *he2 = * (struct top_hash_entry **) p2;
 933 |   struct ospf_lsa_header *lsa1 = &(he1->lsa);
 934 |   struct ospf_lsa_header *lsa2 = &(he2->lsa);
 935 |   struct ospf_lsa_header lsatmp1, lsatmp2;
 936 |   u16 lsa1_type = he1->lsa_type;
 937 |   u16 lsa2_type = he2->lsa_type;
 938 | 
 939 |   if (he1->domain < he2->domain)
 940 |     return -1;
 941 |   if (he1->domain > he2->domain)
 942 |     return 1;
 943 | 
 944 | 
 945 |   /* px1 or px2 assumes OSPFv3 */
 946 |   int px1 = (lsa1_type == LSA_T_PREFIX);
 947 |   int px2 = (lsa2_type == LSA_T_PREFIX);
 948 | 
 949 |   if (px1)
 950 |   {
 951 |     lsa1 = fake_lsa_from_prefix_lsa(&lsatmp1, lsa1, he1->lsa_body);
 952 |     lsa1_type = lsa1->type_raw;	/* FIXME: handle unknown ref_type */
 953 |   }
 954 | 
 955 |   if (px2)
 956 |   {
 957 |     lsa2 = fake_lsa_from_prefix_lsa(&lsatmp2, lsa2, he2->lsa_body);
 958 |     lsa2_type = lsa2->type_raw;
 959 |   }
 960 | 
 961 | 
 962 |   int nt1 = (lsa1_type == LSA_T_NET);
 963 |   int nt2 = (lsa2_type == LSA_T_NET);
 964 | 
 965 |   if (nt1 != nt2)
 966 |     return nt1 - nt2;
 967 | 
 968 |   if (nt1)
 969 |   {
 970 |     /* In OSPFv3, networks are named based on ID of DR */
 971 |     if (lsa_compare_ospf3)
 972 |     {
 973 |       if (lsa1->rt < lsa2->rt)
 974 | 	return -1;
 975 |       if (lsa1->rt > lsa2->rt)
 976 | 	return 1;
 977 |     }
 978 | 
 979 |     /* For OSPFv2, this is IP of the network,
 980 |        for OSPFv3, this is interface ID */
 981 |     if (lsa1->id < lsa2->id)
 982 |       return -1;
 983 |     if (lsa1->id > lsa2->id)
 984 |       return 1;
 985 | 
 986 |     if (px1 != px2)
 987 |       return px1 - px2;
 988 | 
 989 |     return lsa1->sn - lsa2->sn;
 990 |   }
 991 |   else
 992 |   {
 993 |     if (lsa1->rt < lsa2->rt)
 994 |       return -1;
 995 |     if (lsa1->rt > lsa2->rt)
 996 |       return 1;
 997 | 
 998 |     if (lsa1_type < lsa2_type)
 999 |       return -1;
1000 |     if (lsa1_type > lsa2_type)
1001 |       return 1;
1002 | 
1003 |     if (lsa1->id < lsa2->id)
1004 |       return -1;
1005 |     if (lsa1->id > lsa2->id)
1006 |       return 1;
1007 | 
1008 |     if (px1 != px2)
1009 |       return px1 - px2;
1010 | 
1011 |     return lsa1->sn - lsa2->sn;
1012 |   }
1013 | }
1014 | 
1015 | static int
1016 | ext_compare_for_state(const void *p1, const void *p2)
1017 | {
1018 |   struct top_hash_entry * he1 = * (struct top_hash_entry **) p1;
1019 |   struct top_hash_entry * he2 = * (struct top_hash_entry **) p2;
1020 |   struct ospf_lsa_header *lsa1 = &(he1->lsa);
1021 |   struct ospf_lsa_header *lsa2 = &(he2->lsa);
1022 | 
1023 |   if (lsa1->rt < lsa2->rt)
1024 |     return -1;
1025 |   if (lsa1->rt > lsa2->rt)
1026 |     return 1;
1027 | 
1028 |   if (lsa1->id < lsa2->id)
1029 |     return -1;
1030 |   if (lsa1->id > lsa2->id)
1031 |     return 1;
1032 | 
1033 |   return lsa1->sn - lsa2->sn;
1034 | }
