 143 | static inline uint
 144 | ospf_opts(struct ospf_proto *p)
 145 | {
 146 |   if (ospf_is_v2(p))
 147 |     return OPT_O;
 148 | 
 149 |   return ((ospf_is_ip6(p) && !p->af_mc) ? OPT_V6 : 0) |
 150 |     (!p->stub_router ? OPT_R : 0) | (p->af_ext ? OPT_AF : 0);
