 179 | static void
 180 | ospf_flush_area(struct ospf_proto *p, u32 areaid)
 181 | {
 182 |   struct top_hash_entry *en;
 183 | 
 184 |   WALK_SLIST(en, p->lsal)
 185 |     if ((LSA_SCOPE(en->lsa_type) == LSA_SCOPE_AREA) && (en->domain == areaid))
 186 |       ospf_flush_lsa(p, en);
 187 | }
