 384 | /* If new is better return 1 */
 385 | static int
 386 | ospf_rte_better(struct rte *new, struct rte *old)
 387 | {
 388 |   u32 new_metric1 = ea_get_int(new->attrs->eattrs, EA_OSPF_METRIC1, LSINFINITY);
 389 | 
 390 |   if (new_metric1 == LSINFINITY)
 391 |     return 0;
 392 | 
 393 |   if(new->attrs->source < old->attrs->source) return 1;
 394 |   if(new->attrs->source > old->attrs->source) return 0;
 395 | 
 396 |   if(new->attrs->source == RTS_OSPF_EXT2)
 397 |   {
 398 |     u32 old_metric2 = ea_get_int(old->attrs->eattrs, EA_OSPF_METRIC2, LSINFINITY);
 399 |     u32 new_metric2 = ea_get_int(new->attrs->eattrs, EA_OSPF_METRIC2, LSINFINITY);
 400 |     if(new_metric2 < old_metric2) return 1;
 401 |     if(new_metric2 > old_metric2) return 0;
 402 |   }
 403 | 
 404 |   u32 old_metric1 = ea_get_int(old->attrs->eattrs, EA_OSPF_METRIC1, LSINFINITY);
 405 |   if (new_metric1 < old_metric1)
 406 |     return 1;
 407 | 
 408 |   return 0;			/* Old is shorter or same */
 409 | }
