 478 |  * @pool: pool for allocation of attributes
 479 |  *
 480 |  * Its quite simple. It does not accept our own routes and leaves the decision on
 481 |  * import to the filters.
 482 |  */
 483 | static int
 484 | ospf_preexport(struct channel *C, rte *e)
 485 | {
