 500 | /**
 501 |  * ospf_shutdown - Finish of OSPF instance
 502 |  * @P: OSPF protocol instance
 503 |  *
 504 |  * RFC does not define any action that should be taken before router
 505 |  * shutdown. To make my neighbors react as fast as possible, I send
 506 |  * them hello packet with empty neighbor list. They should start
 507 |  * their neighbor state machine with event %NEIGHBOR_1WAY.
 508 |  */
 509 | static int
 510 | ospf_shutdown(struct proto *P)
 511 | {
 512 |   struct ospf_proto *p = (struct ospf_proto *) P;
 513 |   struct ospf_iface *ifa;
 514 | 
 515 |   OSPF_TRACE(D_EVENTS, "Shutdown requested");
 516 | 
 517 |   if ((P->down_code == PDC_CMD_GR_DOWN) && (p->gr_mode == OSPF_GR_ABLE))
 518 |   {
 519 |     /* Originate Grace LSAs */
 520 |     WALK_LIST(ifa, p->iface_list)
 521 |       ospf_originate_gr_lsa(p, ifa);
 522 |   }
 523 |   else
 524 |   {
 525 |     /* Send to all my neighbors 1WAY */
 526 |     WALK_LIST(ifa, p->iface_list)
 527 |       ospf_iface_shutdown(ifa);
 528 |   }
 529 | 
 530 |   /* Cleanup locked rta entries */
 531 |   FIB_WALK(&p->rtf, ort, nf)
 532 |   {
 533 |     rta_free(nf->old_rta);
 534 |   }
 535 |   FIB_WALK_END;
 536 | 
 537 |   if (tm_active(p->disp_timer))
 538 |     tm_stop(p->disp_timer);
 539 | 
 540 |   return PS_DOWN;
 541 | }
