 664 | /**
 665 |  * ospf_reconfigure - reconfiguration hook
 666 |  * @P: current instance of protocol (with old configuration)
 667 |  * @c: new configuration requested by user
 668 |  *
 669 |  * This hook tries to be a little bit intelligent. Instance of OSPF
 670 |  * will survive change of many constants like hello interval,
 671 |  * password change, addition or deletion of some neighbor on
 672 |  * nonbroadcast network, cost of interface, etc.
 673 |  */
 674 | static int
 675 | ospf_reconfigure(struct proto *P, struct proto_config *CF)
 676 | {
 677 |   struct ospf_proto *p = (struct ospf_proto *) P;
 678 |   struct ospf_config *old = (struct ospf_config *) (P->cf);
 679 |   struct ospf_config *new = (struct ospf_config *) CF;
 680 |   struct ospf_area_config *oac, *nac;
 681 |   struct ospf_area *oa, *oax;
 682 |   struct ospf_iface *ifa, *ifx;
 683 |   struct ospf_iface_patt *ip;
 684 | 
 685 |   if (proto_get_router_id(CF) != p->router_id)
 686 |     return 0;
 687 | 
 688 |   if (p->ospf2 != new->ospf2)
 689 |     return 0;
 690 | 
 691 |   if (p->rfc1583 != new->rfc1583)
 692 |     return 0;
 693 | 
 694 |   if (p->instance_id != new->instance_id)
 695 |     return 0;
 696 | 
 697 |   if (old->abr != new->abr)
 698 |     return 0;
 699 | 
 700 |   if (p->areano == 1)
 701 |   {
 702 |     oac = HEAD(old->area_list);
 703 |     nac = HEAD(new->area_list);
 704 | 
 705 |     if (oac->type != nac->type)
 706 |       return 0;
 707 |   }
 708 | 
 709 |   if (old->vpn_pe != new->vpn_pe)
 710 |     return 0;
 711 | 
 712 |   if ((p->af_ext != new->af_ext) || (p->af_mc != new->af_mc))
 713 |     return 0;
 714 | 
 715 |   if (!proto_configure_channel(P, &P->main_channel, proto_cf_main_channel(CF)))
 716 |     return 0;
 717 | 
 718 |   p->stub_router = new->stub_router;
 719 |   p->merge_external = new->merge_external;
 720 |   p->asbr = new->asbr;
 721 |   p->ecmp = new->ecmp;
 722 |   p->gr_mode = new->gr_mode;
 723 |   p->gr_time = new->gr_time;
 724 |   p->tick = new->tick;
 725 |   p->disp_timer->recurrent = p->tick S;
 726 |   tm_start(p->disp_timer, 10 MS);
 727 | 
 728 |   /* Mark all areas and ifaces */
 729 |   WALK_LIST(oa, p->area_list)
 730 |     oa->marked = 1;
 731 | 
 732 |   WALK_LIST(ifa, p->iface_list)
 733 |     ifa->marked = 1;
 734 | 
 735 |   /* Add and update areas */
 736 |   WALK_LIST(nac, new->area_list)
 737 |   {
 738 |     oa = ospf_find_area(p, nac->areaid);
 739 |     if (oa)
 740 |       ospf_area_reconfigure(oa, nac);
 741 |     else
 742 |       ospf_area_add(p, nac);
 743 |   }
 744 | 
 745 |   /* Add and update interfaces */
 746 |   ospf_reconfigure_ifaces(p);
 747 | 
 748 |   /* Add and update vlinks */
 749 |   WALK_LIST(ip, new->vlink_list)
 750 |   {
 751 |     ifa = ospf_find_vlink(p, ip->voa, ip->vid);
 752 |     if (ifa)
 753 |       ospf_iface_reconfigure(ifa, ip);
 754 |     else
 755 |       ospf_iface_new_vlink(p, ip);
 756 |   }
 757 | 
 758 |   /* Delete remaining ifaces and areas */
 759 |   WALK_LIST_DELSAFE(ifa, ifx, p->iface_list)
 760 |     if (ifa->marked)
 761 |     {
 762 |       ospf_iface_shutdown(ifa);
 763 |       ospf_iface_remove(ifa);
 764 |     }
 765 | 
 766 |   WALK_LIST_DELSAFE(oa, oax, p->area_list)
 767 |     if (oa->marked)
 768 |       ospf_area_remove(oa);
 769 | 
 770 |   ospf_schedule_rtcalc(p);
 771 | 
 772 |   return 1;
 773 | }
