1049 | 
1050 |   cli_msg(-1016, "");
1051 |   cli_msg(-1016, "\trouter %R", he->lsa.rt);
1052 |   show_lsa_distance(he);
1053 | 
1054 |   lsa_walk_rt_init(p, he, &rtl);
1055 |   while (lsa_walk_rt(&rtl))
1056 |     if (rtl.type == LSART_VLNK)
1057 |       cli_msg(-1016, "\t\tvlink %R metric %u", rtl.id, rtl.metric);
1058 | 
1059 |   lsa_walk_rt_init(p, he, &rtl);
1060 |   while (lsa_walk_rt(&rtl))
1061 |     if (rtl.type == LSART_PTP)
