1063 | 
1064 |   lsa_walk_rt_init(p, he, &rtl);
1065 |   while (lsa_walk_rt(&rtl))
1066 |     if (rtl.type == LSART_NET)
1067 |     {
1068 |       if (ospf_is_v2(p))
