1082 | 	else
1083 | 	  cli_msg(-1016, "\t\tnetwork [%R] metric %u", rtl.id, rtl.metric);
1084 |       }
1085 |       else
1086 | 	cli_msg(-1016, "\t\tnetwork [%R-%u] metric %u", rtl.id, rtl.nif, rtl.metric);
