1202 | 
1203 | void
1204 | ospf_sh_state(struct proto *P, int verbose, int reachable)
1205 | {
1206 |   struct ospf_proto *p = (struct ospf_proto *) P;
1207 |   int ospf2 = ospf_is_v2(p);
1208 |   int af = ospf_get_af(p);
1209 |   uint i, ix, j1, jx;
1210 |   u32 last_area = 0xFFFFFFFF;
1211 | 
1212 |   if (p->p.proto_state != PS_UP)
1213 |   {
1214 |     cli_msg(-1016, "%s: is not up", p->p.name);
1215 |     cli_msg(0, "");
1216 |     return;
1217 |   }
1218 | 
1219 |   /* We store interesting area-scoped LSAs in array hea and
1220 |      global-scoped (LSA_T_EXT) LSAs in array hex */
1221 | 
1222 |   uint num = p->gr->hash_entries;
1223 |   struct top_hash_entry *hea[num];
1224 |   struct top_hash_entry **hex = verbose ? alloca(num * sizeof(struct top_hash_entry *)) : NULL;
1225 |   struct top_hash_entry *he;
1226 |   struct top_hash_entry *cnode = NULL;
1227 | 
1228 |   j1 = jx = 0;
1229 |   WALK_SLIST(he, p->lsal)
1230 |   {
1231 |     int accept;
1232 | 
1233 |     if (he->lsa.age == LSA_MAXAGE)
1234 |       continue;
1235 | 
1236 |     switch (he->lsa_type)
1237 |     {
1238 |     case LSA_T_RT:
1239 |     case LSA_T_NET:
1240 |       accept = 1;
1241 |       break;
1242 | 
1243 |     case LSA_T_SUM_NET:
1244 |     case LSA_T_SUM_RT:
1245 |     case LSA_T_NSSA:
1246 |     case LSA_T_PREFIX:
1247 |       accept = verbose;
1248 |       break;
1249 | 
1250 |     case LSA_T_EXT:
1251 |       if (verbose)
1252 |       {
1253 | 	he->domain = 1; /* Abuse domain field to mark the LSA */
1254 | 	hex[jx++] = he;
1255 |       }
1256 |       /* fallthrough */
1257 |     default:
1258 |       accept = 0;
1259 |     }
1260 | 
1261 |     if (accept)
1262 |       hea[j1++] = he;
1263 |   }
1264 | 
1265 |   ASSERT(j1 <= num && jx <= num);
1266 | 
1267 |   lsa_compare_ospf3 = !ospf2;
1268 |   qsort(hea, j1, sizeof(struct top_hash_entry *), lsa_compare_for_state);
1269 | 
1270 |   if (verbose)
1271 |     qsort(hex, jx, sizeof(struct top_hash_entry *), ext_compare_for_state);
1272 | 
1273 |   /*
1274 |    * This code is a bit tricky, we have a primary LSAs (router and
1275 |    * network) that are presented as a node, and secondary LSAs that
1276 |    * are presented as a part of a primary node. cnode represents an
1277 |    * currently opened node (whose header was presented). The LSAs are
1278 |    * sorted to get secondary LSAs just after related primary LSA (if
1279 |    * available). We present secondary LSAs only when related primary
1280 |    * LSA is opened.
1281 |    *
1282 |    * AS-external LSAs are stored separately as they might be presented
1283 |    * several times (for each area when related ASBR is opened). When
1284 |    * the node is closed, related external routes are presented. We
1285 |    * also have to take into account that in OSPFv3, there might be
1286 |    * more router-LSAs and only the first should be considered as a
1287 |    * primary. This is handled by not closing old router-LSA when next
1288 |    * one is processed (which is not opened because there is already
1289 |    * one opened).
1290 |    */
1291 | 
1292 |   ix = 0;
1293 |   for (i = 0; i < j1; i++)
1294 |   {
1295 |     he = hea[i];
1296 | 
1297 |     /* If there is no opened node, we open the LSA (if appropriate) or skip to the next one */
1298 |     if (!cnode)
1299 |     {
1300 |       if (((he->lsa_type == LSA_T_RT) || (he->lsa_type == LSA_T_NET))
1301 | 	  && ((he->color == INSPF) || !reachable))
1302 |       {
1303 | 	cnode = he;
1304 | 
1305 | 	if (he->domain != last_area)
1306 | 	{
1307 | 	  cli_msg(-1016, "");
1308 | 	  cli_msg(-1016, "area %R", he->domain);
1309 | 	  last_area = he->domain;
1310 | 	  ix = 0;
1311 | 	}
1312 |       }
1313 |       else
1314 | 	continue;
1315 |     }
1316 | 
1317 |     ASSERT(cnode && (he->domain == last_area) && (he->lsa.rt == cnode->lsa.rt));
1318 | 
1319 |     switch (he->lsa_type)
1320 |     {
1321 |     case LSA_T_RT:
1322 |       if (he->lsa.id == cnode->lsa.id)
1323 | 	show_lsa_router(p, he, verbose);
1324 |       break;
1325 | 
1326 |     case LSA_T_NET:
1327 |       show_lsa_network(he, ospf2);
1328 |       break;
1329 | 
1330 |     case LSA_T_SUM_NET:
1331 |       if (cnode->lsa_type == LSA_T_RT)
1332 | 	show_lsa_sum_net(he, ospf2, af);
1333 |       break;
1334 | 
1335 |     case LSA_T_SUM_RT:
1336 |       if (cnode->lsa_type == LSA_T_RT)
1337 | 	show_lsa_sum_rt(he, ospf2);
1338 |       break;
1339 | 
1340 |     case LSA_T_EXT:
1341 |     case LSA_T_NSSA:
1342 |       show_lsa_external(he, ospf2, af);
1343 |       break;
1344 | 
1345 |     case LSA_T_PREFIX:
1346 |       show_lsa_prefix(he, cnode, af);
1347 |       break;
1348 |     }
1349 | 
1350 |     /* In these cases, we close the current node */
1351 |     if ((i+1 == j1)
1352 | 	|| (hea[i+1]->domain != last_area)
1353 | 	|| (hea[i+1]->lsa.rt != cnode->lsa.rt)
1354 | 	|| (hea[i+1]->lsa_type == LSA_T_NET))
1355 |     {
1356 |       while ((ix < jx) && (hex[ix]->lsa.rt < cnode->lsa.rt))
1357 | 	ix++;
1358 | 
1359 |       while ((ix < jx) && (hex[ix]->lsa.rt == cnode->lsa.rt))
1360 | 	show_lsa_external(hex[ix++], ospf2, af);
1361 | 
1362 |       cnode = NULL;
1363 |     }
1364 |   }
1365 | 
1366 |   int hdr = 0;
1367 |   u32 last_rt = 0xFFFFFFFF;
1368 |   for (ix = 0; ix < jx; ix++)
1369 |   {
1370 |     he = hex[ix];
1371 | 
1372 |     /* If it is still marked, we show it now. */
1373 |     if (he->domain)
1374 |     {
1375 |       he->domain = 0;
1376 | 
1377 |       if ((he->color != INSPF) && reachable)
1378 | 	continue;
1379 | 
1380 |       if (!hdr)
1381 |       {
1382 | 	cli_msg(-1016, "");
1383 | 	cli_msg(-1016, "other ASBRs");
1384 | 	hdr = 1;
1385 |       }
1386 | 
1387 |       if (he->lsa.rt != last_rt)
1388 |       {
1389 | 	cli_msg(-1016, "");
1390 | 	cli_msg(-1016, "\trouter %R", he->lsa.rt);
1391 | 	last_rt = he->lsa.rt;
1392 |       }
1393 | 
1394 |       show_lsa_external(he, ospf2, af);
1395 |     }
1396 |   }
1397 | 
1398 |   cli_msg(0, "");
1399 | }
