1402 | static int
1403 | lsa_compare_for_lsadb(const void *p1, const void *p2)
1404 | {
1405 |   struct top_hash_entry * he1 = * (struct top_hash_entry **) p1;
1406 |   struct top_hash_entry * he2 = * (struct top_hash_entry **) p2;
1407 |   struct ospf_lsa_header *lsa1 = &(he1->lsa);
1408 |   struct ospf_lsa_header *lsa2 = &(he2->lsa);
1409 |   int sc1 = LSA_SCOPE(he1->lsa_type);
1410 |   int sc2 = LSA_SCOPE(he2->lsa_type);
1411 | 
1412 |   if (sc1 != sc2)
1413 |     return sc2 - sc1;
1414 | 
1415 |   if (he1->domain != he2->domain)
1416 |     return he1->domain - he2->domain;
1417 | 
1418 |   if (lsa1->rt != lsa2->rt)
1419 |     return lsa1->rt - lsa2->rt;
1420 | 
1421 |   if (lsa1->id != lsa2->id)
1422 |     return lsa1->id - lsa2->id;
1423 | 
1424 |   if (he1->lsa_type != he2->lsa_type)
1425 |     return he1->lsa_type - he2->lsa_type;
1426 | 
1427 |   return lsa1->sn - lsa2->sn;
1428 | }
1429 | 
1430 | void
1431 | ospf_sh_lsadb(struct lsadb_show_data *ld)
1432 | {
1433 |   struct ospf_proto *p = ld->proto;
1434 |   uint num = p->gr->hash_entries;
1435 |   uint i, j;
1436 |   int last_dscope = -1;
1437 |   u32 last_domain = 0;
1438 |   u16 type_mask = ospf_is_v2(p) ?  0x00ff : 0xffff;	/* see lsa_etype() */
1439 | 
1440 |   if (p->p.proto_state != PS_UP)
1441 |   {
1442 |     cli_msg(-1017, "%s: is not up", p->p.name);
1443 |     cli_msg(0, "");
1444 |     return;
1445 |   }
1446 | 
1447 |   if (ld->router == SH_ROUTER_SELF)
1448 |     ld->router = p->router_id;
1449 | 
1450 |   struct top_hash_entry *hea[num];
1451 |   struct top_hash_entry *he;
1452 | 
1453 |   j = 0;
1454 |   WALK_SLIST(he, p->lsal)
1455 |     if (he->lsa_body)
1456 |       hea[j++] = he;
1457 | 
1458 |   ASSERT(j <= num);
1459 | 
1460 |   qsort(hea, j, sizeof(struct top_hash_entry *), lsa_compare_for_lsadb);
1461 | 
1462 |   for (i = 0; i < j; i++)
1463 |   {
1464 |     struct ospf_lsa_header *lsa = &(hea[i]->lsa);
1465 |     u16 lsa_type = lsa->type_raw & type_mask;
1466 |     u16 dscope = LSA_SCOPE(hea[i]->lsa_type);
1467 | 
1468 |     /* Hack: 1 is used for LSA_SCOPE_LINK, fixed by & 0xf000 */
1469 |     if (ld->scope && (dscope != (ld->scope & 0xf000)))
1470 |       continue;
1471 | 
1472 |     if ((ld->scope == LSA_SCOPE_AREA) && (hea[i]->domain != ld->area))
1473 |       continue;
1474 | 
1475 |     /* For user convenience ignore high nibble */
1476 |     if (ld->type && ((lsa_type & 0x0fff) != (ld->type & 0x0fff)))
1477 |       continue;
1478 | 
1479 |     if (ld->lsid && (lsa->id != ld->lsid))
1480 |       continue;
1481 | 
1482 |     if (ld->router && (lsa->rt != ld->router))
1483 |       continue;
1484 | 
1485 |     if ((dscope != last_dscope) || (hea[i]->domain != last_domain))
1486 |     {
1487 |       cli_msg(-1017, "");
1488 |       switch (dscope)
1489 |       {
1490 |       case LSA_SCOPE_AS:
1491 | 	cli_msg(-1017, "Global");
1492 | 	break;
1493 | 
1494 |       case LSA_SCOPE_AREA:
1495 | 	cli_msg(-1017, "Area %R", hea[i]->domain);
1496 | 	break;
1497 | 
1498 |       case LSA_SCOPE_LINK:
1499 | 	{
1500 | 	  struct iface *ifa = if_find_by_index(hea[i]->domain);
1501 | 	  cli_msg(-1017, "Link %s", (ifa != NULL) ? ifa->name : "?");
1502 | 	}
1503 | 	break;
1504 |       }
1505 |       cli_msg(-1017, "");
1506 |       cli_msg(-1017," Type   LS ID           Router          Sequence   Age  Checksum");
1507 | 
1508 |       last_dscope = dscope;
1509 |       last_domain = hea[i]->domain;
1510 |     }
1511 | 
1512 |     cli_msg(-1017," %04x  %-15R %-15R  %08x %5u    %04x",
1513 | 	    lsa_type, lsa->id, lsa->rt, lsa->sn, lsa->age, lsa->checksum);
1514 |   }
1515 |   cli_msg(0, "");
1516 | }
