 26 | ospf_pkt_fill_hdr(struct ospf_iface *ifa, void *buf, u8 h_type)
 27 | {
 28 |   struct ospf_proto *p = ifa->oa->po;
 29 |   struct ospf_packet *pkt;
 30 | 
 31 |   pkt = (struct ospf_packet *) buf;
