649 | 
650 | void
651 | ospf_send_to(struct ospf_iface *ifa, ip_addr dst)
652 | {
653 |   sock *sk = ifa->sk;
654 |   struct ospf_packet *pkt = (struct ospf_packet *) sk->tbuf;
655 |   uint plen = ntohs(pkt->length);
656 | 
657 |   if (ospf_is_v2(ifa->oa->po))
658 |     ospf_pkt_finalize2(ifa, pkt, &plen);
659 |   else
660 |     ospf_pkt_finalize3(ifa, pkt, &plen, sk->saddr);
661 | 
662 |   int done = sk_send_to(sk, plen, dst, 0);
663 |   if (!done)
664 |     log(L_WARN "OSPF: TX queue full on %s", ifa->ifname);
665 | }
666 | 
667 | static void
668 | ospf_send_to_designated(struct ospf_iface *ifa)
669 | {
670 |   /* In case of real-broadcast mode */
671 |   if (ipa_zero(ifa->des_routers))
672 |   {
673 |     if (ipa_nonzero2(ifa->drip))
674 |       ospf_send_to(ifa, ifa->drip);
675 | 
676 |     if (ipa_nonzero2(ifa->bdrip))
677 |       ospf_send_to(ifa, ifa->bdrip);
678 | 
679 |     return;
680 |   }
681 | 
682 |   ospf_send_to(ifa, ifa->des_routers);
683 | }
684 | 
685 | static void
686 | ospf_send_to_adjacent(struct ospf_iface *ifa)
687 | {
688 |   struct ospf_neighbor *n;
689 | 
690 |   WALK_LIST(n, ifa->neigh_list)
691 |     if (n->state >= NEIGHBOR_EXCHANGE)
692 |       ospf_send_to(ifa, n->ip);
693 | }
694 | 
695 | void
696 | ospf_send_to_iface(struct ospf_iface *ifa)
697 | {
698 |   /*
699 |    * Send packet to (relevant) neighbors on iface
700 |    *
701 |    * On broadcast networks, destination is either AllSPFRouters, or AllDRouters.
702 |    * On PtP networks, destination is always AllSPFRouters. On non-broadcast
703 |    * networks, packets are sent as unicast to every adjacent neighbor.
704 |    */
705 | 
706 |   if (ifa->type == OSPF_IT_BCAST)
707 |   {
708 |     if ((ifa->state == OSPF_IS_DR) || (ifa->state == OSPF_IS_BACKUP))
709 |       ospf_send_to_all(ifa);
710 |     else
711 |       ospf_send_to_designated(ifa);
712 |   }
713 |   else if (ifa->type == OSPF_IT_PTP)
714 |     ospf_send_to_all(ifa);
715 |   else /* Non-broadcast */
716 |     ospf_send_to_adjacent(ifa);
717 | }

