1880 | 
1881 | /* Add LSA into list of candidates in Dijkstra's algorithm */
1882 | static void
1883 | add_cand(struct ospf_area *oa, struct top_hash_entry *en, struct top_hash_entry *par,
1884 | 	 u32 dist, int pos, uint data, uint lif, uint nif)
1885 | {
1886 |   struct ospf_proto *p = oa->po;
1887 |   node *prev, *n;
1888 |   int added = 0;
1889 |   struct top_hash_entry *act;
1890 | 
1891 |   /* 16.1. (2b) */
1892 |   if (en == NULL)
1893 |     return;
1894 |   if (en->lsa.age == LSA_MAXAGE)
1895 |     return;
1896 | 
1897 |   if (ospf_is_v3(p) && (oa->options & OPT_V6) && (en->lsa_type == LSA_T_RT))
1898 |   {
1899 |     /* In OSPFv3 IPv6 unicast, check V6 flag */
1900 |     struct ospf_lsa_rt *rt = en->lsa_body;
1901 |     if (!(rt->options & OPT_V6))
1902 |       return;
1903 |   }
1904 | 
1905 |   /* 16.1. (2c) */
1906 |   if (en->color == INSPF)
1907 |     return;
1908 | 
1909 |   /* 16.1. (2d), also checks that dist < LSINFINITY */
1910 |   if (dist > en->dist)
1911 |     return;
1912 | 
1913 |   /* We should check whether there is a reverse link from en to par, */
1914 |   if (!link_back(oa, en, par, lif, nif))
1915 |     return;
1916 | 
1917 |   struct nexthop *nhs = calc_next_hop(oa, en, par, pos, data, lif, nif);
1918 |   if (!nhs)
1919 |   {
1920 |     log(L_WARN "%s: Cannot find next hop for LSA (Type: %04x, Id: %R, Rt: %R)",
1921 | 	p->p.name, en->lsa_type, en->lsa.id, en->lsa.rt);
1922 |     return;
1923 |   }
1924 | 
1925 |   /* If en->dist > 0, we know that en->color == CANDIDATE and en->nhs is defined. */
1926 |   if ((dist == en->dist) && !nh_is_vlink(en->nhs))
1927 |   {
1928 |     /*
1929 |      * For multipath, we should merge nexthops. We merge regular nexthops only.
1930 |      * Dummy vlink nexthops are less preferred and handled as a special case.
1931 |      *
1932 |      * During merging, new nexthops (nhs) can be reused if they are not
1933 |      * inherited from the parent (i.e. they are allocated in calc_next_hop()).
1934 |      * Current nexthops (en->nhs) can be reused if they weren't inherited in
1935 |      * previous steps (that is stored in nhs_reuse, i.e. created by merging or
1936 |      * allocated in calc_next_hop()).
1937 |      *
1938 |      * Generally, a node first inherits shared nexthops from its parent and
1939 |      * later possibly gets reusable (private) copy during merging. This is more
1940 |      * or less same for both top_hash_entry nodes and orta nodes.
1941 |      *
1942 |      * Note that when a child inherits a private nexthop from its parent, it
1943 |      * should make the nexthop shared for both parent and child, while we only
1944 |      * update nhs_reuse for the child node. This makes nhs_reuse field for the
1945 |      * parent technically incorrect, but it is not a problem as parent's nhs
1946 |      * will not be modified (and nhs_reuse examined) afterwards.
1947 |      */
1948 | 
1949 |     /* Keep old ones */
1950 |     if (!p->ecmp || nh_is_vlink(nhs) || (nhs == en->nhs))
1951 |       return;
1952 | 
1953 |     /* Merge old and new */
1954 |     int new_reuse = (par->nhs != nhs);
1955 |     en->nhs = nexthop_merge(en->nhs, nhs, en->nhs_reuse, new_reuse, p->ecmp, p->nhpool);
1956 |     en->nhs_reuse = 1;
1957 |     return;
1958 |   }
1959 | 
1960 |   DBG("     Adding candidate: rt: %R, id: %R, type: %u\n",
1961 |       en->lsa.rt, en->lsa.id, en->lsa_type);
1962 | 
1963 |   if (en->color == CANDIDATE)
1964 |   {				/* We found a shorter path */
1965 |     rem_node(&en->cn);
1966 |   }
1967 |   en->nhs = nhs;
1968 |   en->dist = dist;
1969 |   en->color = CANDIDATE;
1970 |   en->nhs_reuse = (par->nhs != nhs);
1971 | 
1972 |   prev = NULL;
1973 | 
1974 |   if (EMPTY_LIST(oa->cand))
1975 |   {
1976 |     add_head(&oa->cand, &en->cn);
1977 |   }
1978 |   else
1979 |   {
1980 |     WALK_LIST(n, oa->cand)
1981 |     {
1982 |       act = SKIP_BACK(struct top_hash_entry, cn, n);
1983 |       if ((act->dist > dist) ||
1984 | 	  ((act->dist == dist) && (act->lsa_type == LSA_T_RT)))
1985 |       {
1986 | 	if (prev == NULL)
1987 | 	  add_head(&oa->cand, &en->cn);
1988 | 	else
1989 | 	  insert_node(&en->cn, prev);
1990 | 	added = 1;
1991 | 	break;
1992 |       }
1993 |       prev = n;
1994 |     }
1995 | 
1996 |     if (!added)
1997 |     {
1998 |       add_tail(&oa->cand, &en->cn);
1999 |     }
2000 |   }
2001 | }
