2003 | static inline int
2004 | ort_changed(ort *nf, rta *nr)
2005 | {
2006 |   rta *or = nf->old_rta;
2007 |   return !or ||
2008 |     (nf->n.metric1 != nf->old_metric1) || (nf->n.metric2 != nf->old_metric2) ||
2009 |     (nf->n.tag != nf->old_tag) || (nf->n.rid != nf->old_rid) ||
2010 |     (nr->source != or->source) || (nr->dest != or->dest) ||
2011 |     !nexthop_same(&(nr->nh), &(or->nh));
2012 | }
