2014 | static void
2015 | rt_sync(struct ospf_proto *p)
2016 | {
2017 |   struct top_hash_entry *en;
2018 |   struct fib_iterator fit;
2019 |   struct fib *fib = &p->rtf;
2020 |   struct ospf_area *oa;
2021 | 
2022 |   /* This is used for forced reload of routes */
2023 |   int reload = (p->calcrt == 2);
2024 | 
2025 |   OSPF_TRACE(D_EVENTS, "Starting routing table synchronization");
2026 | 
2027 |   DBG("Now syncing my rt table with nest's\n");
2028 |   FIB_ITERATE_INIT(&fit, fib);
2029 | again1:
2030 |   FIB_ITERATE_START(fib, &fit, ort, nf)
2031 |   {
2032 |     /* Sanity check of next-hop addresses, failure should not happen */
2033 |     if (nf->n.type)
2034 |     {
2035 |       struct nexthop *nh;
2036 |       for (nh = nf->n.nhs; nh; nh = nh->next)
2037 | 	if (ipa_nonzero(nh->gw))
2038 | 	{
2039 | 	  neighbor *nbr = neigh_find(&p->p, nh->gw, nh->iface,
2040 | 				    (nh->flags & RNF_ONLINK) ? NEF_ONLINK : 0);
2041 | 
2042 | 	  /* According to RFC 5838 2.5 Direct Interface Address */
2043 | 	  if (ospf_is_v3(p) && !nbr && ipa_is_ip4(nh->gw))
2044 | 	  {
2045 | 	    nh->flags |= RNF_ONLINK;
2046 | 	    nbr = neigh_find(&p->p, nh->gw, nh->iface, NEF_ONLINK);
2047 | 	  }
2048 | 
2049 | 	  if (!nbr || (nbr->scope == SCOPE_HOST))
2050 | 	    { reset_ri(nf); break; }
2051 | 	}
2052 |     }
2053 | 
2054 |     /* Remove configured stubnets but keep the entries */
2055 |     if (nf->n.type && !nf->n.nhs)
2056 |     {
2057 |       reset_ri(nf);
2058 |       nf->keep = 1;
2059 |     }
2060 | 
2061 |     if (nf->n.type) /* Add the route */
2062 |     {
2063 |       rta a0 = {
2064 | 	.source = nf->n.type,
2065 | 	.scope = SCOPE_UNIVERSE,
2066 | 	.dest = RTD_UNICAST,
2067 | 	.nh = *(nf->n.nhs),
2068 | 	.pref = p->p.main_channel->preference,
2069 |       };
2070 | 
2071 |       if (reload || ort_changed(nf, &a0))
2072 |       {
2073 | 	a0.eattrs = alloca(sizeof(ea_list) + 4 * sizeof(eattr));
2074 | 	memset(a0.eattrs, 0, sizeof(ea_list));
2075 | 
2076 | 	nf->old_metric1 = nf->n.metric1;
2077 | 	nf->old_metric2 = nf->n.metric2;
2078 | 	nf->old_tag = nf->n.tag;
2079 | 	nf->old_rid = nf->n.rid;
2080 | 
2081 | 	a0.eattrs->attrs[a0.eattrs->count++] = (eattr) {
2082 | 	  .id = EA_OSPF_METRIC1,
2083 | 	  .type = EAF_TYPE_INT,
2084 | 	  .u.data = nf->n.metric1,
2085 | 	};
2086 | 
2087 | 	if (nf->n.type == RTS_OSPF_EXT2)
2088 | 	  a0.eattrs->attrs[a0.eattrs->count++] = (eattr) {
2089 | 	    .id = EA_OSPF_METRIC2,
2090 | 	    .type = EAF_TYPE_INT,
2091 | 	    .u.data = nf->n.metric2,
2092 | 	  };
2093 | 
2094 | 	if ((nf->n.type == RTS_OSPF_EXT1) || (nf->n.type == RTS_OSPF_EXT2))
2095 | 	  a0.eattrs->attrs[a0.eattrs->count++] = (eattr) {
2096 | 	    .id = EA_OSPF_TAG,
2097 | 	    .type = EAF_TYPE_INT,
2098 | 	    .u.data = nf->n.tag,
2099 | 	  };
2100 | 
2101 | 	a0.eattrs->attrs[a0.eattrs->count++] = (eattr) {
2102 | 	  .id = EA_OSPF_ROUTER_ID,
2103 | 	  .type = EAF_TYPE_ROUTER_ID,
2104 | 	  .u.data = nf->n.rid,
2105 | 	};
2106 | 
2107 | 	rta *a = rta_lookup(&a0);
2108 | 	rte *e = rte_get_temp(a, p->p.main_source);
2109 | 
2110 | 	rta_free(nf->old_rta);
2111 | 	nf->old_rta = rta_clone(a);
2112 | 
2113 | 	DBG("Mod rte type %d - %N via %I on iface %s, met %d\n",
2114 | 	    a0.source, nf->fn.addr, a0.gw, a0.iface ? a0.iface->name : "(none)", nf->n.metric1);
2115 | 	rte_update(&p->p, nf->fn.addr, e);
2116 |       }
2117 |     }
2118 |     else if (nf->old_rta)
2119 |     {
2120 |       /* Remove the route */
2121 |       rta_free(nf->old_rta);
2122 |       nf->old_rta = NULL;
2123 | 
2124 |       rte_update(&p->p, nf->fn.addr, NULL);
2125 |     }
2126 | 
2127 |     /* Remove unused rt entry, some special entries are persistent */
2128 |     if (!nf->n.type && !nf->external_rte && !nf->area_net && !nf->keep)
2129 |     {
2130 |       if (nf->lsa_id)
2131 | 	idm_free(&p->idm, nf->lsa_id);
2132 | 
2133 |       FIB_ITERATE_PUT(&fit);
2134 |       fib_delete(fib, nf);
2135 |       goto again1;
2136 |     }
2137 |   }
2138 |   FIB_ITERATE_END;
2139 | 
2140 | 
2141 |   WALK_LIST(oa, p->area_list)
2142 |   {
2143 |     /* Cleanup ASBR hash tables */
2144 |     FIB_ITERATE_INIT(&fit, &oa->rtr);
2145 | again2:
2146 |     FIB_ITERATE_START(&oa->rtr, &fit, ort, nf)
2147 |     {
2148 |       if (!nf->n.type)
2149 |       {
2150 | 	FIB_ITERATE_PUT(&fit);
2151 | 	fib_delete(&oa->rtr, nf);
2152 | 	goto again2;
2153 |       }
2154 |     }
2155 |     FIB_ITERATE_END;
2156 |   }
2157 | 
2158 |   /* Cleanup stale LSAs */
2159 |   WALK_SLIST(en, p->lsal)
2160 |     if (en->mode == LSA_M_RTCALC_STALE)
2161 |       ospf_flush_lsa(p, en);
2162 | }
