2165 | /* RFC 3623 2.2 - checking for graceful restart termination conditions */
2166 | void
2167 | ospf_update_gr_recovery(struct ospf_proto *p)
2168 | {
2169 |   struct top_hash_entry *rt, *net, *nbr;
2170 |   struct ospf_lsa_rt_walk rtl;
2171 |   struct ospf_neighbor *n;
2172 |   struct ospf_iface *ifa;
2173 |   struct ospf_area *oa;
2174 |   const char *err_dsc = NULL;
2175 |   uint i, j, missing = 0, err_val = 0;
2176 | 
2177 |   /*
2178 |    * We check here for three cases:
2179 |    * RFC 3623 2.2 (1) - success when all adjacencies are established
2180 |    * RFC 3623 2.2 (2) - failure when inconsistent LSA was received
2181 |    * RFC 3623 2.2 (3) - grace period timeout
2182 |    *
2183 |    * It is handled by processing pre-restart local router-LSA and adjacent
2184 |    * network-LSAs, checking neighbor association for referenced routers (1)
2185 |    * and checking back links from their router-LSAs (2).
2186 |    *
2187 |    * TODO: Use timer for grace period timeout. We avoided that as function
2188 |    * ospf_stop_gr_recovery() called from ospf_disp() makes ending of graceful
2189 |    * restart uninterrupted by other events.
2190 |    */
2191 | 
2192 |   #define CONTINUE { missing++; continue; }
2193 | 
2194 |   if (current_time() > p->gr_timeout)
2195 |     goto timeout;
2196 | 
2197 |   WALK_LIST(oa, p->area_list)
2198 |   {
2199 |     /* Get the router-LSA */
2200 |     rt = oa->rt;
2201 |     if (!rt || (rt->lsa.age == LSA_MAXAGE))
2202 |       CONTINUE;
2203 | 
2204 |     for (lsa_walk_rt_init(p, rt, &rtl), i = 0; lsa_walk_rt(&rtl); i++)
2205 |     {
2206 |       if (rtl.type == LSART_STUB)
2207 | 	continue;
2208 | 
2209 |       ifa = rt_find_iface(oa, i, rtl.data, rtl.lif);
2210 |       if (!ifa)
2211 | 	DROP("inconsistent interface", ospf_is_v2(p) ? rtl.data : rtl.lif);
2212 | 
2213 |       switch (rtl.type)
2214 |       {
2215 |       case LSART_NET:
2216 | 	/* Find the network-LSA */
2217 | 	net = ospf_hash_find_net(p->gr, oa->areaid, rtl.id, rtl.nif);
2218 | 	if (!net)
2219 | 	  CONTINUE;
2220 | 
2221 | 	if (!link_back(oa, net, rt, rtl.lif, rtl.nif))
2222 | 	  DROP("Inconsistent network-LSA", net->lsa.id);
2223 | 
2224 | 	if (ifa->state == OSPF_IS_DR)
2225 | 	{
2226 | 	  /* Find all neighbors from the network-LSA */
2227 | 	  struct ospf_lsa_net *net_body = net->lsa_body;
2228 | 	  uint cnt = lsa_net_count(&net->lsa);
2229 | 	  for (j = 0; j < cnt; i++)
2230 | 	  {
2231 | 	    n = find_neigh(ifa, net_body->routers[j]);
2232 | 	    if (!n || (n->state != NEIGHBOR_FULL))
2233 | 	      CONTINUE;
2234 | 
2235 | 	    if (!n->got_my_rt_lsa)
2236 | 	      DROP("not received my router-LSA", n->rid);
2237 | 
2238 | 	    nbr = ospf_hash_find_rt(p->gr, oa->areaid, n->rid);
2239 | 	    if (!link_back(oa, nbr, net, 0, 0))
2240 | 	      DROP("inconsistent router-LSA", n->rid);
2241 | 	  }
2242 | 	}
2243 | 	else
2244 | 	{
2245 | 	  /* Find the DR (by IP for OSPFv2) */
2246 | 	  n = ospf_is_v2(p) ?
2247 | 	    find_neigh_by_ip(ifa, ipa_from_u32(rtl.id)) :
2248 | 	    find_neigh(ifa, rtl.id);
2249 | 	  if (!n || (n->state != NEIGHBOR_FULL))
2250 | 	    CONTINUE;
2251 | 
2252 | 	  if (!n->got_my_rt_lsa)
2253 | 	    DROP("not received my router-LSA", n->rid);
2254 | 	}
2255 | 	break;
2256 | 
2257 |       case LSART_VLNK:
2258 |       case LSART_PTP:
2259 | 	/* Find the PtP peer */
2260 | 	n = find_neigh(ifa, rtl.id);
2261 | 	if (!n || (n->state != NEIGHBOR_FULL))
2262 | 	  CONTINUE;
2263 | 
2264 | 	if (!n->got_my_rt_lsa)
2265 | 	  DROP("not received my router-LSA", n->rid);
2266 | 
2267 | 	nbr = ospf_hash_find_rt(p->gr, oa->areaid, rtl.id);
2268 | 	if (!link_back(oa, nbr, rt, rtl.lif, rtl.nif))
2269 | 	  DROP("inconsistent router-LSA", rtl.id);
2270 |       }
2271 |     }
2272 |   }
2273 | 
2274 |   #undef CONTINUE
2275 | 
2276 |   if (missing)
2277 |     return;
2278 | 
2279 |   OSPF_TRACE(D_EVENTS, "Graceful restart finished");
2280 |   ospf_stop_gr_recovery(p);
2281 |   return;
2282 | 
2283 | drop:
2284 |   log(L_INFO "%s: Graceful restart ended - %s (%R)", p->p.name, err_dsc, err_val);
2285 |   ospf_stop_gr_recovery(p);
2286 |   return;
