 863 | static inline void
 864 | add_rt3_lsa_link(struct ospf_proto *p, u8 type, struct ospf_iface *ifa, u32 nif, u32 id)
 865 | {
 866 |   struct ospf_lsa_rt3_link *ln = lsab_alloc(p, sizeof(struct ospf_lsa_rt3_link));
 867 |   ln->type = type;
 868 |   ln->padding = 0;
 869 |   ln->metric = ifa->cost;
 870 |   ln->lif = ifa->iface_id;
 871 |   ln->nif = nif;
 872 |   ln->id = id;
 873 | }
