 958 |  *	Net-LSA handling
 959 |  *	Type = LSA_T_NET
 960 |  */
 961 | 
 962 | static void
 963 | prepare_net2_lsa_body(struct ospf_proto *p, struct ospf_iface *ifa)
 964 | {
 965 |   struct ospf_lsa_net *net;
 966 |   struct ospf_neighbor *n;
 967 |   int nodes = ifa->fadj + 1;
 968 |   u16 i = 1;
 969 | 
 970 |   ASSERT(p->lsab_used == 0);
 971 |   net = lsab_alloc(p, sizeof(struct ospf_lsa_net) + 4 * nodes);
 972 | 
 973 |   net->optx = u32_mkmask(ifa->addr->prefix.pxlen);
 974 |   net->routers[0] = p->router_id;
 975 | 
 976 |   WALK_LIST(n, ifa->neigh_list)
 977 |   {
 978 |     if (n->state == NEIGHBOR_FULL)
 979 |     {
 980 |       net->routers[i] = n->rid;
 981 |       i++;
 982 |     }
 983 |   }
 984 |   ASSERT(i == nodes);
 985 | }
 986 | 
 987 | static void
 988 | prepare_net3_lsa_body(struct ospf_proto *p, struct ospf_iface *ifa)
 989 | {
 990 |   struct ospf_lsa_net *net;
 991 |   int nodes = ifa->fadj + 1;
 992 |   u32 options = 0;
 993 |   u16 i = 1;
 994 | 
 995 |   ASSERT(p->lsab_used == 0);
 996 |   net = lsab_alloc(p, sizeof(struct ospf_lsa_net) + 4 * nodes);
 997 | 
 998 |   net->routers[0] = p->router_id;
 999 | 
1000 |   struct ospf_neighbor *n;
1001 |   WALK_LIST(n, ifa->neigh_list)
1002 |   {
1003 |     if (n->state == NEIGHBOR_FULL)
1004 |     {
1005 |       /* In OSPFv3, we would like to merge options from Link LSAs of added neighbors */
1006 | 
1007 |       struct top_hash_entry *en =
1008 | 	ospf_hash_find(p->gr, ifa->iface_id, n->iface_id, n->rid, LSA_T_LINK);
1009 | 
1010 |       if (en)
1011 | 	options |= ((struct ospf_lsa_link *) en->lsa_body)->options;
1012 | 
1013 |       net->routers[i] = n->rid;
1014 |       i++;
1015 |     }
1016 |   }
1017 |   ASSERT(i == nodes);
1018 | 
1019 |   net->optx = options & LSA_OPTIONS_MASK;
1020 | }
