1026 |     .type = LSA_T_NET,
1027 |     .dom  = ifa->oa->areaid,
1028 |     .id   = ospf_is_v2(p) ? ipa_to_u32(ifa->addr->ip) : ifa->iface_id,
1029 |     .opts = ifa->oa->options,
1030 |     .ifa  = ifa
1031 |   };
1032 | 
1033 |   OSPF_TRACE(D_EVENTS, "Updating network state for %s (Id: %R)", ifa->ifname, lsa.id);
1034 | 
1035 |   if (ospf_is_v2(p))
1036 |     prepare_net2_lsa_body(p, ifa);
1037 |   else
1038 |     prepare_net3_lsa_body(p, ifa);
1039 | 
1040 |   ifa->net_lsa = ospf_originate_lsa(p, &lsa);
1041 | }
