1044 | /*
1045 |  *	(Net|Rt)-summary-LSA handling
1046 |  *	(a.k.a. Inter-Area-(Prefix|Router)-LSA)
1047 |  *	Type = LSA_T_SUM_NET, LSA_T_SUM_RT
1048 |  */
1049 | 
1050 | static inline void
1051 | prepare_sum2_lsa_body(struct ospf_proto *p, uint pxlen, u32 metric)
1052 | {
1053 |   struct ospf_lsa_sum2 *sum;
1054 | 
1055 |   sum = lsab_allocz(p, sizeof(struct ospf_lsa_sum2));
1056 |   sum->netmask = u32_mkmask(pxlen);
1057 |   sum->metric = metric;
1058 | }
1059 | 
1060 | static inline void
1061 | prepare_sum3_net_lsa_body(struct ospf_proto *p, ort *nf, u32 metric)
1062 | {
1063 |   struct ospf_lsa_sum3_net *sum;
1064 | 
1065 |   sum = lsab_allocz(p, sizeof(struct ospf_lsa_sum3_net) +
1066 | 		    IPV6_PREFIX_SPACE(nf->fn.addr->pxlen));
1067 |   sum->metric = metric;
1068 |   ospf3_put_prefix(sum->prefix, nf->fn.addr, 0, 0);
1069 | }
