1089 |     .id   = ort_to_lsaid(p, nf),
1090 |     .opts = oa->options,
1091 |     .nf   = nf
1092 |   };
1093 | 
1094 |   if (ospf_is_v2(p))
1095 |     prepare_sum2_lsa_body(p, nf->fn.addr->pxlen, metric);
1096 |   else
1097 |     prepare_sum3_net_lsa_body(p, nf, metric);
