 962 | static void
 963 | prepare_net2_lsa_body(struct ospf_proto *p, struct ospf_iface *ifa)
 964 | {
 965 |   struct ospf_lsa_net *net;
 966 |   struct ospf_neighbor *n;
 967 |   int nodes = ifa->fadj + 1;
 968 |   u16 i = 1;
 969 | 
 970 |   ASSERT(p->lsab_used == 0);
