1405 | static inline void
1406 | update_loopback_addr(struct ospf_proto *p)
1407 | {
1408 |   ip_addr old_addr = p->loopback_addr;
1409 |   ip_addr best_addr = IPA_NONE;
1410 |   int best_pref = 0;
1411 | 
1412 |   struct ospf_iface *ifa;
1413 |   WALK_LIST(ifa, p->iface_list)
1414 |   {
1415 |     if (ifa->type == OSPF_IT_VLINK)
1416 |       continue;
1417 | 
1418 |     struct ifa *a;
1419 |     WALK_LIST(a, ifa->iface->addrs)
1420 |     {
1421 |       if ((a->prefix.type != ospf_get_af(p)) ||
1422 | 	  (a->flags & IA_SECONDARY) ||
1423 | 	  (a->scope <= SCOPE_LINK))
1424 | 	continue;
1425 | 
1426 |       int pref = (a->flags & IA_HOST) ? 3 : (ifa->stub ? 2 : 1);
1427 |       if ((pref > best_pref) || ((pref == best_pref) && ipa_equal(a->ip, old_addr)))
1428 |       {
1429 | 	best_addr = a->ip;
1430 | 	best_pref = pref;
1431 |       }
1432 |     }
1433 |   }
1434 | 
1435 |   if (ipa_equal(best_addr, old_addr))
1436 |     return;
1437 | 
1438 |   p->loopback_addr = best_addr;
1439 | 
1440 |   WALK_LIST(ifa, p->iface_list)
1441 |     if (ifa->loopback_addr_used)
1442 |       ospf_notify_link_lsa(ifa);
1443 | }
1444 | 
1445 | static void
1446 | prepare_link_lsa_body(struct ospf_proto *p, struct ospf_iface *ifa)
1447 | {
1448 |   ip_addr nh = ospf_is_ip4(p) ? IPA_NONE : ifa->addr->ip;
1449 |   int i = 0;
1450 | 
1451 |   /* Preallocating space for header */
1452 |   ASSERT(p->lsab_used == 0);
1453 |   lsab_allocz(p, sizeof(struct ospf_lsa_link));
1454 | 
1455 |   struct ifa *a;
1456 |   WALK_LIST(a, ifa->iface->addrs)
1457 |   {
1458 |     if ((a->prefix.type != ospf_get_af(p)) ||
1459 | 	(a->flags & IA_SECONDARY) ||
1460 | 	(a->scope <= SCOPE_LINK))
1461 |       continue;
1462 | 
1463 |     if (ospf_is_ip4(p) && ipa_zero(nh))
1464 |       nh = a->ip;
1465 | 
1466 |     lsab_put_prefix(p, &a->prefix, 0);
1467 |     i++;
1468 |   }
1469 | 
1470 |   if (ospf_is_ip4(p) && ipa_zero(nh))
1471 |   {
1472 |     nh = p->loopback_addr;
1473 |     ifa->loopback_addr_used = 1;
1474 |   }
1475 | 
1476 |   /* Filling the preallocated header */
1477 |   struct ospf_lsa_link *ll = p->lsab;
1478 |   ll->options = ifa->oa->options | (ifa->priority << 24);
1479 |   ll->lladdr = ospf_is_ip4(p) ? ospf3_4to6(ipa_to_ip4(nh)) : ipa_to_ip6(nh);
1480 |   ll->pxcount = i;
1481 | 
1482 |   if (ipa_zero(nh))
1483 |     log(L_ERR "%s: Cannot find next hop address for %s", p->p.name, ifa->ifname);
1484 | }
1485 | 
1486 | static void
1487 | ospf_originate_link_lsa(struct ospf_proto *p, struct ospf_iface *ifa)
1488 | {
1489 |   if (ospf_is_v2(p))
1490 |     return;
1491 | 
1492 |   struct ospf_new_lsa lsa = {
1493 |     .type = LSA_T_LINK,
1494 |     .dom  = ifa->iface_id,
1495 |     .id   = ifa->iface_id,
1496 |     .ifa  = ifa
1497 |   };
1498 | 
1499 |   OSPF_TRACE(D_EVENTS, "Updating link state for %s (Id: %R)", ifa->ifname, lsa.id);
1500 | 
1501 |   prepare_link_lsa_body(p, ifa);
1502 | 
1503 |   ifa->link_lsa = ospf_originate_lsa(p, &lsa);
1504 | 
1505 |   /* RFC 5340 4.4.3 Events 6+7 - new Link LSA is locally originated */
1506 |   ospf_notify_net_lsa(ifa);
1507 | }
