1994 | /**
1995 |  * ospf_top_new - allocated new topology database
1996 |  * @p: OSPF protocol instance
1997 |  * @pool: pool for allocation
1998 |  *
1999 |  * This dynamically hashed structure is used for keeping LSAs. Mainly it is used
2000 |  * for the LSA database of the OSPF protocol, but also for LSA retransmission
2001 |  * and request lists of OSPF neighbors.
2002 |  */
2003 | struct top_graph *
2004 | ospf_top_new(struct ospf_proto *p, pool *pool)
2005 | {
2006 |   struct top_graph *f;
2007 | 
2008 |   f = mb_allocz(pool, sizeof(struct top_graph));
2009 |   f->pool = pool;
2010 |   f->hash_slab = sl_new(f->pool, sizeof(struct top_hash_entry));
2011 |   f->hash_order = HASH_DEF_ORDER;
2012 |   ospf_top_ht_alloc(f);
2013 |   f->hash_entries = 0;
2014 |   f->hash_entries_min = 0;
2015 |   f->ospf2 = ospf_is_v2(p);
2016 |   return f;
2017 | }
2018 | 
2019 | void
2020 | ospf_top_free(struct top_graph *f)
2021 | {
2022 |   rfree(f->hash_slab);
2023 |   ospf_top_ht_free(f->hash_table);
2024 |   mb_free(f);
2025 | }
2026 | 
2027 | static void
2028 | ospf_top_rehash(struct top_graph *f, int step)
2029 | {
2030 |   struct top_hash_entry **n, **oldt, **newt, *e, *x;
2031 |   uint oldn, oldh;
2032 | 
2033 |   oldn = f->hash_size;
2034 |   oldt = f->hash_table;
2035 |   DBG("re-hashing topology hash from order %d to %d\n", f->hash_order,
2036 |       f->hash_order + step);
2037 |   f->hash_order += step;
2038 |   ospf_top_ht_alloc(f);
2039 |   newt = f->hash_table;
2040 | 
2041 |   for (oldh = 0; oldh < oldn; oldh++)
2042 |   {
2043 |     e = oldt[oldh];
2044 |     while (e)
2045 |     {
2046 |       x = e->next;
2047 |       n = newt + ospf_top_hash(f, e->domain, e->lsa.id, e->lsa.rt, e->lsa_type);
2048 |       e->next = *n;
2049 |       *n = e;
2050 |       e = x;
2051 |     }
2052 |   }
2053 |   ospf_top_ht_free(oldt);
2054 | }
2055 | 
2056 | static struct top_hash_entry *
2057 | ospf_hash_find_(struct top_graph *f, u32 domain, u32 lsa, u32 rtr, u32 type)
2058 | {
2059 |   struct top_hash_entry *e;
2060 |   e = f->hash_table[ospf_top_hash(f, domain, lsa, rtr, type)];
2061 | 
2062 |   while (e && (e->lsa.id != lsa || e->lsa.rt != rtr ||
2063 | 	       e->lsa_type != type || e->domain != domain))
2064 |     e = e->next;
2065 | 
2066 |   return e;
2067 | }
2068 | 
2069 | struct top_hash_entry *
2070 | ospf_hash_find(struct top_graph *f, u32 domain, u32 lsa, u32 rtr, u32 type)
2071 | {
2072 |   struct top_hash_entry *e = ospf_hash_find_(f, domain, lsa, rtr, type);
2073 | 
2074 |   /* Hide hash entry with empty lsa_body */
2075 |   return (e && e->lsa_body) ? e : NULL;
2076 | }
2077 | 
2078 | /* In OSPFv2, lsa.id is the same as lsa.rt for router LSA. In OSPFv3, we don't know
2079 |    lsa.id when looking for router LSAs. We return matching LSA with smallest lsa.id. */
2080 | struct top_hash_entry *
2081 | ospf_hash_find_rt(struct top_graph *f, u32 domain, u32 rtr)
2082 | {
2083 |   struct top_hash_entry *rv = NULL;
2084 |   struct top_hash_entry *e;
2085 |   /* We can put rtr for lsa.id to hash fn, it is ignored in OSPFv3 */
2086 |   e = f->hash_table[ospf_top_hash(f, domain, rtr, rtr, LSA_T_RT)];
2087 | 
2088 |   while (e)
2089 |   {
2090 |     if (e->lsa.rt == rtr && e->lsa_type == LSA_T_RT && e->domain == domain && e->lsa_body)
2091 |     {
