1722 | static void
1723 | prepare_prefix_net_lsa_body(struct ospf_proto *p, struct ospf_iface *ifa)
1724 | {
1725 |   struct ospf_lsa_prefix *lp;
1726 |   struct ospf_neighbor *n;
1727 |   struct top_hash_entry *en;
1728 |   int pxc, offset;
1729 | 
1730 |   ASSERT(p->lsab_used == 0);
1731 |   lp = lsab_allocz(p, sizeof(struct ospf_lsa_prefix));
1732 |   lp->ref_type = LSA_T_NET;
1733 |   lp->ref_id = ifa->net_lsa->lsa.id;
1734 |   lp->ref_rt = p->router_id;
1735 |   lp = NULL; /* buffer might be reallocated later */
1736 | 
1737 |   pxc = 0;
1738 |   offset = p->lsab_used;
1739 | 
1740 |   /* Find all Link LSAs associated with the link and merge their prefixes */
1741 |   if (en = ifa->link_lsa)
1742 |     add_link_lsa(p, en->next_lsa_body ?: en->lsa_body, offset, &pxc);
1743 | 
1744 |   WALK_LIST(n, ifa->neigh_list)
1745 |     if ((n->state == NEIGHBOR_FULL) &&
1746 | 	(en = ospf_hash_find(p->gr, ifa->iface_id, n->iface_id, n->rid, LSA_T_LINK)))
1747 |       add_link_lsa(p, en->lsa_body, offset, &pxc);
1748 | 
1749 |   lp = p->lsab;
1750 |   lp->pxcount = pxc;
1751 | }
