 713 |   if (ifa->state == OSPF_IS_WAITING)
 714 |     return 0;
 715 | 
 716 |   WALK_LIST(neigh, ifa->neigh_list)
 717 |   {
 718 |     if (neigh->state == NEIGHBOR_FULL)
 719 |     {
 720 |       if (neigh->rid == ifa->drid)
 721 | 	return 1;
 722 | 
 723 |       if (ifa->state == OSPF_IS_DR)
 724 | 	return 1;
 725 |     }
 726 |   }
 727 | 
 728 |   return 0;
