1123 |  *	AS-external-LSA and NSSA-LSA handling
1124 |  *	Type = LSA_T_EXT, LSA_T_NSSA
1125 |  */
1126 | 
1127 | static inline void
1128 | prepare_ext2_lsa_body(struct ospf_proto *p, uint pxlen,
1129 | 		      u32 metric, u32 ebit, ip_addr fwaddr, u32 tag)
1130 | {
1131 |   struct ospf_lsa_ext2 *ext;
1132 | 
1133 |   ext = lsab_allocz(p, sizeof(struct ospf_lsa_ext2));
1134 |   ext->metric = metric & LSA_METRIC_MASK;
1135 |   ext->netmask = u32_mkmask(pxlen);
1136 |   ext->fwaddr = ipa_to_u32(fwaddr);
1137 |   ext->tag = tag;
1138 | 
1139 |   if (ebit)
1140 |     ext->metric |= LSA_EXT2_EBIT;
1141 | }
1142 | 
1143 | static inline void
1144 | prepare_ext3_lsa_body(struct ospf_proto *p, ort *nf,
1145 | 		      u32 metric, u32 ebit, ip_addr fwaddr, u32 tag, int pbit, int dn)
1146 | {
1147 |   struct ospf_lsa_ext3 *ext;
1148 |   int bsize = sizeof(struct ospf_lsa_ext3)
1149 |     + IPV6_PREFIX_SPACE(nf->fn.addr->pxlen)
1150 |     + (ipa_nonzero(fwaddr) ? 16 : 0)
1151 |     + (tag ? 4 : 0);
1152 | 
1153 |   ext = lsab_allocz(p, bsize);
1154 |   ext->metric = metric & LSA_METRIC_MASK;
1155 |   u32 *buf = ext->rest;
1156 | 
1157 |   uint flags = (pbit ? OPT_PX_P : 0) | (dn ? OPT_PX_DN : 0);
1158 |   buf = ospf3_put_prefix(buf, nf->fn.addr, flags, 0);
1159 | 
1160 |   if (ebit)
1161 |     ext->metric |= LSA_EXT3_EBIT;
1162 | 
1163 |   if (ipa_nonzero(fwaddr))
1164 |   {
1165 |     ext->metric |= LSA_EXT3_FBIT;
1166 |     buf = ospf3_put_addr(buf, fwaddr);
1167 |   }
1168 | 
1169 |   if (tag)
1170 |   {
1171 |     ext->metric |= LSA_EXT3_TBIT;
1172 |     *buf++ = tag;
1173 |   }
1174 | }
