 875 | static void
 876 | prepare_rt3_lsa_body(struct ospf_proto *p, struct ospf_area *oa)
 877 | {
 878 |   struct ospf_iface *ifa;
 879 |   struct ospf_neighbor *neigh;
 880 |   int bitv = 0;
 881 |   int i = 0;
 882 | 
 883 |   ASSERT(p->lsab_used == 0);
 884 |   lsab_allocz(p, sizeof(struct ospf_lsa_rt));
 885 |   /* ospf_lsa_rt header will be filled later */
 886 | 
 887 |   WALK_LIST(ifa, p->iface_list)
 888 |   {
 889 |     if ((ifa->type == OSPF_IT_VLINK) && (ifa->voa == oa) &&
 890 | 	(!EMPTY_LIST(ifa->neigh_list)))
 891 |     {
 892 |       neigh = (struct ospf_neighbor *) HEAD(ifa->neigh_list);
 893 |       if ((neigh->state == NEIGHBOR_FULL) && (ifa->cost <= 0xffff))
 894 | 	bitv = 1;
 895 |     }
 896 | 
 897 |     if ((ifa->oa != oa) || (ifa->state == OSPF_IS_DOWN))
 898 |       continue;
 899 | 
 900 |     ifa->rt_pos_beg = i;
 901 | 
 902 |     /* RFC 5340 - 4.4.3.2 */
 903 |     switch (ifa->type)
 904 |     {
 905 |     case OSPF_IT_PTP:
 906 |     case OSPF_IT_PTMP:
 907 |       WALK_LIST(neigh, ifa->neigh_list)
 908 | 	if (neigh->state == NEIGHBOR_FULL)
 909 | 	  add_rt3_lsa_link(p, LSART_PTP, ifa, neigh->iface_id, neigh->rid), i++;
 910 |       break;
 911 | 
 912 |     case OSPF_IT_BCAST:
 913 |     case OSPF_IT_NBMA:
 914 |       if (bcast_net_active(ifa))
 915 | 	add_rt3_lsa_link(p, LSART_NET, ifa, ifa->dr_iface_id, ifa->drid), i++;
 916 |       break;
 917 | 
 918 |     case OSPF_IT_VLINK:
 919 |       neigh = (struct ospf_neighbor *) HEAD(ifa->neigh_list);
 920 |       if ((!EMPTY_LIST(ifa->neigh_list)) && (neigh->state == NEIGHBOR_FULL) && (ifa->cost <= 0xffff))
 921 | 	add_rt3_lsa_link(p, LSART_VLNK, ifa, neigh->iface_id, neigh->rid), i++;
 922 |       break;
 923 | 
 924 |     default:
 925 |       log(L_BUG "OSPF: Unknown interface type");
 926 |       break;
 927 |     }
 928 | 
 929 |     ifa->rt_pos_end = i;
 930 |   }
 931 | 
 932 |   struct ospf_lsa_rt *rt = p->lsab;
 933 |   rt->options = get_rt_options(p, oa, bitv) | (oa->options & LSA_OPTIONS_MASK);
 934 | }
