 936 | static void
 937 | ospf_originate_rt_lsa(struct ospf_proto *p, struct ospf_area *oa)
 938 | {
 939 |   struct ospf_new_lsa lsa = {
 940 |     .type = LSA_T_RT,
 941 |     .dom  = oa->areaid,
 942 |     .id   = ospf_is_v2(p) ? p->router_id : 0,
 943 |     .opts = oa->options
 944 |   };
 945 | 
 946 |   OSPF_TRACE(D_EVENTS, "Updating router state for area %R", oa->areaid);
 947 | 
 948 |   if (ospf_is_v2(p))
 949 |     prepare_rt2_lsa_body(p, oa);
 950 |   else
