1176 | /**
1177 |  * originate_ext_lsa - new route received from nest and filters
1178 |  * @p: OSPF protocol instance
1179 |  * @oa: ospf_area for which LSA is originated
1180 |  * @nf: network prefix and mask
1181 |  * @mode: the mode of the LSA (LSA_M_EXPORT or LSA_M_RTCALC)
1182 |  * @metric: the metric of a route
1183 |  * @ebit: E-bit for route metric (bool)
1184 |  * @fwaddr: the forwarding address
1185 |  * @tag: the route tag
1186 |  * @pbit: P-bit for NSSA LSAs (bool), ignored for external LSAs
1187 |  *
1188 |  * If I receive a message that new route is installed, I try to originate an
1189 |  * external LSA. If @oa is an NSSA area, NSSA-LSA is originated instead.
1190 |  * @oa should not be a stub area. @src does not specify whether the LSA
1191 |  * is external or NSSA, but it specifies the source of origination -
1192 |  * the export from ospf_rt_notify(), or the NSSA-EXT translation.
1193 |  */
1194 | void
1195 | ospf_originate_ext_lsa(struct ospf_proto *p, struct ospf_area *oa, ort *nf, u8 mode,
1196 | 		       u32 metric, u32 ebit, ip_addr fwaddr, u32 tag, int pbit, int dn)
1197 | {
1198 |   struct ospf_new_lsa lsa = {
1199 |     .type = oa ? LSA_T_NSSA : LSA_T_EXT,
1200 |     .mode = mode, /* LSA_M_EXPORT or LSA_M_RTCALC */
1201 |     .dom  = oa ? oa->areaid : 0,
1202 |     .id   = ort_to_lsaid(p, nf),
1203 |     .opts = (oa ? (pbit ? OPT_P : 0) : OPT_E) | (dn ? OPT_DN : 0),
1204 |     .nf   = nf
1205 |   };
1206 | 
1207 |   if (ospf_is_v2(p))
1208 |     prepare_ext2_lsa_body(p, nf->fn.addr->pxlen, metric, ebit, fwaddr, tag);
1209 |   else
1210 |     prepare_ext3_lsa_body(p, nf, metric, ebit, fwaddr, tag, oa && pbit, dn);
1211 | 
1212 |   ospf_originate_lsa(p, &lsa);
1213 | }
