1753 | static void
1754 | ospf_originate_prefix_net_lsa(struct ospf_proto *p, struct ospf_iface *ifa)
1755 | {
1756 |   if (ospf_is_v2(p))
1757 |     return;
1758 | 
1759 |   struct ospf_new_lsa lsa = {
1760 |     .type = LSA_T_PREFIX,
1761 |     .dom  = ifa->oa->areaid,
1762 |     .id   = ifa->iface_id,
1763 |     .ifa  = ifa
1764 |   };
1765 | 
1766 |   prepare_prefix_net_lsa_body(p, ifa);
1767 | 
