1776 | 
1777 | static inline void
1778 | ospf_add_gr_period_tlv(struct ospf_proto *p, uint period)
1779 | {
1780 |   struct ospf_tlv *tlv = lsab_allocz(p, sizeof(struct ospf_tlv) + sizeof(u32));
