1795 | static inline void
1796 | ospf_add_gr_address_tlv(struct ospf_proto *p, ip4_addr addr)
1797 | {
1798 |   struct ospf_tlv *tlv = lsab_allocz(p, sizeof(struct ospf_tlv) + sizeof(u32));
1799 |   tlv->type = LSA_GR_ADDRESS;
1800 |   tlv->length = 4;
