2116 | struct top_hash_entry *
2117 | ospf_hash_find_rt3_first(struct top_graph *f, u32 domain, u32 rtr)
2118 | {
2119 |   struct top_hash_entry *e;
2120 |   e = f->hash_table[ospf_top_hash(f, domain, 0, rtr, LSA_T_RT)];
2121 |   return find_matching_rt3(e, domain, rtr);
2122 | }
2123 | 
2124 | struct top_hash_entry *
2125 | ospf_hash_find_rt3_next(struct top_hash_entry *e)
2126 | {
2127 |   return find_matching_rt3(e->next, e->domain, e->lsa.rt);
2128 | }
