2130 | /* In OSPFv2, we don't know Router ID when looking for network LSAs.
2131 |    There should be just one, so we find any match. */
2132 | struct top_hash_entry *
2133 | ospf_hash_find_net2(struct top_graph *f, u32 domain, u32 id)
2134 | {
2135 |   struct top_hash_entry *e;
