2146 | struct top_hash_entry *
2147 | ospf_hash_get(struct top_graph *f, u32 domain, u32 lsa, u32 rtr, u32 type)
2148 | {
2149 |   struct top_hash_entry **ee;
2150 |   struct top_hash_entry *e;
2151 | 
2152 |   ee = f->hash_table + ospf_top_hash(f, domain, lsa, rtr, type);
2153 |   e = *ee;
2154 | 
2155 |   while (e && (e->lsa.id != lsa || e->lsa.rt != rtr ||
2156 | 	       e->lsa_type != type || e->domain != domain))
2157 |     e = e->next;
2158 | 
2159 |   if (e)
2160 |     return e;
2161 | 
2162 |   e = sl_allocz(f->hash_slab);
2163 |   e->color = OUTSPF;
2164 |   e->dist = LSINFINITY;
2165 |   e->lsa.type_raw = type;
2166 |   e->lsa.id = lsa;
2167 |   e->lsa.rt = rtr;
2168 |   e->lsa.sn = LSA_ZEROSEQNO;
2169 |   e->lsa_type = type;
2170 |   e->domain = domain;
2171 |   e->next = *ee;
2172 |   *ee = e;
2173 |   if (f->hash_entries++ > f->hash_entries_max)
2174 |     ospf_top_rehash(f, HASH_HI_STEP);
2175 |   return e;
2176 | }
