2178 | void
2179 | ospf_hash_delete(struct top_graph *f, struct top_hash_entry *e)
2180 | {
2181 |   struct top_hash_entry **ee = f->hash_table +
2182 |     ospf_top_hash(f, e->domain, e->lsa.id, e->lsa.rt, e->lsa_type);
2183 | 
2184 |   while (*ee)
2185 |   {
2186 |     if (*ee == e)
2187 |     {
2188 |       *ee = e->next;
2189 |       sl_free(e);
2190 |       if (f->hash_entries-- < f->hash_entries_min)
2191 | 	ospf_top_rehash(f, -HASH_LO_STEP);
2192 |       return;
2193 |     }
2194 |     ee = &((*ee)->next);
2195 |   }
2196 |   bug("ospf_hash_delete() called for invalid node");
2197 | }
