 557 |   struct top_hash_entry *en;
 558 | 
 559 |   /* Mark all external LSAs as stale */
 560 |   WALK_SLIST(en, p->lsal)
 561 |     if (en->mode == LSA_M_EXPORT)
 562 |       en->mode = LSA_M_EXPORT_STALE;
