1105 |   struct ospf_new_lsa lsa = {
1106 |     .type = LSA_T_SUM_RT,
1107 |     .mode = LSA_M_RTCALC,
1108 |     .dom  = oa->areaid,
1109 |     .id   = drid,	/* Router ID of ASBR, irrelevant for OSPFv3 */
1110 |     .opts = oa->options
1111 |   };
1112 | 
1113 |   if (ospf_is_v2(p))
1114 |     prepare_sum2_lsa_body(p, 0, metric);
1115 |   else
1116 |     prepare_sum3_rt_lsa_body(p, drid, metric, options & LSA_OPTIONS_MASK);
1117 | 
1118 |   ospf_originate_lsa(p, &lsa);
1119 | }
