1392 |  *	Link-LSA handling (assume OSPFv3)
1393 |  *	Type = LSA_T_LINK
1394 |  */
1395 | 
1396 | static inline void
1397 | lsab_put_prefix(struct ospf_proto *p, net_addr *n, u32 cost)
1398 | {
1399 |   void *buf = lsab_alloc(p, IPV6_PREFIX_SPACE(net_pxlen(n)));
1400 |   uint max = (n->type == NET_IP4) ? IP4_MAX_PREFIX_LENGTH : IP6_MAX_PREFIX_LENGTH;
1401 |   u8 flags = (net_pxlen(n) < max) ? 0 : OPT_PX_LA;
1402 |   ospf3_put_prefix(buf, n, flags, cost);
