1858 | 
1859 | static inline int breaks_minlsinterval(struct top_hash_entry *en)
1860 | { return en && (en->lsa.age < LSA_MAXAGE) && (lsa_inst_age(en) < MINLSINTERVAL); }
1861 | 
1862 | void
1863 | ospf_update_topology(struct ospf_proto *p)
1864 | {
1865 |   struct ospf_area *oa;
1866 |   struct ospf_iface *ifa;
1867 | 
1868 |   /* No LSA reorigination during GR recovery */
1869 |   if (p->gr_recovery)
1870 |     return;
1871 | 
1872 |   WALK_LIST(oa, p->area_list)
1873 |   {
1874 |     if (oa->update_rt_lsa)
1875 |     {
1876 |       /*
1877 |        * Generally, MinLSInterval is enforced in ospf_do_originate_lsa(), but
1878 |        * origination of (prefix) router LSA is a special case. We do not want to
1879 |        * prepare a new router LSA body and then postpone it in en->next_lsa_body
1880 |        * for later origination, because there are side effects (updates of
1881 |        * rt_pos_* and px_pos_* in ospf_iface structures) during that, which may
1882 |        * confuse routing table calculation if executed after LSA body
1883 |        * preparation but before final LSA origination (as rtcalc would use
1884 |        * current rt_pos_* indexes but the old router LSA body).
1885 |        *
1886 |        * Here, we ensure that MinLSInterval is observed and we do not even try
1887 |        * to originate these LSAs if it is not. Therefore, origination, when
1888 |        * requested, will succeed unless there is also a seqnum wrapping, which
1889 |        * is not a problem because in that case rtcalc is blocked by MaxAge.
1890 |        */
1891 | 
1892 |       if (breaks_minlsinterval(oa->rt) || breaks_minlsinterval(oa->pxr_lsa))
1893 | 	continue;
1894 | 
1895 |       ospf_originate_rt_lsa(p, oa);
1896 |       ospf_originate_prefix_rt_lsa(p, oa);
1897 |       // ospf_originate_ri_lsa(p, oa);
1898 |       oa->update_rt_lsa = 0;
1899 |     }
1900 |   }
1901 | 
1902 |   if (ospf_is_v3(p) && ospf_is_ip4(p))
1903 |     update_loopback_addr(p);
1904 | 
1905 |   WALK_LIST(ifa, p->iface_list)
1906 |   {
1907 |     if (ifa->type == OSPF_IT_VLINK)
1908 |       continue;
1909 | 
1910 |     if (ifa->update_link_lsa)
1911 |     {
1912 |       ifa->loopback_addr_used = 0;
1913 | 
1914 |       if ((ifa->state > OSPF_IS_LOOP) && !ifa->link_lsa_suppression)
1915 | 	ospf_originate_link_lsa(p, ifa);
1916 |       else
1917 | 	ospf_flush2_lsa(p, &ifa->link_lsa);
1918 | 
1919 |       ifa->update_link_lsa = 0;
1920 |     }
1921 | 
1922 |     if (ifa->update_net_lsa)
1923 |     {
1924 |       if ((ifa->state == OSPF_IS_DR) && (ifa->fadj > 0))
1925 |       {
1926 | 	ospf_originate_net_lsa(p, ifa);
1927 | 	ospf_originate_prefix_net_lsa(p, ifa);
1928 |       }
1929 |       else
1930 |       {
1931 | 	ospf_flush2_lsa(p, &ifa->net_lsa);
1932 | 	ospf_flush2_lsa(p, &ifa->pxn_lsa);
1933 |       }
1934 | 
1935 |       ifa->update_net_lsa = 0;
1936 |     }
1937 |   }
1938 | }
