 762 | static void
 763 | prepare_rt2_lsa_body(struct ospf_proto *p, struct ospf_area *oa)
 764 | {
 765 |   struct ospf_iface *ifa;
 766 |   int i = 0, bitv = 0;
 767 |   struct ospf_neighbor *neigh;
 768 | 
 769 |   ASSERT(p->lsab_used == 0);
 770 |   lsab_allocz(p, sizeof(struct ospf_lsa_rt));
 771 |   /* ospf_lsa_rt header will be filled later */
 772 | 
 773 |   WALK_LIST(ifa, p->iface_list)
 774 |   {
 775 |     int net_lsa = 0;
 776 |     u32 link_cost = p->stub_router ? 0xffff : ifa->cost;
 777 | 
 778 |     if ((ifa->type == OSPF_IT_VLINK) && (ifa->voa == oa) &&
 779 | 	(!EMPTY_LIST(ifa->neigh_list)))
 780 |     {
 781 |       neigh = (struct ospf_neighbor *) HEAD(ifa->neigh_list);
 782 |       if ((neigh->state == NEIGHBOR_FULL) && (ifa->cost <= 0xffff))
 783 | 	bitv = 1;
 784 |     }
 785 | 
 786 |     if ((ifa->oa != oa) || (ifa->state == OSPF_IS_DOWN))
 787 |       continue;
 788 | 
 789 |     ifa->rt_pos_beg = i;
 790 | 
 791 |     /* RFC 2328 - 12.4.1.1-4 */
 792 |     switch (ifa->type)
 793 |     {
 794 |     case OSPF_IT_PTP:
 795 |     case OSPF_IT_PTMP:
 796 |       WALK_LIST(neigh, ifa->neigh_list)
 797 | 	if (neigh->state == NEIGHBOR_FULL)
 798 | 	{
 799 | 	  /*
 800 | 	   * ln->data field should be ifa->iface_id for unnumbered PtP links,
 801 | 	   * IP address otherwise (see RFC 2328 12.4.1.1). This is controlled
 802 | 	   * by ifa->ptp_address field.
 803 | 	   */
 804 | 	  add_rt2_lsa_link(p, LSART_PTP, neigh->rid, ospf_iface_get_data(ifa), link_cost);
 805 | 	  i++;
 806 | 	}
 807 |       break;
 808 | 
 809 |     case OSPF_IT_BCAST:
 810 |     case OSPF_IT_NBMA:
 811 |       if (bcast_net_active(ifa))
 812 |       {
 813 | 	add_rt2_lsa_link(p, LSART_NET, ipa_to_u32(ifa->drip), ipa_to_u32(ifa->addr->ip), link_cost);
 814 | 	i++;
 815 | 	net_lsa = 1;
 816 |       }
 817 |       break;
 818 | 
 819 |     case OSPF_IT_VLINK:
 820 |       neigh = (struct ospf_neighbor *) HEAD(ifa->neigh_list);
 821 |       if ((!EMPTY_LIST(ifa->neigh_list)) && (neigh->state == NEIGHBOR_FULL) && (ifa->cost <= 0xffff))
 822 | 	add_rt2_lsa_link(p, LSART_VLNK, neigh->rid, ipa_to_u32(ifa->addr->ip), link_cost), i++;
 823 |       break;
 824 | 
 825 |     default:
 826 |       log(L_BUG "OSPF: Unknown interface type");
 827 |       break;
 828 |     }
 829 | 
 830 |     ifa->rt_pos_end = i;
 831 | 
 832 |     /* Now we will originate stub area if there is no primary */
 833 |     if (net_lsa ||
 834 | 	(ifa->type == OSPF_IT_VLINK) ||
 835 | 	((ifa->addr->flags & IA_PEER) && ! ifa->cf->stub) ||
 836 | 	configured_stubnet(oa, ifa->addr))
 837 |       continue;
 838 | 
 839 |       /* Host or network stub entry */
 840 |     if ((ifa->addr->flags & IA_HOST) ||
 841 | 	(ifa->state == OSPF_IS_LOOP) ||
 842 | 	(ifa->type == OSPF_IT_PTMP))
 843 |       add_rt2_lsa_link(p, LSART_STUB, ipa_to_u32(ifa->addr->ip), 0xffffffff, 0);
 844 |     else
 845 |       add_rt2_lsa_link(p, LSART_STUB, ip4_to_u32(net4_prefix(&ifa->addr->prefix)),
 846 | 		       u32_mkmask(net4_pxlen(&ifa->addr->prefix)), ifa->cost);
 847 |     i++;
 848 | 
 849 |     ifa->rt_pos_end = i;
 850 |   }
 851 | 
 852 |   struct ospf_stubnet_config *sn;
 853 |   WALK_LIST(sn, oa->ac->stubnet_list)
 854 |     if (!sn->hidden)
 855 |       add_rt2_lsa_link(p, LSART_STUB, ip4_to_u32(net4_prefix(&sn->prefix)),
 856 | 		       u32_mkmask(net4_pxlen(&sn->prefix)), sn->cost), i++;
 857 | 
 858 |   struct ospf_lsa_rt *rt = p->lsab;
 859 |   /* Store number of links in lower half of options */
 860 |   rt->options = get_rt_options(p, oa, bitv) | (u16) i;
 861 | }
