1639 | /*
1640 |  *	Prefix-Net-LSA handling (assume OSPFv3)
1641 |  *	Type = LSA_T_PREFIX, referred type = LSA_T_NET
1642 |  */
1643 | 
1644 | static inline int
1645 | prefix_space(u32 *buf)
1646 | {
1647 |   int pxl = *buf >> 24;
1648 |   return IPV6_PREFIX_SPACE(pxl);
1649 | }
1650 | 
1651 | static inline int
1652 | prefix_same(u32 *b1, u32 *b2)
1653 | {
1654 |   int pxl1 = *b1 >> 24;
1655 |   int pxl2 = *b2 >> 24;
1656 |   int pxs, i;
1657 | 
1658 |   if (pxl1 != pxl2)
1659 |     return 0;
1660 | 
1661 |   pxs = IPV6_PREFIX_WORDS(pxl1);
1662 |   for (i = 1; i < pxs; i++)
1663 |     if (b1[i] != b2[i])
1664 |       return 0;
1665 | 
1666 |   return 1;
1667 | }
1668 | 
1669 | static inline u32 *
1670 | prefix_advance(u32 *buf)
1671 | {
1672 |   int pxl = *buf >> 24;
1673 |   return buf + IPV6_PREFIX_WORDS(pxl);
1674 | }
1675 | 
1676 | /* FIXME eliminate items with LA bit set? see 4.4.3.9 */
1677 | static void
1678 | add_prefix(struct ospf_proto *p, u32 *px, int offset, int *pxc)
1679 | {
1680 |   u32 *pxl = lsab_offset(p, offset);
1681 |   int i;
1682 |   for (i = 0; i < *pxc; pxl = prefix_advance(pxl), i++)
1683 |     if (prefix_same(px, pxl))
1684 |     {
1685 |       /* Options should be logically OR'ed together */
1686 |       *pxl |= (*px & 0x00FF0000);
1687 |       return;
1688 |     }
1689 | 
1690 |   ASSERT(pxl == lsab_end(p));
1691 | 
1692 |   int pxspace = prefix_space(px);
1693 |   pxl = lsab_alloc(p, pxspace);
1694 |   memcpy(pxl, px, pxspace);
1695 |   *pxl &= 0xFFFF0000;	/* Set metric to zero */
1696 |   (*pxc)++;
1697 | }
1698 | 
1699 | static void
1700 | add_link_lsa(struct ospf_proto *p, struct ospf_lsa_link *ll, int offset, int *pxc)
1701 | {
1702 |   u32 *pxb = ll->rest;
1703 |   uint j;
1704 | 
1705 |   for (j = 0; j < ll->pxcount; pxb = prefix_advance(pxb), j++)
1706 |   {
1707 |     u8 pxlen = (pxb[0] >> 24);
1708 |     u8 pxopts = (pxb[0] >> 16);
1709 | 
1710 |     /* Skip NU or LA prefixes */
1711 |     if (pxopts & (OPT_PX_NU | OPT_PX_LA))
1712 |       continue;
1713 | 
1714 |     /* Skip link-local prefixes */
1715 |     if (ospf_is_ip6(p) && (pxlen >= 10) && ((pxb[1] & 0xffc00000) == 0xfe800000))
1716 |       continue;
1717 | 
1718 |     add_prefix(p, pxb, offset, pxc);
1719 |   }
1720 | }
