1941 | static void
1942 | ospf_top_ht_alloc(struct top_graph *f)
1943 | {
1944 |   f->hash_size = 1 << f->hash_order;
1945 |   f->hash_mask = f->hash_size - 1;
1946 |   if (f->hash_order > HASH_HI_MAX - HASH_HI_STEP)
1947 |     f->hash_entries_max = ~0;
1948 |   else
1949 |     f->hash_entries_max = f->hash_size HASH_HI_MARK;
1950 |   if (f->hash_order < HASH_LO_MIN + HASH_LO_STEP)
1951 |     f->hash_entries_min = 0;
1952 |   else
1953 |     f->hash_entries_min = f->hash_size HASH_LO_MARK;
1954 |   DBG("Allocating OSPF hash of order %d: %d hash_entries, %d low, %d high\n",
1955 |       f->hash_order, f->hash_size, f->hash_entries_min, f->hash_entries_max);
1956 |   f->hash_table =
1957 |     mb_alloc(f->pool, f->hash_size * sizeof(struct top_hash_entry *));
1958 |   bzero(f->hash_table, f->hash_size * sizeof(struct top_hash_entry *));
1959 | }
1960 | 
1961 | static inline void
1962 | ospf_top_ht_free(struct top_hash_entry **h)
1963 | {
1964 |   mb_free(h);
1965 | }
1966 | 
1967 | static inline u32
1968 | ospf_top_hash_u32(u32 a)
1969 | {
1970 |   /* Shamelessly stolen from IP address hashing in ipv4.h */
1971 |   a ^= a >> 16;
1972 |   a ^= a << 10;
1973 |   return a;
1974 | }
1975 | 
1976 | static uint
1977 | ospf_top_hash(struct top_graph *f, u32 domain, u32 lsaid, u32 rtrid, u32 type)
1978 | {
1979 |   /* In OSPFv2, we don't know Router ID when looking for network LSAs.
1980 |      In OSPFv3, we don't know LSA ID when looking for router LSAs.
1981 |      In both cases, there is (usually) just one (or small number)
1982 |      appropriate LSA, so we just clear unknown part of key. */
1983 | 
1984 |   return (((f->ospf2 && (type == LSA_T_NET)) ? 0 : ospf_top_hash_u32(rtrid)) +
1985 | 	  ((!f->ospf2 && (type == LSA_T_RT)) ? 0 : ospf_top_hash_u32(lsaid)) +
1986 | 	  type + domain) & f->hash_mask;
1987 | 
1988 |   /*
1989 |   return (ospf_top_hash_u32(lsaid) + ospf_top_hash_u32(rtrid) +
1990 | 	  type + areaid) & f->hash_mask;
1991 |   */
1992 | }
