 735 | 
 736 |   if (p->areano > 1)
 737 |     opts |= OPT_RT_B;
 738 | 
 739 |   if ((p->areano > 1) && oa_is_nssa(oa) && oa->ac->translator)
 740 |     opts |= OPT_RT_NT;
 741 | 
 742 |   if (p->asbr && !oa_is_stub(oa))
 743 |     opts |= OPT_RT_E;
 744 | 
 745 |   if (bitv)
 746 |     opts |= OPT_RT_V;
 747 | 
 748 |   return opts;
