1215 | static struct top_hash_entry *
1216 | ospf_hash_find_(struct top_graph *f, u32 domain, u32 lsa, u32 rtr, u32 type);
1217 | 
1218 | static void
1219 | ospf_flush_ext_lsa(struct ospf_proto *p, struct ospf_area *oa, ort *nf)
1220 | {
1221 |   struct top_hash_entry *en;
1222 | 
1223 |   u32 type = oa ? LSA_T_NSSA : LSA_T_EXT;
1224 |   u32 dom = oa ? oa->areaid : 0;
1225 |   u32 id = ort_to_lsaid(p, nf);
1226 | 
1227 |   en = ospf_hash_find_(p->gr, dom, id, p->router_id, type);
1228 | 
1229 |   if (!en || (en->nf != nf))
1230 |     return;
1231 | 
1232 |   ospf_flush_lsa(p, en);
1233 | }
