1235 | static inline int
1236 | use_gw_for_fwaddr(struct ospf_proto *p, ip_addr gw, struct iface *iface)
1237 | {
1238 |   struct ospf_iface *ifa;
1239 | 
1240 |   if (ipa_zero(gw) || ipa_is_link_local(gw))
1241 |     return 0;
1242 | 
1243 |   WALK_LIST(ifa, p->iface_list)
1244 |     if ((ifa->iface == iface) &&
1245 | 	(!ospf_is_v2(p) || ipa_in_netX(gw, &ifa->addr->prefix)))
1246 |       return 1;
1247 | 
1248 |   return 0;
1249 | }
1250 | 
1251 | static inline ip_addr
1252 | find_surrogate_fwaddr(struct ospf_proto *p, struct ospf_area *oa)
1253 | {
1254 |   struct ospf_iface *ifa;
1255 |   struct ifa *a, *cur_addr = NULL;
1256 |   int np, cur_np = 0;
1257 | 
1258 |   /* RFC 3101 2.3 - surrogate forwarding address selection */
1259 | 
1260 |   WALK_LIST(ifa, p->iface_list)
1261 |   {
1262 |     if ((ifa->oa != oa) ||
1263 | 	(ifa->type == OSPF_IT_VLINK))
1264 |       continue;
1265 | 
1266 |     if (ospf_is_v2(p))
1267 |     {
1268 |       a = ifa->addr;
1269 |       if (a->flags & IA_PEER)
1270 | 	continue;
1271 | 
1272 |       np = (a->flags & IA_HOST) ? 3 : (ifa->stub ? 2 : 1);
1273 |       if (np > cur_np)
1274 |       {
1275 | 	cur_addr = a;
1276 | 	cur_np = np;
1277 |       }
1278 |     }
1279 |     else /* OSPFv3 */
1280 |     {
1281 |       WALK_LIST(a, ifa->iface->addrs)
1282 |       {
1283 | 	if ((a->prefix.type != ospf_get_af(p)) ||
1284 | 	    (a->flags & IA_SECONDARY) ||
1285 | 	    (a->flags & IA_PEER) ||
1286 | 	    (a->scope <= SCOPE_LINK))
1287 | 	  continue;
1288 | 
1289 | 	np = (a->flags & IA_HOST) ? 3 : (ifa->stub ? 2 : 1);
1290 | 	if (np > cur_np)
1291 | 	{
1292 | 	  cur_addr = a;
1293 | 	  cur_np = np;
1294 | 	}
1295 |       }
1296 |     }
1297 |   }
1298 | 
1299 |   return cur_addr ? cur_addr->ip : IPA_NONE;
1300 | }
1301 | 
1302 | void
1303 | ospf_rt_notify(struct proto *P, struct channel *ch UNUSED, net *n, rte *new, rte *old UNUSED)
1304 | {
1305 |   struct ospf_proto *p = (struct ospf_proto *) P;
1306 |   struct ospf_area *oa = NULL;	/* non-NULL for NSSA-LSA */
1307 |   ort *nf;
1308 | 
1309 |   /*
1310 |    * There are several posibilities:
1311 |    * 1) router in regular area - originate external LSA with global scope
1312 |    * 2) router in NSSA area - originate area-specific NSSA-LSA
1313 |    * 3) router in stub area - cannot export routes
1314 |    * 4) area border router - same as (1), it is attached to backbone
1315 |    */
1316 | 
1317 |   if ((p->areano == 1) && oa_is_nssa(HEAD(p->area_list)))
1318 |     oa = HEAD(p->area_list);
1319 | 
1320 |   if (!new)
1321 |   {
1322 |     nf = fib_find(&p->rtf, n->n.addr);
1323 | 
1324 |     if (!nf || !nf->external_rte)
1325 |       return;
1326 | 
1327 |     ospf_flush_ext_lsa(p, oa, nf);
1328 |     nf->external_rte = 0;
1329 | 
1330 |     /* Old external route might blocked some NSSA translation */
1331 |     if ((p->areano > 1) && rt_is_nssa(nf) && nf->n.oa->translate)
1332 |       ospf_schedule_rtcalc(p);
1333 | 
1334 |     return;
1335 |   }
1336 | 
1337 |   ASSERT(p->asbr);
1338 | 
1339 |   /* Get route attributes */
1340 |   rta *a = new->attrs;
1341 |   eattr *m1a = ea_find(a->eattrs, EA_OSPF_METRIC1);
1342 |   eattr *m2a = ea_find(a->eattrs, EA_OSPF_METRIC2);
1343 |   uint m1 = m1a ? m1a->u.data : 0;
1344 |   uint m2 = m2a ? m2a->u.data : 10000;
1345 | 
1346 |   if (m1 > LSINFINITY)
1347 |   {
1348 |     log(L_WARN "%s: Invalid ospf_metric1 value %u for route %N",
1349 | 	p->p.name, m1, n->n.addr);
1350 |     m1 = LSINFINITY;
1351 |   }
1352 | 
1353 |   if (m2 > LSINFINITY)
1354 |   {
1355 |     log(L_WARN "%s: Invalid ospf_metric2 value %u for route %N",
1356 | 	p->p.name, m2, n->n.addr);
1357 |     m2 = LSINFINITY;
1358 |   }
1359 | 
1360 |   /* Ensure monotonicity of metric if both m1 and m2 are used */
1361 |   if ((m1 > 0) && (m2 < LSINFINITY))
1362 |     m2++;
1363 | 
1364 |   uint ebit = m2a || !m1a;
1365 |   uint metric = ebit ? m2 : m1;
1366 |   uint tag = ea_get_int(a->eattrs, EA_OSPF_TAG, 0);
1367 | 
1368 |   ip_addr fwd = IPA_NONE;
1369 |   if ((a->dest == RTD_UNICAST) && use_gw_for_fwaddr(p, a->nh.gw, a->nh.iface))
1370 |     fwd = a->nh.gw;
1371 | 
1372 |   /* NSSA-LSA with P-bit set must have non-zero forwarding address */
1373 |   if (oa && ipa_zero(fwd))
1374 |   {
1375 |     fwd = find_surrogate_fwaddr(p, oa);
1376 | 
1377 |     if (ipa_zero(fwd))
1378 |     {
1379 |       log(L_ERR "%s: Cannot find forwarding address for NSSA-LSA %N",
1380 | 	  p->p.name, n->n.addr);
1381 |       return;
1382 |     }
1383 |   }
1384 | 
1385 |   nf = fib_get(&p->rtf, n->n.addr);
1386 |   ospf_originate_ext_lsa(p, oa, nf, LSA_M_EXPORT, metric, ebit, fwd, tag, 1, p->vpn_pe);
1387 |   nf->external_rte = 1;
1388 | }
