1510 | /*
1511 |  *	Prefix-Rt-LSA handling (assume OSPFv3)
1512 |  *	Type = LSA_T_PREFIX, referred type = LSA_T_RT
1513 |  */
1514 | 
1515 | static void
1516 | prepare_prefix_rt_lsa_body(struct ospf_proto *p, struct ospf_area *oa)
1517 | {
1518 |   struct ospf_config *cf = (struct ospf_config *) (p->p.cf);
1519 |   struct ospf_iface *ifa;
1520 |   struct ospf_lsa_prefix *lp;
1521 |   uint max = ospf_is_ip4(p) ? IP4_MAX_PREFIX_LENGTH : IP6_MAX_PREFIX_LENGTH;
1522 |   int host_addr = 0;
1523 |   int net_lsa;
1524 |   int i = 0;
1525 | 
1526 |   ASSERT(p->lsab_used == 0);
1527 |   lp = lsab_allocz(p, sizeof(struct ospf_lsa_prefix));
1528 |   lp->ref_type = LSA_T_RT;
1529 |   lp->ref_id = 0;
1530 |   lp->ref_rt = p->router_id;
1531 |   lp = NULL; /* buffer might be reallocated later */
1532 | 
1533 |   WALK_LIST(ifa, p->iface_list)
1534 |   {
1535 |     if ((ifa->oa != oa) || (ifa->type == OSPF_IT_VLINK) || (ifa->state == OSPF_IS_DOWN))
1536 |       continue;
1537 | 
1538 |     ifa->px_pos_beg = i;
1539 | 
1540 |     if ((ifa->type == OSPF_IT_BCAST) ||
1541 | 	(ifa->type == OSPF_IT_NBMA))
1542 |       net_lsa = bcast_net_active(ifa);
1543 |     else
1544 |       net_lsa = 0;
1545 | 
1546 |     struct ifa *a;
1547 |     WALK_LIST(a, ifa->iface->addrs)
1548 |     {
1549 |       if ((a->prefix.type != ospf_get_af(p)) ||
1550 | 	  (a->flags & IA_SECONDARY) ||
1551 | 	  (a->flags & IA_PEER) ||
1552 | 	  (a->scope <= SCOPE_LINK))
1553 | 	continue;
1554 | 
1555 |       if (((a->prefix.pxlen < max) && net_lsa) ||
1556 | 	  configured_stubnet(oa, a))
1557 | 	continue;
1558 | 
1559 |       if ((a->flags & IA_HOST) ||
1560 | 	  (ifa->state == OSPF_IS_LOOP) ||
1561 | 	  (ifa->type == OSPF_IT_PTMP))
1562 |       {
1563 | 	net_addr net;
1564 | 	if (a->prefix.type == NET_IP4)
1565 | 	  net_fill_ip4(&net, ipa_to_ip4(a->ip), IP4_MAX_PREFIX_LENGTH);
1566 | 	else
1567 | 	  net_fill_ip6(&net, ipa_to_ip6(a->ip), IP6_MAX_PREFIX_LENGTH);
1568 | 
1569 | 	lsab_put_prefix(p, &net, 0);
1570 | 	host_addr = 1;
1571 |       }
1572 |       else
1573 | 	lsab_put_prefix(p, &a->prefix, ifa->cost);
1574 |       i++;
1575 |     }
1576 | 
1577 |     ifa->px_pos_end = i;
1578 |   }
1579 | 
1580 |   struct ospf_stubnet_config *sn;
1581 |   WALK_LIST(sn, oa->ac->stubnet_list)
1582 |     if (!sn->hidden)
1583 |     {
1584 |       lsab_put_prefix(p, &sn->prefix, sn->cost);
1585 |       if (sn->prefix.pxlen == max)
1586 | 	host_addr = 1;
1587 |       i++;
1588 |     }
1589 | 
1590 |   /* If there are some configured vlinks, find some global address
1591 |      (even from another area), which will be used as a vlink endpoint. */
1592 |   if (!EMPTY_LIST(cf->vlink_list) && !host_addr && ospf_is_ip6(p))
1593 |   {
1594 |     WALK_LIST(ifa, p->iface_list)
1595 |     {
1596 |       if ((ifa->type == OSPF_IT_VLINK) || (ifa->state == OSPF_IS_DOWN))
1597 | 	continue;
1598 | 
1599 |       struct ifa *a;
1600 |       WALK_LIST(a, ifa->iface->addrs)
1601 |       {
1602 | 	if ((a->prefix.type != NET_IP6) ||
1603 | 	    (a->flags & IA_SECONDARY) ||
1604 | 	    (a->scope <= SCOPE_LINK))
1605 | 	  continue;
1606 | 
1607 | 	/* Found some IP */
1608 | 	net_addr_ip6 net = NET_ADDR_IP6(a->ip, IP6_MAX_PREFIX_LENGTH);
1609 | 	lsab_put_prefix(p, (net_addr *) &net, 0);
1610 | 	i++;
1611 | 	goto done;
1612 |       }
1613 |     }
1614 |   }
1615 | 
1616 |  done:
1617 |   lp = p->lsab;
1618 |   lp->pxcount = i;
1619 | }
