 696 | 	return 1;
 697 |     }
 698 |     else
 699 |     {
 700 |       if (net_equal(&a->prefix, &sn->prefix))
 701 | 	return 1;
 702 |     }
 703 |   }
 704 | 
 705 |   return 0;
