 736 |   if (p->areano > 1)
 737 |     opts |= OPT_RT_B;
 738 | 
 739 |   if ((p->areano > 1) && oa_is_nssa(oa) && oa->ac->translator)
 740 |     opts |= OPT_RT_NT;
