1027 |     .dom  = ifa->oa->areaid,
1028 |     .id   = ospf_is_v2(p) ? ipa_to_u32(ifa->addr->ip) : ifa->iface_id,
1029 |     .opts = ifa->oa->options,
1030 |     .ifa  = ifa
1031 |   };
