 692 |   {
 693 |     if (sn->summary)
 694 |     {
 695 |       if (net_in_netX(&a->prefix, &sn->prefix))
 696 | 	return 1;
 697 |     }
 698 |     else
 699 |     {
 700 |       if (net_equal(&a->prefix, &sn->prefix))
 701 | 	return 1;
 702 |     }
 703 |   }
