2056 | static struct top_hash_entry *
2057 | ospf_hash_find_(struct top_graph *f, u32 domain, u32 lsa, u32 rtr, u32 type)
2058 | {
2059 |   struct top_hash_entry *e;
2060 |   e = f->hash_table[ospf_top_hash(f, domain, lsa, rtr, type)];
2061 | 
2062 |   while (e && (e->lsa.id != lsa || e->lsa.rt != rtr ||
2063 | 	       e->lsa_type != type || e->domain != domain))
2064 |     e = e->next;
2065 | 
2066 |   return e;
2067 | }
