 34 | static inline void
 35 | random_data(void *p, uint len)
 36 | {
 37 |   uint ints = (len + sizeof(int) - 1) / sizeof(int);
 38 |   int *d = alloca(sizeof(uint) * ints);
 39 |   for (uint i=0; i<ints; i++)
 40 |     d[i] = random();
 41 | 
 42 |   memcpy(p, d, len);
 43 | }
