  1 | /*
  2 |  *	BIRD -- Table-to-Table Routing Protocol a.k.a Pipe
  3 |  *
  4 |  *	(c) 1999--2000 Martin Mares <mj@ucw.cz>
  5 |  *
  6 |  *	Can be freely distributed and used under the terms of the GNU GPL.
  7 |  */
  8 | 
  9 | /**
 10 |  * DOC: Pipe
 11 |  *
 12 |  * The Pipe protocol is very simple. It just connects to two routing tables
 13 |  * using proto_add_announce_hook() and whenever it receives a rt_notify()
 14 |  * about a change in one of the tables, it converts it to a rte_update()
 15 |  * in the other one.
 16 |  *
 17 |  * To avoid pipe loops, Pipe keeps a `being updated' flag in each routing
 18 |  * table.
 19 |  *
 20 |  * A pipe has two announce hooks, the first connected to the main
 21 |  * table, the second connected to the peer table. When a new route is
 22 |  * announced on the main table, it gets checked by an export filter in
 23 |  * ahook 1, and, after that, it is announced to the peer table via
 24 |  * rte_update(), an import filter in ahook 2 is called. When a new
 25 |  * route is announced in the peer table, an export filter in ahook2
 26 |  * and an import filter in ahook 1 are used. Oviously, there is no
 27 |  * need in filtering the same route twice, so both import filters are
 28 |  * set to accept, while user configured 'import' and 'export' filters
 29 |  * are used as export filters in ahooks 2 and 1. Route limits are
 30 |  * handled similarly, but on the import side of ahooks.
 31 |  */
 32 | 
 33 | #undef LOCAL_DEBUG
 34 | 
 35 | #include "nest/bird.h"
 36 | #include "nest/iface.h"
 37 | #include "nest/protocol.h"
 38 | #include "nest/route.h"
 39 | #include "nest/cli.h"
 40 | #include "conf/conf.h"
 41 | #include "filter/filter.h"
 42 | #include "lib/string.h"
 43 | 
 44 | #include "pipe.h"
 45 | 
 46 | static void
 47 | pipe_rt_notify(struct proto *P, struct channel *src_ch, net *n, rte *new, rte *old)
 48 | {
 49 |   struct pipe_proto *p = (void *) P;
 50 |   struct channel *dst = (src_ch == p->pri) ? p->sec : p->pri;
 51 |   struct rte_src *src;
 52 | 
 53 |   rte *e;
 54 |   rta *a;
 55 | 
 56 |   if (!new && !old)
 57 |     return;
 58 | 
 59 |   if (dst->table->pipe_busy)
 60 |     {
 61 |       log(L_ERR "Pipe loop detected when sending %N to table %s",
 62 | 	  n->n.addr, dst->table->name);
 63 |       return;
 64 |     }
 65 | 
 66 |   if (new)
 67 |     {
 68 |       src = new->src;
 69 | 
 70 |       a = alloca(rta_size(new->attrs));
 71 |       memcpy(a, new->attrs, rta_size(new->attrs));
 72 | 
 73 |       a->cached = 0;
 74 |       a->hostentry = NULL;
 75 |       e = rte_get_temp(a, src);
 76 |     }
 77 |   else
 78 |     {
 79 |       e = NULL;
 80 |       src = old->src;
 81 |     }
 82 | 
 83 |   src_ch->table->pipe_busy = 1;
 84 |   rte_update2(dst, n->n.addr, e, src);
 85 |   src_ch->table->pipe_busy = 0;
 86 | }
 87 | 
 88 | static int
 89 | pipe_preexport(struct channel *C, rte *e)
 90 | {
 91 |   struct proto *pp = e->sender->proto;
 92 | 
 93 |   if (pp == C->proto)
 94 |     return -1;	/* Avoid local loops automatically */
 95 | 
 96 |   return 0;
 97 | }
 98 | 
 99 | static void
100 | pipe_reload_routes(struct channel *C)
101 | {
102 |   struct pipe_proto *p = (void *) C->proto;
103 | 
104 |   /* Route reload on one channel is just refeed on the other */
105 |   channel_request_feeding((C == p->pri) ? p->sec : p->pri);
106 | }
107 | 
108 | 
109 | static void
110 | pipe_postconfig(struct proto_config *CF)
111 | {
112 |   struct pipe_config *cf = (void *) CF;
113 |   struct channel_config *cc = proto_cf_main_channel(CF);
114 | 
115 |   if (!cc->table)
116 |     cf_error("Primary routing table not specified");
117 | 
118 |   if (!cf->peer)
119 |     cf_error("Secondary routing table not specified");
120 | 
121 |   if (cc->table == cf->peer)
122 |     cf_error("Primary table and peer table must be different");
123 | 
124 |   if (cc->table->addr_type != cf->peer->addr_type)
125 |     cf_error("Primary table and peer table must have the same type");
126 | 
127 |   if (cc->rx_limit.action)
128 |     cf_error("Pipe protocol does not support receive limits");
129 | 
130 |   if (cc->in_keep_filtered)
131 |     cf_error("Pipe protocol prohibits keeping filtered routes");
132 | 
133 |   cc->debug = cf->c.debug;
134 | }
135 | 
136 | static int
137 | pipe_configure_channels(struct pipe_proto *p, struct pipe_config *cf)
138 | {
139 |   struct channel_config *cc = proto_cf_main_channel(&cf->c);
140 | 
141 |   struct channel_config pri_cf = {
142 |     .name = "pri",
143 |     .channel = cc->channel,
144 |     .table = cc->table,
145 |     .out_filter = cc->out_filter,
146 |     .in_limit = cc->in_limit,
147 |     .ra_mode = RA_ANY,
148 |     .debug = cc->debug,
149 |     .rpki_reload = cc->rpki_reload,
150 |   };
151 | 
152 |   struct channel_config sec_cf = {
153 |     .name = "sec",
154 |     .channel = cc->channel,
155 |     .table = cf->peer,
156 |     .out_filter = cc->in_filter,
157 |     .in_limit = cc->out_limit,
158 |     .ra_mode = RA_ANY,
159 |     .debug = cc->debug,
160 |     .rpki_reload = cc->rpki_reload,
161 |   };
162 | 
163 |   return
164 |     proto_configure_channel(&p->p, &p->pri, &pri_cf) &&
165 |     proto_configure_channel(&p->p, &p->sec, &sec_cf);
166 | }
167 | 
168 | static struct proto *
169 | pipe_init(struct proto_config *CF)
170 | {
171 |   struct proto *P = proto_new(CF);
172 |   struct pipe_proto *p = (void *) P;
173 |   struct pipe_config *cf = (void *) CF;
174 | 
175 |   P->rt_notify = pipe_rt_notify;
176 |   P->preexport = pipe_preexport;
177 |   P->reload_routes = pipe_reload_routes;
178 | 
179 |   pipe_configure_channels(p, cf);
180 | 
181 |   return P;
182 | }
183 | 
184 | static int
185 | pipe_reconfigure(struct proto *P, struct proto_config *CF)
186 | {
187 |   struct pipe_proto *p = (void *) P;
188 |   struct pipe_config *cf = (void *) CF;
189 | 
190 |   return pipe_configure_channels(p, cf);
191 | }
192 | 
193 | static void
194 | pipe_copy_config(struct proto_config *dest UNUSED, struct proto_config *src UNUSED)
195 | {
196 |   /* Just a shallow copy, not many items here */
197 | }
198 | 
199 | static void
200 | pipe_get_status(struct proto *P, byte *buf)
201 | {
202 |   struct pipe_proto *p = (void *) P;
203 | 
204 |   bsprintf(buf, "%s <=> %s", p->pri->table->name, p->sec->table->name);
205 | }
206 | 
207 | static void
208 | pipe_show_stats(struct pipe_proto *p)
209 | {
210 |   struct proto_stats *s1 = &p->pri->stats;
211 |   struct proto_stats *s2 = &p->sec->stats;
212 | 
213 |   /*
214 |    * Pipe stats (as anything related to pipes) are a bit tricky. There
215 |    * are two sets of stats - s1 for ahook to the primary routing and
216 |    * s2 for the ahook to the secondary routing table. The user point
217 |    * of view is that routes going from the primary routing table to
218 |    * the secondary routing table are 'exported', while routes going in
219 |    * the other direction are 'imported'.
220 |    *
221 |    * Each route going through a pipe is, technically, first exported
222 |    * to the pipe and then imported from that pipe and such operations
223 |    * are counted in one set of stats according to the direction of the
224 |    * route propagation. Filtering is done just in the first part
225 |    * (export). Therefore, we compose stats for one directon for one
226 |    * user direction from both import and export stats, skipping
227 |    * immediate and irrelevant steps (exp_updates_accepted,
228 |    * imp_updates_received, imp_updates_filtered, ...).
229 |    *
230 |    * Rule of thumb is that stats s1 have the correct 'polarity'
231 |    * (imp/exp), while stats s2 have switched 'polarity'.
232 |    */
233 | 
234 |   cli_msg(-1006, "  Routes:         %u imported, %u exported",
235 | 	  s1->imp_routes, s2->imp_routes);
236 |   cli_msg(-1006, "  Route change stats:     received   rejected   filtered    ignored   accepted");
237 |   cli_msg(-1006, "    Import updates:     %10u %10u %10u %10u %10u",
238 | 	  s2->exp_updates_received, s2->exp_updates_rejected + s1->imp_updates_invalid,
239 | 	  s2->exp_updates_filtered, s1->imp_updates_ignored, s1->imp_updates_accepted);
240 |   cli_msg(-1006, "    Import withdraws:   %10u %10u        --- %10u %10u",
241 | 	  s2->exp_withdraws_received, s1->imp_withdraws_invalid,
242 | 	  s1->imp_withdraws_ignored, s1->imp_withdraws_accepted);
243 |   cli_msg(-1006, "    Export updates:     %10u %10u %10u %10u %10u",
244 | 	  s1->exp_updates_received, s1->exp_updates_rejected + s2->imp_updates_invalid,
245 | 	  s1->exp_updates_filtered, s2->imp_updates_ignored, s2->imp_updates_accepted);
246 |   cli_msg(-1006, "    Export withdraws:   %10u %10u        --- %10u %10u",
247 | 	  s1->exp_withdraws_received, s2->imp_withdraws_invalid,
248 | 	  s2->imp_withdraws_ignored, s2->imp_withdraws_accepted);
249 | }
