 35 | struct radv_opt_prefix
 36 | {
 37 |   u8 type;
 38 |   u8 length;
 39 |   u8 pxlen;
 40 |   u8 flags;
 41 |   u32 valid_lifetime;
 42 |   u32 preferred_lifetime;
 43 |   u32 reserved;
 44 |   ip6_addr prefix;
 45 | };
 46 | 
 47 | #define OPT_PX_ONLINK 0x80
 48 | #define OPT_PX_AUTONOMOUS 0x40
