 92 | static int
 93 | radv_prepare_route(struct radv_iface *ifa, struct radv_route *rt,
 94 | 		   char **buf, char *bufend)
 95 | {
 96 |   struct radv_proto *p = ifa->ra;
 97 |   u8 px_blocks = (net6_pxlen(rt->n.addr) + 63) / 64;
 98 |   u8 opt_len = 8 * (1 + px_blocks);
 99 | 
100 |   if (*buf + opt_len > bufend)
101 |   {
102 |     log(L_WARN, "%s: Too many RA options on interface %s",
103 | 	p->p.name, ifa->iface->name);
104 |     return -1;
105 |   }
106 | 
107 |   uint preference = rt->preference_set ? rt->preference : ifa->cf->route_preference;
108 |   uint lifetime = rt->lifetime_set ? rt->lifetime : ifa->cf->route_lifetime;
109 |   uint valid = rt->valid && p->valid && (p->active || !ifa->cf->route_lifetime_sensitive);
110 | 
111 |   struct radv_opt_route *opt = (void *) *buf;
112 |   *buf += opt_len;
113 |   opt->type = OPT_ROUTE;
114 |   opt->length = 1 + px_blocks;
115 |   opt->pxlen = net6_pxlen(rt->n.addr);
116 |   opt->flags = preference;
117 |   opt->lifetime = valid ? htonl(lifetime) : 0;
118 | 
119 |   /* Copy the relevant part of the prefix */
120 |   ip6_addr px_addr = ip6_hton(net6_prefix(rt->n.addr));
121 |   memcpy(opt->prefix, &px_addr, 8 * px_blocks);
122 | 
123 |   /* Keeping track of first linger timeout */
124 |   if (!rt->valid)
125 |     ifa->valid_time = MIN(ifa->valid_time, rt->changed + ifa->cf->route_linger_time S);
126 | 
127 |   return 0;
128 | }
129 | 
130 | static int
131 | radv_prepare_rdnss(struct radv_iface *ifa, list *rdnss_list, char **buf, char *bufend)
132 | {
133 |   struct radv_rdnss_config *rcf = HEAD(*rdnss_list);
134 | 
135 |   while(NODE_VALID(rcf))
136 |   {
137 |     struct radv_rdnss_config *rcf_base = rcf;
138 |     struct radv_opt_rdnss *op = (void *) *buf;
139 |     int max_i = (bufend - *buf - sizeof(struct radv_opt_rdnss)) / sizeof(ip6_addr);
140 |     int i = 0;
141 | 
142 |     if (max_i < 1)
143 |       goto too_much;
144 | 
145 |     op->type = OPT_RDNSS;
146 |     op->reserved = 0;
147 | 
148 |     if (rcf->lifetime_mult)
149 |       op->lifetime = htonl(rcf->lifetime_mult * ifa->cf->max_ra_int);
150 |     else
151 |       op->lifetime = htonl(rcf->lifetime);
152 | 
153 |     while(NODE_VALID(rcf) &&
154 | 	  (rcf->lifetime == rcf_base->lifetime) &&
155 | 	  (rcf->lifetime_mult == rcf_base->lifetime_mult))
156 |       {
157 | 	if (i >= max_i)
158 | 	  goto too_much;
159 | 
160 | 	op->servers[i] = ip6_hton(rcf->server);
161 | 	i++;
162 | 
163 | 	rcf = NODE_NEXT(rcf);
164 |       }
165 | 
166 |     op->length = 1+2*i;
167 |     *buf += 8 * op->length;
168 |   }
169 | 
170 |   return 0;
171 | 
172 |  too_much:
173 |   log(L_WARN "%s: Too many RA options on interface %s",
174 |       ifa->ra->p.name, ifa->iface->name);
175 |   return -1;
176 | }
177 | 
178 | int
179 | radv_process_domain(struct radv_dnssl_config *cf)
180 | {
181 |   /* Format of domain in search list is <size> <label> <size> <label> ... 0 */
182 | 
183 |   const char *dom = cf->domain;
184 |   const char *dom_end = dom; /* Just to  */
185 |   u8 *dlen_save = &cf->dlen_first;
186 |   uint len;
187 | 
188 |   while (dom_end)
189 |   {
190 |     dom_end = strchr(dom, '.');
191 |     len = dom_end ? (uint)(dom_end - dom) : strlen(dom);
192 | 
193 |     if (len < 1 || len > 63)
194 |       return -1;
195 | 
196 |     *dlen_save = len;
197 |     dlen_save = (u8 *) dom_end;
198 | 
199 |     dom += len + 1;
200 |   }
201 | 
202 |   len = dom - cf->domain;
203 |   if (len > 254)
204 |     return -1;
205 | 
206 |   cf->dlen_all = len;
207 | 
208 |   return 0;
209 | }
210 | 
211 | static int
212 | radv_prepare_dnssl(struct radv_iface *ifa, list *dnssl_list, char **buf, char *bufend)
213 | {
214 |   struct radv_dnssl_config *dcf = HEAD(*dnssl_list);
215 | 
216 |   while(NODE_VALID(dcf))
217 |   {
218 |     struct radv_dnssl_config *dcf_base = dcf;
219 |     struct radv_opt_dnssl *op = (void *) *buf;
220 |     int bsize = bufend - *buf - sizeof(struct radv_opt_dnssl);
221 |     int bpos = 0;
222 | 
223 |     if (bsize < 0)
224 |       goto too_much;
225 | 
226 |     bsize = bsize & ~7; /* Round down to multiples of 8 */
227 | 
228 |     op->type = OPT_DNSSL;
229 |     op->reserved = 0;
230 | 
231 |     if (dcf->lifetime_mult)
232 |       op->lifetime = htonl(dcf->lifetime_mult * ifa->cf->max_ra_int);
233 |     else
234 |       op->lifetime = htonl(dcf->lifetime);
235 | 
236 |     while(NODE_VALID(dcf) &&
237 | 	  (dcf->lifetime == dcf_base->lifetime) &&
238 | 	  (dcf->lifetime_mult == dcf_base->lifetime_mult))
239 |       {
240 | 	if (bpos + dcf->dlen_all + 1 > bsize)
241 | 	  goto too_much;
242 | 
243 | 	op->domain[bpos++] = dcf->dlen_first;
244 | 	memcpy(op->domain + bpos, dcf->domain, dcf->dlen_all);
245 | 	bpos += dcf->dlen_all;
246 | 
247 | 	dcf = NODE_NEXT(dcf);
248 |       }
249 | 
250 |     int blen = (bpos + 7) / 8;
251 |     bzero(op->domain + bpos, 8 * blen - bpos);
252 |     op->length = 1 + blen;
253 |     *buf += 8 * op->length;
254 |   }
255 | 
256 |   return 0;
257 | 
258 |  too_much:
259 |   log(L_WARN "%s: Too many RA options on interface %s",
260 |       ifa->ra->p.name, ifa->iface->name);
261 |   return -1;
262 | }
263 | 
264 | static int
265 | radv_prepare_custom(struct radv_iface *ifa, list *custom_list, char **buf, char *bufend)
266 | {
267 |   struct radv_custom_config *ccf;
268 |   WALK_LIST(ccf, *custom_list)
269 |   {
270 |     struct radv_opt_custom *op = (void *) *buf;
271 |     /* Add 2 octets for type and size and 8 - 1 for ceiling the division up to 8 octets */
272 |     int size = (ccf->payload->length + 2 + 8 - 1) / 8;
273 |     if (bufend - *buf < size * 8)
274 |       goto too_much;
275 | 
276 |     memset(op, 0, size * 8); /* Clear buffer so there is no tail garbage */
277 |     op->type = ccf->type;
278 |     op->length = size;
279 |     memcpy(op->payload, ccf->payload->data, ccf->payload->length);
280 | 
281 |     *buf += 8 * op->length;
282 |   }
283 | 
284 |   return 0;
285 | 
286 |  too_much:
287 |   log(L_WARN "%s: Too many RA options on interface %s",
288 |       ifa->ra->p.name, ifa->iface->name);
289 |   return -1;
290 | }
291 | 
292 | static int
293 | radv_prepare_prefix(struct radv_iface *ifa, struct radv_prefix *px,
294 | 		    char **buf, char *bufend)
295 | {
296 |   struct radv_prefix_config *pc = px->cf;
297 | 
298 |   if (*buf + sizeof(struct radv_opt_prefix) > bufend)
299 |   {
300 |     log(L_WARN "%s: Too many prefixes on interface %s",
301 | 	ifa->ra->p.name, ifa->iface->name);
302 |     return -1;
303 |   }
304 | 
305 |   struct radv_opt_prefix *op = (void *) *buf;
306 |   op->type = OPT_PREFIX;
307 |   op->length = 4;
308 |   op->pxlen = px->prefix.pxlen;
309 |   op->flags = (pc->onlink ? OPT_PX_ONLINK : 0) |
310 |     (pc->autonomous ? OPT_PX_AUTONOMOUS : 0);
311 |   op->valid_lifetime = (ifa->ra->active || !pc->valid_lifetime_sensitive) ?
312 |     htonl(pc->valid_lifetime) : 0;
313 |   op->preferred_lifetime = (ifa->ra->active || !pc->preferred_lifetime_sensitive) ?
314 |     htonl(pc->preferred_lifetime) : 0;
315 |   op->reserved = 0;
316 |   op->prefix = ip6_hton(px->prefix.prefix);
317 |   *buf += sizeof(*op);
318 | 
319 |   /* Keeping track of first linger timeout */
320 |   if (!px->valid)
321 |     ifa->valid_time = MIN(ifa->valid_time, px->changed + ifa->cf->prefix_linger_time S);
322 | 
323 |   return 0;
324 | }
325 | 
326 | static void
327 | radv_prepare_ra(struct radv_iface *ifa)
328 | {
329 |   struct radv_proto *p = ifa->ra;
330 |   struct radv_config *cf = (struct radv_config *) (p->p.cf);
331 |   struct radv_iface_config *ic = ifa->cf;
332 |   btime now = current_time();
333 | 
334 |   char *buf = ifa->sk->tbuf;
335 |   char *bufstart = buf;
336 |   char *bufend = buf + ifa->sk->tbsize;
337 | 
338 |   struct radv_ra_packet *pkt = (void *) buf;
339 |   pkt->type = ICMPV6_RA;
340 |   pkt->code = 0;
341 |   pkt->checksum = 0;
342 |   pkt->current_hop_limit = ic->current_hop_limit;
343 |   pkt->router_lifetime = (p->valid && (p->active || !ic->default_lifetime_sensitive)) ?
344 |     htons(ic->default_lifetime) : 0;
345 |   pkt->flags = (ic->managed ? OPT_RA_MANAGED : 0) |
346 |     (ic->other_config ? OPT_RA_OTHER_CFG : 0) |
347 |     (pkt->router_lifetime ? ic->default_preference : 0);
348 |   pkt->reachable_time = htonl(ic->reachable_time);
349 |   pkt->retrans_timer = htonl(ic->retrans_timer);
350 |   buf += sizeof(*pkt);
351 | 
352 |   if (ic->link_mtu)
353 |   {
354 |     struct radv_opt_mtu *om = (void *) buf;
355 |     om->type = OPT_MTU;
356 |     om->length = 1;
357 |     om->reserved = 0;
358 |     om->mtu = htonl(ic->link_mtu);
359 |     buf += sizeof (*om);
360 |   }
361 | 
362 |   /* Keeping track of first linger timeout */
363 |   ifa->valid_time = TIME_INFINITY;
364 | 
365 |   struct radv_prefix *px;
366 |   WALK_LIST(px, ifa->prefixes)
367 |   {
368 |     /* Skip invalid prefixes that are past linger timeout but still not pruned */
369 |     if (!px->valid && ((px->changed + ic->prefix_linger_time S) <= now))
370 | 	continue;
371 | 
372 |     if (radv_prepare_prefix(ifa, px, &buf, bufend) < 0)
373 |       goto done;
374 |   }
375 | 
376 |   if (! ic->rdnss_local)
377 |     if (radv_prepare_rdnss(ifa, &cf->rdnss_list, &buf, bufend) < 0)
378 |       goto done;
379 | 
380 |   if (radv_prepare_rdnss(ifa, &ic->rdnss_list, &buf, bufend) < 0)
381 |     goto done;
382 | 
383 |   if (! ic->dnssl_local)
384 |     if (radv_prepare_dnssl(ifa, &cf->dnssl_list, &buf, bufend) < 0)
385 |       goto done;
386 | 
387 |   if (radv_prepare_dnssl(ifa, &ic->dnssl_list, &buf, bufend) < 0)
388 |     goto done;
389 | 
390 |   if (! ic->custom_local)
391 |     if (radv_prepare_custom(ifa, &cf->custom_list, &buf, bufend) < 0)
392 |       goto done;
393 | 
394 |   if (radv_prepare_custom(ifa, &ic->custom_list, &buf, bufend) < 0)
395 |     goto done;
396 | 
397 | 
398 |   if (p->fib_up)
399 |   {
400 |     FIB_WALK(&p->routes, struct radv_route, rt)
401 |     {
402 |       /* Skip invalid routes that are past linger timeout but still not pruned */
403 |       if (!rt->valid && ((rt->changed + ic->route_linger_time S) <= now))
404 | 	continue;
405 | 
406 |       if (radv_prepare_route(ifa, rt, &buf, bufend) < 0)
407 | 	goto done;
408 |     }
409 |     FIB_WALK_END;
410 |   }
411 | 
412 |  done:
413 |   ifa->plen = buf - bufstart;
414 | }
415 | 
416 | 
417 | void
418 | radv_send_ra(struct radv_iface *ifa, ip_addr to)
419 | {
420 |   struct radv_proto *p = ifa->ra;
421 | 
422 |   /* TX queue is already full */
423 |   if (!sk_tx_buffer_empty(ifa->sk))
424 |     return;
425 | 
426 |   if (ifa->valid_time <= current_time())
427 |     radv_invalidate(ifa);
428 | 
429 |   /* We store prepared RA in tbuf */
430 |   if (!ifa->plen)
431 |     radv_prepare_ra(ifa);
432 | 
433 |   if (ipa_zero(to))
434 |   {
435 |     to = IP6_ALL_NODES;
436 |     RADV_TRACE(D_PACKETS, "Sending RA via %s", ifa->iface->name);
437 |   }
438 |   else
439 |   {
440 |     RADV_TRACE(D_PACKETS, "Sending RA to %I via %s", to, ifa->iface->name);
441 |   }
442 | 
443 |   int done = sk_send_to(ifa->sk, ifa->plen, to, 0);
444 |   if (!done)
445 |     log(L_WARN "%s: TX queue full on %s", p->p.name, ifa->iface->name);
446 | }
447 | 
448 | 
449 | static void
450 | radv_receive_rs(struct radv_proto *p, struct radv_iface *ifa, ip_addr from)
451 | {
452 |   RADV_TRACE(D_PACKETS, "Received RS from %I via %s",
453 | 	     from, ifa->iface->name);
454 | 
455 |   if (ifa->cf->solicited_ra_unicast && ipa_nonzero(from))
456 |     radv_send_ra(ifa, from);
457 |   else
458 |     radv_iface_notify(ifa, RA_EV_RS);
459 | }
460 | 
461 | static int
462 | radv_rx_hook(sock *sk, uint size)
463 | {
464 |   struct radv_iface *ifa = sk->data;
465 |   struct radv_proto *p = ifa->ra;
466 | 
467 |   /* We want just packets from sk->iface */
468 |   if (sk->lifindex != sk->iface->index)
469 |     return 1;
470 | 
471 |   if (ipa_equal(sk->faddr, sk->saddr))
472 |     return 1;
473 | 
474 |   if (size < 8)
475 |     return 1;
476 | 
477 |   byte *buf = sk->rbuf;
478 | 
479 |   if (buf[1] != 0)
480 |     return 1;
481 | 
482 |   /* Validation is a bit sloppy - Hop Limit is not checked and
483 |      length of options is ignored for RS and left to later for RA */
484 | 
485 |   switch (buf[0])
486 |   {
487 |   case ICMPV6_RS:
488 |     radv_receive_rs(p, ifa, sk->faddr);
489 |     return 1;
490 | 
491 |   case ICMPV6_RA:
492 |     RADV_TRACE(D_PACKETS, "Received RA from %I via %s",
493 | 	       sk->faddr, ifa->iface->name);
494 |     /* FIXME - there should be some checking of received RAs, but we just ignore them */
495 |     return 1;
496 | 
497 |   default:
498 |     return 1;
499 |   }
500 | }
501 | 
502 | static void
503 | radv_tx_hook(sock *sk)
504 | {
505 |   struct radv_iface *ifa = sk->data;
506 |   log(L_INFO "%s: TX queue ready on %s", ifa->ra->p.name, ifa->iface->name);
507 | 
508 |   /* Some RAs may be missed due to full TX queue */
509 |   radv_iface_notify(ifa, RA_EV_RS);
510 | }
511 | 
512 | static void
513 | radv_err_hook(sock *sk, int err)
514 | {
515 |   struct radv_iface *ifa = sk->data;
516 |   log(L_ERR "%s: Socket error on %s: %M", ifa->ra->p.name, ifa->iface->name, err);
517 | }
518 | 
519 | int
520 | radv_sk_open(struct radv_iface *ifa)
521 | {
522 |   sock *sk = sk_new(ifa->pool);
523 |   sk->type = SK_IP;
524 |   sk->subtype = SK_IPV6;
525 |   sk->dport = ICMPV6_PROTO;
526 |   sk->saddr = ifa->addr->ip;
527 |   sk->vrf = ifa->ra->p.vrf;
528 | 
529 |   sk->ttl = 255; /* Mandatory for Neighbor Discovery packets */
530 |   sk->rx_hook = radv_rx_hook;
531 |   sk->tx_hook = radv_tx_hook;
532 |   sk->err_hook = radv_err_hook;
533 |   sk->iface = ifa->iface;
534 |   sk->rbsize = 1024; // bufsize(ifa);
535 |   sk->tbsize = 1024; // bufsize(ifa);
536 |   sk->data = ifa;
537 |   sk->flags = SKF_LADDR_RX;
538 | 
539 |   if (sk_open(sk) < 0)
540 |     goto err;
541 | 
542 |   /* We want listen just to ICMPv6 messages of type RS and RA */
543 |   if (sk_set_icmp6_filter(sk, ICMPV6_RS, ICMPV6_RA) < 0)
544 |     goto err;
545 | 
546 |   if (sk_setup_multicast(sk) < 0)
547 |     goto err;
548 | 
549 |   if (sk_join_group(sk, IP6_ALL_ROUTERS) < 0)
550 |     goto err;
551 | 
552 |   ifa->sk = sk;
553 |   return 1;
554 | 
555 |  err:
556 |   sk_log_error(sk, ifa->ra->p.name);
557 |   rfree(sk);
558 |   return 0;
