643 | static int
644 | radv_reconfigure(struct proto *P, struct proto_config *CF)
645 | {
646 |   struct radv_proto *p = (struct radv_proto *) P;
647 |   struct radv_config *old = (struct radv_config *) (P->cf);
648 |   struct radv_config *new = (struct radv_config *) CF;
649 | 
650 |   if (!proto_configure_channel(P, &P->main_channel, proto_cf_main_channel(CF)))
651 |     return 0;
652 | 
653 |   P->cf = CF; /* radv_check_active() requires proper P->cf */
654 |   p->active = radv_check_active(p);
655 | 
656 |   /* Allocate or free FIB */
657 |   radv_set_fib(p, new->propagate_routes);
658 | 
659 |   /* We started to accept routes so we need to refeed them */
660 |   if (!old->propagate_routes && new->propagate_routes)
661 |     channel_request_feeding(p->p.main_channel);
662 | 
663 |   struct iface *iface;
664 |   WALK_LIST(iface, iface_list)
665 |   {
666 |     if (p->p.vrf_set && !if_in_vrf(iface, p->p.vrf))
667 |       continue;
668 | 
669 |     if (!(iface->flags & IF_UP))
670 |       continue;
671 | 
672 |     /* Ignore non-multicast ifaces */
673 |     if (!(iface->flags & IF_MULTICAST))
674 |       continue;
675 | 
676 |     /* Ignore ifaces without link-local address */
677 |     if (!iface->llv6)
678 |       continue;
679 | 
680 |     struct radv_iface *ifa = radv_iface_find(p, iface);
681 |     struct radv_iface_config *ic = (struct radv_iface_config *)
682 |       iface_patt_find(&new->patt_list, iface, NULL);
683 | 
684 |     if (ifa && ic)
685 |     {
686 |       ifa->cf = ic;
687 | 
688 |       /* We cheat here - always notify the change even if there isn't
689 | 	 any. That would leads just to a few unnecessary RAs. */
690 |       radv_iface_notify(ifa, RA_EV_CHANGE);
691 |     }
692 | 
693 |     if (ifa && !ic)
694 |     {
695 |       radv_iface_shutdown(ifa);
696 |       radv_iface_remove(ifa);
697 |     }
698 | 
699 |     if (!ifa && ic)
700 |       radv_iface_new(p, iface, ic);
701 |   }
702 | 
703 |   return 1;
704 | }
