 435 | static inline void
 436 | rip_kick_rxmt_timer(struct rip_iface *ifa)
 437 | {
 438 |   if (! tm_active(ifa->rxmt_timer))
 439 |     tm_start(ifa->rxmt_timer, ifa->cf->rxmt_time);
