  34 | /* RIP packet header */
  35 | struct rip_packet
  36 | {
  37 |   u8 command;
  38 |   u8 version;
  39 |   u16 unused;
  40 | };
  41 | 
  42 | /* Triggered RIP update header (RFC 2091) */
  43 | struct rip_update_hdr
  44 | {
  45 |   u8 version;
  46 |   u8 flush;
  47 |   u16 seqnum;
  48 | };
  49 | 
  50 | /* RTE block for RIPv2 */
  51 | struct rip_block_v2
  52 | {
  53 |   u16 family;
  54 |   u16 tag;
  55 |   ip4_addr network;
  56 |   ip4_addr netmask;
  57 |   ip4_addr next_hop;
  58 |   u32 metric;
  59 | };
  60 | 
  61 | /* RTE block for RIPng */
  62 | struct rip_block_ng
  63 | {
  64 |   ip6_addr prefix;
  65 |   u16 tag;
  66 |   u8 pxlen;
  67 |   u8 metric;
  68 | };
  69 | 
  70 | /* Authentication block for RIPv2 */
  71 | struct rip_block_auth
  72 | {
  73 |   u16 must_be_ffff;
  74 |   u16 auth_type;
  75 |   union {
  76 |     char password[16];
  77 |     struct {
  78 |       u16 packet_len;
  79 |       u8 key_id;
  80 |       u8 auth_len;
  81 |       u32 seq_num;
  82 |       u32 unused1;
  83 |       u32 unused2;
  84 |     };
  85 |   };
  86 | };
  87 | 
  88 | /* Authentication tail, RFC 4822 */
  89 | struct rip_auth_tail
  90 | {
  91 |   u16 must_be_ffff;
  92 |   u16 must_be_0001;
  93 |   byte auth_data[0];
  94 | };
  95 | 
  96 | /* Internal representation of RTE block data */
  97 | struct rip_block
  98 | {
  99 |   net_addr net;
 100 |   u32 metric;
 101 |   u16 tag;
 102 |   u16 no_af;
 103 |   ip_addr next_hop;
 104 | };
