 991 | {
 992 |   struct rip_proto *p = ifa->rip;
 993 | 
 994 |   sock *sk = sk_new(p->p.pool);
 995 |   sk->type = SK_UDP;
 996 |   sk->subtype = rip_is_v2(p) ? SK_IPV4 : SK_IPV6;
 997 |   sk->sport = ifa->cf->port;
 998 |   sk->dport = ifa->cf->port;
