   1 | /*
   2 |  *	BIRD -- Routing Information Protocol (RIP)
   3 |  *
   4 |  *	(c) 1998--1999 Pavel Machek <pavel@ucw.cz>
   5 |  *	(c) 2004--2013 Ondrej Filip <feela@network.cz>
   6 |  *	(c) 2009--2015 Ondrej Zajicek <santiago@crfreenet.org>
   7 |  *	(c) 2009--2015 CZ.NIC z.s.p.o.
   8 |  *
   9 |  *	Can be freely distributed and used under the terms of the GNU GPL.
  10 |  */
  11 | 
  12 | /**
  13 |  * DOC: Routing Information Protocol (RIP)
  14 |  *
  15 |  * The RIP protocol is implemented in two files: |rip.c| containing the protocol
  16 |  * logic, route management and the protocol glue with BIRD core, and |packets.c|
  17 |  * handling RIP packet processing, RX, TX and protocol sockets.
  18 |  *
  19 |  * Each instance of RIP is described by a structure &rip_proto, which contains
  20 |  * an internal RIP routing table, a list of protocol interfaces and the main
  21 |  * timer responsible for RIP routing table cleanup.
  22 |  *
  23 |  * RIP internal routing table contains incoming and outgoing routes. For each
  24 |  * network (represented by structure &rip_entry) there is one outgoing route
  25 |  * stored directly in &rip_entry and an one-way linked list of incoming routes
  26 |  * (structures &rip_rte). The list contains incoming routes from different RIP
  27 |  * neighbors, but only routes with the lowest metric are stored (i.e., all
  28 |  * stored incoming routes have the same metric).
  29 |  *
  30 |  * Note that RIP itself does not select outgoing route, that is done by the core
  31 |  * routing table. When a new incoming route is received, it is propagated to the
  32 |  * RIP table by rip_update_rte() and possibly stored in the list of incoming
  33 |  * routes. Then the change may be propagated to the core by rip_announce_rte().
  34 |  * The core selects the best route and propagate it to RIP by rip_rt_notify(),
  35 |  * which updates outgoing route part of &rip_entry and possibly triggers route
  36 |  * propagation by rip_trigger_update().
  37 |  *
  38 |  * RIP interfaces are represented by structures &rip_iface. A RIP interface
  39 |  * contains a per-interface socket, a list of associated neighbors, interface
  40 |  * configuration, and state information related to scheduled interface events
  41 |  * and running update sessions. RIP interfaces are added and removed based on
  42 |  * core interface notifications.
  43 |  *
  44 |  * There are two RIP interface events - regular updates and triggered updates.
  45 |  * Both are managed from the RIP interface timer (rip_iface_timer()). Regular
  46 |  * updates are called at fixed interval and propagate the whole routing table,
  47 |  * while triggered updates are scheduled by rip_trigger_update() due to some
  48 |  * routing table change and propagate only the routes modified since the time
  49 |  * they were scheduled. There are also unicast-destined requested updates, but
  50 |  * these are sent directly as a reaction to received RIP request message. The
  51 |  * update session is started by rip_send_table(). There may be at most one
  52 |  * active update session per interface, as the associated state (including the
  53 |  * fib iterator) is stored directly in &rip_iface structure.
  54 |  *
  55 |  * RIP neighbors are represented by structures &rip_neighbor. Compared to
  56 |  * neighbor handling in other routing protocols, RIP does not have explicit
  57 |  * neighbor discovery and adjacency maintenance, which makes the &rip_neighbor
  58 |  * related code a bit peculiar. RIP neighbors are interlinked with core neighbor
  59 |  * structures (&neighbor) and use core neighbor notifications to ensure that RIP
  60 |  * neighbors are timely removed. RIP neighbors are added based on received route
  61 |  * notifications and removed based on core neighbor and RIP interface events.
  62 |  *
  63 |  * RIP neighbors are linked by RIP routes and use counter to track the number of
  64 |  * associated routes, but when these RIP routes timeout, associated RIP neighbor
  65 |  * is still alive (with zero counter). When RIP neighbor is removed but still
  66 |  * has some associated routes, it is not freed, just changed to detached state
  67 |  * (core neighbors and RIP ifaces are unlinked), then during the main timer
  68 |  * cleanup phase the associated routes are removed and the &rip_neighbor
  69 |  * structure is finally freed.
  70 |  *
  71 |  * Supported standards:
  72 |  * RFC 1058 - RIPv1
  73 |  * RFC 2453 - RIPv2
  74 |  * RFC 2080 - RIPng
  75 |  * RFC 2091 - Triggered RIP for demand circuits
  76 |  * RFC 4822 - RIP cryptographic authentication
  77 |  */
  78 | 
  79 | #include <stdlib.h>
  80 | 
  81 | #include "rip.h"
  82 | 
  83 | 
  84 | static inline void rip_lock_neighbor(struct rip_neighbor *n);
  85 | static inline void rip_unlock_neighbor(struct rip_neighbor *n);
  86 | static inline int rip_iface_link_up(struct rip_iface *ifa);
  87 | static inline void rip_kick_timer(struct rip_proto *p);
  88 | static inline void rip_iface_kick_timer(struct rip_iface *ifa);
  89 | static void rip_iface_timer(timer *timer);
  90 | static void rip_trigger_update(struct rip_proto *p);
  91 | 
  92 | 
  93 | /*
  94 |  *	RIP routes
  95 |  */
  96 | 
  97 | static struct rip_rte *
  98 | rip_add_rte(struct rip_proto *p, struct rip_rte **rp, struct rip_rte *src)
  99 | {
 100 |   struct rip_rte *rt = sl_alloc(p->rte_slab);
 101 | 
 102 |   memcpy(rt, src, sizeof(struct rip_rte));
 103 |   rt->next = *rp;
 104 |   *rp = rt;
 105 | 
 106 |   rip_lock_neighbor(rt->from);
 107 | 
 108 |   return rt;
 109 | }
 110 | 
 111 | static inline void
 112 | rip_remove_rte(struct rip_proto *p UNUSED, struct rip_rte **rp)
 113 | {
 114 |   struct rip_rte *rt = *rp;
 115 | 
 116 |   rip_unlock_neighbor(rt->from);
 117 | 
 118 |   *rp = rt->next;
 119 |   sl_free(rt);
 120 | }
 121 | 
 122 | static inline int rip_same_rte(struct rip_rte *a, struct rip_rte *b)
 123 | { return a->metric == b->metric && a->tag == b->tag && ipa_equal(a->next_hop, b->next_hop); }
 124 | 
 125 | static inline int rip_valid_rte(struct rip_rte *rt)
 126 | { return rt->from->ifa != NULL; }
 127 | 
 128 | struct rip_iface_adata {
 129 |   struct adata ad;
 130 |   struct iface *iface;
 131 | };
 132 | 
 133 | /**
 134 |  * rip_announce_rte - announce route from RIP routing table to the core
 135 |  * @p: RIP instance
 136 |  * @en: related network
 137 |  *
 138 |  * The function takes a list of incoming routes from @en, prepare appropriate
 139 |  * &rte for the core and propagate it by rte_update().
 140 |  */
 141 | static void
 142 | rip_announce_rte(struct rip_proto *p, struct rip_entry *en)
 143 | {
 144 |   struct rip_rte *rt = en->routes;
 145 | 
 146 |   /* Find first valid rte */
 147 |   while (rt && !rip_valid_rte(rt))
 148 |     rt = rt->next;
 149 | 
 150 |   if (rt)
 151 |   {
 152 |     /* Update */
 153 |     rta a0 = {
 154 |       .pref = p->p.main_channel->preference,
 155 |       .source = RTS_RIP,
 156 |       .scope = SCOPE_UNIVERSE,
 157 |       .dest = RTD_UNICAST,
 158 |     };
 159 | 
 160 |     u8 rt_metric = rt->metric;
 161 |     u16 rt_tag = rt->tag;
 162 | 
 163 |     if (p->ecmp)
 164 |     {
 165 |       /* ECMP route */
 166 |       struct nexthop *nhs = NULL;
 167 |       int num = 0;
 168 | 
 169 |       for (rt = en->routes; rt && (num < p->ecmp); rt = rt->next)
 170 |       {
 171 | 	if (!rip_valid_rte(rt))
 172 | 	    continue;
 173 | 
 174 | 	struct nexthop *nh = allocz(sizeof(struct nexthop));
 175 | 
 176 | 	nh->gw = rt->next_hop;
 177 | 	nh->iface = rt->from->ifa->iface;
 178 | 	nh->weight = rt->from->ifa->cf->ecmp_weight;
 179 | 
 180 | 	nexthop_insert(&nhs, nh);
 181 | 	num++;
 182 | 
 183 | 	if (rt->tag != rt_tag)
 184 | 	  rt_tag = 0;
 185 |       }
 186 | 
 187 |       a0.nh = *nhs;
 188 |     }
 189 |     else
 190 |     {
 191 |       /* Unipath route */
 192 |       a0.from = rt->from->nbr->addr;
 193 |       a0.nh.gw = rt->next_hop;
 194 |       a0.nh.iface = rt->from->ifa->iface;
 195 |     }
 196 | 
 197 |     struct {
 198 |       ea_list l;
 199 |       eattr e[3];
 200 |       struct rip_iface_adata riad;
 201 |     } ea_block = {
 202 |       .l = { .count = 3, },
 203 |       .e = {
 204 | 	{
 205 | 	  .id = EA_RIP_METRIC,
 206 | 	  .type = EAF_TYPE_INT,
 207 | 	  .u.data = rt_metric,
 208 | 	},
 209 | 	{
 210 | 	  .id = EA_RIP_TAG,
 211 | 	  .type = EAF_TYPE_INT,
 212 | 	  .u.data = rt_tag,
 213 | 	},
 214 | 	{
 215 | 	  .id = EA_RIP_FROM,
 216 | 	  .type = EAF_TYPE_IFACE,
 217 | 	  .u.ptr = &ea_block.riad.ad,
 218 | 	}
 219 |       },
 220 |       .riad = {
 221 | 	.ad = { .length = sizeof(struct rip_iface_adata) - sizeof(struct adata) },
 222 | 	.iface = a0.nh.iface,
 223 |       },
 224 |     };
 225 | 
 226 |     a0.eattrs = &ea_block.l;
 227 | 
 228 |     rta *a = rta_lookup(&a0);
 229 |     rte *e = rte_get_temp(a, p->p.main_source);
 230 | 
 231 |     rte_update(&p->p, en->n.addr, e);
 232 |   }
 233 |   else
 234 |   {
 235 |     /* Withdraw */
 236 |     rte_update(&p->p, en->n.addr, NULL);
 237 |   }
 238 | }
 239 | 
 240 | /**
 241 |  * rip_update_rte - enter a route update to RIP routing table
 242 |  * @p: RIP instance
 243 |  * @addr: network address
 244 |  * @new: a &rip_rte representing the new route
 245 |  *
 246 |  * The function is called by the RIP packet processing code whenever it receives
 247 |  * a reachable route. The appropriate routing table entry is found and the list
 248 |  * of incoming routes is updated. Eventually, the change is also propagated to
 249 |  * the core by rip_announce_rte(). Note that for unreachable routes,
 250 |  * rip_withdraw_rte() should be called instead of rip_update_rte().
 251 |  */
 252 | void
 253 | rip_update_rte(struct rip_proto *p, net_addr *n, struct rip_rte *new)
 254 | {
 255 |   struct rip_entry *en = fib_get(&p->rtable, n);
 256 |   struct rip_rte *rt, **rp;
 257 |   int changed = 0;
 258 | 
 259 |   /* If the new route is better, remove all current routes */
 260 |   if (en->routes && new->metric < en->routes->metric)
 261 |     while (en->routes)
 262 |       rip_remove_rte(p, &en->routes);
 263 | 
 264 |   /* Find the old route (also set rp for later) */
 265 |   for (rp = &en->routes; rt = *rp; rp = &rt->next)
 266 |     if (rt->from == new->from)
 267 |     {
 268 |       if (rip_same_rte(rt, new))
 269 |       {
 270 | 	rt->expires = new->expires;
 271 | 	return;
 272 |       }
 273 | 
 274 |       /* Remove the old route */
 275 |       rip_remove_rte(p, rp);
 276 |       changed = 1;
 277 |       break;
 278 |     }
 279 | 
 280 |   /* If the new route is optimal, add it to the list */
 281 |   if (!en->routes || new->metric == en->routes->metric)
 282 |   {
 283 |     rt = rip_add_rte(p, rp, new);
 284 |     changed = 1;
 285 |   }
 286 | 
 287 |   /* Announce change if on relevant position (the first or any for ECMP) */
 288 |   if (changed && (rp == &en->routes || p->ecmp))
 289 |     rip_announce_rte(p, en);
 290 | }
 291 | 
 292 | /**
 293 |  * rip_withdraw_rte - enter a route withdraw to RIP routing table
 294 |  * @p: RIP instance
 295 |  * @addr: network address
 296 |  * @from: a &rip_neighbor propagating the withdraw
 297 |  *
 298 |  * The function is called by the RIP packet processing code whenever it receives
 299 |  * an unreachable route. The incoming route for given network from nbr @from is
 300 |  * removed. Eventually, the change is also propagated by rip_announce_rte().
 301 |  */
 302 | void
 303 | rip_withdraw_rte(struct rip_proto *p, net_addr *n, struct rip_neighbor *from)
 304 | {
 305 |   struct rip_entry *en = fib_find(&p->rtable, n);
 306 |   struct rip_rte *rt, **rp;
 307 | 
 308 |   if (!en)
 309 |     return;
 310 | 
 311 |   /* Find the old route */
 312 |   for (rp = &en->routes; rt = *rp; rp = &rt->next)
 313 |     if (rt->from == from)
 314 |       break;
 315 | 
 316 |   if (!rt)
 317 |     return;
 318 | 
 319 |   /* Remove the old route */
 320 |   rip_remove_rte(p, rp);
 321 | 
 322 |   /* Announce change if on relevant position */
 323 |   if (rp == &en->routes || p->ecmp)
 324 |     rip_announce_rte(p, en);
 325 | }
 326 | 
 327 | /*
 328 |  * rip_rt_notify - core tells us about new route, so store
 329 |  * it into our data structures.
 330 |  */
 331 | static void
 332 | rip_rt_notify(struct proto *P, struct channel *ch UNUSED, struct network *net, struct rte *new,
 333 | 	      struct rte *old UNUSED)
 334 | {
 335 |   struct rip_proto *p = (struct rip_proto *) P;
 336 |   struct rip_entry *en;
 337 |   int old_metric;
 338 | 
 339 |   if (new)
 340 |   {
 341 |     /* Update */
 342 |     u32 rt_tag = ea_get_int(new->attrs->eattrs, EA_RIP_TAG, 0);
 343 |     u32 rt_metric = ea_get_int(new->attrs->eattrs, EA_RIP_METRIC, 1);
 344 |     const eattr *rie = ea_find(new->attrs->eattrs, EA_RIP_FROM);
 345 |     struct iface *rt_from = rie ? ((struct rip_iface_adata *) rie->u.ptr)->iface : NULL;
 346 | 
 347 |     if (rt_metric > p->infinity)
 348 |     {
 349 |       log(L_WARN "%s: Invalid rip_metric value %u for route %N",
 350 | 	  p->p.name, rt_metric, net->n.addr);
 351 |       rt_metric = p->infinity;
 352 |     }
 353 | 
 354 |     if (rt_tag > 0xffff)
 355 |     {
 356 |       log(L_WARN "%s: Invalid rip_tag value %u for route %N",
 357 | 	  p->p.name, rt_tag, net->n.addr);
 358 |       rt_metric = p->infinity;
 359 |       rt_tag = 0;
 360 |     }
 361 | 
 362 |     /*
 363 |      * Note that we accept exported routes with infinity metric (this could
 364 |      * happen if rip_metric is modified in filters). Such entry has infinity
 365 |      * metric but is RIP_ENTRY_VALID and therefore is not subject to garbage
 366 |      * collection.
 367 |      */
 368 | 
 369 |     en = fib_get(&p->rtable, net->n.addr);
 370 | 
 371 |     old_metric = en->valid ? en->metric : -1;
 372 | 
 373 |     en->valid = RIP_ENTRY_VALID;
 374 |     en->metric = rt_metric;
 375 |     en->tag = rt_tag;
 376 |     en->from = (new->src->proto == P) ? rt_from : NULL;
 377 |     en->iface = new->attrs->nh.iface;
 378 |     en->next_hop = new->attrs->nh.gw;
 379 |   }
 380 |   else
 381 |   {
 382 |     /* Withdraw */
 383 |     en = fib_find(&p->rtable, net->n.addr);
 384 | 
 385 |     if (!en || en->valid != RIP_ENTRY_VALID)
 386 |       return;
 387 | 
 388 |     old_metric = en->metric;
 389 | 
 390 |     en->valid = RIP_ENTRY_STALE;
 391 |     en->metric = p->infinity;
 392 |     en->tag = 0;
 393 |     en->from = NULL;
 394 |     en->iface = NULL;
 395 |     en->next_hop = IPA_NONE;
 396 |   }
 397 | 
 398 |   /* Activate triggered updates */
 399 |   if (en->metric != old_metric)
 400 |   {
 401 |     en->changed = current_time();
 402 |     rip_trigger_update(p);
 403 |   }
 404 | }
 405 | 
 406 | void
 407 | rip_flush_table(struct rip_proto *p, struct rip_neighbor *n)
 408 | {
 409 |   btime expires = current_time() + n->ifa->cf->timeout_time;
 410 | 
 411 |   FIB_WALK(&p->rtable, struct rip_entry, en)
 412 |   {
 413 |     for (struct rip_rte *e = en->routes; e; e = e->next)
 414 |       if ((e->from == n) && (e->expires == TIME_INFINITY))
 415 | 	e->expires = expires;
 416 |   }
 417 |   FIB_WALK_END;
 418 | }
 419 | 
 420 | 
 421 | /*
 422 |  *	RIP neighbors
 423 |  */
 424 | 
 425 | struct rip_neighbor *
 426 | rip_get_neighbor(struct rip_proto *p, ip_addr *a, struct rip_iface *ifa)
 427 | {
 428 |   neighbor *nbr = neigh_find(&p->p, *a, ifa->iface, 0);
 429 | 
 430 |   if (!nbr || (nbr->scope == SCOPE_HOST) || !rip_iface_link_up(ifa))
 431 |     return NULL;
 432 | 
 433 |   if (nbr->data)
 434 |     return nbr->data;
 435 | 
 436 |   TRACE(D_EVENTS, "New neighbor %I on %s", *a, ifa->iface->name);
 437 | 
 438 |   struct rip_neighbor *n = mb_allocz(p->p.pool, sizeof(struct rip_neighbor));
 439 |   n->ifa = ifa;
 440 |   n->nbr = nbr;
 441 |   nbr->data = n;
 442 |   n->csn = nbr->aux;
 443 | 
 444 |   add_tail(&ifa->neigh_list, NODE n);
 445 | 
 446 |   return n;
 447 | }
 448 | 
 449 | static void
 450 | rip_remove_neighbor(struct rip_proto *p, struct rip_neighbor *n)
 451 | {
 452 |   neighbor *nbr = n->nbr;
 453 | 
 454 |   TRACE(D_EVENTS, "Removing neighbor %I on %s", nbr->addr, nbr->ifreq->name);
 455 | 
 456 |   rem_node(NODE n);
 457 |   n->ifa = NULL;
 458 |   n->nbr = NULL;
 459 |   nbr->data = NULL;
 460 |   nbr->aux = n->csn;
 461 | 
 462 |   rfree(n->bfd_req);
 463 |   n->bfd_req = NULL;
 464 |   n->last_seen = 0;
 465 | 
 466 |   if (!n->uc)
 467 |     mb_free(n);
 468 | 
 469 |   /* Related routes are removed in rip_timer() */
 470 |   rip_kick_timer(p);
 471 | }
 472 | 
 473 | static inline void
 474 | rip_lock_neighbor(struct rip_neighbor *n)
 475 | {
 476 |   n->uc++;
 477 | }
 478 | 
 479 | static inline void
 480 | rip_unlock_neighbor(struct rip_neighbor *n)
 481 | {
 482 |   n->uc--;
 483 | 
 484 |   if (!n->nbr && !n->uc)
 485 |     mb_free(n);
 486 | }
 487 | 
 488 | static void
 489 | rip_neigh_notify(struct neighbor *nbr)
 490 | {
 491 |   struct rip_proto *p = (struct rip_proto *) nbr->proto;
 492 |   struct rip_neighbor *n = nbr->data;
 493 | 
 494 |   if (!n)
 495 |     return;
 496 | 
 497 |   /*
 498 |    * We assume that rip_neigh_notify() is called before rip_if_notify() for
 499 |    * IF_CHANGE_DOWN and therefore n->ifa is still valid. We have no such
 500 |    * ordering assumption for IF_CHANGE_LINK, so we test link state of the
 501 |    * underlying iface instead of just rip_iface state.
 502 |    */
 503 |   if ((nbr->scope <= 0) || !rip_iface_link_up(n->ifa))
 504 |     rip_remove_neighbor(p, n);
 505 | }
 506 | 
 507 | static void
 508 | rip_bfd_notify(struct bfd_request *req)
 509 | {
 510 |   struct rip_neighbor *n = req->data;
 511 |   struct rip_proto *p = n->ifa->rip;
 512 | 
 513 |   if (req->down)
 514 |   {
 515 |     TRACE(D_EVENTS, "BFD session down for nbr %I on %s",
 516 | 	  n->nbr->addr, n->ifa->iface->name);
 517 |     rip_remove_neighbor(p, n);
 518 |   }
 519 | }
 520 | 
 521 | void
 522 | rip_update_bfd(struct rip_proto *p, struct rip_neighbor *n)
 523 | {
 524 |   int use_bfd = n->ifa->cf->bfd && n->last_seen;
 525 | 
 526 |   if (use_bfd && !n->bfd_req)
 527 |   {
 528 |     /*
 529 |      * For RIPv2, use the same address as rip_open_socket(). For RIPng, neighbor
 530 |      * should contain an address from the same prefix, thus also link-local. It
 531 |      * may cause problems if two link-local addresses are assigned to one iface.
 532 |      */
 533 |     ip_addr saddr = rip_is_v2(p) ? n->ifa->sk->saddr : n->nbr->ifa->ip;
 534 |     n->bfd_req = bfd_request_session(p->p.pool, n->nbr->addr, saddr,
 535 | 				     n->nbr->iface, p->p.vrf,
 536 | 				     rip_bfd_notify, n, NULL);
 537 |   }
 538 | 
 539 |   if (!use_bfd && n->bfd_req)
 540 |   {
 541 |     rfree(n->bfd_req);
 542 |     n->bfd_req = NULL;
 543 |   }
 544 | }
