 547 | /*
 548 |  *	RIP interfaces
 549 |  */
 550 | 
 551 | static void
 552 | rip_iface_start(struct rip_iface *ifa)
 553 | {
 554 |   struct rip_proto *p = ifa->rip;
 555 | 
 556 |   TRACE(D_EVENTS, "Starting interface %s", ifa->iface->name);
 557 | 
 558 |   if (! ifa->cf->demand_circuit)
 559 |   {
 560 |     ifa->next_regular = current_time() + (random() % ifa->cf->update_time) + 100 MS;
 561 |     tm_set(ifa->timer, ifa->next_regular);
 562 |   }
 563 |   else
 564 |   {
 565 |     ifa->next_regular = TIME_INFINITY;
 566 |   }
 567 | 
 568 |   ifa->up = 1;
 569 | 
 570 |   if (ifa->cf->passive)
 571 |     return;
 572 | 
 573 |   rip_send_request(p, ifa);
 574 |   rip_send_table(p, ifa, ifa->addr, 0);
 575 | }
 576 | 
 577 | static void
 578 | rip_iface_stop(struct rip_iface *ifa)
 579 | {
 580 |   struct rip_proto *p = ifa->rip;
 581 |   struct rip_neighbor *n;
 582 | 
 583 |   TRACE(D_EVENTS, "Stopping interface %s", ifa->iface->name);
 584 | 
 585 |   rip_reset_tx_session(p, ifa);
 586 | 
 587 |   ifa->next_regular = 0;
 588 |   ifa->next_triggered = 0;
 589 |   ifa->want_triggered = 0;
 590 | 
 591 |   if (ifa->tx_pending)
 592 |     ifa->tx_seqnum++;
 593 | 
 594 |   ifa->tx_pending = 0;
 595 |   ifa->req_pending = 0;
 596 | 
 597 |   if (ifa->cf->demand_circuit && !ifa->cf->passive)
 598 |     rip_send_flush(p, ifa);
 599 | 
 600 |   WALK_LIST_FIRST(n, ifa->neigh_list)
 601 |     rip_remove_neighbor(p, n);
 602 | 
 603 |   tm_stop(ifa->timer);
 604 |   tm_stop(ifa->rxmt_timer);
 605 |   ifa->up = 0;
 606 | }
 607 | 
 608 | static inline int
 609 | rip_iface_link_up(struct rip_iface *ifa)
 610 | {
 611 |   return !ifa->cf->check_link || (ifa->iface->flags & IF_LINK_UP);
 612 | }
 613 | 
 614 | static void
 615 | rip_iface_update_state(struct rip_iface *ifa)
 616 | {
 617 |   int up = ifa->sk && rip_iface_link_up(ifa);
 618 | 
 619 |   if (up == ifa->up)
 620 |     return;
 621 | 
 622 |   if (up)
 623 |     rip_iface_start(ifa);
 624 |   else
 625 |     rip_iface_stop(ifa);
 626 | }
 627 | 
 628 | static void
 629 | rip_iface_update_buffers(struct rip_iface *ifa)
 630 | {
 631 |   if (!ifa->sk)
 632 |     return;
 633 | 
 634 |   uint rbsize = ifa->cf->rx_buffer ?: ifa->iface->mtu;
 635 |   uint tbsize = ifa->cf->tx_length ?: ifa->iface->mtu;
 636 |   rbsize = MAX(rbsize, tbsize);
 637 | 
 638 |   sk_set_rbsize(ifa->sk, rbsize);
 639 |   sk_set_tbsize(ifa->sk, tbsize);
 640 | 
 641 |   uint headers = (rip_is_v2(ifa->rip) ? IP4_HEADER_LENGTH : IP6_HEADER_LENGTH) + UDP_HEADER_LENGTH;
 642 |   ifa->tx_plen = tbsize - headers;
 643 | 
 644 |   if (ifa->cf->auth_type == RIP_AUTH_CRYPTO)
 645 |     ifa->tx_plen -= RIP_AUTH_TAIL_LENGTH + max_mac_length(ifa->cf->passwords);
 646 | }
 647 | 
 648 | static inline void
 649 | rip_iface_update_bfd(struct rip_iface *ifa)
 650 | {
 651 |   struct rip_proto *p = ifa->rip;
 652 |   struct rip_neighbor *n;
 653 | 
 654 |   WALK_LIST(n, ifa->neigh_list)
 655 |     rip_update_bfd(p, n);
 656 | }
 657 | 
 658 | 
 659 | static void
 660 | rip_iface_locked(struct object_lock *lock)
 661 | {
 662 |   struct rip_iface *ifa = lock->data;
 663 |   struct rip_proto *p = ifa->rip;
 664 | 
 665 |   if (!rip_open_socket(ifa))
 666 |   {
 667 |     log(L_ERR "%s: Cannot open socket for %s", p->p.name, ifa->iface->name);
 668 |     return;
 669 |   }
 670 | 
 671 |   rip_iface_update_buffers(ifa);
 672 |   rip_iface_update_state(ifa);
 673 | }
 674 | 
 675 | 
 676 | static struct rip_iface *
 677 | rip_find_iface(struct rip_proto *p, struct iface *what)
 678 | {
 679 |   struct rip_iface *ifa;
 680 | 
 681 |   WALK_LIST(ifa, p->iface_list)
 682 |     if (ifa->iface == what)
 683 |       return ifa;
 684 | 
 685 |   return NULL;
 686 | }
 687 | 
 688 | static void
 689 | rip_add_iface(struct rip_proto *p, struct iface *iface, struct rip_iface_config *ic)
 690 | {
 691 |   struct rip_iface *ifa;
 692 | 
 693 |   TRACE(D_EVENTS, "Adding interface %s", iface->name);
 694 | 
 695 |   ifa = mb_allocz(p->p.pool, sizeof(struct rip_iface));
 696 |   ifa->rip = p;
 697 |   ifa->iface = iface;
 698 |   ifa->cf = ic;
 699 | 
 700 |   if (ipa_nonzero(ic->address))
 701 |     ifa->addr = ic->address;
 702 |   else if (ic->mode == RIP_IM_MULTICAST)
 703 |     ifa->addr = rip_is_v2(p) ? IP4_RIP_ROUTERS : IP6_RIP_ROUTERS;
 704 |   else /* Broadcast */
 705 |     ifa->addr = iface->addr4->brd;
 706 |   /*
 707 |    * The above is just a workaround for BSD as it can't send broadcasts
 708 |    * to 255.255.255.255. BSD systems need the network broadcast address instead.
 709 |    *
 710 |    * TODO: move this to sysdep code
 711 |    */
 712 | 
 713 |   init_list(&ifa->neigh_list);
 714 | 
 715 |   add_tail(&p->iface_list, NODE ifa);
 716 | 
 717 |   ifa->timer = tm_new_init(p->p.pool, rip_iface_timer, ifa, 0, 0);
 718 |   ifa->rxmt_timer = tm_new_init(p->p.pool, rip_rxmt_timeout, ifa, 0, 0);
 719 | 
 720 |   struct object_lock *lock = olock_new(p->p.pool);
 721 |   lock->type = OBJLOCK_UDP;
 722 |   lock->port = ic->port;
 723 |   lock->iface = iface;
 724 |   lock->data = ifa;
 725 |   lock->hook = rip_iface_locked;
 726 |   ifa->lock = lock;
 727 | 
 728 |   olock_acquire(lock);
 729 | }
 730 | 
 731 | static void
 732 | rip_remove_iface(struct rip_proto *p, struct rip_iface *ifa)
 733 | {
 734 |   rip_iface_stop(ifa);
 735 | 
 736 |   TRACE(D_EVENTS, "Removing interface %s", ifa->iface->name);
 737 | 
 738 |   rem_node(NODE ifa);
 739 | 
 740 |   rfree(ifa->sk);
 741 |   rfree(ifa->lock);
 742 |   rfree(ifa->timer);
 743 | 
 744 |   mb_free(ifa);
 745 | }
 746 | 
 747 | static int
 748 | rip_reconfigure_iface(struct rip_proto *p, struct rip_iface *ifa, struct rip_iface_config *new)
 749 | {
 750 |   struct rip_iface_config *old = ifa->cf;
 751 | 
 752 |   /* Change of these options would require to reset the iface socket */
 753 |   if ((new->mode != old->mode) ||
 754 |       (new->port != old->port) ||
 755 |       (new->tx_tos != old->tx_tos) ||
 756 |       (new->tx_priority != old->tx_priority) ||
 757 |       (new->ttl_security != old->ttl_security) ||
 758 |       (new->demand_circuit != old->demand_circuit))
 759 |     return 0;
 760 | 
 761 |   TRACE(D_EVENTS, "Reconfiguring interface %s", ifa->iface->name);
 762 | 
 763 |   ifa->cf = new;
 764 | 
 765 |   rip_iface_update_buffers(ifa);
 766 | 
 767 |   if ((! ifa->cf->demand_circuit) &&
 768 |       (ifa->next_regular > (current_time() + new->update_time)))
 769 |     ifa->next_regular = current_time() + (random() % new->update_time) + 100 MS;
 770 | 
 771 |   if (ifa->up && new->demand_circuit && (new->passive != old->passive))
 772 |   {
 773 |     if (new->passive)
 774 |       rip_send_flush(p, ifa);
 775 |     else
 776 |     {
 777 |       rip_send_request(p, ifa);
 778 |       rip_send_table(p, ifa, ifa->addr, 0);
 779 |     }
 780 |   }
 781 | 
 782 |   if (new->check_link != old->check_link)
 783 |     rip_iface_update_state(ifa);
 784 | 
 785 |   if (new->bfd != old->bfd)
 786 |     rip_iface_update_bfd(ifa);
 787 | 
 788 |   if (ifa->up)
 789 |     rip_iface_kick_timer(ifa);
 790 | 
 791 |   return 1;
 792 | }
 793 | 
 794 | static void
 795 | rip_reconfigure_ifaces(struct rip_proto *p, struct rip_config *cf)
 796 | {
 797 |   struct iface *iface;
 798 | 
 799 |   WALK_LIST(iface, iface_list)
 800 |   {
 801 |     if (p->p.vrf_set && !if_in_vrf(iface, p->p.vrf))
 802 |       continue;
 803 | 
 804 |     if (!(iface->flags & IF_UP))
 805 |       continue;
 806 | 
 807 |     /* Ignore ifaces without appropriate address */
 808 |     if (rip_is_v2(p) ? !iface->addr4 : !iface->llv6)
 809 |       continue;
 810 | 
 811 |     struct rip_iface *ifa = rip_find_iface(p, iface);
 812 |     struct rip_iface_config *ic = (void *) iface_patt_find(&cf->patt_list, iface, NULL);
 813 | 
 814 |     if (ifa && ic)
 815 |     {
 816 |       if (rip_reconfigure_iface(p, ifa, ic))
 817 | 	continue;
 818 | 
 819 |       /* Hard restart */
 820 |       log(L_INFO "%s: Restarting interface %s", p->p.name, ifa->iface->name);
 821 |       rip_remove_iface(p, ifa);
 822 |       rip_add_iface(p, iface, ic);
 823 |     }
 824 | 
 825 |     if (ifa && !ic)
 826 |       rip_remove_iface(p, ifa);
 827 | 
 828 |     if (!ifa && ic)
 829 |       rip_add_iface(p, iface, ic);
 830 |   }
 831 | }
 832 | 
 833 | static void
 834 | rip_if_notify(struct proto *P, unsigned flags, struct iface *iface)
 835 | {
 836 |   struct rip_proto *p = (void *) P;
 837 |   struct rip_config *cf = (void *) P->cf;
 838 |   struct rip_iface *ifa = rip_find_iface(p, iface);
 839 | 
 840 |   if (iface->flags & IF_IGNORE)
 841 |     return;
 842 | 
 843 |   /* Add, remove or restart interface */
 844 |   if (flags & (IF_CHANGE_UPDOWN | (rip_is_v2(p) ? IF_CHANGE_ADDR4 : IF_CHANGE_LLV6)))
 845 |   {
 846 |     if (ifa)
 847 |       rip_remove_iface(p, ifa);
 848 | 
 849 |     if (!(iface->flags & IF_UP))
 850 |       return;
 851 | 
 852 |     /* Ignore ifaces without appropriate address */
 853 |     if (rip_is_v2(p) ? !iface->addr4 : !iface->llv6)
 854 |       return;
 855 | 
 856 |     struct rip_iface_config *ic = (void *) iface_patt_find(&cf->patt_list, iface, NULL);
 857 |     if (ic)
 858 |       rip_add_iface(p, iface, ic);
 859 | 
 860 |     return;
 861 |   }
 862 | 
 863 |   if (!ifa)
 864 |     return;
 865 | 
 866 |   if (flags & IF_CHANGE_MTU)
 867 |     rip_iface_update_buffers(ifa);
 868 | 
 869 |   if (flags & IF_CHANGE_LINK)
 870 |     rip_iface_update_state(ifa);
 871 | }
