 873 | 
 874 | /*
 875 |  *	RIP timer events
 876 |  */
 877 | 
 878 | /**
 879 |  * rip_timer - RIP main timer hook
 880 |  * @t: timer
 881 |  *
 882 |  * The RIP main timer is responsible for routing table maintenance. Invalid or
 883 |  * expired routes (&rip_rte) are removed and garbage collection of stale routing
 884 |  * table entries (&rip_entry) is done. Changes are propagated to core tables,
 885 |  * route reload is also done here. Note that garbage collection uses a maximal
 886 |  * GC time, while interfaces maintain an illusion of per-interface GC times in
 887 |  * rip_send_response().
 888 |  *
 889 |  * Keeping incoming routes and the selected outgoing route are two independent
 890 |  * functions, therefore after garbage collection some entries now considered
 891 |  * invalid (RIP_ENTRY_DUMMY) still may have non-empty list of incoming routes,
 892 |  * while some valid entries (representing an outgoing route) may have that list
 893 |  * empty.
 894 |  *
 895 |  * The main timer is not scheduled periodically but it uses the time of the
 896 |  * current next event and the minimal interval of any possible event to compute
 897 |  * the time of the next run.
 898 |  */
 899 | static void
 900 | rip_timer(timer *t)
 901 | {
 902 |   struct rip_proto *p = t->data;
 903 |   struct rip_config *cf = (void *) (p->p.cf);
 904 |   struct rip_iface *ifa;
 905 |   struct rip_neighbor *n, *nn;
 906 |   struct fib_iterator fit;
 907 |   btime now_ = current_time();
 908 |   btime next = now_ + MIN(cf->min_timeout_time, cf->max_garbage_time);
 909 |   btime expires = 0;
 910 | 
 911 |   TRACE(D_EVENTS, "Main timer fired");
 912 | 
 913 |   FIB_ITERATE_INIT(&fit, &p->rtable);
 914 | 
 915 |   loop:
 916 |   FIB_ITERATE_START(&p->rtable, &fit, struct rip_entry, en)
 917 |   {
 918 |     struct rip_rte *rt, **rp;
 919 |     int changed = 0;
 920 | 
 921 |     /* Checking received routes for timeout and for dead neighbors */
 922 |     for (rp = &en->routes; rt = *rp; /* rp = &rt->next */)
 923 |     {
 924 |       if (!rip_valid_rte(rt) || (rt->expires <= now_))
 925 |       {
 926 | 	rip_remove_rte(p, rp);
 927 | 	changed = 1;
 928 | 	continue;
 929 |       }
 930 | 
 931 |       next = MIN(next, rt->expires);
 932 |       rp = &rt->next;
 933 |     }
 934 | 
 935 |     /* Propagating eventual change */
 936 |     if (changed || p->rt_reload)
 937 |     {
 938 |       /*
 939 |        * We have to restart the iteration because there may be a cascade of
 940 |        * synchronous events rip_announce_rte() -> nest table change ->
 941 |        * rip_rt_notify() -> p->rtable change, invalidating hidden variables.
 942 |        */
 943 | 
 944 |       FIB_ITERATE_PUT_NEXT(&fit, &p->rtable);
 945 |       rip_announce_rte(p, en);
 946 |       goto loop;
 947 |     }
 948 | 
 949 |     /* Checking stale entries for garbage collection timeout */
 950 |     if (en->valid == RIP_ENTRY_STALE)
 951 |     {
 952 |       expires = en->changed + cf->max_garbage_time;
 953 | 
 954 |       if (expires <= now_)
 955 |       {
 956 | 	// TRACE(D_EVENTS, "entry is too old: %N", en->n.addr);
 957 | 	en->valid = 0;
 958 |       }
 959 |       else
 960 | 	next = MIN(next, expires);
 961 |     }
 962 | 
 963 |     /* Remove empty nodes */
 964 |     if (!en->valid && !en->routes)
 965 |     {
 966 |       FIB_ITERATE_PUT(&fit);
 967 |       fib_delete(&p->rtable, en);
 968 |       goto loop;
 969 |     }
 970 |   }
 971 |   FIB_ITERATE_END;
 972 | 
 973 |   p->rt_reload = 0;
 974 | 
 975 |   /* Handling neighbor expiration */
 976 |   WALK_LIST(ifa, p->iface_list)
 977 |   {
 978 |     /* No expiration for demand circuit ifaces */
 979 |     if (ifa->cf->demand_circuit)
 980 |       continue;
 981 | 
 982 |     WALK_LIST_DELSAFE(n, nn, ifa->neigh_list)
 983 |       if (n->last_seen)
 984 |       {
 985 | 	expires = n->last_seen + n->ifa->cf->timeout_time;
 986 | 
 987 | 	if (expires <= now_)
 988 | 	  rip_remove_neighbor(p, n);
 989 | 	else
 990 | 	  next = MIN(next, expires);
 991 |       }
 992 |   }
 993 | 
 994 |   tm_start(p->timer, MAX(next - now_, 100 MS));
 995 | }
 996 | 
 997 | static inline void
 998 | rip_kick_timer(struct rip_proto *p)
 999 | {
1000 |   if ((p->timer->expires > (current_time() + 100 MS)))
1001 |     tm_start(p->timer, 100 MS);
1002 | }
1003 | 
1004 | /**
1005 |  * rip_iface_timer - RIP interface timer hook
1006 |  * @t: timer
1007 |  *
1008 |  * RIP interface timers are responsible for scheduling both regular and
1009 |  * triggered updates. Fixed, delay-independent period is used for regular
1010 |  * updates, while minimal separating interval is enforced for triggered updates.
1011 |  * The function also ensures that a new update is not started when the old one
1012 |  * is still running.
1013 |  */
1014 | static void
1015 | rip_iface_timer(timer *t)
1016 | {
1017 |   struct rip_iface *ifa = t->data;
1018 |   struct rip_proto *p = ifa->rip;
1019 |   btime now_ = current_time();
1020 |   btime period = ifa->cf->update_time;
1021 | 
1022 |   if (ifa->cf->passive)
1023 |     return;
1024 | 
1025 |   TRACE(D_EVENTS, "Interface timer fired for %s", ifa->iface->name);
1026 | 
1027 |   if (ifa->tx_active)
1028 |   {
1029 |     tm_start(ifa->timer, 100 MS);
1030 |     return;
1031 |   }
1032 | 
1033 |   if (now_ >= ifa->next_regular)
1034 |   {
1035 |     /* Send regular update, set timer for next period (or following one if necessay) */
1036 |     TRACE(D_EVENTS, "Sending regular updates for %s", ifa->iface->name);
1037 |     rip_send_table(p, ifa, ifa->addr, 0);
1038 |     ifa->next_regular += period * (1 + ((now_ - ifa->next_regular) / period));
1039 |     ifa->want_triggered = 0;
1040 |     p->triggered = 0;
1041 |   }
1042 |   else if (ifa->want_triggered && (now_ >= ifa->next_triggered))
1043 |   {
1044 |     /* Send triggered update, enforce interval between triggered updates */
1045 |     TRACE(D_EVENTS, "Sending triggered updates for %s", ifa->iface->name);
1046 |     rip_send_table(p, ifa, ifa->addr, ifa->want_triggered);
1047 |     ifa->next_triggered = now_ + MIN(5 S, period / 2);
1048 |     ifa->want_triggered = 0;
1049 |     p->triggered = 0;
1050 |   }
1051 | 
1052 |   if (ifa->want_triggered && (ifa->next_triggered < ifa->next_regular))
1053 |     tm_set(ifa->timer, ifa->next_triggered);
1054 |   else if (ifa->next_regular != TIME_INFINITY)
1055 |     tm_set(ifa->timer, ifa->next_regular);
1056 | }
1057 | 
1058 | 
1059 | static inline void
1060 | rip_iface_kick_timer(struct rip_iface *ifa)
1061 | {
1062 |   if ((! tm_active(ifa->timer)) || (ifa->timer->expires > (current_time() + 100 MS)))
1063 |     tm_start(ifa->timer, 100 MS);
1064 | }
1065 | 
1066 | static void
1067 | rip_trigger_update(struct rip_proto *p)
1068 | {
1069 |   if (p->triggered)
1070 |     return;
1071 | 
1072 |   struct rip_iface *ifa;
1073 |   WALK_LIST(ifa, p->iface_list)
1074 |   {
1075 |     /* Interface not active */
1076 |     if (! ifa->up)
1077 |       continue;
1078 | 
1079 |     /* Already scheduled */
1080 |     if (ifa->want_triggered)
1081 |       continue;
1082 | 
1083 |     TRACE(D_EVENTS, "Scheduling triggered updates for %s", ifa->iface->name);
1084 |     ifa->want_triggered = current_time();
1085 |     rip_iface_kick_timer(ifa);
1086 |     p->triggered = 1;
1087 |   }
1088 | }
