259 | static void
260 | static_bfd_notify(struct bfd_request *req);
261 | 
262 | static void
263 | static_update_bfd(struct static_proto *p, struct static_route *r)
264 | {
265 |   /* The @r is a RTD_UNICAST next hop, may be a dummy node */
266 | 
267 |   struct neighbor *nb = r->neigh;
268 |   int bfd_up = (nb->scope > 0) && r->use_bfd;
269 | 
270 |   if (bfd_up && !r->bfd_req)
271 |   {
272 |     // ip_addr local = ipa_nonzero(r->local) ? r->local : nb->ifa->ip;
273 |     r->bfd_req = bfd_request_session(p->p.pool, r->via, nb->ifa->ip,
274 | 				     nb->iface, p->p.vrf,
275 | 				     static_bfd_notify, r, NULL);
276 |   }
277 | 
278 |   if (!bfd_up && r->bfd_req)
279 |   {
280 |     rfree(r->bfd_req);
281 |     r->bfd_req = NULL;
282 |   }
283 | }
284 | 
285 | static int
286 | static_decide(struct static_proto *p, struct static_route *r)
287 | {
288 |   /* The @r is a RTD_UNICAST next hop, may be a dummy node */
289 | 
290 |   struct static_config *cf = (void *) p->p.cf;
291 |   uint old_active = r->active;
292 | 
293 |   if (r->neigh->scope < 0)
294 |     goto fail;
295 | 
296 |   if (cf->check_link && !(r->neigh->iface->flags & IF_LINK_UP))
297 |     goto fail;
298 | 
299 |   if (r->bfd_req && (r->bfd_req->state != BFD_STATE_UP))
300 |     goto fail;
301 | 
302 |   r->active = 1;
303 |   return !old_active;
304 | 
305 | fail:
306 |   r->active = 0;
307 |   return old_active;
308 | }
309 | 
310 | static void
311 | static_add_rte(struct static_proto *p, struct static_route *r)
312 | {
313 |   if (r->dest == RTD_UNICAST)
314 |   {
315 |     struct static_route *r2;
316 |     struct neighbor *n;
317 | 
318 |     for (r2 = r; r2; r2 = r2->mp_next)
319 |     {
320 |       n = neigh_find(&p->p, r2->via, r2->iface, NEF_STICKY |
321 | 		     (r2->onlink ? NEF_ONLINK : 0) |
322 | 		     (ipa_zero(r2->via) ? NEF_IFACE : 0));
323 | 
324 |       if (!n)
325 |       {
326 | 	log(L_WARN "Invalid next hop %I of static route %N", r2->via, r2->net);
327 | 	continue;
328 |       }
329 | 
330 |       r2->neigh = n;
331 |       r2->chain = n->data;
332 |       n->data = r2;
333 | 
334 |       static_update_bfd(p, r2);
335 |       static_decide(p, r2);
336 |     }
337 |   }
338 | 
339 |   static_announce_rte(p, r);
340 | }
341 | 
342 | static void
343 | static_reset_rte(struct static_proto *p UNUSED, struct static_route *r)
344 | {
345 |   struct static_route *r2;
346 | 
347 |   for (r2 = r; r2; r2 = r2->mp_next)
348 |   {
349 |     r2->neigh = NULL;
350 |     r2->chain = NULL;
351 | 
352 |     r2->state = 0;
353 |     r2->active = 0;
354 | 
355 |     rfree(r2->bfd_req);
356 |     r2->bfd_req = NULL;
357 |   }
358 | }
