370 | static inline int
371 | static_same_dest(struct static_route *x, struct static_route *y)
372 | {
373 |   if (x->dest != y->dest)
374 |     return 0;
375 | 
376 |   if (x->net->type == NET_ASPA)
377 |     return adata_same(x->aspa, y->aspa);
378 | 
379 |   switch (x->dest)
380 |   {
381 |   case RTD_UNICAST:
382 |     for (; x && y; x = x->mp_next, y = y->mp_next)
383 |     {
384 |       if (!ipa_equal(x->via, y->via) ||
385 | 	  (x->iface != y->iface) ||
386 | 	  (x->onlink != y->onlink) ||
387 | 	  (x->weight != y->weight) ||
388 | 	  (x->use_bfd != y->use_bfd) ||
389 | 	  (!x->mls != !y->mls) ||
390 | 	  ((x->mls) && (y->mls) && (x->mls->len != y->mls->len)))
391 | 	return 0;
392 | 
393 |       if (!x->mls)
394 | 	continue;
395 | 
396 |       for (uint i = 0; i < x->mls->len; i++)
397 | 	if (x->mls->stack[i] != y->mls->stack[i])
398 | 	  return 0;
399 |     }
400 |     return !x && !y;
401 | 
402 |   case RTDX_RECURSIVE:
403 |     if (!ipa_equal(x->via, y->via) ||
404 | 	(!x->mls != !y->mls) ||
405 | 	((x->mls) && (y->mls) && (x->mls->len != y->mls->len)))
406 |       return 0;
407 | 
408 |     if (!x->mls)
409 |       return 1;
410 | 
411 |     for (uint i = 0; i < x->mls->len; i++)
412 |       if (x->mls->stack[i] != y->mls->stack[i])
413 | 	return 0;
414 | 
415 |     return 1;
416 | 
417 |   default:
418 |     return 1;
419 |   }
420 | }
