656 | static void
657 | static_index_routes(struct static_config *cf)
658 | {
659 |   struct static_route *rt, **buf;
660 |   uint num, i, v;
661 | 
662 |   num = list_length(&cf->routes);
663 |   buf = xmalloc(num * sizeof(void *));
664 | 
665 |   /* Initialize with sequential indexes to ensure stable sorting */
666 |   i = 0;
667 |   WALK_LIST(rt, cf->routes)
668 |   {
669 |     buf[i] = rt;
670 |     rt->index = i++;
671 |   }
672 | 
673 |   qsort(buf, num, sizeof(struct static_route *), srt_compare_qsort);
674 | 
675 |   /* Compute proper indexes - sequential for routes with same network */
676 |   for (i = 0, v = 0, rt = NULL; i < num; i++, v++)
677 |   {
678 |     if (rt && !net_equal(buf[i]->net, rt->net))
679 |       v = 0;
680 | 
681 |     rt = buf[i];
682 |     rt->index = v;
683 |   }
684 | 
685 |   xfree(buf);
686 | }
