688 | static int
689 | static_reconfigure(struct proto *P, struct proto_config *CF)
690 | {
691 |   struct static_proto *p = (void *) P;
692 |   struct static_config *o = (void *) P->cf;
693 |   struct static_config *n = (void *) CF;
694 |   struct static_route *r, *r2, *or, *nr;
695 | 
696 |   /* Check change in IGP tables */
697 |   if ((IGP_TABLE(o, ip4) != IGP_TABLE(n, ip4)) ||
698 |       (IGP_TABLE(o, ip6) != IGP_TABLE(n, ip6)))
699 |     return 0;
700 | 
701 |   if (!proto_configure_channel(P, &P->main_channel, proto_cf_main_channel(CF)) ||
702 |       !proto_configure_channel(P, &P->mpls_channel, proto_cf_mpls_channel(CF)))
703 |     return 0;
704 | 
705 |   proto_setup_mpls_map(P, RTS_STATIC, 1);
706 | 
707 |   p->p.cf = CF;
708 | 
709 |   /* Reset route lists in neighbor entries */
710 |   WALK_LIST(r, o->routes)
711 |     for (r2 = r; r2; r2 = r2->mp_next)
712 |       if (r2->neigh)
713 | 	r2->neigh->data = NULL;
714 | 
715 |   /* Reconfigure initial matching sequence */
716 |   for (or = HEAD(o->routes), nr = HEAD(n->routes);
717 |        NODE_VALID(or) && NODE_VALID(nr) && srt_equal(or, nr);
718 |        or = NODE_NEXT(or), nr = NODE_NEXT(nr))
719 |     static_reconfigure_rte(p, or, nr);
720 | 
721 |   if (!NODE_VALID(or) && !NODE_VALID(nr))
722 |     return 1;
723 | 
724 |   /* Reconfigure remaining routes, sort them to find matching pairs */
725 |   struct static_route *or2, *nr2, **orbuf, **nrbuf;
726 |   uint ornum = 0, nrnum = 0, orpos = 0, nrpos = 0, i;
727 | 
728 |   for (or2 = or; NODE_VALID(or2); or2 = NODE_NEXT(or2))
729 |     ornum++;
730 | 
731 |   for (nr2 = nr; NODE_VALID(nr2); nr2 = NODE_NEXT(nr2))
732 |     nrnum++;
733 | 
734 |   orbuf = xmalloc(ornum * sizeof(void *));
735 |   nrbuf = xmalloc(nrnum * sizeof(void *));
736 | 
737 |   for (i = 0, or2 = or; i < ornum; i++, or2 = NODE_NEXT(or2))
738 |     orbuf[i] = or2;
739 | 
740 |   for (i = 0, nr2 = nr; i < nrnum; i++, nr2 = NODE_NEXT(nr2))
741 |     nrbuf[i] = nr2;
742 | 
743 |   qsort(orbuf, ornum, sizeof(struct static_route *), srt_compare_qsort);
744 |   qsort(nrbuf, nrnum, sizeof(struct static_route *), srt_compare_qsort);
745 | 
746 |   while ((orpos < ornum) && (nrpos < nrnum))
747 |   {
748 |     int x = srt_compare(orbuf[orpos], nrbuf[nrpos]);
749 |     if (x < 0)
750 |       static_remove_rte(p, orbuf[orpos++]);
751 |     else if (x > 0)
752 |       static_add_rte(p, nrbuf[nrpos++]);
753 |     else
754 |       static_reconfigure_rte(p, orbuf[orpos++], nrbuf[nrpos++]);
755 |   }
756 | 
757 |   while (orpos < ornum)
758 |     static_remove_rte(p, orbuf[orpos++]);
759 | 
760 |   while (nrpos < nrnum)
761 |     static_add_rte(p, nrbuf[nrpos++]);
762 | 
763 |   xfree(orbuf);
764 |   xfree(nrbuf);
765 | 
766 |   /* All dirty routes were announced anyways */
767 |   BUFFER_FLUSH(p->marked);
768 |   p->marked_all = 0;
769 | 
770 |   return 1;
771 | }
