 377 | void
 378 | krt_replace_rte(struct krt_proto *p, net *n UNUSED, rte *new, rte *old)
 379 | {
 380 |   int err = 0;
 381 | 
 382 |   if (old)
 383 |     krt_send_route(p, RTM_DELETE, old);
 384 | 
 385 |   if (new)
 386 |     err = krt_send_route(p, RTM_ADD, new);
 387 | 
 388 |   if (new)
 389 |   {
 390 |     if (err < 0)
 391 |       bmap_clear(&p->sync_map, new->id);
 392 |     else
 393 |       bmap_set(&p->sync_map, new->id);
 394 |   }
 395 | }
