 397 | #define SKIP(ARG...) do { DBG("KRT: Ignoring route - " ARG); return; } while(0)
 398 | 
 399 | static void
 400 | krt_read_route(struct ks_msg *msg, struct krt_proto *p, int scan)
 401 | {
 402 |   /* p is NULL iff KRT_SHARED_SOCKET and !scan */
 403 | 
 404 |   int ipv6;
 405 |   rte *e;
 406 |   net *net;
 407 |   sockaddr dst, gate, mask;
 408 |   ip_addr idst, igate, imask;
 409 |   net_addr ndst;
 410 |   void *body = (char *)msg->buf;
 411 |   int new = (msg->rtm.rtm_type != RTM_DELETE);
 412 |   char *errmsg = "KRT: Invalid route received";
 413 |   int flags = msg->rtm.rtm_flags;
 414 |   int addrs = msg->rtm.rtm_addrs;
 415 |   int src;
 416 |   byte src2;
 417 | 
 418 |   if (!(flags & RTF_UP) && scan)
 419 |     SKIP("not up in scan\n");
 420 | 
 421 |   if (!(flags & RTF_DONE) && !scan)
 422 |     SKIP("not done in async\n");
 423 | 
 424 | #ifdef RTF_LLINFO
 425 |   /* Obsolete in FreeBSD and NetBSD, still used in OpenBSD */
 426 |   if (flags & RTF_LLINFO)
 427 |     SKIP("link-local\n");
 428 | #endif
 429 | 
 430 | #ifdef RTF_LLDATA
 431 |   /* Reported by NetBSD */
 432 |   if (flags & RTF_LLDATA)
 433 |     SKIP("link-local\n");
 434 | #endif
 435 | 
 436 |   GETADDR(&dst, RTA_DST);
 437 |   GETADDR(&gate, RTA_GATEWAY);
 438 |   GETADDR(&mask, RTA_NETMASK);
 439 | 
 440 |   switch (dst.sa.sa_family) {
 441 |     case AF_INET:
 442 |       ipv6 = 0;
 443 |       break;
 444 |     case AF_INET6:
 445 |       ipv6 = 1;
 446 |       break;
 447 |     default:
 448 |       SKIP("invalid DST");
 449 |   }
 450 | 
 451 |   /* We do not test family for RTA_NETMASK, because BSD sends us
 452 |      some strange values, but interpreting them as IPv4/IPv6 works */
 453 |   mask.sa.sa_family = dst.sa.sa_family;
 454 | 
 455 |   idst  = ipa_from_sa(&dst);
 456 |   imask = ipa_from_sa(&mask);
 457 |   igate = ipa_from_sa(&gate);
 458 | 
 459 | #ifdef KRT_SHARED_SOCKET
 460 |   if (!scan)
 461 |   {
 462 |     int table_id = msg->rtm.rtm_tableid;
 463 |     p = (table_id < KRT_MAX_TABLES) ? krt_table_map[table_id][ipv6] : NULL;
 464 | 
 465 |     if (!p)
 466 |       SKIP("unknown table id %d\n", table_id);
 467 |   }
 468 | #endif
 469 |   if ((!ipv6) && (p->p.main_channel->table->addr_type != NET_IP4))
 470 |     SKIP("reading only IPv4 routes");
 471 |   if (  ipv6  && (p->p.main_channel->table->addr_type != NET_IP6))
 472 |     SKIP("reading only IPv6 routes");
 473 | 
 474 |   int c = ipa_classify_net(idst);
 475 |   if ((c < 0) || !(c & IADDR_HOST) || ((c & IADDR_SCOPE_MASK) <= SCOPE_LINK))
 476 |     SKIP("strange class/scope\n");
 477 | 
 478 |   int pxlen;
 479 |   if (ipv6)
 480 |     pxlen = (flags & RTF_HOST) ? IP6_MAX_PREFIX_LENGTH : ip6_masklen(&ipa_to_ip6(imask));
 481 |   else
 482 |     pxlen = (flags & RTF_HOST) ? IP4_MAX_PREFIX_LENGTH : ip4_masklen(ipa_to_ip4(imask));
 483 | 
 484 |   if (pxlen < 0)
 485 |     { log(L_ERR "%s (%I) - netmask %I", errmsg, idst, imask); return; }
 486 | 
 487 |   if (ipv6)
 488 |     net_fill_ip6(&ndst, ipa_to_ip6(idst), pxlen);
 489 |   else
 490 |     net_fill_ip4(&ndst, ipa_to_ip4(idst), pxlen);
 491 | 
 492 |   if ((flags & RTF_GATEWAY) && ipa_zero(igate))
 493 |     { log(L_ERR "%s (%N) - missing gateway", errmsg, &ndst); return; }
 494 | 
 495 |   u32 self_mask = RTF_PROTO1;
 496 |   u32 alien_mask = RTF_STATIC | RTF_PROTO1 | RTF_GATEWAY;
 497 | 
 498 |   src2 = (flags & RTF_STATIC) ? 1 : 0;
 499 |   src2 |= (flags & RTF_PROTO1) ? 2 : 0;
 500 | 
 501 | #ifdef RTF_PROTO2
 502 |   alien_mask |= RTF_PROTO2;
 503 |   src2 |= (flags & RTF_PROTO2) ? 4 : 0;
 504 | #endif
 505 | 
 506 | #ifdef RTF_PROTO3
 507 |   alien_mask |= RTF_PROTO3;
 508 |   src2 |= (flags & RTF_PROTO3) ? 8 : 0;
 509 | #endif
 510 | 
 511 | #ifdef RTF_REJECT
 512 |   alien_mask |= RTF_REJECT;
 513 | #endif
 514 | 
 515 | #ifdef RTF_BLACKHOLE
 516 |   alien_mask |= RTF_BLACKHOLE;
 517 | #endif
 518 | 
 519 |   if (flags & (RTF_DYNAMIC | RTF_MODIFIED))
 520 |     src = KRT_SRC_REDIRECT;
 521 |   else if (flags & self_mask)
 522 |     {
 523 |       if (!scan)
 524 | 	SKIP("echo\n");
 525 |       src = KRT_SRC_BIRD;
 526 |     }
 527 |   else if (flags & alien_mask)
 528 |     src = KRT_SRC_ALIEN;
 529 |   else
 530 |     src = KRT_SRC_KERNEL;
 531 | 
 532 |   net = net_get(p->p.main_channel->table, &ndst);
 533 | 
 534 |   rta a = {
 535 |     .source = RTS_INHERIT,
 536 |     .scope = SCOPE_UNIVERSE,
 537 |   };
 538 | 
 539 |   /* reject/blackhole routes have also set RTF_GATEWAY,
 540 |      we wil check them first. */
 541 | 
 542 | #ifdef RTF_REJECT
 543 |   if(flags & RTF_REJECT) {
 544 |     a.dest = RTD_UNREACHABLE;
 545 |     goto done;
 546 |   }
 547 | #endif
 548 | 
 549 | #ifdef RTF_BLACKHOLE
 550 |   if(flags & RTF_BLACKHOLE) {
 551 |     a.dest = RTD_BLACKHOLE;
 552 |     goto done;
 553 |   }
 554 | #endif
 555 | 
 556 |   a.nh.iface = if_find_by_index(msg->rtm.rtm_index);
 557 |   if (!a.nh.iface)
 558 |     {
 559 |       log(L_ERR "KRT: Received route %N with unknown ifindex %u",
 560 | 	  net->n.addr, msg->rtm.rtm_index);
 561 |       return;
 562 |     }
 563 | 
 564 |   a.dest = RTD_UNICAST;
 565 |   if (flags & RTF_GATEWAY)
 566 |   {
 567 |     a.nh.gw = igate;
 568 | 
 569 |     /* Clean up embedded interface ID returned in link-local address */
 570 |     if (ipa_is_link_local(a.nh.gw))
 571 |       _I0(a.nh.gw) = 0xfe800000;
 572 | 
 573 |     /* The BSD kernel does not support an onlink flag. We heuristically
 574 |        set the onlink flag, if the iface has only host addresses. */
 575 |     if (krt_assume_onlink(a.nh.iface, ipv6))
 576 |       a.nh.flags |= RNF_ONLINK;
 577 | 
 578 |     neighbor *nbr;
 579 |     nbr = neigh_find(&p->p, a.nh.gw, a.nh.iface,
 580 | 		    (a.nh.flags & RNF_ONLINK) ? NEF_ONLINK : 0);
 581 |     if (!nbr || (nbr->scope == SCOPE_HOST))
 582 |       {
 583 | 	/* Ignore routes with next-hop 127.0.0.1, host routes with such
 584 | 	   next-hop appear on OpenBSD for address aliases. */
 585 |         if (ipa_classify(a.nh.gw) == (IADDR_HOST | SCOPE_HOST))
 586 |           return;
 587 | 
 588 | 	log(L_ERR "KRT: Received route %N with strange next-hop %I",
 589 | 	    net->n.addr, a.nh.gw);
 590 | 	return;
 591 |       }
 592 |   }
 593 | 
 594 |  done:
 595 |   e = rte_get_temp(&a, p->p.main_source);
 596 |   e->net = net;
 597 | 
 598 |   ea_list *ea = alloca(sizeof(ea_list) + 2 * sizeof(eattr));
 599 |   *ea = (ea_list) { .count = 1, .next = e->attrs->eattrs };
 600 |   e->attrs->eattrs = ea;
 601 | 
 602 |   ea->attrs[0] = (eattr) {
 603 |     .id = EA_KRT_SOURCE,
 604 |     .type = EAF_TYPE_INT,
 605 |     .u.data = src2,
 606 |   };
 607 | 
 608 | #ifdef KRT_USE_METRIC
 609 |   ea->count++;
 610 |   ea->attrs[1] = (eattr) {
 611 |     .id = EA_KRT_METRIC,
 612 |     .type = EAF_TYPE_INT,
 613 |     .u.data = msg->rtm.rtm_priority,
 614 |   };
 615 | #endif
 616 | 
 617 |   if (scan)
 618 |     krt_got_route(p, e, src);
 619 |   else
 620 |     krt_got_route_async(p, e, new, src);
 621 | }
