 623 | static void
 624 | krt_read_ifannounce(struct ks_msg *msg)
 625 | {
 626 |   struct if_announcemsghdr *ifam = (struct if_announcemsghdr *)&msg->rtm;
 627 | 
 628 |   if (ifam->ifan_what == IFAN_ARRIVAL)
 629 |   {
 630 |     /* Not enough info to create the iface, so we just trigger iface scan */
 631 |     kif_request_scan();
 632 |   }
 633 |   else if (ifam->ifan_what == IFAN_DEPARTURE)
 634 |   {
 635 |     struct iface *iface = if_find_by_index(ifam->ifan_index);
 636 | 
 637 |     /* Interface is destroyed */
 638 |     if (!iface)
 639 |     {
 640 |       DBG("KRT: unknown interface (%s, #%d) going down. Ignoring\n", ifam->ifan_name, ifam->ifan_index);
 641 |       return;
 642 |     }
 643 | 
 644 |     if_delete(iface);
 645 |   }
 646 | 
 647 |   DBG("KRT: IFANNOUNCE what: %d index %d name %s\n", ifam->ifan_what, ifam->ifan_index, ifam->ifan_name);
 648 | }
