 650 | static void
 651 | krt_read_ifinfo(struct ks_msg *msg, int scan)
 652 | {
 653 |   struct if_msghdr *ifm = (struct if_msghdr *)&msg->rtm;
 654 |   void *body = (void *)(ifm + 1);
 655 |   struct sockaddr_dl *dl = NULL;
 656 |   uint i;
 657 |   struct iface *iface = NULL, f = {};
 658 |   int fl = ifm->ifm_flags;
 659 |   int nlen = 0;
 660 | 
 661 |   for (i = 1; i<=RTA_IFP; i <<= 1)
 662 |   {
 663 |     if (i & ifm->ifm_addrs)
 664 |     {
 665 |       if (i == RTA_IFP)
 666 |       {
 667 |         dl = (struct sockaddr_dl *)body;
 668 |         break;
 669 |       }
 670 |       body += ROUNDUP(((struct sockaddr *)&(body))->sa_len);
 671 |     }
 672 |   }
 673 | 
 674 |   if (dl && (dl->sdl_family != AF_LINK))
 675 |   {
 676 |     log(L_WARN "Ignoring strange IFINFO");
 677 |     return;
 678 |   }
 679 | 
 680 |   if (dl)
 681 |     nlen = MIN(sizeof(f.name)-1, dl->sdl_nlen);
 682 | 
 683 |   /* Note that asynchronous IFINFO messages do not contain iface
 684 |      name, so we have to found an existing iface by iface index */
 685 | 
 686 |   iface = if_find_by_index(ifm->ifm_index);
 687 |   if (!iface)
 688 |   {
 689 |     /* New interface */
 690 |     if (!dl)
 691 |       return;	/* No interface name, ignoring */
 692 | 
 693 |     memcpy(f.name, dl->sdl_data, nlen);
 694 |     DBG("New interface '%s' found\n", f.name);
 695 |   }
 696 |   else if (dl && memcmp(iface->name, dl->sdl_data, nlen))
 697 |   {
 698 |     /* Interface renamed */
 699 |     if_delete(iface);
 700 |     memcpy(f.name, dl->sdl_data, nlen);
 701 |   }
 702 |   else
 703 |   {
 704 |     /* Old interface */
 705 |     memcpy(f.name, iface->name, sizeof(f.name));
 706 |   }
 707 | 
 708 |   f.index = ifm->ifm_index;
 709 |   f.mtu = ifm->ifm_data.ifi_mtu;
 710 | 
 711 |   if (fl & IFF_UP)
 712 |     f.flags |= IF_ADMIN_UP;
 713 |   if (ifm->ifm_data.ifi_link_state != LINK_STATE_DOWN)
 714 |     f.flags |= IF_LINK_UP;          /* up or unknown */
 715 |   if (fl & IFF_LOOPBACK)            /* Loopback */
 716 |     f.flags |= IF_MULTIACCESS | IF_LOOPBACK | IF_IGNORE;
 717 |   else if (fl & IFF_POINTOPOINT)    /* PtP */
 718 |     f.flags |= IF_MULTICAST;
 719 |   else if (fl & IFF_BROADCAST)      /* Broadcast */
 720 |     f.flags |= IF_MULTIACCESS | IF_BROADCAST | IF_MULTICAST;
 721 |   else
 722 |     f.flags |= IF_MULTIACCESS;      /* NBMA */
 723 | 
 724 |   if (fl & IFF_MULTICAST)
 725 |     f.flags |= IF_MULTICAST;
 726 | 
 727 |   iface = if_update(&f);
 728 | 
 729 |   if (!scan)
 730 |     if_end_partial_update(iface);
 731 | }
