 733 | static void
 734 | krt_read_addr(struct ks_msg *msg, int scan)
 735 | {
 736 |   struct ifa_msghdr *ifam = (struct ifa_msghdr *)&msg->rtm;
 737 |   void *body = (void *)(ifam + 1);
 738 |   sockaddr addr, mask, brd;
 739 |   struct iface *iface = NULL;
 740 |   struct ifa ifa;
 741 |   struct sockaddr null;
 742 |   ip_addr iaddr, imask, ibrd;
 743 |   int addrs = ifam->ifam_addrs;
 744 |   int scope, masklen = -1;
 745 |   int new = (ifam->ifam_type == RTM_NEWADDR);
 746 | 
 747 |   /* Strange messages with zero (invalid) ifindex appear on OpenBSD */
 748 |   if (ifam->ifam_index == 0)
 749 |     return;
 750 | 
 751 |   if(!(iface = if_find_by_index(ifam->ifam_index)))
 752 |   {
 753 |     log(L_ERR "KIF: Received address message for unknown interface %d", ifam->ifam_index);
 754 |     return;
 755 |   }
 756 | 
 757 |   GETADDR (&null, RTA_DST);
 758 |   GETADDR (&null, RTA_GATEWAY);
 759 |   GETADDR (&mask, RTA_NETMASK);
 760 |   GETADDR (&null, RTA_GENMASK);
 761 |   GETADDR (&null, RTA_IFP);
 762 |   GETADDR (&addr, RTA_IFA);
 763 |   GETADDR (&null, RTA_AUTHOR);
 764 |   GETADDR (&brd, RTA_BRD);
 765 | 
 766 |   /* Is addr family IP4 or IP6? */
 767 |   int ipv6;
 768 |   switch (addr.sa.sa_family) {
 769 |     case AF_INET: ipv6 = 0; break;
 770 |     case AF_INET6: ipv6 = 1; break;
 771 |     default: return;
 772 |   }
 773 | 
 774 |   /* We do not test family for RTA_NETMASK, because BSD sends us
 775 |      some strange values, but interpreting them as IPv4/IPv6 works */
 776 |   mask.sa.sa_family = addr.sa.sa_family;
 777 | 
 778 |   iaddr = ipa_from_sa(&addr);
 779 |   imask = ipa_from_sa(&mask);
 780 |   ibrd  = ipa_from_sa(&brd);
 781 | 
 782 |   if ((ipv6 ? (masklen = ip6_masklen(&ipa_to_ip6(imask))) : (masklen = ip4_masklen(ipa_to_ip4(imask)))) < 0)
 783 |   {
 784 |     log(L_ERR "KIF: Invalid mask %I for %s", imask, iface->name);
 785 |     return;
 786 |   }
 787 | 
 788 |   /* Clean up embedded interface ID returned in link-local address */
 789 | 
 790 |   if (ipa_is_link_local(iaddr))
 791 |     _I0(iaddr) = 0xfe800000;
 792 | 
 793 |   if (ipa_is_link_local(ibrd))
 794 |     _I0(ibrd) = 0xfe800000;
 795 | 
 796 | 
 797 |   bzero(&ifa, sizeof(ifa));
 798 |   ifa.iface = iface;
 799 |   ifa.ip = iaddr;
 800 | 
 801 |   scope = ipa_classify(ifa.ip);
 802 |   if (scope < 0)
 803 |   {
 804 |     log(L_ERR "KIF: Invalid interface address %I for %s", ifa.ip, iface->name);
 805 |     return;
 806 |   }
 807 |   ifa.scope = scope & IADDR_SCOPE_MASK;
 808 | 
 809 |   if (masklen < (ipv6 ? IP6_MAX_PREFIX_LENGTH : IP4_MAX_PREFIX_LENGTH))
 810 |   {
 811 |     net_fill_ipa(&ifa.prefix, ifa.ip, masklen);
 812 |     net_normalize(&ifa.prefix);
 813 | 
 814 |     if (masklen == ((ipv6 ? IP6_MAX_PREFIX_LENGTH : IP4_MAX_PREFIX_LENGTH) - 1))
 815 |       ifa.opposite = ipa_opposite_m1(ifa.ip);
 816 | 
 817 |     if ((!ipv6) && (masklen == IP4_MAX_PREFIX_LENGTH - 2))
 818 |       ifa.opposite = ipa_opposite_m2(ifa.ip);
 819 | 
 820 |     if (iface->flags & IF_BROADCAST)
 821 |       ifa.brd = ibrd;
 822 | 
 823 |     if (!(iface->flags & IF_MULTIACCESS))
 824 |       ifa.opposite = ibrd;
 825 |   }
 826 |   else if (!(iface->flags & IF_MULTIACCESS) && ipa_nonzero(ibrd))
 827 |   {
 828 |     net_fill_ipa(&ifa.prefix, ibrd, (ipv6 ? IP6_MAX_PREFIX_LENGTH : IP4_MAX_PREFIX_LENGTH));
 829 |     ifa.opposite = ibrd;
 830 |     ifa.flags |= IA_PEER;
 831 |   }
 832 |   else
 833 |   {
 834 |     net_fill_ipa(&ifa.prefix, ifa.ip, (ipv6 ? IP6_MAX_PREFIX_LENGTH : IP4_MAX_PREFIX_LENGTH));
 835 |     ifa.flags |= IA_HOST;
 836 |   }
 837 | 
 838 |   if (new)
 839 |     ifa_update(&ifa);
 840 |   else
 841 |     ifa_delete(&ifa);
 842 | 
 843 |   if (!scan)
 844 |     if_end_partial_update(iface);
 845 | }
