 847 | static void
 848 | krt_read_msg(struct proto *p, struct ks_msg *msg, int scan)
 849 | {
 850 |   /* p is NULL iff KRT_SHARED_SOCKET and !scan */
 851 | 
 852 |   switch (msg->rtm.rtm_type)
 853 |   {
 854 |     case RTM_GET:
 855 |       if (!scan) return;
 856 |       /* fallthrough */
 857 |     case RTM_ADD:
 858 |     case RTM_DELETE:
 859 |     case RTM_CHANGE:
 860 |       krt_read_route(msg, (struct krt_proto *)p, scan);
 861 |       break;
 862 |     case RTM_IFANNOUNCE:
 863 |       krt_read_ifannounce(msg);
 864 |       break;
 865 |     case RTM_IFINFO:
 866 |       krt_read_ifinfo(msg, scan);
 867 |       break;
 868 |     case RTM_NEWADDR:
 869 |     case RTM_DELADDR:
 870 |       krt_read_addr(msg, scan);
 871 |       break;
 872 |     default:
 873 |       break;
 874 |   }
