 878 | /* Sysctl based scans */
 879 | 
 880 | static byte *krt_buffer;
 881 | static size_t krt_buflen, krt_bufmin;
 882 | static struct proto *krt_buffer_owner;
 883 | 
 884 | static byte *
 885 | krt_buffer_update(struct proto *p, size_t *needed)
 886 | {
 887 |   size_t req = *needed;
 888 | 
 889 |   if ((req > krt_buflen) ||
 890 |       ((p == krt_buffer_owner) && (req < krt_bufmin)))
 891 |   {
 892 |     /* min buflen is 32 kB, step is 8 kB, or 128 kB if > 1 MB */
 893 |     size_t step = (req < 0x100000) ? 0x2000 : 0x20000;
 894 |     krt_buflen = (req < 0x6000) ? 0x8000 : (req + step);
 895 |     krt_bufmin = (req < 0x8000) ? 0 : (req - 2*step);
 896 | 
 897 |     if (krt_buffer) 
 898 |       mb_free(krt_buffer);
 899 |     krt_buffer = mb_alloc(krt_pool, krt_buflen);
 900 |     krt_buffer_owner = p;
 901 |   }
 902 | 
 903 |   *needed = krt_buflen;
 904 |   return krt_buffer;
 905 | }
 906 | 
 907 | static void
 908 | krt_buffer_release(struct proto *p)
 909 | {
 910 |   if (p == krt_buffer_owner)
 911 |   {
 912 |     mb_free(krt_buffer);
 913 |     krt_buffer = NULL;
 914 |     krt_buflen = 0;
 915 |     krt_buffer_owner = 0;
 916 |   }
 917 | }
