 919 | static void
 920 | krt_sysctl_scan(struct proto *p, int cmd, int table_id)
 921 | {
 922 |   byte *buf, *next;
 923 |   int mib[7], mcnt;
 924 |   size_t needed;
 925 |   struct ks_msg *m;
 926 |   int retries = 3;
 927 |   int rv;
 928 | 
 929 |   mib[0] = CTL_NET;
 930 |   mib[1] = PF_ROUTE;
 931 |   mib[2] = 0;
 932 |   mib[3] = 0; // Set AF to 0 for all available families
 933 |   mib[4] = cmd;
 934 |   mib[5] = 0;
 935 |   mcnt = 6;
 936 | 
 937 | #ifdef KRT_USE_SYSCTL_7
 938 |   if (table_id >= 0)
 939 |   {
 940 |     mib[6] = table_id;
 941 |     mcnt = 7;
 942 |   }
 943 | #endif
 944 | 
 945 | #ifdef KRT_USE_SETFIB_SCAN
 946 |   if (table_id > 0)
 947 |     if (setfib(table_id) < 0)
 948 |     {
 949 |       log(L_ERR "KRT: setfib(%d) failed: %m", table_id);
 950 |       return;
 951 |     }
 952 | #endif
 953 | 
 954 |  try:
 955 |   rv = sysctl(mib, mcnt, NULL, &needed, NULL, 0);
 956 |   if (rv < 0)
 957 |   {
 958 |     /* OpenBSD returns EINVAL for not yet used tables */
 959 |     if ((errno == EINVAL) && (table_id > 0))
 960 |       goto exit;
 961 | 
 962 |     log(L_ERR "KRT: Route scan estimate failed: %m");
 963 |     goto exit;
 964 |   }
 965 | 
 966 |   /* The table is empty */
 967 |   if (needed == 0)
 968 |     goto exit;
 969 | 
 970 |   buf = krt_buffer_update(p, &needed);
 971 | 
 972 |   rv = sysctl(mib, mcnt, buf, &needed, NULL, 0);
 973 |   if (rv < 0)
 974 |   {
 975 |     /* The buffer size changed since last sysctl ('needed' is not changed) */
 976 |     if ((errno == ENOMEM) && retries--)
 977 |       goto try;
 978 | 
 979 |     log(L_ERR "KRT: Route scan failed: %m");
 980 |     goto exit;
 981 |   }
 982 | 
 983 | #ifdef KRT_USE_SETFIB_SCAN
 984 |   if (table_id > 0)
 985 |     if (setfib(0) < 0)
 986 |       die("KRT: setfib(%d) failed: %m", 0);
 987 | #endif
 988 | 
 989 |   /* Process received messages */
 990 |   for (next = buf; next < (buf + needed); next += m->rtm.rtm_msglen)
 991 |   {
 992 |     m = (struct ks_msg *)next;
 993 |     krt_read_msg(p, m, 1);
 994 |   }
 995 | 
 996 |   return;
 997 | 
 998 |  exit:
 999 |   krt_buffer_release(p);
1000 | 
1001 | #ifdef KRT_USE_SETFIB_SCAN
1002 |   if (table_id > 0)
1003 |     if (setfib(0) < 0)
1004 |       die("KRT: setfib(%d) failed: %m", 0);
1005 | #endif
1006 | }
