1026 | krt_sock_hook(sock *sk, uint size UNUSED)
1027 | {
1028 |   struct ks_msg msg;
1029 |   int l = read(sk->fd, (char *)&msg, sizeof(msg));
1030 | 
1031 |   if (l <= 0)
1032 |     log(L_ERR "krt-sock: read failed");
1033 |   else
