1045 | static sock *
1046 | krt_sock_open(pool *pool, void *data, int table_id UNUSED)
1047 | {
1048 |   sock *sk;
1049 |   int fd;
1050 | 
1051 |   fd = socket(PF_ROUTE, SOCK_RAW, AF_UNSPEC);
1052 |   if (fd < 0)
1053 |     die("Cannot open kernel socket for routes");
1054 | 
1055 | #ifdef KRT_USE_SETFIB_SOCK
1056 |   if (table_id > 0)
1057 |   {
1058 |     if (setsockopt(fd, SOL_SOCKET, SO_SETFIB, &table_id, sizeof(table_id)) < 0)
1059 |       die("Cannot set FIB %d for kernel socket: %m", table_id);
1060 |   }
1061 | #endif
1062 | 
1063 |   sk = sk_new(pool);
1064 |   sk->type = SK_MAGIC;
1065 |   sk->rx_hook = krt_sock_hook;
1066 |   sk->err_hook = krt_sock_err_hook;
1067 |   sk->fd = fd;
1068 |   sk->data = data;
1069 | 
1070 |   if (sk_open(sk) < 0)
1071 |     bug("krt-sock: sk_open failed");
1072 | 
1073 |   return sk;
