 52 |   { .imr_multiaddr = ipa_to_in4(maddr), .imr_ifindex = ifa->index }
 53 | 
 54 | static inline int
 55 | sk_setup_multicast4(sock *s)
 56 | {
 57 |   struct ip_mreqn mr = { .imr_ifindex = s->iface->index };
 58 |   int ttl = s->ttl;
 59 |   int n = 0;
 60 | 
 61 |   /* This defines where should we send _outgoing_ multicasts */
 62 |   if (setsockopt(s->fd, SOL_IP, IP_MULTICAST_IF, &mr, sizeof(mr)) < 0)
 63 |     ERR("IP_MULTICAST_IF");
 64 | 
 65 |   if (setsockopt(s->fd, SOL_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0)
 66 |     ERR("IP_MULTICAST_TTL");
 67 | 
 68 |   if (setsockopt(s->fd, SOL_IP, IP_MULTICAST_LOOP, &n, sizeof(n)) < 0)
 69 |     ERR("IP_MULTICAST_LOOP");
 70 | 
 71 |   return 0;
