 74 | static inline int
 75 | sk_join_group4(sock *s, ip_addr maddr)
 76 | {
 77 |   struct ip_mreqn mr = INIT_MREQ4(maddr, s->iface);
 78 | 
 79 |   if (setsockopt(s->fd, SOL_IP, IP_ADD_MEMBERSHIP, &mr, sizeof(mr)) < 0)
