263 | /**
264 |  * sk_add_ao_key - Add TCP-AO key to the socket
265 |  * @s: Socket
266 |  * @prefix: Prefix
267 |  * @pxlen: Prefix length (or -1 for max)
268 |  * @ifa: Interface (for IPv6 link-local prefix)
269 |  * @key: TCP-AO key to be added
270 |  * @current: Set the new key as current key
271 |  * @rnext: Set the new key as rnext key
272 |  *
273 |  * The function adds the TCP-AO key @key to the kernel list of TCP-AO keys
274 |  * associated with the socket. There can be multiple sets of keys for different
275 |  * peers (for a listening socket), therefore the key is accompanied with the
276 |  * relevant prefix (consists of @prefix, @pxlen, and @ifa).
277 |  *
278 |  * Result: 0 when successful, -1 for an error.
279 |  */
280 | int
281 | sk_add_ao_key(sock *s, ip_addr prefix, int pxlen, struct iface *ifa, const struct ao_key *key, bool current, bool rnext)
282 | {
283 |   if (pxlen < 0)
284 |     pxlen = (s->af == AF_INET) ? IP4_MAX_PREFIX_LENGTH : IP6_MAX_PREFIX_LENGTH;
285 | 
286 |   struct tcp_ao_add_ext ao = {};
287 |   sockaddr_fill((sockaddr *) &ao.addr, s->af, prefix, ifa, 0);
288 |   ao.prefix = pxlen;
289 |   ao.sndid = key->send_id;
290 |   ao.rcvid = key->recv_id;
291 |   ao.set_current = current;
292 |   ao.set_rnext = rnext;
293 | 
294 |   if (!tcp_ao_alg_known(key->algorithm))
295 |     ERR_MSG("Unknown TCP-AO algorithm");
296 | 
297 |   strncpy(ao.alg_name, tcp_ao_alg_names[key->algorithm], sizeof(ao.alg_name));
298 |   ao.keylen = key->keylen;
299 |   memcpy(ao.key, key->key, MIN(key->keylen, TCP_AO_MAXKEYLEN_));
300 | 
301 |   if (setsockopt(s->fd, IPPROTO_TCP, TCP_AO_ADD_KEY, &ao, sizeof(ao)) < 0)
302 |   {
303 |     if (errno == ENOPROTOOPT)
304 |       ERR_MSG("Kernel does not support TCP-AO signatures");
305 |     else
306 |       ERR("TCP_AO_ADD_KEY");
307 |   }
308 | 
309 |   return 0;
310 | }
