312 | /**
313 |  * sk_delete_ao_key - Delete TCP-AO key from the socket
314 |  * @s: Socket
315 |  * @prefix: Prefix
316 |  * @pxlen: Prefix length (or -1 for max)
317 |  * @ifa: Interface (for IPv6 link-local prefix)
318 |  * @key: TCP-AO key to be deleted
319 |  * @current: Optionally set current key
320 |  * @rnext: Optionally set rnext key
321 |  *
322 |  * The function removes the TCP-AO key @key from the kernel list of TCP-AO keys
323 |  * associated with the socket. There can be multiple sets of keys for different
324 |  * peers, therefore the key for deletion is identified not only by its send/recv
325 |  * ID, but also by the relevant prefix (consists of @prefix, @pxlen, and @ifa).
326 |  * Keys on incoming sockets that were cloned from the listening socket use the
327 |  * same prefix as on the listening socket.
328 |  *
329 |  * Optionally, the current key and the rnext key can be set atomically together
330 |  * with the deletion, avoiding failure when the deleted key is current / rnext.
331 |  *
332 |  * Result: 0 when successful, -1 for an error.
333 |  */
334 | int
335 | sk_delete_ao_key(sock *s, ip_addr prefix, int pxlen, struct iface *ifa, const struct ao_key *key, const struct ao_key *current, const struct ao_key *rnext)
336 | {
337 |   if (pxlen < 0)
338 |     pxlen = (s->af == AF_INET) ? IP4_MAX_PREFIX_LENGTH : IP6_MAX_PREFIX_LENGTH;
339 | 
340 |   struct tcp_ao_del_ext ao = {};
341 |   sockaddr_fill((sockaddr *) &ao.addr, s->af, prefix, ifa, 0);
342 |   ao.prefix = pxlen;
343 |   ao.sndid = key->send_id;
344 |   ao.rcvid = key->recv_id;
345 | 
346 |   if (current)
347 |   {
348 |     ao.set_current = 1;
349 |     ao.current_key = current->send_id;
350 |   }
351 | 
352 |   if (rnext)
353 |   {
354 |     ao.set_rnext = 1;
355 |     ao.rnext = rnext->recv_id;
356 |   }
357 | 
358 |   if (setsockopt(s->fd, IPPROTO_TCP, TCP_AO_DEL_KEY, &ao, sizeof(ao)) < 0)
359 |     ERR("TCP_AO_DEL_KEY");
360 | 
361 |   return 0;
362 | }
