388 | /**
389 |  * sk_check_ao_keys - Check TCP-AO keys on socket against a list of expected keys
390 |  * @s: Socket
391 |  * @keys: Array of keys
392 |  * @num: Number of keys
393 |  * @name: Name of caller, prefix for error messages
394 |  *
395 |  * The function reads TCP-AO keys from the kernel and compares them to the
396 |  * provided set of keys. When inconsistencies are found, they are logged and the
397 |  * function reports the error. This is useful for fds received from accept(), to
398 |  * avoid race conditions when keys are cloned from the listening fd.
399 |  *
400 |  * Result: 0 when consistent, -1 for an error.
401 |  */
402 | int
403 | sk_check_ao_keys(sock *s, const struct ao_key **keys, int num, const char *name)
404 | {
405 |   u32 expected_keys[256 / 32];
406 |   u8 key_pos[256];
407 |   int errors = 0;
408 | 
409 |   BIT32_ZERO(expected_keys, 256);
410 |   for (int i = 0; i < num; i++)
411 |   {
412 |     int id = keys[i]->send_id;
413 |     BIT32_SET(expected_keys, id);
414 |     key_pos[id] = i;
415 |   }
416 | 
417 |   struct tcp_ao_getsockopt_ext *sk_keys;
418 |   int sk_keys_num;
419 | 
420 |   if (sk_get_ao_keys(s, &sk_keys, &sk_keys_num) < 0)
421 |   {
422 |     sk_log_error(s, name);
423 |     return -1;
424 |   }
425 | 
426 |   for (int i = 0; i < sk_keys_num; i++)
427 |   {
428 |     const struct tcp_ao_getsockopt_ext *key = &sk_keys[i];
429 | 
430 |     if (!BIT32_TEST(expected_keys, key->sndid) ||
431 | 	(key->rcvid != keys[key_pos[key->sndid]]->recv_id))
432 |     {
433 |       log(L_WARN "%s: Unexpected TCP-AO key %i/%i found on socket",
434 | 	  name, key->sndid, key->rcvid);
435 |       errors++;
436 |       continue;
437 |     }
438 | 
439 |     BIT32_CLR(expected_keys, key->sndid);
440 |   }
441 | 
442 |   if (!errors && (sk_keys_num == num))
443 |     return 0;
444 | 
445 |   for (int i = 0; i < 256; i++)
446 |   {
447 |     if (BIT32_TEST(expected_keys, i))
448 |     {
449 |       const struct ao_key *key = keys[key_pos[i]];
450 |       log(L_WARN "%s: Expected TCP-AO key %i/%i not found on socket",
451 | 	  name, key->send_id, key->recv_id);
452 |       errors++;
453 |     }
454 |   }
455 | 
456 |   return errors ? -1 : 0;
457 | }
