 138 | 
 139 | struct dump_request_file {
 140 |   struct dump_request dr;
 141 |   uint pos, max; int fd;
 142 |   uint last_progress_info;
 143 |   char data[0];
 144 | };
 145 | 
 146 | static void
 147 | dump_to_file_flush(struct dump_request_file *req)
 148 | {
 149 |   if (req->fd < 0)
 150 |     return;
 151 | 
 152 |   for (uint sent = 0; sent < req->pos; )
 153 |   {
 154 |     int e = write(req->fd, &req->data[sent], req->pos - sent);
 155 |     if (e <= 0)
 156 |     {
 157 |       req->dr.report(&req->dr, 8009, "Failed to write data: %m");
 158 |       close(req->fd);
 159 |       req->fd = -1;
 160 |       return;
 161 |     }
 162 |     sent += e;
 163 |   }
 164 | 
 165 |   req->dr.size += req->pos;
 166 |   req->pos = 0;
 167 | 
 168 |   for (uint reported = 0; req->dr.size >> req->last_progress_info; req->last_progress_info++)
 169 |     if (!reported++)
 170 |       req->dr.report(&req->dr, -13, "... dumped %lu bytes in %t s",
 171 | 	  req->dr.size, current_time_now() - req->dr.begin);
 172 | }
 173 | 
 174 | static void
 175 | dump_to_file_write(struct dump_request *dr, const char *fmt, ...)
 176 | {
 177 |   struct dump_request_file *req = SKIP_BACK(struct dump_request_file, dr, dr);
 178 | 
 179 |   for (uint phase = 0; (req->fd >= 0) && (phase < 2); phase++)
 180 |   {
 181 |     va_list args;
 182 |     va_start(args, fmt);
 183 |     int i = bvsnprintf(&req->data[req->pos], req->max - req->pos, fmt, args);
 184 |     va_end(args);
 185 | 
 186 |     if (i >= 0)
 187 |     {
 188 |       req->pos += i;
 189 |       return;
 190 |     }
 191 |     else
 192 |       dump_to_file_flush(req);
 193 |   }
 194 | 
 195 |   bug("Too long dump call");
 196 | }
 197 | 
 198 | struct dump_request *
 199 | dump_to_file_init(off_t offset)
 200 | {
 201 |   ASSERT_DIE(offset + sizeof(struct dump_request_file) + 1024 < (unsigned long) page_size);
 202 | 
 203 |   struct dump_request_file *req = alloc_page() + offset;
 204 |   *req = (struct dump_request_file) {
 205 |     .dr = {
 206 |       .write = dump_to_file_write,
 207 |       .begin = current_time_now(),
 208 |       .offset = offset,
 209 |     },
 210 |     .max = page_size - offset - OFFSETOF(struct dump_request_file, data[0]),
 211 |     .fd = -1,
 212 |   };
 213 | 
 214 |   return &req->dr;
 215 | }
