 217 | void
 218 | dump_to_file_run(struct dump_request *dr, const char *file, const char *what, void (*dump)(struct dump_request *))
 219 | {
 220 |   struct dump_request_file *req = SKIP_BACK(struct dump_request_file, dr, dr);
 221 |   req->fd = open(file, O_CREAT | O_WRONLY | O_EXCL, S_IRUSR);
 222 | 
 223 |   if (req->fd < 0)
 224 |   {
 225 |     dr->report(dr, 8009, "Failed to open file %s: %m", file);
 226 |     goto cleanup;
 227 |   }
 228 | 
 229 |   dr->report(dr, -13, "Dumping %s to %s", what, file);
 230 | 
 231 |   dump(dr);
 232 | 
 233 |   if (req->fd >= 0)
 234 |   {
 235 |     dump_to_file_flush(req);
 236 |     close(req->fd);
 237 |   }
 238 | 
 239 |   btime end = current_time_now();
 240 |   dr->report(dr, 13, "Dumped %lu bytes in %t s", dr->size, end - dr->begin);
 241 | 
 242 | cleanup:
 243 |   free_page(((void *) req) - dr->offset);
 244 | }
