 466 | static inline int
 467 | sk_setup_multicast6(sock *s)
 468 | {
 469 |   int index = s->iface->index;
 470 |   int ttl = s->ttl;
 471 |   int n = 0;
 472 | 
 473 |   if (setsockopt(s->fd, SOL_IPV6, IPV6_MULTICAST_IF, &index, sizeof(index)) < 0)
 474 |     ERR("IPV6_MULTICAST_IF");
 475 | 
 476 |   if (setsockopt(s->fd, SOL_IPV6, IPV6_MULTICAST_HOPS, &ttl, sizeof(ttl)) < 0)
 477 |     ERR("IPV6_MULTICAST_HOPS");
 478 | 
 479 |   if (setsockopt(s->fd, SOL_IPV6, IPV6_MULTICAST_LOOP, &n, sizeof(n)) < 0)
 480 |     ERR("IPV6_MULTICAST_LOOP");
 481 | 
 482 |   return 0;
 483 | }
