 485 | static inline int
 486 | sk_join_group6(sock *s, ip_addr maddr)
 487 | {
 488 |   struct ipv6_mreq mr = INIT_MREQ6(maddr, s->iface);
 489 | 
 490 |   if (setsockopt(s->fd, SOL_IPV6, IPV6_JOIN_GROUP, &mr, sizeof(mr)) < 0)
 491 |     ERR("IPV6_JOIN_GROUP");
 492 | 
 493 |   return 0;
 494 | }
 495 | 
 496 | static inline int
 497 | sk_leave_group6(sock *s, ip_addr maddr)
 498 | {
 499 |   struct ipv6_mreq mr = INIT_MREQ6(maddr, s->iface);
 500 | 
 501 |   if (setsockopt(s->fd, SOL_IPV6, IPV6_LEAVE_GROUP, &mr, sizeof(mr)) < 0)
 502 |     ERR("IPV6_LEAVE_GROUP");
 503 | 
 504 |   return 0;
 505 | }
