 664 | static inline int
 665 | sk_set_min_rcvbuf_(sock *s, int bufsize)
 666 | {
 667 |   int oldsize = 0, oldsize_s = sizeof(oldsize);
 668 | 
 669 |   if (getsockopt(s->fd, SOL_SOCKET, SO_RCVBUF, &oldsize, &oldsize_s) < 0)
 670 |     ERR("SO_RCVBUF");
 671 | 
 672 |   if (oldsize >= bufsize)
 673 |     return 0;
 674 | 
 675 |   bufsize = BIRD_ALIGN(bufsize, 64);
 676 |   if (setsockopt(s->fd, SOL_SOCKET, SO_RCVBUF, &bufsize, sizeof(bufsize)) < 0)
 677 |     ERR("SO_RCVBUF");
 678 | 
 679 |   /*
 680 |   int newsize = 0, newsize_s = sizeof(newsize);
 681 |   if (getsockopt(s->fd, SOL_SOCKET, SO_RCVBUF, &newsize, &newsize_s) < 0)
 682 |     ERR("SO_RCVBUF");
 683 | 
 684 |   log(L_INFO "Setting rcvbuf on %s from %d to %d",
 685 |       s->iface ? s->iface->name : "*", oldsize, newsize);
 686 |   */
 687 | 
 688 |   return 0;
 689 | }
