 698 | static inline byte *
 699 | sk_skip_ip_header(byte *pkt, int *len)
 700 | {
 701 |   if ((*len < 20) || ((*pkt & 0xf0) != 0x40))
 702 |     return NULL;
 703 | 
 704 |   int hlen = (*pkt & 0x0f) * 4;
 705 |   if ((hlen < 20) || (hlen > *len))
 706 |     return NULL;
 707 | 
 708 |   *len -= hlen;
 709 |   return pkt + hlen;
 710 | }
 711 | 
 712 | byte *
 713 | sk_rx_buffer(sock *s, int *len)
 714 | {
 715 |   if (sk_is_ipv4(s) && (s->type == SK_IP))
 716 |     return sk_skip_ip_header(s->rbuf, len);
 717 |   else
 718 |     return s->rbuf;
 719 | }
