1048 | void
1049 | sk_set_tbsize(sock *s, uint val)
1050 | {
1051 |   ASSERT(s->tbuf_alloc == s->tbuf);
1052 | 
1053 |   if (s->tbsize == val)
1054 |     return;
1055 | 
1056 |   byte *old_tbuf = s->tbuf;
1057 | 
1058 |   s->tbsize = val;
1059 |   s->tbuf = s->tbuf_alloc = xrealloc(s->tbuf_alloc, val);
1060 |   s->tpos = s->tbuf + (s->tpos - old_tbuf);
1061 |   s->ttx  = s->tbuf + (s->ttx  - old_tbuf);
1062 | }
