1287 | static int
1288 | sk_passive_connected(sock *s, int type)
1289 | {
1290 |   sockaddr loc_sa, rem_sa;
1291 |   int loc_sa_len = sizeof(loc_sa);
1292 |   int rem_sa_len = sizeof(rem_sa);
1293 | 
1294 |   int fd = accept(s->fd, ((type == SK_TCP) ? &rem_sa.sa : NULL), &rem_sa_len);
1295 |   if (fd < 0)
1296 |   {
1297 |     if ((errno != EINTR) && (errno != EAGAIN))
1298 |       s->err_hook(s, errno);
1299 |     return 0;
1300 |   }
1301 | 
1302 |   sock *t = sk_new(s->pool);
1303 |   t->type = type;
1304 |   t->data = s->data;
1305 |   t->af = s->af;
1306 |   t->fd = fd;
1307 |   t->ttl = s->ttl;
1308 |   t->tos = s->tos;
1309 |   t->vrf = s->vrf;
1310 |   t->rbsize = s->rbsize;
1311 |   t->tbsize = s->tbsize;
1312 | 
1313 |   if (type == SK_TCP)
1314 |   {
1315 |     if ((getsockname(fd, &loc_sa.sa, &loc_sa_len) < 0) ||
1316 | 	(sockaddr_read(&loc_sa, s->af, &t->saddr, &t->iface, &t->sport) < 0))
1317 |       log(L_WARN "SOCK: Cannot get local IP address for TCP<");
1318 | 
1319 |     if (sockaddr_read(&rem_sa, s->af, &t->daddr, &t->iface, &t->dport) < 0)
1320 |       log(L_WARN "SOCK: Cannot get remote IP address for TCP<");
1321 |   }
1322 | 
1323 |   if (sk_setup(t) < 0)
1324 |   {
1325 |     /* FIXME: Call err_hook instead ? */
1326 |     log(L_ERR "SOCK: Incoming connection: %s%#m", t->err);
1327 | 
1328 |     /* FIXME: handle it better in rfree() */
1329 |     close(t->fd);
1330 |     t->fd = -1;
1331 |     rfree(t);
1332 |     return 1;
1333 |   }
1334 | 
1335 |   sk_insert(t);
1336 |   sk_alloc_bufs(t);
1337 |   s->rx_hook(t, 0);
1338 |   return 1;
1339 | }
