1494 | 
1495 |   ssh_session sess = ssh_new();
1496 |   if (sess == NULL)
1497 |     ERR2("Cannot create a ssh session");
1498 |   s->ssh->session = sess;
1499 | 
1500 |   const int verbosity = SSH_LOG_NOLOG;
1501 |   ssh_options_set(sess, SSH_OPTIONS_LOG_VERBOSITY, &verbosity);
1502 |   ssh_options_set(sess, SSH_OPTIONS_HOST, s->host);
