1509 | 
1510 |   if (s->ssh->client_privkey_path)
1511 |     ssh_options_set(sess, SSH_OPTIONS_IDENTITY, s->ssh->client_privkey_path);
1512 | 
1513 |   ssh_set_blocking(sess, 0);
1514 | 
1515 |   switch (sk_ssh_connect(s))
1516 |   {
1517 |   case SSH_AGAIN:
1518 |     break;
1519 | 
1520 |   case SSH_OK:
