1536 | /**
1537 |  * sk_open - open a socket
1538 |  * @s: socket
1539 |  *
1540 |  * This function takes a socket resource created by sk_new() and
1541 |  * initialized by the user and binds a corresponding network connection
1542 |  * to it.
1543 |  *
1544 |  * Result: 0 for success, -1 for an error.
1545 |  */
1546 | int
1547 | sk_open(sock *s)
1548 | {
1549 |   int af = AF_UNSPEC;
1550 |   int fd = -1;
1551 |   int do_bind = 0;
1552 |   int bind_port = 0;
1553 |   ip_addr bind_addr = IPA_NONE;
1554 |   sockaddr sa;
1555 | 
1556 |   if (s->type <= SK_IP)
1557 |   {
1558 |     /*
1559 |      * For TCP/IP sockets, Address family (IPv4 or IPv6) can be specified either
1560 |      * explicitly (SK_IPV4 or SK_IPV6) or implicitly (based on saddr, daddr).
1561 |      * But the specifications have to be consistent.
1562 |      */
1563 | 
1564 |     switch (s->subtype)
1565 |     {
1566 |     case 0:
1567 |       ASSERT(ipa_zero(s->saddr) || ipa_zero(s->daddr) ||
1568 | 	     (ipa_is_ip4(s->saddr) == ipa_is_ip4(s->daddr)));
1569 |       af = (ipa_is_ip4(s->saddr) || ipa_is_ip4(s->daddr)) ? AF_INET : AF_INET6;
1570 |       break;
1571 | 
1572 |     case SK_IPV4:
1573 |       ASSERT(ipa_zero(s->saddr) || ipa_is_ip4(s->saddr));
1574 |       ASSERT(ipa_zero(s->daddr) || ipa_is_ip4(s->daddr));
1575 |       af = AF_INET;
1576 |       break;
1577 | 
1578 |     case SK_IPV6:
1579 |       ASSERT(ipa_zero(s->saddr) || !ipa_is_ip4(s->saddr));
1580 |       ASSERT(ipa_zero(s->daddr) || !ipa_is_ip4(s->daddr));
1581 |       af = AF_INET6;
1582 |       break;
1583 | 
1584 |     default:
1585 |       bug("Invalid subtype %d", s->subtype);
1586 |     }
1587 |   }
1588 | 
1589 |   switch (s->type)
1590 |   {
1591 |   case SK_TCP_ACTIVE:
1592 |     s->ttx = "";			/* Force s->ttx != s->tpos */
1593 |     /* Fall thru */
1594 |   case SK_TCP_PASSIVE:
1595 |     fd = socket(af, SOCK_STREAM, IPPROTO_TCP);
1596 |     bind_port = s->sport;
1597 |     bind_addr = s->saddr;
1598 |     do_bind = bind_port || ipa_nonzero(bind_addr);
1599 |     break;
1600 | 
1601 | #ifdef HAVE_LIBSSH
1602 |   case SK_SSH_ACTIVE:
