1843 | static inline int
1844 | sk_recvmsg(sock *s)
1845 | {
1846 |   struct iovec iov = {s->rbuf, s->rbsize};
1847 |   byte cmsg_buf[CMSG_RX_SPACE];
1848 |   sockaddr src;
1849 | 
1850 |   struct msghdr msg = {
1851 |     .msg_name = &src.sa,
1852 |     .msg_namelen = sizeof(src), // XXXX ??
1853 |     .msg_iov = &iov,
1854 |     .msg_iovlen = 1,
1855 |     .msg_control = cmsg_buf,
1856 |     .msg_controllen = sizeof(cmsg_buf),
1857 |     .msg_flags = 0
1858 |   };
1859 | 
1860 |   int rv = recvmsg(s->fd, &msg, 0);
1861 |   if (rv < 0)
1862 |     return rv;
1863 | 
1864 |   //ifdef IPV4
1865 |   //  if (cf_type == SK_IP)
1866 |   //    rv = ipv4_skip_header(pbuf, rv);
1867 |   //endif
1868 | 
1869 |   sockaddr_read(&src, s->af, &s->faddr, NULL, &s->fport);
1870 |   sk_process_cmsgs(s, &msg);
1871 | 
1872 |   if (msg.msg_flags & MSG_TRUNC)
1873 |     s->flags |= SKF_TRUNCATED;
1874 |   else
1875 |     s->flags &= ~SKF_TRUNCATED;
1876 | 
1877 |   return rv;
1878 | }
