1881 | static inline void reset_tx_buffer(sock *s) { s->ttx = s->tpos = s->tbuf; }
1882 | 
1883 | static int
1884 | sk_maybe_write(sock *s)
1885 | {
1886 |   int e;
1887 | 
1888 |   switch (s->type)
1889 |   {
1890 |   case SK_TCP:
1891 |   case SK_MAGIC:
1892 |   case SK_UNIX:
1893 |     while (s->ttx != s->tpos)
1894 |     {
1895 |       e = write(s->fd, s->ttx, s->tpos - s->ttx);
1896 | 
1897 |       if (e < 0)
1898 |       {
1899 | 	if (errno != EINTR && errno != EAGAIN)
1900 | 	{
1901 | 	  reset_tx_buffer(s);
1902 | 	  /* EPIPE is just a connection close notification during TX */
1903 | 	  s->err_hook(s, (errno != EPIPE) ? errno : 0);
1904 | 	  return -1;
1905 | 	}
1906 | 	return 0;
1907 |       }
1908 |       s->ttx += e;
1909 |     }
1910 |     reset_tx_buffer(s);
1911 |     return 1;
1912 | 
1913 | #ifdef HAVE_LIBSSH
1914 |   case SK_SSH:
1915 |     while (s->ttx != s->tpos)
1916 |     {
1917 |       e = ssh_channel_write(s->ssh->channel, s->ttx, s->tpos - s->ttx);
1918 | 
1919 |       if (e < 0)
1920 |       {
1921 | 	s->err = ssh_get_error(s->ssh->session);
1922 | 	s->err_hook(s, ssh_get_error_code(s->ssh->session));
1923 | 
1924 | 	reset_tx_buffer(s);
1925 | 	/* EPIPE is just a connection close notification during TX */
1926 | 	s->err_hook(s, (errno != EPIPE) ? errno : 0);
1927 | 	return -1;
1928 |       }
1929 |       s->ttx += e;
1930 |     }
1931 |     reset_tx_buffer(s);
1932 |     return 1;
1933 | #endif
1934 | 
1935 |   case SK_UDP:
1936 |   case SK_IP:
1937 |     {
1938 |       if (s->tbuf == s->tpos)
1939 | 	return 1;
1940 | 
1941 |       e = sk_sendmsg(s);
1942 | 
1943 |       if (e < 0)
1944 |       {
1945 | 	if (errno != EINTR && errno != EAGAIN)
1946 | 	{
1947 | 	  reset_tx_buffer(s);
1948 | 	  s->err_hook(s, errno);
1949 | 	  return -1;
1950 | 	}
1951 | 
1952 | 	if (!s->tx_hook)
1953 | 	  reset_tx_buffer(s);
1954 | 	return 0;
1955 |       }
1956 |       reset_tx_buffer(s);
1957 |       return 1;
1958 |     }
1959 | 
1960 |   default:
1961 |     bug("sk_maybe_write: unknown socket type %d", s->type);
1962 |   }
1963 | }
