 283 | void
 284 | times_init(struct timeloop *loop)
 285 | {
 286 |   struct timespec ts;
 287 |   int rv;
 288 | 
 289 |   rv = clock_gettime(CLOCK_MONOTONIC, &ts);
 290 |   if (rv < 0)
 291 |     die("Monotonic clock is missing");
 292 | 
 293 |   if ((ts.tv_sec < 0) || (((u64) ts.tv_sec) > ((u64) 1 << 40)))
 294 |     log(L_WARN "Monotonic clock is crazy");
 295 | 
 296 |   loop->last_time = ts.tv_sec S + ts.tv_nsec NS;
 297 |   loop->real_time = 0;
 298 | }
