 300 | void
 301 | times_update(struct timeloop *loop)
 302 | {
 303 |   struct timespec ts;
 304 |   int rv;
 305 | 
 306 |   rv = clock_gettime(CLOCK_MONOTONIC, &ts);
 307 |   if (rv < 0)
 308 |     die("clock_gettime: %m");
 309 | 
 310 |   btime new_time = ts.tv_sec S + ts.tv_nsec NS;
 311 | 
 312 |   if (new_time < loop->last_time)
 313 |     log(L_ERR "Monotonic clock is broken");
 314 | 
 315 |   loop->last_time = new_time;
 316 |   loop->real_time = 0;
 317 | }
