1106 |  * sk_new - create a socket
1107 |  * @p: pool
1108 |  *
1109 |  * This function creates a new socket resource. If you want to use it,
1110 |  * you need to fill in all the required fields of the structure and
1111 |  * call sk_open() to do the actual opening of the socket.
1112 |  *
1113 |  * The real function name is sock_new(), sk_new() is a macro wrapper
1114 |  * to avoid collision with OpenSSL.
1115 |  */
1116 | sock *
1117 | sock_new(pool *p)
1118 | {
1119 |   sock *s = ralloc(p, &sk_class);
1120 |   s->pool = p;
1121 |   // s->saddr = s->daddr = IPA_NONE;
1122 |   s->tos = s->priority = s->ttl = -1;
1123 |   s->fd = -1;
