1269 |       (sockaddr_read(&sa, s->af, &s->saddr, &s->iface, &s->sport) < 0))
1270 |     log(L_WARN "SOCK: Cannot get local IP address for TCP>");
1271 | 
1272 |   s->type = SK_TCP;
1273 |   sk_alloc_bufs(s);
1274 |   s->tx_hook(s);
