1729 | int
1730 | sk_open_unix(sock *s, const char *name)
1731 | {
1732 |   struct sockaddr_un sa;
1733 |   int fd;
1734 | 
1735 |   /* We are sloppy during error (leak fd and not set s->err), but we die anyway */
1736 | 
1737 |   fd = socket(AF_UNIX, SOCK_STREAM, 0);
1738 |   if (fd < 0)
1739 |     return -1;
1740 | 
1741 |   if (fcntl(fd, F_SETFL, O_NONBLOCK) < 0)
1742 |     return -1;
1743 | 
1744 |   /* Path length checked in test_old_bird() but we may need unix sockets for other reasons in future */
1745 |   ASSERT_DIE(strlen(name) < sizeof(sa.sun_path));
1746 | 
1747 |   sa.sun_family = AF_UNIX;
1748 |   strcpy(sa.sun_path, name);
1749 | 
1750 |   if (bind(fd, (struct sockaddr *) &sa, SUN_LEN(&sa)) < 0)
1751 |     return -1;
1752 | 
1753 |   if (listen(fd, 8) < 0)
1754 |     return -1;
1755 | 
1756 |   s->fd = fd;
1757 |   sk_insert(s);
1758 |   return 0;
1759 | }
