1965 | int
1966 | sk_rx_ready(sock *s)
1967 | {
1968 |   int rv;
1969 |   struct pollfd pfd = { .fd = s->fd };
1970 |   pfd.events |= POLLIN;
1971 | 
1972 |  redo:
1973 |   rv = poll(&pfd, 1, 0);
1974 | 
1975 |   if ((rv < 0) && (errno == EINTR || errno == EAGAIN))
1976 |     goto redo;
1977 | 
1978 |   return rv;
1979 | }
