2170 | static inline int
2171 | sk_write_noflush(sock *s)
2172 | {
2173 |   switch (s->type)
2174 |   {
2175 |   case SK_TCP_ACTIVE:
2176 |     {
2177 |       if (sk_connect(s) >= 0 || errno == EISCONN)
2178 | 	sk_tcp_connected(s);
2179 |       else if (errno != EINTR && errno != EAGAIN && errno != EINPROGRESS)
2180 | 	s->err_hook(s, errno);
