2201 |       return 0;
2202 |     }
2203 | #endif
2204 | 
2205 |   default:
2206 |     if (s->ttx != s->tpos && sk_maybe_write(s) > 0)
2207 |     {
2208 |       if (s->tx_hook)
2209 | 	s->tx_hook(s);
2210 |       return 1;
2211 |     }
2212 |     return 0;
2213 |   }
