2331 | /**
2332 |  * io_log_event - mark approaching event into event log
2333 |  * @hook: event hook address
2334 |  * @data: event data address
2335 |  *
2336 |  * Store info (hook, data, timestamp) about the following internal event into
2337 |  * a circular event log (@event_log). When latency tracking is enabled, the log
2338 |  * entry is kept open (in @event_open) so the duration can be filled later.
2339 |  */
2340 | void
2341 | io_log_event(void *hook, void *data)
2342 | {
2343 |   if (config->latency_debug)
2344 |     io_update_time();
2345 | 
2346 |   struct event_log_entry *en = event_log + event_log_pos;
2347 | 
2348 |   en->hook = hook;
2349 |   en->data = data;
2350 |   en->timestamp = last_time;
2351 |   en->duration = 0;
2352 | 
2353 |   event_log_num++;
2354 |   event_log_pos++;
2355 |   event_log_pos %= EVENT_LOG_LENGTH;
2356 | 
2357 |   event_open = config->latency_debug ? en : NULL;
2358 | }
