 713 | sk_rx_buffer(sock *s, int *len)
 714 | {
 715 |   if (sk_is_ipv4(s) && (s->type == SK_IP))
 716 |     return sk_skip_ip_header(s->rbuf, len);
 717 |   else
 718 |     return s->rbuf;
 719 | }
