1801 | static inline int
1802 | sk_sendmsg(sock *s)
1803 | {
1804 |   struct iovec iov = {s->tbuf, s->tpos - s->tbuf};
1805 |   byte cmsg_buf[CMSG_TX_SPACE];
1806 |   sockaddr dst;
1807 |   int flags = 0;
1808 | 
1809 |   sockaddr_fill(&dst, s->af, s->daddr, s->iface, s->dport);
1810 | 
1811 |   struct msghdr msg = {
1812 |     .msg_name = &dst.sa,
1813 |     .msg_namelen = SA_LEN(dst),
1814 |     .msg_iov = &iov,
1815 |     .msg_iovlen = 1
1816 |   };
1817 | 
1818 | #ifdef CONFIG_DONTROUTE_UNICAST
1819 |   /* FreeBSD silently changes TTL to 1 when MSG_DONTROUTE is used, therefore we
1820 |      cannot use it for other cases (e.g. when TTL security is used). */
1821 |   if (ipa_is_ip4(s->daddr) && ip4_is_unicast(ipa_to_ip4(s->daddr)) && (s->ttl == 1))
1822 |     flags = MSG_DONTROUTE;
1823 | #endif
1824 | 
1825 | #ifdef CONFIG_USE_HDRINCL
1826 |   byte hdr[20];
1827 |   struct iovec iov2[2] = { {hdr, 20}, iov };
1828 | 
1829 |   if (s->flags & SKF_HDRINCL)
1830 |   {
1831 |     sk_prepare_ip_header(s, hdr, iov.iov_len);
1832 |     msg.msg_iov = iov2;
1833 |     msg.msg_iovlen = 2;
1834 |   }
1835 | #endif
1836 | 
1837 |   if (s->flags & SKF_PKTINFO)
1838 |     sk_prepare_cmsgs(s, &msg, cmsg_buf, sizeof(cmsg_buf));
1839 | 
1840 |   return sendmsg(s->fd, &msg, flags);
1841 | }
1842 | 
1843 | static inline int
1844 | sk_recvmsg(sock *s)
1845 | {
1846 |   struct iovec iov = {s->rbuf, s->rbsize};
1847 |   byte cmsg_buf[CMSG_RX_SPACE];
1848 |   sockaddr src;
1849 | 
1850 |   struct msghdr msg = {
1851 |     .msg_name = &src.sa,
1852 |     .msg_namelen = sizeof(src), // XXXX ??
1853 |     .msg_iov = &iov,
1854 |     .msg_iovlen = 1,
1855 |     .msg_control = cmsg_buf,
1856 |     .msg_controllen = sizeof(cmsg_buf),
1857 |     .msg_flags = 0
1858 |   };
1859 | 
1860 |   int rv = recvmsg(s->fd, &msg, 0);
1861 |   if (rv < 0)
1862 |     return rv;
1863 | 
1864 |   //ifdef IPV4
1865 |   //  if (cf_type == SK_IP)
1866 |   //    rv = ipv4_skip_header(pbuf, rv);
1867 |   //endif
1868 | 
1869 |   sockaddr_read(&src, s->af, &s->faddr, NULL, &s->fport);
1870 |   sk_process_cmsgs(s, &msg);
1871 | 
1872 |   if (msg.msg_flags & MSG_TRUNC)
1873 |     s->flags |= SKF_TRUNCATED;
1874 |   else
1875 |     s->flags &= ~SKF_TRUNCATED;
1876 | 
1877 |   return rv;
1878 | }
