2001 | /**
2002 |  * sk_send_to - send data to a specific destination
2003 |  * @s: socket
2004 |  * @len: number of bytes to send
2005 |  * @addr: IP address to send the packet to
2006 |  * @port: port to send the packet to
2007 |  *
2008 |  * This is a sk_send() replacement for connection-less packet sockets
2009 |  * which allows destination of the packet to be chosen dynamically.
2010 |  * Raw IP sockets should use 0 for @port.
2011 |  */
2012 | int
2013 | sk_send_to(sock *s, unsigned len, ip_addr addr, unsigned port)
2014 | {
2015 |   s->daddr = addr;
2016 |   if (port)
2017 |     s->dport = port;
2018 | 
2019 |   s->ttx = s->tbuf;
2020 |   s->tpos = s->tbuf + len;
2021 |   return sk_maybe_write(s);
2022 | }
2023 | 
2024 | /*
2025 | int
2026 | sk_send_full(sock *s, unsigned len, struct iface *ifa,
2027 | 	     ip_addr saddr, ip_addr daddr, unsigned dport)
2028 | {
2029 |   s->iface = ifa;
2030 |   s->saddr = saddr;
2031 |   s->daddr = daddr;
2032 |   s->dport = dport;
2033 |   s->ttx = s->tbuf;
2034 |   s->tpos = s->tbuf + len;
2035 |   return sk_maybe_write(s);
2036 | }
2037 | */
