2050 | #ifdef HAVE_LIBSSH
2051 | static int
2052 | sk_read_ssh(sock *s)
2053 | {
2054 |   ssh_channel rchans[2] = { s->ssh->channel, NULL };
2055 |   struct timeval timev = { 1, 0 };
2056 | 
2057 |   if (ssh_channel_select(rchans, NULL, NULL, &timev) == SSH_EINTR)
2058 |     return 1; /* Try again */
2059 | 
2060 |   if (ssh_channel_is_eof(s->ssh->channel) != 0)
2061 |   {
2062 |     /* The remote side is closing the connection */
2063 |     s->err_hook(s, 0);
2064 |     return 0;
2065 |   }
2066 | 
2067 |   if (rchans[0] == NULL)
2068 |     return 0; /* No data is available on the socket */
2069 | 
2070 |   const uint used_bytes = s->rpos - s->rbuf;
2071 |   const int read_bytes = ssh_channel_read_nonblocking(s->ssh->channel, s->rpos, s->rbsize - used_bytes, 0);
2072 |   if (read_bytes > 0)
2073 |   {
2074 |     /* Received data */
2075 |     s->rpos += read_bytes;
2076 |     call_rx_hook(s, used_bytes + read_bytes);
2077 |     return 1;
2078 |   }
2079 |   else if (read_bytes == 0)
2080 |   {
2081 |     if (ssh_channel_is_eof(s->ssh->channel) != 0)
2082 |     {
2083 | 	/* The remote side is closing the connection */
2084 | 	s->err_hook(s, 0);
2085 |     }
2086 |   }
2087 |   else
2088 |   {
2089 |     s->err = ssh_get_error(s->ssh->session);
2090 |     s->err_hook(s, ssh_get_error_code(s->ssh->session));
2091 |   }
2092 | 
2093 |   return 0; /* No data is available on the socket */
2094 | }
2095 | #endif
