2097 |  /* sk_read() and sk_write() are called from BFD's event loop */
2098 | 
2099 | static inline int
2100 | sk_read_noflush(sock *s, int revents)
2101 | {
2102 |   switch (s->type)
2103 |   {
2104 |   case SK_TCP_PASSIVE:
2105 |     return sk_passive_connected(s, SK_TCP);
2106 | 
2107 |   case SK_UNIX_PASSIVE:
2108 |     return sk_passive_connected(s, SK_UNIX);
2109 | 
2110 |   case SK_TCP:
2111 |   case SK_UNIX:
2112 |     {
2113 |       int c = read(s->fd, s->rpos, s->rbuf + s->rbsize - s->rpos);
2114 | 
2115 |       if (c < 0)
2116 |       {
2117 | 	if (errno != EINTR && errno != EAGAIN)
2118 | 	  s->err_hook(s, errno);
2119 | 	else if (errno == EAGAIN && !(revents & POLLIN))
2120 | 	{
2121 | 	  log(L_ERR "Got EAGAIN from read when revents=%x (without POLLIN)", revents);
2122 | 	  s->err_hook(s, 0);
2123 | 	}
2124 |       }
2125 |       else if (!c)
2126 | 	s->err_hook(s, 0);
2127 |       else
2128 |       {
2129 | 	s->rpos += c;
2130 | 	call_rx_hook(s, s->rpos - s->rbuf);
2131 | 	return 1;
2132 |       }
2133 |       return 0;
2134 |     }
2135 | 
2136 | #ifdef HAVE_LIBSSH
2137 |   case SK_SSH:
2138 |     return sk_read_ssh(s);
2139 | #endif
2140 | 
2141 |   case SK_MAGIC:
2142 |     return s->rx_hook(s, 0);
2143 | 
2144 |   default:
2145 |     {
2146 |       int e = sk_recvmsg(s);
2147 | 
2148 |       if (e < 0)
2149 |       {
2150 | 	if (errno != EINTR && errno != EAGAIN)
2151 | 	  s->err_hook(s, errno);
2152 | 	return 0;
2153 |       }
2154 | 
2155 |       s->rpos = s->rbuf + e;
2156 |       s->rx_hook(s, e);
2157 |       return 1;
2158 |     }
2159 |   }
2160 | }
2161 | 
2162 | int
2163 | sk_read(sock *s, int revents)
2164 | {
2165 |   int e = sk_read_noflush(s, revents);
2166 |   tmp_flush();
2167 |   return e;
2168 | }
2169 | 
2170 | static inline int
2171 | sk_write_noflush(sock *s)
2172 | {
2173 |   switch (s->type)
2174 |   {
2175 |   case SK_TCP_ACTIVE:
2176 |     {
2177 |       if (sk_connect(s) >= 0 || errno == EISCONN)
2178 | 	sk_tcp_connected(s);
2179 |       else if (errno != EINTR && errno != EAGAIN && errno != EINPROGRESS)
2180 | 	s->err_hook(s, errno);
2181 |       return 0;
2182 |     }
2183 | 
2184 | #ifdef HAVE_LIBSSH
2185 |   case SK_SSH_ACTIVE:
2186 |     {
2187 |       switch (sk_ssh_connect(s))
2188 |       {
2189 | 	case SSH_OK:
2190 | 	  sk_ssh_connected(s);
2191 | 	  break;
2192 | 
2193 | 	case SSH_AGAIN:
2194 | 	  return 1;
2195 | 
2196 | 	case SSH_ERROR:
2197 | 	  s->err = ssh_get_error(s->ssh->session);
2198 | 	  s->err_hook(s, ssh_get_error_code(s->ssh->session));
2199 | 	  break;
2200 |       }
2201 |       return 0;
2202 |     }
2203 | #endif
2204 | 
2205 |   default:
2206 |     if (s->ttx != s->tpos && sk_maybe_write(s) > 0)
2207 |     {
2208 |       if (s->tx_hook)
2209 | 	s->tx_hook(s);
2210 |       return 1;
2211 |     }
2212 |     return 0;
2213 |   }
2214 | }
