2281 | /*
2282 |  *	Internal event log and watchdog
2283 |  */
2284 | 
2285 | #define EVENT_LOG_LENGTH 32
2286 | 
2287 | struct event_log_entry
2288 | {
2289 |   void *hook;
2290 |   void *data;
2291 |   btime timestamp;
2292 |   btime duration;
2293 | };
2294 | 
2295 | static struct event_log_entry event_log[EVENT_LOG_LENGTH];
2296 | static struct event_log_entry *event_open;
2297 | static int event_log_pos, event_log_num, watchdog_active;
2298 | static btime last_time;
2299 | static btime loop_time;
2300 | 
2301 | static void
2302 | io_update_time(void)
2303 | {
2304 |   struct timespec ts;
2305 |   int rv;
2306 | 
2307 |   /*
2308 |    * This is third time-tracking procedure (after update_times() above and
2309 |    * times_update() in BFD), dedicated to internal event log and latency
2310 |    * tracking. Hopefully, we consolidate these sometimes.
2311 |    */
2312 | 
2313 |   rv = clock_gettime(CLOCK_MONOTONIC, &ts);
2314 |   if (rv < 0)
2315 |     die("clock_gettime: %m");
2316 | 
2317 |   last_time = ts.tv_sec S + ts.tv_nsec NS;
2318 | 
2319 |   if (event_open)
2320 |   {
2321 |     event_open->duration = last_time - event_open->timestamp;
2322 | 
2323 |     if (event_open->duration > config->latency_limit)
2324 |       log(L_WARN "Event 0x%p 0x%p took %u.%03u ms",
2325 | 	  event_open->hook, event_open->data, (uint) (event_open->duration TO_MS), (uint) (event_open->duration % 1000));
2326 | 
2327 |     event_open = NULL;
2328 |   }
2329 | }
2330 | 
2331 | /**
2332 |  * io_log_event - mark approaching event into event log
2333 |  * @hook: event hook address
2334 |  * @data: event data address
2335 |  *
2336 |  * Store info (hook, data, timestamp) about the following internal event into
2337 |  * a circular event log (@event_log). When latency tracking is enabled, the log
2338 |  * entry is kept open (in @event_open) so the duration can be filled later.
2339 |  */
2340 | void
2341 | io_log_event(void *hook, void *data)
2342 | {
2343 |   if (config->latency_debug)
2344 |     io_update_time();
2345 | 
2346 |   struct event_log_entry *en = event_log + event_log_pos;
2347 | 
2348 |   en->hook = hook;
2349 |   en->data = data;
2350 |   en->timestamp = last_time;
2351 |   en->duration = 0;
2352 | 
2353 |   event_log_num++;
2354 |   event_log_pos++;
2355 |   event_log_pos %= EVENT_LOG_LENGTH;
2356 | 
2357 |   event_open = config->latency_debug ? en : NULL;
2358 | }
2359 | 
2360 | static inline void
2361 | io_close_event(void)
2362 | {
2363 |   if (event_open)
2364 |     io_update_time();
2365 | }
2366 | 
2367 | void
2368 | io_log_dump(struct dump_request *dreq)
2369 | {
2370 |   int i;
2371 | 
2372 |   RDUMP("Event log:");
2373 |   for (i = 0; i < EVENT_LOG_LENGTH; i++)
2374 |   {
2375 |     struct event_log_entry *en = event_log + (event_log_pos + i) % EVENT_LOG_LENGTH;
2376 |     if (en->hook)
2377 |       RDUMP("  Event 0x%p 0x%p at %8d for %d ms", en->hook, en->data,
2378 | 	  (int) ((last_time - en->timestamp) TO_MS), (int) (en->duration TO_MS));
2379 |   }
2380 | }
