 246 | struct dump_request_cli {
 247 |   cli *cli;
 248 |   struct dump_request dr;
 249 | };
 250 | 
 251 | static void
 252 | cmd_dump_report(struct dump_request *dr, int state, const char *fmt, ...)
 253 | {
 254 |   struct dump_request_cli *req = SKIP_BACK(struct dump_request_cli, dr, dr);
 255 |   va_list args;
 256 |   va_start(args, fmt);
 257 |   cli_vprintf(req->cli, state, fmt, args);
