 346 | /**
 347 |  * DOC: Sockets
 348 |  *
 349 |  * Socket resources represent network connections. Their data structure (&socket)
 350 |  * contains a lot of fields defining the exact type of the socket, the local and
 351 |  * remote addresses and ports, pointers to socket buffers and finally pointers to
 352 |  * hook functions to be called when new data have arrived to the receive buffer
 353 |  * (@rx_hook), when the contents of the transmit buffer have been transmitted
 354 |  * (@tx_hook) and when an error or connection close occurs (@err_hook).
 355 |  *
 356 |  * Freeing of sockets from inside socket hooks is perfectly safe.
 357 |  */
 358 | 
 359 | #ifndef SOL_IP
 360 | #define SOL_IP IPPROTO_IP
 361 | #endif
 362 | 
 363 | #ifndef SOL_IPV6
 364 | #define SOL_IPV6 IPPROTO_IPV6
 365 | #endif
 366 | 
 367 | #ifndef SOL_ICMPV6
 368 | #define SOL_ICMPV6 IPPROTO_ICMPV6
 369 | #endif
 370 | 
 371 | 
 372 | /*
 373 |  *	Sockaddr helper functions
 374 |  */
 375 | 
 376 | static inline int UNUSED sockaddr_length(int af)
 377 | { return (af == AF_INET) ? sizeof(struct sockaddr_in) : sizeof(struct sockaddr_in6); }
 378 | 
 379 | static inline void
 380 | sockaddr_fill4(struct sockaddr_in *sa, ip_addr a, uint port)
 381 | {
 382 |   memset(sa, 0, sizeof(struct sockaddr_in));
 383 | #ifdef HAVE_STRUCT_SOCKADDR_SA_LEN
 384 |   sa->sin_len = sizeof(struct sockaddr_in);
 385 | #endif
 386 |   sa->sin_family = AF_INET;
 387 |   sa->sin_port = htons(port);
 388 |   sa->sin_addr = ipa_to_in4(a);
 389 | }
 390 | 
 391 | static inline void
 392 | sockaddr_fill6(struct sockaddr_in6 *sa, ip_addr a, struct iface *ifa, uint port)
 393 | {
 394 |   memset(sa, 0, sizeof(struct sockaddr_in6));
 395 | #ifdef SIN6_LEN
 396 |   sa->sin6_len = sizeof(struct sockaddr_in6);
 397 | #endif
 398 |   sa->sin6_family = AF_INET6;
 399 |   sa->sin6_port = htons(port);
 400 |   sa->sin6_flowinfo = 0;
 401 |   sa->sin6_addr = ipa_to_in6(a);
 402 | 
 403 |   if (ifa && ipa_is_link_local(a))
 404 |     sa->sin6_scope_id = ifa->index;
 405 | }
 406 | 
 407 | void
 408 | sockaddr_fill(sockaddr *sa, int af, ip_addr a, struct iface *ifa, uint port)
 409 | {
 410 |   if (af == AF_INET)
 411 |     sockaddr_fill4((struct sockaddr_in *) sa, a, port);
 412 |   else if (af == AF_INET6)
 413 |     sockaddr_fill6((struct sockaddr_in6 *) sa, a, ifa, port);
 414 |   else
 415 |     bug("Unknown AF");
 416 | }
 417 | 
 418 | static inline void
 419 | sockaddr_read4(struct sockaddr_in *sa, ip_addr *a, uint *port)
 420 | {
 421 |   *port = ntohs(sa->sin_port);
 422 |   *a = ipa_from_in4(sa->sin_addr);
 423 | }
 424 | 
 425 | static inline void
 426 | sockaddr_read6(struct sockaddr_in6 *sa, ip_addr *a, struct iface **ifa, uint *port)
 427 | {
 428 |   *port = ntohs(sa->sin6_port);
 429 |   *a = ipa_from_in6(sa->sin6_addr);
 430 | 
 431 |   if (ifa && ipa_is_link_local(*a))
 432 |     *ifa = if_find_by_index(sa->sin6_scope_id);
 433 | }
 434 | 
 435 | int
 436 | sockaddr_read(sockaddr *sa, int af, ip_addr *a, struct iface **ifa, uint *port)
 437 | {
 438 |   if (sa->sa.sa_family != af)
 439 |     goto fail;
 440 | 
 441 |   if (af == AF_INET)
 442 |     sockaddr_read4((struct sockaddr_in *) sa, a, port);
 443 |   else if (af == AF_INET6)
 444 |     sockaddr_read6((struct sockaddr_in6 *) sa, a, ifa, port);
 445 |   else
 446 |     goto fail;
 447 | 
 448 |   return 0;
 449 | 
 450 |  fail:
 451 |   *a = IPA_NONE;
 452 |   *port = 0;
 453 |   return -1;
 454 | }
