1536 | /**
1537 |  * sk_open - open a socket
1538 |  * @s: socket
1539 |  *
1540 |  * This function takes a socket resource created by sk_new() and
1541 |  * initialized by the user and binds a corresponding network connection
1542 |  * to it.
1543 |  *
1544 |  * Result: 0 for success, -1 for an error.
1545 |  */
1546 | int
1547 | sk_open(sock *s)
1548 | {
1549 |   int af = AF_UNSPEC;
1550 |   int fd = -1;
1551 |   int do_bind = 0;
1552 |   int bind_port = 0;
1553 |   ip_addr bind_addr = IPA_NONE;
1554 |   sockaddr sa;
1555 | 
1556 |   if (s->type <= SK_IP)
1557 |   {
1558 |     /*
1559 |      * For TCP/IP sockets, Address family (IPv4 or IPv6) can be specified either
1560 |      * explicitly (SK_IPV4 or SK_IPV6) or implicitly (based on saddr, daddr).
1561 |      * But the specifications have to be consistent.
1562 |      */
1563 | 
1564 |     switch (s->subtype)
1565 |     {
1566 |     case 0:
1567 |       ASSERT(ipa_zero(s->saddr) || ipa_zero(s->daddr) ||
1568 | 	     (ipa_is_ip4(s->saddr) == ipa_is_ip4(s->daddr)));
1569 |       af = (ipa_is_ip4(s->saddr) || ipa_is_ip4(s->daddr)) ? AF_INET : AF_INET6;
1570 |       break;
1571 | 
1572 |     case SK_IPV4:
1573 |       ASSERT(ipa_zero(s->saddr) || ipa_is_ip4(s->saddr));
1574 |       ASSERT(ipa_zero(s->daddr) || ipa_is_ip4(s->daddr));
1575 |       af = AF_INET;
1576 |       break;
1577 | 
1578 |     case SK_IPV6:
1579 |       ASSERT(ipa_zero(s->saddr) || !ipa_is_ip4(s->saddr));
1580 |       ASSERT(ipa_zero(s->daddr) || !ipa_is_ip4(s->daddr));
1581 |       af = AF_INET6;
1582 |       break;
1583 | 
1584 |     default:
1585 |       bug("Invalid subtype %d", s->subtype);
1586 |     }
1587 |   }
1588 | 
1589 |   switch (s->type)
1590 |   {
1591 |   case SK_TCP_ACTIVE:
1592 |     s->ttx = "";			/* Force s->ttx != s->tpos */
1593 |     /* Fall thru */
1594 |   case SK_TCP_PASSIVE:
1595 |     fd = socket(af, SOCK_STREAM, IPPROTO_TCP);
1596 |     bind_port = s->sport;
1597 |     bind_addr = s->saddr;
1598 |     do_bind = bind_port || ipa_nonzero(bind_addr);
1599 |     break;
1600 | 
1601 | #ifdef HAVE_LIBSSH
1602 |   case SK_SSH_ACTIVE:
1603 |     s->ttx = "";			/* Force s->ttx != s->tpos */
1604 |     fd = sk_open_ssh(s);
1605 |     break;
1606 | #endif
1607 | 
1608 |   case SK_UDP:
1609 |     fd = socket(af, SOCK_DGRAM, IPPROTO_UDP);
1610 |     bind_port = s->sport;
1611 |     bind_addr = (s->flags & SKF_BIND) ? s->saddr : IPA_NONE;
1612 |     do_bind = 1;
1613 |     break;
1614 | 
1615 |   case SK_IP:
1616 |     fd = socket(af, SOCK_RAW, s->dport);
1617 |     bind_port = 0;
1618 |     bind_addr = (s->flags & SKF_BIND) ? s->saddr : IPA_NONE;
1619 |     do_bind = ipa_nonzero(bind_addr);
1620 |     break;
1621 | 
1622 |   case SK_MAGIC:
1623 |     af = 0;
1624 |     fd = s->fd;
1625 |     break;
1626 | 
1627 |   default:
1628 |     bug("sk_open() called for invalid sock type %d", s->type);
1629 |   }
1630 | 
1631 |   if (fd < 0)
1632 |     ERR("socket");
1633 | 
1634 |   s->af = af;
1635 |   s->fd = fd;
1636 | 
1637 |   if (sk_setup(s) < 0)
1638 |     goto err;
1639 | 
1640 |   if (do_bind)
1641 |   {
1642 |     if (bind_port)
1643 |     {
1644 |       int y = 1;
1645 | 
1646 |       if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &y, sizeof(y)) < 0)
1647 | 	ERR2("SO_REUSEADDR");
1648 | 
1649 | #ifdef CONFIG_NO_IFACE_BIND
1650 |       /* Workaround missing ability to bind to an iface */
1651 |       if ((s->type == SK_UDP) && s->iface && ipa_zero(bind_addr))
1652 |       {
1653 | 	if (setsockopt(fd, SOL_SOCKET, SO_REUSEPORT, &y, sizeof(y)) < 0)
1654 | 	  ERR2("SO_REUSEPORT");
1655 |       }
1656 | #endif
1657 |     }
1658 |     else
1659 |       if (s->flags & SKF_HIGH_PORT)
1660 | 	if (sk_set_high_port(s) < 0)
1661 | 	  log(L_WARN "Socket error: %s%#m", s->err);
1662 | 
1663 |     if (s->flags & SKF_FREEBIND)
1664 |       if (sk_set_freebind(s) < 0)
1665 |         log(L_WARN "Socket error: %s%#m", s->err);
1666 | 
1667 |     sockaddr_fill(&sa, s->af, bind_addr, s->iface, bind_port);
1668 |     if (bind(fd, &sa.sa, SA_LEN(sa)) < 0)
1669 |       ERR2("bind");
1670 |   }
1671 | 
1672 |   if (s->ao_keys_init)
1673 |   {
1674 |     for (int i = 0; i < s->ao_keys_num; i++)
1675 |     {
1676 |       const struct ao_key *key = s->ao_keys_init[i];
1677 |       if (sk_add_ao_key(s, s->daddr, -1, s->iface, key, !i, !i) < 0)
1678 |         goto err;
1679 |     }
1680 |   }
1681 |   else if (s->password)
1682 |   {
1683 |     if (sk_set_md5_auth(s, s->saddr, s->daddr, -1, s->iface, s->password, 0) < 0)
1684 |       goto err;
1685 |   }
1686 | 
1687 |   switch (s->type)
1688 |   {
1689 |   case SK_TCP_ACTIVE:
1690 |     if (sk_connect(s) >= 0)
1691 |       sk_tcp_connected(s);
1692 |     else if (errno != EINTR && errno != EAGAIN && errno != EINPROGRESS &&
1693 | 	     errno != ECONNREFUSED && errno != EHOSTUNREACH && errno != ENETUNREACH)
1694 |       ERR2("connect");
1695 |     break;
1696 | 
1697 |   case SK_TCP_PASSIVE:
1698 |     if (listen(fd, 8) < 0)
1699 |       ERR2("listen");
1700 |     break;
1701 | 
1702 |   case SK_UDP:
1703 |     if (s->flags & SKF_CONNECT)
1704 |       if (sk_connect(s) < 0)
1705 | 	ERR2("connect");
1706 | 
1707 |     sk_alloc_bufs(s);
1708 |     break;
1709 | 
1710 |   case SK_SSH_ACTIVE:
1711 |   case SK_MAGIC:
1712 |     break;
1713 | 
1714 |   default:
1715 |     sk_alloc_bufs(s);
1716 |   }
1717 | 
1718 |   if (!(s->flags & SKF_THREAD))
1719 |     sk_insert(s);
1720 | 
1721 |   return 0;
1722 | 
1723 | err:
1724 |   close(fd);
1725 |   s->fd = -1;
1726 |   return -1;
1727 | }
