2038 | 
2039 | static void
2040 | call_rx_hook(sock *s, int size)
2041 | {
2042 |   if (s->rx_hook(s, size))
2043 |   {
2044 |     /* We need to be careful since the socket could have been deleted by the hook */
2045 |     if (current_sock == s)
2046 |       s->rpos = s->rbuf;
2047 |   }
