2382 | void
2383 | watchdog_sigalrm(int sig UNUSED)
2384 | {
2385 |   /* Update last_time and duration, but skip latency check */
2386 |   config->latency_limit = 0xffffffff;
2387 |   io_update_time();
2388 | 
2389 |   debug_safe("Watchdog timer timed out\n");
