2404 | watchdog_start(void)
2405 | {
2406 |   io_update_time();
2407 | 
2408 |   loop_time = last_time;
2409 |   event_log_num = 0;
2410 | 
2411 |   if (config->watchdog_timeout)
2412 |   {
2413 |     alarm(config->watchdog_timeout);
