2437 |  *	Main I/O Loop
2438 |  */
2439 | 
2440 | void
2441 | io_init(void)
2442 | {
2443 |   init_list(&sock_list);
2444 |   init_list(&global_event_list);
2445 |   init_list(&global_work_list);
2446 |   krt_io_init();
2447 |   // XXX init_times();
2448 |   // XXX update_times();
