2455 | static int short_loops = 0;
2456 | #define SHORT_LOOP_MAX 10
2457 | #define WORK_EVENTS_MAX 10
2458 | 
2459 | void
2460 | io_loop(void)
2461 | {
2462 |   int poll_tout, timeout;
2463 |   int nfds, events, pout;
2464 |   timer *t;
2465 |   sock *s;
2466 |   node *n;
2467 |   int fdmax = 256;
2468 |   struct pollfd *pfd = xmalloc(fdmax * sizeof(struct pollfd));
2469 | 
2470 |   watchdog_start1();
2471 |   for(;;)
2472 |     {
2473 |       times_update(&main_timeloop);
2474 |       ev_run_list(&global_event_list);
2475 |       ev_run_list_limited(&global_work_list, WORK_EVENTS_MAX);
2476 |       timers_fire(&main_timeloop);
2477 |       io_close_event();
2478 | 
2479 |       events = !EMPTY_LIST(global_event_list) || !EMPTY_LIST(global_work_list);
2480 |       poll_tout = (events ? 0 : 3000); /* Time in milliseconds */
2481 |       if (t = timers_first(&main_timeloop))
2482 |       {
2483 | 	times_update(&main_timeloop);
2484 | 	timeout = (tm_remains(t) TO_MS) + 1;
2485 | 	poll_tout = MIN(poll_tout, timeout);
2486 |       }
2487 | 
2488 |       nfds = 0;
2489 |       WALK_LIST(n, sock_list)
2490 | 	{
2491 | 	  pfd[nfds] = (struct pollfd) { .fd = -1 }; /* everything other set to 0 by this */
2492 | 	  s = SKIP_BACK(sock, n, n);
2493 | 	  if (s->rx_hook)
2494 | 	    {
2495 | 	      pfd[nfds].fd = s->fd;
2496 | 	      pfd[nfds].events |= POLLIN;
2497 | 	    }
2498 | 	  if (s->tx_hook && s->ttx != s->tpos)
2499 | 	    {
2500 | 	      pfd[nfds].fd = s->fd;
2501 | 	      pfd[nfds].events |= POLLOUT;
2502 | 	    }
2503 | 	  if (pfd[nfds].fd != -1)
2504 | 	    {
2505 | 	      s->index = nfds;
2506 | 	      nfds++;
2507 | 	    }
2508 | 	  else
2509 | 	    s->index = -1;
2510 | 
2511 | 	  if (nfds >= fdmax)
2512 | 	    {
2513 | 	      fdmax *= 2;
2514 | 	      pfd = xrealloc(pfd, fdmax * sizeof(struct pollfd));
2515 | 	    }
2516 | 	}
2517 | 
2518 |       /*
2519 |        * Yes, this is racy. But even if the signal comes before this test
2520 |        * and entering poll(), it gets caught on the next timer tick.
2521 |        */
2522 | 
2523 |       if (async_config_flag)
2524 | 	{
2525 | 	  io_log_event(async_config, NULL);
2526 | 	  async_config();
2527 | 	  async_config_flag = 0;
2528 | 	  continue;
2529 | 	}
2530 |       if (async_dump_flag)
2531 | 	{
2532 | 	  io_log_event(async_dump, NULL);
2533 | 	  async_dump();
2534 | 	  async_dump_flag = 0;
2535 | 	  continue;
2536 | 	}
2537 |       if (async_shutdown_flag)
2538 | 	{
2539 | 	  io_log_event(async_shutdown, NULL);
2540 | 	  async_shutdown();
2541 | 	  async_shutdown_flag = 0;
2542 | 	  continue;
2543 | 	}
2544 | 
2545 |       /* And finally enter poll() to find active sockets */
2546 |       watchdog_stop();
2547 |       pout = poll(pfd, nfds, poll_tout);
2548 |       watchdog_start();
2549 | 
2550 |       if (pout < 0)
2551 | 	{
2552 | 	  if (errno == EINTR || errno == EAGAIN)
2553 | 	    continue;
2554 | 	  die("poll: %m");
2555 | 	}
2556 |       if (pout)
2557 | 	{
2558 | 	  times_update(&main_timeloop);
2559 | 
2560 | 	  /* guaranteed to be non-empty */
2561 | 	  current_sock = SKIP_BACK(sock, n, HEAD(sock_list));
2562 | 
2563 | 	  while (current_sock)
2564 | 	    {
2565 | 	      sock *s = current_sock;
2566 | 	      if (s->index == -1)
2567 | 		{
2568 | 		  current_sock = sk_next(s);
2569 | 		  goto next;
2570 | 		}
2571 | 
2572 | 	      int e;
2573 | 	      int steps;
2574 | 
2575 | 	      steps = MAX_STEPS;
2576 | 	      if (s->fast_rx && (pfd[s->index].revents & POLLIN) && s->rx_hook)
2577 | 		do
2578 | 		  {
2579 | 		    steps--;
2580 | 		    io_log_event(s->rx_hook, s->data);
2581 | 		    e = sk_read(s, pfd[s->index].revents);
2582 | 		    if (s != current_sock)
2583 | 		      goto next;
2584 | 		  }
2585 | 		while (e && s->rx_hook && steps);
2586 | 
2587 | 	      steps = MAX_STEPS;
2588 | 	      if (pfd[s->index].revents & POLLOUT)
2589 | 		do
2590 | 		  {
2591 | 		    steps--;
2592 | 		    io_log_event(s->tx_hook, s->data);
2593 | 		    e = sk_write(s);
2594 | 		    if (s != current_sock)
2595 | 		      goto next;
2596 | 		  }
2597 | 		while (e && steps);
2598 | 
2599 | 	      current_sock = sk_next(s);
2600 | 	    next: ;
2601 | 	    }
2602 | 
2603 | 	  short_loops++;
2604 | 	  if (events && (short_loops < SHORT_LOOP_MAX))
2605 | 	    continue;
2606 | 	  short_loops = 0;
2607 | 
2608 | 	  int count = 0;
2609 | 	  current_sock = stored_sock;
2610 | 	  if (current_sock == NULL)
2611 | 	    current_sock = SKIP_BACK(sock, n, HEAD(sock_list));
2612 | 
2613 | 	  while (current_sock && count < MAX_RX_STEPS)
2614 | 	    {
2615 | 	      sock *s = current_sock;
2616 | 	      if (s->index == -1)
2617 | 		{
2618 | 		  current_sock = sk_next(s);
2619 | 		  goto next2;
2620 | 		}
2621 | 
2622 | 	      if (!s->fast_rx && (pfd[s->index].revents & POLLIN) && s->rx_hook)
2623 | 		{
2624 | 		  count++;
2625 | 		  io_log_event(s->rx_hook, s->data);
2626 | 		  sk_read(s, pfd[s->index].revents);
2627 | 		  if (s != current_sock)
2628 | 		    goto next2;
2629 | 		}
2630 | 
2631 | 	      if (pfd[s->index].revents & (POLLHUP | POLLERR))
2632 | 		{
2633 | 		  sk_err(s, pfd[s->index].revents);
2634 | 		  if (s != current_sock)
2635 | 		    goto next2;
2636 | 		}
2637 | 
2638 | 	      current_sock = sk_next(s);
2639 | 	    next2: ;
2640 | 	    }
2641 | 
2642 | 
2643 | 	  stored_sock = current_sock;
2644 | 	}
2645 |     }
2646 | }
