1127 | static int
1128 | sk_setup(sock *s)
1129 | {
1130 |   int y = 1;
1131 |   int fd = s->fd;
1132 | 
1133 |   if (s->type == SK_SSH_ACTIVE)
1134 |     return 0;
1135 | 
1136 |   if (fcntl(fd, F_SETFL, O_NONBLOCK) < 0)
1137 |     ERR("O_NONBLOCK");
1138 | 
1139 |   if (!s->af)
1140 |     return 0;
1141 | 
1142 |   if (ipa_nonzero(s->saddr) && !(s->flags & SKF_BIND))
1143 |     s->flags |= SKF_PKTINFO;
1144 | 
1145 | #ifdef CONFIG_USE_HDRINCL
1146 |   if (sk_is_ipv4(s) && (s->type == SK_IP) && (s->flags & SKF_PKTINFO))
1147 |   {
1148 |     s->flags &= ~SKF_PKTINFO;
1149 |     s->flags |= SKF_HDRINCL;
1150 |     if (setsockopt(fd, SOL_IP, IP_HDRINCL, &y, sizeof(y)) < 0)
1151 |       ERR("IP_HDRINCL");
1152 |   }
1153 | #endif
1154 | 
1155 |   if (s->vrf && !s->iface && (s->type != SK_TCP))
1156 |   {
1157 |     /* Bind socket to associated VRF interface.
1158 |        This is Linux-specific, but so is SO_BINDTODEVICE.
1159 |        For accepted TCP sockets it is inherited from the listening one. */
1160 | #ifdef SO_BINDTODEVICE
1161 |     struct ifreq ifr = {};
1162 |     strcpy(ifr.ifr_name, s->vrf->name);
1163 |     if (setsockopt(s->fd, SOL_SOCKET, SO_BINDTODEVICE, &ifr, sizeof(ifr)) < 0)
1164 |       ERR("SO_BINDTODEVICE");
1165 | #endif
1166 |   }
1167 | 
1168 |   if (s->iface)
1169 |   {
1170 | #ifdef SO_BINDTODEVICE
1171 |     struct ifreq ifr = {};
1172 |     strcpy(ifr.ifr_name, s->iface->name);
1173 |     if (setsockopt(s->fd, SOL_SOCKET, SO_BINDTODEVICE, &ifr, sizeof(ifr)) < 0)
1174 |       ERR("SO_BINDTODEVICE");
1175 | #endif
1176 | 
1177 | #ifdef CONFIG_UNIX_DONTROUTE
1178 |     if (setsockopt(s->fd, SOL_SOCKET, SO_DONTROUTE, &y, sizeof(y)) < 0)
1179 |       ERR("SO_DONTROUTE");
1180 | #endif
1181 |   }
1182 | 
1183 |   if (sk_is_ipv4(s))
1184 |   {
1185 |     if (s->flags & SKF_LADDR_RX)
1186 |       if (sk_request_cmsg4_pktinfo(s) < 0)
1187 | 	return -1;
1188 | 
1189 |     if (s->flags & SKF_TTL_RX)
1190 |       if (sk_request_cmsg4_ttl(s) < 0)
1191 | 	return -1;
1192 | 
1193 |     if ((s->type == SK_UDP) || (s->type == SK_IP))
1194 |       if (sk_disable_mtu_disc4(s) < 0)
1195 | 	return -1;
1196 | 
1197 |     if (s->ttl >= 0)
1198 |       if (sk_set_ttl4(s, s->ttl) < 0)
1199 | 	return -1;
1200 | 
1201 |     if (s->tos >= 0)
1202 |       if (sk_set_tos4(s, s->tos) < 0)
1203 | 	return -1;
1204 |   }
1205 | 
1206 |   if (sk_is_ipv6(s))
1207 |   {
1208 |     if ((s->type == SK_TCP_PASSIVE) || (s->type == SK_TCP_ACTIVE) || (s->type == SK_UDP))
1209 |       if (setsockopt(fd, SOL_IPV6, IPV6_V6ONLY, &y, sizeof(y)) < 0)
1210 | 	ERR("IPV6_V6ONLY");
1211 | 
1212 |     if (s->flags & SKF_LADDR_RX)
1213 |       if (sk_request_cmsg6_pktinfo(s) < 0)
1214 | 	return -1;
1215 | 
1216 |     if (s->flags & SKF_TTL_RX)
1217 |       if (sk_request_cmsg6_ttl(s) < 0)
1218 | 	return -1;
1219 | 
1220 |     if ((s->type == SK_UDP) || (s->type == SK_IP))
1221 |       if (sk_disable_mtu_disc6(s) < 0)
1222 | 	return -1;
1223 | 
1224 |     if (s->ttl >= 0)
1225 |       if (sk_set_ttl6(s, s->ttl) < 0)
1226 | 	return -1;
1227 | 
1228 |     if (s->tos >= 0)
1229 |       if (sk_set_tos6(s, s->tos) < 0)
1230 | 	return -1;
1231 | 
1232 |     if ((s->flags & SKF_UDP6_NO_CSUM_RX) && (s->type == SK_UDP))
1233 |       if (sk_set_udp6_no_csum_rx(s) < 0)
1234 | 	return -1;
1235 |   }
1236 | 
1237 |   /* Must be after sk_set_tos4() as setting ToS on Linux also mangles priority */
1238 |   if (s->priority >= 0)
1239 |     if (sk_set_priority(s, s->priority) < 0)
1240 |       return -1;
1241 | 
1242 |   if ((s->type == SK_UDP) || (s->type == SK_IP))
1243 |     sk_set_min_rcvbuf(s, s->rbsize);
1244 | 
1245 |   return 0;
1246 | }
