1762 | #define CMSG_RX_SPACE MAX(CMSG4_SPACE_PKTINFO+CMSG4_SPACE_TTL, \
1763 | 			  CMSG6_SPACE_PKTINFO+CMSG6_SPACE_TTL)
1764 | #define CMSG_TX_SPACE MAX(CMSG4_SPACE_PKTINFO,CMSG6_SPACE_PKTINFO)
1765 | 
1766 | static void
1767 | sk_prepare_cmsgs(sock *s, struct msghdr *msg, void *cbuf, size_t cbuflen)
1768 | {
1769 |   if (sk_is_ipv4(s))
1770 |     sk_prepare_cmsgs4(s, msg, cbuf, cbuflen);
1771 |   else
1772 |     sk_prepare_cmsgs6(s, msg, cbuf, cbuflen);
1773 | }
1774 | 
1775 | static void
1776 | sk_process_cmsgs(sock *s, struct msghdr *msg)
1777 | {
1778 |   struct cmsghdr *cm;
1779 | 
1780 |   s->laddr = IPA_NONE;
1781 |   s->lifindex = 0;
1782 |   s->rcv_ttl = -1;
1783 | 
1784 |   for (cm = CMSG_FIRSTHDR(msg); cm != NULL; cm = CMSG_NXTHDR(msg, cm))
1785 |   {
1786 |     if ((cm->cmsg_level == SOL_IP) && sk_is_ipv4(s))
1787 |     {
1788 |       sk_process_cmsg4_pktinfo(s, cm);
1789 |       sk_process_cmsg4_ttl(s, cm);
1790 |     }
1791 | 
1792 |     if ((cm->cmsg_level == SOL_IPV6) && sk_is_ipv6(s))
1793 |     {
1794 |       sk_process_cmsg6_pktinfo(s, cm);
1795 |       sk_process_cmsg6_ttl(s, cm);
1796 |     }
1797 |   }
1798 | }
