1881 | static inline void reset_tx_buffer(sock *s) { s->ttx = s->tpos = s->tbuf; }
1882 | 
1883 | static int
1884 | sk_maybe_write(sock *s)
1885 | {
1886 |   int e;
1887 | 
1888 |   switch (s->type)
1889 |   {
1890 |   case SK_TCP:
1891 |   case SK_MAGIC:
1892 |   case SK_UNIX:
1893 |     while (s->ttx != s->tpos)
1894 |     {
