 278 |  *	Time clock
 279 |  */
 280 | 
 281 | btime boot_time;
 282 | 
 283 | void
 284 | times_init(struct timeloop *loop)
 285 | {
 286 |   struct timespec ts;
 287 |   int rv;
 288 | 
 289 |   rv = clock_gettime(CLOCK_MONOTONIC, &ts);
 290 |   if (rv < 0)
 291 |     die("Monotonic clock is missing");
 292 | 
 293 |   if ((ts.tv_sec < 0) || (((u64) ts.tv_sec) > ((u64) 1 << 40)))
 294 |     log(L_WARN "Monotonic clock is crazy");
 295 | 
 296 |   loop->last_time = ts.tv_sec S + ts.tv_nsec NS;
 297 |   loop->real_time = 0;
 298 | }
 299 | 
 300 | void
 301 | times_update(struct timeloop *loop)
 302 | {
 303 |   struct timespec ts;
 304 |   int rv;
 305 | 
 306 |   rv = clock_gettime(CLOCK_MONOTONIC, &ts);
 307 |   if (rv < 0)
 308 |     die("clock_gettime: %m");
 309 | 
 310 |   btime new_time = ts.tv_sec S + ts.tv_nsec NS;
 311 | 
 312 |   if (new_time < loop->last_time)
 313 |     log(L_ERR "Monotonic clock is broken");
 314 | 
 315 |   loop->last_time = new_time;
 316 |   loop->real_time = 0;
 317 | }
 318 | 
 319 | void
 320 | times_update_real_time(struct timeloop *loop)
 321 | {
 322 |   struct timespec ts;
 323 |   int rv;
 324 | 
 325 |   rv = clock_gettime(CLOCK_REALTIME, &ts);
 326 |   if (rv < 0)
 327 |     die("clock_gettime: %m");
 328 | 
 329 |   loop->real_time = ts.tv_sec S + ts.tv_nsec NS;
 330 | }
 331 | 
 332 | btime
 333 | current_time_now(void)
 334 | {
 335 |   struct timespec ts;
 336 |   int rv;
 337 | 
 338 |   rv = clock_gettime(CLOCK_MONOTONIC, &ts);
 339 |   if (rv < 0)
 340 |     die("clock_gettime: %m");
 341 | 
 342 |   return ts.tv_sec S + ts.tv_nsec NS;
 343 | }
