 509 |  *	IPv6 packet control messages
 510 |  */
 511 | 
 512 | /* Also standardized, in RFC 3542 */
 513 | 
 514 | /*
 515 |  * RFC 2292 uses IPV6_PKTINFO for both the socket option and the cmsg
 516 |  * type, RFC 3542 changed the socket option to IPV6_RECVPKTINFO. If we
 517 |  * don't have IPV6_RECVPKTINFO we suppose the OS implements the older
 518 |  * RFC and we use IPV6_PKTINFO.
 519 |  */
 520 | #ifndef IPV6_RECVPKTINFO
 521 | #define IPV6_RECVPKTINFO IPV6_PKTINFO
 522 | #endif
 523 | /*
 524 |  * Same goes for IPV6_HOPLIMIT -> IPV6_RECVHOPLIMIT.
 525 |  */
 526 | #ifndef IPV6_RECVHOPLIMIT
 527 | #define IPV6_RECVHOPLIMIT IPV6_HOPLIMIT
 528 | #endif
 529 | 
 530 | 
 531 | #define CMSG6_SPACE_PKTINFO CMSG_SPACE(sizeof(struct in6_pktinfo))
 532 | #define CMSG6_SPACE_TTL CMSG_SPACE(sizeof(int))
 533 | 
 534 | static inline int
 535 | sk_request_cmsg6_pktinfo(sock *s)
 536 | {
 537 |   int y = 1;
 538 | 
 539 |   if (setsockopt(s->fd, SOL_IPV6, IPV6_RECVPKTINFO, &y, sizeof(y)) < 0)
 540 |     ERR("IPV6_RECVPKTINFO");
 541 | 
 542 |   return 0;
 543 | }
 544 | 
 545 | static inline int
 546 | sk_request_cmsg6_ttl(sock *s)
 547 | {
 548 |   int y = 1;
 549 | 
 550 |   if (setsockopt(s->fd, SOL_IPV6, IPV6_RECVHOPLIMIT, &y, sizeof(y)) < 0)
 551 |     ERR("IPV6_RECVHOPLIMIT");
 552 | 
 553 |   return 0;
 554 | }
 555 | 
 556 | static inline void
 557 | sk_process_cmsg6_pktinfo(sock *s, struct cmsghdr *cm)
 558 | {
 559 |   if (cm->cmsg_type == IPV6_PKTINFO)
 560 |   {
 561 |     struct in6_pktinfo *pi = (struct in6_pktinfo *) CMSG_DATA(cm);
 562 |     s->laddr = ipa_from_in6(pi->ipi6_addr);
 563 |     s->lifindex = pi->ipi6_ifindex;
 564 |   }
 565 | }
 566 | 
 567 | static inline void
 568 | sk_process_cmsg6_ttl(sock *s, struct cmsghdr *cm)
 569 | {
 570 |   if (cm->cmsg_type == IPV6_HOPLIMIT)
 571 |     s->rcv_ttl = * (int *) CMSG_DATA(cm);
 572 | }
 573 | 
 574 | static inline void
 575 | sk_prepare_cmsgs6(sock *s, struct msghdr *msg, void *cbuf, size_t cbuflen)
 576 | {
 577 |   struct cmsghdr *cm;
 578 |   struct in6_pktinfo *pi;
 579 |   int controllen = 0;
 580 | 
 581 |   msg->msg_control = cbuf;
 582 |   msg->msg_controllen = cbuflen;
 583 | 
 584 |   cm = CMSG_FIRSTHDR(msg);
 585 |   cm->cmsg_level = SOL_IPV6;
 586 |   cm->cmsg_type = IPV6_PKTINFO;
 587 |   cm->cmsg_len = CMSG_LEN(sizeof(*pi));
 588 |   controllen += CMSG_SPACE(sizeof(*pi));
 589 | 
 590 |   pi = (struct in6_pktinfo *) CMSG_DATA(cm);
 591 |   pi->ipi6_ifindex = s->iface ? s->iface->index : 0;
 592 |   pi->ipi6_addr = ipa_to_in6(s->saddr);
 593 | 
 594 |   msg->msg_controllen = controllen;
 595 | }
