1000 | static void
1001 | sk_free(resource *r)
1002 | {
1003 |   sock *s = (sock *) r;
1004 | 
1005 |   sk_free_bufs(s);
1006 | 
1007 | #ifdef HAVE_LIBSSH
1008 |   if (s->type == SK_SSH || s->type == SK_SSH_ACTIVE)
1009 |     sk_ssh_free(s);
1010 | #endif
1011 | 
1012 |   if (s->fd < 0)
1013 |     return;
1014 | 
1015 |   /* FIXME: we should call sk_stop() for SKF_THREAD sockets */
1016 |   if (!(s->flags & SKF_THREAD))
1017 |   {
1018 |     if (s == current_sock)
1019 |       current_sock = sk_next(s);
1020 |     if (s == stored_sock)
1021 |       stored_sock = sk_next(s);
1022 |     rem_node(&s->n);
1023 |   }
1024 | 
1025 |   if (s->type != SK_SSH && s->type != SK_SSH_ACTIVE)
1026 |     close(s->fd);
1027 | 
1028 |   s->fd = -1;
1029 | }
