1031 | void
1032 | sk_set_rbsize(sock *s, uint val)
1033 | {
1034 |   ASSERT(s->rbuf_alloc == s->rbuf);
1035 | 
1036 |   if (s->rbsize == val)
1037 |     return;
1038 | 
1039 |   s->rbsize = val;
1040 |   xfree(s->rbuf_alloc);
1041 |   s->rbuf_alloc = xmalloc(val);
1042 |   s->rpos = s->rbuf = s->rbuf_alloc;
1043 | 
1044 |   if ((s->type == SK_UDP) || (s->type == SK_IP))
1045 |     sk_set_min_rcvbuf(s, s->rbsize);
1046 | }
