1341 | #ifdef HAVE_LIBSSH
1342 | /*
1343 |  * Return SSH_OK or SSH_AGAIN or SSH_ERROR
1344 |  */
1345 | static int
1346 | sk_ssh_connect(sock *s)
1347 | {
1348 |   s->fd = ssh_get_fd(s->ssh->session);
1349 | 
1350 |   /* Big fall thru automata */
1351 |   switch (s->ssh->state)
1352 |   {
1353 |   case SK_SSH_CONNECT:
1354 |   {
1355 |     switch (ssh_connect(s->ssh->session))
1356 |     {
1357 |     case SSH_AGAIN:
1358 |       /* A quick look into libSSH shows that ssh_get_fd() should return non-(-1)
1359 |        * after SSH_AGAIN is returned by ssh_connect(). This is however nowhere
1360 |        * documented but our code relies on that.
1361 |        */
1362 |       return SSH_AGAIN;
1363 | 
1364 |     case SSH_OK:
1365 |       break;
1366 | 
1367 |     default:
1368 |       return SSH_ERROR;
1369 |     }
1370 |   } /* fallthrough */
1371 | 
1372 |   case SK_SSH_SERVER_KNOWN:
1373 |   {
1374 |     s->ssh->state = SK_SSH_SERVER_KNOWN;
1375 | 
1376 |     if (s->ssh->server_hostkey_path)
1377 |     {
1378 |       int server_identity_is_ok = 1;
1379 | 
1380 |       /* Check server identity */
1381 |       switch (ssh_is_server_known(s->ssh->session))
1382 |       {
1383 | #define LOG_WARN_ABOUT_SSH_SERVER_VALIDATION(s,msg,args...) log(L_WARN "SSH Identity %s@%s:%u: " msg, (s)->ssh->username, (s)->host, (s)->dport, ## args);
1384 |       case SSH_SERVER_KNOWN_OK:
1385 | 	/* The server is known and has not changed. */
1386 | 	break;
1387 | 
1388 |       case SSH_SERVER_NOT_KNOWN:
1389 | 	LOG_WARN_ABOUT_SSH_SERVER_VALIDATION(s, "The server is unknown, its public key was not found in the known host file %s", s->ssh->server_hostkey_path);
1390 | 	break;
1391 | 
1392 |       case SSH_SERVER_KNOWN_CHANGED:
1393 | 	LOG_WARN_ABOUT_SSH_SERVER_VALIDATION(s, "The server key has changed. Either you are under attack or the administrator changed the key.");
1394 | 	server_identity_is_ok = 0;
1395 | 	break;
1396 | 
1397 |       case SSH_SERVER_FILE_NOT_FOUND:
1398 | 	LOG_WARN_ABOUT_SSH_SERVER_VALIDATION(s, "The known host file %s does not exist", s->ssh->server_hostkey_path);
1399 | 	server_identity_is_ok = 0;
1400 | 	break;
1401 | 
1402 |       case SSH_SERVER_ERROR:
1403 | 	LOG_WARN_ABOUT_SSH_SERVER_VALIDATION(s, "Some error happened");
1404 | 	server_identity_is_ok = 0;
1405 | 	break;
1406 | 
1407 |       case SSH_SERVER_FOUND_OTHER:
1408 | 	LOG_WARN_ABOUT_SSH_SERVER_VALIDATION(s, "The server gave use a key of a type while we had an other type recorded. " \
1409 | 					     "It is a possible attack.");
1410 | 	server_identity_is_ok = 0;
1411 | 	break;
1412 |       }
1413 | 
1414 |       if (!server_identity_is_ok)
1415 | 	return SSH_ERROR;
1416 |     }
1417 |   } /* fallthrough */
1418 | 
1419 |   case SK_SSH_USERAUTH:
1420 |   {
1421 |     s->ssh->state = SK_SSH_USERAUTH;
1422 |     switch (ssh_userauth_publickey_auto(s->ssh->session, NULL, NULL))
1423 |     {
1424 |     case SSH_AUTH_AGAIN:
1425 |       return SSH_AGAIN;
1426 | 
1427 |     case SSH_AUTH_SUCCESS:
1428 |       break;
1429 | 
1430 |     default:
1431 |       return SSH_ERROR;
1432 |     }
1433 |   } /* fallthrough */
1434 | 
1435 |   case SK_SSH_CHANNEL:
1436 |   {
1437 |     s->ssh->state = SK_SSH_CHANNEL;
1438 |     s->ssh->channel = ssh_channel_new(s->ssh->session);
1439 |     if (s->ssh->channel == NULL)
1440 |       return SSH_ERROR;
1441 |   } /* fallthrough */
1442 | 
1443 |   case SK_SSH_SESSION:
1444 |   {
1445 |     s->ssh->state = SK_SSH_SESSION;
1446 |     switch (ssh_channel_open_session(s->ssh->channel))
1447 |     {
1448 |     case SSH_AGAIN:
1449 |       return SSH_AGAIN;
1450 | 
1451 |     case SSH_OK:
1452 |       break;
1453 | 
1454 |     default:
1455 |       return SSH_ERROR;
1456 |     }
1457 |   } /* fallthrough */
1458 | 
1459 |   case SK_SSH_SUBSYSTEM:
1460 |   {
1461 |     s->ssh->state = SK_SSH_SUBSYSTEM;
1462 |     if (s->ssh->subsystem)
1463 |     {
1464 |       switch (ssh_channel_request_subsystem(s->ssh->channel, s->ssh->subsystem))
1465 |       {
1466 |       case SSH_AGAIN:
1467 | 	return SSH_AGAIN;
1468 | 
1469 |       case SSH_OK:
1470 | 	break;
1471 | 
1472 |       default:
1473 | 	return SSH_ERROR;
1474 |       }
1475 |     }
1476 |   } /* fallthrough */
1477 | 
1478 |   case SK_SSH_ESTABLISHED:
1479 |     s->ssh->state = SK_SSH_ESTABLISHED;
1480 |   }
1481 | 
1482 |   return SSH_OK;
1483 | }
