1485 | /*
1486 |  * Return file descriptor number if success
1487 |  * Return -1 if failed
1488 |  */
1489 | static int
1490 | sk_open_ssh(sock *s)
1491 | {
1492 |   if (!s->ssh)
1493 |     bug("sk_open() sock->ssh is not allocated");
1494 | 
1495 |   ssh_session sess = ssh_new();
1496 |   if (sess == NULL)
1497 |     ERR2("Cannot create a ssh session");
1498 |   s->ssh->session = sess;
1499 | 
1500 |   const int verbosity = SSH_LOG_NOLOG;
1501 |   ssh_options_set(sess, SSH_OPTIONS_LOG_VERBOSITY, &verbosity);
1502 |   ssh_options_set(sess, SSH_OPTIONS_HOST, s->host);
1503 |   ssh_options_set(sess, SSH_OPTIONS_PORT, &(s->dport));
1504 |   /* TODO: Add SSH_OPTIONS_BINDADDR */
1505 |   ssh_options_set(sess, SSH_OPTIONS_USER, s->ssh->username);
1506 | 
1507 |   if (s->ssh->server_hostkey_path)
1508 |     ssh_options_set(sess, SSH_OPTIONS_KNOWNHOSTS, s->ssh->server_hostkey_path);
1509 | 
1510 |   if (s->ssh->client_privkey_path)
1511 |     ssh_options_set(sess, SSH_OPTIONS_IDENTITY, s->ssh->client_privkey_path);
1512 | 
1513 |   ssh_set_blocking(sess, 0);
1514 | 
1515 |   switch (sk_ssh_connect(s))
1516 |   {
1517 |   case SSH_AGAIN:
1518 |     break;
1519 | 
1520 |   case SSH_OK:
1521 |     sk_ssh_connected(s);
1522 |     break;
1523 | 
1524 |   case SSH_ERROR:
1525 |     ERR2(ssh_get_error(sess));
