109 | log_open(struct log_config *l)
110 | {
111 |   l->rf = rf_open(config->pool, l->filename, "a");
112 |   if (!l->rf)
113 |   {
114 |     /* Well, we cannot do much in case of error as log is closed */
115 |     l->mask = 0;
116 |     return -1;
117 |   }
118 | 
