153 |     if (ipa_zero(l->ip))
154 |     {
155 |       cf_warn("Cannot resolve hostname '%s': %s", l->host, err_msg);
156 |       goto err0;
157 |     }
158 |   }
159 | 
160 |   sock *sk = sk_new(p);
161 |   sk->type = SK_UDP;
162 |   sk->daddr = l->ip;
163 |   sk->dport = l->port;
164 |   sk->flags = SKF_CONNECT | SKF_THREAD;
