 132 | static inline void
 133 | add_num_const(struct config *conf, char *name, int val, const char *file, const uint line)
 134 | {
 135 |   struct f_val *v = cfg_alloc(sizeof(struct f_val));
 136 |   *v = (struct f_val) { .type = T_INT, .val.i = val };
 137 |   struct symbol *sym = cf_get_symbol(conf, name);
 138 |   if (sym->class && cf_symbol_is_local(conf, sym))
 139 |     cf_error("Error reading value for %s from %s:%d: already defined", name, file, line);
 140 | 
 141 |   cf_define_symbol(conf, sym, SYM_CONSTANT | T_INT, val, v);
 142 | }
