 527 | static void
 528 | cli_err(sock *s, int err)
 529 | {
 530 |   if (config->cli_debug)
 531 |     {
 532 |       if (err)
 533 | 	log(L_INFO "CLI connection dropped: %s", strerror(err));
 534 |       else
 535 | 	log(L_INFO "CLI connection closed");
 536 |     }
 537 |   cli_free(s->data);
