 540 | static void
 541 | cli_connect_err(sock *s UNUSED, int err)
 542 | {
 543 |   ASSERT_DIE(err);
 544 |   if (config->cli_debug)
 545 |     log(L_INFO "Failed to accept CLI connection: %s", strerror(err));
 546 | }
