 800 | static void
 801 | signal_init(void)
 802 | {
 803 |   struct sigaction sa;
 804 | 
 805 |   bzero(&sa, sizeof(sa));
 806 |   sa.sa_handler = handle_sigusr;
 807 |   sa.sa_flags = SA_RESTART;
 808 |   sigaction(SIGUSR1, &sa, NULL);
 809 |   sa.sa_handler = handle_sighup;
 810 |   sa.sa_flags = SA_RESTART;
 811 |   sigaction(SIGHUP, &sa, NULL);
 812 |   sa.sa_handler = handle_sigterm;
 813 |   sa.sa_flags = SA_RESTART;
 814 |   sigaction(SIGTERM, &sa, NULL);
 815 |   sa.sa_handler = watchdog_sigalrm;
 816 |   sa.sa_flags = 0;
 817 |   sigaction(SIGALRM, &sa, NULL);
 818 |   signal(SIGPIPE, SIG_IGN);
 819 | }
