 872 | static inline char *
 873 | get_bird_name(char *s, char *def)
 874 | {
 875 |   char *t;
 876 |   if (!s)
 877 |     return def;
 878 |   t = strrchr(s, '/');
 879 |   if (!t)
 880 |     return s;
 881 |   if (!t[1])
 882 |     return def;
