 446 | static void
 447 | cli_write(cli *c)
 448 | {
 449 |   sock *s = c->priv;
 450 | 
 451 |   while (c->tx_pos)
 452 |     {
 453 |       struct cli_out *o = c->tx_pos;
 454 | 
 455 |       int len = o->wpos - o->outpos;
 456 |       s->tbuf = o->outpos;
 457 |       o->outpos = o->wpos;
 458 | 
 459 |       if (sk_send(s, len) <= 0)
 460 | 	return;
 461 | 
 462 |       c->tx_pos = o->next;
 463 |     }
 464 | 
 465 |   /* Everything is written */
 466 |   s->tbuf = NULL;
 467 |   cli_written(c);
 468 | }
 469 | 
 470 | void
 471 | cli_write_trigger(cli *c)
 472 | {
 473 |   sock *s = c->priv;
 474 | 
 475 |   if (s->tbuf == NULL)
 476 |     cli_write(c);
 477 | }
