 485 | int
 486 | cli_get_command(cli *c)
 487 | {
 488 |   sock *s = c->priv;
 489 |   byte *t = s->rbuf;
 490 |   byte *tend = s->rpos;
 491 |   byte *d = c->rx_pos;
 492 |   byte *dend = c->rx_buf + CLI_RX_BUF_SIZE - 2;
 493 | 
 494 |   while (t < tend)
 495 |     {
 496 |       if (*t == '\r')
 497 | 	t++;
 498 |       else if (*t == '\n')
 499 | 	{
 500 | 	  *d = 0;
 501 | 	  t++;
 502 | 
 503 | 	  /* Move remaining data and reset pointers */
 504 | 	  uint rest = (t < tend) ? (tend - t) : 0;
 505 | 	  memmove(s->rbuf, t, rest);
 506 | 	  s->rpos = s->rbuf + rest;
 507 | 	  c->rx_pos = c->rx_buf;
 508 | 
 509 | 	  return (d < dend) ? 1 : -1;
 510 | 	}
 511 |       else if (d < dend)
 512 | 	*d++ = *t++;
 513 |     }
 514 | 
 515 |   s->rpos = s->rbuf;
 516 |   c->rx_pos = d;
 517 |   return 0;
 518 | }
