 566 | static struct cli_listener *
 567 | cli_listen(struct cli_config *cf)
 568 | {
 569 |   struct cli_listener *l = mb_allocz(cli_pool, sizeof *l);
 570 |   l->config = cf;
 571 |   sock *s = l->s = sk_new(cli_pool);
 572 |   s->type = SK_UNIX_PASSIVE;
 573 |   s->rx_hook = cli_connect;
 574 |   s->err_hook = cli_connect_err;
 575 |   s->data = l;
 576 |   s->rbsize = 1024;
 577 |   s->fast_rx = 1;
 578 | 
 579 |   /* Return value intentionally ignored */
 580 |   unlink(cf->name);
 581 | 
 582 |   if (sk_open_unix(s, cf->name) < 0)
 583 |   {
 584 |     log(L_ERR "Cannot create control socket %s: %m", cf->name);
 585 |     return NULL;
 586 |   }
 587 | 
 588 |   if (cf->uid || cf->gid)
 589 |     if (chown(cf->name, cf->uid, cf->gid) < 0)
 590 |     {
 591 |       log(L_ERR "Cannot chown control socket %s: %m", cf->name);
 592 |       return NULL;
 593 |     }
 594 | 
 595 |   if (chmod(cf->name, cf->mode) < 0)
 596 |   {
 597 |     log(L_ERR "Cannot chmod control socket %s: %m", cf->name);
 598 |     return NULL;
 599 |   }
 600 | 
 601 |   cli_listener_add_tail(&cli_listeners, l);
 602 | 
 603 |   return l;
 604 | }
