 886 | static inline uid_t
 887 | get_uid(const char *s)
 888 | {
 889 |   struct passwd *pw;
 890 |   char *endptr;
 891 |   long int rv;
 892 | 
 893 |   if (!s)
 894 |     return 0;
 895 | 
 896 |   errno = 0;
 897 |   rv = strtol(s, &endptr, 10);
 898 | 
 899 |   if (!errno && !*endptr)
 900 |     return rv;
 901 | 
 902 |   pw = getpwnam(s);
 903 |   if (!pw)
 904 |     die("Cannot find user '%s'", s);
 905 | 
 906 |   return pw->pw_uid;
 907 | }
