 932 | static void
 933 | parse_args(int argc, char **argv)
 934 | {
 935 |   int config_changed = 0;
 936 |   int socket_changed = 0;
 937 |   int c;
 938 | 
 939 |   bird_name = get_bird_name(argv[0], "bird");
 940 |   if (argc == 2)
 941 |     {
 942 |       if (!strcmp(argv[1], "--version"))
 943 | 	display_version();
 944 |       if (!strcmp(argv[1], "--help"))
 945 | 	display_help();
 946 |     }
 947 |   while ((c = getopt(argc, argv, opt_list)) >= 0)
 948 |     switch (c)
 949 |       {
 950 |       case 'c':
 951 | 	config_name = optarg;
 952 | 	config_changed = 1;
 953 | 	break;
 954 |       case 'd':
 955 | 	log_init_debug("");
 956 | 	run_in_foreground = 1;
 957 | 	break;
 958 |       case 'D':
 959 | 	log_init_debug(optarg);
 960 | 	break;
 961 |       case 'p':
 962 | 	parse_and_exit = 1;
 963 | 	break;
 964 |       case 's':
 965 | 	path_control_socket = optarg;
 966 | 	socket_changed = 1;
 967 | 	break;
 968 |       case 'P':
 969 | 	pid_file = optarg;
 970 | 	break;
 971 |       case 'u':
 972 | 	use_user = optarg;
 973 | 	break;
 974 |       case 'g':
 975 | 	use_group = optarg;
 976 | 	break;
 977 |       case 'f':
 978 | 	run_in_foreground = 1;
 979 | 	break;
 980 |       case 'l':
 981 | 	if (!config_changed)
 982 | 	  config_name = xbasename(config_name);
 983 | 	if (!socket_changed)
 984 | 	  path_control_socket = xbasename(path_control_socket);
 985 | 	break;
 986 |       case 'R':
 987 | 	graceful_restart_recovery();
 988 | 	break;
 989 |       case 'h':
 990 | 	display_help();
 991 | 	break;
 992 |       default:
 993 | 	fputc('\n', stderr);
 994 | 	display_usage();
 995 | 	exit(1);
 996 |       }
 997 |   if (optind < argc)
 998 |    {
 999 |      display_usage();
1000 |      exit(1);
1001 |    }
1002 | }
