 607 | cli_deafen(struct cli_listener *l)
 608 | {
 609 |   rfree(l->s);
 610 |   unlink(l->config->name);
 611 |   cli_listener_rem_node(&cli_listeners, l);
 612 |   mb_free(l);
 613 | }
