 643 | static void
 644 | cli_commit(struct config *new, struct config *old)
 645 | {
 646 |   if (new->shutdown)
 647 |   {
 648 |     /* Keep the main CLI throughout the shutdown */
 649 |     initial_control_socket_config.config = new;
 650 |     main_control_socket->config = &initial_control_socket_config;
 651 |   }
 652 | 
 653 |   WALK_TLIST(cli_config, c, &new->cli)
 654 |   {
 655 |     _Bool seen = 0;
 656 |     WALK_TLIST(cli_listener, l, &cli_listeners)
 657 |       if (l->config->config != new)
 658 | 	if (!strcmp(l->config->name, c->name))
 659 | 	{
 660 | 	  ASSERT_DIE(l->config->config == old);
 661 | 	  l->config = c;
 662 | 	  seen = 1;
 663 | 	  break;
 664 | 	}
 665 | 
 666 |     if (!seen)
 667 |       cli_listen(c);
 668 |   }
 669 | 
 670 |   WALK_TLIST_DELSAFE(cli_listener, l, &cli_listeners)
 671 |     if (l->config->config != new)
 672 |       cli_deafen(l);
 673 | }
