 683 | static inline void
 684 | open_pid_file(void)
 685 | {
 686 |   if (!pid_file)
 687 |     return;
 688 | 
 689 |   pid_fd = open(pid_file, O_WRONLY|O_CREAT, 0664);
 690 |   if (pid_fd < 0)
 691 |     die("Cannot create PID file %s: %m", pid_file);
