 694 | static inline void
 695 | write_pid_file(void)
 696 | {
 697 |   int pl, rv;
 698 |   char ps[24];
 699 | 
 700 |   if (!pid_file)
 701 |     return;
 702 | 
 703 |   /* We don't use PID file for uniqueness, so no need for locking */
 704 | 
 705 |   pl = bsnprintf(ps, sizeof(ps), "%ld\n", (s64) getpid());
 706 |   if (pl < 0)
 707 |     bug("PID buffer too small");
 708 | 
 709 |   rv = ftruncate(pid_fd, 0);
 710 |   if (rv < 0)
 711 |     die("fruncate: %m");
 712 | 
 713 |   rv = write(pid_fd, ps, pl);
 714 |   if(rv < 0)
 715 |     die("write: %m");
 716 | 
 717 |   close(pid_fd);
 718 | }
