 909 | static inline gid_t
 910 | get_gid(const char *s)
 911 | {
 912 |   struct group *gr;
 913 |   char *endptr;
 914 |   long int rv;
 915 | 
 916 |   if (!s)
 917 |     return 0;
 918 | 
 919 |   errno = 0;
 920 |   rv = strtol(s, &endptr, 10);
 921 | 
 922 |   if (!errno && !*endptr)
 923 |     return rv;
 924 | 
 925 |   gr = getgrnam(s);
 926 |   if (!gr)
 927 |     die("Cannot find group '%s'", s);
 928 | 
 929 |   return gr->gr_gid;
 930 | }
