1006 |  */
1007 | 
1008 | int
1009 | main(int argc, char **argv)
1010 | {
1011 | #ifdef HAVE_LIBDMALLOC
1012 |   if (!getenv("DMALLOC_OPTIONS"))
1013 |     dmalloc_debug(0x2f03d00);
1014 | #endif
1015 | 
1016 |   parse_args(argc, argv);
1017 |   log_switch(1, NULL, NULL);
1018 | 
1019 |   random_init();
1020 |   resource_init();
1021 |   timer_init();
1022 |   olock_init();
1023 |   io_init();
1024 |   rt_init();
1025 |   if_init();
1026 |   mpls_init();
1027 | //  roa_init();
1028 |   config_init();
1029 | 
1030 |   uid_t use_uid = get_uid(use_user);
1031 |   gid_t use_gid = get_gid(use_group);
1032 | 
1033 |   cli_init();
1034 | 
1035 |   if (!parse_and_exit)
1036 |   {
1037 |     test_old_bird(path_control_socket);
1038 |     cli_init_unix(use_uid, use_gid);
1039 |   }
1040 | 
1041 |   if (use_gid)
1042 |     drop_gid(use_gid);
1043 | 
1044 |   if (use_uid)
1045 |     drop_uid(use_uid);
1046 | 
1047 |   if (!parse_and_exit)
1048 |     open_pid_file();
1049 | 
1050 |   protos_build();
1051 | 
1052 |   struct config *conf = read_config();
1053 | 
1054 |   if (parse_and_exit)
1055 |     exit(0);
1056 | 
1057 |   if (!run_in_foreground)
1058 |     {
1059 |       pid_t pid = fork();
1060 |       if (pid < 0)
1061 | 	die("fork: %m");
1062 |       if (pid)
1063 | 	return 0;
1064 |       setsid();
1065 |       close(0);
1066 |       if (open("/dev/null", O_RDWR) < 0)
1067 | 	die("Cannot open /dev/null: %m");
1068 |       dup2(0, 1);
1069 |       dup2(0, 2);
1070 |     }
1071 | 
1072 |   main_thread_init();
1073 | 
1074 |   write_pid_file();
1075 | 
1076 |   signal_init();
1077 | 
1078 |   config_commit(conf, RECONFIG_HARD, 0);
1079 | 
1080 |   graceful_restart_init();
1081 | 
1082 | #ifdef LOCAL_DEBUG
1083 |   async_dump_flag = 1;
1084 | #endif
1085 | 
1086 |   log(L_INFO "Started");
1087 |   DBG("Entering I/O loop.\n");
1088 | 
1089 |   io_loop();
1090 |   bug("I/O loop died");
1091 | }

