 144 | /* the code of read_iproute_table() is based on
 145 |    rtnl_tab_initialize() from iproute2 package */
 146 | static void
 147 | read_iproute_table(struct config *conf, char *file, char *prefix, uint max)
 148 | {
 149 |   char buf[512], namebuf[512];
 150 |   char *name;
 151 |   uint val;
 152 |   FILE *fp;
 153 | 
 154 |   strcpy(namebuf, prefix);
 155 |   name = namebuf + strlen(prefix);
 156 | 
 157 |   fp = fopen(file, "r");
 158 |   if (!fp)
 159 |     return;
 160 | 
 161 |   for (uint line = 1; fgets(buf, sizeof(buf), fp); line++)
 162 |   {
 163 |     char *p = buf;
 164 | 
 165 |     while (*p == ' ' || *p == '\t')
 166 |       p++;
 167 | 
 168 |     if (*p == '#' || *p == '\n' || *p == 0)
 169 |       continue;
 170 | 
 171 |     if (sscanf(p, "0x%x %s\n", &val, name) != 2 &&
 172 | 	sscanf(p, "0x%x %s #", &val, name) != 2 &&
 173 | 	sscanf(p, "%u %s\n", &val, name) != 2 &&
 174 | 	sscanf(p, "%u %s #", &val, name) != 2)
 175 |       continue;
 176 | 
 177 |     if (val > max)
 178 |       continue;
 179 | 
 180 |     for(p = name; *p; p++)
 181 |       if ((*p < 'a' || *p > 'z') && (*p < 'A' || *p > 'Z') && (*p < '0' || *p > '9') && (*p != '_'))
 182 | 	*p = '_';
 183 | 
 184 |     add_num_const(conf, namebuf, val, file, line);
 185 |   }
 186 | 
 187 |   fclose(fp);
 188 | }
