 548 | static int
 549 | cli_connect(sock *s, uint size UNUSED)
 550 | {
 551 |   cli *c;
 552 | 
 553 |   if (config->cli_debug)
 554 |     log(L_INFO "CLI connect");
 555 |   s->rx_hook = cli_rx;
 556 |   s->tx_hook = cli_tx;
 557 |   s->err_hook = cli_err;
 558 |   s->data = c = cli_new(s, ((struct cli_listener *) s->data)->config);
 559 |   s->pool = c->pool;		/* We need to have all the socket buffers allocated in the cli pool */
 560 |   s->fast_rx = 1;
 561 |   c->rx_pos = c->rx_buf;
 562 |   rmove(s, c->pool);
 563 |   return 1;
 564 | }
